local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["quest:92551"] = {n="Stolen Supplies",s="Stolen Supplies ger äventyrare i uppdrag att återta plundrade varor från höglandet från Al'Aketh i Falaath Village. Karavanöverfall har stoppat viktiga leveranser av mat och vindstenar mellan låglandet och Shen'dar Highlands, och de lokala luftburna samhällena svälter snart.",h="Stolen Supplies ger äventyrare i uppdrag att återta plundrade varor från höglandet från Al'Aketh i Falaath...",kw={"al'aketh","karavaner","konstapel","falaath village","shen'dar highlands","luftburna","stolen supplies","vindstenar"},ang={["race:Skyborne"]="Räderna slår direkt mot livlinan mellan höglandet och låglandet och lämnar luftburna invånare hungriga och desperata utan sina regelbundna leveranser av mat och vindstenar."},sec={{t="Räder mot höglandets livlina",b="I flera månader har karavaner mellan låglandet och Shen'dar Highlands utsatts för återkommande angrepp längs handelsvägarna. Leveranserna för med sig viktiga förnödenheter, däribland mat och vindstenar, som håller bosättningarna i höglandet vid liv. Utan regelbundna leveranser är lokalbefolkningen på väg att svälta och kämpar för att klara sig medan förråden sinar i hela regionen."},{t="Förrådet i Falaath",b="Al'Aketh skyller offentligt karavanöverfallen på vanliga banditer, men den försvunna lasten berättar en annan historia. Stulna förpackningar med förnödenheter från Shen'dar hamnar gång på gång i Falaath Village, där Al'Aketh samlar sina förråd. När varorna återtas kan de lokala myndigheterna och konstapeln dela ut välbehövlig proviant direkt till de mest utsatta luftburna invånarna."}},faq={{q="Vilka förnödenheter stals från karavanerna?",a="Karavanerna mellan höglandet och låglandet transporterade livsviktiga varor, framför allt mat och vindstenar. De regelbundna leveranserna håller lokalbefolkningen mätt och försörjd.",al={"vad stals","stulna förnödenheter","vilka varor stals"}},{q="Vem ligger bakom karavanräderna?",a="Al'Aketh har plundrat förnödenhetskaravanerna i flera månader. De försöker skylla de försvunna leveranserna på vanliga banditer, men de stulna förråden hamnar bevisligen i deras område vid Falaath Village.",al={"vem stal förnödenheterna","vem överföll karavanerna","karavanernas angripare"}},{q="Var förvaras de stulna förnödenheterna?",a="De stulna förpackningarna med förnödenheter förvaras i Falaath Village, en bosättning tillhörande Al'Aketh i Shen'dar Highlands.",al={"var finns förnödenheterna","var hittar man förnödenheter","plats för stulna förråd"}},{q="Varför är förnödenhetskaravanerna måltavlor?",a="Förnödenheterna omfattar livsviktig proviant som mat och vindstenar som fraktas till och från låglandet. Räderna berövar lokalbefolkningen bland de luftburna dess försörjning, samtidigt som Falaath Village fylls med viktiga resurser från höglandet.",al={"varför stjäla vindstenar och mat","varför karavanräder"}},{q="Vad händer med förnödenheterna när de återtas?",a="När förnödenheterna har återtagits från Falaath Village samordnas utdelningen med den lokala konstapeln, så att de når invånarna som allra mest behöver mat och hjälp.",al={"vem får tillbaka förnödenheterna","omfördelning av förnödenheter","vad händer efter återtagandet"}},{q="Varför skyller Al'Aketh räderna på banditer?",a="Al'Aketh skyller på kringströvande banditer för att slippa ta ansvar för de försvunna handelsvarorna, trots att den stulna lasten gång på gång hamnar på hög i deras egen bosättning i Falaath Village.",al={"varför skylla på banditer","al akeths ursäkt om banditer"}}},fp="15,213,30.272.0,17.274.0,44.135.0,44.138.0,46.93.0,45.171.0,53.144.0,48.134.0"}
P.entries["quest:92553"] = {n="Restocking the Larders",s="Restocking the Larders är ett försörjningsuppdrag i Shen'dar Highlands på Zephras. När ökande faror i vildmarken hindrar byborna från att samla mat får en äventyrare i uppdrag att hämta ägg och striderkött för att försörja bosättningen.",h="Restocking the Larders är ett försörjningsuppdrag i Shen'dar Highlands på Zephras.",kw={"matlagning","restocking the larders","shen'dar highlands","små ägg","strider meat","urseraspäck","zephras"},ang={["profession:Cooking"]="Att samla lokala ingredienser som striderkött och små ägg ger praktisk erfarenhet och matlagningsrecept anpassade till Zephras vilda djur."},sec={{t="Faror i höglandet",b="När oroligheter och ökande faror sprider sig över Shen'dar Highlands blir vardagslivet på Zephras allt mer bekymmersamt. Vanliga bybor kan inte längre tryggt ge sig ut i vildmarken för att samla mat eller jaga, och de gemensamma matförråden har därför sinat rejält. För att hålla bosättningen mätt måste de lokala kockarna vända sig till resande äventyrare med styrkan och skickligheten att trotsa de vilda stigarna."},{t="Mat och tröst",b="Uppgiften går ut på att spåra upp inhemska vilda djur i höglandet för att få tag på striderkött och färska små ägg. Till dem som bidrar med förnödenheter delar kocken gärna med sig av sina matlagningskunskaper och lär ut recept och tekniker som förfinats med lokalt villebråd, bland annat ägg stekta i mustigt urseraspäck, avnjutna med en stillsam pipa torkad peacebloom."}},faq={{q="Vilka förnödenheter behövs till Restocking the Larders?",a="En lokal kock behöver 3 Small Eggs och 8 stycken Strider Meat för att hjälpa till att mätta byn medan farorna håller vanliga matsamlare inomhus.",al={"syftet med restocking the larders","vad ska samlas till restocking the larders"}},{q="Var hittar man ingredienserna?",a="Strider Meat och Small Eggs kommer från vilda djur som strövar omkring i Shen'dar Highlands på ön Zephras.",al={"var hittar man strider meat på zephras","var finns ägg i shen'dar"}},{q="Varför börjar byn få slut på mat?",a="De ökande farorna i området gör det alltför riskabelt för vanliga bybor att ge sig ut för att jaga eller samla mat, så matförråden har sinat.",al={"varför behövs mat på zephras","varför är byn hungrig i shen'dar"}},{q="Vilken belöning erbjuder kocken för maten?",a="Som tack för färska förnödenheter erbjuder uppdragsgivaren matlagningstips, knep och träning i lokala recept.",al={"vad erbjuder uppdragsgivaren","uppdrag med matlagningsträning"}},{q="Vad är Shen'dar Highlands och Zephras?",a="Shen'dar Highlands ligger på Zephras, där lokalbefolkningen kämpar med tilltagande hot samtidigt som de försöker få vardagen att gå ihop.",al={"vad är zephras","var ligger shen'dar highlands"}},{q="Hur tillagar kocken äggen?",a="Kocken svär vid att steka nyplockade små ägg i urseraspäck och kallar kombinationen en oöverträffad tröst på Zephras.",al={"späckets matlagningshemlighet","hur tillagas ägg på zephras"}}},fp="22,187,24.271.0,22.247.0,52.134.0,35.100.0,39.111.0,45.106.0,44.116.0,35.82.0"}
P.entries["quest:92579"] = {n="To Valanaar",s="\"To Valanaar\" är ett öuppdrag där äventyrare för ett brådskande militärt meddelande från Aonda i Shen'dar till fredsvakarnas ledare Valennia Stormfist. Meddelandet varnar bosättningen vid öns sydöstra kant för att en aggressiv kult snabbt växer sig större och att en direkt konflikt inte längre går att undvika.",h="\"To Valanaar\" är ett öuppdrag där äventyrare för ett brådskande militärt meddelande från Aonda i Shen'dar...",kw={"aonda","kult","fredsvakare","shen'dar","to valanaar","valanaar","valennia stormfist"},sec={{t="Ett brådskande meddelande",b="Efter försvaret av Shen'dar och dess pylon skickar höglandsbon Aonda en betrodd resenär över ön med brådskande nyheter till Valanaar. Valanaar ligger vid landets sydöstra kant och hyser öns fredsvakare, under ledning av Valennia Stormfist. Uppdraget bär på en viktig varning: öns fredliga dagar går mot sitt slut, och Valennia måste förbereda sitt folk på en oundviklig sammandrabbning med en aggressiv kult som växer sig allt större."},{t="Stormen närmar sig",b="Fram till den här varningen har de lokala fredsvakarna lyckats undvika direkt konflikt med den mystiska kulten. Men kultens aggressiva intrång har drivit spänningarna till bristningsgränsen. När Valennia läser Aondas skriftliga rapport inser hon att fredsvakarna genast måste samla sina återstående styrkor och utforma en försvarsstrategi innan kulten riktar sin uppmärksamhet mot själva Valanaar."}},faq={{q="Vem skickar dig till Valanaar?",a="Uppdraget ges av Aonda, en höglandsbo i Shen'dar, efter att du hjälpt till att skydda den lokala byn och pylonen från ett överhängande hot från kultister. Hon är imponerad av din hjälp och anförtror dig ett brådskande skriftligt meddelande som ska föras tvärs över ön.",al={"vem ger uppdraget till valanaar","uppdragsgivare till valanaar","vem skickar mig till valanaar"}},{q="Vem är Valennia Stormfist?",a="Valennia Stormfist leder fredsvakarna på ön, med högkvarter i bosättningen Valanaar. Hon ansvarar för det lokala försvaret och ordningen och ska samordna insatser mot regionala hot, som kultens aggressiva expansion.",al={"vem är valennia stormfist","valennia ledare","valennia"}},{q="Vad är Valanaar?",a="Valanaar är en bosättning vid öns sydöstra kant. Den fungerar som bas för öns fredsvakare, ledda av Valennia Stormfist, och som tillflykt och samlingsplats för ortsborna.",al={"vad är valanaar","var ligger valanaar","valanaars plats"}},{q="Vad är syftet med Aondas rapport?",a="Aondas rapport beskriver det växande hotet från kulten och händelserna kring säkerheten i Shen'dar och vid dess pylon. Fredsvakare har länge undvikit direkt konflikt, men rapporten varnar för att kultens snabba expansion gör en framtida sammandrabbning oundviklig och att Valanaar därför måste förbereda sitt försvar.",al={"varför leverera rapporten","vad är aondas rapport","vad står i brevet"}},{q="Vilket hot utgör kulten mot ön?",a="Rapporten varnar för en namnlös kult som snabbt växer sig större över ön. Fredsvakarna har tidigare hållit avstånd för att undvika öppet krig, men kultens senaste aggressiva handlingar mot platser som Shen'dar visar att konflikten inte längre går att undvika.",al={"vilken kult hotar valanaar","vem är kulten","kultens hot mot ön"}},{q="Vad händer när du kommer fram till Valanaar?",a="När Valennia får de dystra nyheterna måste hon rådgöra med sina återstående fredsvakare för att utforma en försvarsstrategi mot framtida kultattacker. Medan hon samordnar deras planer bjuder hon in resenärer att hjälpa ortsborna kring Valanaar, som behöver en hand.",al={"vad göra efter att ha lämnat rapporten","vad händer sedan i valanaar"}}},fp="11,206,18.368.0,19.279.1,26.207.0,26.191.0,17.167.0,38.241.0,45.248.0,37.226.0"}
P.entries["quest:92595"] = {n="The Windshapers",s="\"The Windshapers\" är ett uppdrag där Illaya Amberwind introducerar spelaren till Windshapers och deras andliga uppdrag. Orden har fått i uppgift att återknyta kontakten med vindandarna och strävar efter att skydda Zephras och säkra Shen'doreis överlevnad bland hoten i Skywall.",h="\"The Windshapers\" är ett uppdrag där Illaya Amberwind introducerar spelaren till Windshapers och deras...",kw={"al'aketh","illaya amberwind","shen'dorei","skysight","skywall","windshapers","zephras"},ang={["class:Shaman"]="Illaya påpekar att utbildade schamaner naturligt kommunicerar med elementen, men att gåvan skysight även kan visa sig hos andra. Det visar på Windshapers gemensamma andliga plikt med dem som åkallar elementen.",["race:Skyborne"]="Windshapers kämpar för Shen'doreis överlevnad och hemland bland de osäkra höjderna i Skywall och Zephras."},sec={{t="Windshapers uppdrag",b="Windshapers är en orden som ägnar sig åt att kommunicera med vindandarna och skydda Shen'dorei. De välkomnar dem med en medfödd andlig känslighet och försöker överbrygga den växande klyftan mellan sitt folk och de elementarkrafter som upprätthåller deras luftburna rike. Illaya Amberwind hjälper nya rekryter att förstå de tunga bördor som orden bär."},{t="Prövningar på Zephras",b="Överlevnad i Skywall är långt ifrån säker. Windshapers måste ta sig igenom den förrädiska inre oron som Al'Aketh orsakar, samtidigt som de uthärdar elementarplanets större faror. Att återupprätta dialogen med vindandarna anses avgörande för att Zephras ska bestå och Shen'dorei klara stormen."}},faq={{q="Vilka är Windshapers?",a="Windshapers är en grupp som ägnar sig åt att kommunicera med vindandarna och skydda sitt folk, Shen'dorei. Under ledare som Illaya Amberwind söker de upp individer med skysight för att återupprätta dialogen med vindandarna och bevara sitt hotade hemland.",al={"vilka är windshapers","windshapers fraktion","vad gör windshapers"}},{q="Vad är skysight?",a="Skysight är en medfödd andlig känslighet eller gåva som gör det möjligt att få kontakt med luftens element. Som Illaya förklarar behöver man inte ha formell träning som schaman för att ha skysight, men det är avgörande att kunna bemästra gåvan för att nå vindandarna.",al={"vad är skysight","skysight historia"}},{q="Vem är Illaya Amberwind?",a="Illaya Amberwind är en mentor bland Windshapers som känner igen andliga gåvor hos resenärer. Hon välkomnar dem som har skysight och förklarar Windshapers uppdrag, farorna som hotar Zephras och prövningarna som Shen'dorei står inför.",al={"vem är illaya","illaya amberwind"}},{q="Vad är Zephras?",a="Zephras är ett luftburet område eller samhälle som genomlider svåra prövningar och inre oro. Windshapers kämpar aktivt för att skydda Zephras och bevara en framtid för sitt folk där.",al={"vad är zephras","zephras historia"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är en fientlig intern fraktion eller ett hot som plågar Windshapers och Shen'dorei och förvärrar farorna med att överleva i Skywall.",al={"vilka är al'aketh","al'aketh hot"}},{q="Vilka är Shen'dorei?",a="Shen'dorei är folket som Windshapers företräder. De står inför inre hot som Al'Aketh och osäkra förhållanden i Skywall, och deras överlevnad hänger på att Windshapers återställer balansen med vindarna.",al={"vilka är shen'dorei","shen'dorei historia"}}},fp="15,176,26.326.0,17.239.0,24.217.0,17.209.0,24.217.0,16.171.0,21.150.0,23.209.0"}
P.entries["quest:92596"] = {n="The High Order",s="The High Order är ett introduktionsuppdrag på Zephras där Rathiril Sunlance förklarar shen'doreis svåra situation. Sedan de förlorade sina elementära välgörares hjälp måste dessa ättlingar till Highborne från Eldre'Thalas bemästra sin uråldriga arkana magi för att säkra sin överlevnad.",h="The High Order är ett introduktionsuppdrag på Zephras där Rathiril Sunlance förklarar shen'doreis svåra...",kw={"al'aketh","arkana","eldre'thalas","highborne","rathiril sunlance","shen'dorei","the high order","zephras"},ang={["class:Mage"]="Rathiril påpekar att även äventyrare som inte formellt utbildats till magiker bär starka arkaniska auror. Det visar att deras gemensamma magi är ett medfött arv, inte bara en studerad disciplin.",["race:Skyborne"]="Som ättlingar till forntidens Highborne i Eldre'Thalas måste shen'dorei bemästra sina uråldriga arkaniska gåvor för att stå på egna ben efter att deras elementära beskyddare lämnat dem."},sec={{t="Ett folk på egen hand",b="The High Order är shen'doreis på Zephras målmedvetna försök att återta sin styrka och forma sin egen framtid. Länge förlitade sig deras folk på sina elementära välgörares beskydd och ynnest. Nu när dessa elementära beskyddare är borta står folket ensamt, sårbart för inre stridigheter och faror från omgivningen. Ledare som Rathiril Sunlance söker upp personer med fallenhet för arkana förmågor, så att de kan ansluta sig till uppdraget att bevara folket och göra det självförsörjande."},{t="Arvet från Eldre'Thalas",b="Shen'dorei bär med sig arvet från sitt förfädershem Eldre'Thalas och delar en medfödd källa till arkan energi, som omger även dem som inte formellt har invigts i magins konst. The High Order ser det som deras gemensamma öde, som ättlingar till Highborne, att utöva dessa uråldriga magiska gåvor. På så vis hoppas de kunna motverka inre hot som Al'Aketh och stå emot de många säkerhetshot som hemsöker deras hem på Zephras."}},faq={{q="Vad är High Order?",a="The High Order är en organisation bland shen'dorei som arbetar för folkets överlevnad. Orden grundades av ättlingar till Highborne från Eldre'Thalas och strävar efter att ta till vara på sina uråldriga arkaniska gåvor, så att deras samhälle kan försvara sig och klara sig på egen hand på Zephras.",al={"vilka är high order","vad är high order","high orders syfte"}},{q="Vem är Rathiril Sunlance?",a="Rathiril Sunlance är en alv med anknytning till The High Order på Zephras. Han lär nykomlingar om de lokala arkanenergiernas natur, shen'doreis svåra situation och The High Orders beslutsamhet att överleva utan sina forna elementära beskyddare.",al={"vem är rathiril","rathiril sunlance berättelse","sunlance"}},{q="Vad är Zephras?",a="Zephras är den flytande ön i Skywall där Rathiril Sunlance och hans folk nu bor. Platsen genomsyras av arkan energi, och där möter shen'dorei både inre faror och yttre osäkerhet kring sin trygghet.",al={"var finns high order","vad är zephras","zephras berättelse"}},{q="Vilka är shen'dorei?",a="Shen'dorei är alver som härstammar från Highborne i sitt förfädershem Eldre'Thalas. De bor nu på Zephras, har en medfödd koppling till arkan magi och strävar efter att klara sig på egen hand.",al={"vilka är shen'dorei","shen'dorei","shen'dorei berättelse"}},{q="Vilka var de elementära välgörarna?",a="De elementära välgörarna var mäktiga elementvarelser som tidigare hjälpte och beskyddade shen'dorei. Men nu är de borta, och folket på Zephras måste helt förlita sig på sin egen magiska förmåga och uppfinningsrikedom.",al={"vilka är elementvarelserna","elementära beskyddare","elementära välgörare"}},{q="Vad är Al'Aketh?",a="Al'Aketh är en intern fraktion eller ett hot som utmanar shen'doreis trygghet på Zephras. Att hantera sådana inre fiender är en av de centrala frågor som får The High Order att organisera sitt försvar.",al={"vad är al'aketh","al'aketh-hot","inre hot på zephras"}},{q="Hur hänger The High Order och Eldre'Thalas ihop?",a="Shen'doreis förfäder kom från Eldre'Thalas, den uråldriga Highborne-staden i Kalimdor, som många år 25 ADP känner till som Dire Maul. The High Order hedrar detta förfädersarv genom att bevara och använda sina uråldriga arkaniska gåvor.",al={"kopplingen till eldre'thalas","kommer de från dire maul","highbornes ursprung"}}},fp="14,225,21.364.0,22.360.0,23.242.0,25.214.0,16.225.0,23.168.0,35.191.0,22.164.0,63.241.0"}
P.entries["quest:92597"] = {n="Reading the Ley Lines",s="Reading the Ley Lines är en övergångsrit för unga Skyborne som upptäcker sitt magiska Highborne-arv. På uppdrag av Falorne Fallwind på Zephras Isle reser noviser till stenarna i Thendal Grove för att känna av och dra kraft ur de råa arkanströmmar som rusar genom elementterrängen.",h="Reading the Ley Lines är en övergångsrit för unga Skyborne som upptäcker sitt magiska Highborne-arv.",kw={"al'aketh","falorne fallwind","highborne","ley-linjer","reading the ley lines","skyborne","thendal grove","thendal standing stones","windshapers","zephras isle"},ang={["class:Mage"]="För utövare av arkanmagi är blottlagda ley-linjer en ovärderlig reservoar av otämjd kraft i en miljö som domineras av elementstormar.",["race:Skyborne"]="Denna rit väcker ditt medfödda Highborne-arv och lär dig att kanalisera underjordisk ley-energi direkt in i dina besvärjelser."},sec={{t="Arkanströmmar från elementplanet",b="Även i elementplanets vindpinade trakter löper slumrande arkanledningar under jorden. Medan märkliga elementaler och fientliga Al'Aketh driver över Zephras Isle har underjordiska ley-linjer börjat tränga upp mot ytan. För magiutövare ger dessa sprickor direkt tillgång till otämjda arkanreservoarer och skänker kraft åt alla som har den blodslinje och kunskap som krävs för att kanalisera dem."},{t="Highborne-arvet",b="Falorne Fallwind uppmanar nykomlingar att omfamna sitt Highborne-ursprung i stället för att ödmjuka sig inför vindandar som de lokala Windshapers eller Al'Aketh-fanatikerna. Enligt Fallwind beror överlevnaden mot elementplanets hårda krafter inte på att be främmande varelser om nåd, utan på att bemästra den inneboende arkanmakt som löper under deras fötter."},{t="Thendal Standing Stones",b="Nordost om bosättningen ligger Thendal Grove, där uråldriga resta stenar markerar en kraftfull ley-linjekonvergens. Denna utsatta plats för magisk energi, omgiven av virvlande vindar och Al'Aketh-anhängare, låter noviser stämma sina sinnen, harmoniera med ley-linjens puls och frigöra sin naturliga rasförmågas fulla potential."}},faq={{q="Vem ger uppdraget Reading the Ley Lines?",a="Uppdraget erbjuds av Falorne Fallwind på Zephras Isle till unga Skyborne som lär sig att tygla sina förfäders arkanförmågor.",al={"uppdragsgivare","falorne fallwind","vem startar reading the ley lines"}},{q="Var finns ley-linjen?",a="Ley-linjen finns nordost vid Thendal Standing Stones, som ligger i Thendal Grove bland fientliga elementaler och Al'Aketh-anhängare.",al={"ley-linjens plats","var ligger thendal grove","thendal standing stones plats"}},{q="Varför finns ley-linjer i elementplanet?",a="Slumrande arkanledningar löper genom marken även här i elementplanet. Nyligen har dessa ley-linjer börjat bryta igenom ytan och ge Skyborne direkt tillgång till kraftfulla energiströmmar.",al={"arkanmagi i elementplanet","ley-linjer i elementplanet historia"}},{q="Hur ser Falorne Fallwind på Windshapers?",a="Falorne föraktar Windshapers och ser deras vördnad för luftandar som en svag underkastelse inför likgiltiga elementvarelser, inte bättre än Al'Akeths dyrkan.",al={"falorne om windshapers","windshapers historia","windshapers jämfört med highborne"}},{q="Vilken förmåga krävs för att kanalisera ley-linjen?",a="Uppdraget kräver att du använder Skybornes rasförmåga ”Read Ley Line” medan du står i energikonvergensen vid stenarna.",al={"read ley line-förmågan","hur man läser en ley-linje","använd rasförmåga"}},{q="Vilken nytta ger det att utnyttja ley-linjer?",a="Genom att kommunicera med blottlagda ley-linjer kanaliseras rå arkanenergi in i användaren, vilket höjer dennes magiska förmåga och ger varierande effekter beroende på ledningens natur.",al={"vad gör ley-linjer","ley-linjernas fördelar"}}},fx={e5a629f0={q="Varför vill Falorne Fallwind att du läser ley-linjerna?",a="Falorne tror att det enda sättet att rädda ditt folk i elementarplanet är att återta ditt Highborne-arv och hämta kraft direkt från arkana ley-linjer. Han ser ner på grupper som The Windshapers och Al'Aketh, eftersom de underkastar sig likgiltiga elementvarelser. I hans ögon kräver överlevnad att du bemästrar latent magi i stället för att förlita dig på nyckfulla andar.",al={"falorne fallwinds motiv","varför läsa ley-linjer","varför falorne fallwind vill läsa ley-linjerna"}}},fp="21,171,38.291.0,16.349.0,23.302.0,42.118.0,30.142.0,49.174.0,47.161.0,49.114.0,49.147.0"}
P.entries["quest:92598"] = {n="The Gift of Skysight",s="The Gift of Skysight är en tidig övergångsrit för unga Windshapers som lär sig att bemästra sin medfödda kontakt med andevärlden. Under Ventaari Brightwishs ledning reser de invigda till en Elemental Convergence för att väcka sin perception och lyssna direkt till andarnas viskningar.",h="The Gift of Skysight är en tidig övergångsrit för unga Windshapers som lär sig att bemästra sin medfödda...",kw={"elemental convergence","elementandar","skysight","resta stenar","thendal grove","ventaari brightwish","windshaper","zephras"},ang={["class:Shaman"]="Schamaner känner igen Elemental Convergence som helig mark, där gränsen mellan dödlig vilja och elementplanen är som tunnast.",["faction:Horde"]="Som allierade på Zephras Isle förlitar sig Horde på Windshapers övernaturliga förutseende för att navigera bland öns okartlagda faror.",["race:Skyborne"]="För Skyborne är Skysight inte bara ett besynnerligt trick, utan en födslorätt skänkt av elementära beskyddare, som ligger till grund för deras kulturella och andliga identitet."},sec={{t="En helig perception",b="Windshapers har ett medfött band till de elementarkrafter som formar deras värld, förkroppsligat i den heliga förmåga som kallas Skysight. Gåvan låter dödliga sinnen stämma in på andliga våglängder och överbrygga den fysiska klyftan mellan de levande och det osedda. En Windshaper kan kalla fram denna inre syn ute i vildmarken, men kontakten fördjupas nära kraftsamlingar och låser upp resonanta välsignelser och dold visdom som vinden viskar fram."},{t="Thendal Groves sammanflöde",b="Nordost om bosättningen, bland forntida resta stenar, ligger en Elemental Convergence i Thendal Grove. Sådana platser fungerar som fokuspunkter där råa energier samlas och andeväsen dröjer sig kvar. Ventaari Brightwish skickar noviser till denna heliga plats, inte bara för att slutföra en uppgift, utan för att pröva deras andliga styrka. Precis som kroppens och sinnets förmågor behöver Skysight övas medvetet för att mogna, så att en växande Windshaper kan tyda elementens skiftande omen, som deras folks överlevnad är beroende av."}},faq={{q="Vad är syftet med det här uppdraget?",a="Uppdraget lär novisa Windshapers att använda sin Skysight-förmåga i praktiken. Ventaari Brightwish leder de invigda till en Elemental Convergence, där de får uppleva hur omgivningens kraft förstärker deras andliga sinnen.",al={"syftet med the gift of skysight","varför göra det här uppdraget","träning i skysight"}},{q="Vem är Ventaari Brightwish?",a="Ventaari Brightwish är en andlig vägledare och mentor som ansvarar för Windshapers tidiga träning på Zephras Isle. Hon lär dem att respektera och utveckla sitt elementära arv.",al={"ventaari","vem är ventaari brightwish","brightwish"}},{q="Vad är en Elemental Convergence?",a="En Elemental Convergence är en fokuserad plats med förhöjd andlig energi, ofta utmärkt av forntida resta stenar. Sådana platser drar naturligt till sig elementandar och förstärker förmågor som Skysight.",al={"vad är en elemental convergence","lore om elemental convergence","sammanflödet i thendal grove"}},{q="Var ligger Elemental Convergence?",a="Sammanflödet finns bland de resta stenarna i Thendal Grove, strax nordost om bosättningen på Zephras Isle.",al={"var ligger sammanflödet","thendal groves läge","de resta stenarnas läge"}},{q="Kan Skysight användas var som helst?",a="Ja. En Windshaper kan åkalla Skysight var som helst, men inne i en Elemental Convergence får du en mycket kraftfullare välsignelse och kan få ytterligare insikter från närliggande andar.",al={"kan jag använda skysight var som helst","skysight utanför sammanflödet","var kan jag använda skysight"}},{q="Varför anses Skysight vara avgörande för överlevnaden?",a="Skysight överbryggar klyftan mellan dödliga och elementandar. Enligt Ventaari är förmågan att uppfatta och lyssna till elementens varningar avgörande för att kunna navigera bland hotande faror och skydda deras folk.",al={"varför är skysight viktigt","skysight och överlevnad","elementen och överlevnad"}}},fx={d2ee972c={q="Varför vill Ventaari Brightwish att du använder Skysight vid konvergensen?",a="Ventaari Brightwish vill träna dig i ditt medfödda Windshaper-arv. Precis som en muskel måste Skysight tränas på kraftplatser som Elemental Convergence, så att du kan lära dig att överbrygga avståndet mellan den dödliga och den andliga världen. Hon tror att det är avgörande för din överlevnad att tala med andarna och lyssna till vad elementen säger ditt folk.",al={"varför ventaari vill det här","ventaari brightwishs motiv","varför använda skysight här"}}},fp="20,163,19.399.0,32.398.0,34.114.0,27.131.0,33.163.0,43.119.0,30.136.0,50.163.0"}
P.entries["quest:926"] = {n="Flawed Power Stone",s="Över The Barrens vilar Flawed Power Stone på arkana bord, laddad med arkan energi. Dess skapare lämnade den fatalt bristfällig, så den förbrukar sin egen kraft kort efter att den flyttas.",h="Över The Barrens vilar Flawed Power Stone på arkana bord, laddad med arkan energi.",kw={"arkanisk","the barrens","bristfällig kraftsten","kraftstenar","ritualbord","instabil magi"},ang={["faction:Horde"]="Som medlem av Horde håller du uppsikt över arkaniska märkvärdigheter utspridda över The Barrens, på din vakt mot obehörig trolldom som kan hota dina försörjningsleder."},sec={{t="Instabilt hantverk",b="I The Barrens håller bristfälliga kraftstenar arkan essens i bräckliga strukturer. Deras skapare gjorde dem avsiktligt instabila, så de förfaller till inert materia ögonblick efter att någon hanterar dem."},{t="Självförbrukande energi",b="En sten börjar förbruka sin kraft så snart den lämnar ritualbordet där den vilar. Energin brinner bort för snabbt för att någon ska kunna bära den långt."}},faq={{q="Vad är en bristfällig kraftsten?",a="Flawed Power Stone rymmer rå magisk kraft, men dess avsiktliga brister gör att den snabbt förbrukar sig själv när den väl har flyttats.",al={"bristfällig kraftsten","vad är den här stenen","kraftstenens bakgrund"}},{q="Kan stenarna bevaras för alltid?",a="Nej. När stenarna skiljs från borden som stabiliserar dem kollapsar deras magiska matriser och energin tar snabbt slut.",al={"bevara bristfällig sten","kan jag förvara den","bevara stenen"}},{q="Vem använder stenarna?",a="Orchen Ak'Zeloth förbereder stenarna, och Horde-äventyrare bär dem till eldaltaret på Dreadmist Peak. Där stör de Demon Seeds förbindelse med Burning Legion.",al={"vem gjorde kraftstenarna","vem tillverkade dem","stenarnas skapare"}},{q="Varför bryr sig Horde om dem?",a="Horde använder stenarna mot Burning Legion. Ak'Zeloth förberedde dem åt Neeru Fireblade, så att bära en till eldaltaret på Dreadmist Peak kan bryta Demon Seeds förbindelse med Legion.",al={"hordes intresse","varför vill horde ha den"}}},fp="18,171,22.187.0,21.150.0,29.102.0,40.128.0,22.182.0,35.206.0"}
P.entries["quest:9260"] = {n="Investigate the Scourge of Stormwind",s="Gisselstyrkor pressar mot Stormwind, medan nekropoler tornar upp sig bortom murarna. Lieutenant Orrin kallar försvararna till anfall mot lägren, insamling av nekrotiska stenar och studier av runorna där.",h="Gisselstyrkor pressar mot Stormwind, medan nekropoler tornar upp sig bortom murarna.",kw={"argent dawn","invasion","lich king","lieutenant orrin","nekropol","nekrotiska stenar","runcirklar","gisslet","stormwind"},ang={["class:Paladin"]="Som paladin möter du Gisslet utanför Stormwind och kan rikta helig vrede mot dess runor medan du skyddar kungarikets invånare.",["class:Priest"]="Som präst kan du studera de förvridna viskningarna i runorna och lära dig om skuggmagin som binder samman Gisselns främsta styrkor.",["faction:Alliance"]="För Alliansen är försvaret av Stormwinds portar en fråga om överlevnad. Gisslet har nått ända till detta sydliga fäste."},sec={{t="De odöda vid huvudstadens tröskel",b="Gisselstyrkor har nått utkanten av Stormwind City. Nekropoler svävar ovanför medan odöda och kultister får fäste nära kungarikets främsta bastion. Lieutenant Orrin samlar försvarare utanför staden för att driva tillbaka dem innan de hotar huvudstaden."},{t="De viskande runorna",b="Glödande runor märker ut marken kring Gisselläger, men deras syfte är fortfarande oklart. Cirklarna sprakar av magi som liknar nekropolernas och bär på kusliga viskningar. Lieutenant Orrin kan bara gissa vem som hör de onaturliga rösterna, om någon gör det."}},faq={{q="Vem är Lieutenant Orrin?",a="Lieutenant Orrin är en officer som samordnar Stormwinds försvar. Han samarbetar med Argent Dawn och organiserar lokala krigare för att samla information och bryta upp Gisselns fästen nära staden.",al={"orrin","lieutenant orrin","vem ger uppdraget"}},{q="Varför anfaller Gisslet Stormwind?",a="Lich King har skickat nekropoler och invasionsstyrkor över Azeroth för att sprida skräck och öka de odödas antal. Stormwind är ett viktigt fäste för de levande och därför ett mål för Gisslet.",al={"varför gisslet här","gisslets invasion av stormwind","varför anfalla stormwind"}},{q="Vad är de glödande runcirklarna?",a="Gisslet har placerat glödande runcirklar nära sina läger. De pulserar av mörk magi och bär på onaturliga viskningar, men deras syfte är okänt.",al={"runcirklar","glödande runor","vad gör cirklarna"}},{q="Vad är dunkla nekrotiska stenar?",a="Dunkla nekrotiska stenar är magiska föremål som bärs av Gisselns mindre styrkor. De innehåller kvarvarande nekrotisk energi och intresserar Argent Dawn.",al={"dunkla nekrotiska stenar","nekrotiska stenar","vad är nekrotiska stenar"}},{q="Vilken roll spelar Argent Dawn i det här uppdraget?",a="Argent Dawn är en självständig orden som bekämpar Gisslet var det än visar sig. Lieutenant Orrin samarbetar med orden för att säkra information och stenar åt dess krig mot Lich Kings arméer.",al={"argent dawn","argent dawns koppling"}},{q="Är det farligt att närma sig runcirklarna?",a="Cirklarna utstrålar en oroande energi och disharmoniska viskningar. Försiktiga spejare kan närma sig dem och lära sig om Gisselns kommunikation utan att förlora förståndet.",al={"är runorna säkra","viskningar i runorna"}}},fx={c2a78be7={q="Varför vill Lieutenant Orrin att det här undersöks?",a="The Lich King har släppt lös sina odöda styrkor precis utanför Stormwinds portar, under en hotfull, svävande nekropol. Lieutenant Orrin vet att staden inte har råd att sitta sysslolös medan inkräktare samlas vid tröskeln. Han måste snabbt förstå den märkliga magin bakom deras lysande runringar och decimera deras led innan de odöda får ett permanent fäste utanför kungarikets murar.",al={"varför orrin vill få det här gjort","lieutenant orrins motiv","varför undersöka scourge"}},["9cb0511c"]={q="Vilka skickas du att bekämpa utanför Stormwind?",a="Du strider mot Scourges invaderande styrkor, som har samlats under nekropolen strax utanför staden. Dessa odöda stormtrupper och vidunder har slagit läger vid Stormwinds portar för att skapa kaos och hota kungariket på uppdrag av The Lich King.",al={"vem strider jag mot","vilka är fienderna utanför stormwind","vilka scourge-styrkor finns utanför"}}},fp="36,219,33.265.0,20.249.0,24.195.0,39.206.0,35.155.0,29.139.0,52.202.0,44.164.0"}
P.entries["quest:9261"] = {n="Investigate the Scourge of Ironforge",s="Lieutenant Nevell från Argent Dawn kallar på modiga försvarare när Scourge dyker upp precis utanför Ironforges portar. Odöda trupper och hotfulla runcirklar hotar Dun Moroghs snöiga bergspass under en svävande nekropol. Försvararna ska förgöra de vandrande liken och ta reda på vad de märkligt lysande sigillen är till för.",h="Lieutenant Nevell från Argent Dawn kallar på modiga försvarare när Scourge dyker upp precis utanför...",kw={"argent dawn","dimmig nekrotisk sten","dun morogh","undersök scourges angrepp mot ironforge","ironforge","lich king","lieutenant nevell","nekropol","runcirkel","scourge"},ang={["class:Paladin"]="Scourge är den heliga Ljusets raka motsats. Att undersöka Lich Kings runiska ondska och rena bort hans viljelösa slavar hör helt och hållet till en paladins heliga uppdrag.",["class:Priest"]="De psykiska ekon som mumlar genom runcirklarna utgör en tydlig fara för vanliga soldaters förstånd. Det krävs andlig styrka för att stå emot dem.",["faction:Alliance"]="Ironforge är en viktig ekonomisk och militär grundpelare för Alliansen. Ett fäste för odöda vid dess portar hotar försörjningslinjerna genom Eastern Kingdoms.",["race:Dwarf"]="Att vanhelga Dun Moroghs rena snö med ruttnande vidunder är en skymf mot varje dvärg. Att försvara bergsingången handlar om hem och härd."},sec={{t="Döden vid bergsportarna",b="Scourges invasion stannar inte vid Lordaeron eller de pestdrabbade nordliga länderna. Svävande nekropoler kastar dystra skuggor över Azeroth, även över Dun Moroghs iskalla höjder precis utanför Ironforges bergsingång. Argent Dawn har placerat ut observatörer som Lieutenant Nevell för att övervaka och hejda denna krypande farsot innan den kan bryta igenom Bronzebeards fäste."},{t="Oheliga inskrifter",b="Under nekropolens skugga har de odöda slagit läger kring lysande runcirklar och pulserande nekrotiska stenar. När spejare ställer sig nära de hotfulla cirklarna upptäcker de mörka, viskande röster som ekar genom den omgivande magin. Lieutenant Nevell drar slutsatsen att cirklarna fungerar som mörka kanaler för kommunikation, men han vet inte vem Scourge kontaktar."}},faq={{q="Vem är Lieutenant Nevell?",a="Lieutenant Nevell är en officer i Argent Dawn som är stationerad vid Ironforge för att samordna försvaret mot Scourges invasion. Han ger äventyrare i uppdrag att samla in nekrotiska stenar och ta reda på vad de oheliga sigillen kring inkräktarnas läger är till för.",al={"nevell","lieutenant nevell","uppdragsgivare"}},{q="Varför anfaller Scourge Ironforge?",a="Uppdraget gäller Scourge-styrkor som slagit läger utanför Ironforge under en nekropol. Lieutenant Nevell ber försvararna att decimera deras styrkor och undersöka de märkliga runcirklarna i närheten.",al={"scourge utanför ironforge","varför odöda i dun morogh","invasion av ironforge"}},{q="Vad är dimmiga nekrotiska stenar?",a="Dimmiga nekrotiska stenar tas från Scourges inkräktare och lämnas till Argent Dawn som bevis på att odöda har dödats.",al={"nekrotiska stenar","dimmig nekrotisk sten","scourge-stenar"}},{q="Vad är de lysande runcirklarna till för?",a="De lysande runcirklarna finns nära Scourges invasionsstyrkor. Lieutenant Nevell ber dig undersöka vad de är till för.",al={"runcirklar","lysande cirklar","vad är runorna"}}},fx={["4916b51d"]={q="Varför vill Lieutenant Nevell att det här undersöks?",a="Scourge marscherar mot Ironforges tröskel och en nekropol tornar upp sig ovanför. Lieutenant Nevell och Argent Dawn vägrar att stå sysslolösa. Märkliga runringar som glöder av ohelig magi har dykt upp nära de odödas läger utanför portarna. Nevell vet att dessa ritualer bådar illa, och han behöver att du avslöjar vilka onda krafter inkräktarna kanaliserar innan staden drabbas av en ännu större katastrof.",al={"nevells motiv","varför undersöka scourge vid ironforge","varför nevell vill få det här gjort"}},f222933f={q="Vilka skickas du att bekämpa utanför Ironforge?",a="Du skickas mot Scourges förtrupp, som slagit läger precis utanför Ironforges portar. Dessa odöda fasor, utsända på The Lich Kings order och stärkta av en svävande nekropol, vill terrorisera Dun Morogh och belägra dvärgarnas kungarike.",al={"vem ska jag bekämpa","scourges mål vid ironforge","vem strider jag mot"}}},fp="36,188,27.275.0,19.288.1,25.231.0,39.162.0,29.120.0,49.110.0"}
P.entries["quest:9262"] = {n="Investigate the Scourge of Darnassus",s="Investigate the Scourge of Darnassus är ett nöduppdrag från Lieutenant Beitha på uppdrag av Argent Dawn. Med en nekropol som tornar upp sig över Scourge-lägret får Alliansens försvarare i uppgift att förgöra de framryckande odöda och tyda de mörka runringar som dyker upp utanför stadsportarna.",h="Investigate the Scourge of Darnassus är ett nöduppdrag från Lieutenant Beitha på uppdrag av Argent Dawn.",kw={"argent dawn","beitha","darnassus","lich king","nekropol","nekrotisk sten","runring","scourge","teldrassil","odöda"},ang={["class:Druid"]="Nekromantins spridning och förruttnat kött på Teldrassils jord utgör en onaturlig farsot som varje vildmarkens väktare svurit att utrota.",["class:Priest"]="Präster ställs inför det isande provet att undersöka korrumperade nekromantiska runor och använda sin mentala disciplin och tro för att stå emot vansinnet som viskar genom Scourges mörka nätverk.",["faction:Alliance"]="Försvaret av Darnassus visar Alliansens beslutsamhet att stå enad mot det globala hot som Lich Kings invasionsstyrka utgör.",["race:NightElf"]="För kaldorei är ruttnande nekropoler och vanhelgande odöda så nära Teldrassils heliga mark en grotesk kränkning som måste renas bort omedelbart."},sec={{t="En farsot på världsträdet",b="Scourge-invasionen har nått Teldrassils skyddade grenar. Svävande nekropoler visar sig på himlen och kräks ut gastar, skelett och nekromantiska fasor alldeles utanför Darnassus. Lieutenant Beitha från Argent Dawn har trätt fram för att samordna försvaret av huvudstaden och värvar frivilliga som vill hejda förtruppen och samla underrättelser innan de odöda övermannar nattalvernas hemland."},{t="Viskningar i runorna",b="Utöver att dräpa de odöda och samla in deras dunkla nekrotiska stenar får spejare i uppdrag att undersöka märkliga, glödande runformationer som pulserar på marken nära invasionslägren. När försvarare går nära ringarna utsätts de för oroande övernaturliga viskningar, som avslöjar att runorna fungerar som onaturliga kommunikationsreläer, även om Lieutenant Beitha inte vet vem Scourge kontaktar."}},faq={{q="Vem är Lieutenant Beitha?",a="Lieutenant Beitha är en officer från Argent Dawn som är stationerad i Darnassus. Hon organiserar det lokala motståndet mot Scourge-invasionen och delar ut uppgifter för att minska antalet odöda och studera deras nekromantiska utrustning.",al={"vem ger uppdraget investigate the scourge of darnassus","uppdragsgivare beitha","lieutenant beithas bakgrund"}},{q="Varför anfaller Scourge Darnassus?",a="Uppdraget gäller Scourge-styrkor som slagit läger utanför Darnassus under en nekropol. Lieutenant Beitha ber försvararna minska deras antal och undersöka de märkliga runringarna i närheten.",al={"varför finns odöda i darnassus","invasionen av teldrassil","lich king anfaller nattalver"}},{q="Vad är de glödande runringarna utanför staden?",a="De glödande runringarna syns nära Scourges invasionsstyrkor. Lieutenant Beitha ber dig undersöka deras syfte.",al={"scourge-runor darnassus","runringar utanför darnassus","vad är invasionsrunorna"}},{q="Vad är dunkla nekrotiska stenar?",a="Dunkla nekrotiska stenar tas från Scourge-inträngare och förs till Argent Dawn som bevis på att odöda har dräpts.",al={"nekrotiska stenar","vad gör nekrotiska stenar","bakgrund om dim necrotic stone"}},{q="Vem finansierar eller leder försvaret i Darnassus?",a="Argent Dawn samordnar undersökningen genom Lieutenant Beitha. Orden är hängiven åt kampen mot Scourge.",al={"vem leder försvaret av darnassus","argent dawn darnassus"}},{q="Kan det skada dig att lyssna på runringarna?",a="Deras exakta effekter är inte fastställda. Beitha ber försvararna undersöka den märkliga energin kring ringarna.",al={"viskningar från runringar","är röster från runringar farliga"}}},fx={["39b377fd"]={q="Varför vill Lieutenant Beitha att det här görs?",a="The Lich King har sänt en odöd invasion ända fram till Teldrassils tröskel, med en hotfull nekropol ovanför Darnassus som bas. Lieutenant Beitha och Argent Dawn vägrar stå sysslolösa medan vidunder samlas utanför stadsportarna. Hon behöver att du decimerar deras led för att lätta trycket på huvudstaden, tar med bevis på att de har förstörts och avslöjar det mörka syftet bakom de lysande runringar som stärker deras läger.",al={"beithas motiv","varför undersöka scourge","varför beitha vill få det här gjort"}},a5f671f0={q="Vilka skickas du att bekämpa utanför Darnassus?",a="Du skickas mot Scourges invaderande styrkor, som har slagit läger precis utanför Darnassus. Dessa odöda trälar och vidunder har sänts direkt av The Lich King under skuggan av en svävande nekropol. De försöker få ett fotfäste och hota nattalvernas huvudstad.",al={"vem strider jag mot","vilka scourge-styrkor finns utanför darnassus","vilka är inkräktarna"}}},fp="36,187,26.352.0,21.290.1,25.185.0,39.160.0,52.111.0,29.113.0,52.118.0,44.109.0"}
P.entries["quest:9263"] = {n="Investigate the Scourge of Orgrimmar",s="Utanför Orgrimmar har Scourge slagit läger under en svävande nekropol. Lieutenant Dagel kallar på försvarare att slå tillbaka de odöda, återta nekrotiska stenar och undersöka runringar laddade med nekromantisk energi. Angreppet för Lich Kings räckvidd till Durotar.",h="Utanför Orgrimmar har Scourge slagit läger under en svävande nekropol.",kw={"argent dawn","dagel","durotar","invasion","lich king","nekrotisk sten","orgrimmar","runring","the scourge"},ang={["faction:Horde"]="En Scourge-styrka som slagit läger inom synhåll från Orgrimmars torn är en förolämpning Horden inte kan tåla. Varje svuren mästare har en plikt att försvara Durotar från Lich Kings undersåtar.",["race:Orc"]="Orcherna vann Durotars torra, röda jord genom umbäranden och blod. De tänker inte låta tanklösa vidunder vanställa hemmet de huggit ut med sina bara händer.",["race:Undead"]="För Forsaken väcker Scourge minnen av deras forna slaveri. Att krossa inkräktarna är en personlig vendetta mot Lich Kings fortsatta räckvidd."},sec={{t="Odöda vid portarna",b="Scourge hotar nu länder långt från Lordaeron och den nordliga isen. Svävande nekropoler kastar sina skuggor över Azeroth, till och med över Durotar. Odöda styrkor har samlats vid Orgrimmars portar och slagit läger som hotar Hordens huvudstad. Lieutenant Dagel och Argent Dawn samordnar försvaret och kallar på lokala mästare att driva tillbaka inkräktarna innan de kan inleda en belägring."},{t="Nekrotiska reliker och mörka viskningar",b="Scourges läger rymmer dunkla nekrotiska stenar och glödande runringar. Ringarna omger lägret och bär samma mörka kraft som nekropolen ovanför. De som kliver in i runorna hör onaturliga röster eka genom etern. Rösterna antyder någon form av kommunikation, men Dagel vet inte vem de når."}},faq={{q="Varför anfaller The Scourge Orgrimmar?",a="Scourge-styrkor har slagit läger utanför Orgrimmar under en nekropol. Lieutenant Dagel ber försvarare decimera deras led och undersöka de närliggande runringarna.",al={"varför the scourge orgrimmar","odöda utanför org","lich king anfaller orgrimmar"}},{q="Vem är Lieutenant Dagel?",a="Lieutenant Dagel är en officer som samordnar med Argent Dawn för att samla försvarare mot invasionen. Från en plats nära hotet leder Dagel krigare i att döda de odöda och undersöka deras magiska redskap.",al={"lieutenant dagel","dagel uppdragsgivare","vem är dagel"}},{q="Vad är de dunkla nekrotiska stenarna?",a="Dunkla nekrotiska stenar tas från Scourge-inkräktare och förs till Argent Dawn som bevis på att odöda har dödats.",al={"nekrotiska stenar","vad är dunkla nekrotiska stenar","dunkla stenar"}},{q="Vad är de glödande runringarna utanför staden?",a="De glödande ringarna bär samma märkliga energi som de närliggande odöda och nekropolen. Dagel ber försvarare undersöka deras syfte.",al={"runringar","glödande runor org","scourge-ringar"}},{q="Varför är Argent Dawn i Durotar?",a="Argent Dawn är en självständig orden som ägnar sig åt att förgöra Scourge var den än visar sig. Orden samarbetar med Hordens försvarare för att skydda Orgrimmars gränser från invasionen.",al={"argent dawn i orgrimmar","varför argent dawn här","argent dawn horden"}},{q="Är nekropolen ovanför staden farlig?",a="Nekropolen tornar upp sig över Scourges läger och delar dess märkliga energi. Dess närvaro gör hotet från de odöda nära staden oroande.",al={"svävande fästning org","nekropol ovanför durotar"}}},fx={["4fe35d0b"]={q="Varför vill Lieutenant Dagel att Scourge undersöks?",a="The Lich Kings undersåtar samlas precis utanför Orgrimmars portar under en hotfull nekropol, och Lieutenant Dagel vet att staden inte kan stå sysslolös. Han fruktar den vidriga magi inkräktarna smider i sina läger. Genom att avslöja syftet med deras märkliga, lysande runringar och decimera den annalkande horden hoppas Dagel få viktig information om Scourges mörka planer och avvärja en katastrofal belägring av Durotar.",al={"varför dagel vill det här","dagels motiv","varför undersöka scourge"}},["76cd191d"]={q="Vilka skickas du att bekämpa utanför Orgrimmar?",a="Du skickas mot de annalkande odöda styrkorna som sänts av The Lich King och slagit läger precis utanför Orgrimmar, under en svävande nekropol. Dessa viljelösa vidunder och vidriga vandrande döda ingår i en samordnad invasion som hotar Kalimdor. De etablerar vidriga arkana fästen i öknen för att försvaga Hordens försvar och terrorisera Durotar.",al={"vilka strider vi mot","scourge-fiender utanför orgrimmar","vem ska jag döda åt dagel"}}},fp="36,274,19.396.0,33.327.1,39.164.0,24.201.0,33.120.0,52.136.0,43.181.0,49.135.0"}
P.entries["quest:92640"] = {n="Desperate Times",s="Desperate Times ber spelarna rapportera till Valennia Stormfist i Valanaar för att planera ett direkt angrepp mot en farlig kults helgedom. Eftersom det inte går att konfrontera kulten öppet är det avgörande att slå ut dess ledare Lorthuna vid helgedomen, men det kräver att de djupa motsättningarna mellan Windshapers och High Order överbryggas.",h="Desperate Times ber spelarna rapportera till Valennia Stormfist i Valanaar för att planera ett direkt angrepp...",kw={"kult","desperate times","high order","lorthuna","helgedom","valanaar","valennia stormfist","windshapers"},sec={{t="Ett direkt angrepp",b="När kulten inte kan konfronteras säkert öppet måste försvararna byta till en djärvare strategi. I stället för en utdragen strid på ofördelaktig mark går planen ut på att utnyttja en öppning och slå direkt mot kultens helgedom. Om Lorthuna elimineras innan hon fullgör sin roll i deras storslagna plan kan hotet slås ut vid källan."},{t="Enade splittrade fraktioner",b="I Valanaar har Valennia Stormfist länge utarbetat en strategi för att anfalla helgedomen. Men räden kan inte lyckas utan betydande förstärkningar och samlad styrka. Ett angrepp kräver att allvarliga politiska motsättningar överbryggas, eftersom de kvarstående spänningarna mellan Windshapers och High Order hotar den allians som behövs för att genomföra anfallet."}},faq={{q="Vem är Valennia Stormfist?",a="Valennia Stormfist är en ledare eller strateg i Valanaar. Hon har ägnat tid åt att utveckla en taktisk plan för att anfalla helgedomen där kulten håller till, men för att genomföra den måste klyftan mellan rivaliserande fraktioner överbryggas.",al={"vem är valennia","valennia stormfist","var finns valennia"}},{q="Vem är Lorthuna?",a="Lorthuna är en central person i den fientliga kulten. Hon håller just nu på att genomföra en viktig plan vid helgedomen, vilket gör henne till huvudmålet för det föreslagna förebyggande anfallet.",al={"vem är lorthuna","lorthunas bakgrund","kultledaren lorthuna"}},{q="Varför måste helgedomen angripas direkt?",a="Att angripa kulten direkt i det öppna anses omöjligt eller självmordsbenäget. Ett direkt angrepp mot deras helgedom ger det bästa strategiska tillfället att oskadliggöra Lorthuna innan hennes plan kan förverkligas.",al={"varför anfalla helgedomen","orsaken till kultanfallet"}},{q="Vad är problemet mellan Windshapers och High Order?",a="Spänningarna är just nu stora mellan Windshapers och High Order. Trots motsättningarna påpekar Valennia att ingen av fraktionerna ensam kan hoppas lyckas med ett angrepp mot helgedomen; båda måste samarbeta.",al={"spänningar mellan high order och windshapers","varför strider fraktionerna","windshapers tvist"}},{q="Var ligger Valanaar?",a="Valanaar fungerar som utgångspunkt där Valennia Stormfist samordnar strategin och samlar nödvändiga allierade inför det kommande anfallet mot kultens helgedom.",al={"var ligger valanaar","valanaars plats"}},{q="Vad är det övergripande målet med uppdraget?",a="Målet är att söka upp Valennia Stormfist i Valanaar, ta reda på detaljerna kring hennes planerade angrepp mot helgedomen och bidra till att säkra det nödvändiga samarbetet mellan de splittrade fraktionerna.",al={"desperate times mål","vad är planen i desperate times"}}},fp="15,195,15.304.0,24.282.0,26.153.0,16.140.0,41.140.0,61.148.0,18.121.0,41.150.0"}
P.entries["quest:92642"] = {n="Disrupting Logistics",s="Disrupting Logistics ger äventyrare i uppdrag att hejda ett fullskaligt anfall från Al'Aketh-kultister i Gustberry Lowlands. Genom att slå ut fiendens helare, som håller frontens slagskämpar vid liv, hjälper spelarna de hårt trängda lokala försvararna att vända striden innan deras linjer kollapsar.",h="Disrupting Logistics ger äventyrare i uppdrag att hejda ett fullskaligt anfall från Al'Aketh-kultister i...",kw={"al'aketh","slagskämpar","kultister","disrupting logistics","gustberry lowlands","helare","valennia"},ang={["class:Priest"]="Präster vet hur viktigt helande stöd är för att hålla en anfallslinje uppe, vilket gör Al'Akeths helare till kultisternas offensivs nyckel.",["class:Rogue"]="Att smyga bakom fiendens linjer för att slå ut viktiga helare och störa förstärkningar till förtruppen är vanlig taktisk sabotageverksamhet för skurkar."},sec={{t="Ett desperat försvar",b="Ett våldsamt anfall hotar att övermanna försvararna som är stationerade ovanför Gustberry Lowlands. Fiendestyrkor samlas och de lokala linjerna pressas till bristningsgränsen, så frontens befälhavare börjar misströsta. Försvararna väntar sig betydande förstärkningar från Valennia, men tvingas förlita sig på vilka kapabla händer som än dyker upp. De hoppas att precisa angrepp mot fiendens stödnätverk kan förhindra en nära förestående kollaps."},{t="Bryt kultisternas linje",b="Al'Akeths anfall bygger på samordnade led av våldsamma slagskämpar, med hängivna helare som läker sår och håller trycket vid fronten uppe. I Gustberry Lowlands bryter det kultisternas offensiv när helarna slås ut. Då skärs deras uthållighet av, och försvararna får en chans att samla sig och slå tillbaka invasionen."}},faq={{q="Vad är uppdraget Disrupting Logistics?",a="Disrupting Logistics är ett brådskande försvarsuppdrag som ska hejda ett fullskaligt anfall från Al'Aketh-kultister i Gustberry Lowlands. En ensam försvarare håller stånd och behöver omedelbar hjälp med att slå ut fiendens stöd vid fronten innan försvaret kollapsar helt.",al={"vad är disrupting logistics","uppdraget disrupting logistics","uppdrag i gustberry lowlands"}},{q="Vilka är Al'Aketh-kultisterna som anfaller låglandet?",a="Anfallarna är Al'Aketh-kultister, med aggressiva slagskämpar och stödjande helare som driver ett pågående anfall in i Gustberry Lowlands. Deras samordnade front är starkt beroende av hängivna helare för att hålla ett oavbrutet tryck mot de lokala försvararna.",al={"vilka är alaketh","vem anfaller gustberry lowlands","vilka är kultisterna"}},{q="Varför är Al'Akeths helare särskilt utvalda mål?",a="Al'Akeths helare ger ett kontinuerligt helande stöd som låter förtruppens krigare storma fram utan uppehåll. Genom att slå ut helarna hoppas försvaret bryta anfallets momentum och skapa en öppning för att samla sig och driva kultisterna tillbaka.",al={"varför döda helare","varför rikta in sig på alakeths helare"}},{q="Var äger anfallet rum?",a="Gustberry Lowlands ligger precis nedanför den försvarspost som kultisterna belägrar. Området är nu översvämmat av Al'Akeths slagskämpar och helare, som driver sitt anfall framåt.",al={"var ligger gustberry lowlands","gustberry lowlands plats"}},{q="Vem är Valennia?",a="Valennia verkar vara en ledare eller samordnare med ansvar för att organisera hjälp och förstärkningar. Försvararen är dock frustrerad över att Valennia bara lyckades skicka en enda äventyrare för att möta ett massivt anfall.",al={"vem är valennia","valennia förstärkningar"}},{q="Vem leder försvaret mot Al'Aketh?",a="Uppdraget erbjuds av en hårt trängd försvarare vars folk är på väg att övermannas av Al'Aketh-kultisterna. Försvararen visar vördnad för ”vindarna” och är desperat efter alla stridskrafter som kan vända striden.",al={"vem ger disrupting logistics","vilka är mina folk som håller stånd"}}},fp="20,178,19.351.0,25.239.0,39.198.0,53.171.0,51.183.0,35.192.0,16.146.0,46.183.0"}
P.entries["quest:92643"] = {n="The Turncoat",s="The Turncoat handlar om en Al'Aketh-kultist som försöker hoppa av och byta kultens verkliga avsikter med ön mot en fristad. Resenärer skickas för att hämta honom från ett avskilt gömställe i högländerna nordväst om Valanaar. De måste ta reda på om detta hemliga möte är ett verkligt genombrott eller en dödlig fälla.",h="The Turncoat handlar om en Al'Aketh-kultist som försöker hoppa av och byta kultens verkliga avsikter med ön...",kw={"al'aketh","kultist","avhoppare","högländerna","the turncoat","valanaar"},ang={["class:Rogue"]="Infiltration, avhopp och bakhåll hör till välbekant mark. Kultister som bryter leden väntar sig tystnad eller ett hugg, och lönnmördarna utanför visar att hemlighetsmakeriet gick åt båda hållen i högländerna."},sec={{t="Eden som bröts",b="En hemlig kontakt inom Al'Aketh erbjuder en sällsynt möjlighet att genomskåda kultens hemlighetsmakeri. En kultist hävdar att han känner till organisationens verkliga avsikter med ön, har brutit sin trohet och erbjudit sig att hoppa av. I utbyte kräver han säkra löften om beskydd. Med tanke på hur väl kulten skyddar sina planer är varje spår in i dess inre värt risken att ta kontakt."},{t="Gömstället i högländerna",b="Avhopparen flydde till en avskild bostad i högländerna nordväst om Valanaar och väntar ensam på en diskret eskort. För att nå honom måste du ta dig försiktigt in bland kullarna. Mötet innebär en tydlig risk för ett Al'Aketh-bakhåll, utformat för att locka fram nyfikna motståndare."},{t="Tystnad i högländerna",b="Hoppet om ett fredligt undsättande krossas när du kommer fram till det avskilda huset i högländerna. Lönnmördare har redan spårat upp avhopparen och dödat honom innan någon eskort hunnit fram. Bland spåren efteråt och de fallna lönnmördarna utanför fångar en glimtande reflex på den döde avhopparens kropp blicken. Kanske har han ändå lämnat ett svar efter sig."}},faq={{q="Vem är avhopparen?",a="Avhopparen är en före detta medlem av Al'Aketh-kulten som påstod sig ha avgörande kunskap om kultens verkliga avsikter med ön. I utbyte mot beskydd erbjöd han sig att hoppa av och avslöja vad han visste.",al={"vem är avhopparen","vem var avhopparen","avhopparens identitet"}},{q="Vad är Al'Aketh?",a="Al'Aketh är en gåtfull kult som verkar i trakten. Deras hemliga planer och slutliga mål med ön förblir dolda bakom sträng sekretess och fanatism. Därför tar de lokala myndigheterna stora risker för att hämta avhoppare som är villiga att tala.",al={"vilka är alaketh","alaketh-kulten","vad är alaketh"}},{q="Var gömmer sig avhopparen?",a="Avhopparen tog sin tillflykt till en avskild bostad strax nordväst om Valanaar, inbäddad i högländerna. Det avlägsna huset valdes som gömställe medan han väntade på att bli hämtad, efter löften om beskydd.",al={"var gömmer sig avhopparen","avhopparens plats","var hittar man avhopparen"}},{q="Vad hände med avhopparen?",a="När någon nådde den avskilda bostaden i högländerna hade lönnmördare redan spårat upp och dödat avhopparen. Allt hopp om att förhöra honom medan han levde försvann när hans kropp hittades inne i huset.",al={"vad hände med avhopparen","dog avhopparen","vem dödade avhopparen"}},{q="Vad lämnade avhopparen efter sig?",a="När du undersöker den döde avhopparens kropp efter att ha gjort dig av med lönnmördarna utanför fångar något glittrande blicken. Föremålet han bar på blev kvar och antyder att hans hemligheter kanske inte dog helt med honom.",al={"vilket glänsande föremål","avhopparens glänsande föremål","glittrande reflex på kroppen"}},{q="Varför bestämde sig kultisten för att hoppa av?",a="Kultisten säger sig känna till Al'Akeths verkliga avsikter med ön och går bara med på att överlämna sig om han får löften om beskydd. Uppdraget säger inte vad som fick honom att hoppa av.",al={"varför hoppade kultisten av","avhopparens motiv","varför förråda alaketh"}}},fp="12,206,13.233.0,20.213.0,24.246.1,20.188.0,21.197.0,29.147.0,30.166.0,35.168.0,37.171.0"}
P.entries["quest:92644"] = {n="Unfortunate News",s="Unfortunate News är ett uppdrag i WoW Forever som följer på ett försök att kontakta en avhoppande kultist. När äventyraren anländer är informatören redan död. Äventyraren hittar en skadad, lysande blå kristall på kroppen och lämnar den till High Elder Talanaanis Shadowsong i Valanaar.",h="Unfortunate News är ett uppdrag i WoW Forever som följer på ett försök att kontakta en avhoppande kultist.",kw={"kultist","lysande kristall","shadowsong","talanaanis shadowsong","avhoppare","unfortunate news","valanaar"},ang={["class:Mage"]="Den återfunna artefakten är en skadad, lysande blå kristall som hittats hos en kultist. Den antyder att kultisterna ägnar sig åt magiska eller mystiska bruk som High Elder Shadowsong undersöker."},sec={{t="Ett misslyckat möte",b="I WoW Forever skildrar ”Unfortunate News” de dystra följderna av ett försök att möta en avhoppande kultist. En äventyrare som skickats för att träffa avhopparen upptäcker att informatören redan har dödats. Kroppen är fortfarande varm när äventyraren kommer fram. Under liket ligger en liten, lysande blå kristall. Den är skadad, men utstrålar fortfarande tillräckligt mycket närvaro för att motivera en omedelbar rapport till High Elder Talanaanis Shadowsong i Valanaar."},{t="Shadowsongs undersökning",b="När äventyraren återvänder ensam till Valanaar berättar hen att avhopparen dog innan något vittnesmål kunde samlas in. Förlusten av en levande kontakt är ett allvarligt bakslag, men den återfunna blå kristallen fångar High Elders uppmärksamhet. Han finner den skadade kristallen intressant och tar den från dig."}},faq={{q="Vad är uppdraget Unfortunate News?",a="”Unfortunate News” är ett uppdrag i WoW Forever som handlar om en avhoppande kultists död. När du upptäcker att avhopparen har dödats hittar du en mystisk, lysande kristall på liket och rapporterar tillbaka till High Elder Shadowsong.",al={"vad är unfortunate news","uppdraget unfortunate news","unfortunate news wow forever"}},{q="Vem var den avhoppande kultisten?",a="Avhopparen var en kultist som en äventyrare skickades för att träffa eller föra i säkerhet. Men kultisten dödades innan hen hann tala eller fly, och lämnade bara efter sig sitt fortfarande varma lik och en skadad kristall.",al={"vem är den döda avhopparen","vem dog i unfortunate news","avhoppande kultist"}},{q="Vem är High Elder Shadowsong?",a="Talanaanis Shadowsong är en alv och High Elder i Valanaar. Han leder undersökningar av kultisterna och tar emot den skadade kristall som hittas på avhopparens kropp.",al={"vem är shadowsong i valanaar","var finns talanaanis shadowsong","talanaanis shadowsong"}},{q="Vad är den skadade blå kristallen?",a="Det är en liten, lysande blå kristall som hittas under den fallna kultisten som hoppat av. Trots att den är synligt skadad finner High Elder Shadowsong den intressant och ser den som en ledtråd värd att undersöka vidare.",al={"vad är den lysande kristallen","blå kristall från kultist","skadad kristall unfortunate news"}},{q="Var utspelar sig uppdraget?",a="Valanaar är bosättningen eller utposten där High Elder Talanaanis Shadowsong bor och dit du återvänder för att lämna din rapport och den tillvaratagna kristallen.",al={"var ligger valanaar","valanaars plats","lämna in unfortunate news"}},{q="Hur hänger det här uppdraget ihop med The Turncoat?",a="Det här uppdraget följer direkt efter ”The Turncoat”, där en äventyrare ger sig av för att hitta den avhoppande kultisten, men kommer för sent för att rädda hen.",al={"vilket uppdrag kommer före unfortunate news","föregångare till unfortunate news","uppdraget the turncoat"}}},fp="16,164,19.232.0,26.275.1,35.166.0,29.160.0,29.166.0,33.153.0,33.120.0,44.112.0"}
P.entries["quest:92645"] = {n="Breaking the Breaker",s="Breaking the Breaker är ett desperat militärt anfall mot Commander Belguilos, en skräckinjagande före detta fredsväktare som nu leder ett farligt kultangrepp i Gustberry Lowlands. Att döda henne vid hennes villa på sluttningen ger de hårt ansatta försvararna deras enda verkliga chans att överleva anfallet.",h="Breaking the Breaker är ett desperat militärt anfall mot Commander Belguilos, en skräckinjagande före detta...",kw={"belguilos","breaking the breaker","commander belguilos","kultbefälhavare","gustberry lowlands","fredsväktare","the breaker","villa"},ang={["class:Warrior"]="Att möta Commander Belguilos innebär att ta sig an en aggressiv före detta fredsväktare som gjort sig förtjänt av den fruktade titeln ”the Breaker”.",["race:Skyborne"]="Åkallan av de fyra vindarna för att välsigna hjälten speglar Skyborne-kulturens traditioner och trosföreställningar när den står emot farliga kultister i låglandet."},sec={{t="Ett desperat försvar",b="Gustberry Lowlands utsätts för ett intensivt angrepp av aggressiva kultister, och de lokala försvararna pressas till gränsen för sin överlevnad. Att slå tillbaka anfallet verkar nästan omöjligt utan att slå till direkt mot operationens ledare: Commander Belguilos, som alla fruktar som ”the Breaker”. Att döda henne vid hennes basvilla anses vara en farlig, nästan självmordsbenägen uppgift, men passivitet garanterar försvararnas undergång."},{t="Den fallna fredsväktaren",b="Långt innan hon tog befälet över kultisthären upprätthöll Belguilos ordningen som fredsväktare. Ändå märkte de omkring henne redan då något djupt oroande i hennes uppförande. När kultens inflytande spred sig okontrollerat anammade hon dess extremism fullt ut. Nu är hon kultens befälhavare och en veritabel skräck."}},faq={{q="Vem är Belguilos the Breaker?",a="Belguilos, känd som ”the Breaker”, är en mäktig befälhavare som leder ett kultistangrepp. Innan hon anslöt sig till kulten tjänstgjorde hon som fredsväktare, men de som levde samtidigt med henne minns att hon redan då var djupt oroande och våldsbenägen.",al={"vem är belguilos","vem är the breaker","kultbefälhavare"}},{q="Var finns Commander Belguilos?",a="Commander Belguilos är stationerad i villan vid foten av kullen i Gustberry Lowlands. Därifrån kan hon samordna kultisternas offensiv mot de lokala försvararna.",al={"var finns belguilos","belguilos plats","var hittar man the breaker"}},{q="Varför måste Belguilos dödas?",a="De lokala försvararna utsätts för ett anfall från kultister som nästan inte går att slå tillbaka medan Belguilos leder angreppet. Om hon dödas bryts kultens ledarskap, vilket ger försvararna en verklig chans att överleva.",al={"varför döda belguilos","orsak till kultangreppet","varför är the breaker farlig"}},{q="Vad var Belguilos innan hon anslöt sig till kulten?",a="Belguilos tjänstgjorde ursprungligen som fredsväktare innan kulten spårade ur. De som kände henne tyckte dock att hon var märkbart ”underlig” redan när hon upprätthöll ordningen. Därför är hennes senare uppgång till brutal kultledare föga förvånande.",al={"vad var belguilos tidigare","var belguilos god","fredsväktare kultist"}},{q="Vad betyder välsignelsen från de fyra vindarna?",a="Välsignelsen åkallar de fyra vindarna, ett traditionellt uttryck för djup lättnad och tacksamhet. Försvararna använder det när de får veta att den skräckinjagande kultbefälhavaren har stoppats för gott.",al={"de fyra vindarnas betydelse","vem säger de fyra vindarna välsigne dig"}},{q="Vad är Gustberry Lowlands?",a="Gustberry Lowlands är det omstridda område där kultangreppet pågår. Vid foten av kullen ligger en villa där Commander Belguilos kan hittas.",al={"vad är gustberry lowlands","var finns uppdraget the breaker"}}},fp="20,195,19.329.0,22.276.0,29.175.0,39.158.0,33.180.0,50.158.0,59.166.0,32.144.0"}
P.entries["quest:92646"] = {n="Confront Lorthuna",s="Confront Lorthuna skildrar jakten på översteprästinnan Lorthuna, som flyr genom en portal till Rohashi Spires ovanför Zephras. Äventyrarna ska förstärka Elaadrin Evengale och Ayessa Dawnsinger i en desperat strid högt ovanför ön. Efter striden är viktiga försvarare skadade, och Zephras framtida säkerhet är oviss.",h="Confront Lorthuna skildrar jakten på översteprästinnan Lorthuna, som flyr genom en portal till Rohashi Spires...",kw={"ayessa dawnsinger","confront lorthuna","elaadrin evengale","översteprästinnan lorthuna","lorthuna","muln","rohashi spires","valennia","windshapers","zephras"},ang={["class:Priest"]="Översteprästinnan Lorthuna står för ett korrumperat andligt ledarskap bland spirorna, vilket gör striden mot henne särskilt betydelsefull för präster som försvarar sig mot mörka läror.",["class:Shaman"]="Muln och Windshapers vägleder den elementära balansen på Zephras, så schamaner har ett starkt andligt intresse av att öns elementära harmoni överlever Lorthunas hot."},sec={{t="Jakten till spirorna",b="Översteprästinnan Lorthuna flyr genom en mystisk portal upp till Rohashi Spires ovanför. En skadad allierad lämnas kvar vid portalens tröskel, medan Elaadrin Evengale och Ayessa Dawnsinger genast följer efter upp i höjden. De ropar på alla stridsdugliga hjältar att komma igenom och hjälpa dem innan Lorthuna undkommer rättvisan eller stärker sin makt."},{t="Stridens pris",b="Efter den farliga sammandrabbningen i spirorna är försvararna hårt åtgångna. Valennia och hennes överlevande styrkor behöver omedelbar vård av helare och förs tillbaka till High Elder's residence för att återhämta sig. Lorthuna möts i strid, men insatsen lämnar koalitionen sargad och dess resurser hårt ansträngda."},{t="En utsatt ö",b="När den omedelbara striden är över återvänder Muln till Azeroths fastland efter att ha diskuterat Windshapers framtid och deras fortsatta uppdrag. Men segern innebär ingen fred: efter striden är Zephras kritiskt utsatt, och de kvarvarande ledarna måste skyndsamt planera försvar mot de faror som väntar."}},faq={{q="Vem är översteprästinnan Lorthuna?",a="Översteprästinnan Lorthuna är en mäktig motståndare som flydde genom en portal till Rohashi Spires ovanför Zephras. Hennes handlingar utgjorde ett så allvarligt hot att viktiga försvarare, däribland Ayessa Dawnsinger och Elaadrin Evengale, följde efter henne för att besegra henne.",al={"vem är lorthuna","vad är lorthuna","översteprästinnan lorthunas bakgrund"}},{q="Vad är Rohashi Spires?",a="Rohashi Spires är högt belägna klippor som tornar upp sig ovanför ön Zephras. De nås via en portal och blev slagfältet dit översteprästinnan Lorthuna flydde för att ta strid.",al={"vad är rohashi spires","vart leder portalen","rohashi spires plats"}},{q="Vem följde efter Lorthuna genom portalen?",a="Elaadrin Evengale och Ayessa Dawnsinger var först genom portalen i jakten på översteprästinnan Lorthuna när hon flydde upp mot spirorna. De bad om förstärkning, och äventyraren följde efter.",al={"vem följde efter lorthuna","ayessa och elaadrin","vem går in i portalen"}},{q="Vad hände med Valennia och hennes styrkor?",a="Valennia ledde styrkor under konfrontationen och skadades svårt i striderna. Efteråt skickades helare dit för att säkerställa att hon kom tillbaka i trygghet, och hon fördes till High Elder's residence för att vila.",al={"vem är valennia","vad hände med valennia","valennas styrkor"}},{q="Vilken roll har Muln i händelserna?",a="Muln är en allierad med koppling till Windshapers, som hjälpte till på Zephras innan han återvände till Azeroths fastland. Innan han gav sig av diskuterade han Windshapers framtidsplaner och deras större uppdrag.",al={"vem är muln","muln lämnar zephras","vart tog muln vägen"}},{q="Är Zephras tryggt efter konfrontationen med Lorthuna?",a="Även efter konfrontationen med översteprästinnan Lorthuna är Zephras i ett utsatt läge. Ön är mer sårbar än någonsin, och försvararna måste utarbeta nya planer för att skydda den mot hot som närmar sig.",al={"vad händer med zephras","är zephras tryggt nu","zephrasöarnas tillstånd"}}},fp="17,204,23.295.0,22.248.1,25.257.1,31.169.0,28.138.0,37.141.0,41.156.0,36.134.0,59.146.0"}
P.entries["quest:92679"] = {n="Blood Tithe",s="Blood Tithe är ett uppdrag som Alvarion Windfield, en sjuklig Skyborne-bonde, inleder när han söker hjälp i bosättningen Valanaar. I sin desperation att skydda sin försörjning rekryterar han äventyrare som ska resa västerut till hans fruktträdgård i låglandet och hjälpa hans fru, Aamelia.",h="Blood Tithe är ett uppdrag som Alvarion Windfield, en sjuklig Skyborne-bonde, inleder när han söker hjälp i...",kw={"aamelia windfield","alvarion windfield","blood tithe","skyborne","valanaar","windfield orchard"},ang={["race:Skyborne"]="Alvarion Windfield är en Skyborne-bonde vars fysiska lidande och desperata vädjan om hjälp belyser de svårigheter som vanliga Skyborne möter utanför bosättningen Valanaar."},sec={{t="En vädjan i Valanaar",b="I bosättningen Valanaar söker en skadad Skyborne vid namn Alvarion Windfield desperat efter dugliga äventyrare. Alvarion plågas av synlig smärta och har rest från sitt hem till staden för att leja stridsvana personer som kan rädda hans försörjning. I stället för att ge resande uppgifter på plats vädjar han till dem som vill hjälpa att bege sig västerut till låglandet, där hans fru Aamelia sköter familjens fruktträdgård."},{t="Problem i låglandet",b="Windfield Orchard ligger i låglandet väster om Valanaar. Eftersom Alvarion är oförmögen att arbeta på grund av sitt svåra lidande faller ansvaret för gården på Aamelia Windfield. Äventyrare som antar Alvarions erbjudande måste ta sig till den västra dalen för att ta reda på vad som hotar fruktträdgården och hjälpa den hårt ansatta familjen."}},faq={{q="Vem är Alvarion Windfield?",a="Alvarion Windfield är en Skyborne-bonde som har kommit till Valanaar för att hitta dugliga stridskämpar som kan skydda hans hem. Trots att han lider av svår fysisk smärta lyckas han hänvisa äventyrarna till sin fru, Aamelia, vid deras fruktträdgård.",al={"vem är alvarion","alvarion windfields bakgrund","vem ger blood tithe"}},{q="Var ligger Windfield Orchard?",a="Windfield Orchard ligger väster om Valanaar, nere i låglandet. Alvarion skickar dit äventyrare för att träffa sin fru, Aamelia Windfield, som leder gårdens omedelbara försvar.",al={"var ligger windfield orchard","var finns aamelia windfield","hur hittar man fruktträdgården"}},{q="Varför har Alvarion ont?",a="När man träffar honom säger han inte vad han lider av, men Alvarion plågas tydligt av intensiv, förlamande smärta när han talar. Det gör hans vädjan om hjälp än mer brådskande.",al={"varför har alvarion ont","vad är det för fel på alvarion","alvarions smärta"}},{q="Vem är Aamelia Windfield?",a="Aamelia Windfield är Alvarions fru och befinner sig vid familjens fruktträdgård väster om Valanaar. Alvarion hänvisar villiga äventyrare till henne så att hon kan organisera försvaret av deras mark.",al={"vem är aamelia","aamelia windfields bakgrund","alvarions fru"}},{q="Vad går uppdraget Blood Tithe ut på?",a="Blood Tithe börjar med att Alvarion Windfield rekryterar resande i Valanaar för att hjälpa hans utsatta gård. Äventyrarna måste lyssna på hans önskemål och söka upp hans fru Aamelia vid deras fruktträdgård i låglandet.",al={"sammanfattning av uppdraget blood tithe","vad handlar blood tithe om","gård under attack i valanaar"}},{q="Vilken betydelse har Valanaar här?",a="Valanaar är en bosättning där resande och Skyborne samlas. Alvarion besöker denna samlingsplats särskilt för att hitta lejda hjälpare och äventyrare som kan rädda hans fruktträdgård från faran.",al={"valanaars bakgrund","var utspelar sig blood tithe","vad är valanaar"}}},fp="11,208,18.270.0,23.239.0,26.183.0,39.163.0,24.149.0,25.143.0,32.131.0,37.139.0"}
P.entries["quest:92682"] = {n="Make Yourself Useful",s="Make Yourself Useful är ett uppdrag på Windfield Orchard där äventyrare hjälper till att skydda stormäppleskörden mot odisciplinerade banditer. En utpressare vid namn Ferauu ska hämta sin vanliga andel av skörden, men hungriga fredlösa har lämnat leden för att plundra träden i förväg. När du tar hand om dessa tjuvar vinner du den vaksamme fruktodlarens respekt.",h="Make Yourself Useful är ett uppdrag på Windfield Orchard där äventyrare hjälper till att skydda...",kw={"banditer","ferauu","hungriga banditer","make yourself useful","fruktodling","mogna stormäpplen","stormäpplen","windfield orchard"},ang={["class:Rogue"]="Medan fredlösa banditer sviker sitt eget gäng för att få smaka stormäpplen i förtid känner rutinerade skurkar igen den klassiska bristen på disciplin hos amatörtjuvar."},sec={{t="Problem på Windfield Orchard",b="På Windfield Orchard försvåras jordbruket av utpressning. En banditledare vid namn Ferauu och hans gäng har gjort upp om att ta sin vanliga andel av fruktskörden. Men disciplinen brister bland banditerna, så småtjuvar kan inte alltid vänta tills chefen kommer som planerat. De smyger in i förväg för att plocka från träden."},{t="Tjuvar bland tjuvar",b="I stället för att tåla odisciplinerade tjuvar bland stormäppelträden sätter fruktodlaren ambitiösa nykomlingar i arbete innan Ferauu väntas komma. Äventyrare får i uppgift att säkra den mogna stormäppleskörden och göra sig av med de hungriga banditer som olovligen rör sig bland träden. Odlaren påpekar att Ferauu troligen skulle avrätta skurkarna själv för att de gått bakom ryggen på honom och lagt beslag på hans andel."}},faq={{q="Vem är Ferauu?",a="Ferauu är en banditledare som pressar Windfield Orchard på regelbundna tributer, eller en ”andel”, av skörden. Han upprätthåller en hänsynslös disciplin bland sina män, men uppenbarligen inte tillräckligt för att hindra några hungriga underhuggare från att smyga dit i förväg bakom hans rygg.",al={"vem är ferauu","ferauus historia","ferauu banditledare"}},{q="Vad är Windfield Orchard?",a="Windfield Orchard är en lokal odling som är känd för sina stormäpplen. Odlingen drivs under tvång och måste betala Ferauus banditgäng med delar av fruktskörden för att hålla fred.",al={"vad är windfield orchard","windfield orchards historia","stormäppelodling"}},{q="Varför stryker hungriga banditer omkring bland stormäppelträden?",a="Hungriga banditer som tillhör Ferauu har tjuvstartat och smugit in i odlingen före den planerade hämtningen av skörden för att stjäla stormäpplen åt sig själva. Eftersom de har lämnat leden och stjäl från skörden sätter fruktodlaren äventyrare i arbete med att rensa bort dem.",al={"varför döda hungriga banditer","varför är banditer på odlingen","hungriga banditers historia"}},{q="Vad är stormäpplen?",a="Stormäpplen är en fruktsort som odlas på Windfield Orchard. De är tillräckligt eftertraktade för att både vara vardagsmat och utgöra den tribut som lokala brottsgäng som Ferauus kräver.",al={"vad är stormäpplen","mogna stormäpplen"}},{q="Vet Ferauu att hans banditer smyger in i odlingen?",a="Nej, Ferauu vet inte att just de här banditerna kom tidigt. Som fruktodlaren påpekar har dessa fredlösa gått sin egen väg, och Ferauu skulle troligen avrätta dem själv om han kom på dem med att lägga beslag på skörden innan han anlände.",al={"vet ferauu om banditerna","ferauus svek"}},{q="Vem ger dig uppdraget Make Yourself Useful?",a="Uppdraget erbjuds av fruktodlaren på Windfield Orchard, som håller uppsikt över odlingarna från ett fönster i närheten. När djärva nykomlingar kommer för att söka arbete eller mat sätter odlaren deras mod på prov genom att skicka dem mot inkräktande banditer.",al={"vem ger make yourself useful","uppdragsgivare för make yourself useful"}}},fp="20,208,28.224.0,21.298.0,14.193.0,26.153.0,53.219.0,21.125.0,59.175.0,40.230.0"}
P.entries["quest:92683"] = {n="Flutterfly Dust",s="Flutterfly Dust är en lokal syssla i Gustberry Lowlands där pulver samlas från jättelika, bevingade flutterflies. Insekterna är vanligtvis fogliga, men ensliga nybyggare behöver resenärers hjälp med att samla in det kladdiga ämnet på grund av det ständiga hotet från kringströvande banditer.",h="Flutterfly Dust är en lokal syssla i Gustberry Lowlands där pulver samlas från jättelika, bevingade...",kw={"banditer","flutterfly","flutterfly dust","flutterfly swatter","gustberry lowlands","fruktodling","vingdamm"},sec={{t="Giganterna i Gustberry",b="De yttre fälten och fruktodlingarna i Gustberry Lowlands är hem åt jättelika flutterflies, natursköna bevingade insekter som makligt svävar genom landsbygden. Deras milda utseende ger trakten en lantlig charm, men de fladdrande vingarna sprider ett fint, genomträngande damm som kan samlas in i stora mängder. Även om insekterna främst lever vilt, lockar deras närvaro närboende nybyggare som vill samla in denna luftburna biprodukt för praktiska hushållsbehov."},{t="Flugsmällor och skakningar",b="För att samla in flutterfly-damm krävs ett förvånansvärt trubbigt tillvägagångssätt: slå de stora insekterna med en Flutterfly Swatter. De flesta flutterflies får panik och flyger upp när de blir slagna, skakar på bakdelen och lämnar högar av löst pulver efter sig. Ibland vänder sig dock en upprörd flutterfly om och slår tillbaka när den blir provocerad, vilket visar att även fogliga trädgårdskryp har sina gränser när de får en smäll."},{t="Outtalade användningsområden",b="Att samla in dammet är kladdigt och det fastnar lätt, så kläder och utrustning brukar vara täckta i veckor. Den lokala beställaren väntar ivrigt på leveransen eftersom banditer på lur gör ensamma utflykter till fälten alltför farliga, men dammets slutdestination hålls hemlig. När nybyggaren får frågor om vad det ska användas till, avfärdar hen dem undvikande med att det är till allmänna ”grejer och sånt”."}},faq={{q="Vad används flutterfly-damm till?",a="Enligt den lokala invånaren som samlar in det har vingdammet från jättelika flutterflies praktiska användningsområden i hemmet när det samlas i tillräckliga mängder. Det exakta syftet förblir dock medvetet oklart, eftersom uppdragsgivaren avleder frågor med påståendet att det är till allmänna ”grejer och sånt”.",al={"vad är flutterfly dust","användning av flutterfly dust","vad ska dammet användas till"}},{q="Var finns flutterflies?",a="Jättelika flutterflies kan hittas fladdrande över de yttre fälten nära den lokala fruktodlingen, särskilt i Gustberry Lowlands. De delar fälten med närliggande banditer, vilket gör insamlingen farlig för ensliga invånare.",al={"var finns flutterflies","flutterfly-plats","kryp i gustberry lowlands"}},{q="Är flutterflies aggressiva?",a="Flutterflies är i allmänhet fogliga och lugna varelser som oftast flyr när de blir störda. Men om de får en smäll eller provoceras kan några ta illa upp och överraska äventyrare genom att försvara sig innan de släpper ifrån sig vingdammet.",al={"är flutterflies farliga","attackerar flutterflies","flutterfly-beteende"}},{q="Hur samlas flutterfly-damm in?",a="Äventyrare använder en specialutformad Flutterfly Swatter för att ge de överdimensionerade insekterna en rejäl smäll. De skrämda eller upprörda varelserna skakar på bakdelen när de reagerar och sprider en hög med vingdamm som går att samla in på marken.",al={"hur får man tag på damm","flutterfly swatter","samla flutterfly-damm"}},{q="Varför behöver invånaren hjälp med att samla in dammet?",a="Nybyggaren som behöver dammet bor ensam och kan inte enkelt lämna huset för att samla in det, eftersom banditer som lurar i låglandet runtomkring utgör ett alltför stort hot för att det ska vara värt risken att ge sig långt ut på fälten.",al={"varför behövs hjälp","bandithot i gustberry","varför ber uppdragsgivaren om hjälp"}},{q="Varför är invånaren undvikande om dammets egentliga syfte?",a="Uppdragsgivaren vägrar avslöja exakt vad det kladdiga dammet ska användas till i hushållet och viftar nervöst bort frågorna med ”grejer och sånt”. Om det handlar om en pinsam personlig syssla, ett oortodoxt hantverk eller helt enkelt privata angelägenheter förblir oförklarat.",al={"varför så hemlighetsfull","hemligt dammrecept"}}},fp="15,184,23.244.0,19.200.0,21.277.0,33.122.0,29.170.0,28.135.0,33.151.0,59.169.0,58.144.0"}
P.entries["quest:92684"] = {n="Ornery Ornery Galestriders",s="Ornery Ornery Galestriders handlar om en fruktodlare i Gustberry Lowlands som kämpar med en mager säsongsskörd. De lokala galestriders i låglandet, större och vildsintare än sina släktingar i höglandet, har plundrat odlingen på stormapples och hotar gårdens försörjning. Om du gallrar ut de aggressiva fåglarna säkrar du den återstående frukten och får välbehövliga färska filéer till middagen.",h="Ornery Ornery Galestriders handlar om en fruktodlare i Gustberry Lowlands som kämpar med en mager...",kw={"galestrider","gustberry lowlands","galestrider i låglandet","fruktodling","argsinta galestriders","stormapples","filé"},ang={["class:Hunter"]="Jägare som spårar vilda djur i Gustberry Lowlands bör tänka på att de lokala galestriders i låglandet har kraftiga sparkar och ett aggressivt temperament jämfört med sina släktingar i höglandet.",["profession:Cooking"]="Galestriders i låglandet ger rejäla bitar filé som blir en mättande varm måltid, ett välkommet avbrott från magra skördar och frukt."},sec={{t="Försvara odlingen",b="I Gustberry Lowlands har lokala bönder det svårt efter en redan mager säsongsskörd. Som om det inte vore nog har vilda galestriders invaderat odlingarna, länsat grenarna på mogna stormapples och hotat den lilla frukt som finns kvar. För att gården ska kunna överleva måste de djärvaste fåglarna skrämmas bort eller gallras ut innan hela skörden går förlorad."},{t="Låglandets fasor",b="Till skillnad från sina mindre och jämförelsevis lugnare kusiner i höglandet är låglandets galestriders väldiga, argsinta bestar. Resenärer i låglandet måste närma sig dem med yttersta försiktighet, eftersom en enda välriktad spark från deras kraftiga ben kan sätta en oförsiktig kämpe ur stridbart skick eller döda hen. När de fälls ger de stora filéer som förser hungriga lokalbor med sällsynta, rejäla måltider."}},faq={{q="Varför ställer galestriders till problem för bonden?",a="De lokala galestriders har plundrat odlingen för att äta bondens stormapples. Eftersom säsongens skörd redan är ovanligt liten hotar fruktstölden direkt den lokala matförsörjningen.",al={"vad stjäl galestriders","varför döda galestriders","stormappleodling"}},{q="Hur farliga är galestriders i låglandet?",a="Galestriders i låglandet är betydligt större och aggressivare än de som finns i höglandet. Deras kraftiga, välriktade sparkar kan lätt slå omkull en resenär för gott om hen blir överraskad.",al={"hur farliga är galestriders","galestriderattacker","är galestriders starka"}},{q="Vad vill bonden ha från galestriders?",a="Bonden ber resenärer att gallra ut de aggressiva galestriders i låglandet och samla in filéer från de fallna bestarna. Köttet ger en välbehövlig varm måltid efter lång tid utan färskt kött.",al={"galestriderkött","vad lämnar galestriders efter sig","filéuppdrag"}},{q="Var finns de här galestriders?",a="Argsinta galestriders från låglandet strövar omkring i Gustberry Lowlands, särskilt nära gårdarna och fruktodlingarna där de letar efter stormapples.",al={"var finns galestriders","galestriders plats","gustberry lowlands"}},{q="Hur skiljer sig galestriders i låglandet från dem i höglandet?",a="Galestriders i låglandet skiljer sig från sina motsvarigheter i höglandet främst genom storlek och temperament: låglandets variant blir märkbart större, är betydligt argsintare och utdelar förödande sparkar.",al={"galestriders i höglandet jämfört med låglandet","galestridervarianter"}},{q="Vad är stormapples?",a="Stormapples är en frukt som odlas i regionen. Eftersom skörden den här säsongen redan är knapp är det avgörande att skydda de återstående träden från galestriders som letar efter mat.",al={"vad är stormapples","fruktskörd"}}},fp="26,213,21.253.0,15.241.0,57.126.0,40.136.0,48.109.0,35.132.0,63.120.0,21.141.0"}
P.entries["quest:92685"] = {n="The Hills Have Eyes",s="\"The Hills Have Eyes\" är ett uppdrag i Gustberry Lowlands där den hårt ansatta bonden Aamelia tar strid mot landsvägsrövare. Äventyrare slår till mot ett läger i de norra kullarna för att försvaga rövarbandet innan dess ledare Ferauu går till anfall.",h="\"The Hills Have Eyes\" är ett uppdrag i Gustberry Lowlands där den hårt ansatta bonden Aamelia tar strid mot...",kw={"aamelia","rövarmasker","blodfläckade rövarmasker","ferauu","gustberry lowlands","landsvägsrövare","the hills have eyes"},ang={["profession:Tailoring"]="Aamelia skämtar mörkt om att sy en filt av blodfläckade rövarmasker åt Ferauu, vilket visar hennes rätt makabra förtjusning i nål och tråd."},sec={{t="Ett förebyggande anfall",b="I Gustberry Lowlands står bonden Aamelia inför ett överhängande anfall från ett rövarband lett av Ferauu. I stället för att passivt vänta på att undergången ska stå vid hennes dörr uppmanar hon resande att slå till mot ett rövarläger i kullarna norrut. Genom att slå ut landsvägsrövarna innan de samlar sig för attacken hoppas hon tunna ut deras led och vinna dyrbar tid."},{t="Förnyat hopp och hämnd",b="Som bevis på bakhållet ber Aamelia om blodfläckade masker som tagits från de stupade landsvägsrövarna. Hon skämtar bistert om att sy ihop dem till en filt att ge Ferauu och gläds åt vetskapen om att hennes plågoandar mötte hårt motstånd. När lägret i norr försvagas bryts veckor av hopplös väntan, och hon får mod att stå upp när Ferauu och hans huvudstyrka till slut anländer."}},faq={{q="Vad är The Hills Have Eyes?",a="\"The Hills Have Eyes\" är ett försvarsuppdrag som Aamelia ger på sin gård. Inför ett nära förestående anfall från Ferauus rövarband skickar hon äventyrare till kullarna i norr för att överfalla rövarna och hämta deras blodfläckade masker innan de slår till.",al={"uppdraget hills have eyes","vad är det här för uppdrag","vad är hills have eyes"}},{q="Vem ger uppdraget The Hills Have Eyes?",a="Aamelia försvarar sin gård och har i veckor väntat skräckslagen på att rövare ska övermanna hennes hem. När hon slår tillbaka mot landsvägsrövarna får hon nytt hopp inför Ferauus förestående anfall.",al={"vem ger hills have eyes","vem är aamelia","uppdragsgivaren aamelia"}},{q="Vem är Ferauu?",a="Ferauu leder landsvägsrövarna som härjar kring Gustberry Lowlands. Han och hans banditer har hotat Aamelias gård och är redo att gå till anfall.",al={"vem är ferauu","ferauu boss","rövarledaren ferauu"}},{q="Var finns landsvägsrövarna?",a="Highwayman Bandits håller till i läger runt om i Gustberry Lowlands, däribland ett litet läger uppe i kullarna strax norr om Aamelias gård.",al={"rövare i gustberry lowlands","var finns rövarna","rövarläger i kullarna"}},{q="Varför vill Aamelia ha blodfläckade rövarmasker?",a="Aamelia kräver blodfläckade masker som bevis på att rövarna fick lida och överrumplades. Att slå ner dem i förväg jämnar ut oddsen inför Ferauus nära förestående anfall.",al={"varför samla masker","varför blodfläckade masker","vad ska maskerna användas till"}},{q="Vad händer efter att uppdraget är slutfört?",a="När lägret i kullarna har slagits ut börjar Aamelia åter känna hopp för sin gård. Men Ferauu och hans kvarvarande banditer väntas anlända när som helst, och en sista strid närmar sig.",al={"vad händer efter hills have eyes","nästa uppdrag aamelia","ferauus anfall"}}},fp="19,175,19.295.0,28.357.1,28.177.0,40.136.0,14.130.0,41.136.0,49.140.0,40.161.0"}
P.entries["quest:92693"] = {n="Standing Our Ground",s="Standing Our Ground är ett avgörande uppdrag där en äventyrare står sida vid sida med Aamelia Windfield i en desperat konfrontation med en hotfull banditledare. Efter att ha förberett försvararna för strid möter du det som tycktes vara en förlorad kamp för att skydda dem från banditerna.",h="Standing Our Ground är ett avgörande uppdrag där en äventyrare står sida vid sida med Aamelia Windfield i en...",kw={"aamelia windfield","banditledare","banditer","förlorad kamp","standing our ground","valanaar"},sec={{t="En desperat sista strid",b="Standing Our Ground är höjdpunkten i en desperat kamp mot ett banditgäng. Efter att ha hjälpt till att förbereda de lokala försvararna för en oundviklig strid får du en sista möjlighet att gå därifrån och återvända tryggt till Valanaar i stället för att kasta dig in i vad som verkar vara en dödsdömd sista strid."},{t="Mötet med banditledaren",b="När du signalerar att du är redo går du fram tillsammans med Aamelia Windfield för att möta banditledaren direkt. När du besegrar banditen är det överhängande hotet undanröjt, och Aamelia kippar efter andan av chock och lättnad över att deras desperata chansning faktiskt lyckades."}},faq={{q="Vem ger uppdraget Standing Our Ground?",a="Uppdraget ges av Aamelia Windfield, som förbereder sig på att möta ett förestående banditanfall och ger dig en sista chans att dra dig ur innan ni konfronterar deras ledare.",al={"vem ger standing our ground","uppdragsgivare standing our ground","npc standing our ground"}},{q="Vem slåss du mot i Standing Our Ground?",a="Du möter en framryckande banditledare som hotar de lokala försvararna. Aamelia Windfield samlar sina sista krafter för att marschera ut och möta ledaren direkt.",al={"vem är banditledaren i standing our ground","boss i standing our ground","banditledare i standing our ground"}},{q="Vilken roll spelar Valanaar i det här uppdraget?",a="Valanaar är den närliggande bosättning som Aamelia Windfield nämner som en tillflyktsort. Hon ger dig uttryckligen möjligheten att dra dig tillbaka till Valanaar om du inte vill riskera livet i striden.",al={"var ligger valanaar i standing our ground","reträttstad i standing our ground","valanaar-uppdrag"}},{q="Varför beskriver Aamelia striden som en förlorad kamp?",a="Aamelia och hennes följeslagare tror att oddsen är starkt emot dem. De ser konfrontationen som en desperat sista strid där det verkar nästan omöjligt att överleva en dag till utan hjälp utifrån.",al={"varför är standing our ground en förlorad kamp","standing our ground-berättelse","aamelia windfields kamp"}},{q="Vad händer när konfrontationen är över?",a="Mot alla odds besegras banditledaren. När uppdraget är slutfört är Aamelia Windfield chockad och lättad över att prövningen äntligen är över, och kämpar för att lugna sitt bultande hjärta.",al={"vad händer efter att banditledaren besegrats i standing our ground","lämna in standing our ground","överlever aamelia"}},{q="Vad leder fram till den sista striden?",a="Före det här uppdraget hjälpte du försvararna med förberedelser som gav dem en chans att slåss mot bandithotet och banade väg för den avgörande konfrontationen.",al={"förkunskapskrav för standing our ground","uppdrag före standing our ground"}}},fp="19,181,22.219.0,29.228.1,40.89.0,40.122.0,43.129.0,53.169.0,44.139.0,34.117.0"}
P.entries["quest:92698"] = {n="What Is My Purpose?",s="\"What Is My Purpose?\" är ett uppdrag som kretsar kring en jättelik Malfunctioning Cyclone Construct, som planlöst vandrar genom åkrarna. Den uråldriga maskinen upprepar trasiga talfragment under sin pansarplåt och har glömt sina ursprungliga uppgifter efter årtionden av vanvård sedan vindelementarerna gav sig av. För att undersöka konstrukten får äventyrarna söka upp den lokala fruktodlaren Aamelia Windfield och fråga om dess mystiska förflutna och tidigare skötare.",h="\"What Is My Purpose?\" är ett uppdrag som kretsar kring en jättelik Malfunctioning Cyclone Construct, som...",kw={"aamelia windfield","alvarion","konstrukt","cyklonkonstrukt","felande cyklonkonstrukt","fruktodling","vad är mitt syfte","vindelementarer","windshapers"},ang={["class:Shaman"]="Schamaner kan vara särskilt intresserade av konstruktens funktionsförfall, eftersom lokala berättelser kopplar dess övergivande och haveri direkt till vindelementarernas avfärd från området.",["profession:Engineering"]="Ingenjörer kan finna Malfunctioning Cyclone Construct intressant som exempel på uråldrig automatisering. Dess interna logikloopar består trots århundraden av slitage och total avsaknad av tekniskt underhåll."},sec={{t="Den vandrande konstrukten",b="Djupt inne bland åkrarna står en väldig Cyclone Construct och vandrar planlöst över marken, fast i en trasig funktionsloop. Den som närmar sig den bepansrade jätten kan höra dämpat, fragmenterat tal vibrera under de tunga plåtarna. Den upprepar felmeddelanden i det oändliga och ifrågasätter sin grundläggande funktion. Årtionden av isolering har berövat maskinen dess syfte, och dess interna direktiv är förvanskade eller bortglömda. Automatonen ser väldig och skräckinjagande ut, men utgör inget aktivt hot mot förbipasserande. I stället är den en melankolisk relik från en äldre tid, vars röst reducerats till statiska frågor som ekar över jorden."},{t="Glömt arbete och The Windshapers",b="När Aamelia Windfield får frågor om maskinen berättar hon att automatonen har vandrat omkring på fälten i årtionden, till synes ända sedan vindelementarerna gav sig av. En lokalbo vid namn Alvarion spekulerade i att maskinen en gång fraktade rikliga skördar till avlägsna marknader eller skötte boskap, för flera sekler sedan och långt innan marken blev en fruktodling. I forna tider byggde och underhöll en grupp som kallades The Windshapers dessa cyklonkonstrukter. Fruktodlarna har ibland pratat om att be The Windshapers reparera maskinen, men frågan har aldrig varit brådskande. Därför får konstrukten ströva omkring ostörd och till stor del ignorerad."}},faq={{q="Vad är Malfunctioning Cyclone Construct?",a="Malfunctioning Cyclone Construct är en uråldrig bepansrad automaton som planlöst vandrar genom de lokala åkrarna. Den underhölls en gång av The Windshapers, men har förfallit efter årtionden av vanvård. Under sin pansarplåt upprepar den oavbrutet trasiga talfragment som ifrågasätter dess syfte och rapporterar funktionsfel.",al={"vad är konstrukten","cyklonkonstrukt","jättekonstrukt på åkrarna"}},{q="Vem är Aamelia Windfield?",a="Aamelia Windfield är en lokalbo som bor nära fruktodlingen där den felande konstrukten vandrar. Hon känner till maskinens historia och berättar att den har vandrat över fälten i årtionden sedan vindelementarerna gav sig av, och att dess skapare, The Windshapers, brukade ta hand om sådana apparater.",al={"aamelia windfield","vem är aamelia","fruktodlings-npc"}},{q="Vad var konstruktens ursprungliga syfte?",a="Konstruktens exakta ursprungliga syfte har fallit i glömska. Enligt Aamelia Windfield trodde en lokalbo vid namn Alvarion att den kan ha fraktat skördar till marknaden eller skött boskap för flera sekler sedan, innan den nuvarande fruktodlingen fanns. Det kan ha varit så långt tillbaka som tusen år.",al={"konstruktens syfte","vad gjorde konstrukten","konstruktens uppgift"}},{q="Vilka är The Windshapers?",a="The Windshapers är en uråldrig grupp som är känd för att skapa och underhålla cyklonkonstrukter. Förr ansvarade de för att serva dessa automatiserade maskiner. Numera har de lokala lantarbetarna inte bett dem om hjälp, eftersom det saknas både överhängande fara och behov.",al={"windshapers","vem skapade konstrukten","vem underhåller cyklonkonstrukter"}},{q="Varför upprepar konstrukten fragmenterade ord?",a="Konstrukten lider av ett allvarligt mekaniskt eller funktionellt fel, troligen orsakat av årtionden utan underhåll efter att vindelementarerna gav sig av. När någon närmar sig yttrar den osammanhängande fraser som ”funktionsfel” och ”vad är funktion”, vilket tyder på att dess direktivhantering har fastnat i en olöst frågeloop.",al={"varför talar konstrukten","funktionsfel hos konstrukten","vad säger den"}},{q="Varför har lokalborna inte reparerat eller monterat ned konstrukten?",a="Konstrukten utgör inget hot mot invånarna eller deras fruktodlingar, utan vandrar bara fredligt bland träden och grödorna. Lokalbor som Aamelia Windfield har pratat om att be The Windshapers om underhåll, men frågan har aldrig varit tillräckligt brådskande för att motivera handling. Därför ignorerar lokalborna den helt enkelt.",al={"varför ignoreras konstrukten","varför lagar man inte konstrukten","är konstrukten farlig"}},{q="Vem är Alvarion?",a="Alvarion är en lokalbo som Aamelia Windfield nämner och som undersökte den vandrande konstruktens historia. Han trodde att maskinen ursprungligen utförde jordbruksarbete, antingen genom att frakta inbärgade skördar till marknaden eller genom att valla boskap långt innan området gjordes om till en fruktodling.",al={"alvarion","vem är alvarion","alvarions teori"}}},fp="19,220,23.373.0,35.470.0,45.276.0,25.191.0,42.187.0,24.182.0,48.216.0,60.264.0,16.201.0"}
P.entries["quest:92699"] = {n="The Supreme Magister",s="The Supreme Magister hänvisar nyanlända äventyrare i Valanaar till Elaadrin Evengale, ledaren för High Order. Orden håller till i en lodge i bosättningens sydöstra del och söker dugliga allierade samtidigt som den hanterar bittra motsättningar med Windshapers och hotet från en lokal sekt.",h="The Supreme Magister hänvisar nyanlända äventyrare i Valanaar till Elaadrin Evengale, ledaren för High Order.",kw={"magi","sekt","elaadrin evengale","high order","rathiril","the supreme magister","valanaar","windshapers"},ang={["class:Mage"]="Elaadrin lägger märke till en livfull magisk aura hos magiutövare och värdesätter den sällsynta begåvning och vilja som krävs för att bemästra magin och bevara deras hemland."},sec={{t="High Order i Valanaar",b="När de anländer till Valanaar hänvisas nykomlingar med särskilt stor potential till High Order. Organisationen leds av Supreme Magister Elaadrin Evengale och håller till i en lodge längst i bosättningens sydöstra del. Elaadrin håller noga uppsikt över nyanlända och söker dem som har den styrka, beslutsamhet och mystiska aura som krävs för att möta farorna kring deras hotade hem."},{t="Rivaliserande fraktioner och hotande sekter",b="Den sköra inre freden i Valanaar är hotad. High Order och Windshapers hyser en djup fientlighet mot varandra, och nykomlingar varnas för att hålla sig på långt avstånd från Windshapers så att våld inte bryter ut på gatorna. Med en farlig sekt i närheten har de lokala ledarna inte råd med inre blodsutgjutelse medan yttre hot tornar upp sig över staden."}},faq={{q="Vem är Elaadrin Evengale?",a="Elaadrin Evengale är High Orders nuvarande Supreme Magister. Han leder deras verksamhet från en lodge i Valanaars sydöstra hörn och söker personer med magisk begåvning och beslutsamhet nog att skydda deras hem.",al={"vem är elaadrin evengale","elaadrin evengale","vem är supreme magister"}},{q="Var finns Elaadrin Evengale?",a="Elaadrin Evengale och hans följare håller till i en lodge längst i Valanaars sydöstra del.",al={"var finns supreme magister","var hittar man elaadrin evengale","var ligger lodgen i valanaar"}},{q="Vad är High Order?",a="High Order är en magisk organisation i Valanaar, ledd av Supreme Magister Elaadrin Evengale. De fokuserar på att använda magisk kraft för att försvara sitt hem, trots att de blir allt färre och spänningarna i trakten ökar.",al={"vad är high order","high orders historia"}},{q="Varför råder det konflikt mellan High Order och Windshapers?",a="High Order och Windshapers är bittra rivaler i Valanaar. De lokala ledarna insisterar på att hålla dem på långt avstånd från varandra för att förhindra öppet fraktionsvåld på gatorna, särskilt när sektens verksamhet hotar bosättningen.",al={"varför strider high order och windshapers","konflikten med windshapers","spänningar i valanaar"}},{q="Vem är Rathiril?",a="Rathiril är en medarbetare eller medlem som genom magiska meddelanden hänvisar lovande äventyrare i Valanaar till High Order och uppmärksammar Elaadrin Evengale på personer med stor potential.",al={"vem är rathiril","rathirils meddelande"}},{q="Vilken sekt hotar Valanaar?",a="En mystisk sekt är verksam kring Valanaar och utgör ett så stort hot att de lokala myndigheterna aktivt motverkar stridigheter mellan grupper som High Order och Windshapers för att hålla bosättningen trygg.",al={"vilken sekt finns i valanaar","sektens hot mot valanaar"}}},fp="20,192,26.282.0,32.298.0,25.178.0,37.84.0,23.227.0,65.198.0,16.163.0,29.190.0"}
P.entries["quest:927"] = {n="The Moss-twined Heart",s="Moss-twined Heart är en märklig, förvriden kärna från den monstruösa trädlingen Blackmoss the Fetid. Den är täckt av oljig, mörk mossa, men hjärtat fortsätter oroväckande nog att slå på egen hand. Det får botanisten Denalan vid Lake Al'Almeth att undersöka saken.",h="Moss-twined Heart är en märklig, förvriden kärna från den monstruösa trädlingen Blackmoss the Fetid.",kw={"blackmoss the fetid","farsot","förvridning","denalan","lake al'ameth","moss-twined heart","teldrassil","trädling"},ang={["class:Druid"]="Druider i Cenarion Circle intresserar sig starkt för avvikelser som det här pulserande, fördärvade hjärtat. De försöker avgöra om förvridningen kan renas bort eller om den visar på en djupare förruttnelse.",["profession:Herbalism"]="Varje växtkunnig kan se att den oljiga påväxten på den här kärnan är helt onaturlig. Den trotsar vanliga botaniska egenskaper genom att hålla ett avskuret hjärta vid liv.",["race:NightElf"]="För kaldorei är det ett allvarsamt tecken på att deras nya hem plågas av en krypande sjukdom att se hur det unga Världsträdet Teldrassil fostrar besmittade, aggressiva trädlingar som Blackmoss."},sec={{t="En pulserande kärna",b="Det här trädlinghjärtat har skurits ut ur resterna av Blackmoss the Fetid och är nästan oigenkännligt under ett lager mörk, oljig mossa. Det enda som avslöjar dess sanna natur är en långsam, rytmisk puls som fortsätter även efter att det skilts från varelsen. En sådan onaturlig uthållighet antyder att förvridningen som sprider sig bland Teldrassils vilda växtliv är långt mer omfattande än vanlig förruttnelse."},{t="Denalans undersökning",b="Denalan, en skarpsinnig forskare av traktens växter som håller till nära Lake Al'Almeth, inser genast hur allvarligt det är med föremålet. Trädlingar ska vara milda varelser, sammanflätade med Världsträdets grenar, men det här hjärtat visar tecken på en virulent förödande kraft. Denalan är både nyfiken och bekymrad och bestämmer sig för att plantera och studera det förvridna organet för att förstå den hemska mossan som slår rot i öns jord."}},faq={{q="Var kommer Moss-twined Heart ifrån?",a="Hjärtat tas från Blackmoss the Fetid, en stor och svårt förvriden trädling som strövar omkring i Teldrassils vildmark.",al={"var får jag tag på hjärtat","moss-twined heart byte","blackmoss the fetids hjärta"}},{q="Varför slår hjärtat fortfarande?",a="Den mörka, oljiga mossan som angripit trädlingen verkar hålla hjärtat vid liv med onaturlig kraft. Även när det skurits loss från varelsen behåller hjärtat sin långsamma, ihållande rytm.",al={"varför pulserar hjärtat","hjärta som fortfarande slår","trädlinghjärtats puls"}},{q="Vem är Denalan?",a="Denalan är en nattalv och naturkännare som sköter en plantskola nära Lake Al'Almeths stränder. Han ägnar sig åt att studera Teldrassils växter, groddar och den krypande förvridning som drabbar öns trädlingar.",al={"vem är denalan","var finns denalan","denalans plats"}},{q="Vad ska Denalan göra med hjärtat?",a="Denalan bestämmer sig för att plantera hjärtat i en förtrollad kruka så att det kan gro och han kan isolera den hemska mossan. Han hoppas kunna hitta grundorsaken till den fördärvade växtligheten.",al={"vad händer med hjärtat","uppdraget att plantera hjärtat","denalans hjärtforskning"}},{q="Vad ska trädlingar vara?",a="Trädlingar är naturligt fridsamma plantelementarer som föds ur skogen. Men i hela Teldrassil har mörka krafter och onaturlig besmittelse drivit många av dem till vansinne och gjort dem aggressiva.",al={"vad är trädlingar","trädlingars bakgrund","är trädlingar onda"}},{q="Är förvridningen i hjärtat magisk eller naturlig?",a="Mossan verkar hemsk och oljig snarare än frisk. Det tyder på en onaturlig farsot i Teldrassils inhemska ekosystem, inte vanlig nedbrytning i vildmarken.",al={"är mossan magisk","varifrån kommer den hemska mossan","teldrassils mossfarsot"}}},fp="21,166,14.241.0,21.405.0,43.120.0,31.138.0,15.184.0,36.156.0,36.158.0,50.119.0"}
P.entries["quest:92700"] = {n="The Grand Skyseer",s="The Grand Skyseer är en introducerande resa in i hjärtat av Valanaar, där resenärer uppmanas att söka audiens hos Ayessa Dawnsinger i Windshaper-lodgen. Medan spänningarna pyr mellan lokala fraktioner och en skum kult hotar regionen, söker Windshapers desperat personer med andlig synförmåga.",h="The Grand Skyseer är en introducerande resa in i hjärtat av Valanaar, där resenärer uppmanas att söka audiens...",kw={"ayessa dawnsinger","elder amberwind","high order","shen'dar village","skysight","the grand skyseer","valanaar","windshapers","zephras"},ang={["class:Druid"]="De som känner av andliga auror och naturens osedda flöde finner besläktade tankar hos Windshapers, som håller uppsikt över himlens subtila skiftningar.",["class:Shaman"]="Ayessa Dawnsinger känner genast igen resenärer som står i samklang med andarna och har andliga gåvor, vilket gör Windshapers till en viktig kontakt för schamaner i samklang med elementarkrafter."},sec={{t="Ankomsten till Valanaar",b="När resenärer anländer till staden Valanaar hänvisas de till den centrala lodgen, där Windshapers samlas under ledning av Grand Skyseer Ayessa Dawnsinger. Efter att ha väckt Elder Amberwinds uppmärksamhet genom anmärkningsvärda dåd i Shen'dar Village välkomnas nyanlända in bland dem som står i samklang med andarna. Men Valanaar är fortfarande fullt av yttre och inre faror, och nykomlingar måste navigera den bräckliga lokala politiken varsamt."},{t="Rivaliteter och hotande kulter",b="Freden i Valanaar är skör. Windshapers är öppet fientliga mot High Order, och gatustrider mellan fraktionerna hotar att destabilisera bosättningen. Eftersom en skum kult aktivt hotar regionen har lokala ledare beordrat båda fraktionerna att hålla avstånd och prioritera överlevnad mot gemensamma fiender framför bittra territoriella fejder."},{t="Den avtagande skysynen",b="Grand Skyseer Ayessa Dawnsinger ser att den andliga förmåga som kallas skysight blir allt ovanligare bland Zephras folk. De som anländer med en stark aura och andlig harmoni betraktas som oumbärliga allierade, i stort behov av att hjälpa Windshapers navigera de svåra tider som landet står inför."}},faq={{q="Vem är Grand Skyseer?",a="Grand Skyseer är Ayessa Dawnsinger, en framstående andlig ledare bland Windshapers i Valanaar. Hon håller till i lodgen nära bosättningens centrum och tar emot resenärer som står i samklang med andarna och har den sällsynta gåvan skysight.",al={"vem är grand skyseer","ayessa dawnsinger vem är hon","vem är ayessa"}},{q="Var finns Ayessa Dawnsinger?",a="Ayessa Dawnsinger finns i Windshaper-lodgen nära centrum av bosättningen Valanaar. Hon väntar på resenärer från Shen'dar Village som för med sig nyheter om nyliga dåd från Elder Amberwind.",al={"var finns ayessa dawnsinger","var ligger grand skyseers lodge","ayessas plats i valanaar"}},{q="Vilka är Windshapers?",a="Windshapers är en andlig sammanslutning i Valanaar, lokalt ledd av Grand Skyseer Ayessa Dawnsinger. Medlemmarna studerar himlen och samtalar med andarna, men befinner sig för närvarande i skarp konflikt med en annan lokal grupp som kallas High Order.",al={"vad är windshapers","windshaper-fraktionen i valanaar"}},{q="Varför är Windshapers i konflikt med High Order?",a="De två ordnarna är oense om vindandarna. High Order har blivit misstänksamma mot andarnas avsikter och vill själva förstå Skywalls krafter, medan Windshapers litar på elementarerna och ser sådana frågor som en förolämpning. Motsättningarna är så djupa att våld mellan fraktionerna på Valanaars gator inte kommer att tolereras, särskilt medan kulten hotar regionen.",al={"konflikten mellan windshapers och high order","varför är high order arg på windshapers","high order i valanaar"}},{q="Vad är gåvan skysight?",a="Skysight är en sällsynt andlig förmåga som bara ett fåtal individer i Zephras besitter. Den låter dem känna av andliga auror och kommunicera med osedda krafter. Ayessa Dawnsinger säger att allt färre har gåvan, vilket gör dem med skysight oumbärliga för att uthärda de nuvarande svårigheterna.",al={"vad är skysight","skysight-gåvan i zephras"}},{q="Vem är Elder Amberwind?",a="Elder Amberwind är en respekterad äldste i Shen'dar Village som bedömer resenärer och skickar besked till Valanaar om deras dåd och andliga samklang. Hen hänvisar värdiga personer till Grand Skyseer Ayessa Dawnsinger.",al={"vem är elder amberwind","amberwind i shendar village"}}},fp="17,185,19.340.0,27.313.0,19.244.0,25.226.0,37.185.0,24.199.0,49.292.0,29.232.0,23.222.0"}
P.entries["quest:92701"] = {n="To Valanaar",s="”To Valanaar” är ett leveransuppdrag med brådskande nyheter från byn Shen'dar till fredsbevararnas garnison i Valanaar. Det markerar en kritisk upptrappning på ön och varnar Commander Valennia Stormfist för att fredsbevararna inte längre kan undvika öppen konflikt med den snabbt växande kulten.",h="”To Valanaar” är ett leveransuppdrag med brådskande nyheter från byn Shen'dar till fredsbevararnas garnison i...",kw={"aonda","kult","fredsbevarare","pylon","shen'dar","to valanaar","valanaar","valennia stormfist"},sec={{t="Meddelande från Shen'dar",b="Efter försvaret av byn Shen'dar och dess viktiga pylon skickar höglandsbon Aonda en betrodd budbärare över ön. Målet är Valanaar, en bosättning på öns sydöstra spets, där de lokala fredsbevararnas befälhavare måste varnas för kultens snabba upptrappning."},{t="Stormen närmar sig",b="Under en tid har fredsbevararna under Valennia Stormfist försökt förhindra en öppen strid med den gåtfulla kult som tränger in på ön. Men händelserna i Shen'dar markerar en vändpunkt. Kultens inflytande växer snabbt, och Valennia tvingas inse att tiden då de kunde undvika strid är över. Hennes krympande skara fredsbevarare måste nu förbereda Valanaar på ett nära förestående anfall."}},faq={{q="Vem är Valennia Stormfist?",a="Valennia Stormfist är befälhavare för fredsbevararna på ön och verkar från bosättningen Valanaar. Hon ansvarar för att skydda lokalbefolkningen och märker hur den lilla garnisonen får allt svårare att räcka till när kultens aktivitet ökar i regionen.",al={"vem är valennia stormfist","valennia","fredsbevararnas ledare"}},{q="Vem är Aonda?",a="Aonda är en listig höglandsbo som håller till i byn Shen'dar. Efter att ha säkrat en lokal pylon och försvarat bosättningen mot kultens angrepp anförtror hon resenärer uppgiften att föra hennes skriftliga rapport över ön till Valennia.",al={"vem skickade rapporten","listig höglandsbo","aonda"}},{q="Vad är Valanaar?",a="Valanaar är en bosättning vid öns sydöstra spets. Den är huvudbas för Valennia Stormfist och de lokala fredsbevararna och fungerar som en försvarsbastion för öns invånare.",al={"vad är valanaar","var ligger valanaar","valanaars läge"}},{q="Vad hotar kulten ön med?",a="Ön hotas av en snabbt växande kult som har börjat tränga in i lokala bosättningar och heliga pyloner. Fredsbevararna har tidigare undvikit direkta strider, men kultens expansion tvingar nu Valanaar och dess försvarare att förbereda sig på en oundviklig kamp.",al={"vilken kult","vem anfaller","kultens expansion"}},{q="Vad är Shen'dar?",a="Shen'dar är en by nära en viktig pylon på ön. Efter att nyligen ha slagit tillbaka kultens angrepp och säkrat byn och pylonen har dess ledare nära kontakt med fredsbevararna i Valanaar.",al={"vad är shen'dar","shen'dar","by vid en pylon"}},{q="Vad står det i Aondas rapport?",a="Den skriftliga rapporten beskriver de senaste händelserna kring försvaret av Shen'dar och dess pylon. Den varnar Valennia för att kultens snabba territoriella expansion gör att en direkt konflikt inte längre kan undvikas.",al={"vad står i aondas rapport","den skriftliga rapportens innehåll","vad står det i brevet"}}},fp="11,154,22.249.0,19.303.0,26.173.0,13.170.0,17.143.0,40.200.0,17.194.0,36.162.0"}
P.entries["quest:92703"] = {n="Deliver the News",s="Deliver the News avslutar Windfield-familjens prövningar vid fruktodlingen i Skywall. Efter att ha hjälpt Aamelia att säkra gården beger sig The Adventurer till Valanaar för att berätta för den orolige Alvarion Windfield att familjen är i säkerhet.",h="Deliver the News avslutar Windfield-familjens prövningar vid fruktodlingen i Skywall.",kw={"aamelia","alvarion windfield","konstruktion","deliver the news","fruktodling","skywall","valanaar","windfield","vindformare"},ang={["race:Skyborne"]="Alvarion talar om verkliga hjältar ur berättelser från tiden innan folket kom till Skywall. Det påminner Skyborne-äventyrare om deras rötter och kulturarv före flytten."},sec={{t="Lättnad vid fruktodlingen",b="Deliver the News löser krisen vid Windfield-familjens fruktodling. Efter att ha räddat gården från en annalkande katastrof tackar Aamelia varmt och är redo att lämna faran bakom sig. Nu när fruktodlingen är säkrad blir det viktigast att lugna Alvarion Windfield, som flydde till bosättningen Valanaar för att be om hjälp."},{t="En hemlighet för framtiden",b="Innan Aamelia skickar resenären till Valanaar ber hon Alvarion att rekrytera en skicklig vindformare när han har återhämtat sig. En konstruktion finns kvar vid fruktodlingen, och hon vill att en expert undersöker den noggrant för att försäkra sig om att den inte utgör något hot. Hon delar också en öm hemlighet: hon väntar barn och vill hålla det hemligt för Alvarion tills han har återvänt hem i säkerhet."},{t="En hjälte i Valanaar",b="I Valanaar blir Alvarion Windfield överväldigad av känslor när han får veta att hans familj och hem är i säkerhet. Han hade begett sig till staden för att söka hjälp och trodde att det var ett desperat, nästan hopplöst försök. The Adventurers framgång påminner honom om de legendariska hjältar som omtalades innan hans folk kom till Skywall. Nu när hemmet är räddat hälsar familjen Windfield sin räddare välkommen för alltid."}},faq={{q="Vad är uppdraget Deliver the News?",a="Deliver the News är ett uppdrag som Aamelia ger efter att krisen vid Windfield-fruktodlingen är löst. Hon ber The Adventurer att resa till staden Valanaar och berätta för hennes partner Alvarion Windfield att faran är över och att hon är i säkerhet.",al={"uppdraget deliver the news","vad är deliver the news","vem ger deliver the news"}},{q="Vem är Alvarion Windfield?",a="Alvarion Windfield är en invånare i Skywall som återhämtar sig i Valanaar. Han reste till staden för att söka hjälp med problemen vid familjens fruktodling och trodde att allt hopp var ute innan han mötte spelaren.",al={"vem är alvarion windfield","var är alvarion","alvarions plats"}},{q="Vem är Aamelia?",a="Aamelia bor på Windfield-gården och sköter fruktodlingen tillsammans med Alvarion. Tacksam för spelarens ingripande ger hon dem i uppdrag att berätta för Alvarion i Valanaar att de har lyckats.",al={"vem är aamelia","uppdragsgivaren aamelia"}},{q="Vad håller Aamelia hemligt för Alvarion?",a="Aamelia berättar lågmält för The Adventurer att hon väntar barn. Hon rör varsamt vid magen och ber att få hålla nyheten hemlig för Alvarion tills han har återhämtat sig och kommit hem.",al={"vad är aamelias hemlighet","aamelia rör vid magen","är aamelia gravid"}},{q="Varför vill Aamelia att en vindformare kommer till fruktodlingen?",a="Aamelia vill att Alvarion tar med sig en vindformare tillbaka till fruktodlingen när han har återhämtat sig. Hon vill att specialisten undersöker en konstruktion på ägorna för att se till att den inte utgör någon fara för familjen som snart växer.",al={"varför konstruktionen och vindformaren","vilken konstruktion nämner aamelia","windfield-konstruktionen"}},{q="Var utspelar sig uppdraget?",a="Uppdraget knyter samman Windfield-fruktodlingen med bosättningen Valanaar, som ligger i det elementära riket Skywall där nybyggarna har slagit sig ner.",al={"var utspelar sig deliver the news","valanaar-uppdrag i skywall"}}},fp="16,125,21.196.0,23.287.1,18.337.0,35.135.0,26.168.0,15.161.0,44.134.0,58.181.0,33.126.0"}
P.entries["quest:92706"] = {n="WANTED: Bruuz",s="Bruuz hotar hamntrafiken som håller Ratchet i gång. Gazlowe har utlyst en belöning för den enorma hajen som stryker kring kajerna och stör kusthandeln.",h="Bruuz hotar hamntrafiken som håller Ratchet i gång.",kw={"the barrens","belöning","bruuz","ryggfena","gazlowe","ratchet","haj","steamwheedle"},ang={["class:Hunter"]="Som jägare kan du pröva ditt tålamod och din träffsäkerhet mot Bruuz, en enorm vattenpredator.",["profession:Cooking"]="Som kock skulle du kunna använda det färska kustköttet från en haj så stor som Bruuz. Gazlowe vill bara ha ryggfenan som bevis på att den dödats."},sec={{t="Skräck i bukten",b="Ratchet är den främsta neutrala förbindelsen mellan Kalimdor och Eastern Kingdoms, och handeln är beroende av handelsfartyg. På senare tid har en enorm haj vid namn Bruuz strukit omkring i bukten. Hamnarbetarna gav hajen dess namn efter att den började angripa småbåtar, sjömän och last som lossades nära kajerna. Dess närvaro stör hamnen och utsätter fartygen som försörjer Ratchet för fara."},{t="Gazlowes belöning",b="Gazlowe har utlyst en offentlig belöning för att hindra fartyg från att undvika hans hamn av rädsla för hajen. Efterlysningen vänder sig till fiskare och utlovar en rejäl belöning. För att göra anspråk på den måste du döda Bruuz och ta med hajens ryggfena som bevis."}},faq={{q="Vem är Bruuz?",a="Bruuz är en enorm, aggressiv haj som jagar nära Ratchets lastkajer. Hamnarbetarna gav den det namnet efter att den angripit sjömän och småfartyg.",al={"vad är bruuz","bruuz haj","vem är hajen bruuz"}},{q="Varför utlyste Gazlowe en belöning för Bruuz?",a="Bruuz stör sjöfarten och handeln som driver Ratchets ekonomi. Gazlowe erbjuder en kontant belöning för hajens kropp för att skydda verksamheten vid kajerna.",al={"varför döda bruuz","gazlowes hajuppdrag","varför vill gazlowe ha bruuz fena"}},{q="Var brukar Bruuz hålla till?",a="Bruuz stryker omkring i vattnen utanför Ratchet i The Barrens, ofta nära de största lastkajerna och hamninloppet.",al={"bruuz plats","var finns bruuz","hitta bruuz"}},{q="Vilket bevis kräver Gazlowe för dödandet?",a="Gazlowe kräver Bruuzs ryggfena som bevis på att hajen har dödats innan han betalar ut belöningen.",al={"lämna in bruuz","vad tar man med till gazlowe","bruuz ryggfena"}},{q="Kan både alliansens och hordens äventyrare ta sig an efterlysningen?",a="Ja. Ratchet styrs av det neutrala Steamwheedle Cartel, och Gazlowe välkomnar dugliga äventyrare från båda fraktionerna att ta hand om hajen.",al={"är wanted: bruuz neutral","kan horden göra wanted: bruuz","kan alliansen göra bruuz"}},{q="Varför riktar efterlysningen sig särskilt till fiskare?",a="Efterlysningen förklarar inte varför den vänder sig till fiskare. Den inleds med ”Alla fiskare sökes!” och utlovar en rejäl belöning för Bruuzs fena.",al={"alla fiskare sökes bruuz","är det här ett fiskeuppdrag"}}},fp="13,145,19.347.0,16.231.0,13.141.0,39.144.0,29.107.0,45.101.0,57.140.0,50.139.0"}
P.entries["quest:92708"] = {n="A Grand Adventure",s="A Grand Adventure markerar en vändpunkt för krisen på Zephras Isle i Skywall. Under ledning av Ayessa Dawnsinger och Windshapers skisseras en djärv plan för att rädda deras hem genom att resa ner till Azeroths dödliga värld.",h="A Grand Adventure markerar en vändpunkt för krisen på Zephras Isle i Skywall.",kw={"a grand adventure","ayessa dawnsinger","azeroth","skywall","vindandar","windshapers","zephras isle"},ang={["race:Skyborne"]="För Skywalls himmelsburna folk innebär detta en monumental perspektivförändring: de lämnar sitt hems elementära rike och beger sig ner till Azeroth för att söka räddning åt Zephras Isle."},sec={{t="Krisen på Zephras Isle",b="Zephras Isle står inför en växande kris då vindandar har försvunnit utan förklaring. Som svar har Windshapers undersökt dessa störningar och upptäckt oväntade sanningar om sina försvunna fränder och sitt elementära hems öde. Ayessa Dawnsinger söker dugliga äventyrare som kan ta till sig deras upptäckter och förbereda sig för ett aldrig tidigare skådat uppdrag."},{t="En färd bortom Skywall",b="När Ayessa Dawnsinger berättar om sina upptäckter avslöjar hon en djärv och okonventionell slutsats: Skywall ensamt har varken kraften eller kunskapen som krävs för att rädda Zephras Isle. Räddningen finns i stället nedanför, i Azeroths dödliga värld. Att färdas bortom deras hemland innebär ett djärvt brott mot traditionen och ber äventyrare att ge sig ut i det okända för att säkra öns framtid."}},faq={{q="Vad är uppdraget A Grand Adventure?",a="A Grand Adventure är ett avgörande uppdrag som Ayessa Dawnsinger ger på Zephras Isle. Där berättar hon om Windshapers slutsats: för att rädda deras hem måste de lämna Skywall och bege sig till Azeroth.",al={"vad är det här för uppdrag","uppdraget grand adventure","vad är a grand adventure"}},{q="Vem är Ayessa Dawnsinger?",a="Ayessa Dawnsinger är en viktig medlem av Windshapers på Zephras Isle. Hon undersöker krisen som hotar ön och föreslår en plan för att söka hjälp och kraft från Azeroth.",al={"vem är ayessa","dawnsinger","vem är ayessa dawnsinger"}},{q="Vilken kris pågår på Zephras Isle?",a="Zephras Isle drabbas av en allvarlig kris där vindandar har försvunnit. Windshapers har undersökt försvinnandena för att hitta ett sätt att rädda sitt hem.",al={"vad är krisen på zephras isle","vad hände på zephras isle","zephras problem"}},{q="Vilka är Windshapers?",a="Windshapers är en grupp på Zephras Isle som arbetar för att undersöka och lösa de elementära störningar och försvinnanden av vindandar som hotar ön.",al={"vilka är windshapers","windshapers zephras"}},{q="Varför måste Windshapers resa till Azeroth?",a="Ayessa Dawnsinger tror att kunskapen, den outnyttjade potentialen och kraften som krävs för att lösa krisen på Zephras Isle inte finns enbart i Skywall, utan måste sökas i världen nedanför, på Azeroth.",al={"varför resa till azeroth","varför lämna skywall","vägen till räddning"}},{q="Vad är Skywall?",a="Skywall är Windshapers och Zephras Isles elementära hemrike, beläget ovanför Azeroths dödliga värld.",al={"vad är skywall","var ligger skywall"}}},fp="17,165,26.318.0,24.283.1,36.158.0,25.150.0,44.145.0,24.95.0,49.142.0,16.107.0"}
P.entries["quest:92709"] = {n="A Grand Adventure",s="I Valanaar ber Elaadrin Evengale dig att lyssna på High Orders planer. Deras sökande efter uråldrig magi kan forma Zephras Isles framtid.",h="I Valanaar ber Elaadrin Evengale dig att lyssna på High Orders planer.",kw={"a grand adventure","uråldrig magi","elaadrin evengale","high order","highborne","kirin tor","valanaar","zephras isle"},sec={{t="Ett förlorat arv",b="Elaadrin talar om din härkomst som Highborne och de unga som kan hjälpa till att rädda sitt hem. High Order söker sina förfäders uråldriga magi och det som har gått förlorat under många årtusenden."},{t="Vägen framåt",b="Elaadrin säger att Azeroth är nyckeln till sökandet. Kirin Tor ska visa High Order vägen. Medan dess medlemmar förbereder sig för att ge sig av kan du tala med andra i Valanaar. Många behöver hjälp med sitt arbete."}},faq={{q="Vem ber mig att lyssna?",a="Elaadrin Evengale i Valanaar ber dig att lyssna på High Orders planer.",al={"vem är elaadrin","elaadrin evengale","vem vill prata"}},{q="Vad försöker High Order återupptäcka?",a="High Order söker sina förfäders uråldriga magi och det som gick förlorat under många årtusenden.",al={"vad letar de efter","uråldrig magi","high orders planer"}},{q="Varför söker High Order efter uråldrig magi?",a="Elaadrin säger att återupptäckten av uråldrig magi är nyckeln till att avslöja Zephras Isles hemligheter och trygga dess framtid.",al={"varför uråldrig magi","rädda zephras","öns framtid"}},{q="Vem ska visa dem vägen?",a="Elaadrin säger att Kirin Tor ska visa High Order vägen.",al={"kirin tor","vem vägleder dem","azeroth-planen"}},{q="Vad kan jag göra medan de förbereder sig för att ge sig av?",a="Medan de förbereder sig för att ge sig av kan du tala med andra medlemmar av High Order i Valanaar. De flesta behöver hjälp med sitt arbete.",al={"hjälp i valanaar","andra medlemmar i high order","vad händer sedan"}}},fp="17,139,15.193.0,13.195.1,27.72.0,44.90.0,43.111.0,27.61.0,42.124.0"}
P.entries["quest:92727"] = {n="The Missing Scholar",s="The Missing Scholar handlar om Fillion Flamebreezes försvinnande. Han var forskare vid High Order och skickades till Zephras för att undersöka atmosfärisk magi. Hans spår längs vägen mellan Valanaar och Shen'dar Highlands visar hur farliga forskningsresor över ön kan vara.",h="The Missing Scholar handlar om Fillion Flamebreezes försvinnande.",kw={"blodfläckad väska","fillion flamebreeze","high order","shen'dar highlands","the missing scholar","valanaar","vindburen magi","zephras"},ang={["class:Mage"]="Magiker som undersöker Zephras naturliga avvikelser delar Flamebreezes nyfikenhet på de vindburna, magiska strömmar som samlas i högländerna.",["race:Skyborne"]="Zephras vindar och atmosfäriska magi är av största intresse för Skyborne, men terrängens dolda faror utgör ett hot även mot forskare."},sec={{t="The High Order:s uppdrag",b="Att söka kunskap är den lärda orden High Orders främsta uppgift, men akademiskt fältarbete på Zephras har blivit allt farligare. När forskaren Fillion Flamebreeze gav sig av mot Shen'dar Highlands för att studera atmosfäriska, magiska fenomen rapporterade han aldrig tillbaka. Hans kollegor började befara att faror i området hade tagit honom längs gränsvägarna."},{t="Spår längs vägen i väster",b="Flamebreeze lämnade bosättningen Valanaar och begav sig västerut mot Shen'dar Highlands karga bergstrakter för att samla in empiriska uppgifter om vindburen magi som samlas bland topparna. Han försvann innan han nådde fram. En genomsökning av färdvägen hittar bara hans personliga väska kvar i smutsen, med stänk av intorkat blod. Det råder därför allvarliga tvivel om att han överlevde."}},faq={{q="Vem är Fillion Flamebreeze?",a="Fillion Flamebreeze är en forskare knuten till High Order på Zephras. Han skickades ut för att undersöka den mystiska vindburna magi som samlas i Shen'dar Highlands, men försvann sedan spårlöst längs vägen.",al={"vem är fillion flamebreeze","fillion flamebreeze bakgrund","vem är den försvunna forskaren"}},{q="Vad hände med Fillion Flamebreeze?",a="Fillion nådde aldrig fram. Längs vägen västerut mot Shen'dar Highlands finns bara hans övergivna väska kvar. Den har ett broderat namn och olycksbådande stänk av intorkat blod som tyder på att han överfölls eller attackerades.",al={"vad hände med fillion","dog fillion","fillion flamebreezes öde"}},{q="Vad är High Order?",a="High Order ägnar sig åt att samla in och bevara kunskap om Zephras. Trots sitt akademiska uppdrag har arbetet på ön blivit allt farligare på grund av vilda magiska fenomen och hot längs vägarna.",al={"high orders uppdrag","vad gör high order","high order zephras"}},{q="Varför reste Fillion till Shen'dar Highlands?",a="Flamebreeze reste till Shen'dar Highlands för att dokumentera och samla in uppgifter om ovanlig vindburen magi som samlas och strömmar genom vissa delar av det höglänta området.",al={"vart var fillion på väg","vindmagi shendar","varför reste han till högländerna"}},{q="Var sågs Fillion Flamebreeze senast?",a="Forskarens blodfläckade väska ligger längs vägen västerut från Valanaar, där den börjar stiga mot Shen'dar Highlands.",al={"var finns väskan","fillions väskas plats","vägen från valanaar"}},{q="Vad är den vindburna magin i Shen'dar Highlands?",a="Vindburen magi är atmosfäriska, magiska strömmar som naturligt samlas på vissa högt belägna platser på Zephras, särskilt i Shen'dar Highlands. Därför är de ett viktigt studieområde för magiker.",al={"vad är vindburen magi på zephras","vindmagi i högländerna"}}},fp="19,224,24.308.0,26.321.1,27.158.0,37.214.0,23.152.0,53.139.0,40.129.0,54.177.0"}
P.entries["quest:92741"] = {n="Unwelcome Visitors",s="Unwelcome Visitors är ett uppdrag i Valanaar som ges av Iaadaria Bitterwind på uppdrag av High Order. En plötslig ökning av shrieklingbeståndet i den farliga Shadowgale Forest hotar att sprida sig till omgivande områden. Äventyrare får i uppdrag att gå in i den avspärrade skogen, gallra bland bestarna och samla in deras klor för lärda studier och alkemisk forskning.",h="Unwelcome Visitors är ett uppdrag i Valanaar som ges av Iaadaria Bitterwind på uppdrag av High Order.",kw={"alkemiska egenskaper","iaadaria bitterwind","shadowgale forest","shriekling","shriekling talons","the high order","unwelcome visitors","valanaar"},ang={["class:Druid"]="Shrieklingarnas plötsliga explosionsartade ökning och utbredning visar på en ekologisk störning i Shadowgale Forest som kräver ett snabbt ingripande för att återställa den naturliga balansen.",["class:Hunter"]="Jägare är väl lämpade att spåra och minska det överbefolkade shrieklingbeståndet i Shadowgale Forest och ta på sig rollen som skogvaktare och fångstmän, något som High Order öppet föraktar."},sec={{t="Shrieklinginvasionen",b="Shadowgale Forest har länge ansetts vara ett farligt område där vanliga äventyrare inte får vistas. Men gränsen har börjat suddas ut. Skogens inhemska shrieklingar har blivit fler än någonsin och trängs nu mot skogsbrynet, redo att utvidga sina jaktmarker bortom trädkronorna. Om ingen hejdar dem riskerar rovbestarna att tränga in på bebodda marker och färdvägar. Då blir ett avskilt hot ett aktivt hot mot hela trakten."},{t="Vetenskaplig jakt",b="I Valanaar ser Iaadaria Bitterwind från High Order både faran och de vetenskapliga möjligheterna med angreppet. High Order brukar avstå från vardaglig skadedjursbekämpning och från att agera enkla fångstmän, men shrieklingklornas unika alkemiska egenskaper gör ett undantag värt besväret. Genom att anlita erfarna äventyrare för att bege sig in i Shadowgale Forest och säkra åtta klor skyddar Orden samhället och får samtidigt tag på sällsynta biologiska reagenser till sina studier."}},faq={{q="Vem ger uppdraget Unwelcome Visitors?",a="Unwelcome Visitors ges av Iaadaria Bitterwind, en forskare med anknytning till High Order som är stationerad i Valanaar. Hon ber dugliga resenärer att jaga shrieklingar i den närliggande vildmarken och samla material till hennes alkemiska studier.",al={"vem ger unwelcome visitors","uppdragsgivare för unwelcome visitors","var hämtar man unwelcome visitors"}},{q="Varför är High Order intresserade av shrieklingarna?",a="High Order anser i regel att fångst och skadedjursbekämpning ligger under deras värdighet, men Iaadaria Bitterwind ser en chans till vetenskaplig vinning. Shrieklingklor har särskilda alkemiska egenskaper, så Orden kan studera värdefulla reagenser och samtidigt låtsas hjälpa trakten.",al={"varför vill high order ha klor","high order och shrieklingar","iaadaria bitterwinds motiv"}},{q="Varför måste shrieklingbeståndet gallras?",a="Under de senaste månaderna har shrieklingarna i Shadowgale Forest ökat kraftigt i antal. När de blev fler började bestarna tränga utanför sitt vanliga skogsområde. Om spridningen inte hejdas utgör de ett växande hot mot närliggande områden.",al={"varför döda shrieklingar","hotet från shrieklingarna","varför är shrieklingar ett problem"}},{q="Var ligger Shadowgale Forest?",a="Shadowgale Forest är en förrädisk skog nära Valanaar. Den är känd för att vara ytterst farlig och brukar vara avspärrad för vanliga resenärer och oerfarna äventyrare på grund av det våldsamma djurlivet där.",al={"var ligger shadowgale forest","shadowgale forests läge","hur tar man sig till shadowgale forest"}},{q="Vad är shrieklingar?",a="Shrieklingar är våldsamma rovdjur som hör hemma i Shadowgale Forest. De har vassa klor med alkemisk kraft, och under de senaste månaderna har de förökat sig snabbt. De är tillräckligt aggressiva för att ta sig ut ur skogen och hota marker bortom sitt vanliga habitat.",al={"vad är en shriekling","shrieklingarnas historia","vad är shrieklingar för slags bestar"}},{q="Vilka föremål behövs för att slutföra Unwelcome Visitors?",a="Äventyrare som tar sig an Unwelcome Visitors måste bege sig in i Shadowgale Forests farliga djup, döda de talrika bestarna och hämta åtta Shriekling Talons. Troféerna lämnas direkt till Iaadaria Bitterwind i Valanaar för att hjälpa henne med hennes lärda studier och alkemiska forskning.",al={"målen med unwelcome visitors","vad behövs för unwelcome visitors","antal shrieklingklor som behövs"}},{q="Varför får vanliga äventyrare inte gå in i Shadowgale Forest?",a="Shadowgale Forest anses vara ytterst farlig och är officiellt avspärrad för vanliga äventyrare på grund av det dödliga djurlivet och den förrädiska miljön. Bara de som är beredda på stor fara vågar sig in i skogen, till exempel de som anlitats för att gallra bland de aggressiva shrieklingarna.",al={"varför är shadowgale avspärrad","faror i shadowgale forest","får vem som helst gå in i shadowgale forest"}}},fp="18,160,20.339.0,17.417.0,39.185.0,53.263.0,45.190.0,35.171.0,21.215.0,55.162.0,58.217.0"}
P.entries["quest:92742"] = {n="Testing the Wells",s="Alba Fairmoon skickar dig genom Westfall för att testa gårdarnas brunnar. Proverna kan avslöja vad som förgiftar jorden och grundvattnet.",h="Alba Fairmoon skickar dig genom Westfall för att testa gårdarnas brunnar.",kw={"alba fairmoon","grundvatten","the jansen stead","the molsen farm","gift","testing the wells","vattenprov","westfall"},ang={["class:Druid"]="Som druid inser du att onaturliga gifter i jord och färskt grundvatten skadar landets balans och kräver helande.",["faction:Alliance"]="Som medlem av Alliansen vet du att Westfalls gårdar måste producera mat för att Stormwinds kungarike ska överleva. Brunnarnas hälsa angår hela kungariket."},sec={{t="Förgiftning i grundvattnet",b="Alba Fairmoon ber dig testa grundvattnet i Westfall. Försummelse och banditdåd har redan skadat de öppna slätterna, och gift under jorden hotar den jordbruksmark som finns kvar. Du samlar prover från gårdsbrunnar så att Alba kan ta reda på vad som förorenar jorden och vattnet."},{t="Gårdar i gränslandet",b="Du tar prover från brunnarna vid The Jansen Stead och The Molsen Farm. Dessa gårdar ligger bland utspridda gårdar som hotas av Defiaslaglösa och vilda djur. Vattnet från deras brunnar kan visa om förgiftningen stiger upp ur marken, orsakas av magi eller medvetet har hällts i vattnet som försörjer regionen."}},faq={{q="Vad är syftet med Testing the Wells?",a="Alba Fairmoon vill ta reda på varifrån giftet som drabbar Westfall kommer och vad det är. Färska grundvattenprover från gårdsbrunnar låter henne undersöka föroreningen.",al={"varför testa brunnarna","målet med att testa brunnarna","vad går uppdraget ut på"}},{q="Vem ger dig uppdraget?",a="Alba Fairmoon ger dig uppdraget medan hon undersöker den utbredda korruptionen och de onaturliga gifterna i Westfall.",al={"vem ger uppdraget testing the wells","alba fairmoon uppdrag","uppdragsgivare"}},{q="Vilka platser ska provtas?",a="Du tar prover från brunnarna vid The Jansen Stead och The Molsen Farm i Westfall.",al={"vart ska jag gå","vilka brunnar","brunnarnas platser"}},{q="Vad hotar Westfalls vatten och jord?",a="En okänd förgiftning eller ett gift fördärvar Westfalls mark. Att testa brunnsvattnet är första steget mot att ta reda på om grundvattnet under gårdarna är förorenat.",al={"varför är westfall förgiftat","vad förgiftar marken","giftets källa"}},{q="Är föroreningen naturlig eller konstgjord?",a="Orsaken är ännu okänd. Prover från The Jansen Stead och The Molsen Farm kan visa om förruttnelsen kommer av naturlig förorening av grundvattnet eller av avsiktligt sabotage.",al={"är vattnet förgiftat med flit","vem förgiftade brunnarna"}},{q="Varför fokusera på The Jansen Stead och The Molsen Farm?",a="The Jansen Stead och The Molsen Farm är etablerade gårdar med brunnar som hämtar vatten från grundvattennivån under slätterna. Genom att testa dem kan man se hur långt föroreningen har spridit sig.",al={"varför jansen och molsen","varför dessa gårdar"}}},fx={["40e3ab69"]={q="Varför vill Alba Fairmoon att det här görs?",a="Alba Fairmoon försöker hitta källan till och den exakta karaktären hos giftet som förorenar Westfalls jord och grundvatten. Genom att analysera vatten direkt från brunnarna på gårdar i drift hoppas hon kunna fastställa vad som förstör landet innan föroreningen sprider sig bortom all räddning.",al={"varför alba vill ha vattenprover","alba fairmoons motiv","varför testa brunnarna"}},d6dffc38={q="Vad ska vattenprovet från The Jansen Stead användas till?",a="Det här provet ger Alba Fairmoon grundvatten direkt från The Jansen Stead. Genom att undersöka det tillsammans med prover från andra gårdar kan hon spåra om fördärvet sprider sig djupt ner i grundvattenmagasinen i Westfall eller läcker ut från en specifik lokal föroreningskälla.",al={"vad vattenprovet från the jansen stead används till","varför hämta vatten från the jansen stead","syftet med provet från the jansen stead"}},fcb7e3cb={q="Vad ska vattenprovet från The Molsen Farm användas till?",a="Det här vattnet, hämtat från brunnen vid The Molsen Farm, låter Alba Fairmoon undersöka hur omfattande föroreningen är på olika delar av Westfalls jordbruksmark. Genom att jämföra dess renhet med andra lokala brunnar kan hon bedöma hur giftet sprider sig och hur kraftigt det är.",al={"vad vattenprovet från the molsen farm används till","varför samla in prov från the molsen farm","syftet med vattnet från the molsen farm"}}},fp="17,131,21.270.0,21.268.0,41.155.0,22.110.0,35.65.0,46.164.0,43.167.0,42.182.0"}
P.entries["quest:92744"] = {n="Murloc Gills",s="Alba Fairmoon skickar hjälp från Alliansen till Longshore i Westfall för att samla murlocgälar. Hon oroar sig för att missväxten ska nå Stora havet, och gälarna kan visa om kustvattnen är förgiftade.",h="Alba Fairmoon skickar hjälp från Alliansen till Longshore i Westfall för att samla murlocgälar.",kw={"alba fairmoon","missväxt","svält","longshore","murloc gills","havsvatten","stormwind","gifter","westfall"},ang={["class:Druid"]="Missväxt som sprider sig från inlandet till kustens ekosystem hotar den inhemska faunan. Att övervaka inhemska indikatorarter som murlocs hjälper till att skydda mot den faran.",["faction:Alliance"]="Med kung Varian försvunnen och matbrist som underblåser oroligheter är det avgörande för Stormwinds stabilitet att skydda Westfalls återstående livsmedelsförsörjning.",["race:Human"]="För Stormwinds folk är Westfalls förfall ett omedelbart hot mot deras hem, jordbruk och matbord."},sec={{t="Ett hot mot kusten",b="Westfall är redan nära ruin, med sviktande skördar, bönder som drivits bort och banditer som strövar längs vägarna. Alba Fairmoon oroar sig för att missväxten ska sprida sig från åkrarna inåt landet till Stora havet. Om kusten är förgiftad kan fisken som mättar Westfalls fattiga och pryder borden i Stormwind City försvinna. Den förlusten kan driva ett redan hårt pressat kungarike rakt in i svält."},{t="Vattnets väktare",b="Murlocs är envisa och våldsamma, men deras amfibiska kroppar gör dem till naturliga tecken på vattnets kvalitet. Deras andning filtrerar ständigt havsvatten, vilket gör gälarna särskilt mottagliga för gifter, missväxt och onaturliga föroreningar. Alba Fairmoon hoppas kunna bedöma föroreningen genom att undersöka färska gälar från murlocs som stryker omkring vid Longshore."}},faq={{q="Varför vill Alba Fairmoon ha murlocgälar?",a="Alba Fairmoon vill ha murlocgälar för att ta reda på om Westfalls missväxt har nått havet. Murlocgälar fungerar som biologiska filter och visar snabbt spår av gifter eller föroreningar i havsvatten.",al={"varför murlocgälar","alba fairmoon murlocs","uppdragets syfte"}},{q="Var finns murlocs som hör till uppdraget?",a="Murlocs stryker omkring vid Longshore, stranden längs Westfalls västkust. De håller till i det grunda vattnet och på tidvattenslätterna bortom klipporna.",al={"var finns murlocs","murlocs vid longshore","plats för murlocgälar"}},{q="Vilken större fara hotar om havet förgiftas?",a="Westfall är Stormwinds främsta spannmålsbod, och skördarna inåt landet sviktar redan. Fisket längs kusten ger livsviktig mat. Om gifter förorenar havslivet längs kusten kan kungariket drabbas av oundviklig svält.",al={"varför spelar detta roll","risk för svält i westfall","hot mot stormwind"}},{q="Är murlocs särskilt mottagliga för sjukdomar?",a="Murlocs överlever hårda förhållanden, men deras amfibiska andningssystem reagerar omedelbart på kemiska eller magiska orenheter i vattnet. Därför är de användbara när man undersöker vattenburna föroreningar.",al={"murlocernas fysiologi","blir murlocs sjuka"}},{q="Har det här uppdraget någon koppling till Defias Brotherhood?",a="Defias Brotherhood har skapat kaos och lämnat jordbruksmark obrukad i stora delar av Westfall. Alba Fairmoons undersökning handlar i stället om ekologisk missväxt och om att skydda kungarikets livsmedelskällor.",al={"koppling till defias","är det här defias"}},{q="Vem är Alba Fairmoon?",a="Alba Fairmoon är en forskare från Alliansen i Westfall som håller uppsikt över missväxten och miljöförsämringen som hotar regionens jordbruk.",al={"vem är fairmoon","alba fairmoons historia"}}},fx={["853673a8"]={q="Vad ska Longshore Murloc Gill användas till?",a="Murlocs andas genom sina gälar när de stryker omkring i kustvattnen, vilket gör deras andningsvävnad känslig för allt som förorenar havet. Alba Fairmoon använder gälarna som biologiska testobjekt. Genom att undersöka vävnaden efter gifter kan hon avgöra om den märkliga förorening som förtorkar Westfalls jord och grödor också har börjat förgifta havet.",al={"vad murloc-gälar används till","varför samla in murloc-gälar","murloc-gälar från longshore"}},["4abd0ea3"]={q="Varför jagar du murlocs vid Longshore?",a="Murlocs lever längs Westfalls västkust och utsätts ständigt för tidvattnet och havsstänket. Eftersom deras vattenlevande kroppar filtrerar kustvattnet direkt genom gälarna ger prover från dem omedelbara biologiska bevis på om föroreningar har läckt från den drabbade jordbruksmarken ut i havet.",al={"varför murlocs","vilka är murlocs vid longshore","varför angripa murlocs"}}},fp="12,190,25.325.0,26.319.0,41.169.0,44.133.0,53.215.0,42.192.0,50.195.0,21.137.0"}
P.entries["quest:92745"] = {n="The State of the Mines",s="Alba Fairmoon hittar giftiga metaller i Westfalls brunnar och oroar sig för åkermarken. Hon misstänker gruvorna som Defias Brotherhood tagit över och varnar för att jorden kan bli obrukbar i årtionden. Du beger dig till Jangolode Mine och Gold Coast Quarry för att störa gruvdriften.",h="Alba Fairmoon hittar giftiga metaller i Westfalls brunnar och oroar sig för åkermarken.",kw={"alba fairmoon","defias","gold coast quarry","jangolode mine","koboldgrävare","gruvdrift","riverpaw","giftiga utsläpp","westfall"},ang={["class:Druid"]="Som druid möter du ett akut hot från metallgifter som sipprar ut i Westfalls slätter och kustekosystem.",["faction:Alliance"]="Som medlem i Alliansen vet du att Westfall hjälper till att försörja Stormwind med mat. Om Defias förstör dess åkermark kan kungariket drabbas av svält i åratal.",["profession:Mining"]="I Jangolode Mine och Gold Coast Quarry utvinner Defias mineraler utan större hänsyn till säkerheten eller gruvornas bärighet."},sec={{t="Förgiftad jord",b="Alba Fairmoon hittar farligt höga halter giftiga metaller i Westfalls brunnar. Regionen var en gång Stormwinds viktigaste spannmålsbod, men nu hotas dess grödor. Alba misstänker att gruvorna som Defias Brotherhood tagit över förgiftar vattnet. Om föroreningen fortsätter kan den omgivande jorden ligga ofruktbar i årtionden."},{t="Tvångsarbete och rekryterad arbetskraft",b="Defias låter lokala varelser arbeta tillsammans med sina stråtrövare och tömmer Westfall på dess resurser. Riverpaw-kobolder gräver efter sten och mineraler i Gold Coast Quarry, medan koboldgrävare tunnlar genom Jangolode Mine. Om du stör deras arbete försvagas Defias förmåga att bearbeta och distribuera förorenade mineraler."}},faq={{q="Varför läcker giftiga metaller ut från Westfalls gruvor?",a="Alba Fairmoon misstänker att gruvorna som Defias Brotherhood tagit över förorenar Westfalls grundvatten med giftiga metaller. Hon vill störa gruvarbetarna för att stoppa utsläppen.",al={"varför giftigt vatten westfall","gruvföroreningar westfall","giftiga utsläpp westfall"}},{q="Vem ligger bakom gruvdriften i Westfall?",a="Defias Brotherhood kontrollerar gruvdriften i Westfall. De har tagit över det forna kungarikets infrastruktur och låter Riverpaw-kobolder och kobolder utvinna mineraler.",al={"vem driver gruvorna","vem kontrollerar westfalls gruvor","defias gruvdrift"}},{q="Var arbetar Riverpaw-kobolderna och kobolderna?",a="Riverpaw-kobolder arbetar i Gold Coast Quarry vid Westfalls västra kust, medan koboldgrävare arbetar inne i Jangolode Mine i norr.",al={"var finns gruvarbetarna","gold coast quarry plats","jangolode mine plats"}},{q="Vem är Alba Fairmoon?",a="Alba Fairmoon undersöker Westfalls vatten och försöker skydda regionens åkermark från bestående skador.",al={"vem ger uppdraget gruvornas tillstånd","alba fairmoon bakgrund","uppdragsgivare"}},{q="Varför arbetar kobolder och kobolder för Defias?",a="Defias använder kobolder och kobolder som arbetskraft i de övertagna gruvorna. Alba säger inte hur arbetarna rekryterades.",al={"varför anlitar defias kobolder","kobolder som arbetar för defias"}},{q="Kan jorden i Westfall återhämta sig från föroreningen?",a="Alba Fairmoon säger att jorden kan återhämta sig om föroreningskällan stoppas snabbt. Om gruvdriften fortsätter kan marken förbli ofruktbar och förhärjad i årtionden.",al={"kan westfalls jord läka","kan grödor växa igen"}}},fx={f9d72c87={q="Varför vill Alba Fairmoon att gruvarbetarna dödas?",a="Vattenprover från de lokala brunnarna visade att farliga giftiga metaller sipprar ner i Westfalls jord. Alba Fairmoon vet att miljögiftet blir kvar och gör regionen ofruktbar och oförmögen att odla grödor i årtionden om den aggressiva dagbrottsbrytningen inte stoppas omedelbart.",al={"varför döda gruvarbetarna","alba fairmoons motiv","varför stoppa gruvbrytningen"}},["23ba5f2a"]={q="Vilka är gruvarbetarna i Jangolode Mine och Gold Coast Quarry?",a="Du skickas mot Kobold Diggers i Jangolode Mine och Riverpaw Miners i Gold Coast Quarry. De här varelserna arbetar inte för egen räkning, utan används som arbetskraft av Defias Brotherhood, som tog gruvorna för att skoningslöst utvinna Westfalls mineraltillgångar.",al={"vilka är gruvarbetarna","vem skickas jag att döda","kobold diggers och riverpaw miners"}}},fp="22,240,18.325.0,25.320.0,51.182.0,48.160.0,50.136.0,21.107.0,50.113.0,57.169.0"}
P.entries["quest:92747"] = {n="Moonbrook Espionage",s="Alba Fairmoon skickar dig för att spana på Moonbrook, där tecken på industri oroar Alliansen. Giftet som hittats i hela Westfall verkar inte komma från de mindre gruvorna, så blickarna vänds mot The Deadmines under staden.",h="Alba Fairmoon skickar dig för att spana på Moonbrook, där tecken på industri oroar Alliansen.",kw={"alba fairmoon","the deadmines","spioneri","industriförnödenheter","gruvor","moonbrook","gift","westfall"},ang={["class:Rogue"]="Som skurk kan du smyga genom Moonbrook och samla underrättelser om Defias verksamhet utan att väcka misstankar.",["faction:Alliance"]="Som medlem av Alliansen vet du att aktiv industri i Moonbrook hotar Westfalls kornbod och Stormwinds säkerhet.",["profession:Mining"]="Som gruvarbetare känner du till rikedomarna och den logistiska omfattningen hos de djupa schakten under Moonbrook."},sec={{t="Ett giftigt spår",b="Gruvorna som redan undersökts i hela Westfall ger inga svar om giftet som sprider sig genom regionen. Ingen känd gruvdrift ovan jord verkar vara källan. En stor plats återstår att utforska: The Deadmines vidsträckta schakt, direkt under Moonbrooks förstörda gator."},{t="The Deadmines hemligheter",b="Enligt uppgifter övergavs The Deadmines efter att Horden intog regionen under det första kriget. Ändå ligger modern industriutrustning och förnödenheter utspridda i Moonbrook. De tyder på en omfattande gruv- och tillverkningsverksamhet som döljs bakom den ruinerade stadens tomma yta."}},faq={{q="Vem ger uppdraget Moonbrook Espionage?",a="Alba Fairmoon ger dig i uppdrag att undersöka Moonbrook. Hon har granskat misstänkta gifter och industriell verksamhet i det omstridda Westfall.",al={"uppdragsgivare","vem ger moonbrook espionage","alba fairmoon"}},{q="Varför undersöker Alba Moonbrook?",a="De andra gruvorna i området visar inga tecken på att framställa giftet som Alba undersöker. Moonbrook ligger direkt ovanför The Deadmines, så hon misstänker en olaglig verksamhet under staden.",al={"varför moonbrook","vad finns i moonbrook","undersöka moonbrook"}},{q="Vad är The Deadmines?",a="The Deadmines är regionens djupaste och mest vidsträckta guldgruvor. De har betraktats som tomma ruiner sedan Stormwind föll under det första kriget, men det sägs att ohyra och banditer hemsöker dem.",al={"the deadmines historia","vad är the deadmines","deadmines historia"}},{q="Vilka föremål samlas in under spaningsuppdraget?",a="Spejare skickas för att hämta Suspicious Industrial Supplies som ligger utspridda i Moonbrook. Förnödenheterna tyder på aktiv industri och raffinering nära gruvschakten.",al={"suspicious industrial supplies","föremål i moonbrook espionage"}},{q="Vilka hot finns i Moonbrook just nu?",a="Defias Brotherhood har tagit över Moonbrook och använder dess förfallna byggnader som en främre samlingsplats. De vaktar ytans ingång till det underjordiska nätverket.",al={"fiender i moonbrook","vem kontrollerar moonbrook"}},{q="Vad bevisar fyndet av förnödenheterna?",a="Modern, tung industriutrustning i en stad som anses övergiven tyder på en samordnad fraktion som bedriver storskalig tillverkning utom räckhåll för Stormwinds myndigheter.",al={"vad betyder förnödenheterna","defias industri"}}},fp="19,209,13.271.0,24.282.1,32.144.0,36.181.0,23.198.0,53.167.0,40.161.0,39.175.0"}
P.entries["quest:92748"] = {n="Explosive Consultation",s="I Westfall förgiftar giftig industri under The Deadmines jordbruksmarken. Du beger dig till Dwarven District i Stormwind för att söka upp en ingenjör som kan skaffa kraftiga sprängämnen.",h="I Westfall förgiftar giftig industri under The Deadmines jordbruksmarken.",kw={"alba fairmoon","the deadmines","dwarven district","ingenjörskonst","explosive consultation","sprite jumpsprocket","stormwind","gifter","westfall"},ang={["faction:Alliance"]="Som medlem av Alliansen ser du hur Westfalls kämpande gränssamhällen är beroende av verkstäderna i Stormwinds Dwarven District.",["profession:Engineering"]="Som ingenjör vet du att rå styrka inte kan lösa Westfalls problem med förgiftad mark. Att slå ut stora underjordiska maskiner kräver specialiserad ammunition och noggrann teknisk skicklighet.",["race:Gnome"]="Som gnom bidrar du med teknisk uppfinningsrikedom som kan hjälpa till att neutralisera industriella hot under jord, bortom räckhåll för Alliansens reguljära styrkor."},sec={{t="En giftig källa",b="Westfall plågas av hemlösa på flykt och banditdåd under Defias Brotherhoods styre. Bevis från hela regionen tyder på ett samordnat, mekaniserat hot under jord. Industriavfall och frätande gifter förorenar marken, och spåren leder in i The Deadmines, där en organiserad verksamhet pågår under jord."},{t="Söker Stormwinds expertis",b="De befästa tunnlarna och maskineriet i The Deadmines kräver mer än vanliga vapen. För att hindra giftet från att nå Westfalls åkrar söker du hjälp i Stormwind Citys Dwarven District. Dånande smedjor, uppfinnare och handlare som säljer sprängpulver fyller stadsdelen. Där letar du efter Sprite Jumpsprocket, en ingenjör som kan ta fram sprängämnen för uppdraget."}},faq={{q="Varför behöver vi sprängämnen i The Deadmines?",a="Bevis från Westfall tyder på att en omfattande industriell verksamhet i The Deadmines producerar gifter som förorenar närliggande jordbruksmark. Kraftiga sprängämnen kan slå ut dess förstärkta maskineri.",al={"varför sprängämnen i the deadmines","varför behöver vi bomber","orsak till gifterna i the deadmines"}},{q="Vem ger uppdraget?",a="Alba Fairmoon skickar hjältar för att undersöka de onaturliga föroreningarna och oroligheterna som hotar Westfall.",al={"vem ger explosive consultation","starta explosive consultation"}},{q="Vem är Sprite Jumpsprocket?",a="Sprite Jumpsprocket är en gnomingenjör i Stormwinds Dwarven District. Hon arbetar med komplicerade mekaniska apparater och flyktiga ämnen och kan tillverka kraftfulla sprängladdningar.",al={"sprite jumpsprocket plats","vem är jumpsprocket"}},{q="Varför söka hjälp i Dwarven District?",a="Stormwinds Dwarven District är stadens industriella hjärta, med skickliga smeder, uppfinnare, sprängpulver och tekniska komponenter.",al={"varför dwarven district","stormwind och dwarven district"}},{q="Hjälper Stormwinds regering till med detta?",a="Eftersom kung Varian Wrynn är försvunnen och Adelsrådet tvekar att skicka reguljära militära garnisoner till Westfall, förlitar sig de lokala försvararna på frivilliga och privata hantverkare i huvudstaden i stället för reguljära arméregementen.",al={"hjälper armén till","varför ingenjör i stormwind"}}},fx={fe11cddb={q="Varför vill Alba Fairmoon att du letar efter sprängämnen?",a="Alba Fairmoon har hittat bevis på en omfattande industriell verksamhet djupt inne i The Deadmines. Hon har kopplat maskineriet under jord direkt till de vidriga gifter som förgiftar jorden och förstör odlingsmarken ovanför. Hon vet att en verksamhet av den här storleken inte kan monteras ner för hand, och vill därför ha kraftiga sprängämnen som kan förinta maskineriet som förorenar landsbygden innan skadorna blir oåterkalleliga.",al={"varför alba fairmoon behöver sprängämnen","alba fairmoons motiv","varför alba behöver sprängämnen"}}},fp="22,216,14.261.0,29.256.0,43.169.0,22.101.0,27.174.0,44.171.0,52.231.0"}
P.entries["quest:92749"] = {n="A Dynamite Plan",s="Sprite Jumpsprocket vill gärna använda dynamit i Stormwind. Den uppfinningsrika fixaren i Dwarven District har hört talas om industriellt sabotage och vill ha grov dynamit för att sätta sin plan i verket.",h="Sprite Jumpsprocket vill gärna använda dynamit i Stormwind.",kw={"grov dynamit","dwarven district","ingenjörskonst","sprängämnen","sabotage","sprite jumpsprocket","stormwind"},ang={["faction:Alliance"]="Som medlem i Alliansen upptäcker du Sprites explosiva plan innanför murarna i din huvudstad, Stormwind.",["profession:Engineering"]="Som ingenjör kan du tillverka grov dynamit av grovt sprängkrut och linnetyg. Det är ett enkelt prov på tidig pysslingsteknik.",["race:Gnome"]="Som gnom ser du hur Sprite Jumpsprocket möter komplicerade industriella problem med kluriga, explosiva uppfinningar."},sec={{t="Gnistor i Dwarven District",b="Sprite Jumpsprocket, en gnomisk ingenjör i Stormwinds Dwarven District, välkomnar prat om industriellt sabotage. I stället för att mana till försiktighet ber hon förbipasserande legosoldater att ta med ett knippe grov dynamit."},{t="Gnomiska ambitioner",b="Du kan tillverka grov dynamit vid en ingenjörsarbetsbänk eller byta till dig den av stadens hantverkare. Sprite ber om tio stavar, tillräckligt för att störa de industriella planer som tar form i de kringliggande områdena. Hennes plan visar de praktiska och farliga metoder som gnomer föredrar när de möter mekaniska och politiska störningar."}},faq={{q="Vem är Sprite Jumpsprocket?",a="Sprite Jumpsprocket är ingenjör i Dwarven District i Stormwind City, bland stadens smedjor och verkstäder. Hon ägnar sig åt djärva och oberäkneliga ingenjörsprojekt.",al={"sprite jumpsprocket","vem är sprite","uppdragsgivare"}},{q="Vad behöver Sprite till uppdraget?",a="Sprite behöver tio stavar grov dynamit. Du kan tillverka dem med ingenjörskonst eller skaffa dem genom handel eller auktionshuset.",al={"föremål till dynamitplanen","vad behöver jag","föremål som behövs"}},{q="Varför vill Sprite ha grov dynamit?",a="Pratet om industriellt sabotage har fångat Sprites intresse. Hon vill ha ett lager enkla sprängladdningar för att sätta igång.",al={"varför dynamit","dynamitens syfte","sabotagemotiv"}},{q="Var lämnar jag in uppdraget?",a="Sprite Jumpsprocket finns i Stormwind Citys Dwarven District.",al={"var lämnar jag in","inlämningsplats","sprites plats"}},{q="Måste jag kunna ingenjörskonst för att slutföra uppdraget?",a="Nej, du behöver inte kunna ingenjörskonst. Ingenjörer kan tillverka grov dynamit, och du kan också byta till dig den eller köpa den på auktionshuset.",al={"behöver jag ingenjörskonst","krav på ingenjörskonst","kan icke-ingenjörer göra det här"}},{q="Hur hänger det här ihop med oron kring Stormwind?",a="Sprite säger inte vad hon tänker sabotera. Hon visar bara sin iver att sätta igång med dynamit när industriellt sabotage kommer på tal.",al={"problem i stormwind","sabotage i westfall","lore om industriellt sabotage"}}},fx={dd094caa={q="Vad ska Coarse Dynamite användas till?",a="Sprite Jumpsprocket vill gärna ägna sig åt lite industrisabotage, och sprängkraft är central för planen. Coarse Dynamite ger den råa sprängkraft hon behöver för att störa maskindriften eller röja undan strukturella hinder inför sitt kommande företag.",al={"vad coarse dynamite används till","vad sprite behöver dynamit till","varför coarse dynamite"}}},fp="15,158,30.184.0,17.309.0,27.155.0,36.130.0,37.112.0,29.60.0,47.130.0,58.129.0"}
P.entries["quest:92750"] = {n="Detonation at a Distance",s="Sprite Jumpsprocket behöver ett säkrare sätt att utlösa sprängämnen, och svaret finns i Stormwind. Hon skickar dig till Stormwind Intelligence för att hämta en fjärrutlösare.",h="Sprite Jumpsprocket behöver ett säkrare sätt att utlösa sprängämnen, och svaret finns i Stormwind.",kw={"detonation at a distance","jasper fel","fjärrutlösare","si:7","sprite jumpsprocket","stormwind intelligence","westfall"},ang={["class:Rogue"]="Som rogue tar du dig in i hjärtat av SI:7:s verksamhet i Old Town, där människor utövar konsten att arbeta i hemlighet.",["profession:Engineering"]="Som ingenjör kan du tillverka stubiner och dynamit, men fjärrutlösare av militär kvalitet kommer ofta via kontakter som specialiserar sig på diskret sabotage.",["race:Gnome"]="Som gnom delar du Sprite Jumpsprockets intresse för ingenjörsproblem, men hon vänder sig till människornas underrättelsetjänst för spionammunition."},sec={{t="En kontrollerad explosion",b="Sprite Jumpsprocket vill utlösa sprängämnen på säkert avstånd. Gobliner och gnomer är kända för att hantera flyktiga kemikalier vårdslöst, men vissa sprängningar kräver försiktighet. En vanlig stubin kan utsätta den som tänder den för fara. Sprite vet att en kontrollerad explosion kräver en särskild utlösare, en sådan som vanliga uppfinnare inte har till hands."},{t="Kontakta SI:7",b="Sprite skickar dig till Stormwind Intelligence i Old Town i stället för till lokala dvärgsprängare eller vanliga ingenjörsleverantörer. Nätverket kallas SI:7, och dess hemliga agenter hanterar sabotage, smygoperationer och riktade sprängningar. Jasper Fel arbetar bland dem i huvudstaden och kan ordna diskret, farlig utrustning."}},faq={{q="Vem skickar dig på uppdraget?",a="Sprite Jumpsprocket, en gnomisk uppfinnare i Stormwinds Dwarven District, skickar dig för att hitta en fjärrutlösare.",al={"uppdragsgivare","vem startar detonation at a distance","sprite jumpsprocket uppdrag"}},{q="Vem behöver du prata med i Stormwind?",a="Sprite hänvisar dig till Jasper Fel, en medarbetare inom Stormwind Intelligence i Stormwind.",al={"var lämnar man in uppdraget","kontakt inom stormwind intelligence","jasper fels plats"}},{q="Varför behöver Sprite Jumpsprocket en fjärrutlösare?",a="Sprite vill utlösa sprängämnen på avstånd. En fjärrutlösare är mer praktisk än en okontrollerad explosion om du vill behålla armar och ben i behåll.",al={"varför fjärrutlösare","syftet med detonation"}},{q="Varför kontakta Stormwind Intelligence i stället för en ingenjör?",a="Stormwind Intelligence har specialiserad sabotageutrustning som vanliga handlare och fältuppfinnare varken lagerför eller säljer öppet.",al={"varför si:7","varför stormwind intelligence"}},{q="Var i Stormwind finns Jasper Fel?",a="Jasper Fel finns i Old Town, vid SI:7:s högkvarter där Stormwinds spioner och hemliga agenter arbetar.",al={"jasper fel stormwind","jasper fels rum"}},{q="Vilken fraktion kan utföra uppdraget?",a="Endast medlemmar i Alliance kan utföra det här arbetet, eftersom det kräver samarbete med Stormwinds kungliga underrättelseavdelning.",al={"är uppdraget bara för alliance","kan horde göra detta"}}},fx={be1ed035={q="Varför skickar Sprite Jumpsprocket dig till SI:7 i stället för att gå själv?",a="Sprite Jumpsprocket har ingen fjärrutlösare själv. Eftersom du vill ha en kontrollerad explosion som låter dig behålla armar och ben hänvisar hon dig till de listiga typerna på Stormwind Intelligence, som hon litar på kan hitta en. Uppdraget säger inte varför hon inte går själv.",al={"varför jag, sprite jumpsprocket","varför skicka spelaren till si:7","varför kan inte sprite åka till stormwind"}}},fp="24,124,18.229.0,21.299.0,30.108.0,40.84.0,53.136.0,59.133.0,41.95.0,37.125.0"}
P.entries["quest:92751"] = {n="Detonation at a Distance",s="I Moonbrook väcker explosioner under Westfall SI:7:s uppmärksamhet. Jasper Fel, en agent från Stormwind, skickar ett Remote Detonator Kit så att arbetet kan skötas på säkert avstånd.",h="I Moonbrook väcker explosioner under Westfall SI:7:s uppmärksamhet.",kw={"the deadmines","dwarven district","jasper fel","moonbrook","fjärrdetonator","si:7","sprite jumpsprocket","westfall"},ang={["class:Rogue"]="Som skurk ger mötet med Jasper Fel dig en inblick i SI:7:s hemliga nätverk, som håller uppsikt över agenter i fält och i tysthet förser dem med verktyg.",["faction:Alliance"]="Som medlem av Alliansen ser du hur Stormwind försöker återta Westfall med hemlig ingenjörskonst och underrättelsearbete i stället för öppen militär styrka.",["profession:Engineering"]="Som ingenjör kan du uppskatta en detonatorprototyp som utlöser laddningar på avstånd och undviker riskfyllda manuella stubiner vid sprängningar i grottor.",["race:Gnome"]="Som gnom visar Sprite Jumpsprockets arbete hur gnomisk ingenjörskonst förser Stormwinds spioner med prototyper."},sec={{t="Ögon i skuggorna",b="Jasper Fel och SI:7 håller uppsikt över händelser i Stormwinds områden, däribland den oroliga gränsen mot Westfall. När han får höra om sprängningsarbetet i Moonbrook vet Fel redan vad som pågår i de övergivna gruvgångarna under landsbygden."},{t="En prototyp till lösning",b="Explosioner i trånga grottor utsätter alla i närheten för fara. Jasper Fel tillhandahåller ett Remote Detonator Kit av prototypmodell, tillverkat av ingenjörer med band till Alliansen, så att sprängladdningar under Westfall kan utlösas utifrån. Han skickar dig med kitet till Sprite Jumpsprocket i Stormwinds Dwarven District och varnar dig för att nämna SI:7 för dina alvbundsförvanter."}},faq={{q="Vem är Jasper Fel?",a="Jasper Fel är agent vid Stormwinds underrättelsetjänst SI:7. Han håller utkik efter dolda hot i riket och tillhandahåller verktyg för att hantera dem.",al={"jasper fel","vem ger uppdraget detonation at a distance","uppdragsgivare"}},{q="Varför bryr sig SI:7 om Moonbrook?",a="Banditer och laglösa håller Moonbrook, vars yta leder ner till The Deadmines. Sprängningsarbetet djupt under Westfall har fångat Stormwinds underrättelsenäts uppmärksamhet.",al={"varför moonbrook","koppling till defias","grottor i westfall"}},{q="Vem är Sprite Jumpsprocket?",a="Sprite Jumpsprocket är en gnomingenjör i Stormwinds Dwarven District. Hon förbereder sprängämnen för rivningen.",al={"sprite jumpsprocket","vem tar emot detonatorn","npc att lämna in till"}},{q="Vem menar Jasper Fel med ”alvvännen”?",a="Jasper Fel syftar på Alba Fairmoon, alven som undersöker giftet i Westfall och skickade dig för att leta efter sprängämnen. SI:7 håller sitt direkta stöd hemligt för utomstående bundsförvanter.",al={"alvvän","berätta inte för alven","jasper fel alv"}},{q="Vad används Remote Detonator Kit till?",a="Remote Detonator Kit utlöser sprängladdningar på säkert avstånd, så att agenter kan röja eller rasa underjordiska passager utan att bli instängda där inne.",al={"fjärrdetonator","detonatorkit","vad gör kitet"}},{q="Vart tar det här uppdraget dig?",a="Du tar detonatorkitet till Sprite Jumpsprocket i Stormwind Citys Dwarven District.",al={"vart ska jag gå","uppdragsväg","inlämningsplats"}}},fx={dd5ef9f7={q="Varför hjälper Jasper Fel till med fjärrutlösaren?",a="Jasper Fel erbjuder ett avancerat prototypkit för utlösare till Sprite. Han ber dig hålla hans inblandning hemlig för din alvvän medan du hjälper till med den planerade sprängningen.",al={"jasper fels motiv","varför hjälpa till med utlösaren","varför ger jasper fel mig kitet"}},["2c859344"]={q="Varför ber Jasper Fel dig i stället för att sköta det själv?",a="Jasper Fel anförtror dig prototypkitet för utlösare till Sprite och ber dig hålla hans inblandning hemlig för din alvvän. Han förklarar inte varför han inte kan överlämna det själv.",al={"varför skicka mig","varför levererar inte jasper fel själv","varför inte si:7-agenter"}}},fp="24,179,19.243.0,20.334.1,18.154.0,35.165.0,27.120.0,44.162.0,42.162.0,31.88.0"}
P.entries["quest:92752"] = {n="Explosive Consultation",s="I Westfall skickar Sprite Jumpsprocket en instabil sprängladdning till Alba Fairmoon. Den armerade sprängladdningen måste nå henne säkert, med detonatorn orörd.",h="I Westfall skickar Sprite Jumpsprocket en instabil sprängladdning till Alba Fairmoon.",kw={"alba fairmoon","detonator","explosive consultation","sprängämnen","gnomisk ingenjörskonst","sprite jumpsprocket","westfall"},ang={["faction:Alliance"]="Som äventyrare för Alliansen ser du operatörer runt om i Westfall använda okonventionella vapen mot befästa banditläger och skenande maskiner.",["profession:Engineering"]="Som ingenjör känner du till riskerna med gnomisk ammunition: stor sprängkraft och en hårutlösande detonator.",["race:Gnome"]="Som gnom ser du Sprite Jumpsprocket ta med sig Gnomeregans explosiva lösningar till Westfalls hårt prövade front."},sec={{t="En explosiv leverans",b="Sprite Jumpsprocket har färdigställt ett knippe Extra-Destructive Explosives åt Alba Fairmoon. Att bära en skarp laddning genom ett krigshärjat Westfall gör en väg ännu farligare, redan hotad av Defias-banditer och vildsinta bestar."},{t="Varsam hantering",b="Sprite Jumpsprocket varnar dig för att vara försiktig med detonatorn. Lasten ska förstöra den dolda industriella verksamheten i The Deadmines, som förgiftar Westfalls odlingsmarker. Alba Fairmoon behöver sprängämnena oskadade innan hon kan använda dem."}},faq={{q="Vem ger uppdraget Explosive Consultation?",a="Sprite Jumpsprocket, en gnomisk uppfinnare i Stormwinds Dwarven District, ger dig sprängämnena att bära.",al={"vem ger explosive consultation","uppdragsgivare explosive consultation","sprite jumpsprockets uppdrag"}},{q="Vem tar emot sprängämnena när uppdraget är slutfört?",a="Alba Fairmoon i Westfall tar emot Extra-Destructive Explosives.",al={"vart ska jag ta sprängämnena","vem lämnar in explosive consultation","alba fairmoon sprängämnen"}},{q="Vilket föremål ska du transportera?",a="Du bär ett paket Extra-Destructive Explosives med en armerad, ömtålig detonator.",al={"vad lämnar sprite över","föremål i explosive consultation","vilken bomb är det här"}},{q="Varför behövs sprängämnen i Westfall?",a="Alba Fairmoon spårade gifterna som förorenar Westfalls odlingsmarker till en enorm industriell verksamhet gömd i The Deadmines. Hon sökte upp en ingenjör som kunde förse henne med sprängämnen kraftiga nog att förstöra den.",al={"varför behöver de bomber","syftet med sprängämnen i westfall","varför spränga saker i westfall"}},{q="Är uppdraget tillgängligt för Hordens äventyrare?",a="Nej. Sprite Jumpsprocket och Alba Fairmoon stöder Alliansens operationer, så bara Alliansens äventyrare kan ta sig an uppdraget.",al={"kan horden göra explosive consultation","horden explosive consultation"}},{q="Varnar Sprite Jumpsprocket dig för någon särskild fara?",a="Sprite Jumpsprocket varnar för att bomben är armerad och säger åt dig att hantera detonatorn ytterst varsamt under färden.",al={"sprites varning","bombvarning i westfall"}}},fx={bb434565={q="Varför vill Sprite Jumpsprocket att sprängämnena levereras till Alba?",a="Sprite Jumpsprocket har färdigställt de extra kraftiga sprängämnen som beställts för Alba Fairmoons arbete i Westfall. Efter att ha tillverkat den farliga lasten behöver Sprite en äventyrare som kan sköta den känsliga och riskfyllda transporten tillbaka till Alba, så att bomben kan användas som avsett.",al={"varför leverera sprängämnen till alba","sprite jumpsprockets motiv","varför tillverkade sprite bomben"}}},fp="22,151,19.237.0,18.246.0,44.105.0,52.68.0,43.86.0,38.190.0,45.117.0,60.121.0"}
P.entries["quest:92753"] = {n="Destruction in Deadmines",s="Djupt under Moonbrook förgiftar Defias industri marken. Alba Fairmoon misstänker att deras metallurgiska smedja är källan till förgiftningen och skickar dig att förstöra den med sprängämnen.",h="Djupt under Moonbrook förgiftar Defias industri marken.",kw={"alba fairmoon","the deadmines","defias brotherhood","extra-destructive explosives","metallurgisk smedja","moonbrook","sabotage","westfall"},ang={["faction:Alliance"]="När Defias smedja förstörs slår det mot maskineriet och vapnen som hotar Stormwinds suveränitet inifrån Westfall.",["profession:Engineering"]="Alba Fairmoon föreslår att använda särskilda Extra-Destructive Explosives mot tunga industrianläggningar för att undanröja den misstänkta föroreningskällan.",["profession:Mining"]="The Deadmines var en gång Stormwinds rikaste guld- och järngruvor. Defias har förvandlat dem till ett befäst smältverk som förgiftar jorden."},sec={{t="Sabotera gjuteriet",b="Under Moonbrook rymmer The Deadmines ett befäst komplex som driver Defias Brotherhood. Den tunga smedjan smälter metall och tillverkar maskiner. Alba Fairmoon tror att smedjan troligen är källan till föroreningen som plågar området. Hon vill förstöra den."},{t="En avgörande explosion",b="Smedjan ligger bakom barrikader, stråtrövare och gobliningenjörer. Du bär på Extra-Destructive Explosives och placerar dem intill smedjan. Sedan flyr du till kullarna ovanför Moonbrook, där Alba Fairmoon väntar på att detonera laddningen och hoppas att marken kan börja läka."}},faq={{q="Vad är målet med uppdraget?",a="Du ska ta dig in i The Deadmines under Moonbrook, hitta Defias Brotherhoods metallurgiska smedja och placera Extra-Destructive Explosives i närheten. Alba Fairmoon väntar vid utgången.",al={"uppdragsmål","vad ska jag göra","vad är destruction in deadmines"}},{q="Vem är Alba Fairmoon?",a="Alba Fairmoon är en agent för Alliansen i Westfall. Hon tror att förgiftningen och giftet i regionen kommer från tung smältning och industriellt arbete inne i The Deadmines.",al={"vem är alba","alba fairmoon bakgrund","uppdragsgivare"}},{q="Varför anses Defias smedja vara så farlig?",a="Alba misstänker att den stora metallurgiska smedjan i The Deadmines är källan till giftet. Hon hoppas att marken kan börja läka om den förstörs.",al={"varför förstöra smedjan","vad gör smedjan","gift från smedjan"}},{q="Var möter spelaren Alba efter att ha placerat sprängämnena?",a="Alba Fairmoon väntar i kullarna bakom Moonbrook, utanför The Deadmines nära gruvans övre utgång. Hon är redo att utlösa sprängämnena när du kommer ut i säkerhet.",al={"var väntar alba","var ligger utgången från the deadmines","var lämnar jag in uppdraget"}},{q="Var ligger smedjan i The Deadmines?",a="Smedjan ligger djupt inne i The Deadmines, bortom gruvgångarna i det industriella gjuteriet, där Defias-arbetare och goblinförmän arbetar.",al={"var ligger smedjan","smedjans läge i the deadmines","hitta smedjan"}},{q="Läker marken direkt när smedjan förstörs?",a="Alba hoppas att marken runt Moonbrook kan återhämta sig när den tunga smältningen upphör. Det kommer att ta tid att få bort spåren efter år av Defias-industri och försummelse.",al={"kommer marken att läka","upphör giftet","efterverkningar av smedjan"}}},fx={cfdfebff={q="Varför vill Alba Fairmoon att smedjan förstörs?",a="Alba tror att Defias-smedjan djupt inne i The Deadmines är den verkliga källan till den giftiga förorening som sipprar ut i den omgivande jorden. Genom att placera ut sprängämnen och krossa den enorma smältanläggningen hoppas hon kunna hejda fördärvet vid dess källa, så att Westfalls skadade jord äntligen kan börja återhämta sig.",al={"alba fairmoons motiv","varför förstöra smedjan i deadmines","varför vill alba att det här ska göras"}}},fp="24,177,22.263.0,16.278.1,33.180.0,21.167.0,48.146.0,62.163.0,48.141.0,52.146.0"}
P.entries["quest:928"] = {n="Crown of the Earth",s="Crown of the Earth är en övergångsresa som tar unga night elves från Shadowglen ut i Teldrassils större värld. Med heligt månbrunnsvatten, välsignat på toppen av Aldrassil, beger sig resenärerna söderut längs skogsvägen för att möta Corithras Moonrage i Dolanaar. Resan markerar steget från avskild träning till det brådskande försvaret av det stora världsträdet.",h="Crown of the Earth är en övergångsresa som tar unga night elves från Shadowglen ut i Teldrassils större värld.",kw={"aldrassil","corithras moonrage","crown of the earth","dolanaar","månbrunn","partially filled vessel","shadowglen","teldrassil","tenaron stormgrip"},ang={["class:Druid"]="När unga druider transporterar det helgade vattnet blir de en del av de pågående, sköra ansträngningarna att vårda och balansera Teldrassils växande ekosystem.",["class:Priest"]="Att bära månbrunnsvatten som helgats genom Elunes nåd står för hennes prästerskaps heliga plikt att värna samhällets andliga hälsa.",["race:NightElf"]="Steget utanför Shadowglens gräns är en viktig övergångsrit för varje ung Kaldorei som ger sig av för att tjäna sitt folk."},sec={{t="Lämna gläntan",b="Efter att ha visat sin hängivenhet genom att smaka på Shadowglens förtrollade månbrunnsvatten kallas de nya lärlingarna inför Tenaron Stormgrip vid Aldrassils krona. Tenaron ser att de är redo, förseglar det insamlade vattnet i ett större kärl och beordrar dem att bege sig bortom den skyddade gläntan. Vägen söderut mot Dolanaar är huvudleden ut ur Shadowglen och slingrar sig genom skogar som blivit alltmer oberäkneliga och fientliga."},{t="Vägen till Dolanaar",b="Dolanaar är den första större byn som resenärer möter när de lämnar startgläntan. Byn ligger längs kullerstensvägarna som slingrar sig genom centrala Teldrassil och sjuder av liv kring sin egen orörda månbrunn. Här väntar Corithras Moonrage, en äldste som har fått i uppgift att leda större bevarandeinsatser bland trädets grenar. Kärlet som överlämnas till honom knyter den unga äventyraren direkt till världsträdets större och oroliga öde."}},faq={{q="Vad bär jag till Dolanaar?",a="Du bär på Partially Filled Vessel, som innehåller helgat vatten från månbrunnen i Shadowglen. Tenaron Stormgrip hällde ditt första offer i kärlet så att Corithras Moonrage kan fortsätta ritualarbetet runtom i Teldrassil.",al={"vad är kärlet","lore om partially filled vessel","vad är det här för vatten"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en äldste bland night elves som håller till vid månbrunnen i Dolanaar. Han vägleder äventyrare som anländer och hjälper dem att fortsätta de viktiga riter och undersökningar som krävs för att vårda det nyväxta världsträdet.",al={"vem är corithras","corithras moonrages roll","var finns corithras"}},{q="Varför skickar Tenaron bort mig från Shadowglen?",a="Shadowglen erbjuder grundläggande träning, men utmaningarna som Teldrassil står inför kräver hjälp från hela trädet. När du har visat att du kan hantera lokala hot och vörda månbrunnarna skickar Tenaron dig till Dolanaar, där större uppgifter väntar.",al={"varför lämna shadowglen","varför bege sig till dolanaar","tenaron skickar bort mig"}},{q="Var ligger vägen till Dolanaar?",a="Följ kullerstensvägen söderut från Aldrassil och förbi Shadowglens portar. Fortsätt längs kullerstenen när stigen svänger söderut och västerut, tills du kommer fram till byn Dolanaar.",al={"hur tar man sig till dolanaar","vägen till dolanaar","vägen ut ur shadowglen"}},{q="Varför varnar Tenaron för farliga bestar?",a="Tenaron säger bara att farliga bestar har strövat omkring i skogarna på sistone. Även bland Teldrassils heliga grenar har djurlivet blivit aggressivt, så det innebär en verklig risk att lämna den stenlagda stigen.",al={"varför är bestar farliga","fördärvade bestar i teldrassil","varning om att hålla sig på vägen"}},{q="Vad händer när jag kommer till Dolanaar?",a="Corithras Moonrage tar emot kärlet och skickar dig för att fylla flaskor vid andra månbrunnar runtom i Teldrassil. På så sätt fortsätter du berättelsen om trädet.",al={"vad händer efter crown of the earth","nästa uppdrag i dolanaar","vad gör corithras"}}},fx={a4343de4={q="Varför skickar Tenaron Stormgrip en äventyrare i stället för att själv leverera kärlet?",a="Tenaron Stormgrip vakar över Aldrassils grenar och sköter de heliga angelägenheterna i Shadowglen, där unga nattalver först finslipar sina färdigheter. Han kan inte överge sina plikter uppe i det stora trädet bara för att bära budburet vatten tvärs över Teldrassil. Genom att skicka lovande noviser kan han pröva din disciplin och beredskap för den större världen, samtidigt som det heliga kärlet når Corithras Moonrage utan att Shadowglen lämnas obevakat.",al={"varför skicka mig","varför behöver tenaron mig","varför tar han inte kärlet själv"}}},fp="18,172,17.281.0,20.317.0,31.196.0,26.161.0,46.219.0,30.160.0,45.177.0,37.142.0"}
P.entries["quest:92812"] = {n="Economic Warfare",s="En Gelkis-kentaur ber dig samla in snidade totem från andra klaner. Sådana totem bär på berättelser och ger Gelkis mer makt att förhandla med Magram.",h="En Gelkis-kentaur ber dig samla in snidade totem från andra klaner.",kw={"byte","kentaur","desolace","ekonomisk krigföring","gelkis","magram","totem","handel"},sec={{t="Berättelser i byte",b="Gelkis håller fast vid en gammal kentaurtradition: klaner byter snidade totem som berättar om en persons eller klans stora bedrifter. Klanerna är fortfarande i konflikt, men hedrar ändå denna bytestradition. Du kan ge Gelkis totem från stupade kentaurer i andra klaner, så att de får mer att erbjuda i byte."},{t="Gelkis förråd",b="Gelkis lägger dina bidrag till sin samling, och deras makt växer. De har fortfarande långt kvar innan de kan besegra Magram Clan."}},faq={{q="Vad byter kentaurerna?",a="Kentaurklaner byter snidade totem som står för en individs eller klans stora bedrifter.",al={"kentaurernas bytesvaror","vad byts"}},{q="Varför är totemen viktiga för Gelkis?",a="Gelkis använder totemen som bytesmedel, och en större samling gör dem starkare.",al={"gelkis totem","totemens värde"}},{q="Byter kentaurerna fortfarande medan de strider?",a="Ja. Klanerna hedrar traditionen trots sin ständiga konflikt, även om tillfällena att byta har blivit få.",al={"kentaurklaner byter","byte under konflikt"}},{q="Vilken klan hoppas Gelkis besegra?",a="Gelkis hoppas besegra Magram Clan.",al={"gelkis fiende","magram clan"}}},fp="16,152,16.298.0,13.152.1,26.99.0,43.99.0,42.113.0,42.44.0"}
P.entries["quest:92819"] = {n="Destruction in Deadmines",s="I Westfall skickar Alba Fairmoon en agent för att förstöra Defias smedja i The Deadmines. Sprängämnena är redan utplacerade, och Alba väntar i kullarna bakom Moonbrook på fjärrutlösaren.",h="I Westfall skickar Alba Fairmoon en agent för att förstöra Defias smedja i The Deadmines.",kw={"alba fairmoon","the deadmines","defias","destruction in deadmines","detonator","sprängämnen","sabotage","westfall"},ang={["class:Rogue"]="Du infiltrerar fiendens område, placerar sprängladdningar och smiter undan före explosionen i denna hemliga sabotageaktion.",["faction:Alliance"]="Som medlem i Alliance bidrar varje slag mot Defias fäste till att skydda Westfalls kämpande gårdar och Stormwinds södra gräns.",["profession:Engineering"]="Uppdraget kretsar kring sprängningar och fjärrutlösta detonatorer, ett hantverk som kan tilltala ingenjörer."},sec={{t="Sabotage under Westfall",b="The Deadmines rymmer Defias Brotherhoods styrka under Westfall. Alba Fairmoon ger dig i uppdrag att sabotera smedjan som göms i gruvorna. Sprängämnena är redan utplacerade intill den, och du återvänder till Alba i kullarna bakom Moonbrook för att detonera dem på säkert avstånd. Hon hoppas att Westfalls förgiftade jord ska kunna börja läka när smedjan förstörts."},{t="Fjärrutlösaren",b="Laddningen ligger intill smedjan djupt inne i The Deadmines. Med en fjärrutlösare kan du detonera den utanför grottorna, efter att du återvänt till Alba Fairmoon i kullarna bakom Moonbrook. Hon hoppas att Westfalls förgiftade jord ska kunna börja läka när smedjan förstörts."}},faq={{q="Vem ger uppdraget Destruction in Deadmines?",a="Alba Fairmoon, en agent i Westfall, ger dig uppdraget och skickar dig mot Defias Brotherhoods fäste.",al={"vem ger destruction in deadmines","uppdragsgivare för detonering i deadmines","alba fairmoon-uppdrag"}},{q="Vad är uppdragets främsta mål?",a="Du detonerar sprängämnena som placerats intill Defias smedja i The Deadmines med fjärrutlösaren från utsidan av gruvorna, efter att du återvänt till Alba Fairmoon.",al={"vad gör man i destruction in deadmines","målet med destruction in deadmines","hur slutför man destruction in deadmines"}},{q="Varför angriper man The Deadmines med sprängämnen?",a="Alba Fairmoon spårade giftet i Westfalls åkermark till en stor metallurgisk smedja gömd i The Deadmines. Hon hoppas att marken ska kunna börja läka när den förstörs.",al={"varför spränga deadmines","deadmines-sabotagets bakgrund","varför använda detonator i deadmines"}},{q="Var utspelar sig uppdraget?",a="När sprängämnena har placerats återvänder du till Alba Fairmoon i kullarna bakom Moonbrook, utanför The Deadmines.",al={"destruction in deadmines-plats","var ligger destruction in deadmines","var ligger detonatorn i deadmines"}},{q="Är det här uppdraget tillgängligt för Horde-spelare?",a="Nej. Alba Fairmoon arbetar med Alliance-agenter som försvarar Westfall mot Defias Brotherhood.",al={"är destruction in deadmines bara för alliance","kan horde göra destruction in deadmines"}},{q="Vilket hot utgör Defias Brotherhood i Westfall?",a="Defias Brotherhood drev bort bönder, plundrade bosättningar och tog över Westfalls övergivna gruvor. Djupt inne i The Deadmines bygger de upp ett väpnat uppror som hotar Stormwinds kungarike.",al={"defias bakgrund i westfall","varför bekämpa defias","vad gör defias i deadmines"}}},fp="24,158,25.344.0,13.261.0,46.95.0,46.145.0,41.169.0,33.115.0,43.99.0,57.209.0"}
P.entries["quest:92834"] = {n="Avenged Tenfold",s="Avenged Tenfold handlar om Elaadrin, en lärd i High Order som försökte få slut på ett utbrott av kultvåld genom fredliga förhandlingar. När kulten Al'Aketh brutalt styckade hans sändebud och kära vän Belathaan Brightwish övergav Elaadrin diplomatin och valde snabb, magisk vedergällning mot kultisterna norr om Valanaar.",h="Avenged Tenfold handlar om Elaadrin, en lärd i High Order som försökte få slut på ett utbrott av kultvåld...",kw={"al'aketh","avenged tenfold","belathaan brightwish","elaadrin","gustberry fields","high order","shrine of akir","windshapers","windstone charms"},ang={["class:Mage"]="När Elaadrin provoceras kanaliserar han sprakande arkan kraft, vilket visar att High Orders hängivenhet till logik backas upp av en formidabel magisk styrka."},sec={{t="Det diplomatiska försöket",b="När kulten Al'Aketh inledde sin våldsamma kampanj svarade grupper som Peacekeepers och Windshapers med väpnad kraftmätning. Elaadrin, som företrädde High Order, såg sådana aggressiva uppvisningar som en dåraktig upptrappning. Han höll fast vid High Orders pragmatiska principer och vilja att undvika konflikter, trodde att ett förnuftigt samtal fortfarande var möjligt och skickade sin nära vän Belathaan Brightwish till Shrine of Akir för att förhandla om fred."},{t="Ett makabert avslag",b="Kulten svarade på Elaadrins diplomatiska försök med fruktansvärd brutalitet. Ett paket anlände med Belathaans avskurna tunga, täckt av silverpigment. Förfärad och tyngd av skuld insåg Elaadrin att det hade kostat hans kära vän livet att välja den fredliga vägen. Han medgav att Windshapers hade rätt när de avvisade förhandlingar, övergav all diplomati och beordrade resenärer att jaga kultisterna genom Gustberry Fields och vid Shrine of Akir och samla in deras Al'Aketh Windstone Charms."},{t="Försiktighet och arkan vrede",b="High Order sätter logik framför känslor och resonerar att det nästan alltid är klokast att undvika blodsutgjutelse. Men Elaadrin visar att kall logik kan slå åt båda hållen när motståndare misstar återhållsamhet för hjälplöshet. Med sprakande arkan energi omkring sig gör han klart att High Order föredrar fred, men att de som styckar deras sändebud kommer att mötas av överväldigande vedergällning."}},faq={{q="Vem är Elaadrin?",a="Elaadrin företräder High Order och försökte först nå en fredlig diplomatisk lösning med kulten Al'Aketh. När hans sändebud och nära vän Belathaan Brightwish mördades övergav Elaadrin diplomatin och beordrade att kultisterna skulle förgöras.",al={"vem är elaadrin","uppdragsgivare avenged tenfold","vem ger det här uppdraget"}},{q="Vad hände med Belathaan Brightwish?",a="Belathaan Brightwish var en nära vän till Elaadrin, som skickades som sändebud till Shrine of Akir för att inleda en fredlig dialog med kulten Al'Aketh. Kulten mördade honom brutalt och skickade tillbaka en låda med hans avskurna tunga, målad med silverpigment, till Elaadrin.",al={"vad hände med belathaan","vem är belathaan brightwish","varför dog belathaan"}},{q="Vilka är kultisterna i Al'Aketh?",a="Al'Aketh är en våldsam kult som verkar norr om Valanaar, kring Gustberry Fields och Shrine of Akir. De bär böneamuletter som kallas Al'Aketh Windstone Charms och avvisar utomståendes fredliga försök med våld.",al={"vilka är alaketh","vilka är kultisterna","al'aketh-kulten"}},{q="Vad är High Order?",a="High Order är en organisation som är stolt över sin pragmatism, sitt intellekt och sin logik. De anser i allmänhet att det klokaste är att undvika konflikter och värna om liv, men de kan ta till kraftfull magisk vedergällning när någon går dem emot.",al={"vad är high order","high orders övertygelser"}},{q="Vilka är Windshapers?",a="Windshapers och Peacekeepers är grupper som först svarade på kulten Al'Akeths våld med styrkedemonstrationer och maktspel. Elaadrin kritiserade till en början deras agerande som en vårdslös upptrappning, men medgav till sist att de hade rätt i att avvisa diplomatiska vädjanden.",al={"vilka är windshapers","windshapers och peacekeepers"}},{q="Var finns kultisterna i Al'Aketh?",a="Kultisterna i Al'Aketh samlas norr om Valanaar, särskilt i Gustberry Fields och kring Shrine of Akir, dit Belathaan Brightwish skickades före sin död.",al={"var ligger shrine of akir","var ligger gustberry fields","var finns kultisterna"}}},fp="15,227,23.376.0,20.443.1,25.341.0,16.209.0,38.249.0,30.223.0,23.186.0,24.239.0,38.164.0"}
P.entries["quest:92840"] = {n="Catching Wind",s="Catching Wind är en expedition från High Order till Overlook Standing Stones i Shen'dar Highlands. Med ett Index Esoteria skickas en agent för att mäta elementarkraften i forntida vindstensformationer, trots Windshapers häftiga och våldsamma protester.",h="Catching Wind är en expedition från High Order till Overlook Standing Stones i Shen'dar Highlands.",kw={"al'aketh","catching wind","fillion","high order","index esoteria","overlook standing stones","shen'dar highlands","valanaar","windshapers","vindstensformationer","zephras"},ang={["class:Mage"]="Magiker och lärda inom arkana uppskattar Index Esoterias analytiska funktion och ser elementarfenomen som mätbara fält för arkan forskning.",["class:Shaman"]="Schamaner kan slitas mellan Windshapers vördnad för elementarströmmarna och High Orders kliniska utvinning av rå elementarkraft."},sec={{t="Att mäta stormvindarna",b="High Order vill mäta och förstå de kaotiska elementarflöden som strömmar genom Shen'dar Highlands. För att låsa upp hemligheterna i Overlook Standing Stones skapade forskare Index Esoteria, ett precisionsinstrument avsett att samla in data från enorma vindstensformationer. High Order beskriver arbetet som livsviktig forskning som krävs för att rädda Zephras, medan lokala traditionalister ser dessa akademiska undersökningar som vanhelgande intrång i vindens domäner."},{t="Dogm mot undersökning",b="Spänningarna mellan expeditionen från High Order och Windshapers blossar snabbt upp vid stenarna. Windshapers ser studiet och utvinningen av elementarkrafter som en ren skändning av sina heliga traditioner. High Order anser att Windshapers är lika dogmatiskt trångsynta som de våldsamma Al'Aketh och vägrar låta det lokala motståndet stoppa uppdraget att rädda riket."},{t="Massakern vid de resta stenarna",b="När arbetet från High Order vid Overlook Standing Stones möter fientligt motstånd blir våld oundvikligt. Sammandrabbningen spiller blod bland vindstenarna. High Order lyckas säkra sina mätvärden med Index Esoteria, men Windshapers fördömer händelsen som en massaker, vilket förvärrar en bitter fejd som kastar sin skugga över staden Valanaar."}},faq={{q="Vad handlar uppdraget Catching Wind om?",a="Catching Wind är ett uppdrag på High Orders vägnar för att studera elementarkraften kring Overlook Standing Stones i Shen'dar Highlands. En äventyrare får i uppgift att bära ett Index Esoteria och samla in viktiga data från enorma vindstensformationer trots Windshapers fientliga motstånd.",al={"vad är catching wind","uppdraget catching wind"}},{q="Vad är ett Index Esoteria?",a="Index Esoteria är ett specialiserat mätinstrument som används av High Order. Det är utformat för att samla in, mäta och registrera data om elementarkraft direkt från de enorma vindstensformationerna vid Overlook Standing Stones.",al={"vad är index esoteria","index esoteria instrument"}},{q="Vilka är Windshapers?",a="Windshapers är en fraktion som värnar om sina heliga platser och traditionella trosföreställningar om elementarmagi. De ser High Orders akademiska forskning och tekniska apparater som en skändning och försvarar aggressivt vindstensformationerna mot utomstående intrång.",al={"vilka är windshapers","windshapers historia"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är en öppet våldsam grupp som High Order nämner tillsammans med Windshapers. High Order säger att Al'Aketh är den mer öppet våldsamma av de två grupperna, men ser båda fraktionerna som farliga fanatiker bundna till felaktiga och orubbliga dogmer.",al={"vilka är al'aketh","al'aketh"}},{q="Var ligger Overlook Standing Stones?",a="Overlook Standing Stones ligger i Shen'dar Highlands. Platsen är känd för sina enorma vindstensformationer som leder starka elementarströmmar, vilket gör den till en viktig forskningsplats för High Order.",al={"var ligger overlook standing stones","overlook standing stones plats"}},{q="Vem är Fillion?",a="Fillion är en agent eller forskare från High Order som ursprungligen skickades till Overlook Standing Stones för att mäta och studera elementarkraften. Konfrontationen med Windshapers gjorde det nödvändigt att skicka en äventyrare med Index Esoteria för att säkra uppgifterna.",al={"vad hände med fillion","vem är fillion"}},{q="Varför behöver High Order data om vindstenarna?",a="High Order anser att kunskap om rikets elementarkrafter är avgörande för deras övergripande uppdrag att rädda Zephras. De ser vetenskapliga undersökningar som nödvändiga för att övervinna elementarhot som traditionella trosföreställningar inte kan lösa.",al={"varför vill high order ha data","rädda zephras"}}},fp="13,177,19.306.0,26.322.0,27.272.1,38.234.0,26.168.0,24.199.0,21.205.0,47.183.0,15.231.0,48.184.0"}
P.entries["quest:92849"] = {n="The Missing Scholar",s="The Missing Scholar följer sökandet efter Fillion Flamebreeze, en forskare som försvann på vägen tillbaka från ett uppdrag vid Overlook Standing Stones. Spåren leder till en närliggande grotta i norr, dit Fillion släpades av ett rovlystet bevingat odjur.",h="The Missing Scholar följer sökandet efter Fillion Flamebreeze, en forskare som försvann på vägen tillbaka...",kw={"fillion","fillion flamebreeze","overlook standing stones","the missing scholar","windshapers","bevingat odjur"},sec={{t="Den försvunna forskaren",b="Tecken på olycka längs vägen tyder på att forskaren Fillion Flamebreeze utsattes för ett överfall under sin resa. Spåren efter hans försvinnande leder norrut mot mynningen av en mörk grotta, där den försvunna forskaren kanske fortfarande klamrar sig fast vid livet och väntar på hjälp."},{t="Överfall av Windshapers",b="Fillion Flamebreeze var på väg tillbaka från ett forskningsuppdrag vid Overlook Standing Stones när fientliga Windshapers överföll honom. Angriparna misshandlade honom skoningslöst, släpade honom sedan till grottmynningen och lämnade honom att förblöda, helt hjälplös inför vad som än lurade därinne."},{t="Det bevingade odjurets håla",b="Medan Fillion låg döende vid grottans tröskel kom ett enormt bevingat odjur fram ur mörkret och släpade in honom. Odjuret förde honom djupt in i sitt näste som byte åt sina ungar, ett grymt öde som bara avvärjdes tack vare en räddning i sista stund."}},faq={{q="Vem är Fillion Flamebreeze?",a="Fillion Flamebreeze är en forskare som var på väg tillbaka från ett uppdrag vid Overlook Standing Stones när fientliga Windshapers överföll honom. Blödande och medvetslös utanför en närliggande grotta släpades han in av ett enormt bevingat rovdjur.",al={"vem är fillion","fillion flamebreeze","försvunnen forskare npc"}},{q="Vad gjorde Fillion vid Overlook Standing Stones?",a="Overlook Standing Stones var platsen för Fillion Flamebreezes forskningsuppdrag före överfallet. Det är oklart exakt vad han forskade om där, men hans väg tillbaka från stenarna ledde rakt in i Windshapers överfall.",al={"vad är overlook standing stones","uppdrag vid overlook standing stones","fillions uppdrag"}},{q="Vem attackerade Fillion Flamebreeze?",a="Fillion överfölls och misshandlades av angripare som kallas Windshapers. I stället för att döda honom direkt tvingade de honom till mynningen av en närliggande grotta och lämnade honom där, blödande och knappt vid medvetande.",al={"vem attackerade fillion","vad är windshapers","windshapers överfall"}},{q="Vilket odjur tog in Fillion i grottan?",a="Ett enormt bevingat odjur som hade sitt bo i grottan norr om överfallsplatsen plockade upp en medvetslös Fillion vid grottmynningen. Det släpade honom djupt in i sitt näste för att föda sig självt och sina hungriga ungar.",al={"vilket grottodjur","bevingat monster fillion","vad tog fillion"}},{q="Var kan Fillion Flamebreeze hittas?",a="Ledtrådar vid platsen för hans olycka pekar mot en grotta strax norrut. Om du söker igenom grottan hittar du Fillion fångad i odjurets häckningsplats, där han väntar på att bli räddad innan han blir uppäten.",al={"hur hittar man fillion","var är den försvunne forskaren","fillions grottplats"}},{q="Vad blev den försvunne forskarens öde?",a="Fillion överlever prövningen tack vare ett ingripande i sista stund i grottan. Om en äventyrare inte hade spårat upp honom och ingripit skulle han ha blivit middag åt det bevingade odjuret och dess avkomma.",al={"överlevde fillion","vad händer med fillion flamebreeze","rädda den försvunne forskaren"}}},fp="19,179,23.215.0,25.234.1,24.217.1,27.237.0,55.204.0,33.144.0,41.165.0,39.186.0,41.190.0"}
P.entries["quest:92850"] = {n="The Missing Scholar",s="The Missing Scholar är ett uppdrag där äventyrare hjälper forskaren Fillion Flamebreeze efter att ha hittat honom nära ett farligt näste. När Fillion återvänder oskadd till Valanaar ger han resenärer i uppdrag att döda den närbelägna Shriekling Matriarch, som hotar bosättningen.",h="The Missing Scholar är ett uppdrag där äventyrare hjälper forskaren Fillion Flamebreeze efter att ha hittat...",kw={"fillion flamebreeze","shriekling","shriekling den","shriekling matriarch","supreme magister","the missing scholar","valanaar"},ang={["class:Mage"]="Fillion Flamebreeze förlitar sig på sin egen träning i de arkana konsterna för att återhämta sig och resa tryggt, vilket visar på en samhörighet med andra som utövar magi."},sec={{t="En farlig häckningsplats",b="Efter att ha återhämtat sig från sin prövning nära ett näste med rovdjur kan forskaren Fillion Flamebreeze resa tillbaka mot tryggheten i Valanaar. Men det omedelbara hotet kan inte ignoreras: en kull shrieklings har byggt ett näste oroväckande nära bosättningen. I stället för att låta bestarna dröja kvar vid stadens tröskel ber Flamebreeze dugliga resenärer att ta sig in i Shriekling Den och döda Shriekling Matriarch."},{t="Rapport till magistern",b="När Matriarch är dödad och hennes huvud har lämnats till Fillion i Valanaar tackar forskaren, men påpekar bekymrat att shrieklings bara är det minsta av deras bekymmer. Innan Flamebreeze tar itu med större frågor förbereder han en fullständig rapport om sitt uppdrag och trakten omkring, som han ska lämna direkt till Supreme Magister."}},faq={{q="Vem är Fillion Flamebreeze?",a="Fillion Flamebreeze är en forskare med kunskaper i de arkana konsterna. Han var på ett uppdrag nära Valanaar innan han blev strandsatt nära ett näste med farliga bestar.",al={"vem är fillion flamebreeze","vem är forskaren","vem ger uppdraget the missing scholar"}},{q="Vad är shrieklings?",a="Shrieklings är fientliga bestar som har byggt bo i ett närbeläget näste, farligt nära bosättningen Valanaar. Fillion Flamebreeze varnar för att deras närhet utgör ett direkt hot mot alla som reser i trakten.",al={"vad är shrieklings","var bygger shrieklings bo","hot från shrieklings"}},{q="Vem är Supreme Magister?",a="Supreme Magister är den regionala myndigheten i Valanaar som Fillion Flamebreeze måste rapportera till om händelserna vid nästet och läget för hans uppdrag.",al={"vem är supreme magister","fillions rapport","vem rapporterar fillion till"}},{q="Vad är Valanaar?",a="Valanaar är den närbelägna bosättningen eller utposten där Fillion Flamebreeze är stationerad och dit han återvänder när han har återhämtat sig tillräckligt för att resa på egen hand.",al={"vad är valanaar","var ligger valanaar"}},{q="Vad är Shriekling Matriarch?",a="Shriekling Matriarch är ledaren för shrieklings som håller till i Shriekling Den. Fillion ger äventyrare i uppdrag att döda henne och ta med hennes huvud tillbaka för att undanröja det omedelbara hotet mot Valanaar.",al={"målet shriekling matriarch","vem ska dödas i shriekling den"}},{q="Varför anser Fillion att shrieklings är det minsta av deras bekymmer?",a="Fillion Flamebreeze ser shrieklings som ett omedelbart hot mot Valanaar på grund av deras närhet, men när du återvänder påpekar han illavarslande att de i slutänden är det minsta av deras bekymmer.",al={"varför minsta av våra bekymmer","större fara för valanaar"}}},fp="19,163,25.263.0,25.226.1,27.156.0,21.128.0,28.157.0,17.118.0,33.171.0,70.152.0"}
P.entries["quest:92860"] = {n="In Service of Zephras",s="In Service of Zephras är ett uppdrag där en äventyrare överlämnar ett bud från High Order, som lovar Valanaar sitt fulla militära och diplomatiska stöd mot Al'Aketh-sekten. Tilltagande fientliga rörelser på ön har tvingat High Order att överge sin policy att undvika direkt konfrontation med sektmedlemmarna. När sändebudet överlämnar budskapet till Valennia Stormfist kommer hen också med dystra nyheter om att hennes kusin Belathaan har dött, vilket befäster deras gemensamma beslutsamhet att skydda Zephras folk.",h="In Service of Zephras är ett uppdrag där en äventyrare överlämnar ett bud från High Order, som lovar Valanaar...",kw={"al'aketh","belathaan","al'aketh-sekten","high order","in service of zephras","stormfist","valanaar","valennia stormfist","zephras"},sec={{t="Det växande hotet",b="Under en tid försökte High Order begränsa den öppna fientligheten mot den hemlighetsfulla Al'Aketh-sekten och förhindra ett fullskaligt krig över hela ön. Den bräckliga hållningen föll samman när sekten visade omisskännlig fientlighet, styrkt av oroväckande rapporter om omfattande truppförflyttningar. High Order insåg att sektmedlemmarna samlar styrkor inför en operation som hotar freden och tryggheten i varje bosättning och har därför valt att agera beslutsamt. I stället för att förbli passiva åskådare har de beslutat att bidra med sina styrkor till en aktiv allians och skickar ett sändebud för att samordna med de lokala försvararna innan Al'Aketh går till angrepp."},{t="Allians med Valanaar",b="För att möta det växande hotet från sekten skickas sändebudet till Valennia Stormfist för att officiellt erbjuda High Orders ovillkorliga hjälp i Valanaars motstånd mot Al'Aketh. Budskapet upprättar en gemensam försvarsfront mellan de två fraktionerna och banar väg för gemensamma militära insatser i regionen. Uppdraget har dock ett högt personligt pris: vid ankomsten måste resenären meddela att Belathaan, Valennias kusin och en hängiven tjänare åt Zephras, har dött. Medan Valennia sörjer hans bortgång svär hon hämnd, och den gemensamma sorgen blir till omedelbara förberedelser inför det kommande fälttåget."}},faq={{q="Vad handlar uppdraget In Service of Zephras om?",a="I In Service of Zephras får spelaren i uppdrag att uppsöka Valennia Stormfist på uppdrag av High Order. High Order försökte tidigare undvika direkt våld mot Al'Aketh-sekten, men ökande fientlighet och rapporter om omfattande truppförflyttningar från sekten runt ön tvingade dem att agera. Uppdraget innebär att High Order formellt stöder Valanaars försvar och samtidigt framför sorgliga nyheter om Belathaans öde.",al={"översikt över in service of zephras","vad händer i in service of zephras","uppdraget in service of zephras"}},{q="Vem är Valennia Stormfist?",a="Valennia Stormfist är en ledare som samordnar försvaret mot Al'Aketh i Valanaar. När High Order skickar ett sändebud för att lova sitt stöd tar Valennia emot erbjudandet om ömsesidig hjälp. Hon är också kusin till Belathaan, en fallen tjänare åt Zephras vars död rapporteras under mötet. Det får henne att svära hämnd mot sektmedlemmarna som hotar deras folk.",al={"valennia stormfists bakgrund","vem är valennia","valennia stormfist"}},{q="Vem var Belathaan?",a="Belathaan var kusin till Valennia Stormfist och en hängiven tjänare åt Zephras som dog före händelserna i det här uppdraget. Valennia minns honom som en hedervärd tjänare och försvarare av deras sak. Äventyraren bekräftar formellt hans död när hen rapporterar till Valennia, vilket gör konflikten mer personlig och stärker löftet att hämnas honom.",al={"vem är belathaan","belathaans bakgrund","vad hände med belathaan"}},{q="Vad är Al'Aketh?",a="Al'Aketh är en fientlig sekt som är verksam på ön och vars aggressiva rörelser hotar Zephras folk. High Order försökte först undvika att provocera fram direkta konfrontationer med dem, men de senaste fientliga utspelen och illavarslande rapporterna om omfattande rörelser från sekten har gjort kriget oundvikligt. Sekten har tvingat de lokala styrkorna och High Order att bilda en väpnad allians för att slå tillbaka den.",al={"vilka är al'aketh","al'aketh-sekten","vad är al'aketh"}},{q="Vilken roll har High Order i konflikten?",a="High Order försökte först undvika ett direkt krig med Al'Aketh-sekten och föredrog en återhållsam hållning. Men aggressiva handlingar och rykten om omfattande mobilisering från sekten övertygade ledningen om att neutralitet inte längre var hållbar. Genom att skicka en kurir till Valennia Stormfist lovar High Order officiellt att ställa hela sin styrka bakom Valanaars militära motstånd mot sekten.",al={"high orders inblandning","varför strider high order","high order och zephras"}},{q="Vad är Zephras?",a="Zephras är ön Zephras Isle, som High Order, Valanaar och dess försvarare alla kämpar för att skydda. High Order varnar uttryckligen för att sektens växande aktivitet bådar illa för Zephras folk, och fallna hjältar som Belathaan blir ihågkomna som trogna tjänare åt Zephras. Att skydda befolkningen är det främsta skälet till alliansen mot Al'Aketh.",al={"var ligger zephras","vem är zephras","zephras bakgrund"}}},fp="21,194,20.378.0,22.413.1,46.324.0,26.251.0,18.227.0,21.223.0,47.266.0,16.284.0"}
P.entries["quest:92871"] = {n="In Service of Zephras",s="Ryktet sprids över Zephras om att Al'Aketh-sekten mobiliserar inför en större konflikt. För att stärka öns försvar skickas ett sändebud för att försäkra Valennia Stormfist om att Windshapers står redo att stödja hennes fredsvakter.",h="Ryktet sprids över Zephras om att Al'Aketh-sekten mobiliserar inför en större konflikt.",kw={"al'aketh","in service of zephras","valanaar","valennia stormfist","windshapers","zephras"},sec={{t="Rykten på ön",b="Spänningarna ökar över ön Zephras, då rapporter tyder på omfattande sekteristisk aktivitet. Fredsvakterna under Valennia Stormfist har länge hållit vakt över dessa marker, men Al'Aketh verkar organisera sig inför en större konflikt. För att skydda ön har Windshapers lovat att stå stadigt vid Valanaars styrkors sida om öppna strider bryter ut."},{t="Lova stöd",b="Du skickas för att träffa Valennia Stormfist och bekräfta att Windshapers är fullt redo att hjälpa hennes fredsvakter. När Valennia får höra att de allierade är redo välkomnar hon det snabba åtagandet och förbereder sig på att diskutera den förvärrade situationen kring sekten."}},faq={{q="Vem är Valennia Stormfist?",a="Valennia Stormfist leder fredsvakterna som ansvarar för att skydda Zephras. Hon samordnar öns försvar, däribland Valanaars kampanj mot den fientliga sekten Al'Aketh.",al={"vem är valennia stormfist","valennia stormfist"}},{q="Vilka är Windshapers?",a="Windshapers är en allierad grupp på Zephras som hjälper Valennia Stormfist och hennes fredsvakter. De ger Valanaars styrkor sitt fulla stöd i kampen mot det växande hotet från Al'Aketh.",al={"vilka är windshapers","windshapers bakgrund"}},{q="Vad är Al'Aketh?",a="Al'Aketh är en sekt som verkar över hela ön Zephras. Rapporter tyder på att de genomför större förflyttningar och förbereder sig för en nära förestående konflikt.",al={"vilka är alaketh","vad är alaketh","al aketh-sekten"}},{q="Vad är Zephras?",a="Zephras är en ö som försvaras av Valennia Stormfist och hennes fredsvakter, där Windshapers hjälper till mot hotfull sektaktivitet från Al'Aketh.",al={"vad är zephras","ön zephras"}},{q="Vad är Valanaar?",a="Valanaar är en bosättning på Zephras och hem åt Valennia Stormfists fredsvakter. Windshapers ger sitt fulla stöd till dess kamp mot Al'Aketh.",al={"vad är valanaar","vem är valanaar"}}},fp="21,167,20.279.0,16.208.0,26.148.0,24.175.0,22.115.0,16.125.0,17.144.0"}
P.entries["quest:92872"] = {n="Dutiful Steps",s="Caretaker Alaric ber dig bära gravstoft från kryptan i Stromgarde Keep till havet. Riten förnyar minnescykeln för de fallna.",h="Caretaker Alaric ber dig bära gravstoft från kryptan i Stromgarde Keep till havet.",kw={"caretaker alaric","ceremonier","krypta","plikttrogna steg","fallna","great sea","påse med gravstoft","stromgarde keep","gravstoft"},sec={{t="Mot havet",b="Din väg tillbaka till den solbelysta världen börjar med en liten väska. Caretaker Alaric ber dig ta den till klipporna bakom Stromgarde Keep och kasta innehållet i Great Sea. Stoftet kommer från graven under borgen, där dess väktare bevarar ceremonier för att hedra de fallna. Varje årstid sprids en del över Azeroths hav som en symbolisk förnyelse."}},faq={{q="Vem ber mig bära stoftet?",a="Caretaker Alaric ber dig bära gravstoftet från kryptan i Stromgarde Keep till havet.",al={"vem gav mig detta","alarics begäran"}},{q="Vad finns i väskan?",a="Väskan innehåller stoft från graven under Stromgarde Keep.",al={"vad finns i påsen","gravstoft"}},{q="Varför sprids gravstoftet över havet?",a="Varje årstid sprids en del gravstoft över Azeroths hav som en symbolisk handling för att förnya kretslopp.",al={"varför kasta stoft i havet","vad är stoftet till för"}},{q="Var ska jag kasta väskan?",a="Caretaker Alaric ber dig kasta gravstoftet i Great Sea från klipporna bakom Stromgarde Keep.",al={"var ska jag kasta det","klipporna bakom stromgarde"}},{q="Vad bevarar gravens väktare?",a="Gravens väktare bevarar kunskap om ceremonier som används för att hedra de fallna.",al={"vad finns i graven","ceremonier"}}},fp="13,142,14.371.0,35.91.0,23.61.0,43.101.0,37.106.0,40.87.0"}
P.entries["quest:92880"] = {n="Return to Valanaar",s="Return to Valanaar är ett uppdrag där en äventyrare överlämnar Yorna's report om försvaret av det östra vakttornet till Valennia Stormfist i Valanaar. Rapporten bekräftar att försvarslinjen har stabiliserats och att de återstående angriparna håller på att rensas bort, till stor lättnad för bosättningens ledning.",h="Return to Valanaar är ett uppdrag där en äventyrare överlämnar Yorna's report om försvaret av det östra...",kw={"östra vakttornet","fyra vindar","return to valanaar","valanaar","valennia stormfist","yorna","yorna's report"},ang={["race:Skyborne"]="Välsignelsen som åkallar de fyra vindarna speglar de kulturella och andliga band som är gemensamma bland Valanaars försvarare och ledare."},sec={{t="Besked från utposten",b="Efter ett våldsamt angrepp på utposten skickar försvararen Yorna ett besked tillbaka till bosättningen Valanaar. Angriparna har slagits tillbaka och de återstående fienderna håller på att rensas bort. En äventyrare skickas med Yorna's Report för att lugna den oroliga ledningen som väntar på nyheter i staden."},{t="Lättnad i Valanaar",b="Budet förmedlar direkt till Valennia Stormfist i Valanaar hur det står till vid det östra vakttornet. När hon får bekräftat att tornet har hållit stånd och att försvarslinjen är stabiliserad uttrycker Valennia tydlig lättnad och tackar vindarna för att deras viktiga gränspost fortfarande är säker."}},faq={{q="Vem skickar dig till Valanaar?",a="Yorna ger dig uppdraget efter ett hårt utkämpat försvar mot fientliga angripare vid en utpost och ber dig överlämna en lägesrapport till ledningen.",al={"vem ger return to valanaar","vem skickar dig tillbaka till valanaar","yorna uppdragsgivare"}},{q="Vem rapporterar du till i Valanaar?",a="Valennia Stormfist är stationerad i Valanaar och väntar på besked om de avlägsna försvararnas säkerhet och beredskap.",al={"vem är valennia stormfist","var finns valennia stormfist","lämna in return to valanaar"}},{q="Vad är Yorna's Report?",a="Yorna's Report innehåller en uppdatering som bekräftar att försvararna har stabiliserat sin ställning efter angreppet och håller på att rensa bort de återstående angriparna.",al={"vad är yorna's report","vad står i yorna's report"}},{q="Vilket vakttorn angreps?",a="Utposten som försvaras av Yorna och hennes styrkor är det östra vakttornet, en viktig försvarsposition som bevakar vägarna mot Valanaar.",al={"vilket torn angreps","vilket vakttorn är yorna vid"}},{q="Hur är läget vid det östra vakttornet?",a="Även om några angripare fortfarande måste rensas bort har försvararna säkrat positionen, och läget vid vakttornet anses vara stabilt.",al={"är vakttornet säkert","vann försvararna"}},{q="Varför talar försvararna om de fyra vindarna?",a="Uttrycket ”Må de fyra vindarna välsigna dig” och Valennias utrop ”Tacka vindarna” visar att försvararna i Valanaar vördar vindarna och elementen.",al={"de fyra vindarnas betydelse","må de fyra vindarna välsigna dig"}}},fp="18,153,21.219.0,18.204.0,26.128.0,33.105.0,23.112.0,34.105.0,45.130.0,45.135.0"}
P.entries["quest:92881"] = {n="The High Elder's Request",s="The High Elder's Request skickar äventyrare till Valanaar för att rådgöra med High Elder Talaanis Shadowsong efter samordnade angrepp mot regionens vakttorn. Rapporter från det västra vakttornet tyder på att en fientlig kult siktar in sig på de lokala förankringspelarna.",h="The High Elder's Request skickar äventyrare till Valanaar för att rådgöra med High Elder Talaanis Shadowsong...",kw={"förankringspelare","östra vakttornet","shadowsong","skypräst","talaanis shadowsong","the high elder's request","valanaar","västra vakttornet"},ang={["class:Priest"]="Kultens intresse för förankringspelarna och den gåtfulla skyprästens inblandning vid det västra vakttornet är en oroande utveckling för präster som studerar gudomlig eller rituell manipulation."},sec={{t="Problem vid vakttornen",b="Nyliga samordnade angrepp mot både det västra och det östra vakttornet har avslöjat ett oroande mönster. Det som först verkade vara utspridda skärmytslingar pekar nu mot en välplanerad offensiv riktad mot de lokala förankringspelarna. Rapporter från konfrontationen med en skypräst vid det västra vakttornet avslöjade först kultens intresse för dessa strukturer, vilket fick myndigheterna att se försvaret av tornen som en akut angelägenhet."},{t="Möte i Valanaar",b="Medvetna om det växande hotet mot förankringspelarna uppmanar ledarna äventyrarna att tala direkt med High Elder Talaanis Shadowsong i Valanaar. High Elder har ett lovande spår om kultens rörelser och söker erfarna allierade som är beredda att spåra fienden och hindra den ritual eller det sabotage de planerar att genomföra."}},faq={{q="Vem är High Elder Shadowsong?",a="High Elder Talaanis Shadowsong är en ledare i Valanaar. När en kult genomför samordnade angrepp mot regionens vakttorn söker han kapabla äventyrare som kan följa upp lovande spår om kultens verkliga avsikter.",al={"vem är talaanis shadowsong","high elder shadowsong","var är shadowsong"}},{q="Var ligger Valanaar?",a="Valanaar är en bosättning eller fristad där High Elder Talaanis Shadowsong håller till, samordnar försvaret och undersöker kultens intrång mot de lokala förankringspelarna och tornen.",al={"vad är valanaar","valanaars plats"}},{q="Varför angreps vakttornen?",a="Samordnade angrepp träffade både det västra och det östra vakttornet. Försvararna misstänker att angreppen inte var slumpmässiga räder, utan avsiktliga manövrer för att angripa eller manipulera de närliggande förankringspelarna.",al={"varför angreps vakttornen","västra och östra vakttornen","angrepp mot vakttornen"}},{q="Vad är förankringspelarna?",a="Förankringspelarna är viktiga försvarsstrukturer eller regionala strukturer. Underrättelser från angreppet mot det västra vakttornet tyder på att en fientlig kult specifikt försöker störa dem eller lägga dem under sig.",al={"vad är förankringspelarna","kulten och förankringspelarna","varför förankringspelarna"}},{q="Vem var skyprästen vid det västra vakttornet?",a="En skypräst var inblandad i händelsen vid det västra vakttornet. Uppgifterna från mötet ledde till att ledarna drog slutsatsen att kulten hade en större plan för förankringspelarna.",al={"vem var skyprästen","skyprästen vid det västra vakttornet","skyprästens roll"}},{q="Vilken kult siktar in sig på vakttornen?",a="En aggressiv kult har samordnat samtidiga angrepp mot regionens vakttorn. Dess exakta natur och djupare motiv utreds fortfarande medan High Elder Shadowsong försöker avslöja dess planer.",al={"vilken kult är det","vem angrep tornen"}}},fp="24,213,26.339.0,20.266.0,29.188.0,18.159.0,34.160.0,27.166.0,48.177.0,39.179.0"}
P.entries["quest:929"] = {n="Crown of the Earth",s="Crown of the Earth är ett heligt uppdrag från Corithras Moonrage i Dolanaar, där du hämtar välsignat vatten från månkällan nära Starbreeze Village. Som tack för att de fyller på vattnet i Darnassus får unga Night Elf lära sig den tragiska historia som fick deras folk att odla Teldrassils väldiga grenar.",h="Crown of the Earth är ett heligt uppdrag från Corithras Moonrage i Dolanaar, där du hämtar välsignat vatten...",kw={"corithras moonrage","crown of the earth","dolanaar","jade phial","månkälla","nordrassil","starbreeze village","teldrassil"},ang={["class:Druid"]="Månkällorna är viktiga kanaler för naturens och stjärnornas magi. De är levande reservoarer som knyter din ordens plikter i Darnassus till Teldrassils rötter.",["race:NightElf"]="Varje Night Elf måste möta förlusten av odödligheten och Malfurion Stormrages försvinnande. Därför är denna heliga insamling en viktig lektion i ditt folks sorg efter de senaste händelserna."},sec={{t="Att hålla månkällorna vid liv",b="Den stora månkällan mitt i Darnassus kräver ständig kontakt med de mindre källor som finns utspridda i världsträdets krona. Druider tillverkar särskilda jadeflaskor för att samla och bära det lysande vattnet utan att förorena det. Genom att skicka noviser till fots till Starbreeze Village ser de äldre till att stadens fontäner hålls fyllda av Elunes nåd och att de unga förstår arbetet som krävs för att ge näring åt Teldrassil."},{t="Ekon från Tredje kriget",b="När novisen har slutfört arbetet får hen höra berättelser från förr. Corithras Moonrage berättar om förtvivlan som grep kaldorei strax efter slaget vid Mount Hyjal. Offret av världsträdet Nordrassil berövade Night Elf deras dyrbara odödlighet, och mitt i förödelsen släpptes Illidan Stormrage fri medan Shan'do Malfurion Stormrage försvann. Denna tid av sorg och isolering lade grunden till den omstridda planteringen av Teldrassil."}},faq={{q="Varför hämtar man vatten från månkällan?",a="Druiderna i Darnassus fyller regelbundet på stadens främsta månkällas vatten med vatten från skogsskrinen i närheten. På så sätt bevarar de det heliga nätverket över hela Teldrassil.",al={"varför hämta vatten från månkällan","vad används månkällans vatten till","vad används jadeflaskan till"}},{q="Var ligger månkällan för uppdraget?",a="Månkällan ligger strax utanför Starbreeze Village, öster om Dolanaar längs skogsstigen.",al={"var ligger månkällan","var ligger månkällan vid starbreeze","brunnen i starbreeze village"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en Night Elf i Dolanaar som vägleder unga äventyrare genom ritualerna och berättelserna kring Teldrassils välmående.",al={"vem ger uppdraget","corithras moonrages historia"}},{q="Vilken historia berättar Corithras när man återvänder?",a="Han berättar om de katastrofala följderna av slaget vid Mount Hyjal: Nordrassil brändes, kaldoreis odödlighet försvann, Illidan befriades och Shan'do Malfurion Stormrage försvann.",al={"vad berättar corithras","historien om crown of the earth"}},{q="Varför känner sig Night Elf vilsna efter Mount Hyjal?",a="Nordrassil hade skänkt Night Elf evigt liv och beskydd. När trädets kraft offrades för att förgöra Archimonde krossades deras tidlösa tillvaro. De blev dödliga, vilse och djupt sårbara.",al={"varför förlorade alverna sin odödlighet","vad hände efter hyjal"}},{q="Vad betyder Shan'do?",a="Shan'do är en hederstitel på darnassiska som betyder ”ärad lärare”. Här används den om Malfurion Stormrage, druidernas högste ledare.",al={"vad betyder shan'do","betydelsen av shan'do"}}},fx={["5a4296ad"]={q="Varför vill Corithras Moonrage att det här ska göras?",a="Corithras utför viktiga uppdrag för Cenarion Circle och undervisar unga nattalver om deras folks utsatta tillstånd. Teldrassils heliga vatten kräver ständig omsorg och balans, och druiderna i Darnassus behöver färskt vatten från månbrunnar ute bland grenarna. Genom att byta denna tjänst mot historia och vägledning ser Corithras till att månbrunnen i Darnassus fylls på och att du förstår de tunga bördor ditt folk bär efter det tredje kriget.",al={"corithras moonrages motiv","varför behöver corithras vatten","corithras uppdrag vid månbrunnarna"}},["0abe9d82"]={q="Vad används Filled Jade Phial till?",a="Filled Jade Phial innehåller heligt vatten från månbrunnen nära Starbreeze Village. Kärlet är särskilt utformat för att bevara månbrunnsvattnets latenta magiska kraft, och förser druiderna i Darnassus med nytt vatten. De hämtar kraft ur Teldrassils samlade källor för sina ritualer och sin läkekonst.",al={"filled jade phials syfte","vad används jade phial till","filled jade phial"}}},fp="18,215,24.445.0,23.359.0,46.138.0,44.90.0,26.151.0,46.194.0,47.202.0,18.122.0"}
P.entries["quest:92909"] = {n="Harvesting the Harvesters",s="Harvesting the Harvesters är ett lokalt uppdrag i Westfall där du hjälper Ozwin Ironsprocket, en besökande gnomisk uppfinnare som sitter fast i ett stall på Saldean's Farm. Efter att ha underskattat hur våldsamma områdets vildsinta skördegolemer är behöver Ozwin bärgade mekaniska delar för att bygga en flyktanordning.",h="Harvesting the Harvesters är ett lokalt uppdrag i Westfall där du hjälper Ozwin Ironsprocket, en besökande...",kw={"isofjädrar från golemer","skördegolemer","gyrostabilisatorer från skördare","harvesting the harvesters","ironforge","ozwin ironsprocket","saldean's farm","westfall"},ang={["faction:Alliance"]="Alliansresenärer som besöker Saldean's Farm kan hjälpa en besökande gnomisk lärd som blev strandsatt efter ett felberäknat försök att laga Westfalls mekaniska plåga.",["profession:Engineering"]="Genom att bärga komplicerade delar som isofjädrar och gyrostabilisatorer från oregerliga skördegolemer får man de viktiga rådelar som behövs för att uppfinna en fungerande flyktanordning.",["race:Gnome"]="Ozwin Ironsprocket förkroppsligar gnomernas typiska ambition att meka med komplicerade maskiner, även om hans underskattning av maskinernas aggressivitet ledde till att han blev instängd i ett stall."},sec={{t="Ett felberäknat försök",b="Westfalls bördiga slätter har kastats in i kaos och översvämmats av både laglösa och mekaniska skördare på bärsärkagång. Ryktet om dessa vildsinta automater nådde Ironforges tekniska verkstäder och inspirerade den gnomiske ingenjören Ozwin Ironsprocket att resa söderut. Ozwin litade på sin tekniska skicklighet och trodde att han kunde felsöka och kalibrera om de oregerliga jordbruksmaskinerna för att återställa lugnet på regionens hårt prövade åkrar."},{t="Fast i stallet",b="När Ozwin kom fram till fälten kring Saldean's Farm upptäckte han snabbt att skördegolemerna var mycket mer oberäkneliga och våldsamma än ritningarna antydde. Maskinernas rakbladsvassa skär och vilda svingar fick gnomen att fly för sitt liv in i ett närbeläget stall. Ozwin sitter fast och kan inte ta sig ut på fälten, så han förlitar sig på djärva äventyrare som kan bärga användbara isofjädrar och gyrostabilisatorer från de mekaniska bestarna. Då kan han sätta ihop en anordning för att fly säkert."}},faq={{q="Vem är Ozwin Ironsprocket?",a="Ozwin Ironsprocket är en gnomisk uppfinnare som reste från Ironforge till Westfall med det djärva målet att kalibrera om de våldsamma skördegolemerna. Deras extrema fientlighet tvingade honom dock att söka skydd i ett stall på Saldean's Farm.",al={"vem är ozwin ironsprocket","ozwin","uppdragsgivare"}},{q="Varför är skördegolemerna så aggressiva?",a="De mekaniska skördegolemerna som strövar omkring på Westfalls övergivna fält har blivit vilt aggressiva och angriper förbipasserande. Ozwin hoppades kunna åtgärda deras funktionsfel med en rutinmässig omkalibrering, men deras våldsamhet visade sig vara långt värre än hans beräkningar förutspådde.",al={"varför anfaller skördarna","varför är golemer aggressiva","vad är fel på skördarna"}},{q="Var kan Ozwin Ironsprocket hittas?",a="Ozwin Ironsprocket gömmer sig i ett stall på Saldean's Farm i Westfall och tar skydd från de farliga skördegolemerna som stryker omkring på fälten i närheten.",al={"var finns ozwin ironsprocket","var lämnar man in harvesting the harvesters","ozwins plats"}},{q="Vad tänker Ozwin bygga med de insamlade delarna?",a="Ozwin behöver isofjädrar från golemer och gyrostabilisatorer från skördare för att bygga en mekanisk nödanordning som ger honom tillräckligt skydd för att fly från stallet utan att skadas.",al={"vad behöver ozwin delarna till","varför samla isofjädrar","delar till flyktanordning"}},{q="Varför reste Ozwin från Ironforge till Westfall?",a="Ozwin fick höra att oregerliga maskiner terroriserade landsbygden i Westfall och reste hela vägen från dvärgarnas huvudstad Ironforge. Han trodde att hans uppfinningsrikedom kunde hjälpa honom att kalibrera om de oregerliga automaterna.",al={"varför kom ozwin till westfall","varför lämna ironforge"}},{q="Var kommer de nödvändiga golem-delarna ifrån?",a="Isofjädrarna och gyrostabilisatorerna bärgas direkt från de fientliga skördegolemerna och skördarna som stryker omkring på jordbruksfälten i Westfall kring Saldean's Farm.",al={"varifrån får man delarna","hur får man isofjädrar och gyrostabilisatorer"}}},fp="25,156,24.307.0,20.345.0,26.178.0,41.190.0,38.124.0,57.134.0,48.158.0,44.135.0"}
P.entries["quest:92910"] = {n="Harvesting the Harvesters",s="En bärgad del från en skördemaskin kan intressera någon som studerar skördegolemar. Du ombeds ta den till Ozwin Ironsprocket på Saldean's Farm.",h="En bärgad del från en skördemaskin kan intressera någon som studerar skördegolemar.",kw={"skördegolem","skördemaskin","harvesting the harvesters","ozwin ironsprocket","precessive autocognition assembly","saldean's farm","bärgad del"},sec={{t="En bärgad del",b="Någon på Saldean's Farm kanske vill undersöka delen du bärgade från en skördemaskin. Den verkar till största delen vara intakt, och Ozwin Ironsprocket väntar på att få se den."}},faq={{q="Vad ska jag ta med till Ozwin?",a="Du tar med Precessive Autocognition Assembly till Ozwin Ironsprocket, en del som bärgats från en skördemaskin.",al={"skördemaskinsdel","vilket föremål","autocognition assembly"}},{q="Vart ska jag ta den bärgade delen?",a="Ta Precessive Autocognition Assembly till Ozwin Ironsprocket på Saldean's Farm.",al={"var finns ozwin","saldean's farm","vart ska den lämnas"}},{q="Varför skulle någon vilja ha delen?",a="Den bärgade delen verkar till största delen vara intakt, och någon som är intresserad av skördegolemar kanske vill se den.",al={"varför skördemaskiner","vem vill ha detta","intresse för skördemaskiner"}}},fp="25,141,15.156.0,24.101.0,35.84.0,32.101.0"}
P.entries["quest:92911"] = {n="Harvesting the Harvesters",s="På Saldean's Farm behöver Ozwin Ironsprocket delar till en apparat som ska ta kontroll över skördemaskinernas system en kort stund. Han fortsätter att sätta ihop apparaten medan du samlar ihop det han behöver.",h="På Saldean's Farm behöver Ozwin Ironsprocket delar till en apparat som ska ta kontroll över skördemaskinernas...",kw={"copper modulators","crude scope","apparat","golem isosprings","skördemaskiner","harvesting the harvesters","ozwin ironsprocket"},sec={{t="Delar till Ozwin",b="Ozwin Ironsprocket på Saldean's Farm undersöker vad som får skördemaskinerna att fungera. Han tror att han kan ta kontroll över deras system en kort stund. Du samlar ihop delar till hans apparat medan han fortsätter att arbeta med bygget."},{t="Den färdiga apparaten",b="Ozwin gör färdigt apparaten och ber dig att prova den. Han stannar på gården, som börjar kännas som hemma för honom."}},faq={{q="Vem ber om delar?",a="Ozwin Ironsprocket på Saldean's Farm behöver delar till en apparat.",al={"vem behöver delar","ozwin delar"}},{q="Vad bygger Ozwin?",a="Ozwin bygger en apparat som ska ta kontroll över skördemaskinernas system en kort stund.",al={"vilken apparat","skördemaskinsapparat"}},{q="Vilka delar behöver Ozwin?",a="Ozwin behöver Golem Isosprings, Copper Modulators och en Crude Scope.",al={"dellista","vad behöver ozwin"}},{q="Var arbetar Ozwin?",a="Ozwin Ironsprocket arbetar på Saldean's Farm.",al={"var är ozwin","ozwins plats"}}},fp="25,182,15.218.0,19.117.1,24.62.0,23.80.0,27.67.0,23.48.0"}
P.entries["quest:92914"] = {n="Strange Pylons",s="I Shen'dralas är en urladdad kristallpylons syfte okänt. Du ombeds leta efter fler i närheten.",h="I Shen'dralas är en urladdad kristallpylons syfte okänt.",kw={"kristall","alvruiner","ädelsten","manaelementärer","pylon","shen'dralas","märkliga pyloner"},sec={{t="Bland ruinerna",b="En märklig kristall vilar på en uråldrig piedestal bland Shen'dralas alvruiner. För bara några ögonblick sedan vaktades den av utmärglade manaelementärer. Ädelstenen är sprucken och dess magi nästan uttömd, så dess syfte förblir ett mysterium. Du söker i området efter fler liknande pyloner."}},faq={{q="Vad är den märkliga pylonen?",a="Det är en sprucken ädelsten på en uråldrig piedestal i Shen'dralas. Den uttömda magin gör dess syfte okänt.",al={"märklig pylon","kristallpylon","vad är den här kristallen"}},{q="Varför surrar kristallen?",a="Ett svagt kraftsurr kommer från den spruckna ädelstenen, trots att dess magi nästan är uttömd.",al={"kristallsurr","varför surrar den","svagt surr"}},{q="Vad vaktade kristallen?",a="Utmärglade manaelementärer vaktade kristallen för bara några ögonblick sedan.",al={"manaelementärer","vad vaktade den","elementärer vid pylonen"}},{q="Var finns de andra pylonerna?",a="Du ombeds söka i Shen'dralas efter fler pyloner som den du hittade.",al={"andra pyloner","hitta fler pyloner","pylonernas platser"}}},fp="14,109,15.269.0,26.116.0,27.92.0,30.63.0,27.76.0"}
P.entries["quest:92947"] = {n="Making Our Move",s="Making Our Move är ett samordnat taktiskt anfall mot de fientliga Al'Aketh som befäst sig i Shrine of Akir. Med en avledningsmanöver framifrån och en flankmanöver försöker anfallsstyrkan bryta igenom försvaret och nå översteprästinnan.",h="Making Our Move är ett samordnat taktiskt anfall mot de fientliga Al'Aketh som befäst sig i Shrine of Akir.",kw={"al'aketh","al'aketh blademaster","al'aketh guardian","al'aketh spiritcaller","översteprästinna","hyusaa quickbreeze","making our move","shrine of akir"},ang={["class:Priest"]="Anfallet riktas mot Al'Akeths ledning, särskilt den fientliga översteprästinnan och hennes Spiritcallers som styr från Shrine of Akir."},sec={{t="En samordnad kniptång",b="Anfallet mot Shrine of Akir bygger på exakt timing och en uppdelning av styrkorna. En liten grupp elitkämpar stormar huvudingången för att slå larm och locka fram försvararna, medan befälhavaren leder huvudstyrkan från flanken. Den samordnade framryckningen ska splittra försvararnas uppmärksamhet och öppna en väg rakt mot helgedomens ledning."},{t="Genom Al'Akeths försvarslinjer",b="Shrine of Akir försvaras av de mäktiga Al'Aketh, vars led består av tungt rustade Guardians, mystiska Spiritcallers och stridsvana Blademasters. För att bryta igenom försvarslinjen måste ni ta er genom dessa främsta led och bana väg mot den inre helgedomen, där översteprästinnan leder sina anhängare. När det yttre motståndet väl är krossat samlas styrkorna på nytt med ställföreträdaren Hyusaa Quickbreeze vid helgedomens trappa."}},faq={{q="Vad är målet med anfallet i Making Our Move?",a="Making Our Move är ett samordnat taktiskt anfall mot de fientliga styrkor som håller Shrine of Akir. En avledningsmanöver framifrån drar till sig fiendens uppmärksamhet medan huvudstyrkan går runt deras position för att bryta sig in i helgedomen och besegra översteprästinnan.",al={"making our move","uppdraget making our move","uppdraget shrine of akir"}},{q="Vem är Hyusaa Quickbreeze?",a="Hyusaa Quickbreeze är anfallsstyrkans ställföreträdare. När du har decimerat leden bland Al'Akeths försvarare vid helgedomen får du order om att möta Quickbreeze vid helgedomens trappa.",al={"vem är hyusaa","hyusaa quickbreeze","var finns hyusaa"}},{q="Vem är översteprästinnan som anfallet riktas mot?",a="Översteprästinnan är den ledande gestalten i Shrine of Akir. Hela den omfattande flankmanövern ska snabbt tränga igenom fiendens linjer så att anfallsstyrkan kan nå henne och besegra henne.",al={"vem är översteprästinnan vid akir","översteprästinnan alaketh","målet översteprästinnan"}},{q="Vad är Shrine of Akir?",a="Shrine of Akir är en befäst religiös plats som hålls av Al'Aketh. Den försvaras av beväpnade väktare, spiritcallers och blademasters som skyddar den centrala helgedomen där deras ledning håller till.",al={"vad är shrine of akir","lore om shrine of akir","var finns shrine of akir"}},{q="Vilka Al'Aketh-styrkor håller helgedomen?",a="Al'Aketh är de fientliga försvarare som håller Shrine of Akir. Deras styrkor består av ståndaktiga Guardians i främsta ledet, trollkunniga Spiritcallers och rörliga Blademasters som vaktar vägen till deras översteprästinna.",al={"vilka är alaketh","al'akeths försvarare","alaketh-fiender"}},{q="Varför används en avledningsmanöver framifrån i anfallet?",a="Några få erfarna kämpar skickas rakt genom helgedomens huvudingång för att locka fram försvararna och skapa kaos. Avledningen gör att huvudstyrkan kan gå runt anläggningen och slå sig in mot den inre helgedomen.",al={"varför avledningsmanöver","anfallsplan för helgedomen","anfallsstrategi för making our move"}}},fp="15,179,20.338.0,27.359.0,56.171.0,26.156.0,49.132.0,27.174.0,47.195.0,49.203.0"}
P.entries["quest:93"] = {n="Dusky Crab Cakes",s="Chef Grual på Scarlet Raven Tavern i Darkshire har en hemlighet bakom sina berömda Dusky Crab Cakes: de innehåller inte krabba alls. För att hjälpa den utsvultne och nervöse Jitters skickas äventyrare ut för att samla spindelben från de dödliga spindeldjur som strövar omkring i norra Duskwood, så att byns älskade tilltugg kan tillagas.",h="Chef Grual på Scarlet Raven Tavern i Darkshire har en hemlighet bakom sina berömda Dusky Crab Cakes: de...",kw={"chef grual","darkshire","duskwood","dusky crab cakes","jitters","scarlet raven tavern","spindelben","venom web spider"},ang={["faction:Alliance"]="Rätten visar hur osäker Alliansens södra gränstrakt är, där städer som Darkshire tvingas livnära sig på jättelika skadedjur på grund av eftersatt infrastruktur och avbrutna försörjningslinjer.",["profession:Cooking"]="Chef Grual visar prov på den uthållighet som krävs av kockar i gränstrakterna och bevisar att även skräckinjagande rovdjur i vildmarken, som giftiga jättespindlar, kan förvandlas till en bys stolta lokala delikatess."},sec={{t="En tvivelaktig delikatess",b="Duskwood har länge plågats av isolering, mörk magi och avbrutna försörjningsvägar, vilket tvingat Darkshires invånare att anpassa sin matlagning. Chef Grual, kocken på Scarlet Raven Tavern, löste sin köttbrist genom att hitta på Dusky Crab Cake. Trots att namnet antyder skaldjur från avlägsna kuster medger Grual utan omsvep att rättens tydligt syrliga smak helt och hållet kommer från de kladdiga benen från traktens jättespindlar."},{t="Jakt på giftspindlar",b="För att uppfylla beställningen skickar Grual jägare norrut mot bergssluttningarna och flodstränderna där Venom Web Spiders spinner sina nät. I en dyster skog full av odöda och vilda bestar är det farligt att samla färskt spindelkött, men det är fortfarande en av de få lättillgängliga proteinkällorna i den härjade skogen. Grual steker de kryddade spindelbenen i en het panna tills de blir knapriga."},{t="Tröst åt en förbannad själ",b="Matärendet har sin grund i omtanken om Jitters, en upprörd luffare som söker skydd i den övergivna byn Raven Hill i västra Duskwood. Jitters är uppfylld av skuld och skälver av skräck efter att oavsiktligt ha släppt fasor lösa över trakten, och han kan knappt tänka på något annat än sin hungriga mage. En varm omgång av Gruals smakrika spindelkakor blir en sällsynt, om än bisarr, tröst i hans eländiga exil."}},faq={{q="Är Dusky Crab Cakes verkligen gjorda av krabba?",a="Nej. Chef Grual erkänner öppet för äventyrare att Dusky Crab Cakes helt och hållet görs av kladdiga spindelben. Darkshire har ingen tillgång till havet eller färsk krabba, så Grual använder traktens jättespindlar för att efterlikna konsistensen och få till ett skarpt, syrligt tilltugg.",al={"är det riktig krabba","krabbkakornas hemlighet","vad innehåller krabbkakor"}},{q="Var får Chef Grual tag på spindelbenen?",a="Grual förlitar sig på äventyrare som samlar kladdiga ben från Venom Web Spiders. Dessa aggressiva spindeldjur håller främst till i norra Duskwood, mellan skogens bergssluttningar och floden.",al={"var hittar man spindelben","spindelplatser i duskwood","var finns venom web spiders"}},{q="Vem bakas de här krabbkakorna åt?",a="Grual serverar dem till gäster i Darkshire, men just den här omgången har beställts åt Jitters. Jitters är en vettskrämd eremit som svälter i spökstaden Raven Hill i västra Duskwood och desperat behöver något som stillar hans kurrande mage.",al={"vem vill ha krabbkakorna","vem äter krabbkakorna","varför laga krabbkakor"}},{q="Kommer Chef Grual att lära mig laga Dusky Crab Cakes?",a="Chef Grual håller sitt exakta recept på Dusky Crab Cakes strikt hemligt och vägrar avslöja sin egen kryddblandning. Han belönar däremot hjälpsamma äventyrare med ett annat recept ur sin kulinariska repertoar.",al={"kan jag lära mig receptet på krabbkakor","recept på krabbkakor matlagning"}},{q="Varför förlitar sig Darkshire på spindlar som föda?",a="Duskwoods vägar hemsöks av odöda, Nightbane-worgen och fientliga varelser, vilket stör handelskaravaner och jordbruk svårt. Eftersom färsk boskap och importerade varor är sällsynta använder Darkshires invånare sin uppfinningsrikedom och fångar den vilda fauna de kan komma åt.",al={"varför äta spindlar i darkshire","matbrist i duskwood"}},{q="Vet Jitters att kakorna är gjorda av spindlar?",a="Jitters är särskilt sugen på Gruals berömda krabbkakor och bryr sig föga om ingredienserna. Förlamad av skräck och svält ute i skogen längtar han efter vilken välbekant måltid som helst från Darkshire, oavsett dess rysliga ursprung.",al={"vet jitters om spindlarna","jitters reaktion på spindelkött"}}},fx={e54432be={q="Vad används Gooey Spider Leg till?",a="Trots det trevliga namnet på tavernans meny är Gooey Spider Legs själva köttet i Chef Gruals berömda Dusky Crab Cakes. Grual kryddar de sprattlande benen med sin hemliga kryddblandning och steker dem i en panna. Han förlitar sig på deras naturliga safter för att ge de smakrika kakorna deras särpräglade, syrliga smak.",al={"vad gooey spider leg används till","varför gooey spider legs","spindelben i krabbkakor"}}},fp="16,156,23.300.0,22.309.0,25.320.1,43.216.0,42.166.0,40.196.0,54.184.0,44.236.0,48.213.0"}
P.entries["quest:930"] = {n="The Glowing Fruit",s="Glowing Fruit är ett uppdrag i Teldrassil som börjar när du upptäcker en märklig fruktbärande växt som växer vilt i skogen. Unga äventyrare misstänker att något onaturligt ligger bakom och tar det självlysande exemplaret till örtkännaren Denalan vid Lake Al'Ameth för undersökning.",h="Glowing Fruit är ett uppdrag i Teldrassil som börjar när du upptäcker en märklig fruktbärande växt som växer...",kw={"boglings","denalan","glowing fruit","örtmedicin","lake al'ameth","märklig fruktväxt","teldrassil","timberlings"},ang={["class:Druid"]="För druider som värnar om naturens balans är främmande, instabil flora som växer onaturligt bland Teldrassils heliga grenar en omedelbar varningssignal.",["profession:Herbalism"]="Örtkunniga kommer att uppskatta Denalans botaniska insikter om hur främmande frön kan färdas mellan kontinenter och mutera när de utsätts för förtrollad jord.",["race:NightElf"]="Kaldoreiungdomar lär sig av Denalan att även den unga jorden i deras nya hem, Teldrassil, är mottaglig för oförutsägbara främmande farsoter."},sec={{t="En onaturlig skörd",b="När upptäcktsresande färdas bland Teldrassils dimhöljda grenar stöter de ibland på märkliga, lysande växter med stora, runda frukter. Med tanke på världsträdets känsliga balans och de märkliga beteenden som öns djurliv nyligen uppvisat måste ovanliga växter undersökas noggrant. Övertygade om att den märkliga växten inte bör ignoreras plockar äventyrarna den strålande skörden för att ta den till någon som känner till vildmarkens växter."},{t="Denalans undersökning",b="Vid Lake Al'Ameth tar den kunnige trädgårdsmästaren och örtkännaren Denalan emot den lysande frukten med både fascination och oro. Han noterar att exemplaret verkar exotiskt och spekulerar i att fröna kan ha kommit från avlägsna länder på andra sidan havet, kanske till och med Eastern Kingdoms. Än mer oroande för Denalan är hur det främmande fröet reagerade med Teldrassils jord. När han planterar fröna i den jord han har förberett stiger fientliga boglings upp ur marken."}},faq={{q="Var hittar man den märkliga fruktväxten?",a="Den märkliga fruktväxten växer vilt i Teldrassils ödemarker, undangömd bland snåren långt från de större bosättningarna. När du undersöker växten får du Glowing Fruit och uppdraget börjar.",al={"var hittar jag växten","den märkliga fruktväxtens plats","hur börjar man glowing fruit"}},{q="Vem är Denalan?",a="Denalan är en örtkunnig Night Elf och botaniker som håller till längs Lake Al'Ameths stränder. Han ägnar dagarna åt att sköta jorden, studera traktens växter och hålla uppsikt över de märkliga miljöförändringar som påverkar Teldrassil.",al={"var finns denalan","denalan npc","vem tar emot glowing fruit"}},{q="Varför lyser frukten?",a="Orsaken till att frukten lyser är inte fastställd. Denalan betraktar den som ett ovanligt exemplar och planerar att undersöka den.",al={"varför lyser frukten","vad är fel på frukten"}},{q="Vad händer när du lämnar frukten till Denalan?",a="Ta den lysande frukten till Denalan vid Lake Al'Ameth för undersökning. Hans fynd och resultatet av överlämningen avslöjas när du återvänder.",al={"vad dyker upp efter uppdraget","bogling-bakhåll"}},{q="Var tror Denalan att växten kommer ifrån?",a="Denalan misstänker att växtens frön kan ha sitt ursprung långt borta på andra sidan Great Sea och ha förts till Kalimdor från Azeroths avlägsna östra kontinent.",al={"var kom fröna ifrån","fruktens ursprung"}},{q="Har uppdraget koppling till andra ekologiska problem på Teldrassil?",a="Ja. Det ingår i Denalans bredare forskning om varför Teldrassils grenar och traktens skogsvarelser, som timberlings, blir alltmer upprörda och onaturliga.",al={"teldrassils fördärv","problem vid lake al'ameth"}}},fx={a8a1e1a2={q="Varför ta den glödande frukten till Denalan?",a="Strange Fruited Plant är en tanklös växt, men dess kusliga sken och bisarra utseende sticker genast ut bland Teldrassils naturliga växter. Du inser att en sådan onaturlig avvikelse måste undersökas och tar därför initiativet att lämna ett exemplar till Denalan vid Lake Al'Ameth. Du vet att botanikern aktivt studerar öns märkliga ekologiska störningar.",al={"varför frukten till denalan","strange fruited plants motiv","varför plocka glödande frukt"}}},fp="17,185,20.306.0,23.373.1,41.158.0,15.190.0,24.85.0,48.147.1,46.137.0,67.161.0"}
P.entries["quest:93036"] = {n="Infiltrating the Cult",s="Infiltrating the Cult är ett uppdrag i Shen'dar Village där en okänd äventyrare får i uppgift att närma sig den lokala missionären Sania Silverstream. Bakom sin fromma fasad värvar Sania anhängare till Al'Aketh, en kult tillägnad vindherren Al'Akir. Uppdraget går ut på att avslöja kultens verkliga planer för bosättningen innan den sköra freden brister.",h="Infiltrating the Cult är ett uppdrag i Shen'dar Village där en okänd äventyrare får i uppgift att närma sig...",kw={"al'aketh","al'akir","alaketh","infiltrating the cult","sania silverstream","shen'dar village","vindherre","vindfurste"},ang={["class:Priest"]="Sania Silverstream utger sig för att vara en lägre prästinna, men hennes tro tillhör en elementarherre snarare än det Heliga Ljuset eller Elune. Sanna präster kommer att känna igen hennes behagliga religiösa fasad som en täckmantel för elementardyrkan.",["class:Rogue"]="Att infiltrera en fientlig kult genom en ovetande värvare passar en skurks talanger inom spionage, bedrägeri och spaning bakom fiendens linjer."},sec={{t="En skör fred",b="I Shen'dar Village håller en orolig vapenvila på att falla samman. Under en tid har de lokala myndigheterna tolererat Sania Silverstreams närvaro. Hon är en självutnämnd missionär som bor bland dem. Hon företräder Al'Akeths orden, en organisation som klär sig i en godartad religiös rörelses skrud samtidigt som den skickar ut vänliga värvare för att locka ovetande anhängare. Byäldste tillät henne att värva enbart för att undvika att provocera kulten till öppen konflikt, men förespeglingen om att kunna leva sida vid sida håller på att blekna."},{t="Bakom missionärens slöja",b="Bakom det diplomatiska spelet och det stillsamma missionsarbetet finns hängivenhet till en uråldrig och farlig makt: Al'Akir vindherren, luftens elementarers härskare. När man närmar sig presenterar sig Sania öppet som en lägre prästinna i Al'Akeths orden. Hon bjuder in blivande invigda att lära sig om deras härskare och lovar dem en plats vid hans bord. Eftersom de bofasta känner henne alltför väl för att kunna undersöka henne säkert, får nykomlingar i byn i uppgift att vinna hennes förtroende och avslöja vad kulten egentligen planerar för Shen'dar."}},faq={{q="Vem är Sania Silverstream?",a="Sania Silverstream är en lägre prästinna i Shen'dar Village som säger sig vara missionär för en religiös orden kallad Al'Aketh. I själva verket värvar hon lokalbefolkningen på ett vänligt och harmlöst sätt till dyrkan av vindherren Al'Akir.",al={"vem är sania","sania silverstreams historia","prästinnan sania"}},{q="Vad är Al'Akeths orden?",a="Al'Aketh är en kult som utger sig för att vara en vanlig religiös rörelse. Bakom sina offentliga missionsaktiviteter vördar de Al'Akir vindherren, luftens elementarherre, och försöker utöka sitt inflytande genom att i det tysta värva anhängare från närliggande bosättningar.",al={"vilka är alaketh","vad är alaketh","alakeths orden"}},{q="Varför har Shen'dar Village tolererat Sania Silverstream?",a="Byäldste har tolererat Sania Silverstreams missionärsnärvaro för att bevara en skör illusion av fred och undvika öppen fientlighet med kulten. Men den oroliga vapenvilan är snabbt på väg att brista, och därför har man beslutat att undersöka henne i hemlighet.",al={"varför låta sania stanna","varför inte döda sania","varför är sania i byn"}},{q="Vem är vindherren Al'Akir?",a="Al'Akir vindherren är elementarherren över himlen, stormarna och luften. Al'Akeths orden vördar honom som sin gudomliga härskare och lovar en plats vid vindherrens bord åt alla som ångrar sig och ansluter sig till deras sak.",al={"vem är vindherren","al'akirs historia","vem är al'akir"}},{q="Varför får du infiltrera kulten i stället för någon från byn?",a="Eftersom du är en okänd nykomling i Shen'dar Village kommer Sania och Al'Aketh inte att misstänka att du arbetar för byns ledare. Du kan närma dig henne under förevändningen att du är en intresserad rekryt utan att väcka misstankar.",al={"varför jag","varför skicka en äventyrare","varför infiltrera kulten"}},{q="Vad planerar Al'Aketh för Shen'dar Village?",a="De lokala ledarna misstänker att Al'Akeths värvningsförsök döljer större och aggressiva ambitioner för Shen'dar Village. Huvudsyftet med att infiltrera kulten är att avslöja dessa hemliga planer innan byns sköra fred kollapsar helt.",al={"kultens planer för byn","vad vill alaketh","alakeths avsikter"}}},fp="21,204,18.424.0,29.388.1,26.197.0,34.244.0,54.210.0,28.192.0,60.218.0,52.181.0"}
P.entries["quest:93065"] = {n="Prepare for Battle",s="Prepare for Battle markerar Peacekeepers mobilisering när de samlar sina styrkor för att marschera ut från staden. Äventyrare kallas till sina sista förberedelser och ska möta Valennia Stormfist i Gustberry Lowlands innan truppen ger sig av.",h="Prepare for Battle markerar Peacekeepers mobilisering när de samlar sina styrkor för att marschera ut från...",kw={"östra vägen","gustberry lowlands","mobilisering","peacekeepers","prepare for battle","valennia stormfist"},ang={["class:Warrior"]="För frontkämpar är mobiliseringen ett avgörande förspel till striden, där utrustningskontroller och leden som formas tillsammans med allierade avgör hur det kommande slaget utvecklar sig."},sec={{t="En kallelse till samling",b="När spänningarna i regionen ökar har det lokala försvarsförbandet Peacekeepers kallat till vapen. Soldater och frivilliga beordras att säkra sin utrustning, göra vapnen redo och samlas för en organiserad marsch genom det omgivande området."},{t="Samlingen i Gustberry Lowlands",b="Uppsamlingsplatsen för expeditionen ligger längs den östra vägen som går norrut från staden in i Gustberry Lowlands. Där genomför samordnaren Valennia Stormfist en sista inspektion och upprop för att säkerställa att alla kämpar är redo innan truppen marscherar in i faran."}},faq={{q="Vem är Valennia Stormfist?",a="Valennia Stormfist samordnar Peacekeepers uppbåd i Gustberry Lowlands. Hon övervakar de sista förberedelserna längs den östra vägen norrut från staden innan styrkorna ger sig av.",al={"vem är valennia stormfist","valennia stormfist","stormfist"}},{q="Vilka är Peacekeepers?",a="Peacekeepers är ett organiserat lokalt militärt förband eller försvarsförband som nu mobiliserar sina styrkor för att möta ett hot som närmar sig utanför staden.",al={"vilka är peacekeepers","peacekeepers","peacekeepers styrka"}},{q="Var ligger Gustberry Lowlands?",a="Gustberry Lowlands är regionens uppsamlingsområde där de lokala försvarsstyrkorna samlas. Det ligger längs vägen norrut från staden.",al={"var ligger gustberry lowlands","gustberry lowlands plats","gustberry lowlands"}},{q="Vad förbereder sig Peacekeepers för?",a="Peacekeepers rustar sig för att marschera ut med full styrka och kallar alla dugliga allierade att kontrollera sin utrustning och samlas vid stadens utkant innan expeditionen ger sig av.",al={"vad förbereder de sig för","varför förbereda sig för strid","vad är det för strid"}},{q="Var ligger mötesplatsen för marschen?",a="Samlingsplatsen ligger längs den östra vägen norrut från staden. Den har valts så att truppen kan formera sig innan marschen ut på fältet.",al={"var ligger samlingsplatsen","var ska man möta valennia","mötesplats"}},{q="Vad händer när alla har samlats?",a="När de har anmält sig gör Valennia Stormfist en sista avstämning med de samlade leden och konstaterar att styrkorna är så redo de kan bli för att marschera ut i faran.",al={"hur avslutas uppbådet","vad säger valennia","vi är så redo vi kan bli"}}},fp="18,208,16.240.0,35.213.0,26.187.0,25.115.0,33.128.0,40.160.0,44.142.0,40.102.0"}
P.entries["quest:93089"] = {n="What Comes Next",s="På Zephras Isle söker High Order din välsignelse inför avresan med sina allierade från Kirin Tor. Deras expedition är beroende av att finna en arkan lösning på öns instabilitet.",h="På Zephras Isle söker High Order din välsignelse inför avresan med sina allierade från Kirin Tor.",kw={"ansirem","dalaran","elaadrin evengale","high order","kirin tor","skycutter","what comes next","zephras isle"},sec={{t="Avresan",b="High Elder Shadowsong har välsignat expeditionen, och förberedelserna är klara. Ansirem har arbetat för att upprätta resor med skycutter mellan Dalaran och Zephras Isle. Nu förbereder sig förtruppen för avfärd. Tala med Elaadrin Evengale när du är redo att lämna ön."}},faq={{q="Vem ska jag tala med innan jag lämnar Zephras Isle?",a="Tala med Elaadrin Evengale när du är redo att lämna Zephras Isle.",al={"vem ska jag tala med","lämna zephras isle","elaadrins avresa"}},{q="Vart är High Order på väg?",a="High Order förbereder en expedition, med transport med skycutter mellan Dalaran och Zephras Isle.",al={"vart är de på väg","high orders resmål","nästa anhalt"}},{q="Vem hjälper High Order?",a="Kirin Tor hjälper High Order. Ansirem har arbetat med transport med skycutter mellan Dalaran och Zephras Isle.",al={"vilka är de allierade","hjälp från kirin tor","high orders vänner"}},{q="Vad söker expeditionen?",a="Expeditionen hoppas finna en arkan lösning som kan ge Zephras Isle stabilitet.",al={"vad letar de efter","arkan lösning","varför lämna ön"}},{q="Vad hände med kulten?",a="Elaadrin säger att kulten har besegrats och att förberedelserna inför expeditionen är klara.",al={"kultens status","är kulten besegrad","hur är det med kulten"}}},fp="15,179,13.274.0,48.70.0,30.101.0,30.117.0,31.83.0,26.91.0"}
P.entries["quest:93090"] = {n="What Comes Next",s="What Comes Next markerar slutet på händelserna på Zephras Isle, när resenärer förbereder sig på att ge sig av genom skyn. Det lokala kult hotet är undanröjt och High Elder Shadowsongs välsignelse är säkrad. Nu öppnas färder med skycutter mellan ön och Mulgore slätter.",h="What Comes Next markerar slutet på händelserna på Zephras Isle, när resenärer förbereder sig på att ge sig av...",kw={"ayessa dawnsinger","earthen ring","high elder shadowsong","mulgore","muln","skycutter","what comes next","zephras isle"},ang={["class:Shaman"]="Expeditionen ordnar direkta färder till Mulgore för att knyta kontakt med Earthen Ring, den högt aktade shamanorganisationen som verkar för att lugna Azeroths elementandar.",["race:Tauren"]="Målet på andra sidan skyn är Mulgore, taurenernas förfäders hemland där Earthen Ring bedriver sin verksamhet."},sec={{t="Avfärd från Zephras Isle",b="När den lokala kulten besegrats och tryggheten återvänt till Zephras Isle har High Elder Shadowsong välsignat den fortsatta färden. Expeditionen på ön blickar nu bortom dess stränder och riktar fokus mot Kalimdors öppna himmel. Ayessa Dawnsinger samordnar den sista avfärden för dem som är redo att lämna ön bakom sig."},{t="Skycutters till Mulgore",b="Det krävdes noggranna förberedelser för att ordna färder från ön. Muln arbetade målmedvetet för att säkra stabila skycutterfärder mellan Zephras Isle och Mulgore. Efter lyckade provfärder har en förtrupp redan tagit sig över och väntar på andra sidan, redo att ta kontakt med shamanerna i Earthen Ring."}},faq={{q="Vad är uppdraget What Comes Next?",a="What Comes Next är ett övergångsuppdrag som markerar avfärden från Zephras Isle. Efter att ha fått High Elder Shadowsongs välsignelse och sett till att kulten besegrats förbereder sig resenärerna på att färdas med skycutter till Kalimdors fastland.",al={"vad är what comes next","uppdraget what comes next","vad är det här för uppdrag"}},{q="Vart reser expeditionen?",a="Skycutterfärden går mellan Zephras Isle och Mulgore, ett gräsbevuxet höglandsområde mitt i Kalimdor där Earthen Ring har sitt hem och där expeditionens förtrupp redan väntar.",al={"vart ska vi","skycutter destination","vart flyger skycutter"}},{q="Vem är Ayessa Dawnsinger?",a="Ayessa Dawnsinger samordnar avfärden från Zephras Isle. Hon bekräftar att förberedelserna är klara, att provflygningarna har lyckats och att expeditionen har High Elder Shadowsongs välsignelse att ge sig av.",al={"vem är ayessa dawnsinger","ayessa dawnsinger","ayessa"}},{q="Vem är Muln?",a="Muln är en allierad som arbetade målmedvetet för att ordna stabila skycutterfärder mellan Zephras Isle och Mulgore. Han genomförde provfärder för att säkerställa en trygg resa genom skyn.",al={"vem är muln","muln skycutter","muln zephras"}},{q="Vad är Earthen Ring?",a="Earthen Ring är en sammanslutning av shamaner som strävar efter att upprätthålla harmoni mellan elementandar. Under expeditionen är de kontaktpersoner och värdar som välkomnar resenärerna till Mulgore.",al={"vad är earthen ring","earthen ring mulgore","vilka är earthen ring"}},{q="Varför lämnar expeditionen Zephras Isle?",a="När den lokala kulten besegrats och High Elder Shadowsongs välsignelse säkrats är syftet med att stanna isolerade på Zephras Isle uppnått. Expeditionen kan nu fortsätta till fastlandet.",al={"varför lämna zephras isle","är zephras färdigt","varför åka till mulgore"}}},fp="15,214,27.332.0,21.231.0,34.191.0,33.185.0,25.184.0,12.149.0,25.166.0,43.176.0"}
P.entries["quest:931"] = {n="The Shimmering Frond",s="Bland rötterna och trädkronorna i Teldrassil har en märklig växt upptäckts, skimrande av ett utomvärldsligt ljus. Resenärer inser hur sällsynt den är och tar ett exemplar till botanikern Denalan vid Lake Al'Ameth för att ta reda på varifrån den kommer.",h="Bland rötterna och trädkronorna i Teldrassil har en märklig växt upptäckts, skimrande av ett utomvärldsligt...",kw={"botanik","denalan","lake al'ameth","shimmering frond","spirande bladskott","märklig växt med bladskott","swamp of sorrows","teldrassil"},ang={["class:Druid"]="Druider som värnar om det stora trädets balans håller uppsikt över främmande växtliv som förs in i Teldrassils känsliga, unga trädkronor.",["profession:Herbalism"]="Örtmästare och växtentusiaster uppskattar det botaniska mysteriet i att hitta en våtmarksväxt som frodas tusentals kilometer från sitt ursprungliga ekosystem.",["race:NightElf"]="För Night Elf-folket som vårdar sitt nya hem ger Denalans experiment viktiga insikter i hur motståndskraftig Teldrassils jord verkligen är."},sec={{t="Ett märkligt sken",b="När uppmärksamma resenärer vandrar genom Teldrassils grönskande grenar kan de stöta på en märklig växt med bladskott. Till skillnad från skogens vanliga växtlighet fångar dess bladskott ljuset och skimrar med ett pulserande, slingrande sken. Den onaturliga närvaron fångar blicken hos alla som värnar om öns känsliga, unga ekosystem."},{t="Denalans upptäckt",b="När sticklingen förs till botanikern Denalan vid Lake Al'Ameth avslöjas en oväntad sanning. Denalan identifierar växten som ett exotiskt exemplar som inte hör hemma i norra Kalimdor. Han stötte senast på en sådan för flera årtionden sedan, under en resa till det avlägsna Swamp of Sorrows i Eastern Kingdoms. Han fascineras av att ett frö kunnat färdas över havet och växa sig så stort på Världsträdet, och börjar genast odla och undersöka exemplaret."}},faq={{q="Var kommer den märkliga växten ursprungligen ifrån?",a="Enligt botanikern Denalan hör växten hemma i Swamp of Sorrows, en dimmig våtmark långt åt sydost i Eastern Kingdoms. Han hade inte sett ett levande exemplar sedan han besökte träskmarkerna flera årtionden tidigare.",al={"bladskottets ursprung","varifrån kommer bladskottet","träskväxt"}},{q="Vem är Denalan?",a="Denalan är en vetgirig Night Elf-botaniker och örtmästare som håller till nära Lake Al'Ameths strand på Teldrassil. Han ägnar sin tid åt att studera och vårda Teldrassils växande växtliv, och experimenterar ofta med främmande frön och planteringskärl.",al={"denalans historia","vem är denalan"}},{q="Varför växer den här växten på Teldrassil?",a="Det förblir ett ekologiskt mysterium. Denalan förundras över hur ett frö kunnat färdas hela vägen från Eastern Kingdoms över Stora havet och ändå slå rot och frodas till ett så stort exemplar i Teldrassils bördiga jord.",al={"hur kom den till teldrassil","varför är bladskottet här"}},{q="Vad händer efter att man ger bladskottet till Denalan?",a="Denalan placerar genast exemplaret i sin planteringslåda vid Lake Al'Ameth för att utföra tester. Hans odling får snart flera bladskott att spira, vilket leder till ytterligare studier av den exotiska floran.",al={"nästa uppdrag","denalans test","spirande bladskott"}},{q="Orsakar den här växten fördärv i Teldrassil?",a="Nej. Mycket av Teldrassils djurliv påverkas av ett subtilt fördärv från onda krafter, men den här växten verkar bara vara en ovanlig, malplacerad exotisk sort, inte en källa till fördärv.",al={"är bladskottet fördärvat","fördärvad växt"}}},fx={add2b0dd={q="Varför ta en kvist från Strange Fronded Plant till Denalan?",a="Växten har inget medvetet syfte; den är bara ett ovanligt, pulserande exemplar som växer vilt bland Teldrassils grenar. Du känner igen dess märkliga, skimrande aura som något främmande och kanske onaturligt för det stora trädet, så du skördar ett skott åt Denalan, botanikern vid Lake Al'Ameth som studerar sällsynta växter.",al={"strange fronded plants motiv","varför ta skottet till denalan","varför ta skottet"}}},fp="20,168,14.188.0,19.318.1,50.139.0,15.180.0,40.174.0,47.151.1,47.107.0"}
P.entries["quest:93159"] = {n="The Strange Hermit",s="The Strange Hermit är ett introduktionsuppdrag i Shadowgale Forest om en blyg, huvbärande enstöring som bor långt från civilisationen. Efter lång tids isolering söker eremiten samtal och delar med sig av glimtar från sitt enkla, handgjorda liv och sitt band till de sjungande skogsandarna i trakten.",h="The Strange Hermit är ett introduktionsuppdrag i Shadowgale Forest om en blyg, huvbärande enstöring som bor...",kw={"skogsandar","handgjord","eremit","huvbärande gestalt","ensamvarg","shadowgale forest","märklig eremit"},ang={["class:Druid"]="Druider som står i samklang med naturen kan uppskatta eremitens kontakt med traktens skogsandar, även om hans oförmåga att verkligen samtala med dem skiljer sig från en druids djupare förbindelse.",["profession:Engineering"]="Hantverkare och uppfinnare kan känna igen sig i hur eremiten finner ro i att bygga saker för hand och inreda sitt ensliga hem."},sec={{t="En enstöring i skogen",b="Djupt inne bland Shadowgale Forests avskilda trädkronor bor en gåtfull, huvbärande enstöring som bara är känd som The Strange Hermit. Långt från bebodda samhällen och vanliga handelsvägar tillbringar han dagarna i stilla ensamhet bland träden. När du närmar dig märks det på hans stapplande tal och nervösa uppträdande hur länge han har levt utan vanligt umgänge. Till och med en enkel hälsning blir en obekant utmaning."},{t="Andar och enkla ting",b="Trots sitt ensamma liv hävdar eremiten att han har allt sällskap och alla förnödenheter han behöver. Han berättar att han bodde någon annanstans innan han slog sig ner här och valde ett liv omgiven av handgjorda prydnader och skogens andar. De vilda andarna sjunger ofta för honom, men han medger att melodiska körer inte helt kan ersätta samtal med någon som verkligen kan svara."}},faq={{q="Vem är den märkliga eremiten?",a="The Strange Hermit är en excentrisk, huvbärande person som lever isolerad i Shadowgale Forest. Han är ovan vid regelbundet umgänge och tillbringar sin tid med att sköta handgjorda tillhörigheter och umgås med traktens skogsandar i stället för med andra människor.",al={"märklig eremit","eremitens identitet","vem är eremiten"}},{q="Var bor eremiten?",a="Eremiten har sitt hem avskilt, djupt bland träden i Shadowgale Forest, långt från de vanliga vägarna där få resenärer någonsin vandrar.",al={"var är eremiten","shadowgale forests plats","eremitens område"}},{q="Varför lever eremiten ensam?",a="Han medger att han bodde på en helt annan plats innan han drog sig tillbaka till skogen. Han är mycket fåordig om sitt förflutna, men valde ett stilla liv omgiven endast av sådant han själv byggt och skogens vilda andar.",al={"varför är eremiten ensam","eremitens isolering","eremitens bakgrund"}},{q="Kan eremiten tala med skogsandar?",a="Han ser traktens skogsandar som sina följeslagare, även om de inte för vanliga samtal. I stället sjunger de för honom, vilket han tycker om, även om sången inte ger samma djup i samtalet som med en annan dödlig.",al={"eremiten talar med andar","shadowgale forests skogsandar","eremitens vänner"}},{q="Vad har eremiten byggt i skogen?",a="Eremiten nämner att han har flera handgjorda föremål och konstruktioner som håller honom sysselsatt. Han finner ro och tillfredsställelse i enkla, handgjorda ägodelar.",al={"eremitens hantverk","vad byggde eremiten"}},{q="Vad händer under uppdraget ”The Strange Hermit”?",a="Uppdraget går ut på att närma sig den nervöse eremiten i Shadowgale Forest, inleda ett vänligt samtal och höra vad han är villig att berätta om sitt tillbakadragna liv.",al={"uppdraget the strange hermit","tala med eremiten"}}},fp="18,192,22.261.0,25.245.0,26.194.0,27.117.0,36.180.0,41.148.0,40.140.0,51.115.0"}
P.entries["quest:93160"] = {n="The Forest's Bounty",s="The Forest's Bounty är ett lokalt uppdrag i Shadowgale Forest där en försiktig örtletare ber om hjälp att samla fallna ekollon. Glupska rovfåglar stryker omkring i skogens djupare delar, så det är alltför farligt att plocka dem utan en äventyrares beskydd. Ekollonen rostas sedan till en smakrik måltid från skogen.",h="The Forest's Bounty är ett lokalt uppdrag i Shadowgale Forest där en försiktig örtletare ber om hjälp att...",kw={"ekollon","matlagning","plocka vilda växter","rovfågel","shadowgale acorns","shadowgale forest","the forest's bounty"},ang={["profession:Cooking"]="Att samla Shadowgale Acorns visar hur lokala vilda nötter kan rostas till enkel skogsmat, vilket gör dem särskilt intressanta för matintresserade örtletare."},sec={{t="En farlig plocktur",b="En försiktig örtletare som söker mat i Shadowgale Forest hamnar i knipa. Ekollon ligger utspridda över skogsmarken, men rovfågelslika varelser stryker omkring bland träden. Efter att ha samlat allt som fallit nära tryggheten är örtletaren beroende av förbipasserande resenärer som vågar sig in i de vildare dungarna, så att ingen av dem behöver gå hungrig."},{t="Skörden rostas",b="Shadowgale Acorns ger rejält med näring åt den som vet hur de ska tillagas. Råa är de bittra eller hårda, men när de rostas över en sprakande eld blir skogens vilda skörd en mustig, rostad godsak. Att trotsa rovfåglarna bland träden förvandlar ett enkelt skogssökande till en varm måltid ute i vildmarken."}},faq={{q="Vem ber dig att samla ekollonen?",a="En nervös örtletare som vilar nära Shadowgale Forest ber om hjälp. Hen har samlat alla ekollon i närheten som är säkra att plocka och behöver nu en tålig äventyrare som vågar sig längre in i skogen, där farliga djur strövar omkring.",al={"vem ger uppdraget the forest's bounty","vem vill ha ekollon","uppdragsgivare the forest's bounty"}},{q="Var finns ekollonen?",a="Shadowgale Acorns ligger utspridda på marken under trädkronorna i Shadowgale Forest. Den som letar måste söka på skogsmarken och samtidigt hålla utkik efter fientliga rovdjur bland träden.",al={"var finns shadowgale acorns","ekollonens plats","ekollon i shadowgale forest"}},{q="Varför är det farligt att samla ekollon här?",a="Rovfåglar stryker omkring på skogsmarken. Dessa aggressiva varelser gör det mycket farligt för vanligt folk utan stridsträning att ge sig långt från lägret och försvara sig.",al={"varför är shadowgale forest farlig","vad är rovfåglar","varför är det farligt att samla ekollon"}},{q="Vad används ekollonen till?",a="Ekollonen är en mättande källa till vildmarksmat. När de har samlats in ska de rostas över en eld till ett varmt, nötigt mellanmål att dela med dem som vågar trotsa skogens bestar.",al={"vad används shadowgale acorns till","rostade ekollon","varför samla ekollon"}},{q="Vad är det för rovfågelliknande varelser som nämns i skogen?",a="Uppdragsgivaren beskriver dem som farliga ”rovfågelsgrejer” som jagar i Shadowgale Forest. Dessa fågel- eller reptillika rovdjur är tillräckligt stora och vildsinta för att se en oförsiktig resenär som sin nästa måltid.",al={"vad är en rovfågelsgrej","rovfåglar i shadowgale forest","rovfåglar i skogen"}},{q="Hur tillagas ekollonen?",a="Ekollonen är hårda eller bittra när de plockas från marken, men örtletaren påpekar särskilt att Shadowgale Acorns blir en utsökt godsak när de rostas ordentligt över värme.",al={"går det att äta shadowgale acorns råa","hur tillagar man shadowgale acorns","äta skogsekollon"}}},fp="19,164,23.292.0,20.236.0,34.162.0,27.132.0,40.133.0,29.128.0,59.181.0,39.99.0"}
P.entries["quest:93165"] = {n="Mercy Falls on Deaf Ears",s="Mercy Falls on Deaf Ears är en belöning som utlovas av en sörjande enklav som söker våldsam hämnd på Al'Aketh-kulten. Efter en fruktansvärd tragedi som kultisterna orsakat lovar enklaven mynt och tillgång till Nightclaws dolda kunskap i utbyte mot troféer från deras stupade fiender. Den som antar uppdraget kastas rakt in i konflikten som sprider sig genom Shadowgale Forest och de omkringliggande områdena.",h="Mercy Falls on Deaf Ears är en belöning som utlovas av en sörjande enklav som söker våldsam hämnd på...",kw={"al'aketh","blodsfejd","kultister","öron","gustberry lowlands","mercy falls on deaf ears","nightclaw","shadowgale forest","shrine of akir"},sec={{t="Blod för blod",b="Fejden mellan Nightclaw-enklaven och Al'Aketh-kultisterna är bitter och skoningslös. Efter en ospecificerad men förödande tragedi som drabbade enklaven har de överlevande gett upp allt hopp om fredlig försoning. För att hämnas sina fallna fränder vänder de sig till kringvandrande äventyrare och legosoldater och kräver våldsam vedergällning. I utbyte mot att fälla kultisterna och ta deras öron som dystra bevis på dådet erbjuder enklaven kalla mynt och utsikten till större förtroende."},{t="Hotet från Al'Aketh",b="Al'Aketh verkar i flera vildmarksområden och sprider sitt inflytande genom Gustberry Lowlands, Shadowgale Forests mörka skogar och det forntida Shrine of Akir. Deras mörka sedvänjor och fanatiska natur har väckt lokalbefolkningens hat. Genom att angripa deras läger i dessa områden försvagar du kultens närvaro och vinner Nightclaws gunst. Denna hemlighetsfulla grupp håller sina egna esoteriska mysterier nära tills en främling bevisar sin lojalitet."}},faq={{q="Vad är Mercy Falls on Deaf Ears?",a="Mercy Falls on Deaf Ears är ett uppdrag där en äventyrare anlitas för att hämnas på Al'Aketh-kultisterna efter en katastrofal attack mot en lokal enklav. Uppdragsgivaren kräver vedergällning: äventyrarna ska döda kultister och återvända med deras avhuggna öron som obestridliga bevis på dödsfallen, i utbyte mot mynt och förtroende.",al={"uppdraget mercy falls on deaf ears","vad är det här för uppdrag","översikt över uppdraget"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är en sekt av förbannade kultister som är kända för att föra olycka och tragedi till närliggande bosättningar. De har en fientlig närvaro i Gustberry Lowlands, Shadowgale Forest och Shrine of Akir och väcker öppna blodsfejder med dem som bor i de omgivande områdena.",al={"vilka är alaketh","alaketh-kultisternas bakgrund","vilka är al'aketh"}},{q="Var hittar man Al'Aketh-kultister?",a="Al'Aketh-kultister finns i tre olika områden: bland Shadowgale Forests täta trädkronor, på den heliga marken kring Shrine of Akir och runtom i Gustberry Lowlands. Om du dödar kultister i något av dessa områden får du de bevis som den sörjande enklaven kräver.",al={"var finns alaketh-kultister","alakeths platser","var hittar man kultister"}},{q="Varför samlar uppdragsgivaren på kultisternas öron?",a="Avhuggna öron är påtagliga och obestridliga bevis på dödsfall i en brutal konflikt i vildmarken, där blod måste betalas med blod. Eftersom enklaven hyser ett djupt hat mot Al'Aketh efter en svår tragedi kräver de fysiska troféer för att försäkra sig om att varje utbetald belöning motsvarar en död kultist.",al={"varför öron","varför vill de ha kultisternas öron","öron som bevis"}},{q="Vilka är Nightclaw?",a="Nightclaw är en hemlighetsfull enklav som har lidit stora förluster till följd av Al'Aketh-kultens härjningar. De är misstänksamma mot främlingar, men besitter välbevarade hemligheter och kunskap. Om utomstående bevisar sin lojalitet genom att krossa deras kultistfiender får de så småningom tillgång till gruppens innersta mysterier.",al={"nightclaw-fraktionen","vilka är nightclaw","nightclaws hemligheter och bakgrund"}},{q="Vilken tragedi orsakade Al'Aketh?",a="Uppdragsgivaren berättar om en stor tragedi som Al'Aketh direkt vållade Nightclaw-enklaven och som utlöste en oförsonlig blodfejd. Belöningen nämner inga specifika dödsoffer eller detaljer, men händelsen var så fasansfull att de överlevande kräver total hämnd utan nåd.",al={"vad gjorde alaketh","vad hände med enklaven","alaketh-tragedin"}},{q="Vilka hemligheter bär Nightclaw på?",a="Nightclaws hemligheter hålls inom enklaven och avslöjas inte genast för utomstående. Uppdragsgivaren lovar att äventyrare som fortsätter hjälpa till i kampen mot Al'Aketh och visar sig vara sanna vänner så småningom får tillgång till denna dolda kunskap.",al={"nightclaws hemligheter","vilka hemligheter har nightclaw","vad avslöjar nightclaw"}}},fp="24,329,15.361.0,19.392.0,33.168.0,21.257.0,37.169.0,46.180.0,22.231.0,36.206.0,33.234.0"}
P.entries["quest:93172"] = {n="Free the Hollows",s="Free the Hollows är ett uppdrag i Shadowgale Forest, där spöklika andar som kallas vindhåligheter dröjer kvar bland forntida ruiner. Fångade av en uråldrig tragedi hemsöker deras sorgsna sång skogarna runtomkring, tills någon befriar dem.",h="Free the Hollows är ett uppdrag i Shadowgale Forest, där spöklika andar som kallas vindhåligheter dröjer kvar...",kw={"free the hollows","spöken","håligheter","ruiner","shadowgale","shadowgale forest","vindhåligheter"},ang={["class:Druid"]="Oroliga andar som dröjer kvar i Shadowgale Forest är en onaturlig störning i vildmarken som kräver balans och befrielse.",["class:Priest"]="Vindhåligheterna är sorgsna skepnader som fångats av tragedi. Att förgöra dem är därför en barmhärtighetshandling som befriar själar bundna i evig vånda.",["race:NightElf"]="Öns lokala alver har länge anat att Shadowgale Forest är hemsökt och oroats av de tragiska andar som dröjer kvar, bundna till deras forntida ruiner."},sec={{t="Hemsökelser i Shadowgale",b="Alver som bor över hela ön har länge betraktat Shadowgale Forest som en hemsökt lund, och deras vidskepelse har grund i verkligheten. Djupt inne i skogen, i nordost, ligger gamla stenruiner där skepnader kända som vindhåligheter driver omkring bland snåren utan slut. Andarna utstrålar ingen fientlighet, utan en djup sorg, fångade av tyngden från den katastrof som drabbade ruinerna för länge sedan."},{t="Den sorgsna sången",b="Under stilla nätter berättar resenärer nära ruinerna att de hör en märklig, eterisk sång som driver med vinden. Den liknar ingen känd sång från dödliga och bär på en djup melankoli som oroar alla som hör den. Med tron att det är en plåga att låta skuggorna vara fångade i sin eviga klagosång söker medkännande resenärer upp vindhåligheterna för att förstöra deras spektrala bojor och skänka dem frid."}},faq={{q="Vad är vindhåligheter?",a="Vindhåligheter är sorgsna, spöklika andar som hemsöker gamla alvruiner i nordöstra Shadowgale Forest. Fångade av någon uråldrig tragedi frambringar de en kuslig, sorgsen sång som ekar bland träden om natten.",al={"vad är vindhåligheter","håligheternas bakgrund","vad är håligheterna"}},{q="Varför måste vindhåligheterna befrias?",a="Uppdragsgivaren tror att andarna är fångade i evig sorg efter en fruktansvärd katastrof. Att förstöra vindhåligheterna ses som en handling av befrielse och barmhärtighet, som frigör deras dröjande skepnader från banden till ruinerna.",al={"varför befria håligheter","varför döda håligheter","syftet med free the hollows"}},{q="Var hittar man andarna?",a="Shadowgale Forest är en skogsklädd ö som bebos av alver. Där finns forntida ruiner i nordost, där de spöklika håligheterna samlas.",al={"var ligger shadowgale forest","ruinerna i shadowgale","ruinernas plats"}},{q="Vad är den märkliga sången som hörs i skogen?",a="Vindhåligheternas sång beskrivs som en oerhört sorgsen melodi som inte liknar någon vanlig sång. Man tror att den föddes ur deras tragiska död och ändlösa fångenskap i öns ruiner.",al={"håligheternas sång","spöksång","varför sjunger spöken"}},{q="Vem ber dig befria håligheterna?",a="Uppgiften erbjuds av en observatör på ön som känner medlidande med de fångade andarna och märker att de lokala alverna är rädda för den hemsökta skogen.",al={"vem ger free the hollows","uppdragsgivare för free the hollows"}},{q="Vad hände vid ruinerna som skapade håligheterna?",a="Även om de exakta detaljerna har fallit i glömska vet lokalbefolkningen att en fruktansvärd händelse inträffade vid ruinerna i nordost och band andarna till platsen i ett evigt, sorgset kretslopp.",al={"vad hände vid ruinerna i shadowgale","varför är ruinerna hemsökta"}}},fp="16,173,23.290.0,17.315.0,26.184.0,41.184.0,28.125.0,47.176.0,33.121.0,49.152.0"}
P.entries["quest:93176"] = {n="My Little Friends",s="En skötare erbjuder dig ett paket för att börja studera tre små varelser. Entomology Starter Kit innehåller anteckningar och material för arbetet.",h="En skötare erbjuder dig ett paket för att börja studera tre små varelser.",kw={"arbor tarantula","entomologi","flesh picker","hay weevil specimen","menageri","my little friends","startsats"},sec={{t="En skötares erbjudande",b="En skötare som har ägnat många timmar åt att studera ett litet menageri erbjuder sig att dela sin hobby med dig. Paketet innehåller anteckningar och material för att komma igång. Med Entomology Starter Kit kan du leta efter en Arbor Tarantula, ett Hay Weevil Specimen och en Flesh Picker."}},faq={{q="Vad vill skötaren att jag ska göra?",a="Använd Entomology Starter Kit för att hitta och fånga en Arbor Tarantula, ett Hay Weevil Specimen och en Flesh Picker.",al={"my little friends uppdrag","vad ska jag samla"}},{q="Vad finns i paketet?",a="Paketet innehåller anteckningar och material för att komma igång med skötarens hobby.",al={"startsatsens innehåll","vad finns i paketet"}},{q="Vad studerar skötaren?",a="Skötaren studerar anatomin, kosten och de sociala ritualerna hos varelserna i ett litet menageri.",al={"litet menageri","vad studerar han"}},{q="Vad händer om jag tappar bort startsatsen?",a="Skötaren säger att du kommer att behöva köpa ett nytt paket för en liten avgift.",al={"borttappad startsats","ersätta startsatsen"}}},fp="17,141,18.256.0,35.111.0,23.86.0,28.96.0,31.74.0"}
P.entries["quest:932"] = {n="Twisted Hatred",s="Twisted Hatred är ett hemligt uppdrag från Tallonkai Swiftroot i Teldrassil. Han ber betrodda hjältar ta sig in i Fel Rocks grotta och döda Lord Melenas, en satyr som samlar de lokala grell till en organiserad, korrumperande styrka farligt nära nattalvernas bosättningar.",h="Twisted Hatred är ett hemligt uppdrag från Tallonkai Swiftroot i Teldrassil.",kw={"fel rock","grell","lord melenas","satyr","tallonkai swiftroot","teldrassil","twisted hatred"},ang={["class:Druid"]="Melenas och hans korrumperade grell vid Fel Rock förgiftar den sköra balansen i Teldrassils nyvuxna vildmark.",["race:NightElf"]="Varje satyr är en forntida påminnelse om hur dina förfäder föll offer för demoniska ambitioner. Att döda Lord Melenas är både en plikt mot världsträdet och en botgöring för dina förfäder."},sec={{t="En bitter skam",b="För nattalverna är satyrer ett levande minne av ett forntida svek. De föddes ur Highborne som överlämnade sig åt Burning Legion under War of the Ancients och är getbenta demoner, en smärtsam och bestående skamfläck i kaldoreis historia. Att en satyr skulle etablera ett avskyvärt fäste just här i Teldrassil, det unga världsträdet som skulle vara en fristad, ses av lokala försvarare som Tallonkai Swiftroot som en stor skam."},{t="Hotet vid Fel Rock",b="Norr om stigarna i närheten ligger Fel Rock, ett korrumperat grottsystem fullt av vilda grell. Lord Melenas har samlat dessa naturligt kaotiska varelser till en fientlig, organiserad styrka under sin mörka vilja. Tallonkai fruktar vad satyren tänker släppa lös bland världsträdets grenar och kräver att Melenas dödas snabbt, tyst och beslutsamt. Ta med hans avhuggna huvud tillbaka."}},faq={{q="Vem är Lord Melenas?",a="Lord Melenas är en satyr som tagit grottan Fel Rock i norra Teldrassil i besittning. Han leder en skara aggressiva grellkrigare och smider planer på att sprida korrumpering över hela världsträdet.",al={"lord melenas","vem är melenas","bossen i fel rock"}},{q="Var hittar jag Lord Melenas?",a="Han håller till djupt inne i Fel Rock, ett taggigt grottsystem norr om Dolanaar i Teldrassil, omgiven av grell och andra korrumperade varelser.",al={"melenas plats","var är melenas","hur hittar man fel rock"}},{q="Varför vill Tallonkai Swiftroot hålla det här hemligt?",a="Satyrer representerar ett fasansfullt, forntida kapitel i nattalvernas historia. De svek sitt folk under War of the Ancients. Att en satyr lurar så fräckt i hjärtat av det nyplanterade världsträdet ses som en fullständig skam som Tallonkai helst vill hantera utan att skapa allmän panik.",al={"varför hemligt","varför måste det här stanna mellan oss","tallonkai hemlighet"}},{q="Vilken relation har satyrer till grell?",a="Grell är små, busiga och naturligt korrumperade vilda varelser som finns över hela Teldrassil. Satyrer är listiga och till sin natur demoniska, så de skrämmer eller tvingar gärna dessa mindre varelser att tjäna sina avskyvärda mål.",al={"grell och satyrer","varför följer grell melenas","satyrers koppling till grell"}},{q="Varför finns det satyrer på Teldrassil över huvud taget?",a="Teldrassil växte upp för bara några år sedan. Trots druidernas förhoppningar om en ren fristad kröp korrumpering och mörka varelser snabbt in på ön. Satyrer smög sig in och etablerade fästen på skuggiga platser som Fel Rock.",al={"satyrer på teldrassil","hur kom satyrerna hit","korrumpering av teldrassil"}},{q="Vem är Tallonkai Swiftroot?",a="Tallonkai Swiftroot är en nattalvsväktare stationerad nära Dolanaar. Han håller utkik efter nya hot mot Teldrassil och ger äventyrare i uppdrag att oskadliggöra närliggande fickor av korrumpering.",al={"tallonkai","vem ger uppdraget twisted hatred"}}},fx={["84ee0888"]={q="Varför behöver Tallonkai Swiftroot Melenas' Head?",a="Tallonkai Swiftroot ber om Lord Melenas avhuggna huvud som obestridligt bevis på att satyren verkligen har dödats. När Lord Melenas är död och huvudet är i hans hand kan Tallonkai vara säker på att det vidriga hotet alldeles intill Shadowglen har undanröjts i hemlighet. Då kan han lämna den förödmjukande saken bakom sig utan att väcka de äldstes oro.",al={"melenas heads syfte","varför ta tillbaka melenas head","vad används melenas head till"}}},fp="14,179,17.327.0,22.331.0,20.167.0,30.123.0,51.210.0,50.167.0,54.221.0,27.165.0"}
P.entries["quest:93225"] = {n="Carved Centaur Totems",s="Gurda Wildmane tror att snidade totemer kan hjälpa henne vinna Gelkis- eller Magramklanens gunst. Hon behöver äkta totemer från kentaurklaner runt om i Desolace.",h="Gurda Wildmane tror att snidade totemer kan hjälpa henne vinna Gelkis- eller Magramklanens gunst.",kw={"snidade kentaurtotemer","kentaurvaluta","desolace","gelkis","ghost walker post","gurda wildmane","magram"},sec={{t="En kentaurvaluta",b="Gurda Wildmane vid Ghost Walker Post har sett kentaurklaner träffas för att handla utanför sina bosättningar. Hon har sett dem använda snidade totemer som valuta. Nu tror hon att en stor bunt kan beveka Gelkis eller Magram, men totemerna hon har snidat kanske inte verkar äkta. Därför ber hon dig hämta äkta exemplar åt henne."}},faq={{q="Vad vill Gurda ha?",a="Gurda Wildmane ber dig hämta äkta snidade kentaurtotemer åt henne.",al={"gurdas begäran","vad behöver wildmane"}},{q="Varför behöver hon snidade totemer?",a="Gurda tror att en stor bunt kan hjälpa henne vinna Gelkis- eller Magramklanens gunst.",al={"vad ska totemerna användas till","varför totemer"}},{q="Var använder kentaurerna totemerna?",a="Gurda har sett kentaurer från olika klaner träffas utanför sina bosättningar och handla med snidade totemer som valuta.",al={"kentaurhandel","var totemer"}},{q="Var hittar jag Gurda Wildmane?",a="Gurda Wildmane finns vid Ghost Walker Post.",al={"gurdas plats","wildmane vid ghost walker"}},{q="Vilka kentaurklaner är inblandade?",a="Gurda hoppas att en bunt totemer ska vinna antingen Gelkis eller Magrams gunst.",al={"gelkis magram","vilka klaner"}}},fp="21,157,18.320.0,21.69.0,32.79.0,32.118.0,32.39.0,33.84.0"}
P.entries["quest:933"] = {n="Crown of the Earth",s="Crown of the Earth är ett Alliance-uppdrag som Corithras Moonrage ger i Dolanaar. Han ber dig hämta vatten från månbrunnen nära Pools of Arlithrien, ett område som hotas allt mer av vansinniga Gnarlpine-furbolger. När du slutför uppdraget får du veta hur Arch Druid Fandral Staghelm samlade nattalverna för att resa Teldrassil efter Malfurion Stormrages försvinnande.",h="Crown of the Earth är ett Alliance-uppdrag som Corithras Moonrage ger i Dolanaar.",kw={"corithras moonrage","dolanaar","fandral staghelm","gnarlpine","malfurion stormrage","pools of arlithrien","tourmaline phial"},ang={["class:Druid"]="Cenarion Circles splittring under Fandral Staghelms ledarskap blir tydligare när Corithras berättar om det desperata försöket att återfå den forntida odödligheten.",["race:NightElf"]="Den här delen av din resa förklarar den omstridda politiska drivkraft som ledde till att Teldrassil skapades efter Malfurions plötsliga försvinnande."},sec={{t="En farlig månbrunn",b="Corithras Moonrage ber dig ta en turmalinflaska till en månbrunn sydost om ingången till Darnassus, vid stränderna kring Pools of Arlithrien. Resan är långt ifrån lugn. De en gång fridfulla Gnarlpine-furbolgerna har plötsligt gripits av våldsam vrede. De överfaller resande och trakasserar Sentinels patruller i hela området. Tidiga rapporter avfärdade det som enstaka skärmytslingar, men hotet har vuxit och hemsöker nattalvernas nya hem."},{t="Fandral Staghelms ambition",b="När du lämnar över den fyllda flaskan berättar Corithras viktig historia om Teldrassils skapelse. Efter det tredje kriget försvann Shan'do Malfurion Stormrage och lämnade Cenarion-druiderna utan ledare och splittrade. I hans frånvaro tog Arch Druid Fandral Staghelm över ledarskapet. Staghelm övertygade de äldstes krets i Darkshore om att nattalverna inte hade råd att sörja sysslolösa. De behövde återfå sin förlorade odödlighet och läka sin civilisation genom att plantera ett enormt nytt världsträd."}},faq={{q="Var finns månbrunnen i det här uppdraget?",a="Månbrunnen ligger sydost om huvudingången till Darnassus, vid Pools of Arlithriens södra stränder.",al={"månbrunnen vid arlithrien","månbrunnens plats","var fyller man flaskan"}},{q="Varför anfaller Gnarlpine-furbolgerna?",a="Gnarlpine-folket var traditionellt ett fridfullt björnmänniskosläkte, men ett mörkt, tanklöst raseri har nyligen drabbat dem över hela Teldrassil. Sentinels avfärdade först de tidiga angreppen som enstaka händelser, men fördärvet har spridit sig snabbt och gjort dem till ett ständigt hot mot närliggande bosättningar och patruller.",al={"furbolger vansinniga","gnarlpine aggressiva","varför anfaller furbolgerna"}},{q="Vad hände med Malfurion Stormrage?",a="Shan'do Malfurion Stormrage försvann utan förklaring efter det tredje kriget. Än i dag vet varken Cenarion-druiderna eller nattalvernas ledare vad som blev av honom.",al={"var är malfurion","vad hände med stormrage","malfurion försvunnen"}},{q="Vem beslutade att plantera Teldrassil?",a="När Malfurion var försvunnen tog Arch Druid Fandral Staghelm på sig att vägleda druiderna. Han övertalade de äldstes krets i Darkshore att stödja resandet av ett nytt världsträd. Han hävdade att det var nödvändigt för kaldorei att återuppbygga sitt samhälle och återfå odödligheten de förlorat när Nordrassil förstördes.",al={"vem skapade teldrassil","staghelm världsträd","varför växte teldrassil"}}},fx={f2628340={q="Varför vill Corithras Moonrage att det här ska göras?",a="Corithras Moonrage undersöker Teldrassils heliga månbrunnar för att bedöma och vårda Världsträdets hälsa. Medan han vägleder dig genom ritualerna berättar han också om Teldrassils oroliga historia och hur trädet planterades. Han hoppas att du ska förstå både ditt folks heliga plikter och de oroande tecken som sprider sig i ert nya hem.",al={"varför vill corithras ha vatten från månbrunnarna","corithras motiv","varför crown of the earth"}},["21308da4"]={q="Vad används Filled Tourmaline Phial till?",a="Kärlet innehåller rent vatten från månbrunnen nära Pools of Arlithrien. Corithras behöver prover från Teldrassils olika månbrunnar för att övervaka vattnet som ger Världsträdet näring och utföra ritualerna som bevarar landets andliga balans medan fördärvet växer.",al={"filled tourmaline phials syfte","varför fylla tourmaline phial","tourmaline phial från månbrunnen"}}},fp="18,201,19.359.0,27.473.0,37.111.0,41.247.0,37.151.0,32.269.0"}
P.entries["quest:93317"] = {n="Crab Season",s="Crab Season är ett brådskande insamlingsuppdrag på Zephras, där du ska samla sällsynta Windsong crawlers under deras korta årliga säsong. Eftersom kultisternas senaste aktivitet gjort stränderna vid Windsong Lake farliga kallas äventyrare in för att trotsa både fientliga inkräktare och aggressiva kräftdjur.",h="Crab Season är ett brådskande insamlingsuppdrag på Zephras, där du ska samla sällsynta Windsong crawlers...",kw={"crab season","krabbor","kultistaktivitet","kött från windsong crawlers","windsong crawlers","windsong lake","zephras"},ang={["profession:Cooking"]="Det är viktigt för de lokala förråden på Zephras att samla säsongens kött från Windsong crawlers, men färska fångster från sjön måste hanteras varsamt eftersom djuren är aggressiva."},sec={{t="En flyktig skörd",b="Vid stränderna kring Windsong Lake på Zephras öppnar ett kort skördefönster under bara några veckor varje år. De inhemska Windsong crawlers dyker upp i stora antal längs sötvattnets stränder och bifloder, och erbjuder en sällsynt köttskörd åt den som är djärv nog att samla dem innan årets möjlighet går förlorad."},{t="Faror vid vattnet",b="Den senaste tidens ökade kultistaktivitet kring Zephras har stört vardagslivet och utsatt lokala samlare för fara. När fientliga kultister patrullerar vildmarken har det blivit alldeles för riskabelt för ensamma samlare att ta sig till Windsong Lake. Den korta säsongen riskerar att gå till spillo om inte dugliga äventyrare vågar sig ut till stränderna och de argsinta krabborna."}},faq={{q="Vad är Windsong crawlers?",a="Windsong crawlers är en aggressiv krabbart som bara finns i Windsong Lake på ön eller landmassan Zephras. De kan bara skördas under ett kort säsongsfönster på några veckor varje år.",al={"vad är windsong crawlers","windsongkrabbor","sjökrabbor zephras"}},{q="Varför måste krabborna skördas just nu?",a="Windsong crawlers kan bara samlas in under ett kort säsongsfönster på några veckor varje år. Om de inte skördas innan fönstret stängs går möjligheten att samla deras kött förlorad resten av året.",al={"varför samla crawlers nu","crawlersäsongens tidsfönster","varför krabbor bara en kort tid"}},{q="Varför kan den lokala skördaren inte samla krabborna själv?",a="Den senaste kultistaktiviteten i området har gjort det för farligt att ta sig till Windsong Lake för vanlig insamling. Lokala samlare kan därför inte nå stränderna innan det korta skördefönstret stängs.",al={"varför kan lokalbor inte samla krabbor","kultister zephras","kultistaktivitet windsong"}},{q="Var finns Windsong crawlers?",a="Windsong crawlers håller till längs stränderna kring Windsong Lake på Zephras och längs närliggande sammanbindande flodbankar.",al={"var finns windsong crawlers","var finns krabbor på zephras","windsong lakes stränder"}},{q="Är Windsong crawlers farliga att jaga?",a="Trots sitt anspråkslösa utseende som enkla sötvattenskräftdjur är Windsong crawlers märkbart stridslystna och mycket elakare än de ser ut. De kniper gärna efter alla som försöker samla deras kött.",al={"är windsong crawlers farliga","krabbornas temperament","elaka krabbor"}},{q="Vad används köttet från Windsong crawlers till?",a="Köttet från de insamlade krabborna är eftertraktad säsongsmat från sjön, tillgänglig under de få veckor då krabborna finns att samla. Det är så uppskattat att lokalbor anlitar äventyrare när kultister blockerar vägarna.",al={"vad används köttet från windsong crawlers till","varför samla krabbkött","vad används crawlerkött till"}}},fp="11,149,18.180.0,19.235.0,27.135.0,48.144.0,58.125.0,34.105.0,40.74.0,39.163.0"}
P.entries["quest:93318"] = {n="WANTED: Vulgara the Insatiable",s="WANTED: Vulgara the Insatiable är en belöning från Peacekeepers för att fälla ett monstruöst bevingat odjur som terroriserar Shen'dar Highlands. Constable Aonda har utfärdat kontraktet, som kräver att äventyrare dödar den glupska vuldrenen och överlämnar hennes huvud till Danarii Bellowveil.",h="WANTED: Vulgara the Insatiable är en belöning från Peacekeepers för att fälla ett monstruöst bevingat odjur...",kw={"belöning","constable aonda","danarii bellowveil","peacekeepers","shen'dar highlands","shen'dar village","vuldren","vulgara","vulgara the insatiable"},sec={{t="Highland Scourge",b="En officiell efterlysning från Constable Aonda i Peacekeepers pekar ut Vulgara the Insatiable som en omedelbar fara för höglandet. Den väldiga bevingade vuldrenen har terroriserat resenärer och lokala bosättningar från sitt näste sydväst om Shen'dar Village. Därför uppmanar lokala myndigheter prisjägare att sätta stopp för hennes skräckvälde."},{t="Pressade beskyddare",b="Peacekeepers är redan belägrade från flera håll och kämpar för att hantera hot från regionala banditer och en skum kult som verkar i området. Om Vulgara elimineras minskar den hårda pressen på lokalbefolkningen. Då förblir himlen över Shen'dar trygg medan försvararna fokuserar på att skydda samhället."}},faq={{q="Vem är Vulgara the Insatiable?",a="Vulgara the Insatiable är en väldig, bevingad vuldren som terroriserar Shen'dar Highlands. Lokala myndigheter kallar henne höglandets gissel. Hennes glupska aptit och våldsamma närvaro utgör en allvarlig fara för resenärer och närliggande bosättningar.",al={"vem är vulgara","vulgara bakgrund","vad är vulgara för slags monster"}},{q="Vem utfäste belöningen för Vulgara?",a="Constable Aonda i de lokala Peacekeepers utfärdade den officiella belöningen för Vulgara för att skydda invånarna. Jägarna ska överlämna bevis på odjurets död till Danarii Bellowveil.",al={"vem utfärdade belöningen för vulgara","vem vill döda vulgara","constable aonda"}},{q="Var hittar man Vulgara the Insatiable?",a="Vulgara strövar enligt uppgift på en höjd sydväst om Shen'dar Village i Shen'dar Highlands.",al={"vulgaras plats","var dyker vulgara upp","hitta vulgara"}},{q="Vem är Danarii Bellowveil?",a="Danarii Bellowveil är rådgivaren som hanterar utbetalningen av belöningen. Danarii är hårt pressad av kringliggande banditer och kultister, men granskar Vulgara's avhuggna huvud och betalar ut den utlovade belöningen.",al={"vem är danarii bellowveil","lämna in till danarii"}},{q="Vad är en vuldren för slags varelse?",a="En vuldren är ett farligt, rovgirigt bevingat odjur som finns i höglandet. Vulgara är ett ovanligt stort och våldsamt exemplar vars omättliga jakt hotar lokala bosättningar.",al={"vad är en vuldren","vuldren odjur"}},{q="Vilka andra hot plågar Shen'dar Highlands?",a="Förutom rovdjur som Vulgara är Peacekeepers i Shen'dar Highlands hårt ansträngda av aktiva hot från en fast förankrad kult och höglandsbanditer som ger sig på lokalbefolkningen.",al={"vilka hot finns i shendar highlands","kult och banditer i shendar"}}},fp="30,204,20.264.0,20.212.0,30.207.0,33.155.0,42.81.0,26.180.0,35.164.0,49.174.0"}
P.entries["quest:93319"] = {n="Pilfered Windstones",s="Pilfered Windstones är ett lokalt uppdrag på Zephras där du återtar livsviktiga stulna resurser från Highlands Bandits. Dessa vindstenar förvaras i reserv för nödsituationer och är avgörande för vardagen, men de lokala ordningsvakterna är upptagna med kultisthot och kan inte själva rensa ut tjuvarna.",h="Pilfered Windstones är ett lokalt uppdrag på Zephras där du återtar livsviktiga stulna resurser från...",kw={"aonda","banditgrotta","falaath village","highlands bandits","pilfered windstones","shen'dar highlands","vindstenar","zephras"},ang={["class:Rogue"]="Highlands Bandits använder simpel list för att stjäla lagrade vindstenar, men skickliga skurkar känner igen hur tjuvar utnyttjar en bosättning som är upptagen med kultisthot.",["race:Skyborne"]="Livet på Zephras är starkt beroende av vindstenar för den dagliga överlevnaden, så det är avgörande att försvara och återta förråden för att hålla de lokala bosättningarna vid liv."},sec={{t="Zephras stulna förråd",b="På ön Zephras är vindstenar mer än märkliga artefakter – de är livsviktiga resurser för vardagen. Bosättningarna har nödförråd för att klara kriser. Men förråden började sina stadigt, och det var först när tillfångatagna banditer från norra Shen'dar Highlands upptäcktes med stenarna som mysteriet fick sin förklaring. Dessa ficktjuvar hade tydligen smugit sig in i de lokala förråden i flera månader och utnyttjat den bristande bevakningen för att stjäla så mycket de kunde bära."},{t="Överansträngt försvar och hot vid horisonten",b="Även om det verkar självklart att rensa ut den norra grottan står bosättningens ledare inför svåra val. Aonda, som ansvarar för byns försvar, avböjde att godkänna en moträd eftersom samhället har för få ordningsvakter för att avvara några. I söder blir kultisterna vid Falaath Village snabbt fler och utgör en allvarlig fara som tvingar vakterna att hålla sina poster. Eftersom ordningsvakterna är upptagna med kultisthotet faller det på självständiga äventyrare som vågar möta banditerna att återta de stulna vindstenarna."}},faq={{q="Vad används vindstenar till på Zephras?",a="På Zephras förlitar sig invånarna på vindstenar för sin vardag och överlevnad. Eftersom de är så viktiga för det dagliga livet försöker bosättningarna ha ett förråd undanstoppat för nödsituationer.",al={"vad används vindstenar till","varför behövs vindstenar","vindstenarnas syfte"}},{q="Vem stal vindstenarna?",a="Vindstenarna stals av Highlands Bandits, som håller till i en grotta i Shen'dar Highlands. När tillfångatagna banditer påträffades med stenarna insåg lokalbefolkningen att tjuvarna troligen hade brutit sig in i byns förråd i flera månader.",al={"vem stal vindstenarna","vem tog vindstenarna","vindstenstjuvar"}},{q="Var håller Highlands Bandits till?",a="Highlands Bandits har sitt läger i en grotta norr om bosättningen, i Shen'dar Highlands. Där samlar de stöldgods från byns förråd.",al={"var finns banditgrottan","highlands bandits plats","shendar-banditer"}},{q="Varför har byn inte rensat ut banditgrottan?",a="Aonda, som ansvarar för bosättningens försvar, valde att inte organisera en räd mot den norra grottan eftersom byn har så få ordningsvakter. Om de skickades bort skulle bosättningen bli sårbar för det växande antalet kultister vid Falaath Village i söder.",al={"varför anfaller de inte banditgrottan","varför anfaller aonda inte","byförsvar mot banditer"}},{q="Vilket hot finns vid Falaath Village?",a="Falaath Village ligger i söder och där ökar antalet kultister oroväckande snabbt. Deras växande närvaro utgör ett omedelbart hot som binder upp de lokala ordningsvakterna med att försvara hemmet i stället för att jaga banditer.",al={"vilket hot finns vid falaath village","kultister falaath","falaath-kultister"}},{q="Löser återtagandet av vindstenarna bosättningens brist?",a="De återtagna vindstenarna ger nödförråden tillfällig påfyllning, men lokalbefolkningen påpekar att störningarna i de större försörjningsrutterna fortfarande är ett akut problem. Om försörjningslinjerna inte säkras snart kommer bristen fortsätta att hota bosättningen.",al={"är vindstenarna säkra nu","zephras försörjningsrutter","är bristen på vindstenar löst"}}},fp="19,184,28.354.0,38.379.0,40.117.0,25.210.0,40.137.0,51.254.0,38.159.0,63.194.0"}
P.entries["quest:93320"] = {n="Tower Defense",s="Tower Defense skildrar en desperat kamp mot övermäktiga styrkor vid en befäst position. Medan försvararna vid fronten upprätthåller ett tillfälligt dödläge hotar den växande utmattningen att få försvaret att falla utan snabb hjälp.",h="Tower Defense skildrar en desperat kamp mot övermäktiga styrkor vid en befäst position.",kw={"försvarare","utmattning","befästning","utpost","belägring","dödläge","tower defense"},ang={["class:Warrior"]="Försvar mot numerärt överlägsna styrkor prövar uthålligheten lika mycket som skickligheten och kräver disciplinerade kämpar vid fronten för att förhindra en total kollaps."},sec={{t="Ett pressat försvar",b="Tower Defense kretsar kring en desperat kamp vid en befäst position under hårt angrepp. Garnisonen lyckas stå emot den första anstormningen, men fienden är fler och fortsätter att pressa sitt övertag. När de överlevande kämparna börjar bli utmattade blir den tillfälliga gränsen mellan överlevnad och nederlag allt skörare."},{t="Utmattningens hot",b="Trots att garnisonen håller en försvarslinje arbetar tiden emot den. Långvariga skärmytslingar mot övermäktiga styrkor tär stadigt på deras krafter och förvandlar striden till ett utmattningskrig. För att överleva belägringen behöver försvararna genast vidta en avgörande åtgärd och bryta dödläget innan linjerna brister."}},faq={{q="Vad handlar Tower Defense om?",a="Tower Defense är en brådskande försvarsinsats där försvararna kämpar för att hålla en position mot övermäktiga styrkor. Den närmaste försvarslinjen håller, men utmattning hotar att bryta försvaret om de inte hittar en avgörande motåtgärd.",al={"vad är tower defense","uppdraget tower defense","vad är det här för uppdrag"}},{q="Vilka strider försvararna mot?",a="Angriparna är fler än försvararna och pressar så hårt att de gradvis nöter ner garnisonen och tvingar fram ett spänt dödläge. Deras tillhörighet är inte känd; endast deras farliga numerära överläge är dokumenterat.",al={"vem anfaller i tower defense","vilka strider vi mot","fienden i tower defense"}},{q="Hur går det för försvararna just nu?",a="Försvararna börjar bli utmattade efter långvarig strid under obevekliga angrepp. Utan förstärkningar riskerar garnisonen att förlora mark mot de övermäktiga styrkorna, om de inte agerar snabbt och bryter dödläget.",al={"varför är försvararna trötta","dödläge vid tornet","stridens läge"}},{q="Avgör det striden att hålla linjen?",a="Att stå emot angreppet ger bara en tillfällig respit, inte en slutgiltig seger. Styrkorna på plats inser att utmattningen kommer att övermanna dem om ingen omedelbar plan bryter låsningen.",al={"vann vi tower defense","hur slutar tower defense","vad händer efter att vi hållit stånd"}},{q="Var utspelar sig försvaret?",a="Försvaret äger rum vid en befäst utpost under belägring, där styrkorna är hårt ansatta av de många fiendernas ständiga press.",al={"var finns tower defense","området tower defense","vilket torn är det här"}},{q="Vad krävs för att vända striden?",a="Försvararna måste snabbt utarbeta en strategi för att bryta belägringen och vända striden innan den utmattade frontlinjen ger vika för fiendens numerära överläge.",al={"vad måste göras härnäst","hur vinner man belägringen","bryta dödläget"}}},fp="13,156,21.221.0,23.219.0,28.152.0,31.143.0,44.155.0,41.131.0,35.135.0,32.94.0"}
P.entries["quest:934"] = {n="Crown of the Earth",s="Crown of the Earth är ett avgörande steg i Dolanaars uppdragskedja, där man undersöker plågorna som drabbar Teldrassil. Corithras Moonrage skickar äventyrare att hämta vatten från den heliga månbrunnen i The Oracle Glade. Resan avslöjar den oroande sanningen bakom världsträdets skapelse.",h="Crown of the Earth är ett avgörande steg i Dolanaars uppdragskedja, där man undersöker plågorna som drabbar...",kw={"alexstrasza","amethyst phial","corithras moonrage","fandral staghelm","odödlighet","månbrunn","nozdormu","the oracle glade","oracle tree","teldrassil"},ang={["class:Druid"]="För Cenarion Circle visar ett besök vid The Oracle Tree den ideologiska klyftan mellan Fandral Staghelms hänsynslösa ambitioner och den naturliga balans som Malfurion Stormrage traditionellt har bevarat.",["faction:Alliance"]="När man förstår Teldrassils bräckliga tillstånd blir det lättare att förstå den ihållande farsoten och galenskapen bland varelserna som plågar Alliansens nyaste huvudstadsområde.",["race:NightElf"]="Resan berör nattalvernas förhoppningar om Teldrassil efter Nordrassils offer under det tredje kriget."},sec={{t="The Oracle Glade",b="Corithras Moonrage visar resenärer vägen långt nordväst på Teldrassil, inbäddad under The Oracle Glades majestätiska trädkrona. Direkt under The Oracle Trees väldiga grenar ligger den första och mäktigaste månbrunnen som rests på ön. När sökare hämtar en Amethyst Phial med dess skimrande vatten får de möta den främsta helgedomen, där druiderna och själva trädet vakar över sitt nya hemlands hälsa."},{t="Den uteblivna välsignelsen",b="När Corithras får tillbaka flaskan till Dolanaar avslöjar han den mörka bristen i ärkedruiden Fandral Staghelms storslagna plan. Efter Nordrassils offer vid Mount Hyjal försökte Staghelm återställa nattalvernas odödlighet genom att plantera Teldrassil och be Drakflykterna om välsignelser. Men Nozdormu the Timeless One vägrade och tillrättavisade Staghelm för hans rena arrogans. Drottning Alexstrasza följde hans exempel och undanhöll Livsaspektens livsviktiga välsignelse. Därmed blev Teldrassils tillväxt instabil och bristfällig, och trädet blev sårbart för djup korruption."}},faq={{q="Var ligger månbrunnen i The Oracle Glade?",a="Månbrunnen ligger i nordvästra Teldrassil, strax norr om huvudvägen mot Darnassus. Den finns under The Oracle Trees väldiga grenar.",al={"var ligger oracle glade","oracle glade månbrunnens plats","oracle glades brunn"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en nattalvsväktare som är stationerad i Dolanaar. Han leder unga försvarare genom Teldrassils grenar för att ta prover från månbrunnarna och berättar om trädets bristfälliga begynnelse.",al={"corithras","vem är corithras moonrage"}},{q="Återställde Teldrassil nattalvernas odödlighet?",a="Nej. Teldrassil ger nattalverna ett nytt hem, men deras odödliga liv har inte återställts efter Nordrassils offer under det tredje kriget.",al={"är nattalver odödliga","teldrassils odödlighet","lever alver för evigt igen"}},{q="Varför samlar man vatten från The Oracle Glade?",a="Månbrunnen under The Oracle Tree är öns första och mäktigaste brunn. När Corithras hämtar dess vatten kan han bedöma Teldrassils andliga och naturliga hälsa i grunden.",al={"varför hämta vatten från oracle glade","amethyst phials syfte"}}},fx={["28d6c4e0"]={q="Varför vill Corithras Moonrage att det här ska göras?",a="Corithras Moonrage vägleder dig genom Teldrassils heliga månbrunnar och berättar den sanna historien om det nya Världsträdet. Genom att skicka dig under grenarna vid The Oracle Tree för att hämta vatten från Teldrassils första och mäktigaste brunn ser han till att du själv får ta del av dess djupa visdom innan han avslöjar varför grenarna fortfarande är oroliga och saknar odödlighet.",al={"varför vill corithras ha vattnet","corithras motiv","varför skicka till oracle glade"}}},fp="18,174,16.321.0,19.520.1,43.152.0,26.190.0,45.139.0,62.156.0"}
P.entries["quest:93461"] = {n="Welcome to Shen'dar Village",s="Welcome to Shen'dar Village presenterar resenärer för en avlägsen fristad präglad av forntida Highborne-släkter och pyrande rivalitet mellan fraktioner. Även om High Order och Windshapers upprätthåller en yttre vapenvila i bosättningen, dröjer bittra spänningar kvar strax utanför bygränsen.",h="Welcome to Shen'dar Village presenterar resenärer för en avlägsen fristad präglad av forntida...",kw={"coriella calmbreeze","high order","highborne","huvudloge","rathiril sunlance","shendar village","windshapers"},ang={["class:Mage"]="Magiker med band till Highborne-traditioner känner igen sitt ursprung i High Order, vars äldste som Rathiril Sunlance åtnjuter respekt i Shen'dar.",["race:NightElf"]="Shen'dar Village är genomsyrat av det forntida Highbornes arv och släkter och påminner oroväckande om stoltheten och det magiska arvet som splittrade alvsamhället."},sec={{t="En skör härd",b="Shen'dar Village är en skör fristad där olika alvfraktioner lever sida vid sida under en spänd vapenvila. Nykomlingar med spår av Highborne-blod skickas genast för att visa sin vördnad för High Orders äldste, Rathiril Sunlance, i bosättningens huvudloge och ordna logi hos den lokala värdshusvärden, Coriella Calmbreeze."},{t="Vildmarkens rivalitet",b="Under den vardagliga rutinen med logi och ströjobb pyr friktionen mellan två framträdande grupper: High Order och Windshapers. Även om de strikt upprätthåller hövligheten på bytorget, där de är i trygghet, råder fientlighet fritt i den omgivande vildmarken, där gamla rivaliteter avgörs utom nyfikna ögons räckhåll."}},faq={{q="Vad är syftet med uppdraget Welcome to Shen'dar Village?",a="Welcome to Shen'dar Village är ett introduktionsuppdrag som gör nyanlända äventyrare bekanta med bosättningens nyckelpersoner och sköra fred. Du får i uppdrag att träffa Rathiril Sunlance, den bofasta äldsten i High Order, och Coriella Calmbreeze på byns värdshus innan du tar dig an lokala uppgifter.",al={"vad är det här för uppdrag","information om welcome to shendar village","introduktion till shendar village"}},{q="Vem är Rathiril Sunlance?",a="Rathiril Sunlance är en äldste i High Order som bor i Shen'dar Village. Han finns i byns huvudloge, strax runt hörnet från den första uppdragsgivaren, och är en viktig kontakt för dig med Highborne-ätt eller ärenden som rör High Order.",al={"vem är rathiril sunlance","äldste i high order","var finns rathiril"}},{q="Vem är Coriella Calmbreeze?",a="Coriella Calmbreeze driver det lokala värdshuset i Shen'dar Village. Hon tar hand om resenärer med mat, logi och förnödenheter inför färder ut i den omgivande vildmarken.",al={"vem är coriella calmbreeze","värdshusvärd i shendar","var får man logi i shendar"}},{q="Vad ligger bakom spänningen mellan High Order och Windshapers?",a="Spänningen mellan High Order och Windshapers är stor på grund av deras olika traditioner och ambitioner. De två fraktionerna lyckas leva sida vid sida med hövlighet inom Shen'dar Villages gränser, men återhållsamheten upphör vid byns utkant, där konflikterna ofta övergår i våld ute i vildmarken.",al={"high order mot windshapers","varför finns det spänningar","konflikt i byn"}},{q="Vad är det för utseende hos High Order som uppdragsgivaren nämner?",a="De som härstammar från Highborne är kända för ett särskilt glitter i ögonen, ett magiskt arv som genast avslöjar för uppmärksamma lokalbor att de har High Orders utseende.",al={"high orders utseende","highborne-ögon","highborne-glitter"}},{q="Är Shen'dar Village skyddat från konflikter?",a="Inne i Shen'dar Village upprätthålls hövligheten strikt mellan rivaliserande fraktioner som High Order och Windshapers. Utanför bosättningen råder däremot ingen sådan fred, och öppen fientlighet blossar ofta upp utom vakande ögons räckhåll.",al={"är shendar säkert","våld utanför shendar","faror i vildmarken"}}},fp="27,199,16.267.0,22.230.0,61.211.0,25.249.0,27.156.0,63.230.0,56.157.0,39.171.0"}
P.entries["quest:935"] = {n="Crown of the Earth",s="”Crown of the Earth” markerar höjdpunkten i månbrunnsriterna över hela Teldrassil. När det insamlade vattnet överlämnas till Arch Druid Fandral Staghelm i Darnassus blir oron över världsträdets bristfälliga, oblessade existens tydlig.",h="”Crown of the Earth” markerar höjdpunkten i månbrunnsriterna över hela Teldrassil.",kw={"alexstrasza","cenarion enclave","corithras moonrage","crown of the earth","darnassus","fandral staghelm","månbrunn","nozdormu","teldrassil"},ang={["class:Druid"]="När du bär månbrunnsvatten till Cenarion Circles ärkedruid ställs du direkt inför Fandral Staghelm. Mötet visar den djupa politiska och andliga splittring som har gripit druidernas ledarskap medan Malfurion är borta.",["faction:Alliance"]="För den större Alliansen är Darnassus en mäktig huvudstad full av uråldriga mysterier, men den fördärvade vildmarken runt staden visar att även nattalverna möter inre faror på sin egen heliga mark.",["race:NightElf"]="Riten blottlägger den stilla oron under ditt nya hem: Teldrassil planterades i högmod utan drak aspekternas välsignelser, och den växande sjukdomen påminner om hur skör ditt folks nya början är."},sec={{t="Ett bristfälligt ursprung",b="Teldrassil restes efter det tredje kriget för att ge nattalverna ett nytt hem och återställa deras förlorade odödlighet. Men de stora aspekterna Alexstrasza och Nozdormu undanhöll sina välsignelser och vägrade godkänna trädets tillkomst. Utan deras gudomliga beskydd har Teldrassil drabbats av en smygande sjukdom, som får bisarra varelser att välla fram ur grenverket och tidigare fridfulla furbolgstammar att sjunka ner i vansinne."},{t="Leverans till ärkedruiden",b="Corithras Moonrage ber unga äventyrare samla vatten från månbrunnar över hela ön för att övervaka och lindra grenverkets åkommor. Corithras samlar proverna i ett enda kärl och skickar budbäraren djupt in i Darnassus, till Cenarion Enclave. Där sitter Arch Druid Fandral Staghelm, Teldrassils skapare, som ser den smygande korruptionen som en besvärlig börda han ensam måste lösa, inte som ett tecken på högmod."}},faq={{q="Varför vill Fandral Staghelm ha vattnet från månbrunnarna?",a="Fandral Staghelm lät samla prover från månbrunnar över hela Teldrassil för att studera och bekämpa korruptionen som sipprar genom världsträdet. Som ledaren som drev på trädets plantering bär han ansvaret för att hitta en lösning på de märkliga bestarna och de vansinniga furbolgerna som oroar trädkronan.",al={"varför fandral vill ha vatten","varför fandral behöver kärlet","vad vattnet ska användas till"}},{q="Varför plågas Teldrassil av korruption och vansinniga bestar?",a="Till skillnad från det uråldriga världsträdet Nordrassil planterades Teldrassil utan välsignelser från Alexstrasza Livgivaren eller Nozdormu den Tidlöse. Eftersom det nya trädet nekades dessa urdrakars beskydd är dess tillväxt i grunden bristfällig, vilket låter märkliga maligniteter slå rot i jorden och förvrida djurlivet och furbolgerna i närheten.",al={"varför teldrassil är sjukt","korruption i teldrassil","varför furbolgerna är galna"}},{q="Var finns Arch Druid Fandral Staghelm?",a="Arch Druid Fandral Staghelm bor i Darnassus, i Cenarion Enclave. Du hittar honom högst upp i den centrala druidpaviljongen, med utsikt över enklavens heliga lundar.",al={"var finns fandral","fandral staghelms plats","hur hittar man fandral"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en nattalv stationerad i Dolanaar som låter unga äventyrare fylla flaskor vid Teldrassils månbrunnar. Han häller flaskornas innehåll i ett enda kärl och skickar budbärare för att leverera det till ärkedruiden Staghelm i Darnassus.",al={"vem ger crown of the earth","corithras roll","corithras moonrage"}},{q="Vad händer när du har slutfört uppdraget?",a="När du levererar det fyllda kärlet till Fandral Staghelm avslutas den huvudsakliga uppdragskedjan för Crown of the Earth i Teldrassil. Staghelm tar emot vattnet ganska kort och riktar sedan uppmärksamheten tillbaka mot de större hoten mot nattalvernas hemland.",al={"fortsättning på crown of the earth","vad händer efter crown of the earth 6","nästa uppdrag efter crown of the earth"}},{q="Varför är Fandral Staghelm så avvisande när han tar emot kärlet?",a="Fandral Staghelm är ökänd för att vara stolt, otålig och tyngd av den överväldigande uppgiften att leda Cenarion Circle medan Malfurion Stormrage är borta. Han ser administrativa bakslag och långsamma budbärare med förakt och känner att Teldrassils överlevnad helt vilar på hans egna axlar.",al={"varför fandral är otrevlig","fandrals personlighet","är fandral alltid butter"}}},fx={d62362b9={q="Varför vill Corithras Moonrage att kärlet förs till Fandral?",a="Corithras oroar sig djupt för sjukdomen som sprider sig i Teldrassil. Eftersom Världsträdet växte utan Aspekternas, Alexstrasza och Nozdormus, livsviktiga välsignelser har märkliga bestar stigit upp ur jorden och tidigare fredliga furbolger blivit våldsamt vansinniga. Corithras tror att Arch Druid Fandral Staghelm aktivt söker ett botemedel mot det spridande fördärvet. Därför samlar han skyndsamt vattenproverna du hämtat bland grenarna och skickar dig direkt till Darnassus med dem.",al={"corithras motiv","varför skicka vatten från månbrunnen","varför vill corithras att det här ska göras"}},["01febe86"]={q="Varför skickar Corithras Moonrage dig i stället för att själv gå?",a="Corithras är kvar i Dolanaar för att sköta lokala angelägenheter och hålla uppsikt över de oroande avvikelserna som stör Teldrassils nedre grenar. Du har själv färdats till de olika månbrunnarna och hämtat vattenflaskorna, vilket visar din uthållighet och hängivenhet. Genom att anförtro dig det samlade kärlet kan Corithras hålla uppsikt över Dolanaar och samtidigt se till att Fandral Staghelm får proverna i Darnassus utan ytterligare dröjsmål.",al={"varför skicka spelaren till fandral","varför jag, corithras","varför levererar inte corithras kärlet själv"}}},fp="18,209,16.368.0,26.368.1,51.257.0,58.324.0,45.161.0,26.239.0,41.201.1,64.240.0"}
P.entries["quest:93552"] = {n="Harvesting Windstones",s="Harvesting Windstones är ett uppdrag som erbjuds av Dalia the Collector i Thendal Grove på Zephras Isle. När de uråldriga elementarkrafterna som håller ön vid liv sakta försvagas, har råa vindstenar blivit en viktig magisk bränslekälla. Äventyrare skickas runt i lunden för att samla kristallkluster av vindsten innan deras kraft går förlorad.",h="Harvesting Windstones är ett uppdrag som erbjuds av Dalia the Collector i Thendal Grove på Zephras Isle.",kw={"förankringspelare","dalia","dalia the collector","thendal grove","vindelementarer","vindstenskluster","vindstenar","zephras isle"},ang={["class:Mage"]="För dem som utövar arkana konster är den koncentrerade elementarkraften i vindstenar en tydlig påminnelse om hur sköra magiska ekosystem blir när deras elementarkällor försvinner.",["profession:Mining"]="Att samla råa vindstenar är en introduktion till att samla värdefulla mineraler och kristaller i Zephras Isles otämjda vildmark."},sec={{t="En ö som försvagas",b="Zephras Isle är starkt beroende av kvarvarande vindmagi för att hålla sig vid liv, men öns naturliga försvar försvagas. För flera århundraden sedan försvann vindelementarerna som levde på ön tillsammans med de lokala alverna helt. Sedan de försvann har den omgivande magin som håller landet och de stora förankringspelarna uppe sakta men säkert avtagit. För invånarna i Thendal Grove kräver överlevnad att varje möjlig reserv av rå energi säkras."},{t="Vindstenarnas värde",b="Vindstenar är lysande blå kristallformationer som finns naturligt utspridda i Thendal Grove. I deras sköra skal finns tät, koncentrerad vindmagi från svunna tider. De är ingen outsinlig lösning, men de utgör en pålitlig och ovärderlig källa till magisk näring och nytta för öns alver. Därför är insamlingen av råa kluster en livsviktig daglig uppgift."}},faq={{q="Vad är vindstenar?",a="Vindstenar är blå kristallfyndigheter runt Thendal Grove som innehåller koncentrerad, rå vindenergi. Alverna på Zephras Isle samlar dem som en viktig magisk bränslekälla.",al={"rå vindsten","vindstenskluster","blå kristaller"}},{q="Vem är Dalia the Collector?",a="Dalia är en alv som samlar in resurser och håller till i Thendal Grove på Zephras Isle. Hon organiserar insamlingen av viktiga råvaror, särskilt vindstenar, för att hjälpa till att fylla på öns krympande magiska reserver.",al={"dalia","dalia zephras","samlaren dalia"}},{q="Varför försvagas magin på Zephras Isle?",a="För flera århundraden sedan försvann vindelementarerna som levde tillsammans med de lokala alverna. Utan deras fortsatta närvaro har förtrollningen som de stora förankringspelarna ingjutit i ön sakta runnit bort.",al={"zephras förlorar magi","magin försvagas zephras","förankringspelare"}},{q="Vart tog vindelementarerna vägen?",a="Deras öde är fortfarande ett mysterium. Det enda man vet är att de försvann för flera århundraden sedan och lämnade ön att sakta förbruka sina återstående elementarreserver.",al={"saknade elementarer","var finns vindelementarerna","elementarerna försvann"}},{q="Vad är förankringspelarna?",a="De stora förankringspelarna är uråldriga strukturer på Zephras Isle, genomsyrade av kraftfull magi som håller landet vid liv. Nu när elementarerna är borta försvagas deras livgivande krafter gradvis.",al={"stora förankringspelarna","förankringspelarnas historia"}},{q="Var hittar du råa vindstenar?",a="Råa vindstenar finns utspridda över landskapet i Thendal Grove på Zephras Isle och ser ut som lysande blå kristallformationer.",al={"vindstenarnas plats","kristaller i thendal grove"}}},fx={["0a83a06c"]={q="Varför vill Dalia the Collector ha Windstone Clusters?",a="Dalia söker Windstone Clusters eftersom Zephras Isle är beroende av deras magiska kraft för att bestå. Sedan vindelementarerna försvann för århundraden sedan har den livgivande magi som en gång gav ön näring sakta avtagit. För de lokala alverna, vars liv och kultur fortfarande är tätt knutna till arkansk energi, är de här kristalliserade vindarna en livsviktig och pålitlig energikälla som ersätter det de försvagade förankringspylons inte längre kan ge.",al={"varför vill dalia ha windstones","dalia the collectors motiv","varför samla windstones"}},["33ac4299"]={q="Vad används Windstone Clusters till?",a="Windstone Clusters innehåller vindarnas råa, koncentrerade energi. Eftersom de uråldriga magiska förankringspylons på Zephras Isle långsamt förlorar sin kraft använder öns invånare de kristalliserade klustren som en pålitlig alternativ energikälla. Den håller samhället vid liv och bevarar dess viktiga band till magisk energi.",al={"vad windstone cluster används till","vad är windstone cluster till för","varför windstone clusters"}}},fp="21,166,15.327.0,23.276.0,20.168.0,27.214.0,40.178.0,33.152.0,27.191.0,33.122.0"}
P.entries["quest:93644"] = {n="Tattered Journal",s="En skadad dagbok som hittas nära Shen'dralas leder dig till dess författare, Evenshade. De ord som saknas kan fortfarande vara viktiga för honom.",h="En skadad dagbok som hittas nära Shen'dralas leder dig till dess författare, Evenshade.",kw={"skadad dagbok","evenshade","förlorad dagbok","mordent","återställa dagboken","shen'dralas","sliten dagbok"},sec={{t="Ett namn finns kvar",b="Nära Shen'dralas finns en dagbok med slitna sidor som knappt går att läsa. Bland de suddiga bokstäverna står ett efternamn tydligt: Evenshade. Författaren kan finnas i närheten, och dagbokens återstående ord är den enda ledtråden."},{t="Dagbokens öde",b="Mordent känner igen dagboken som sin, trots att århundraden gått sedan han förlorade den. Texten är borta, men han minns vad den innehöll och håller den kunskapen för sig själv. Han låter dig försöka återställa dagboken, om sidorna finns kvar."}},faq={{q="Var hittades dagboken?",a="Dagboken hittades nära Shen'dralas.",al={"var dagboken finns","slitna dagbokens plats"}},{q="Vem skrev dagboken?",a="Namnet som finns kvar i dagboken pekar ut Evenshade som författaren.",al={"dagbokens författare","evenshades dagbok"}},{q="Varför leta efter Evenshade?",a="Efternamnet Evenshade står i dagboken, och författaren kan finnas någonstans i Shen'dralas.",al={"hitta evenshade","dagbokens efternamn"}},{q="Kan du läsa dagboken?",a="Det mesta av dagbokens innehåll har gått förlorat, och de återstående bokstäverna är svåra att urskilja.",al={"oläslig dagbok","dagbokens innehåll"}},{q="Vad säger Mordent om dagboken?",a="Mordent känner igen den som sin förlorade dagbok, men säger att texten är borta.",al={"mordents dagbok","vem äger dagboken"}},{q="Kommer Mordent att berätta vad som stod där?",a="Mordent minns vad dagboken innehöll, men vill inte tala om det högt.",al={"dagbokens innehåll","mordents hemlighet"}}},fp="16,124,14.231.0,18.250.1,28.39.0,22.71.0,23.88.0,25.96.0,40.72.0,36.85.0"}
P.entries["quest:93680"] = {n="Key to the City",s="Magus Wordeen Voidglare i Tarren Mill vill veta mer om Kirin Tor, vars stad Archimonde förstörde och som nu har återuppbyggt Dalaran alldeles intill Dark Lady. Du ska genomsöka Kirin Tors läger efter något som kan föra in Horde i staden utan att någon märker det.",h="Magus Wordeen Voidglare i Tarren Mill vill veta mer om Kirin Tor, vars stad Archimonde förstörde och som nu...",kw={"archimonde","burning legion","dalaran","smutsig nyckel","kirin tor","nyckel till kloakerna","tarren mill","wordeen voidglare"},sec={{t="Den återuppbyggda staden",b="Alliansen hade en gång en armé av magiker, Kirin Tor, men den demoniska Burning Legion visade sig vara starkare. I ett enda slag jämnade ärkedemonen Archimonde deras stad med marken, och de överlevande blev rotlösa vagabonder. Nu har de återuppbyggt Dalaran alldeles intill Dark Lady. Magus Wordeen Voidglare i Tarren Mill vill veta mer och skickar dig till deras läger för att leta efter något, till exempel en uråldrig bok eller en hemlig relik, som kan föra in Horde i staden utan att någon märker det. Det du kommer tillbaka med är en smutsig Dalaran-nyckel till kloakerna."},{t="Wordeens svar",b="När Wordeen får se en nyckel till kloakerna säger han att det lyckligtvis är någon annan som ska använda den. Det finns arbete att göra innan den är säker att använda."}},faq={{q="Vem ger uppdraget Key to the City?",a="Magus Wordeen Voidglare i Tarren Mill.",al={"vem ger key to the city","uppdragsgivare för key to the city","var startar jag key to the city"}},{q="Varför är Horde intresserade av Dalaran?",a="Kirin Tor, vars stad Archimonde förstörde, har återuppbyggt Dalaran alldeles intill Dark Lady. Wordeen vill veta mer och behöver ett sätt att ta sig in utan att någon märker det.",al={"varför dalaran","varför hålla koll på dalaran","vad gör magikerna"}},{q="Vilket föremål ska du hitta?",a="En Dalaran-nyckel till kloakerna, en smutsig nyckel som finns i Kirin Tors läger.",al={"vad ska jag hämta åt wordeen","vad är nyckeln","föremålet key to the city"}}},fp="15,277,16.543.0,16.136.1,42.40.0,39.159.0,31.69.0"}
P.entries["quest:937"] = {n="The Enchanted Glade",s="I The Oracle Glade på nordvästra Teldrassil kämpar Sentinel Arynia Cloudsbreak för att skydda The Oracle Tree från aggressiva Bloodfeather-harpior. Efter att en utsänd budbärare på väg till Darnassus dödats kallas försvarare in för att slå tillbaka mot harpiornas bon och återta deras bälten som bevis.",h="I The Oracle Glade på nordvästra Teldrassil kämpar Sentinel Arynia Cloudsbreak för att skydda The Oracle Tree...",kw={"arynia cloudsbreak","bloodfeather","darnassus","harpier","the oracle glade","the oracle tree","sentinel","teldrassil","the enchanted glade"},ang={["class:Druid"]="Druider hyser stor vördnad för de kännande uråldringarna; att rensa bort harpiorna som hotar The Oracle Tree hjälper till att bevara gläntans naturliga balans.",["faction:Alliance"]="Att hjälpa Sentinels att säkra Teldrassils heliga lundar stärker banden till nattalvernas ledare i närbelägna Darnassus.",["race:NightElf"]="Att försvara världsträdets uråldriga andar och skydda Sentinels från harpiors vanhelgande är en högtidlig plikt för varje kaldorei."},sec={{t="En glänta under belägring",b="The Oracle Glade är en av Teldrassils heliga tillflyktsorter, centrerad kring ett kolossalt, uråldrigt exemplar som kallas The Oracle Tree. Sentinel Arynia Cloudsbreak skickades dit med en eskort av krigare för att vaka över denna vördnadsvärda gren. Tyvärr har vilda Bloodfeather-harpior trängt in i hålrummen, byggt bon över hela den omgivande trädkronan och hotar alla som närmar sig."},{t="Avbruten förbindelse med Darnassus",b="Spänningarna nådde sin kulmen när The Oracle Tree försökte skicka en budbärare till huvudstaden Darnassus med en brådskande rapport. Budbäraren hann aldrig förbi grenarna; harpierna överföll och dödade kuriren innan rapporten kunde lämna gläntan. Som svar har Arynia gett lokala äventyrare i uppdrag att decimera flocken och hämta Bloodfeather-bälten för att hejda den framryckande flocken."},{t="En kallelse från trädet",b="När det omedelbara hotet från de närliggande bona har minskat reagerar själva det uråldriga trädet. The Oracle Tree fäller en bit av sin förtrollade bark och söker ett sändebud som kan överlämna dess budskap till kaldoreiernas högsta ledare."}},faq={{q="Varför anfaller harpierna The Oracle Glade?",a="Bloodfeather-klanen har täta bon över norra Teldrassil. I The Oracle Glade har de omringat The Oracle Tree, vaktar sina boplatser ursinnigt och anfaller alla som försöker färdas till eller från den heliga platsen.",al={"harpier i the oracle glade","varför bloodfeather anfaller","harpier vid the oracle tree"}},{q="Vem är Sentinel Arynia Cloudsbreak?",a="Arynia Cloudsbreak är en Sentinel-officer som är stationerad tillsammans med en liten förtrupp i The Oracle Glade. Hennes främsta uppdrag är att försvara The Oracle Tree mot de omgivande harpiorna och återupprätta kontakten med Darnassus.",al={"arynia cloudsbreak","vem ger uppdraget the enchanted glade","cloudsbreaks historia"}},{q="Vad hände med budbäraren som skickades till Darnassus?",a="Budbäraren som skickades med en rapport från The Oracle Tree till Darnassus överfölls och dödades längs gläntans stigar av Bloodfeather-harpior innan hen nådde säkerhet.",al={"budbärare från the oracle tree","död budbärare darnassus"}},{q="Vad är The Oracle Tree?",a="The Oracle Tree är en väldig, kännande uråldring med rötter i The Oracle Glade. Den vakar över världsträdets grenar och förmedlar sin visdom och sina varningar till nattalvernas ledare.",al={"the oracle tree teldrassil","vem är the oracle tree"}},{q="Vilka bevis kräver Sentinel Cloudsbreak?",a="Sentinel Cloudsbreak kräver sex Bloodfeather-bälten från de dödade harpiorna som konkret bevis på att deras boplatser runt gläntan har decimerats.",al={"uppdraget bloodfeather belt","hur många bälten","bevis för uppdraget"}},{q="Vad händer efter att harpierna decimerats?",a="När det omedelbara området har säkrats fäller The Oracle Tree en bit av sin egen bark och öppnar en direkt kommunikationsväg så att en äventyrare kan föra dess sedan länge försenade budskap mot Darnassus.",al={"nästa uppdrag efter the enchanted glade","vad gör the oracle tree härnäst"}}},fx={["2b035f45"]={q="Varför vill Sentinel Arynia Cloudsbreak att det här ska göras?",a="Sentinel Arynia Cloudsbreak skickades ut med en liten styrka av Sentinels för att försvara det heliga Oracle Tree. Harpyor har byggt bon över hela gläntan och trängt in försvararna. De har till och med slaktat en kurir som skickades till Darnassus med viktiga rapporter. Arynia kan inte lämna sin försvarspost obevakad, så hon behöver en äventyrare som angriper bona direkt och driver tillbaka flocken innan gläntan övermannas.",al={"varför döda harpyorna","arynia cloudsbreaks motiv","varför skydda oracle tree"}},["164cdda3"]={q="Vilka är Bloodfeather-harpyorna som hotar gläntan?",a="Bloodfeather-harpyorna är våldsamma fågelliknande rovdjur som har slagit sig ned i de nordvästra delarna av Teldrassil. De är aggressiva och revirhävdande, och har byggt bon runt The Oracle Glade. De har skurit av kontakten med Darnassus och försöker driva bort eller slakta nattalvsväktarna som skyddar det uråldriga trädet.",al={"vilka är harpyorna","bloodfeather-harpyor i teldrassil","varför är harpyorna här"}},["3f052dc4"]={q="Varför kan inte Sentinel Cloudsbreak ta hand om harpyorna själv?",a="Sentinel Arynia Cloudsbreak leder bara en liten grupp Sentinels som är stationerade vid The Oracle Tree. Eftersom deras budbärare redan är död och harpyor omringar platsen måste hennes återstående trupper stanna kvar och skydda det heliga trädet från bakhåll. För att gå till angrepp mot harpyornas bon behövs dugliga, obundna resenärer som vågar ta sig in i fientliga nästen.",al={"varför behöver arynia min hjälp","varför kan sentinels inte döda harpyorna","varför jag till den förtrollade gläntan"}}},fp="19,252,19.296.0,26.290.0,23.172.1,43.181.0,35.187.0,46.175.0,24.178.0,45.149.0,39.146.1"}
P.entries["quest:93735"] = {n="The Broken Construct",s="The Broken Construct handlar om att hjälpa en hantverkare i Valanaar som kämpar med att reparera en sällsynt, skadad automat. Dessa maskiner skänktes ursprungligen av vindens bortgångna andar och bevarades av The Windshapers, vilket gör varje fungerande konstruktion som finns kvar till en ovärderlig relik från öns förflutna.",h="The Broken Construct handlar om att hjälpa en hantverkare i Valanaar som kämpar med att reparera en sällsynt...",kw={"hantverkare","the broken construct","konstruktion","riaani nightwind","valanaar","vindandar","windshapers"},ang={["class:Mage"]="Konstruktionerna och instrumenten som The Windshapers sköter drivs av känsliga magiska apparater, vilket gör dem särskilt intressanta för utövare av arkana konster.",["class:Shaman"]="Vindens andar skänkte ursprungligen konstruktionerna, vilket visar på det starka historiska bandet mellan lokalbefolkningen och elementarkrafterna innan andarna lämnade ön.",["profession:Engineering"]="Hantverkare som arbetar med uråldriga förtrollade konstruktioner ställs inför mekaniska och magiska utmaningar när de försöker hålla relikerna igång utan deras ursprungliga andliga beskyddare."},sec={{t="Vindandarnas gåvor",b="För länge sedan skänkte vindens andar magiska instrument, apparater och levande konstruktioner till öns folk. The Windshapers fick i uppgift att sköta dem och bevara dessa elementära gåvor genom generationerna. Men när andarna lämnade ön upphörde deras urgamla stöd, och de flesta underbara skapelser förföll tills bara en handfull fortfarande fungerade."},{t="En kris i Valanaar",b="I staden Valanaar skadades nyligen en av de sista fungerande konstruktionerna, vilket hotar att ytterligare minska öns redan krympande arv. Hantverkaren Riaani Nightwind skickades till stadens västra utkant för att undersöka maskinen och försöka reparera den, men dessa uråldriga apparater är så ömtåliga att de behöver all hjälp de kan få."}},faq={{q="Vilka är The Windshapers?",a="The Windshapers är lokala vårdare som historiskt har anförtrotts att sköta de magiska instrument, apparater och konstruktioner som vindens andar skänkte. Sedan andarna lämnade ön har deras uppgift blivit att varsamt bevara de få reliker som fortfarande fungerar.",al={"vilka är the windshapers","the windshapers i historien","vad gör the windshapers"}},{q="Varifrån kom de magiska konstruktionerna?",a="Vindens andar skänkte konstruktionerna till öns invånare, tillsammans med olika andra magiska instrument och apparater. Efter att vindandarna lämnat ön har mycket få av dessa skapelser fortsatt att fungera.",al={"vem byggde konstruktionerna","konstruktionernas ursprung","varifrån kom konstruktionerna"}},{q="Vem är Riaani Nightwind?",a="Riaani Nightwind är en hantverkare som skickats till västra Valanaar för att undersöka och reparera en av stadens få återstående fungerande konstruktioner efter att den skadats.",al={"vem är riaani nightwind","riaani nightwinds plats","hantverkare i valanaar"}},{q="Varför är de flesta av öns konstruktioner trasiga?",a="Konstruktionerna är beroende av gåvor och förtrollningar från vindens andar. När andarna lämnade ön avtog kraften och omsorgen som krävdes för att hålla dem igång, och i dag fungerar bara några få.",al={"varför är konstruktionerna trasiga","varför slutade konstruktionerna fungera","vindandarna lämnar ön"}},{q="Hur hänger Valanaar samman med konstruktionerna?",a="Valanaar är en bosättning där några av de sista fungerande konstruktionerna som vindens andar skänkte finns. En av dessa kvarvarande maskiner skadades nyligen i stadens västra del, vilket gör reparationer brådskande.",al={"vad är valanaar","staden valanaar","var finns konstruktionen"}},{q="Vad behöver göras i The Broken Construct?",a="Du ombeds ta dig till västra Valanaar för att hitta hantverkaren Riaani Nightwind och hjälpa till med att reparera den skadade konstruktionen.",al={"målet med uppdraget the broken construct","vad gör jag i the broken construct","vart ska jag gå i the broken construct"}}},fp="20,230,25.291.0,20.290.0,24.236.0,43.173.0,24.151.0,47.167.0,48.204.0,47.127.0"}
P.entries["quest:93736"] = {n="Unwelcome Spirits",s="Unwelcome Spirits är ett uppdrag åt Windshapers där du undersöker de oroande vindväsen som kallas ”hollows” och plötsligt dykt upp i Shadowgale Forest. Dessa märkliga väsen visade sig först efter att vindens sanna andar försvunnit, så Windshapers samlar in deras essenser för att förstå vad som drev bort de ursprungliga andarna.",h="Unwelcome Spirits är ett uppdrag åt Windshapers där du undersöker de oroande vindväsen som kallas ”hollows”...",kw={"hollows","shadowgale forest","vindväsen","unwelcome spirits","wind hollow essence","vindhollows","vindandar","windshapers"},ang={["class:Shaman"]="För den som står i förbindelse med elementarkrafter signalerar de naturliga vindandarnas avfärd och de tomma hollows ankomst en djup störning i traktens luftbalans."},sec={{t="De försvunna andarna",b="The Windshapers är upptagna av ett enda avgörande mysterium: vindandarnas plötsliga avfärd. När förbindelsen med dem har brutits lägger orden all sin kraft på att ta reda på varför de naturliga vindandarna övergav dem och vilka ritualer eller handlingar som kan locka dem tillbaka. I deras frånvaro har ett tomrum uppstått i traktens elementära atmosfär."},{t="Skuggor i Shadowgale",b="Efter vindandarnas avfärd dök en oroande ny närvaro upp i norr, i Shadowgale Forest. Iakttagare började se märkliga vindväsen som ofta kallas hollows. Före andarnas uttåg kände Windshapers inte till dessa varelser, som verkar nära knutna till de sanna luftandarnas plötsliga frånvaro. Att skingra dem och samla in deras kvarlämnade essenser ger bästa chansen att förstå deras natur."}},faq={{q="Vilka är Windshapers?",a="The Windshapers är en orden som vill förstå varför vindandarna övergav dem och upptäcka vad som kan göras för att få andarna tillbaka. Deras undersökningar kretsar kring märkliga fenomen som uppstod direkt efter att andarna försvann.",al={"vilka är windshapers","windshapers-fraktionen","vad vill windshapers"}},{q="Vad är hollows?",a="Hollows är en ovanlig sorts vindväsen som visade sig i Shadowgale Forest först efter att de ursprungliga vindandarna hade lämnat platsen. Man vet ännu lite om deras ursprung eller sanna natur, så forskare samlar in deras essenser för vidare studier.",al={"vad är hollows","vindhollows-lore","hollow-vindväsen"}},{q="Var ligger Shadowgale Forest?",a="Shadowgale Forest ligger i norr. Det är där de märkliga vindväsendena hollows har dykt upp i stort antal och slagit sig ner efter att traktens elementandar dragit sig undan.",al={"var ligger shadowgale forest","shadowgales läge"}},{q="Varför gav sig vindandarna av?",a="Den exakta orsaken till att vindandarna försvann är fortfarande okänd. Windshapers forskning syftar främst till att ta reda på varför de gav sig av och hitta ett sätt att återupprätta förbindelsen med dem.",al={"varför lämnade vindandarna","vart tog andarna vägen"}},{q="Varför samlar man in Wind Hollow Essences?",a="Wind Hollow Essences samlas in från skingrade hollows så att Windshapers kan undersöka deras lämningar. Genom att studera den fysiska essens som blir kvar hoppas de förstå vad som gav upphov till varelserna efter att andarna hade lämnat platsen.",al={"varför samla in hollow-essenser","syftet med wind hollow essence"}},{q="Betraktas hollows som fientliga?",a="Även om man ännu inte vet mycket säkert om dem ses hollows som ovälkomna inkräktare som dök upp när de naturliga andarna saknades. De blir allt fler i Shadowgale Forest, så de måste skingras för att skydda trakten och säkra exemplar.",al={"är hollows farliga","hot från hollow-vindväsen"}}},fp="17,189,20.204.0,21.273.0,24.207.0,21.195.0,27.122.0,31.122.0,44.168.0,35.202.0"}
P.entries["quest:93737"] = {n="The Broken Construct",s="The Broken Construct handlar om att hjälpa Riaani Nightwind, som står med överkroppen djupt inne i en maskin som inte fungerar. Ayessa har skickat dit dig som assistent, och du måste lyssna på Riaanis planer för att ta reda på hur du kan hjälpa till att återställa apparaten.",h="The Broken Construct handlar om att hjälpa Riaani Nightwind, som står med överkroppen djupt inne i en maskin...",kw={"ayessa","trasig konstruktion","konstruktion","ingenjörskonst","riaani nightwind","the broken construct"},ang={["profession:Engineering"]="Mekare och ingenjörer känner igen frustrationen i att hantera en trasig konstruktion vars mekaniska inre kräver omständlig felsökning."},sec={{t="Hjälpa hantverkaren",b="The Broken Construct börjar när Ayessa skickar en äventyrare för att hjälpa Riaani Nightwind. Riaani arbetar hårt med att försöka hitta felet i en skadad konstruktion, helt uppslukad av apparatens inre delar. Han blir förvånad över att få hjälp utifrån och tvivlar på att en otränad resenär kan hantera känsligt mekaniskt arbete, men går med på att beskriva några nödvändiga uppgifter när han väl kravlar sig ut ur maskinen."},{t="Felsökning av maskiner",b="Konstruktioner kräver exakt montering och noggrann kalibrering, så varje haveri är ett allvarligt bakslag för en ingenjör. Riaani Nightwind står djupt inne bland mekaniska delar och behöver ett extra par händer för att samla material eller utföra fälttester. Att lyssna noga på Riaanis genomgång är första steget mot att få den stillastående maskinen att fungera igen."}},faq={{q="Vem är Riaani Nightwind?",a="Riaani Nightwind är en uppfinnare som arbetar flitigt med en avstängd mekanisk konstruktion. Även om han till en början är skeptisk till nykomlingar som skickas till honom behöver han hjälp med att få maskinen att fungera igen.",al={"vem är riaani nightwind","riaani","mekaniker för konstruktioner"}},{q="Vem är Ayessa?",a="Ayessa är en medarbetare som hänvisar äventyrare till Riaani Nightwind för att hjälpa honom med hans pågående mekaniska problem. Det är hennes rekommendation som får Riaani att överväga att sätta en nykomling i arbete.",al={"vem skickade mig till riaani","ayessa","vem är ayessa"}},{q="Vad är den trasiga konstruktionen?",a="Konstruktionen är en mekanisk skapelse som för närvarande lider av mekaniska fel. Riaani Nightwind hittas djupt inne i den, där han försöker avgöra vilka delar och uppgifter som krävs för att reparera den.",al={"vad är konstruktionen","vilken maskin lagar riaani","trasig maskin"}},{q="Vad behöver Riaani hjälp med?",a="När du anländer från Ayessa måste du först ge Riaani en stund att kliva bort från konstruktionens inre och förklara situationen, så att du får instruktioner om hur du bäst kan hjälpa till.",al={"vad vill riaani att jag ska göra","uppdraget med den trasiga konstruktionen","hur hjälper jag riaani"}},{q="Varför är Riaani skeptisk till din hjälp?",a="Riaani är helt uppslukad av tekniskt arbete och blir något otålig när han blir avbruten. Han betraktar de flesta äventyrare som otränade nybörjare tills de visar att de kan följa mekaniska instruktioner.",al={"varför kallar riaani mig nybörjare","är riaani otrevlig","riaanis dialog"}}},fp="20,141,21.300.0,25.356.0,24.163.0,14.164.0,29.165.0,32.128.0,37.171.0"}
P.entries["quest:93738"] = {n="The Broken Construct",s="En Windshaper ber dig berätta för Ayessa Dawnsinger vad du fått veta om den trasiga konstruktionen. High Orders arbete med vindandemagi har väckt oro.",h="En Windshaper ber dig berätta för Ayessa Dawnsinger vad du fått veta om den trasiga konstruktionen.",kw={"ayessa dawnsinger","belathaan","trasig konstruktion","high order","valanaar","valennia stormfist","vindandar","windshaper"},sec={{t="Återvänd till Ayessa",b="För vidare det du fått veta till Ayessa Dawnsinger i Valanaar. High Order har prövat Windshapers tålamod med sina experiment med vindandemagi. Gruppen har också befattat sig med kunskap inom Windshapers ansvarsområde. Ayessa kan avgöra vad som bör hända härnäst."},{t="Ett oroande namn",b="Ayessa tror att High Order låg bakom att konstruktionen gick sönder. Hon känner Belathaan som Valennia Stormfists kusin och säger att hans mor var en Windshaper. Hans inblandning gör henne besviken. Hon behöver tid att tänka efter."}},faq={{q="Vem ska jag rapportera till?",a="Rapportera det du fått veta till Ayessa Dawnsinger i Valanaar.",al={"rapportera till ayessa","var rapportera","ayessa daw sinsinger"}},{q="Varför oroar sig Windshapers för High Order?",a="High Order har experimenterat med vindandemagi och lagt sig i kunskap inom Windshapers ansvarsområde, trots att det är förbjudet.",al={"high order problem","varför är windshapers arga","high order vindmagi"}},{q="Vad hände med konstruktionen?",a="Ayessa tror att High Order låg bakom att konstruktionen gick sönder.",al={"trasig konstruktion","konstruktionen gick sönder","varför är konstruktionen trasig"}},{q="Vem är Belathaan?",a="Belathaan är Valennia Stormfists kusin, och hans mor var en Windshaper.",al={"belathaan","belathaans familj","belathaans kusin"}}},fp="20,158,16.251.0,16.239.1,23.57.0,55.140.0,31.79.0,17.76.0"}
P.entries["quest:93739"] = {n="Exploring the Horde",s="Exploring the Horde är ett introduktionsuppdrag som skickar äventyrare på en vidsträckt rundtur bland Hordens ledare. Resan börjar med att rapportera till Nazgrel i Grommash Hold och går vidare till Vol'jin, Cairne Bloodhoof och Lady Sylvanas Windrunner. Uppdraget visar de diplomatiska och militära band som förenar orcher, troll, tauren och Forsaken.",h="Exploring the Horde är ett introduktionsuppdrag som skickar äventyrare på en vidsträckt rundtur bland Hordens...",kw={"cairne bloodhoof","darkspear","exploring the horde","forsaken","grommash hold","nazgrel","orgrimmar","sylvanas windrunner","tauren","thunder bluff","undercity","vol'jin"},ang={["faction:Horde"]="Resan presenterar äventyrarna för de olika ledarna som vägleder den nybildade Horden genom Kalimdor och Eastern Kingdoms.",["race:Orc"]="Nazgrel är direkt rådgivare åt krigshövding Thrall i Orgrimmar och fungerar som en viktig militär kontakt för unga orchkrigare som vill göra sig ett namn.",["race:Tauren"]="Mötet med High Chieftain Cairne Bloodhoof i Thunder Bluff knyter resenärerna till taurenfolkets andliga hjärta och styrka.",["race:Troll"]="Samtalet med Shadow Hunter Vol'jin stärker banden mellan Darkspear-stammen och deras orchallierade i Valley of Spirits.",["race:Undead"]="Resan till Undercity för att möta Dark Lady Sylvanas Windrunner visar hur viktig, om än spänd, Forsakens allians med Horden i Kalimdor är."},sec={{t="Order från Grommash Hold",b="Exploring the Horde börjar i Grommash Hold, fästningen i hjärtat av Orgrimmar, där Nazgrel och krigshövdingens råd leder militära operationer. Äventyrare hänvisas till Nazgrel för att få order om att bege sig ut i koalitionens vidsträckta områden. Uppdraget kräver en lång resa bort från Durotars röda kanjoner för att lära känna vidden av de folk som förenas under den röda fanan."},{t="En allians för överlevnad",b="Uppdraget skickar resenärer att tala med de främsta företrädarna för de allierade folken: Shadow Hunter Vol'jin bland Darkspear trolls, High Chieftain Cairne Bloodhoof bland tauren och Lady Sylvanas Windrunner, Forsakens drottning. Genom att möta dessa gestalter ansikte mot ansikte får äventyraren en inblick i banden som knyter Kalimdor till Lordaerons pesthärjade länder på andra sidan Stora havet."}},faq={{q="Vad är uppdraget Exploring the Horde?",a="Exploring the Horde är en introduktionsresa där äventyraren ska rapportera till Nazgrel i Grommash Hold. Därifrån leder instruktionerna resenären genom Hordens områden för att söka upp och tala direkt med viktiga ledare för olika folk: Vol'jin, Cairne Bloodhoof och Lady Sylvanas Windrunner.",al={"vad är exploring the horde","uppdraget exploring the horde","vad gör man i uppdraget"}},{q="Vem är Nazgrel och var finns han?",a="Nazgrel är en framstående orchkrigare och betrodd underbefälhavare som är stationerad i Grommash Hold i Orgrimmar. Han är rådgivare vid Hordens maktcentrum, samordnar uppdrag och hänvisar blivande hjältar till viktiga befälhavare och regionala allierade.",al={"vem är nazgrel","var finns nazgrel","nazgrels roll"}},{q="Vilka ledare ska du träffa?",a="Uppdraget leder dig till Hordens främsta ledare: Shadow Hunter Vol'jin bland Darkspear trolls, High Chieftain Cairne Bloodhoof bland tauren i Mulgore och Lady Sylvanas Windrunner, bansheedrottningen som styr Forsaken i Undercity.",al={"vilka ledare ska jag tala med","ledare att besöka","vem ska man tala med"}},{q="Varför ska äventyrare besöka alla ledarna?",a="Den moderna Horden är en koalition av olika folk som förenas av en gemensam kamp för överlevnad och broderskapspakter. Besöken hos Vol'jin, Cairne och Sylvanas visar alliansens räckvidd och bekantar äventyrarna med de olika maktcentrumen i Durotar, Mulgore och Lordaeron.",al={"varför besöka alla ledare","syftet med att besöka hordens ledare","diplomatiska skäl"}},{q="Var finns ledarna?",a="Vol'jin finns bland Darkspear trolls i Orgrimmars Valley of Spirits. Cairne Bloodhoof håller hov högt uppe på Thunder Bluffs platåberg i Mulgore. Lady Sylvanas Windrunner bor djupt inne i Undercitys Royal Quarter, under Ruins of Lordaeron.",al={"var finns ledarna","ledarnas platser","hitta vol'jin cairne sylvanas"}},{q="Vad är Grommash Hold?",a="Grommash Hold är den centrala fästningen i Valley of Strength i Orgrimmar. Den är uppkallad efter den legendariske Grom Hellscream och fungerar som Command Center, där krigshövding Thrall och hans främsta rådgivare, däribland Nazgrel, styr Hordens angelägenheter.",al={"vad är grommash hold","var ligger grommash hold","orgrimmars fästning"}}},fp="19,164,25.281.0,23.338.0,38.134.0,39.179.0,35.195.0,52.182.0,39.242.0,22.187.0"}
P.entries["quest:93740"] = {n="Blood for Blood",s="Flera Windshaper-noviser har hittats döda i Highlands, och misstankarna riktas genast mot Al'Akeths fanatiker. Ayessa skickar äventyrare norrut till Gustberry Lowlands för att slå ner kultisterna och återvända med deras vindstensbönekärl.",h="Flera Windshaper-noviser har hittats döda i Highlands, och misstankarna riktas genast mot Al'Akeths fanatiker.",kw={"al'aketh","ayessa","blood for blood","kultister","gustberry lowlands","highlands","windshapers","vindstensbönekärl"},sec={{t="En dyster upptäckt",b="Morgonen började med dystra nyheter för Windshapers: flera av deras noviser hade hittats mördade i Highlands. Även om det fortfarande saknas säkra bevis riktas misstankarna genast mot Al'Akeths kultister, vars ihärdiga fanatism gör dem till huvudmisstänkta. Windshapers vägrar låta blodspillan förbli obesvarad, drivna av en regel som kräver öga för öga."},{t="Krav på hämnd",b="Ayessa kräver direkt hämnd på alla Al'Aketh som påträffas norrut i Gustberry Lowlands. För att försäkra sig om att vedergällningen genomförs ber hon om vindstensbönekärlen som tas från de fallna kultisterna, som bevis på deras död. Angreppet är tänkt som ett första svar på vad Windshapers ser som långvarig fanatism."}},faq={{q="Vilka är Al'Aketh?",a="Al'Aketh är kultister som Windshapers ser som blodtörstiga fanatiker. De misstänks för att ha dödat Windshaper-noviserna som hittades i Highlands.",al={"vilka är al'aketh","al'akeths kultister","vilka slåss vi mot"}},{q="Varför söker Windshapers hämnd?",a="Flera Windshaper-noviser hittades döda i Highlands, och Windshapers misstänker starkt att Al'Akeths kultister låg bakom attacken. Enligt sin troslära kräver Windshapers hämnd.",al={"varför döda al'aketh","windshaper-noviser döda","varför hämnd"}},{q="Vem är Ayessa?",a="Ayessa är en företrädare för Windshapers som leder hämnden mot Al'Aketh och samlar in bönekärlen från de fallna kultisterna.",al={"vem är ayessa","uppdragsgivare","ayessa windshaper"}},{q="Vad är vindstensbönekärlen?",a="Vindstensbönekärlen är personliga föremål som Al'Akeths kultister bär med sig. Ayessa kräver dem som konkreta bevis på att kultisterna som låg bakom blodspillan har dödats.",al={"vad är vindstensbönekärl","bönekärl","bevis på dådet"}},{q="Var finns Al'Aketh?",a="Al'Akeths kultister håller till norrut, i Gustberry Lowlands, där de utövar sina ritualer.",al={"var finns al'aketh","var finns kultisterna","gustberry lowlands plats"}}},fp="15,228,16.279.0,22.280.0,21.138.0,44.145.0,14.144.0,37.142.0,32.94.0"}
P.entries["quest:93746"] = {n="A Firm Response",s="\"A Firm Response\" är ett Horde-uppdrag på Zephras Isle som Ayessa Dawnsinger ger. Spänningarna kokar över när det gåtfulla High Order inkräktar på Windshapers territorium och verksamhet. Ayessa beordrar ett förebyggande angrepp mot Belathaan Brightwish på vägen till Shrine of Akir för att med våld markera tydliga gränser.",h="\"A Firm Response\" är ett Horde-uppdrag på Zephras Isle som Ayessa Dawnsinger ger.",kw={"a firm response","ayessa dawnsinger","belathaan brightwish","high order","levande stormar","shrine of akir","windshapers","zephras isle"},ang={["class:Shaman"]="Sammandrabbningen med Living Storms på vägen visar hur det oroliga och otämjda elementarluftskenet genomsyrar Zephras Isle.",["faction:Horde"]="Hordes närvaro på Zephras Isle bygger på att säkra positioner och hindra rivaliserande fraktioner som High Order från att inkräkta på allierades intressen."},sec={{t="Dra gränsen",b="Windshapers på Zephras Isle tolererar inte oinbjuden granskning, särskilt inte från en så hemlighetsfull och beräknande organisation som High Order. Tidigare varningar har ignorerats, och Ayessa Dawnsinger tvingas därför trappa upp konflikten. För att skydda deras intressen väljer hon att genskjuta Belathaan Brightwish på den ensliga vägsträckan norrut mot Shrine of Akir, så att sammanstötningen sker utom räckhåll för nyfikna blickar i staden."},{t="Stormar på vägen",b="Belathaans färd norrut mot den uråldriga Shrine of Akir väcker omedelbart misstankar, även om hans exakta motiv är oklara. När han konfronteras på den avskilda vägen blir mötet snabbt fientligt, och Living Storms dras in i striden. Genom att besegra dessa våldsamma elementarer och kuva Belathaan skickar du ett tydligt budskap till High Order: inblandning i Windshapers angelägenheter kommer att besvaras med våld."}},faq={{q="Vem är Ayessa Dawnsinger?",a="Ayessa Dawnsinger är en uppdragsgivare som står på Horde och Windshapers sida på Zephras Isle. Hon värnar om deras domäner och är skoningslös mot inkräktare som lägger sig i deras angelägenheter.",al={"ayessa dawnsinger","vem ger ett tydligt svar","ayessa"}},{q="Vem är Belathaan Brightwish?",a="Belathaan Brightwish är en operatör med kopplingar till High Order. Han ses på väg ensam mot Shrine of Akir och blir måltavla för Ayessa Dawnsingers försök att skrämma hans organisation.",al={"belathaan brightwish","belthaan","vem är belathaan"}},{q="Vad är High Order?",a="High Order är en fraktion verksam på Zephras Isle vars aktiviteter går emot de lokala Windshapers intressen. Trots uttryckliga varningar fortsätter de att snoka i angelägenheter som inte angår dem.",al={"high order","high orders historia","vad är high order"}},{q="Var ligger Shrine of Akir?",a="Shrine of Akir ligger norr om staden på Zephras Isle. Belathaan genskjuts längs den avskilda vägen som leder till denna plats.",al={"shrine of akir","var ligger shrine of akir","shrine akir zephras"}},{q="Varför vill Ayessa att Belathaan ska besegras och inte dödas?",a="Ayessa vill uttryckligen skicka ett budskap snarare än starta ett fullskaligt krig. Genom att banka Belathaan blodig och låta honom återvända till sina överordnade hoppas hon ingjuta rädsla och respekt för Windshapers gränser.",al={"döda belathaan","varför skona belathaan","varför bara blåmärken"}},{q="Vad är Living Storms som möter dig under uppdraget?",a="Living Storms är elementarväsen som visar sig under konfrontationen med Belathaan på vägen. De speglar de flyktiga elementarkrafter som präglar Zephras Isle.",al={"levande stormar","vad är levande stormar"}}},fx={["3180a0eb"]={q="Varför vill Ayessa Dawnsinger att Belathaan konfronteras?",a="The High Order har upprepade gånger blandat sig i The Windshapers angelägenheter och struntat i tidigare varningar om att respektera deras territorium och seder. Ayessa anser att diplomatiska ord inte längre räcker. Genom att genskjuta Belathaan på vägen och ge honom en ordentlig omgång hoppas hon skicka ett glasklart budskap till hans överordnade: The Windshapers kommer att försvara sina gränser med våld om det behövs.",al={"varför konfrontera belathaan","ayessas motiv","varför skicka ett meddelande till high order"}}},fp="15,209,16.292.0,18.327.1,25.168.0,28.169.0,23.169.0,36.118.0,57.176.0,56.160.0"}
P.entries["quest:93786"] = {n="A Message in Blood",s="Krom’rosh skickar dig mot människornas gård vid Meadowsbrook. Han vill att gårdsfolket dödas som svar på avhopparnas anspråk på marken.",h="Krom’rosh skickar dig mot människornas gård vid Meadowsbrook.",kw={"ett budskap i blod","farholde","gård","mänskliga avhoppare","krom'rosh","meadowsbrook farm","gårdsarbetarna vid meadowsbrook farm","skärmytslingar"},ang={["faction:Horde"]="Som medlem av Horde utför du Krom’roshs order mot mänskliga avhoppare som har gjort anspråk på gården."},sec={{t="Gårdsfolket",b="Krom’rosh visar dig vägen till Meadowsbrook Farm, sydväst om floden. Mänskliga avhoppare gjorde anspråk på gården för några år sedan och sträckte sig sedan mot Farholde, fästet på den östra stranden. Krom’rosh säger att de tidigare skärmytslingarna saknade tillräckligt många krigare för att segra. Nu vill han att du stör gårdsarbetet och inte lämnar några fångar."}},faq={{q="Vem ber mig bege mig till Meadowsbrook?",a="Krom’rosh ber dig anfalla Meadowsbrook Farm och störa jordbruket där.",al={"vem skickade mig","krom'roshs uppdrag","vem ber mig"}},{q="Varför vill Krom’rosh att gården ska anfallas?",a="Mänskliga avhoppare gjorde anspråk på gården och utökade sitt område mot Farholde. Krom’rosh vill påminna dem om att hans folk finns där.",al={"varför anfalla gården","varför meadowsbrook","varför slåss mot människor"}},{q="Var ligger Meadowsbrook Farm?",a="Meadowsbrook Farm ligger sydväst om floden.",al={"var ligger gården","meadowsbrook läge","gården sydväst"}},{q="Vilka är gårdsarbetarna?",a="Gårdsarbetarna vid Meadowsbrook Farm är de människor som Krom’rosh skickar dig för att döda.",al={"vilka är gårdsarbetarna","folket vid meadowsbrook","människor på gården"}},{q="Vad hände i de tidigare skärmytslingarna?",a="Krom’rosh säger att hans sida skulle ha haft övertaget i de tidigare skärmytslingarna om de haft fler krigare.",al={"tidigare strider","varför skärmytslingarna misslyckades","kromroshs skärmytslingar"}}},fp="18,136,13.314.0,34.73.0,44.119.0,27.50.0,22.72.0,40.98.0"}
P.entries["quest:93788"] = {n="Borrowed Blades",s="Kreza Darkthorn ber dig hämta skogshuggarnas yxor från Turner's Logging Camp. Bladen ska ge material till vapen i Rog'mar.",h="Kreza Darkthorn ber dig hämta skogshuggarnas yxor från Turner's Logging Camp.",kw={"lånade blad","smedja","gur'dok","kreza darkthorn","skogshuggare","rog'mar","turner's logging camp","vapen","skogshuggarens yxa"},sec={{t="Vid Logging Camp",b="Kreza Darkthorn håller igång smedjan i Rog'mar medan Gur'dok bryter ner bladen. Människornas närvaro i söder och Twilight i väster gör det svårt att samla resurser. Du ombeds hämta skogshuggarnas yxor från Turner's Logging Camp, så att materialen kan formas till vapen."}},faq={{q="Vem vill ha yxorna?",a="Kreza Darkthorn i Rog'mar ber dig hämta yxorna från Turner's Logging Camp.",al={"vem skickade mig","krezas yxor","vem behöver blad"}},{q="Varför vill Kreza ha skogshuggarnas yxor?",a="Gur'dok bryter ner bladen, och Kreza använder materialen till att tillverka vapen.",al={"varför yxor","vad används yxor till","material till vapen"}},{q="Var ligger Turner's Logging Camp?",a="Turner's Logging Camp ligger söderut längs floden, vid sågverket.",al={"logging camp plats","var finns skogshuggarna","turner's camp"}},{q="Vad gör det svårt att samla resurser?",a="Människornas närvaro i söder och Twilight i väster gör kampen om resurser svår.",al={"varför resurser är svåra att få tag på","människornas närvaro","twilight i närheten"}}},fp="15,143,19.304.0,19.84.0,42.87.0,31.60.0,41.96.0"}
P.entries["quest:93791"] = {n="Speak with Belann",s="Speak with Belann skickar blivande magiker till Valanaar för att träffa mästerhantverkaren Belann Windwood. När en novis blir skickligare i magi är det en viktig övergångsrit enligt High Orders gamla traditioner att skapa ett eget magiskt fokus.",h="Speak with Belann skickar blivande magiker till Valanaar för att träffa mästerhantverkaren Belann Windwood.",kw={"belann","belann windwood","high order","magiskt fokus","stavar","valanaar","spön"},ang={["class:Mage"]="Att skapa ett eget magiskt fokus är en viktig övergångsrit för blivande magiker som hedrar High Orders uråldriga traditioner."},sec={{t="En ritual för växande kraft",b="När en blivande magiker blir skickligare i magi åberopar High Order uråldriga seder för att pröva och utveckla sina förmågor. Att skapa ett personligt magiskt fokus, som en stav eller ett spö, är en av ordens mest långlivade traditioner för elever som vill binda sin växande kraft till ett redskap de själva har skapat."},{t="Hantverkaren i Valanaar",b="För att utföra detta heliga hantverk skickas noviser till Valanaar för att söka upp Belann Windwood. Belann är känd för att i över ett århundrade ha smitt enastående stavar och spön åt High Order. Han är en betrodd mentor som gärna välkomnar hängivna elever och vägleder dem genom deras magiska redskaps komplicerade hantverk och historia."}},faq={{q="Vem är Belann Windwood?",a="Belann Windwood är en mästerhantverkare som bor i Valanaar. I över ett århundrade har han ägnat sitt hantverk åt att skapa stavar och spön åt medlemmar av High Order.",al={"vem är belann","belann windwood","belann"}},{q="Vad är High Order?",a="High Order är en uråldrig sammanslutning av magiker. Dess långvariga traditioner omfattar att vägleda unga magiker i att skapa och bemästra sina egna magiska fokus.",al={"vad är high order","high orders historia"}},{q="Vad är ett magiskt fokus?",a="Ett magiskt fokus, som ett spö eller en stav, kanaliserar magisk energi. Att skapa ett eget fokus räknas som en av de äldsta övergångsriterna för magiker under utbildning inom High Order.",al={"vad är ett magiskt fokus","syftet med magiskt fokus"}},{q="Var hittar man Valanaar?",a="Valanaar är bosättningen där Belann Windwood har sin verkstad och hjälper elever från High Order att skapa magiska fokus.",al={"var ligger valanaar","valanaars läge"}},{q="Varför skickas du för att tala med Belann?",a="Du är en blivande magiutövare vars krafter växer, och skickas till Belann för att lära av hans sekel av erfarenhet och börja forma ditt eget magiska redskap.",al={"varför besöka belann","varför skapa ett fokus"}},{q="Vad händer när du har träffat Belann?",a="När du presenterar dig för Belann i Valanaar välkomnar hantverkaren dig och gör sig redo att berätta om nästa steg i skapandet av ditt magiska fokus.",al={"vad händer sedan","efter samtalet med belann"}}},fp="17,153,23.326.0,25.270.0,23.145.0,23.158.0,22.162.0,28.112.0,38.157.0,35.138.0"}
P.entries["quest:93797"] = {n="Boughs in the Wind",s="Boughs in the Wind är en traditionell övergångsrit där en lärling samlar en vindgenomsyrad gren nära Falaath Village för att skapa ett magiskt fokus. Belann Windwood i Valanaar vägleder lärlingarna i traditionen, som hedrar en uråldrig sed i en tid då den magiska talangen i Zephras stadigt avtar.",h="Boughs in the Wind är en traditionell övergångsrit där en lärling samlar en vindgenomsyrad gren nära Falaath...",kw={"belann windwood","boughs in the wind","falaath village","magiskt fokus","valanaar","vindaltare","wind-infused bough","zephras"},ang={["class:Mage"]="Att skapa ett magiskt fokus av vindgenomsyrade grenar är en tidig övergångsrit för magiker som lär sig kanalisera elementarresonans.",["race:Skyborne"]="Eftersom allt färre unga visar fallenhet för magi för varje år som går, hjälper du till att bevara ditt folks förfäderskultur i Zephras när du deltar i skapandet av ett traditionellt magiskt fokus."},sec={{t="En övergångsrit",b="I Zephras länder genomgår unga magiker med gryende magisk talang en traditionell övergångsrit: de skapar sitt eget magiska fokus. Mentorer som Belann Windwood i Valanaar vägleder lärlingarna genom denna uråldriga sed och ber dem samla en nedfallen gren från regionens äldsta träd. Dessa vördnadsvärda grenar bär på kvarvarande elementarkrafter från vinden, vilket gör dem till utmärkta ledare för besvärjelser."},{t="Viskningar vid vindaltaret",b="De mest kraftfulla grenarna samlas nära vindaltaret strax söder om Falaath Village, där elementarströmmarna naturligt samlas. Enligt traditionen väljer grenen ofta magikern, och det sägs ibland att den stilla sjunger för dem som är känsliga nog att tämja dess kraft. För äldre som Belann innebär varje elev som fullbordar ritualen att deras kultur förs vidare, särskilt eftersom allt färre i Zephras föds med en magisk gåva för varje år som går."}},faq={{q="Vad är uppdraget Boughs in the Wind?",a="Boughs in the Wind är ett uppdrag som utgör en övergångsrit, där en blivande magiker samlar en vindgenomsyrad nedfallen gren för att skapa sitt eget magiska fokus. Det är en uråldrig sed som bevarar Zephras magiska arv.",al={"vad är boughs in the wind","uppdraget boughs in the wind","uppdrag om magiskt fokus"}},{q="Vem är Belann Windwood?",a="Belann Windwood är en mentor i Valanaar som vägleder unga magiker när de traditionellt skapar sina magiska fokus. Han ser med oro på att allt färre visar en magisk gåva för varje år som går.",al={"vem är belann windwood","belann uppdragsgivare","belann valanaar"}},{q="Var hittar du Wind-Infused Bough?",a="Vindgenomsyrade grenar faller från de äldsta träden nära vindaltaret, strax söder om Falaath Village. Belann hänvisar lärlingarna dit eftersom det uråldriga träet bär på kvarvarande elementarströmmar.",al={"var hittar man vindgren","var finns wind-infused bough","grenens plats"}},{q="Varför skapar unga magiker ett magiskt fokus?",a="Enligt den lokala traditionen skapar lärlingar sitt eget magiska fokus när de visat prov på magisk skicklighet. Fokuset leder elementarkrafter och fungerar både som en kanal för besvärjelser och som en invigning i kulturella riter.",al={"varför skapa magiskt fokus","magiskt fokus syfte","magiskt fokus bakgrund"}},{q="Varför frågar Belann om grenen sjöng för dig?",a="Belann Windwood påpekar att traditionen säger att grenen ofta väljer magikern, snarare än tvärtom. Han säger att en lämplig gren kan tyckas sjunga för någon som är känslig nog att hantera elementarvindar.",al={"grenen väljer magikern","sjungande gren","väljer grenen dig"}},{q="Vad händer med magin i Zephras?",a="Zephras är landet där den här traditionen utövas. Enligt Belann Windwood föds allt färre i Zephras med en naturlig magisk talang för varje år som går, vilket gör det viktigt att de uråldriga riterna förs vidare.",al={"var ligger zephras","magin avtar i zephras","zephras magibakgrund"}}},fp="18,207,17.262.0,27.396.0,37.130.0,23.174.0,41.181.0,47.153.0,46.155.0,38.147.0"}
P.entries["quest:938"] = {n="Mist",s="Mist är ett eskortuppdrag bland Teldrassils skuggiga grenar. Efter att ha hittat en skadad grå sabelkatt som lämnats ensam djupt inne i skogen måste resenärer leda henne tryggt tillbaka till Sentinel Arynia Cloudsbreak vid en närbelägen månskensbrunn.",h="Mist är ett eskortuppdrag bland Teldrassils skuggiga grenar.",kw={"arynia cloudsbreak","mist","månskensbrunn","the oracle tree","sabelkatt","vaktpost","teldrassil"},ang={["class:Hunter"]="Varje djurmästare känner igen den starka hängivenheten och intelligenta blicken i Mists ögon, så att föra henne tryggt tillbaka till sin partner är en fråga om yrkesstolthet.",["faction:Alliance"]="Att hjälpa vaktposterna i Teldrassil stärker den viktiga välviljan mellan den unga Alliansen och världsträdets kaldorei-försvarare.",["race:NightElf"]="Bandet mellan en vaktpost och en sabelkatt är en hörnsten i Night Elf-folkets krigföring och skogskunskap. Genom att rädda Mist värnar du om detta uråldriga, heliga följeslagarskap."},sec={{t="En skadad följeslagare",b="Djupt inne i Teldrassils vilda snår ligger Mist, en särpräglad grå sabelkatt med svåra, skärande sår över rygg och buk. I stället för att uppföra sig som ett vilt djur visar Mist ett anmärkningsvärt lugn och en klar intelligens i sina blå ögon, och söker genast vägledning och skydd hos vänligt sinnade resenärer."},{t="Bakhållens pris",b="Mist är Sentinel Arynia Cloudsbreaks älskade följeslagare. När Arynia patrullerade de väldiga grenarna nära The Oracle Tree överrumplades de av illvilliga häxor som gick till bakhåll och skilde dem åt. Övertygad om att hennes trogna husdjur hade mött en blodig död drog sig Arynia i sorg tillbaka till lugnet vid en närbelägen månskensbrunn, där hon desperat hoppades att Mist ändå hade överlevt."}},faq={{q="Vem är Mist?",a="Mist är en trogen grå sabelkatt och följeslagare till Sentinel Arynia Cloudsbreak. Hon hittas skadad i Teldrassils skogar efter att ha skilts från sin matte under ett våldsamt bakhåll.",al={"mist katt","vad är mist","vem är sabelkatten"}},{q="Vem skadade Mist?",a="Mist och hennes matte överfölls av lokala häxor som lurade i Teldrassils skogar. Angriparna lyckades skilja dem åt och tillfogade katten djupa sår över ryggen och magen.",al={"vem skadade mist","varför blöder mist","häxor överfaller mist"}},{q="Vart ska Mist eskorteras?",a="Mist måste föras tryggt till Sentinel Arynia Cloudsbreak, som väntar vid månskensbrunnen nära The Oracle Tree.",al={"vart ska jag ta mist","lämna in mist","mists destination"}},{q="Vem är Sentinel Arynia Cloudsbreak?",a="Arynia Cloudsbreak är en Night Elf-vaktpost och Mists följeslagare. Hon väntar vid månskensbrunnen nära The Oracle Tree.",al={"arynia cloudsbreak","cloudsbreak","mists ägare"}},{q="Varför knyter Night Elf-vaktposter band till sabelkatter?",a="Night Elf-vaktposter har stridit sida vid sida med Kalimdors stora katter i årtusenden och förlitar sig på dem som stridslystna partners i skärmytslingar, spejare bland de skuggiga grenarna och betrodda följeslagare för livet.",al={"night elf-katter som följeslagare","vaktposternas sabelkatter","varför sabelkatter"}},{q="Var ligger The Oracle Tree i förhållande till räddningsplatsen?",a="The Oracle Tree ligger i nordvästra Teldrassil. Vid en närbelägen månskensbrunn med heligt vatten utför Sentinel Arynia Cloudsbreak sina plikter.",al={"the oracle trees plats","månskensbrunnen mist"}}},fx={["1795c253"]={q="Varför behöver Mist din hjälp?",a="Mist är svårt skadad, med djupa sår över ryggen och magen, och har skilts från sin följeslagare Sentinel Arynia Cloudsbreak. Försvagad och ensam i skogen kan hon inte ta sig genom Teldrassils faror på egen hand och nå tryggheten vid månbrunnen utan ditt beskydd.",al={"varför hjälpa mist","mists motiv","varför behöver mist eskort"}},["94db0917"]={q="Varför förlitar sig Mist på dig i stället för att rädda sig själv?",a="Mist är alltför svårt skadad för att kämpa sig genom den fientliga skogen eller göra den långa färden tillbaka utan hjälp. Hon är ett djur som skilts från sin Sentinel och har inga allierade eller vakter i närheten att vända sig till. När du hittar henne känner hon igen dig som vänligt sinnad och litar på att du kan leda och skydda henne.",al={"varför jag för mist","varför kan mist inte fly ensam","varför följer mist med dig"}}},fp="4,154,19.257.0,19.238.1,12.145.0,17.135.0,30.101.0,35.120.0,50.191.0,52.150.0"}
P.entries["quest:93835"] = {n="Confront Lorthuna",s="En skadad magiker behöver din hjälp med att följa Ayessa Dawnsinger och Elaadrin Evengale genom en portal till Rohashi Spires. Där står de inför High Priestess Lorthuna och behöver din hjälp.",h="En skadad magiker behöver din hjälp med att följa Ayessa Dawnsinger och Elaadrin Evengale genom en portal...",kw={"ayessa dawnsinger","elaadrin evengale","high order","lorthuna","portal","rohashi spires","valennia","zephras"},sec={{t="Genom portalen",b="Lorthuna flydde genom en portal till spirorna ovanför. Ayessa Dawnsinger och Elaadrin Evengale följde efter för en liten stund sedan, men deras följeslagare är för svårt skadad för att följa med. Följ de två magikerna genom portalen när de ställs mot översteprästinnan."},{t="Efter sammandrabbningen",b="De återstående magikerna skickades för att hjälpa Valennia och hennes styrkor att fly. Valennia vilar i High Elder Shadowsongs bostad. Ansirem har återvänt till Azeroth efter att ha diskuterat nästa steg för High Order. Zephras överlevde dagen, men är fortfarande farligt sårbar, och planer måste göras för det som väntar."}},faq={{q="Vem ber mig att följa efter Lorthuna?",a="En skadad magiker ber dig att följa Ayessa Dawnsinger och Elaadrin Evengale genom portalen och hjälpa dem att möta High Priestess Lorthuna.",al={"vem skickade mig","skadad magiker","vem behöver hjälp"}},{q="Vart tog Lorthuna vägen?",a="Lorthuna flydde genom en portal till Rohashi Spires ovanför.",al={"var är lorthuna","lorthunas portal","vart flydde hon"}},{q="Vem följde efter Lorthuna?",a="Ayessa Dawnsinger och Elaadrin Evengale gick genom portalen efter Lorthuna.",al={"ayessa och elaadrin","vem följde efter henne","vem är där uppe"}},{q="Varför kan den skadade magikern inte följa med dem?",a="Magikern fick ta emot för många träffar och måste stanna kvar.",al={"varför går jag ensam","magikern för svårt skadad","varför stanna kvar"}},{q="Var är Valennia?",a="Valennia vilar i High Elder Shadowsongs bostad efter att de återstående magikerna hjälpte henne och hennes styrkor att fly.",al={"var finns valennia","vart tog hon vägen","valennia i säkerhet"}},{q="Vad står på spel nu?",a="Zephras är farligt sårbar, och High Order måste planera för det som väntar.",al={"zephras sårbar","vad hände med zephras","nästa steg för high order"}}},fp="17,176,18.239.0,15.311.1,38.137.0,22.62.0,24.79.0,40.49.0,18.116.0,20.84.0"}
P.entries["quest:93836"] = {n="The Fate of Zephras",s="The Fate of Zephras är ett avgörande uppdrag efter att kultledaren Lorthuna besegrats på Zephras Isle. När öns skyddande slöjande runor har fallit, för du bud om det annalkande elementhotet från Al'Akir och Ayessas föreslagna expedition till Azeroth till High Elder Talaanis Shadowsong i Valanaar.",h="The Fate of Zephras är ett avgörande uppdrag efter att kultledaren Lorthuna besegrats på Zephras Isle.",kw={"al'akir","ayessa","the fate of zephras","lorthuna","muln","shrine of akir","talaanis shadowsong","valanaar","zephras isle"},ang={["class:Shaman"]="Schamaner inser det allvarliga hotet från Vindherren Al'Akir, vars elementarrike omger Zephras när de uråldriga runorna faller.",["race:Skyborne"]="Uppdraget markerar en vändpunkt för Skyborne-folket på Zephras Isle, som väger förlusten av de skyddande runorna och hotet från Al'Akir mot sitt nya uppdrag bortom sitt svävande hem."},sec={{t="En bräcklig seger",b="The Fate of Zephras innebär en avgörande uppgörelse för invånarna på Zephras Isle. Efter den dramatiska konfrontationen ovanför Shrine of Akir har kultledaren Lorthuna dödats, men segern har ett högt pris. De uråldriga runorna som dolde ön för Al'Akirs blick har kollapsat och lämnat den svävande fristaden försvarslös mitt i Vindherrens rike. Som svar skickas en budbärare över ön för att föra bud till Valanaar."},{t="Budet till Valanaar",b="Uppdraget kräver att du talar direkt med High Elder Talaanis Shadowsong i Valanaar. Den äldste får inte bara veta att Lorthuna har dödats och att runorna har brustit, utan också om Ayessas djärva beslut att leda en expedition till Azeroth. När deras magiska slöja är borta beslutar öborna sig för att ge sig ut och söka efter sätt att skydda sitt hem. Shadowsong begrundar blandningen av fruktan och triumf och konstaterar att även om Al'Akir är ett fruktansvärt hot, verkar elementargudar över enorma tidsskalor, vilket kan ge dem dyrbar tid att agera."}},faq={{q="Vad handlar uppdraget The Fate of Zephras om?",a="The Fate of Zephras är ett avgörande uppdrag efter att Lorthuna besegrats vid Shrine of Akir. När de skyddande runorna som dolde Zephras Isle har krossats, för du bud om det annalkande elementhotet och Ayessas föreslagna expedition till Azeroth direkt till High Elder Talaanis Shadowsong i Valanaar.",al={"uppdraget the fate of zephras","vad är the fate of zephras","vad händer i the fate of zephras"}},{q="Varför är Zephras Isle hotad av Al'Akir?",a="Zephras Isle ligger inom elementarriket som tillhör Vindherren Al'Akir. Urruna skyddade tidigare fristaden från hans blick, men nu när försvaret har fallit ligger ön oskyddad och sårbar om elementarherren riktar sin vrede mot den.",al={"varför är zephras hotat","varför anfalla zephras","zephras elementhot"}},{q="Vem är Talaanis Shadowsong?",a="Talaanis Shadowsong är High Elder för Skyborne-folket på Zephras Isle och finns i bosättningen Valanaar. Han ansvarar för sitt folks styre och överlevnad och tar emot rapporter om elementhot och viktiga beslut som påverkar deras hem.",al={"vem är talaanis shadowsong","high elder shadowsong","var finns talaanis shadowsong"}},{q="Vad är Ayessas plan?",a="Ayessa är en viktig person på Zephras Isle som planerar en expedition till Azeroth. Hon inser att ön inte kan stå emot ett angrepp från Al'Akir utan försvar och söker lösningar och allierade utanför deras rike för att säkra sitt folks överlevnad på lång sikt.",al={"vem är ayessa","ayessas plan","vad gör ayessa"}},{q="Vem var Lorthuna och vad hände med henne?",a="Lorthuna var ledare för kulten som verkade på Zephras Isle. Före det här uppdraget dödades hon ovanför Shrine of Akir, vilket bröt organisationens ledarskap, samtidigt som konflikten fick de magiska runorna som skyddade ön att falla.",al={"vem är lorthuna","kultledaren lorthuna","vad hände med lorthuna"}},{q="Vem är Muln?",a="Muln är en rådgivare eller lärd som känner till elementarherrarna. Han varnade Zephras försvarare för Al'Akirs enorma makt och farlighet och bekräftade att de var sårbara utan magiskt skydd.",al={"vem är muln","mulns bakgrund"}}},fp="19,190,20.293.0,20.417.1,44.222.0,43.209.0,27.189.0,22.154.0,42.148.0,12.196.0"}
P.entries["quest:93926"] = {n="The Western Watch",s="The Western Watch är ett brådskande uppdrag att återkalla Peacekeeper Vaaniel och garnisonen från en isolerad utpost i sydväst, som belägras av kultister. De lokala ledarna inser att befästningen inte är värd de liv den kräver och försöker dra tillbaka försvararna för att skydda huvudbosättningen.",h="The Western Watch är ett brådskande uppdrag att återkalla Peacekeeper Vaaniel och garnisonen från en isolerad...",kw={"kult","peacekeeper vaaniel","fredsväktare","stormmagiker","the western watch","vakttorn","västra vakttornet"},sec={{t="En dyrköpt utpost",b="Det västra vakttornet står sydväst om bosättningen och bevakar gränslandet. När fientliga kultister åter började pressa på bedömde de lokala ledarna att den isolerade byggnaden kostade för mycket att försvara. I stället för att offra fler liv på att hålla en utsatt position skrevs order om att återkalla fredsväktarna och samla alla tillgängliga styrkor för att skydda byn och dess invånare."},{t="För sent att dra sig tillbaka",b="Peacekeeper Vaaniel ledde garnisonen som fått i uppdrag att hålla det västra vakttornet mot inkommande hot. Tyvärr kom ordern om reträtt för sent. När budbärarna nådde befästningen hade kultens stormbehärskande magiker redan intagit tornet. Peacekeeper Vaaniel och hans grupp låg döda bland förkolnad sten och blixtsvedda märken."}},faq={{q="Vem är Peacekeeper Vaaniel?",a="Peacekeeper Vaaniel är officeren som leder fredsväktarna vid det västra vakttornet. När kultister anfaller tornet får du i uppdrag att hitta honom och säga åt honom att så fort som möjligt föra tillbaka sin garnison till byn.",al={"vem är vaaniel","vaaniels bakgrund","peacekeeper vaaniel"}},{q="Varför beordrades fredsväktarna att överge vakttornet?",a="De lokala ledarna insåg att det kostade för många liv att hålla det avlägsna västra vakttornet mot kultisternas skoningslösa angrepp. De beslutade att dra tillbaka garnisonen så att försvararna kunde samlas i byn och skydda civilbefolkningen.",al={"varför överge tornet","varför lämna vakttornet","order om västra vakten"}},{q="Vad dödade Peacekeeper Vaaniel?",a="Peacekeeper Vaaniel dödades av kultens magiker, som behärskade stormmagi. Färska bränn- och svedmärken över hans kropp visar att blixtar och rå elementarmagi användes för att slå ut tornets försvarare.",al={"hur dog vaaniel","vem dödade vaaniel","vad dödades fredsväktaren av"}},{q="Vem anföll det västra vakttornet?",a="Angreppet utfördes av en fientlig kult som använde förödande stormmagi. De lokala befälhavarna känner inte till kultens exakta motiv för att ta vakttornet, men deras aggressiva anfall utgjorde ett omedelbart hot mot bosättningarna i närheten.",al={"vem anfaller tornet","kultens angrepp på västra tornet","vilken kult är det"}},{q="Var ligger det västra vakttornet?",a="Vakttornet står sydväst om den lokala bosättningen. Det fungerar som en utpost som bevakar de västra tillfarterna, men det isolerade läget gjorde det sårbart för samordnade angrepp från kultister.",al={"var ligger vakttornet","västra vakttornets läge"}},{q="Vad hände med garnisonen i tornet?",a="När löparna kom med order om att evakuera tillbaka till bosättningen hade vakttornet redan fallit. Peacekeeper Vaaniel och utpostens försvarare övermannades och dödades av kultens magiker strax innan hjälpen kunde nå fram.",al={"vad händer vid tornet","vad hände med vakttornet","överlevde några fredsväktare"}}},fp="17,183,16.329.0,19.264.1,27.189.0,60.173.0,32.152.0,36.180.0,40.148.0,43.184.0"}
P.entries["quest:93927"] = {n="A Last Request",s="A Last Request börjar när du upptäcker en fallen fredsvaktares kropp ute i fält. I den döda vaktens händer finns en blodfläckad lapp med viktiga ledtrådar om hans sista stund. Genom att läsa hans döende ord får du veta hur du kan slutföra hans oavslutade plikt och bringa klarhet i hans öde.",h="A Last Request börjar när du upptäcker en fallen fredsvaktares kropp ute i fält.",kw={"a last request","blodig lapp","död fredsvaktare","fredsvaktare","fredsvaktarens lapp"},sec={{t="En dyster upptäckt",b="A Last Request börjar med en dyster upptäckt ute i fält: en fallen fredsvaktares livlösa kropp. Även i döden håller väktaren fast vid en blodfläckad lapp, som lossnar när du undersöker honom. I dessa oroliga dagar på Zephras får fredsvaktare ofta betala det yttersta priset när de försöker upprätthålla ordningen, och deras döende ord är ofta enda sättet att ta reda på vad som hände dem."},{t="Det sista meddelandet",b="Pergamentet, täckt av blod och lösgjort ur fredsvaktarens händer, innehåller hans sista vädjan eller instruktioner. Den som tog vaktens liv lämnade hans plikt oavslutad, så den som hittar kroppen får tyda ledtrådarna och slutföra hans sista uppdrag. När du läser lappen får du de avgörande anvisningarna för att gå vidare och besvara den fallne väktarens sista rop."}},faq={{q="Vem är den döde fredsvaktaren?",a="Den fallne fredsvaktarens exakta identitet förblir okänd när du först hittar honom. Det som står klart är att han var en ordningens väktare vars plikt fick ett våldsamt slut, och att han bara lämnade efter sig det brådskande meddelandet i sitt grepp.",al={"vem är den döde fredsvaktaren","död fredsvaktare","fredsvaktarens identitet"}},{q="Vad står det på den blodiga lappen?",a="Den blodiga lappen är fredsvaktarens sista redogörelse. Kulten överrumplade hans post: Raani hann aldrig ana vad som väntade, Arvensus fick ett svärd i magen, och själv fälldes han av en blixt och lämnades att dö, övertygad om att såren skulle fullborda det kulten påbörjat.",al={"vad är den blodiga lappen","vad står det på lappen","fredsvaktarens lapp"}},{q="Hur upptäcks denna begäran?",a="Uppdraget börjar så snart du upptäcker och undersöker en fredsvaktares livlösa kropp. När du söker igenom den fallne försvararen hittar du den blodiga lappen i hans livlösa händer, med hans sista vädjan.",al={"hur startar a last request","var hittar man a last request"}},{q="Vad hände med fredsvaktaren?",a="Kulten överföll hans post utan förvarning. Hans kamrater föll, och han träffades av en blixt och lämnades att dö. Han levde precis länge nog för att skriva ner vad som hänt på lappen som hittades i hans händer.",al={"varför dödades fredsvaktaren","vem dödade fredsvaktaren"}},{q="Vad är fredsvaktarens sista begäran?",a="Fredsvaktaren dog innan han hann slutföra sitt uppdrag eller själv överlämna sitt meddelande. När en äventyrare hämtar och undersöker hans blodfläckade lapp kan hen tyda hans sista instruktioner och uppfylla hans döende önskan.",al={"vad är fredsvaktarens begäran","syftet med sista begäran"}},{q="Vilken uppgift har fredsvaktare?",a="Fredsvaktare ska upprätthålla ordningen och skydda bosättningar och vägar från faror. Om de stupar ute i fält blir deras uppgifter ogjorda och deras allierade ovetande, såvida någon inte hämtar deras sista rapporter.",al={"vilka är fredsvaktare","fredsvaktarnas historia"}}},fp="14,146,16.225.0,17.216.0,28.153.0,35.249.0,31.111.0,33.207.0,39.189.0,32.219.0"}
P.entries["quest:93948"] = {n="Deliver the Signet",s="Deliver the Signet är ett uppdrag där en resenär för en återfunnen släktring till High Elder Talaanis Shadowsong i Valanaar. Överlämnandet bekräftar tragiskt att hans brorson har dött på Zephras Isle och öppnar samtidigt nya möjligheter att hjälpa de lokala fredsväktarna.",h="Deliver the Signet är ett uppdrag där en resenär för en återfunnen släktring till High Elder Talaanis...",kw={"deliver the signet","shadowsong family signet","shen'dorei","talaanis shadowsong","valanaar","valennia stormfist","zephras isle"},ang={["race:NightElf"]="Det framträdande släktnamnet Shadowsong för tankarna till älvsläkternas långa historia. Men här på Zephras Isle kämpar High Elder Talaanis och de lokala shen'dorei med sina egna utmaningar."},sec={{t="Ett dystert ärende",b="När en äventyrare reser mot bosättningen Valanaar har hen med sig Shadowsong Family Signet, som återfunnits i ett avlägset torn. Med denna dystra symbol i sin vård söker resenären upp Talaanis Shadowsong, High Elder på Zephras Isle. Trots svåra förhållanden på ön är han älskad av sitt folk. Talaanis måste ta emot det smärtsamma beskedet att hans brorson har dött, tillsammans med kondoleanser och familjeklenoden som återfunnits."},{t="Sorg och plikt i Valanaar",b="När High Elder Talaanis tar emot sigillringen i Valanaar uttrycker han sin uppriktiga tacksamhet trots den djupa sorgen. Han ser vilken skicklighet resenären visat när reliken återfanns och hänvisar hen till Captain Valennia Stormfist, ledare för Valanaars fredsväktare. Bosättningen är hårt pressad och välkomnar all hjälp som dugliga beskyddare kan erbjuda."}},faq={{q="Vem är Talaanis Shadowsong?",a="Talaanis Shadowsong är High Elder på Zephras Isle. Han är högt respekterad och älskad av sitt samhälle, leder sitt folk genom oroliga tider och får utstå en personlig tragedi när han får sigillringen som bekräftar att hans brorson har dött.",al={"vem är talaanis","high elder talaanis","talaanis shadowsongs historia"}},{q="Vad är Shadowsong Family Signet?",a="Sigillet är Shadowsong Family Signet, som återfanns i ett torn. Det bekräftar dystert att Talaanis Shadowsongs brorson har dött och återför en familjeklenod till den sörjande High Elder.",al={"vad är sigillringen","brorsonens ring","shadowsong-sigillet"}},{q="Var ligger Valanaar?",a="Valanaar är en bosättning på Zephras Isle där High Elder Talaanis Shadowsong bor och där Captain Valennia Stormfist leder de lokala fredsväktarna.",al={"var ligger valanaar","bosättningen valanaar","talaanis plats"}},{q="Vem är Valennia Stormfist?",a="Valennia Stormfist är kapten för fredsväktarna i Valanaar. High Elder Talaanis rekommenderar att man talar med henne om arbete och säger att bosättningen är i stort behov av dugligt folk.",al={"vem är valennia stormfist","kapten valennia","kapten för valanaars fredsväktare"}},{q="Vilka är shen'dorei som Talaanis nämner?",a="Talaanis kallar dugliga unga resenärer som kommer ner från högländerna för shen'dorei. Det visar på den älviska närvaro och det arv som lever kvar på Zephras Isle.",al={"vilka är shendorei","shendorei högländerna"}},{q="Vad hände med Talaanis Shadowsongs brorson?",a="Talaanis brorson dog vid ett torn där hans familjesigill gick förlorat. När sigillet förs till Valanaar får High Elder veta att brorsonen har dött, vilket ger ett sorgligt avslut på förlusten.",al={"vad hände med talaanis brorson","hur dog brorsonen"}}},fp="18,224,15.334.0,26.329.0,27.145.0,37.142.0,26.140.0,26.153.0,45.151.0,46.143.0"}
P.entries["quest:93949"] = {n="Bugged",s="Bugged är ett uppdrag i Valanaar där en säsongsvis anstormning av låglandsinsekter visar sig vara en spionkomplott. Magiker från High Order upptäckte att lokala kultister väver avlyssningsförtrollningar på skyhoppare för att spionera på bosättningen, så skadedjuren måste utrotas.",h="Bugged är ett uppdrag i Valanaar där en säsongsvis anstormning av låglandsinsekter visar sig vara en...",kw={"bugged","kult","förtrollade skyhoppare","high order","avlyssningsbesvärjelse","skyhoppare","valanaar"},ang={["class:Mage"]="Magiker från High Order avslöjade magiska avlyssningsskydd som vävts på vanliga skadedjur och använde arkana analyser i kampen mot spionaget."},sec={{t="Avlyssnare i svärmen",b="Under skyhopper-säsongen i låglandet svärmar inhemska insekter runt staden Valanaar. De brukar ses som ett rent säsongsbesvär, men en undersökning av magiker från High Order visade att flera dödade exemplar bar på avancerade avlyssningsförtrollningar. En lokal kult har gjort insektssvärmen till vapen och förvandlat vanliga låglandsskadedjur till diskreta övervakningsverktyg för att avlyssna staden."},{t="Rensa luften",b="Eftersom förtrollade skyhoppare inte går att skilja från vanliga skyhoppare tvingas Valanaars beskyddare gallra ut svärmarna utan urskillning. När insekterna utrotas förlorar den fientliga kulten tillgång till viktig information. Den magiska övervakningen upphör och stadens försvar mot omstörtande verksamhet inifrån stärks."}},faq={{q="Vad är skyhoppare?",a="Skyhoppare är bevingade skadedjur som hör hemma i låglandet runt Valanaar. Under sin säsongsvisa anstormning svärmar de i stora mängder.",al={"vad är skyhoppare","skyhopperinsekt"}},{q="Vem förtrollade insekterna?",a="Lokala kultister misstänks fånga skyhoppare och lägga magiska avlyssningsbesvärjelser på dem för att spionera på bosättningen.",al={"vem förtrollade insekterna","kultens avlyssningsinsekter","vem spionerar i valanaar"}},{q="Hur ser du vilka skyhoppare som är förtrollade?",a="Förtrollade skyhoppare ser ut precis som vanliga insekter för blotta ögat. Först när svärmarna utrotas kan de magiskt laddade spionerna hittas och oskadliggöras.",al={"hur ser man förtrollade skyhoppare","vilka insekter är förtrollade"}},{q="Var utspelar det sig?",a="Insektsangreppet och spionaget äger rum runt Valanaar, en luftburen stad där säsongssvärmar stiger upp från det angränsande låglandet.",al={"var finns uppdraget bugged","valanaars insekter"}},{q="Vilken sorts förtrollning lades på skyhopparna?",a="Magiker från High Order undersökte dödade insekter och upptäckte en särskild avlyssningsbesvärjelse som bundits till dem. Den gjorde varelserna till rörliga övervakningsverktyg.",al={"vilken besvärjelse finns på insekterna","skyhopperförtrollning"}},{q="Varför måste alla skyhoppare utrotas?",a="Eftersom det inte går att se skillnad på förtrollade skyhoppare och vanliga skadedjur måste svärmen rensas ut. Då kan kultens nätverk av magiska avlyssningsposter utplånas och Valanaar skyddas.",al={"varför döda skyhoppare","målet med uppdraget bugged"}}},fp="6,188,26.244.0,16.206.0,20.124.0,26.96.0,47.121.0,27.115.0,54.115.0,50.165.0"}
P.entries["quest:93951"] = {n="A Little Beauty",s="A Little Beauty är ett lokalt uppdrag i Shen'dar Highlands där resenärer samlar mjuka hippogryffjädrar nära Zephras. Skyborne använder de färgstarka fjädrarna för att pryda håret och ge byn en stund av enkel glädje och skönhet i svåra tider.",h="A Little Beauty är ett lokalt uppdrag i Shen'dar Highlands där resenärer samlar mjuka hippogryffjädrar nära...",kw={"a little beauty","dunfjädrar","fjädrar","hippogryff","fjäderplymer","shen'dar highlands","skyborne","zephras"},ang={["race:Skyborne"]="När Skyborne på Zephras samlar färgstarka hippogryffdun kan de pryda håret med mjuka fjädrar, hålla sina traditioner vid liv och finna små glädjeämnen trots svårigheterna."},sec={{t="Höglandets fjädrar",b="På Zephras Isle, sydväst om byn, har vilda hippogryffer slagit sig ner och häckar i Shen'dar Highlands. Dessa revirhävdande bestar kan vara till besvär för resenärer i närheten, men de fäller ovanligt färgstarka och silkeslena dunfjädrar. För de lokala Skyborne är de tappade fjädrarna ett tillfälle att skapa utsökta prydnader som vävs direkt in i håret."},{t="Glädje i det lilla",b="Att samla prydnadsfjädrar till håret kan verka som ren fåfänga, men hantverkaren i Zephras ser det som något nödvändigt. Även när omständigheterna är hårda hjälper det samhället att finna och dela små vardagsglädjeämnen. Skönhet i bybornas liv gör att varje dag rymmer något värt att fira."}},faq={{q="Varför samlar man hippogryffjädrar?",a="Dunfjädrar från vilda hippogryffer samlas in för att skapa hårprydnader åt de lokala Skyborne. Hippogryfferna nära bosättningen kan vara till besvär, men deras tappade fjädrar uppskattas för att de är ovanligt silkeslena och färgstarka.",al={"varför samla fjädrar","vad används fjädrar till","fjädrarnas syfte"}},{q="Vad är Zephras?",a="Zephras är Zephras Isle, ön där Skyborne bor och där uppdraget äger rum. Den lokala hantverkaren gör hårprydnader av de insamlade fjädrarna för att skänka invånarna glädje och lättsamma stunder.",al={"vem är zephras","vilken by är det här","var händer det här"}},{q="Var häckar hippogryfferna?",a="De vilda hippogryfferna häckar sydväst om byn i Shen'dar Highlands. Eftersom vilda hippogryffer är mycket revirhävdande och inte tolererar objudna gäster krävs försiktighet när man samlar tappade fjädrar kring deras bon.",al={"var finns bona","var finns hippogryffer","shen'dar highlands plats"}},{q="Varför är små förnöjelser som hårprydnader viktiga i sådana här tider?",a="Att pryda håret med fjädrar kan verka som en fåfäng småsak, men uppdragsgivaren förklarar att det är viktigt att omfamna små glädjeämnen och skönhet, särskilt i svåra tider. Ansträngningen är värd det om den ger andra en stunds lycka.",al={"är fjädrar viktiga","varför hårprydnader","fåfäng småsak"}},{q="Är hippogryfferna fientliga mot besökare?",a="Hippogryfferna som lever sydväst om byn är vilda varelser. De betraktar sina häckningsplatser som sitt revir och tolererar inte inkräktare, så ovana resenärer riskerar att råka illa ut när de samlar deras tappade dunfjädrar.",al={"varför är hippogryffer farliga","är hippogryffer vilda"}},{q="Är det vanligt bland Skyborne att pryda håret med fjädrar?",a="Ja, många Skyborne tycker om att väva in färgstarka fjädrar i håret som personliga prydnader. Hippogryffernas ovanligt mjuka dunfjädrar passar utmärkt till dessa prydnader.",al={"skyborne-fjädrar","bär skyborne fjädrar"}}},fp="15,157,23.241.0,27.222.0,44.173.0,16.159.0,30.152.0,74.139.0,40.161.0,59.131.0"}
P.entries["quest:93958"] = {n="The Inner Sanctum",s="The Inner Sanctum kretsar kring en farlig rekognosering i Shrine of Akirs innersta kammare. Efter att Valennia Stormfist och hennes anfallsstyrka brutit igenom till The Sanctum under hårda strider lade sig en kuslig tystnad över området. Nu måste någon snabbt ta reda på om några överlevande finns kvar.",h="The Inner Sanctum kretsar kring en farlig rekognosering i Shrine of Akirs innersta kammare.",kw={"the inner sanctum","shrine of akir","stormfist","valennia","valennia stormfist","valennia stormnäve"},sec={{t="En plötslig tystnad",b="Efter ett intensivt anfall ledde Valennia Stormfist sin styrka genom en bräsch in till The Sanctum i Shrine of Akir. Den första sammanstötningen följdes av ljudet av hårda, desperata strider långt inne i kamrarna. Snart tystnade ljuden tvärt och oroväckande, och de allierade utanför började frukta det värsta."},{t="Priset för genombrottet",b="När du går in i det tysta The Sanctum ser du det dystra priset för anfallet. I stället för en segerrik förtrupp som säkrat platsen finner du Valennia Stormfist svårt sårad efter striden. Förtruppens öde är fortfarande ovissare än någonsin."}},faq={{q="Vem är Valennia Stormfist?",a="Valennia Stormfist är en befälhavare som leder ett anfall in i Shrine of Akirs djup. Hon gick i spetsen för genombrottet in i The Sanctum med sina styrkor, men den våldsamma striden där inne tystnade plötsligt och kusligt.",al={"vem är valennia","vem är valennia stormfist","valennia"}},{q="Vad är Shrine of Akir?",a="Shrine of Akir rymmer ett The Sanctum som just nu är under anfall. Valennias trupper bröt igenom dess försvar under hårda strider, och platsen har blivit centrum för en spänd och dödlig sammandrabbning.",al={"vad är shrine of akir","shrine of akir i berättelsen","akir-helgedomen"}},{q="Vad hände med Valennias styrkor där inne?",a="Strax efter genombrottet ekade hårda strider där inne, men ljuden upphörde plötsligt. Ett oroväckande lugn lade sig över The Sanctum, och de allierade utanför började frukta att Valennias förtrupp hade övermannats eller utplånats.",al={"varför är det tyst","vad hände med valennias styrkor","valennias soldater"}},{q="Lever Valennia Stormfist fortfarande?",a="Valennia överlever anfallet, men hittas svårt sårad i The Sanctum i Shrine of Akir när striderna har lagt sig.",al={"lever valennia","dog valennia","valennias öde"}},{q="Vad är målet inne i The Sanctum?",a="The Sanctum är den djupaste kammaren i Shrine of Akir. Uppdraget går ut på att du går in ensam, undersöker följderna av genombrottet och tar kontakt med Valennia och eventuella överlevande stridskämpar.",al={"vad är the inner sanctum","syftet med uppdraget the inner sanctum"}},{q="Vem skickar dig in i The Sanctum?",a="En allierad som håller uppsikt över området bakom er, utanför The Sanctum, skickar in dig. Medan de håller försvarslinjen och ser till att du har ryggen fri skickar de dig framåt för att ansluta dig till Valennias förtrupp.",al={"vem skickar dig till valennia","uppdragsgivare för the inner sanctum"}}},fp="17,175,16.262.0,22.139.1,26.177.0,27.173.0,42.173.0,34.123.0,47.158.0,37.156.0"}
P.entries["quest:93963"] = {n="Exploring the Alliance",s="Du börjar Exploring the Alliance i Stormwind Keep och reser sedan för att träffa härskarna i Ironforge och Darnassus. Deras länder visar hur vidsträckt Alliansen är innan du vänder mot Westfall.",h="Du börjar Exploring the Alliance i Stormwind Keep och reser sedan för att träffa härskarna i Ironforge och...",kw={"dalaran","darnassus","exploring the alliance","high tinker mekkatorque","ironforge","magni bronzebeard","randal emerson","stormwind keep","tyrande whisperwind","westfall"},ang={["faction:Alliance"]="Som nykomling i Alliansen besöker du dess främsta fästen och möter ledarna som håller pakten samman.",["race:Skyborne"]="Som Skyborne-gäst på Azeroth uppmanas du att lära känna de allierade folken som ger dig skydd, medan din orden förbereder sig på att slå sig ned i Dalaran."},sec={{t="En rundtur bland allierade länder",b="Randal Emerson, en tjänare i Stormwind Keeps södra förmak, skickar dig bortom människornas huvudstad. Du har nyligen anlänt till Azeroth, och Alliansen bjuder in dig att själv möta dess allierade folk. Resan tar dig bortom borgen, där du får lära dig om de skilda kulturerna, traditionerna och styrkan hos dem som står vid Stormwinds sida."},{t="Möten med de främsta ledarna",b="Dina resor går över land och hav till Alliansens ledare. I Ironforge möter du King Magni Bronzebeard i bergets salar och High Tinker Gelbin Mekkatorque, ledare för de fördrivna gnomerna. I Darnassus, högt uppe på Teldrassil, möter du High Priestess Tyrande Whisperwind. Deras städer och folk visar banden mellan människor, dvärgar, gnomer och nattalver."},{t="En värld i behov av hjälp",b="Efter den långa resan återvänder du till Stormwind. Kunskap om Azeroth hjälper dig att bistå ditt eget folk, medan din orden förbereder sig på att slå sig ned i Dalaran. För tillfället behöver de oroliga trakterna nära huvudstaden hjälp, med början i Westfalls kämpande jordbruksmarker."}},faq={{q="Vad är uppdraget Exploring the Alliance?",a="Du reser tvärs över Azeroth för att möta ledarna vid Alliansens viktigaste maktcentra. Resan för dig inför härskarna i Ironforge och Darnassus samt High Tinker Gelbin Mekkatorque, ledare för gnomerna i exil.",al={"uppdraget exploring the alliance","vad är det här för uppdrag"}},{q="Vem är Randal Emerson?",a="Randal Emerson är en tjänare i Stormwind Keeps södra förmak. Han visar resenärer vägen till de andra huvudstäderna.",al={"randal emerson","vem visar vägen"}},{q="Vilka ledare ska besökas under resan?",a="Du besöker King Magni Bronzebeard i Ironforge, High Tinker Gelbin Mekkatorque och High Priestess Tyrande Whisperwind i Darnassus. Var och en leder ett av Alliansens kärnfolk och dess maktcentrum.",al={"besökta ledare","vem ska jag prata med"}},{q="Varför nämns Dalaran när uppdraget slutförs?",a="Din orden förbereder sig på att etablera sin närvaro i Dalaran. Medan förberedelserna pågår uppmuntras du att lära dig mer om Azeroth och hjälpa de närliggande trakterna.",al={"varför nämns dalaran","orden i dalaran"}},{q="Vart leder vägen efter den här resan?",a="När du återvänt till Stormwind Keep beger du dig mot landsbygden nära huvudstaden, närmare bestämt Westfall. De oroliga samhällena där behöver snarast kapabla försvarare.",al={"vart ska jag gå härnäst","efter exploring the alliance"}},{q="Varför behandlas äventyraren som gäst hos Alliansen?",a="Du behandlas som en främling som nyligen anlänt till Azeroth, och förväntas förstå den större världen så att du kan skydda och hjälpa ditt eget folk. Resan låter dig lära känna Alliansens skiftande kulturer.",al={"gäst hos alliansen","varför gäst"}}},fp="22,167,22.330.0,29.363.0,22.273.0,41.223.0,22.133.0,50.195.0,51.170.0,55.165.0,57.211.0"}
P.entries["quest:94"] = {n="A Watchful Eye",s="Theocritus håller Morganth under uppsikt från Tower of Azora i Elwynn Forest. Han skickar resenärer österut till Redridge Mountains för att placera en förtrollad runa vid en gammal lejonstaty nära Tower of Ilgalar.",h="Theocritus håller Morganth under uppsikt från Tower of Azora i Elwynn Forest.",kw={"elwynn","glyph of azora","morganth","old lion statue","redridge","theocritus","tower of azora","tower of ilgalar"},ang={["class:Mage"]="Som magiker ser du hur magisk spådom kan nå över stora avstånd. Theocritus använder metoder från Elwynn, medan Morganth utövar laglös trolldom.",["faction:Alliance"]="Som medlem i Alliansen hjälper du till att vakta gränsen mellan Elwynn Forest och de belägrade bosättningarna i Redridge Mountains mot laglösa mänskliga magiker som Morganth."},sec={{t="En rivalitet över gränsen",b="Theocritus håller uppsikt över kullarna från sitt torn i östra Elwynn Forest. Hans rival, Morganth, är en mäktig trollkarl som har lagt beslag på Tower of Ilgalar i Redridge Mountains. Theocritus fruktar att Morganths mörka magi kan korsa gränsen, så han skapade Eye of Azora för att hålla den laglöse trollkarlen under uppsikt på avstånd."},{t="Lejonets vakthållning",b="Theocritus behöver mer än en avlägsen utsikt för att få veta vad Morganth planerar. Han ger resenärer Glyph of Azora och skickar dem till Old Lion Statue nära Tower of Ilgalar. Statyn har hållit vakt där i årtionden. Placera runan i den slitna fördjupningen vid dess fot, så upprättas en magisk förbindelse till Azora. Då kan Theocritus blicka in i sin rivals sinne."}},faq={{q="Vem är Theocritus?",a="Theocritus är en magiker i Alliansen som bor i Tower of Azora i östra Elwynn Forest. Han studerar magi för att skydda trakten från laglösa magiker, särskilt Morganth.",al={"theocritus","magiker i tower of azora","vem ger uppdraget a watchful eye"}},{q="Vem är Morganth?",a="Morganth är en laglös mänsklig magiker som gjort Tower of Ilgalar i Redridge Mountains till sitt fäste. Han är Theocritus bittra rival, och Theocritus fruktar de planer han smider mot de omgivande länderna.",al={"morganth","vem är morganth","rivaliserande magiker"}},{q="Var ligger Old Lion Statue?",a="Old Lion Statue står på höjdryggarna med utsikt över Tower of Ilgalar, bland de östra kullarna i Redridge Mountains. En grund fördjupning vid statyns fot rymmer Glyph of Azora.",al={"lejonstatyns plats","var står statyn","var placera glyph of azora"}},{q="Vad gör Glyph of Azora?",a="Glyph of Azora är en förtrollad sten som skapats av Theocritus. När den placeras i lejonstatyn nära Tower of Ilgalar förmedlar den hans magiska lyssningsbesvärjelse och låter honom utforska Morganths tankar.",al={"glyph of azora","vad är glyph of azora"}},{q="Vad är Tower of Ilgalar?",a="Tower of Ilgalar är ett ensligt stentorn högt uppe bland klipporna i östra Redridge Mountains. Morganth och hans tjänare håller till där och försvarar tornet.",al={"tower of ilgalar","ilgalar"}},{q="Vad händer efter att runan placerats?",a="När Glyph of Azora har placerats i statyn talar Theocritus genom stenen och erbjuder Looking Further. Han börjar avslöja Morganths planer.",al={"nästa uppdrag","vad händer efter a watchful eye"}}},fx={["0c307b8a"]={q="Varför vill Theocritus att detta ska göras?",a="Morganth är en hänsynslös magiker med väldig kraft som håller till i Tower of Ilgalar. Theocritus kan se sin rival med hjälp av Eye of Azoras skådande magi, men det räcker inte längre att bara se honom. Genom att fästa Glyph of Azora på den närbelägna lejonstatyn hoppas Theocritus kunna tränga in i Morganths sinne och upptäcka vad den mörke trollkarlen planerar, innan han släpper lös det över området.",al={"theocritus motiv","varför placera glyph of azora","varför spionera på morganth"}}},fp="14,186,27.296.0,16.348.0,18.173.0,16.201.0,37.175.0,32.188.0,29.144.0,35.150.0"}
P.entries["quest:940"] = {n="Teldrassil",s="Efter att de kringströvande harpiorna nära The Oracle Tree har rensats ut, anförtror Sentinel Arynia Cloudsbreak dig uppgiften att bära en lägesrapport till Darnassus. Den inskrivna barken är adresserad till Arch Druid Fandral Staghelm och innehåller nyheter om grenarnas tillstånd och den pågående korruption som plågar Världsträdet.",h="Efter att de kringströvande harpiorna nära The Oracle Tree har rensats ut, anförtror Sentinel Arynia...",kw={"arynia cloudsbreak","cenarion enclave","darnassus","fandral staghelm","odödlighet","inscribed bark","kaldoreier","oracle tree","teldrassil"},ang={["class:Druid"]="Att bära bud från det uråldriga The Oracle Tree direkt till ledaren för Cenarion Circle belyser den pågående kampen för att återställa Teldrassils naturliga balans.",["faction:Alliance"]="För alliansens mästare som utför sina första uppdrag på ön innebär detta uppdrag en formell introduktion till nattalvernas huvudstad och dess stränga ledarskap.",["race:NightElf"]="När du överlämnar rapporten möter du Arch Druid Staghelm öga mot öga och får se hans personliga besatthet av att återställa kaldoreiernas odödlighet genom Teldrassils plågade grenar."},sec={{t="En budbärare till stenstaden",b="Djupt bland Teldrassils grenar vakar The Oracle Tree över skogen. När du har rensat bort harpiorna från deras bon i The Oracle Glade beslutar Sentinel Arynia Cloudsbreak att det äntligen är säkert att skicka bud till kaldoreiernas ledare. Hon anförtror dig en bit inskriven bark och skickar dig genom vildmarken till Darnassus, den stora ”skogen av sten”, för att överlämna The Oracle Trees rapport direkt till Arch Druid Fandral Staghelm."},{t="Staghelms ambition och frustration",b="När Fandral Staghelm får rapporten tar han emot den med blandade känslor. Han är tacksam över nyheten att harpiorna har drivits tillbaka, men rapporten understryker en djupare sanning: så snart ett hot på Teldrassil minskar, gror ett annat i dess ställe. För Staghelm, som drev på planteringen av det nya Världsträdet för att återge nattalverna deras förlorade odödlighet, är de fortsatta plågorna bland grenarna en bitter påminnelse om att hans storslagna verk är långt ifrån färdigt."}},faq={{q="Vad är syftet med uppdraget ”Teldrassil”?",a="Uppdraget fungerar som en berättelsemässig bro mellan dina äventyr i vildmarken kring The Oracle Tree och huvudstaden. Sentinel Arynia Cloudsbreak ger dig i uppgift att ta med en Inscribed Bark med The Oracle Trees rapport till Arch Druid Fandral Staghelm i Darnassus.",al={"uppdragsmål för teldrassil","vad gör det här uppdraget","överlämning i teldrassil"}},{q="Vem är Sentinel Arynia Cloudsbreak?",a="Arynia Cloudsbreak är en nattalvssentinell som är stationerad nära The Oracle Tree i Teldrassils vildmarker. Hon håller uppsikt över regionala hot som de lokala Bloodfeather-harpiorna och samordnar skogens försvar med Darnassus.",al={"arynia cloudsbreaks historia","vem startar uppdraget teldrassil"}},{q="Varför kallar Arynia Darnassus för en ”skog av sten”?",a="Nattalverna lever bland Världsträdets trädkronor, men staden Darnassus är byggd av monumentala marmor- och stentempel, broar och paviljonger. Jämfört med den otämjda vildmarken kring The Oracle Tree är huvudstaden en konstruerad skog av sten.",al={"betydelsen av skog av sten","varför skog av sten"}},{q="Varför är Fandral Staghelm så bekymrad över The Oracle Trees rapport?",a="Staghelm ledde arbetet med att skapa Teldrassil i hopp om att återfå kaldoreiernas odödlighet efter att Nordrassil skadades under det tredje kriget. Nyheterna från The Oracle Tree bekräftar att Teldrassil fortfarande plågas av utbredd korruption och oro bland djurlivet, vilket hotar hans ambitioner.",al={"fandral staghelms reaktion","varför är staghelm orolig"}},{q="Vilket uppdrag leder fram till detta, och vad följer sedan?",a="Det här uppdraget följer direkt efter ”The Enchanted Glade”, där du tar itu med harpiorna som hotar The Oracle Tree. När du har överlämnat rapporten till Arch Druid Staghelm skickar han dig vidare till Darkshore med uppföljningsuppdraget ”Grove of the Ancients”.",al={"uppdragskedjan i teldrassil","vilket uppdrag kommer härnäst"}},{q="Var hittar man Arch Druid Fandral Staghelm?",a="Arch Druid Fandral Staghelm bor i Darnassus och står på toppen av Cenarion Enclave, där han övervakar Cenarion Circles druider och vägleder kaldoreiernas styre.",al={"var finns fandral","fandral staghelms plats"}}},fx={d4229979={q="Varför vill Sentinel Arynia Cloudsbreak att den här rapporten levereras?",a="Arynia behöver att Arch Druid Fandral Staghelm får rapporten från The Oracle Tree, så att Darnassus hålls informerat om trädets tillstånd. Skogen har lidit av harpyangrepp och onaturlig förruttnelse, och tidigare budbärare har inte klarat färden. Nu när lugnet har återvänt till The Oracle Glade måste nyheterna nå Arch Druid, så att ledarna kan bedöma världsträdets tillstånd.",al={"varför skicka rapporten till fandral","arynia cloudsbreaks motiv","varför vill arynia få rapporten levererad"}},["174bd7d2"]={q="Varför skickar Arynia Cloudsbreak dig i stället för en annan budbärare?",a="Tidigare budbärare som skickats längs skogsstigarna har inte nått Darnassus eller försvunnit på vägen, så Arynia tvekar att riskera ännu en vanlig kurir. Du har visat mod och stridsförmåga genom att rensa The Oracle Glade från harpyor. Därmed har du vunnit skogens gunst och visat att du kan försvara dig själv och budskapet på de farliga vägarna till staden.",al={"varför skicka mig till darnassus","varför inte skicka en annan budbärare","varför behöver arynia dig"}}},fp="10,203,29.359.0,35.336.0,46.188.0,35.219.0,51.210.0,68.276.0,48.200.0,47.172.0"}
P.entries["quest:94003"] = {n="The Skybreaker Bulwark",s="The Skybreaker Bulwark är ett uppdrag på Zephras Isle som handlar om Skybreaker-släktens tragiska undergång. Äventyrare ska ta sig till Shrine of Akir för att återta en helig förfäderssköld från kultisten Zaal Stormshield.",h="The Skybreaker Bulwark är ett uppdrag på Zephras Isle som handlar om Skybreaker-släktens tragiska undergång.",kw={"al'aketh","shrine of akir","skybreaker","skybreaker bulwark","skybreaker defense","the skybreaker bulwark","zaal stormshield","zephras isle"},ang={["class:Paladin"]="Sköldbärande försvarare som vördar heliga reliker kommer att uppskatta möjligheten att återta ett välsignat arvegods ur händerna på en korrumperad kultist.",["class:Warrior"]="Krigare som värdesätter defensiv skicklighet finner här ett syfte som passar dem: för att återfå förfädersskölden belönas de med undervisning i tekniken Skybreaker Defense."},sec={{t="En fallen släkt",b="På Zephras Isle har Skybreaker-släktens urgamla släktlinje gått ett tragiskt öde till mötes genom Al'Akeths hand. Familjen mördades brutalt, och endast en enda överlevare blev kvar, tyngd av djup sorg och bitter skam över att ha förlorat familjens främsta arvegods. Denna dyrbara relik, Skybreaker Bulwark, togs av kultisten Zaal Stormshield, som nu håller till vid Shrine of Akir."},{t="Den heliga skölden",b="Enligt familjetraditionen har Skybreaker Bulwark en skyddande välsignelse: ingen skada kan drabba den som verkligen är värdig att bära den. Den siste Skybreakern anser att kultisten Zaal inte förtjänar dess gudomliga ynnest och söker därför en äventyrare som kan ta sig till Shrine of Akir, fälla tjuven och återta förfädersskölden. Som belöning får äventyraren lära sig tekniken Skybreaker Defense."}},faq={{q="Vilka är Skybreakers?",a="Skybreakers är en urgammal släkt på Zephras Isle vars medlemmar nästan helt har utplånats. Uppdragsgivaren är den enda överlevande ur denna släktlinje, sedan resten dödats av Al'Aketh.",al={"vilka är skybreakers","skybreaker-familjen"}},{q="Vad är Skybreaker Bulwark?",a="Skybreaker Bulwark är en förfäderssköld som tillhör Skybreaker-släkten på Zephras Isle. Enligt familjens tradition och berättelser kan ingen skada drabba den som anses värdig att bära skölden.",al={"vad är skybreaker bulwark","skölden","skybreaker-sköldens historia"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är den fientliga styrka som ligger bakom massakern på Skybreaker-familjen på Zephras Isle. Endast en ensam överlevare blev kvar för att sörja förlusten.",al={"vem dödade skybreakers","vad är al'aketh","al'aketh"}},{q="Vem är Zaal Stormshield?",a="Zaal Stormshield är en kultist som stal Skybreaker Bulwark efter Skybreaker-familjens undergång. Han bär arvegodset vid Shrine of Akir på Zephras Isle.",al={"vem har skölden","zaal","stormshield"}},{q="Var ligger Shrine of Akir?",a="Shrine of Akir är en plats på Zephras Isle där kultisten Zaal Stormshield har tagit sin tillflykt med den stulna Skybreaker Bulwark.",al={"var är zaal","shrine of akir-plats","var hittar man skölden"}},{q="Varför måste Bulwark återtas?",a="När arvegodset återtas gottgörs familjens skam och den heliga reliken tas ur ovärdiga händer. Som tack för att den återtas lär den siste Skybreakern ut Skybreaker Defense.",al={"varför återta skölden","vad är skybreaker defense","sköldbelöning"}}},fp="22,144,16.273.0,17.345.0,24.143.0,31.153.0,21.98.0,24.166.0,28.103.0,34.187.0"}
P.entries["quest:94006"] = {n="The Great Ursera Spirit",s="En druid skickar dig för att möta Urs'endris, en ande på Zephras som har lärt druider urseraformen i generationer. Hans rike förtvinar, och Urs'endris kan vägleda dig vidare i dina studier.",h="En druid skickar dig för att möta Urs'endris, en ande på Zephras som har lärt druider urseraformen i...",kw={"druid","vattenfall","shrine of akir","ande","urs'endris","ursera","valanaar","zephras"},ang={["class:Druid"]="Som druid har dina studier fört dig till Urs'endris, som har lärt druider urseraformen i generationer."},sec={{t="Den stora anden",b="En druid skickar dig till Urs'endris nära vattenfallen nordost om Valanaar. Dina druidiska studier har lett dig till ett möte med en av Zephras stora andar. Urs'endris har lärt druider att anta urseraformen i generationer, och hans rike förtvinar och försvinner ut i himlen."}},faq={{q="Vem är Urs'endris?",a="Urs'endris är en vis ande på Zephras som har lärt druider att anta urseraformen i generationer.",al={"vem är urs'endris","stor ande urs","urseraande"}},{q="Var hittar jag Urs'endris?",a="Urs'endris finns nära vattenfallen nordost om Valanaar, nära Shrine of Akir.",al={"urs'endris plats","var är urs'endris","möta anden"}},{q="Varför skickas jag till Urs'endris?",a="Du har kommit tillräckligt långt i dina druidiska studier för att möta en av Zephras stora andar, och Urs'endris kan undervisa dig vidare.",al={"varför möta urs'endris","druid ande uppdrag","urserastudier"}},{q="Vad händer med Urs'endris rike?",a="Urs'endris rike har börjat förtvina och falla upp i himlen.",al={"förtvinande rike","zephras faller","vad är fel där"}},{q="Vad är urseraformen?",a="Urseraformen är en form som Urs'endris har lärt druider att anta i generationer.",al={"urseraform","klons väg","ursera"}}},fp="23,185,16.270.0,18.102.0,28.76.0,34.132.0,41.62.0,25.80.0"}
P.entries["quest:94007"] = {n="Taming the Beast",s="I Valanaar kan Quel'ana Quickgale lära dig att tämja ett vilddjur. Din tid i höglandet har förberett dig för att söka en djurföljeslagare.",h="I Valanaar kan Quel'ana Quickgale lära dig att tämja ett vilddjur.",kw={"djurföljeslagare","tämja vilddjur","höglandet","quel'ana quickgale","taming the beast","valanaar"},sec={{t="En ny följeslagare",b="Din värd tror att du är redo att söka en djurföljeslagare efter din tid i höglandet. Bege dig till Valanaar och tala med Quel'ana Quickgale. Han lär dig konsten att tämja vilddjur."}},faq={{q="Vem lär ut konsten att tämja vilddjur?",a="Quel'ana Quickgale lär dig att tämja vilddjur i Valanaar.",al={"vem är quel'ana quickgale","lärare i att tämja vilddjur"}},{q="Var hittar jag Quel'ana Quickgale?",a="Quel'ana Quickgale finns i Valanaar, hamnen i sydost.",al={"var finns quel'ana","valanaar tämjning"}},{q="Varför ska jag till Valanaar?",a="Du skickas till Valanaar för att tala med Quel'ana Quickgale och börja lära dig att tämja vilddjur.",al={"varför valanaar","uppdrag tämja vilddjur"}},{q="Vad ska jag lära mig?",a="Quel'ana Quickgale ska lära dig att tämja ett vilddjur så att du kan söka en djurföljeslagare.",al={"vad innebär det att tämja vilddjur","djurföljeslagare"}}},fp="16,135,15.187.0,25.58.0,35.61.0,27.92.0,19.86.0"}
P.entries["quest:94013"] = {n="Taming the Beast",s="Quel'ana Quickgale ger dig ett sista prov där du ska tämja en Vuldren Alpha. Att klara det förbereder dig för din klass djupare lärdomar.",h="Quel'ana Quickgale ger dig ett sista prov där du ska tämja en Vuldren Alpha.",kw={"djurföljeslagare","gustberry lowlands","quel'ana quickgale","taming rod","taming the beast","valanaar","vuldren alpha","zephras isle"},sec={{t="Det sista provet",b="Quel'ana ger dig en Taming Rod och skickar dig till Gustberry Lowlands. Där ska du tämja en Vuldren Alpha. Lämna sedan tillbaka staven till honom i Valanaar. Det här provet visar din skicklighet och förbereder dig för djupare lärdomar inom din klass."},{t="En ny lärdom",b="När du återvänder säger Quel'ana att du har lärt dig grunderna. Han erbjuder sig att lära dig att knyta ett bestående band till en djurföljeslagare. Han uppmanar dig att föra den kunskapen vidare till gagn för den klass som Zephras Isle behöver."}},faq={{q="Vad ber Quel'ana mig att tämja?",a="Quel'ana ber dig att tämja en Vuldren Alpha med Taming Rod i Gustberry Lowlands.",al={"tämja vuldren alpha","vilket vilddjur","tämja alpha"}},{q="Var hittar jag en Vuldren Alpha?",a="Vuldren Alpha finns i Gustberry Lowlands.",al={"var finns alpha","gustberry lowlands","var tämja vilddjur"}},{q="Vad används Taming Rod till?",a="Quel'ana ger dig Taming Rod för att tämja en Vuldren Alpha.",al={"stavens syfte","taming rod uppdrag","hur använda staven"}},{q="Var lämnar jag tillbaka Taming Rod?",a="Lämna tillbaka Taming Rod till Quel'ana Quickgale i Valanaar.",al={"lämna tillbaka staven","var finns quelana","var lämna tillbaka taming rod"}},{q="Vad får jag lära mig efter det här?",a="Quel'ana säger att han kan lära dig att knyta ett bestående band till en djurföljeslagare.",al={"nästa lärdom","band till djurföljeslagare","vad kommer sedan"}}},fp="16,136,15.228.0,12.223.1,34.88.0,34.47.0,27.58.0,33.56.0,29.79.0"}
P.entries["quest:94050"] = {n="Training the Beast",s="I Valanaar möter du Quel'dora Quickgale för att lära dig att träna ditt djur. Hon lär dig att ta hand om och vägleda det.",h="I Valanaar möter du Quel'dora Quickgale för att lära dig att träna ditt djur.",kw={"mata djur","jägare","djurträning","quel'dora quickgale","återuppliva djur","tämja djur","training the beast","valanaar"},ang={["class:Hunter"]="Som jägare lär du dig att träna och vägleda ett djur som du redan kan tämja."},sec={{t="Quel'doras undervisning",b="Din jägarkamrat skickar dig till sin syster, Quel'dora Quickgale, i Valanaar. Du vet redan hur man tämjer ett djur. Nu kan Quel'dora lära dig att träna din följeslagare."},{t="En jägares ansvar",b="Quel'dora lär dig att vägleda ditt djur, lära det nya förmågor, mata det och återuppliva det om det faller i strid. Hon uppmanar dig att respektera balansen och bevara din vördnad inför naturen omkring dig."}},faq={{q="Vem är Quel'dora Quickgale?",a="Quel'dora Quickgale är syster till jägaren som skickar dig för att lära dig att träna djur.",al={"vem är queldora","quel'dora","quickgale"}},{q="Var hittar jag Quel'dora?",a="Quel'dora Quickgale finns i Valanaar.",al={"var finns queldora","quel'doras plats","tränare i valanaar"}},{q="Vad lär Quel'dora ut?",a="Quel'dora lär dig att träna och vägleda ditt djur, lära det förmågor, mata det och återuppliva det om det faller i strid.",al={"djurträning","träna mitt djur","vad kan djurtränaren lära ut"}},{q="Kan jag redan tämja ett djur?",a="Jägaren som skickar dig till Quel'dora säger att du redan har förmågan att tämja ett djur.",al={"tämja djur","djurtämjning","kan jägare tämja"}},{q="Vad ber jägaren mig att göra?",a="Jägaren ber dig att tala med Quel'dora Quickgale i Valanaar.",al={"training the beast","djurtränarens uppdrag","tala med queldora"}},{q="Vad säger Quel'dora om naturen?",a="Quel'dora uppmanar dig att respektera balansen och leva i vördnad inför naturen omkring dig.",al={"respektera naturen","balans","quel'doras råd"}}},fp="18,119,20.166.0,17.191.0,27.84.0,27.35.0,26.116.0,25.84.0,34.66.0,37.84.0"}
P.entries["quest:941"] = {n="Planting the Heart",s="Plantering av hjärtat är ett uppdrag åt örtkännaren Denalan vid Lake Al'Ameth i Teldrassil. Efter att ha avlägsnat den kvävande mossan från ett märkligt träigt hjärta från en fördärvad timberling, prövar Denalan om hans särskilt näringsrika jord kan rena och läka den kvarvarande vanhelgelsen inuti det.",h="Plantering av hjärtat är ett uppdrag åt örtkännaren Denalan vid Lake Al'Ameth i Teldrassil.",kw={"blackmoss the fetid","renat hjärta","denalan","lake al'ameth","blomlåda","tainted heart","teldrassil","timberling"},ang={["class:Druid"]="För en druid är det ett lugnande tecken att se en timberlings fördärvade kärna renas av näringsrik jord. Det visar att den onaturliga vanhelgelsen som drabbar världsträdets grenar fortfarande kan hejdas med naturlig omsorg.",["profession:Herbalism"]="Denalans skicklighet med näringsrik jord och botanisk återhämtning visar det viktiga sambandet mellan att studera jorden och att läka skadat växtliv.",["race:NightElf"]="Att återställa levande trä och väcka liv i fallna skogsandar speglar kaldorei-folkets åtagande att vårda naturen, trots Teldrassils oroande sjukdomar."},sec={{t="En andra chans till liv",b="När Denalan undersöker det märkliga träiga organet från timberlingen Blackmoss the Fetid lyckas han skrapa bort den vidriga mossan som stryper dess yta. Trots hans ansträngningar pulserar en djupare, onaturlig vanhelgelse fortfarande i träet. I stället för att bränna det eller kasta bort det förlitar sig Denalan på sina livslånga kunskaper om botanik och jordbruk. Han ber resenärer att gräva ner hjärtat direkt i hans egen blomlåda, i hopp om att de näringsämnen han blandat ska locka den naturliga livskraft som finns kvar tillbaka till hälsa."},{t="Den näringsrika jordens underverk",b="När det svärtade trähjärtat placeras i Denalans blomlåda reagerar det oväntat. Så fort det vidrör den bördiga jorden borrar sig hjärtat ner i myllan, som om en urinstinkt styrde det. Ögonblick senare kommer det upp till ytan igen, renat från sin vidriga fördärvelse och pulserande av en mild, vänskaplig värme. Genom att rena fröet från en fallen, vanhelgad varelse visar Denalan att varsam omvårdnad och helig jord fortfarande kan återställa harmonin, även när Teldrassils vilda invånare faller offer för onaturliga farsoter."}},faq={{q="Varifrån kommer det vanhelgade hjärtat?",a="Hjärtat kommer ursprungligen från Blackmoss the Fetid, en fördärvad timberling som håller till längs Lake Al'Ameths stränder. Det återfanns täckt av trasslig, vidrig mossa innan Denalan skrapade det rent.",al={"hjärtats ursprung","varifrån kom hjärtat","blackmoss hjärta"}},{q="Vem är Denalan?",a="Denalan är en botaniker och örtkännare av folket Night Elf som sköter ett avskilt läger vid Lake Al'Ameths östra kant. Han ägnar dagarna åt att studera Teldrassils växtliv, undersöka den märkliga fördärvelse som sprider sig genom grenverket och blanda näringsrik jord.",al={"vem är denalan","denalans historia"}},{q="Varför lägger man hjärtat i en blomlåda i stället för att förstöra det?",a="Denalan tror på att förstå och läka naturen, inte bara förstöra fördärvade varelser. Han hoppas att den näringsrika jord han har förberett kan driva ut vanhelgelsen och återställa hjärtats ursprungliga, rena livskraft.",al={"varför plantera hjärtat","varför läka hjärtat"}},{q="Vad händer när du gräver ner hjärtat?",a="Hjärtat borrar sig genast ner i jorden när det kommer i kontakt med den. Några sekunder senare slingrar det sig upp till ytan igen, helt renat från sin vidriga vanhelgelse och pulserande svagt som en levande följeslagare.",al={"vad händer i blomlådan","hjärtat borrar sig ner"}},{q="Botar detta timberlingarnas fördärvelse?",a="Det botar bara det här enda räddade hjärtat. Det visar att enskilda botaniska andar kan renas med omsorg och näringsrik jord, men den större fördärvelse som sprider sig över Teldrassil är fortfarande ett hot.",al={"botas timberlingar","bota timberlingar"}},{q="Varför är jorden i Denalans blomlåda speciell?",a="Denalan har lagt mycket tid på att experimentera med kompost och näringsrika jordblandningar kring Lake Al'Ameth. Han har utformat en jord som är kraftfull nog att återuppliva sjuklig växtlighet och driva bort den krypande förruttnelsen.",al={"denalans jord","jord i blomlåda"}}},fp="18,188,23.366.0,29.383.1,40.167.0,15.228.0,56.176.0,37.167.1,49.183.0,45.184.0"}
P.entries["quest:942"] = {n="The Absent Minded Prospector",s="Det här uppdraget för ett utgrävningsmysterium från Darkshore över Great Sea till Wetlands. Chief Archaeologist Greywhisker ger dig en märklig fossil från Kalimdor och skickar dig till Archaeologist Flagongut i Menethil Harbor för att avslöja dess hemligheter.",h="Det här uppdraget för ett utgrävningsmysterium från Darkshore över Great Sea till Wetlands.",kw={"absent minded prospector","archaeologist flagongut","chief archaeologist greywhisker","darkshore","deepwater tavern","explorers' league","menethil harbor","mysterious fossil"},ang={["faction:Alliance"]="För att slutföra uppdraget måste du använda Alliansens sjöleder och resa från Kalimdor till Menethil Harbor så att förbundets avdelningar kan hålla kontakten.",["race:Dwarf"]="För dvärgäventyrare visar detta ärende hur långt Explorers' League når och knyter fältarbetet i avlägsna Kalimdor till forskarkollegor i Khaz Modan."},sec={{t="En märklig upptäckt",b="När Chief Archaeologist Greywhisker undersöker den märkliga fossil som hittats i Darkshore ser han en slående likhet med en relik som visades på en konferens för Explorers' League i Ironforge. Den tidigare reliken presenterades av Archaeologist Flagongut, som var övertygad om att sådana fossil bar på krafter som väntade på att låsas upp. Greywhisker tror att Flagongut är den enda dvärg som kan avgöra vad som gör fyndet från Kalimdor så märkvärdigt."},{t="En resa över havet",b="Att bära med sig den mystiska reliken innebär en lång resa från Kalimdor till Eastern Kingdoms. Senast sågs Flagongut vänta på en beväpnad eskort till Whelgar Excavation Site medan han bodde på Deepwater Tavern i Menethil Harbor. När du överlämnar fossilen till honom vänds allt: en lokal undersökning i Darkshore knyts till en arkeologisk utredning som sträcker sig över hela kontinenten."}},faq={{q="Varför skickar Greywhisker mig ända till Menethil Harbor?",a="Chief Archaeologist Greywhisker minns att Archaeologist Flagongut visade upp en identisk relik på en årlig konferens för Explorers' League i Ironforge. Greywhisker tror att Flagongut har kunskapen som krävs för att låsa upp dess dolda kraft och skickar dig därför till hans senast kända plats i Menethil Harbor.",al={"varför till menethil","greywhiskers fossilärende","varför wetlands"}},{q="Vem är Archaeologist Flagongut?",a="Archaeologist Flagongut är en forskare från Explorers' League som är stationerad i Wetlands. Han väntar ut förseningar på Deepwater Tavern i Menethil Harbor och förbereder sig för en expedition till den farliga Whelgar Excavation Site.",al={"vem är flagongut","archaeologist flagonguts bakgrund"}},{q="Vad är den mystiska fossilen?",a="Det är ett uråldrigt, märkligt fynd från Darkshore. Flagongut hävdade tidigare att ett likadant exemplar som han studerat bar på dold magisk kraft eller historisk betydelse som väntade på att låsas upp.",al={"vad är fossilen","mysterious fossils ursprung","remtravels fossil"}},{q="Vad säger Flagongut när du överlämnar fossilen?",a="Flagongut blir häpen när han upptäcker att en relik som är identisk med hans eget forskningsprov kommer från den avlägsna kontinenten Kalimdor. Det bekräftar att den forntida historien knyter samman de båda landmassorna.",al={"flagonguts reaktion","lämna in fossilen"}},{q="Vart vill Flagongut ta sig härnäst?",a="Flagongut har väntat i Menethil Harbor på en eskort för att resa inåt landet mot Whelgar Excavation Site, en viktig utgrävningsplats i Wetlands.",al={"vart flagongut ska","flagonguts utgrävning"}},{q="Hur passar uppdraget in i berättelsen om Absent Minded Prospector?",a="Det är uppdragskedjans transportsträcka. Efter att ha eskorterat och räddat Prospector Remtravel i Darkshore och låtit Greywhisker analysera hans utgrävda relik flyttas utredningen från norra Kalimdor direkt till förbundets experter i Eastern Kingdoms.",al={"absent minded prospector del fyra","uppdragskedjans sammanhang"}}},fx={["5b36a0d8"]={q="Varför vill Chief Archaeologist Greywhisker att detta ska göras?",a="Chief Archaeologist Greywhisker har lagt märke till att det märkliga fossil som Remtravel grävde fram liknar en sällsam relik som visades upp vid en konferens för Explorers' League i Ironforge. Upptäckaren, Archaeologist Flagongut, trodde att reliken hade en slumrande kraft som väntade på att väckas. Greywhisker hoppas att Flagongut kan studera det nya fyndet och låsa upp det förflutnas uråldriga hemligheter.",al={"varför skicka fossilet","greywhiskers motiv","varför vill greywhisker få fossilet undersökt"}}},fp="28,201,19.374.0,23.327.0,60.282.0,31.217.0,30.195.0,52.171.0,37.121.0,68.212.0"}
P.entries["quest:94212"] = {n="Craftsman's Writ: Elixir of Wisdom",s="En överlåtbar Craftsman's Writ efterfrågar ett Elixir of Wisdom och anger leverans och betalning. Du behöver dokumentet för att slutföra bytet.",h="En överlåtbar Craftsman's Writ efterfrågar ett Elixir of Wisdom och anger leverans och betalning.",kw={"craftsman's writ","leverans","elixir of wisdom","betalning","överlåtbar","dokument"},sec={{t="En skriftlig begäran",b="En bleknad lapp med namnet Craftsman's Writ: Elixir of Wisdom ber dig ta med ett Elixir of Wisdom. Den anger en leveransplats och betalningsuppgifter, och dokumentet kan lämnas vidare. Du måste ha dokumentet på dig när du slutför bytet."}},faq={{q="Vad efterfrågas i dokumentet?",a="Det efterfrågar ett Elixir of Wisdom.",al={"elixirdokument","vilket föremål efterfrågas"}},{q="Kan jag lämna dokumentet vidare till någon annan?",a="Ja. Det står på lappen att dokumentet kan lämnas vidare.",al={"kan dokumentet lämnas vidare","kan någon annan bära det"}},{q="Vad behöver jag för att slutföra bytet?",a="Du behöver ha föremålet som efterfrågas och dokumentet på dig. Lappen anger leveransplatsen och betalningsuppgifterna.",al={"vad behövs för leveransen","slutföra dokumentet"}}},fp="34,149,17.246.0,27.33.0,36.44.0,40.118.0"}
P.entries["quest:94214"] = {n="Craftsman's Writ: Shadow Protection Potion",s="En överlåtbar beställningssedel efterfrågar en Shadow Protection Potion och anger leverans- och betalningsuppgifter. För att genomföra affären måste du ha beställningssedeln med dig.",h="En överlåtbar beställningssedel efterfrågar en Shadow Protection Potion och anger leverans- och...",kw={"craftsman's writ","leverans","betalning","trolldryck","shadow protection potion","överlåtbar","beställningssedel"},sec={{t="En skriftlig begäran",b="En bleknad lapp ber dig att tillhandahålla en Shadow Protection Potion. Den anger också leveransplats och betalningsuppgifter och säger att beställningssedeln kan gå från hand till hand. Du behöver ha beställningssedeln med dig för att slutföra utbytet."}},faq={{q="Vad efterfrågar beställningssedeln?",a="Beställningssedeln efterfrågar en Shadow Protection Potion.",al={"vad vill de ha","beställning av trolldryck","beställningssedelns föremål"}},{q="Var ska jag leverera den?",a="Leveransplatsen är markerad på din karta.",al={"leveransplats","vart ska trolldrycken","markerad plats"}},{q="Står det på beställningssedeln hur jag får betalt?",a="Beställningssedeln innehåller information om betalningen.",al={"betalningsuppgifter","hur mycket betalar de","betalning för beställningssedeln"}},{q="Kan jag ge beställningssedeln till någon annan?",a="Ja. På lappen står det att beställningssedeln kan överlåtas.",al={"kan den överlåtas","lämna beställningssedeln vidare","överlåta beställningssedeln"}},{q="Behöver jag ha beställningssedeln med mig?",a="Ja. Du måste ha beställningssedeln med dig för att genomföra affären.",al={"behövs beställningssedeln vid leverans","måste jag bära med mig den","beställningssedel krävs"}}},fp="42,156,17.215.0,27.47.0,22.44.0,37.44.0,36.44.0,35.65.0"}
P.entries["quest:94216"] = {n="Craftsman's Writ: Elixir of Lesser Agility",s="Ett överlåtelsebart skriftligt uppdrag ber dig skaffa en Elixir of Lesser Agility åt en kund. Det anger en leveransplats och betalningsuppgifter.",h="Ett överlåtelsebart skriftligt uppdrag ber dig skaffa en Elixir of Lesser Agility åt en kund.",kw={"smidighet","craftsman's writ","leverans","elixir","elixir of lesser agility","betalning","överlåtelsebar"},sec={{t="En kunds önskemål",b="En kund efterfrågar en Elixir of Lesser Agility genom detta skriftliga uppdrag med bleknat bläck. Du ombeds skaffa föremålet och ta det till den utmärkta platsen. Du måste ha uppdraget med dig för att slutföra affären."}},faq={{q="Vad ber uppdraget om?",a="Kunden ber om en Elixir of Lesser Agility.",al={"vilket föremål","elixirönskemål","vad vill de ha"}},{q="Var ska jag lämna den?",a="Uppdraget visar en leveransplats på kartan.",al={"leveransplats","var ska den lämnas","utmärkt plats"}},{q="Står det i uppdraget hur betalningen går till?",a="Uppdraget innehåller information om betalningen.",al={"betalningsuppgifter","hur mycket betalar de","vad är betalningen"}},{q="Kan någon annan bära uppdraget?",a="Ja. Texten längst ner säger att uppdraget kan överlåtas.",al={"kan det överlåtas","lämna det vidare","överlåta uppdraget"}},{q="Behöver jag uppdraget för att slutföra leveransen?",a="Ja. Du måste ha uppdraget med dig för att slutföra affären.",al={"behöver uppdraget","behålla papperet","uppdraget krävs"}}},fp="42,132,20.209.0,27.51.0,22.58.0,36.44.0,32.54.0,44.68.0"}
P.entries["quest:94219"] = {n="Craftsman's Writ: Draught of Water Breathing",s="Ett överlåtbart beställningsbrev efterfrågar en Draught of Water Breathing och anger leverans- och betalningsuppgifter. Du behöver brevet för att genomföra utbytet.",h="Ett överlåtbart beställningsbrev efterfrågar en Draught of Water Breathing och anger leverans- och...",kw={"craftsman's writ","leverans","draught of water breathing","betalning","vattenandning","beställningsbrev"},sec={{t="En skriftlig beställning",b="Den bleknade lappen ber dig om en Draught of Water Breathing. Den anger också leveransplats och betalning och kan överlåtas från en innehavare till en annan."}},faq={{q="Vad efterfrågar beställningsbrevet?",a="Det efterfrågar en Draught of Water Breathing.",al={"vad vill de ha","beställning av dryck","beställningsbrevets föremål"}},{q="Var ska jag lämna den?",a="Beställningsbrevet anger en leveransplats som är markerad på din karta.",al={"leveransplats","var ska den lämnas","beställningsbrevets plats"}},{q="Vilken betalning erbjuds?",a="Beställningsbrevet innehåller information om betalningen.",al={"hur mycket betalt","beställningsbrevets betalning","vad får man"}},{q="Kan beställningsbrevet överlåtas?",a="Ja. På lappen står det att beställningsbrevet kan överlåtas.",al={"överlåtbart beställningsbrev","kan någon annan bära det","överlåta beställningsbrevet"}},{q="Behöver jag beställningsbrevet för att genomföra utbytet?",a="Ja. Du måste ha beställningsbrevet med dig för att genomföra transaktionen.",al={"behövs lappen","beställningsbrev krävs","går det att leverera utan det"}}},fp="44,143,17.146.0,27.43.0,22.55.0,24.44.0,28.47.0,44.65.0"}
P.entries["quest:94220"] = {n="Craftsman's Writ: Pearl-Handled Dagger",s="Ett överlåtbart beställningsbrev efterfrågar en Pearl-Handled Dagger och anger villkor för leverans och betalning. Du behöver brevet för att slutföra utbytet.",h="Ett överlåtbart beställningsbrev efterfrågar en Pearl-Handled Dagger och anger villkor för leverans och...",kw={"craftsman's writ","dolk","leverans","betalning","pearl-handled dagger","beställningsbrev"},sec={{t="Beställningsbrevet",b="Meddelandet är skrivet med bleknat bläck och nämner en Pearl-Handled Dagger bland de föremål som önskas. De nedre raderna anger en leveransplats och betalningsvillkor. Beställningsbrevet kan gå från hand till hand, men du måste ha det hos dig när du slutför utbytet."}},faq={{q="Vad efterfrågas i beställningsbrevet?",a="Beställningsbrevet efterfrågar en Pearl-Handled Dagger.",al={"pärldolk beställningsbrev","vilket föremål efterfrågas"}},{q="Var ska jag lämna föremålet?",a="Leveransplatsen är markerad på din karta.",al={"leveransplats","var ska det lämnas"}},{q="Vad erbjuder kunden?",a="Beställningsbrevet innehåller information om betalningen.",al={"betalningsvillkor","hur stor betalning"}},{q="Kan jag överlåta det här beställningsbrevet?",a="Ja. I beställningsbrevet står det att det kan överlåtas.",al={"överlåta beställningsbrev","är meddelandet överlåtbart"}},{q="Behöver jag behålla beställningsbrevet?",a="Ja. Du måste ha beställningsbrevet hos dig för att slutföra affären.",al={"behöver beställningsbrev för att slutföra","måste ha meddelandet"}}},fp="38,141,8.243.0,27.41.0,28.44.0,29.44.0,25.41.0,27.70.0"}
P.entries["quest:94222"] = {n="Craftsman's Writ: Iridescent Hammer",s="En kund väntar på en Iridescent Hammer, med leverans- och betalningsuppgifter angivna i ett beställningsbrev. Märkningen som överlåtbart låter innehavaren slutföra utbytet.",h="En kund väntar på en Iridescent Hammer, med leverans- och betalningsuppgifter angivna i ett beställningsbrev.",kw={"craftsman's writ","leverans","hammare","iridescent hammer","betalning","överlåtbart","beställningsbrev"},sec={{t="Beställningsbrevet",b="Kunden ber om en Iridescent Hammer. Ta med beställningsbrevet för att slutföra utbytet på den markerade platsen."}},faq={{q="Vad vill kunden ha?",a="Kunden vill ha en Iridescent Hammer.",al={"iridescent hammer beställningsbrev","vilket föremål efterfrågas"}},{q="Var ska jag leverera den?",a="Beställningsbrevet innehåller leveransuppgifterna, och platsen är markerad på din karta.",al={"beställningsbrev leveransplats","vart ska hammaren lämnas"}},{q="Måste jag ha beställningsbrevet med mig?",a="Ja. Ha beställningsbrevet med dig för att slutföra utbytet.",al={"behövs beställningsbrevet vid leverans","beställningsbrev krävs"}},{q="Kan någon annan använda beställningsbrevet?",a="Ja. Beställningsbrevet är märkt som överlåtbart.",al={"överlåtbart beställningsbrev","överlåta beställningsbrevet"}},{q="Står det i beställningsbrevet hur betalningen fungerar?",a="Ja. Beställningsbrevet innehåller betalningsinformation.",al={"hammare betalning","hur stor är betalningen"}}},fp="35,155,8.108.0,28.49.0,22.76.0,33.53.0,30.40.0,36.43.0"}
P.entries["quest:94223"] = {n="Craftsman's Writ: Silver Skeleton Key",s="Ett överlåtelsebart dokument begär en Silver Skeleton Key och anger en plats där du ska lämna den. Kryptan rymmer en vårdares anteckning och en kista som hör ihop med nyckeln.",h="Ett överlåtelsebart dokument begär en Silver Skeleton Key och anger en plats där du ska lämna den.",kw={"vårdare","hantverkarens dokument","krypta","raven hill cemetery","silver skeleton key","kista","odöda"},sec={{t="Dokumentet",b="Bleknat bläck nämner en Silver Skeleton Key och anger en leveransplats och betalning. Dokumentet kan gå från hand till hand, men du måste bära det för att slutföra bytet."},{t="I kryptan",b="En anteckning på en kista berättar att vårdaren på Raven Hill Cemetery är död. Han skriver att arbetsgivarna i Darkshire till största delen har glömt honom och att han lämnade sin förmögenhet i lådan åt den som kan öppna den. När odöda samlas i närheten och ingen annan syns använder du nyckeln. Kistan innehåller inte mycket, men innehållet täcker en del av kostnaden."}},faq={{q="Vad ber dokumentet om?",a="Dokumentet begär en Silver Skeleton Key och anger en leveransplats och betalning.",al={"dokument om silvernyckel","vilken nyckel efterfrågas"}},{q="Kan någon annan bära dokumentet?",a="Ja. Dokumentet säger att det kan överlåtas, men du måste ha det för att slutföra bytet.",al={"överlåtelsebart dokument","kan jag lämna över det"}},{q="Vart skickar dokumentet mig?",a="Dokumentet hänvisar dig till platsen som är markerad på kartan.",al={"leveransplats","vart ska nyckeln tas"}},{q="Vem lämnade anteckningen i kryptan?",a="Anteckningen lämnades av en vårdare på Raven Hill Cemetery som skriver att han har dött.",al={"vårdarens anteckning","vem dog"}},{q="Vad fanns i kistan?",a="Kistan är nästan tom, men innehållet räcker för att täcka en del av kostnaden.",al={"tom kista","vårdarens skatt"}}},fp="37,165,8.165.0,12.334.1,27.81.0,32.97.0,28.56.0,31.77.0,22.72.0"}
P.entries["quest:94224"] = {n="Craftsman's Writ: Heavy Bronze Mace",s="En bleknad skrift begär en Heavy Bronze Mace och anger villkoren för leverans och betalning. Du behöver skriften för att slutföra bytet.",h="En bleknad skrift begär en Heavy Bronze Mace och anger villkoren för leverans och betalning.",kw={"hantverkarens skrift","leverans","heavy bronze mace","klubba","betalning","överlåtbar skrift"},sec={{t="En skriftlig begäran",b="Anteckningen är skriven med bleknat bläck, och kunden ber om en Heavy Bronze Mace. Du ska ta det efterfrågade föremålet till platsen som markerats på kartan. Behåll skriften, eftersom den krävs för att slutföra bytet."}},faq={{q="Vad begär skriften?",a="Kunden begär en Heavy Bronze Mace.",al={"heavy bronze mace-skrift","vilket föremål efterfrågas"}},{q="Var ska jag lämna in klubban?",a="Leveransplatsen är markerad på kartan.",al={"plats för leverans av klubban","var den ska lämnas"}},{q="Måste jag behålla skriften?",a="Ja. Du måste ha skriften på dig för att slutföra affären.",al={"behöver skriften","skriften krävs"}},{q="Vad står det om betalningen?",a="Anteckningen innehåller information om betalningen, men den tillhandahållna texten anger inget belopp.",al={"betalning för klubban","hur stor är betalningen"}},{q="Kan någon annan använda skriften?",a="Texten längst ned säger att skriften kan överlåtas.",al={"överlåtbar skrift","överlåta skriften till någon"}}},fp="35,133,17.218.0,27.44.0,28.44.0,27.69.0,37.92.0,30.56.0"}
P.entries["quest:94226"] = {n="Craftsman's Writ: Green Iron Gauntlets",s="MacKinleys beställning ber dig att ge honom Green Iron Gauntlets. Den överlåtbara handlingen innehåller uppgifter om leverans och betalning.",h="MacKinleys beställning ber dig att ge honom Green Iron Gauntlets.",kw={"craftsman's writ","leverans","green iron gauntlets","knogjärn av grönt järn","mackinley","betalning","överlåtbar"},sec={{t="En skriftlig beställning",b="Den bleknade beställningen anger Green Iron Gauntlets, en leveransplats och betalning. Du måste ha beställningen med dig för att slutföra utbytet. MacKinley väntar på varorna, men hans hälsning antyder att något inte stämmer."},{t="Vid utbytet",b="MacKinley säger att han ville ha knogjärn av grönt järn, inte stridshandskar. Han tar emot stridshandskarna medan han väntar på en ersättningsleverans och betalar dig sedan mindre än du väntat dig."}},faq={{q="Vad ber MacKinley om?",a="Beställningen gäller ett par Green Iron Gauntlets, men MacKinley säger att han menade att beställa knogjärn av grönt järn.",al={"vad vill mckinley ha","beställning på green iron"}},{q="Var ska jag leverera stridshandskarna?",a="Beställningen anger en leveransplats som är markerad på din karta.",al={"var ska det levereras","beställningens plats"}},{q="Måste jag ha beställningen med mig?",a="Ja. Du måste ha beställningen med dig för att slutföra utbytet.",al={"behövs beställningen","glömt beställningen"}},{q="Vad säger beställningen om betalningen?",a="Handlingen innehåller uppgifter om betalningen, men anger inget belopp i texten.",al={"hur mycket betalt","betalningsuppgifter"}},{q="Kan någon annan bära beställningen?",a="Ja. Handlingen säger att beställningen är överlåtbar.",al={"överlåtbar beställning","kan beställningen ges bort"}}},fp="38,123,15.216.0,15.157.1,28.114.0,33.55.0,27.66.0,37.77.0,32.44.0"}
P.entries["quest:94231"] = {n="Craftsman's Writ: Moonsight Rifle",s="En överlåtbar beställning efterfrågar en Moonsight Rifle och anger leveransplats och betalning. Köparen vill att utbytet hålls tyst.",h="En överlåtbar beställning efterfrågar en Moonsight Rifle och anger leveransplats och betalning.",kw={"täckmantel","hantverkarbeställning","korseld","leverans","moonsight rifle","betalning","gevär","satyr"},sec={{t="Ett diskret utbyte",b="En bleknad lapp ber dig ta med en Moonsight Rifle till den markerade platsen, där betalningen ordnas. Beställningen kan lämnas från hand till hand, men du måste ha den för att slutföra utbytet. Köparen varnar för att ditt närmande väcker uppmärksamhet och kan röja deras täckmantel."},{t="Geväret",b="När Moonsight Rifle visas upp berömmer köparen dess kraft mot satyrer. De säger åt dig att kliva åt sidan innan korselden börjar."}},faq={{q="Vad efterfrågas i beställningen?",a="Beställningen gäller en Moonsight Rifle, som ska levereras på platsen som markerats på kartan.",al={"beställning på moonsight rifle","vilket gevär vill de ha"}},{q="Kan jag ge beställningen till någon annan?",a="Ja. Det står på lappen att beställningen kan överlåtas, men du måste ha den för att slutföra utbytet.",al={"kan beställningen överlåtas","överlämna beställningen"}},{q="Varför vill köparen vara diskret?",a="Köparen säger att ditt närmande väcker uppmärksamhet och riskerar att röja deras täckmantel.",al={"varför så hemlighetsfull","röja täckmanteln"}},{q="Vem är geväret tänkt att användas mot?",a="Köparen säger att geväret kan skjuta huvudet av en satyr.",al={"gevär mot satyrer","moonsight rifle mål"}}},fp="33,127,16.270.0,9.139.1,27.87.0,36.107.0,33.86.0,42.62.0"}
P.entries["quest:94233"] = {n="Craftsman's Writ: Practice Lock",s="En överlåtbar skrivelse ber dig lämna in ett Practice Lock. Leveransplatsen och betalningsvillkoren står på lappen.",h="En överlåtbar skrivelse ber dig lämna in ett Practice Lock.",kw={"craftsman's writ","leverans","lås","betalning","practice lock","överlåtbar","skrivelse"},sec={{t="En skriftlig begäran",b="En kund begär ett Practice Lock genom en bleknad, överlåtbar skrivelse. Du ombeds lämna föremålet på platsen som markerats på kartan. Du måste ha skrivelsen med dig för att slutföra affären."}},faq={{q="Vad begär skrivelsen?",a="Skrivelsen begär ett Practice Lock.",al={"begäran om practice lock","vilket föremål","skrivelse om lås"}},{q="Var ska jag lämna Practice Lock?",a="Leveransplatsen är markerad på kartan.",al={"leveransplats","vart ska det lämnas","var lämna"}},{q="Behöver jag behålla skrivelsen?",a="Ja. Du måste ha skrivelsen med dig för att slutföra affären.",al={"behöver skrivelsen","ta med lappen","skrivelsen krävs"}},{q="Kan skrivelsen överlåtas?",a="Ja. Det står i skrivelsen att den kan överlåtas.",al={"kan jag överlåta den","överlåtbar lapp","överlåt skrivelsen"}},{q="Nämner lappen någon betalning?",a="Skrivelsen nämner betalning, men anger inget belopp i den tillhandahållna texten.",al={"betalningsvillkor","hur mycket betalas","betalning"}}},fp="31,122,17.215.0,27.36.0,37.44.0,27.69.0,25.38.0,30.68.0"}
P.entries["quest:94238"] = {n="Craftsman's Writ: Heavy Leather Ball",s="Ett överlåtelsebart Craftsman's Writ gäller en Heavy Leather Ball och anger en kund. Sos'mols längtan efter bollen gör leveransen viktig för honom.",h="Ett överlåtelsebart Craftsman's Writ gäller en Heavy Leather Ball och anger en kund.",kw={"craftsman's writ","leverans","heavy leather ball","ogre","betalning","sos'mol","överlåtelsebar"},sec={{t="En kunds begäran",b="Det bleknade skrivelsen efterfrågar en Heavy Leather Ball och anger detaljer om leverans och betalning. Du tar med dig skrivelsen för att genomföra bytet. Sos'mol har nynnat en falskstämd melodi om tristess när du anländer. Han fortsätter nynna, men tystare, och verkar lite generad."},{t="Sos'mols glädje",b="Sos'mol frågar om du har tagit med dig bollen. När han får den tåras hans ögon, och han säger att det är den lyckligaste dagen i en ogres liv. Bollen betyder mer för honom än vad han än hade önskat sig tidigare, även om han inte minns vad det var."}},faq={{q="Vad efterfrågar skrivelsen?",a="Skrivelsen efterfrågar en Heavy Leather Ball samt detaljer om leverans och betalning.",al={"heavy leather ball-skrivelse","vilket föremål efterfrågas"}},{q="Vem är kunden?",a="Sos'mol är kunden som anges för leveransen.",al={"vem vill ha bollen","sos'mol-skrivelse"}},{q="Varför vill Sos'mol ha en boll?",a="Sos'mol säger att bollen var något han hade drömt om.",al={"varför boll","sos'mol vill ha boll"}},{q="Vad gör Sos'mol när jag anländer?",a="Sos'mol har nynnat en falskstämd sång om tristess och fortsätter tystare när du närmar dig.",al={"vad gör sos'mol","sos'mol sjunger"}},{q="Kan någon annan använda skrivelsen?",a="Ja. Anteckningen säger att skrivelsen kan överlåtas.",al={"överlåtelsebar skrivelse","kan jag ge bort skrivelsen"}}},fp="36,151,20.284.0,17.252.1,27.88.0,20.46.0,29.60.0,36.99.0,30.44.0"}
P.entries["quest:94242"] = {n="Craftsman's Writ: Pilferer's Gloves",s="Ett överlåtbart beställningsbrev efterfrågar Pilferer's Gloves och anger detaljer om leverans och betalning. Du behöver brevet för att slutföra affären.",h="Ett överlåtbart beställningsbrev efterfrågar Pilferer's Gloves och anger detaljer om leverans och betalning.",kw={"craftsman's writ","leverans","handskar","betalning","pilferer's gloves","överlåtbar","beställningsbrev"},sec={{t="En skriftlig beställning",b="En bleknad lapp efterfrågar ett par Pilferer's Gloves. Den anger var de ska levereras och hur betalningen ordnas, och beställningsbrevet kan gå från hand till hand."},{t="Affären",b="Du behöver ha beställningsbrevet med dig när du tar de efterfrågade handskarna till den markerade platsen. Lappen knyter uppgifterna om leverans och betalning till den här skriftliga beställningen."}},faq={{q="Vad efterfrågas i beställningsbrevet?",a="Beställningsbrevet efterfrågar ett par Pilferer's Gloves.",al={"pilferer's gloves beställningsbrev","beställning av handskar","vilket föremål"}},{q="Var ska jag leverera handskarna?",a="Leveransplatsen är markerad på din karta.",al={"leveransplats","vart handskarna ska tas","markerad plats"}},{q="Vad behöver jag för att slutföra affären?",a="Du behöver ha beställningsbrevet i din ägo för att slutföra affären.",al={"behöver beställningsbrevet","krav på beställningsbrev","slutföra affären"}},{q="Står det i beställningsbrevet hur betalningen fungerar?",a="Beställningsbrevet innehåller information om betalningen.",al={"betalningsuppgifter","hur stor betalning","betalning för handskar"}},{q="Kan någon annan bära beställningsbrevet?",a="Ja. Beställningsbrevet kan överlåtas.",al={"överlåtbart beställningsbrev","lämna lappen vidare","går det att ge bort det"}}},fp="35,141,15.156.0,15.156.0,27.48.0,30.44.0,43.65.0,36.44.0,32.30.0"}
P.entries["quest:94243"] = {n="Craftsman's Writ: Heavy Quiver",s="Ett bleknat Craftsman's Writ: Heavy Quiver ber dig lämna en Heavy Quiver på en markerad plats och ger betalningsuppgifter.",h="Ett bleknat Craftsman's Writ: Heavy Quiver ber dig lämna en Heavy Quiver på en markerad plats och ger...",kw={"craftsman's writ","leverans","heavy quiver","betalning","koger","överlåtbart"},sec={{t="Beställningsbrevet",b="Meddelandet ber dig skaffa en Heavy Quiver och ta den till platsen som markerats på din karta. Ha beställningsbrevet med dig för att slutföra utbytet."}},faq={{q="Vad efterfrågas i beställningsbrevet?",a="Kunden efterfrågar en Heavy Quiver.",al={"beställning av heavy quiver","vilket föremål efterfrågas"}},{q="Var ska jag lämna den?",a="Leveransplatsen är markerad på din karta.",al={"leveransplats","var ska kogret lämnas"}},{q="Behöver jag ha beställningsbrevet med mig?",a="Ja. Ha beställningsbrevet med dig för att slutföra utbytet.",al={"behövs beställningsbrevet","beställningsbrev krävs"}},{q="Kan jag ge beställningsbrevet till någon annan?",a="Ja. Beställningsbrevet kan överlåtas till någon annan.",al={"överlåta beställningsbrev","kan någon annan använda det"}},{q="Nämner beställningsbrevet någon betalning?",a="Beställningsbrevet ger betalningsuppgifter, men inget belopp anges.",al={"hur stor är betalningen","betalning för koger"}}},fp="30,121,8.140.0,27.39.0,22.41.0,28.54.0,37.49.0,30.56.0"}
P.entries["quest:94245"] = {n="Craftsman's Writ: Barbaric Gloves",s="En överlåtbar beställning gäller Barbaric Gloves och anger en leveransplats och betalningsuppgifter. Du måste ha beställningen med dig för att slutföra affären.",h="En överlåtbar beställning gäller Barbaric Gloves och anger en leveransplats och betalningsuppgifter.",kw={"barbaric gloves","hantverkarens beställning","leverans","handskar","betalning","överlåtbar","beställning"},sec={{t="En kunds önskemål",b="En kund beställer ett par Barbaric Gloves genom den här bleknade beställningen. Anteckningen anger en leveransplats och betalningsuppgifter, och den kan lämnas vidare från hand till hand. Du måste ha beställningen på dig när du levererar den efterfrågade varan."}},faq={{q="Vad gäller beställningen?",a="Kunden beställer ett par Barbaric Gloves.",al={"beställning för barbaric gloves","vilka handskar","hantverkarbeställning"}},{q="Var ska jag leverera handskarna?",a="Leveransplatsen är markerad på kartan.",al={"leveransplats","var handskarna ska lämnas"}},{q="Måste jag bära med mig beställningen?",a="Ja. Du måste ha beställningen på dig för att slutföra affären.",al={"måste ha beställningen med mig","beställningen krävs"}},{q="Kan beställningen överlåtas?",a="Ja. Anteckningen säger att beställningen kan överlåtas.",al={"överlåta beställningen","lämna beställningen vidare"}},{q="Vad står det om betalningen i beställningen?",a="Beställningen innehåller information om betalningen.",al={"betalningsuppgifter","hur stor betalningen är"}}},fp="33,151,20.237.0,27.50.0,30.44.0,28.70.0,28.44.0,37.44.0"}
P.entries["quest:94246"] = {n="Craftsman's Writ: Red Whelp Gloves",s="Ett överlåtbart beställningsbrev efterfrågar ett par Red Whelp Gloves. Det anger leveransplats och betalning för utbytet.",h="Ett överlåtbart beställningsbrev efterfrågar ett par Red Whelp Gloves.",kw={"craftsman's writ","leverans","betalning","red whelp gloves","överlåtbart","beställningsbrev"},sec={{t="En skriftlig begäran",b="En bleknad lapp efterfrågar ett par Red Whelp Gloves och anger leveransplats och betalning. Du måste ha beställningsbrevet för att slutföra utbytet."}},faq={{q="Vad efterfrågar beställningsbrevet?",a="Beställningsbrevet efterfrågar ett par Red Whelp Gloves.",al={"red whelp gloves beställningsbrev","vilket föremål efterfrågas"}},{q="Var ska jag lämna handskarna?",a="Beställningsbrevet anger en leveransplats som är markerad på din karta.",al={"leveransplats","var ska handskarna lämnas"}},{q="Vad behöver jag för att slutföra utbytet?",a="Du måste ha beställningsbrevet i din ägo för att slutföra utbytet.",al={"vad behövs","krav på beställningsbrev"}},{q="Kan beställningsbrevet överlåtas?",a="Ja. Enligt lappen är beställningsbrevet överlåtbart.",al={"överlåtbart beställningsbrev","kan någon annan ta det"}},{q="Nämner beställningsbrevet någon betalning?",a="Ja. Beställningsbrevet innehåller information om betalning.",al={"hur stor betalning","betalning för handskar"}}},fp="34,114,17.145.0,27.47.0,30.57.0,40.62.0,28.44.0,30.49.0"}
P.entries["quest:94249"] = {n="Craftsman's Writ: Azure Silk Hood",s="Ett bleknat Craftsman’s Writ efterfrågar en Azure Silk Hood och anger villkor för leverans och betalning. Du behöver beställningsbrevet för att slutföra utbytet.",h="Ett bleknat Craftsman’s Writ efterfrågar en Azure Silk Hood och anger villkor för leverans och betalning.",kw={"azure silk hood","craftsman's writ","leverans","betalning","sidenhuva","överlåtbart","beställningsbrev"},sec={{t="De skriftliga villkoren",b="Meddelandet är skrivet med bleknat bläck och anger ett föremål: en Azure Silk Hood. Det anger också leveransplatsen och betalningen. Beställningsbrevet kan överlåtas från en innehavare till en annan, men du behöver ha det med dig för att slutföra affären."}},faq={{q="Vad efterfrågas i beställningsbrevet?",a="Kunden efterfrågar en Azure Silk Hood.",al={"beställning på azurblå huva","vilket föremål efterfrågas","hantverkarens beställningsbrev"}},{q="Var ska jag leverera huvan?",a="Leveransplatsen är markerad på din karta.",al={"leveransplats","vart ska det lämnas","markerad plats"}},{q="Vad behöver jag för affären?",a="Du behöver ha det efterfrågade föremålet och beställningsbrevet med dig.",al={"vad behövs","behövs beställningsbrevet?","slutföra utbytet"}},{q="Står det i beställningsbrevet hur betalningen går till?",a="Meddelandet innehåller information om betalningen, men texten här anger inte beloppet.",al={"hur stor är betalningen","betalningsvillkor","vad får jag"}},{q="Kan någon annan bära beställningsbrevet?",a="Ja. Beställningsbrevet är märkt som överlåtbart.",al={"överlåtbart beställningsbrev","kan jag överlåta det","vem kan ha det"}}},fp="33,144,17.225.0,27.42.0,28.44.0,35.60.0,36.91.0,32.40.0"}
P.entries["quest:94250"] = {n="Craftsman's Writ: Small Silk Pack",s="En överlåtbar beställningssedel begär ett Small Silk Pack och anger leverans och betalning. Du behöver sedeln för att slutföra bytet.",h="En överlåtbar beställningssedel begär ett Small Silk Pack och anger leverans och betalning.",kw={"craftman's writ","leverans","betalning","silke","small silk pack","överlåtbar","beställningssedel"},sec={{t="Beställningssedeln",b="En kunds bleknade anteckning ber dig om ett Small Silk Pack. Där står vart paketet ska levereras och hur betalningen går till. Sedeln kan lämnas vidare, men du måste ha den när bytet slutförs."}},faq={{q="Vad ber beställningssedeln om?",a="Kunden begär ett Small Silk Pack.",al={"beställningssedel för small silk pack","vilket föremål efterfrågas","beställning av silkespaket"}},{q="Vart ska jag leverera paketet?",a="Beställningssedeln anger leveransinformationen, och platsen är markerad på kartan.",al={"leveransplats","vart ska det lämnas","var ska det lämnas av"}},{q="Hur går betalningen till?",a="Beställningssedeln innehåller information om betalningen.",al={"hur mycket får jag","betalningsuppgifter","vad är betalningen"}},{q="Kan jag lämna beställningssedeln till någon annan?",a="Ja. Anteckningen säger att beställningssedeln kan lämnas vidare.",al={"kan beställningssedeln överlåtas","ge bort beställningssedeln","lämna vidare"}},{q="Behöver jag beställningssedeln för att slutföra bytet?",a="Ja. Du måste ha beställningssedeln för att slutföra transaktionen.",al={"behöver beställningssedeln vid inlämning","måste jag behålla anteckningen","beställningssedel krävs"}}},fp="33,141,8.220.0,27.42.0,28.79.0,23.44.0,40.44.0,44.70.0"}
P.entries["quest:94252"] = {n="Craftsman's Writ: Red Woolen Boots",s="En överlåtbar skrivelse begär ett par Red Woolen Boots och anger leverans- och betalningsinformation. Du behöver skrivelsen för att slutföra bytet.",h="En överlåtbar skrivelse begär ett par Red Woolen Boots och anger leverans- och betalningsinformation.",kw={"stövlar","hantverkarens skrivelse","leverans","betalning","red woolen boots","överlåtbar","skrivelse"},sec={{t="Den skriftliga begäran",b="En bleknad anteckning ber dig att lämna ett par Red Woolen Boots. Den anger var du ska leverera dem och hur betalningen ordnas. Skrivelsen kan överlåtas, men du måste ha den på dig när du slutför bytet."}},faq={{q="Vad begär skrivelsen?",a="Skrivelsen begär ett par Red Woolen Boots.",al={"skrivelse om röda stövlar","vilka stövlar efterfrågas"}},{q="Var ska jag leverera stövlarna?",a="Skrivelsen anger leveransinformation, och den markerade platsen visas på din karta.",al={"leveransplats","var röda stövlar ska lämnas"}},{q="Hur ordnas betalningen?",a="Skrivelsen innehåller information om betalningen.",al={"betalning för stövlar","hur mycket betalar de"}},{q="Kan jag överlåta skrivelsen?",a="Ja. Anteckningen säger att skrivelsen kan överlåtas.",al={"överlåtbar skrivelse","kan någon annan bära den"}},{q="Behöver jag skrivelsen för att slutföra bytet?",a="Ja. Du måste ha skrivelsen på dig för att slutföra transaktionen.",al={"behöver ha skrivelsen med mig","slutföra transaktion"}}},fp="34,143,19.213.0,27.47.0,29.81.0,24.44.0,25.44.0,44.75.0"}
P.entries["quest:94253"] = {n="Craftsman's Writ: Colorful Kilt",s="En kund söker en förklädnad för att smyga in i Zul'Gurub, och Craftsman's Writ: Colorful Kilt anger vilket plagg kunden vill ha.",h="En kund söker en förklädnad för att smyga in i Zul'Gurub, och Craftsman's Writ: Colorful Kilt anger vilket...",kw={"colorful kilt","craftsman's writ","leverans","förklädnad","ritualutövare","zul'gurub"},sec={{t="En förklädnad",b="Det överlåtbara beställningsbrevet ber dig att ta med en Colorful Kilt till den markerade platsen. Kunden planerar att ta sig genom portarna till Zul'Gurub utklädd till en av dess ritualutövare och säger att kilten passar förklädnaden."}},faq={{q="Vad efterfrågas i beställningsbrevet?",a="Beställningsbrevet efterfrågar en Colorful Kilt som ska levereras till platsen markerad på din karta.",al={"beställning colorful kilt","vilket föremål behövs"}},{q="Varför vill kunden ha en färgglad kilt?",a="Kunden planerar att smyga in i Zul'Gurub utklädd till en av dess ritualutövare och säger att kilten kommer att hjälpa.",al={"varför kilt","kilt förklädnad"}},{q="Kan jag överlåta det här beställningsbrevet?",a="Ja. Beställningsbrevet anger att det kan överlåtas.",al={"överlåta beställningsbrev","ge bort beställningsbrev"}},{q="Var ska jag leverera kilten?",a="Beställningsbrevet hänvisar dig till platsen markerad på din karta.",al={"leveransplats","vart ska den lämnas"}}},fp="31,121,10.206.0,27.88.0,43.104.0,25.38.0,32.56.0"}
P.entries["quest:943"] = {n="The Absent Minded Prospector",s="Det här uppdraget är slutkapitlet i sökandet som Prospector Remtravels utgrävningar i Darkshore satte i gång. Archaeologist Flagongut i Menethil Harbor vill förena Remtravels fynd med sitt eget fossil och den förlorade Stone of Relu för att frigöra de forntida relikernas dolda krafter.",h="Det här uppdraget är slutkapitlet i sökandet som Prospector Remtravels utgrävningar i Darkshore satte i gång.",kw={"darkshore","explorers' league","flagongut","fossil","menethil","remtravel","stone of relu","wetlands","whelgar"},ang={["faction:Alliance"]="Alliansens kurirer och äventyrare färdas ofta över havet mellan nattalvernas marker i Darkshore och dvärgarnas bosättningar kring Menethil Harbor.",["race:Dwarf"]="Uppdragskedjan visar Explorers' Leagues kärnuppdrag: att knyta samman avlägsna utgrävningsplatser över kontinenterna och pussla ihop dvärgarnas arv och Titanernas mysterier."},sec={{t="Arkeologi över kontinenterna",b="Det som började som ett eskortuppdrag för att hjälpa den tankspridde Prospector Remtravel i norra Darkshore leder över Great Sea till våtmarkerna i Wetlands. Flagonguts eget ursprungliga fossil finns hos Prospector Whelgar på hans utgrävningsplats i Wetlands. Archaeologist Flagongut går igenom de insamlade fynden och inser att en nyckelartefakt krävs för att frigöra de mystiska krafterna i fossilen: Stone of Relu."},{t="Förlorad i träskmarkerna",b="Innan Flagongut hann möta Whelgar överföll en flock fläckiga rovfåglar hans karavan längs vägen och slukade Stone of Relu. För att lösa mysteriet behöver Flagongut en äventyrare som jagar upp rovdjuren, återfår stenen de svalt och hämtar det ursprungliga fossilet från Whelgars läger. När båda fossilen och nyckeln är samlade hoppas de dvärgiska forskarna kunna upptäcka relikernas sanna ursprung och kraft."}},faq={{q="Varför slutar ett uppdrag i Darkshore i Wetlands?",a="Explorers' League har aktiva verksamheter både i Kalimdor och Eastern Kingdoms. Chief Archaeologist Greywhisker skickade Remtravels fossil från Darkshore över havet till Archaeologist Flagongut i Wetlands, och knöt samman de två utgrävningsplatserna genom gemensam forskning.",al={"varför uppdrag i wetlands från darkshore","kopplingen till menethil harbor","varför skicka till wetlands"}},{q="Vad är Stone of Relu?",a="Stone of Relu är en forntida relik som Archaeologist Flagongut återfunnit. Han tror att den fungerar som ett chiffer eller en katalysator som kan frigöra de slumrande magiska hemligheterna i fossilen som grävts upp i Darkshore och Wetlands.",al={"stone of relu","vad är relu-stenen","relu-artefakt"}},{q="Vem är Archaeologist Flagongut?",a="Archaeologist Flagongut är en agent för dvärgarnas Explorers' League och har sin bas i Menethil Harbor. Han studerar forntida reliker från utgrävningar i trakten och hoppas kunna frigöra den dolda kraften i fossilen som Prospectors Remtravel och Whelgar hittat.",al={"flagongut","vem är flagongut"}},{q="Vem har det ursprungliga fossilet?",a="Prospector Whelgar har Flagonguts ursprungliga fossil på sin utgrävningsplats i Wetlands. Remtravels fossil från Darkshore är det du redan har lämnat till Flagongut.",al={"var är fossilet","vem har remtravels fossil","whelgars fossil"}},{q="Varför har rovfåglarna Stone of Relu?",a="När Flagongut färdades längs vägen genom Wetlands för att träffa Prospector Whelgar överfölls han av fläckiga rovfåglar. I kaoset under attacken svalde ett av rovdjuren stenen hel.",al={"rovfågel svalde relik","varför rovfåglarna har stenen"}},{q="Vad tror dvärgarna att fossilen kan göra?",a="Flagongut tror att fossilen rymmer en dold kraft och hemligheter från det förflutna, och att Stone of Relu är nyckeln till att frigöra dem.",al={"fossilens kraft","vad gör fossilet"}}},fx={["1568e7b3"]={q="Vad ska Flagongut's Fossil användas till?",a="Flagongut's Fossil är ett av de forntida fynd som dvärgarnas utgrävare har hittat, tillsammans med den bit som Prospector Remtravel grävde fram i Darkshore. Archaeologist Flagongut tror att de uråldriga relikerna bär på vilande magisk kraft och bortglömda hemligheter, som han hoppas kunna låsa upp och tyda med hjälp av Stone of Relus resonanta kraft.",al={"flagonguts fossil","vad flagonguts fossil används till","vad är flagonguts fossil"}}},fp="28,229,29.366.0,19.376.1,48.246.0,26.221.0,31.241.0,28.162.0,38.172.0,45.133.0"}
P.entries["quest:94369"] = {n="The Fate of Zephras",s="I Valanaar ger du Talaanis Shadowsong besked om faran som hotar Zephras. De fallna skyddsbarriärerna lämnar ön blottad för Al'Akir, och dess folk måste bestämma hur de ska skydda sitt hem.",h="I Valanaar ger du Talaanis Shadowsong besked om faran som hotar Zephras.",kw={"al'akir","elaadrin","lorthuna","shrine of akir","talaanis shadowsong","valanaar","skyddsbarriärer","windlord","zephras"},sec={{t="En varning till Talaanis",b="Du berättar för Talaanis vad som hände ovanför Shrine of Akir. Du berättar om Elaadrins plan att lämna Zephras Isle. High Elder Shadowsong behöver förstå faran och varför du skickades till Azeroth. Folket i Zephras måste hitta ett sätt att rädda sitt hem."},{t="Det som återstår",b="Talaanis begrundar nyheterna. Lorthuna är borta, och kulten har förlorat sin ledare. Zephras har inte invaderats. Ändå kan Al'Akir rikta sin uppmärksamhet mot ön om några år eller årtionden, och nu blandas skälen att fira med rädsla."}},faq={{q="Vem ska jag tala med?",a="Du talar med Talaanis Shadowsong i Valanaar.",al={"vem att tala med","talaanis","var rapportera"}},{q="Vad ska jag berätta för Talaanis?",a="Du berättar för Talaanis vad som hände ovanför Shrine of Akir och om Elaadrins plan att lämna Zephras Isle.",al={"vad hände vid helgedomen","vad rapportera","nyheter från shrine of akir"}},{q="Varför är folket i Zephras rädda för Al'Akir?",a="Skyddsbarriärerna som dolde Zephras har fallit. Al'Akir kan välja att anfalla medan folket befinner sig i hans domän.",al={"varför frukta al'akir","windlord fara","hot från al akir"}},{q="Vad behöver High Elder Shadowsong veta?",a="High Elder Shadowsong behöver få veta vilken fara som hotar och vad folket i Zephras tänker göra under sitt uppdrag till Azeroth.",al={"vad talaanis behöver","nyheter till high elder","avsikter för azeroth"}}},fp="19,183,22.251.0,12.225.1,20.47.0,24.102.0,48.104.0,45.122.0"}
P.entries["quest:94373"] = {n="Call of Earth",s="Call of Earth är en helig prövning under Teo Hammerstorms ledning i Anvilmar, där de prövades tålamod och uthållighet sätts på prov. De måste möta Frostmane-trollen söderut och ta deras björnhängen innan de får en jord-sapta.",h="Call of Earth är en helig prövning under Teo Hammerstorms ledning i Anvilmar, där de prövades tålamod och...",kw={"anvilmar","call of earth","coldridge valley","earth totem","frostmane","frostmane bear pendant","iceclaw-björn","sapta","shaman","teo hammerstorm"},ang={["class:Shaman"]="Call of Earth är en tidig invigning i gemenskapen med stenens och jordens andar och leder fram till att en jord-sapta tillreds.",["faction:Alliance"]="Denna rit prövar nyblivna försvarare mot de framryckande Frostmane-trollen som håller till i grottorna söder om Anvilmar.",["race:Dwarf"]="Denna prövning erbjuds i Coldridge Valley nära Anvilmar och knyter dvärgarnas styrka och bergsarv till jordens beständiga tålamod."},sec={{t="Stenens visdom",b="I Anvilmar i Coldridge Valley vakar mentorn Teo Hammerstorm över de prövade som är redo att följa jordens karga väg. Teo ser landet som en stadig och orubblig grund och vägleder unga vandrare att lyssna till bergen. Han varnar för att stenen visserligen är en beständig sköld, men att dess gunst inte ges lättvindigt. Verklig beslutsamhet och djup respekt krävs innan jordens hemligheter delas."},{t="Prövning i Frostmane Den",b="För att visa sig redo måste en prövad möta Frostmane-trollen som lurar i en grotta söderut. Trollen gör grova hängen av de våldsamma Iceclaw-björnarna som strövar omkring på de frusna höjderna. Att återta två sådana björnhängen från trollens håla är ett konkret bevis på att den som ansöker har den envisa beslutsamhet och styrka som elementandar kräver."},{t="Jord-saptan",b="När den prövade visar hänget för Teo Hammerstorm berömmer den äldre dennes tålamod, jordens främsta dygd, som består längre än sönderfallande toppar och floddalar som gröps ur. Som erkännande för denna bevisade respekt börjar Teo förbereda en jord-sapta, en viktig katalysator som låter den prövade uppfatta och följa elementens sanna väg."}},faq={{q="Vem erbjuder uppdraget Call of Earth?",a="Teo Hammerstorm, en äldre vägvisare i Anvilmar i Coldridge Valley, erbjuder prövningen. Han lär unga prövade stenens vägar och låter dem bevisa sin beslutsamhet inför jordens andar.",al={"vem ger call of earth","uppdragsgivare call of earth","teo hammerstorm-uppdrag"}},{q="Vad ber Teo Hammerstorm dig att göra?",a="Du måste ta dig söder om Anvilmar till grottan där Frostmane-trollen håller till och hämta två Frostmane Bear Pendants, som trollen tillverkar av Iceclaw-björnar. När du lämnar dem till Teo Hammerstorm är prövningen avklarad.",al={"mål för call of earth","vad behövs för call of earth","frostmane-hängen uppdrag"}},{q="Var hittar du Frostmane Bear Pendants?",a="Hängena bärs av Frostmane-trollen som bor i en grotta söder om Anvilmar. Talismanerna tillverkas av lokala Iceclaw-björnar och bärs av trollen som håller till i hålan.",al={"var finns frostmane bear pendants","hur får man frostmane bear pendants","frostmane-grottan anvilmar"}},{q="Vilken belöning förbereder Teo Hammerstorm när prövningen är avklarad?",a="En sapta är en ceremoniell blandning eller dryck som andliga mentorer tillreder för att stämma en utövare med elementandar. När prövningen är avklarad tillreder Teo en jord-sapta som låter dig följa jordens sanna väg.",al={"vad är en sapta","jord-sapta dvärg","vad tillverkar teo hammerstorm"}},{q="Varför måste de prövade möta Frostmane-trollen i den här prövningen?",a="Att konfrontera Frostmane-trollen visar den fysiska beslutsamhet och andliga uthållighet som krävs för att stå i förbindelse med jorden. Genom att ta björnhängena från fientliga troll i deras håla bevisar den prövade sig värdig bergens beständiga gunst.",al={"varför döda frostmane-troll","varför frostmane-hängen"}},{q="Vad lär Teo Hammerstorm ut om jordens natur?",a="Teo lär ut att tålamod är jordens största dygd och påpekar hur den består medan berg vittrar sönder och floder långsamt gröper ur dalar. Han betonar att stenen skyddar dem som respekterar den, men varnar för att även berggrunden kan rubbas om man förnärmar den.",al={"jordens dygder teo hammerstorm","bergets visdom"}}},fp="13,171,19.289.0,26.279.0,17.273.1,35.180.0,40.189.0,46.135.0,57.139.0,60.162.0,58.204.0"}
P.entries["quest:94374"] = {n="Call of Earth",s="Call of Earth är en helig shamanrit som binder en novissjäls dödliga ande till världens bestående grundvalar. Genom att dricka den visionära brygden Earth Sapta vid en avskild bergsande-sten lär sig sökaren ödmjukhet, tålamod och elementär medvetenhet bland snö och klippor.",h="Call of Earth är en helig shamanrit som binder en novissjäls dödliga ande till världens bestående grundvalar.",kw={"call of earth","dun morogh","earth sapta","elementrit","hidden path","sapta","shaman","spirit stone"},ang={["class:Shaman"]="Den här riten är en viktig gemenskap för shamaner. Den binder anden till stenen och ger en syn bortom dödlig uppfattningsförmåga genom sapta, den rituella brygden.",["faction:Alliance"]="Att en elementrit förekommer bland de snöiga bergsklyftorna visar hur shamantraditioner slår rot i Alliansens områden.",["race:Dwarf"]="Med dvärgarnas kärva talrytm bland frusna bergstoppar knyter denna heliga gemenskap bandet till jorden direkt till Dun Moroghs snöiga höjder."},sec={{t="Visionens brygd",b="Call of Earth är en helig prövning i andlig samklang, där en novis måste dricka den förtrollade brygden Earth Sapta vid en avlägsen bergshelgedom. Sapta har skapats genom uråldrig elementmagi och binder drickarens ande till världens berggrund. Den ger dödliga ögon den sällsynta förmågan att skåda elementandar och subtila strömmar som vanliga ögon inte kan se. På grund av sin styrka får brygden bara drickas på en utvald helig plats där bandet mellan ande och sten kan knytas på ett säkert sätt."},{t="Andestenen i snön",b="Högt uppe på ett snödrivet berg, vid slutet av en avskild dold stig, vilar Spirit Stone. Noviser färdas genom det bistra, frusna landskapet för att ödmjukt stå inför den uråldriga klippan. När de träder fram utan högmod och dricker sapta upptäcker de att den levande jorden välkomnar dem även bland vinterns hårdaste bergsklyftor. Bergen blir en grund för varaktig fysisk styrka, medan de vidsträckta, stilla slätterna lär ut tålamodets lågmälda kraft."},{t="Styrka och stillhet",b="Att tala med stenen är en grundläggande rit för andliga vägvisare. Till skillnad från vindens rastlösa raseri, elden och det dånande vattnet lär jorden ut orubblig disciplin och stillsam motståndskraft. För att klara riten måste sökaren ta till sig jordens stilla väsen och förbereda kropp och sinne för de motstridiga, kaotiska motsatserna hos de mer ombytliga elementen som dånar över världen."}},faq={{q="Vad är Earth Sapta?",a="Earth Sapta är en kraftfull, mystisk brygd som framställts med magi för att binda en utövares ande direkt till elementen. Den är inte avsedd för den viljesvage. När man dricker den genomborrar den den vanliga dödliga synen och visar andar och elementära sanningar som andra inte kan uppfatta.",al={"vad är sapta","lore om earth sapta","vad gör sapta"}},{q="Var ska sapta drickas?",a="Brygden får bara drickas på en särskilt utsedd helig plats. I den här riten skickas utövaren norrut uppför berget längs en dold stig för att hitta den uråldriga Spirit Stone, undangömd bland bergsklyftorna.",al={"var dricker jag sapta","var ligger spirit stone","var finns spirit stone"}},{q="Vad är syftet med riten Call of Earth?",a="Call of Earth är en grundläggande prövning i gemenskap och ödmjukhet. Genom att dricka sapta vid Spirit Stone lär sig novisen att hämta styrka från bergen och tålamod från slätterna, och att stämma sin dödliga ande med den levande världen innan hen möter de mer våldsamma elementen.",al={"varför göra uppdraget","betydelsen av call of earth","lore om call of earth"}},{q="Vem kan brygga Earth Sapta?",a="Bara ett fåtal invigda shamaner har kunskapen och den andliga beredskap som krävs för att brygga sapta. Receptet hålls hemligt och vördas djupt, eftersom brygden knyter den dödliges medvetande direkt till urkrafterna.",al={"vem kan sapta-receptet","kan vem som helst göra sapta"}},{q="Hur skiljer sig jordelementet från de andra elementen?",a="Medan andra elementkrafter kolliderar, brinner och dånar i våldsam oro står jordelementet för orubblig stillhet, tålamod och en grund som inte sviktar. Noviser måste först lära sig ödmjukhet inför stenen innan de möter de andra elementens ombytliga dubbelnatur.",al={"jorden jämfört med andra element","jämförelse mellan jord, eld, vatten och luft"}},{q="Var utspelar sig den här riten?",a="Uppdraget utspelar sig högt uppe i en kall, snötäckt bergskedja. Där följer noviser en avskild stig som slingrar sig genom snö och sten för att tala med landets andar trots den bitande frosten.",al={"var utspelar sig call of earth","jorduppdrag i fruset land"}}},fp="13,213,21.300.0,28.300.0,22.330.0,20.259.0,33.174.0,46.264.0,34.232.0,61.242.0,39.178.0"}
P.entries["quest:94375"] = {n="Call of Earth",s="Call of Earth är en elementär övergångsrit för unga shamaner i Dun Moroghs snöiga vidder. Genom att tala med de lokala jordandarna får de invigda en Rough Quartz att ta med till Teo Hammerstorm i Anvilmar. Den enkla stenen bevisar deras förbindelse med andarna och blir kärnan i deras Earth Totem.",h="Call of Earth är en elementär övergångsrit för unga shamaner i Dun Moroghs snöiga vidder.",kw={"anvilmar","call of earth","coldridge valley","dun morogh","earth totem","rough quartz","shaman","teo hammerstorm","totem"},ang={["class:Shaman"]="Att tala med jordens andar och vinna en Earth Totem är en grundläggande övergångsrit för alla blivande shamaner.",["faction:Alliance"]="Shamanritualer kring Anvilmar vittnar om att elementens andliga vägledare blir allt mer närvarande i Ironforges länder.",["race:Dwarf"]="Dvärgarnas band till sten och berg går djupt. Att tala direkt med jordandar i Dun Morogh förenar deras förfäders stenhantverk med shamanens väg."},sec={{t="Den viskande stenen",b="Call of Earth markerar de första stegen på shamanens andliga väg för en invigd i Dun Morogh. Djupt bland de frusna topparna måste den blivande shamanen söka upp jordens ande och lyssna till dess lärdomar. Provet kräver ödmjukhet: anden skänker bara en Rough Quartz, en enkel sten som ska bli hjärtat i en Earth Totem. Den påminner den sökande om att sann uthållighet inte mäts i storlek, utan i tålamod, styrka och orubblig beslutsamhet."},{t="Bergens gåva",b="När den invigde återvänder till Anvilmar med stenen i handen bedömer Teo Hammerstorm om hen är värdig. Som hantverkare och vägledare kräver Teo tydliga bevis på att bergsandarna har erkänt den sökande. Utan Rough Quartz avvisas den invigde utan vidare; med stenen formar Teo den råa stenen till en Earth Totem och knyter den unga shamanen till världens rötters tidlösa styrka."}},faq={{q="Vad används Rough Quartz till?",a="En jordelementarande ger Rough Quartz som bevis på förbindelsen med andarna. Den ser kanske ut som en oansenlig sten, men blir den nödvändiga kärnan när du skapar din Earth Totem.",al={"syftet med rough quartz","vad är rough quartz","varför behöver jag rough quartz"}},{q="Vem är Teo Hammerstorm?",a="Teo Hammerstorm är en mentor i Anvilmar i Dun Morogh. Han prövar blivande shamaner och kräver bevis på förbindelse med elementen innan han formar deras heliga totem.",al={"vem är teo hammerstorm","teo hammerstorms plats","var är teo"}},{q="Vad är Call of Earth?",a="Call of Earth är ett heligt prov där unga shamaner söker kontakt med jordandarna, visar tålamod och styrka och vinner sin första Earth Totem.",al={"call of earth-uppdragskedjan","vad är call of earth","earth totem-uppdrag"}},{q="Vad begär jordens ande av den invigde?",a="Jordens ande ber den invigde att förbli stark, ha tålamod och söka visdom. Den lär ut att även det minsta kan överleva andra och att sann kraft kommer ur ömsesidig respekt för jorden.",al={"jordandens lära","vad begär jorden","shamanens jordfilosofi"}},{q="Var ligger Anvilmar?",a="Anvilmar är dvärgabosättningen i Coldridge Valley i Dun Morogh. Där samlas de unga dvärginvigda för att träna och tala med de omgivande bergen.",al={"vad är anvilmar","anvilmars bakgrund","var utspelar sig call of earth"}},{q="Varför är Earth Totem viktig?",a="Ett totem är en helig förbindelse mellan en shaman och elementandar. Earth Totem knyter bärarens vilja till bergens stadiga kraft och motståndskraft.",al={"varför totemet är viktigt","shamanernas totemtradition","vad gör en earth totem"}}},fp="13,190,20.342.0,20.329.0,29.111.0,23.159.0,26.107.0,47.186.0,26.129.0,33.140.0"}
P.entries["quest:944"] = {n="The Master's Glaive",s="Uppdraget skickar Alliance-äventyrare söderut genom Darkshore för att undersöka den kusliga Master's Glaive åt Onu, en uråldrig visdomsväktare. Målet är att ta reda på om den lömska sekten Twilight's Hammer har infiltrerat kvarlevorna efter den fallna forntidsskräcken.",h="Uppdraget skickar Alliance-äventyrare söderut genom Darkshore för att undersöka den kusliga Master's Glaive...",kw={"darkshore","the master's glaive","gammal herre","onu","phial of scrying","spåskål","twilight's hammer"},ang={["class:Druid"]="Druider besvarar Onus kallelse för att förstå hur den uråldriga, vilande smittan djupt nere i jorden stör landet och djurlivet omkring den.",["faction:Alliance"]="Alliance-styrkorna i Darkshore måste hindra Twilight's Hammer från att väcka uråldriga fasor som kan översvämma de kämpande bosättningarna i norra Kalimdor.",["race:NightElf"]="För nattalver är Master's Glaive en påtaglig påminnelse om urtidens fasor som fanns före deras civilisation. Att se galna kultister vanhelga Darkshores heliga jord är outhärdligt."},sec={{t="En oroande närvaro",b="När Onu, en uråldrig visdomsväktare, undersöker den kvardröjande korruptionen och det fördrivna djurlivet längs Darkshore lägger han märke till oroande tecken. Nagorna längs kusten är illa nog, men Twilight's Hammers närvaro bådar betydligt värre. Den fanatiska sekten dyrkar inte vanliga mörka krafter. De vördar världens uråldriga urkrafter, som störtades för tidsåldrar sedan."},{t="Den fallne herren",b="Längre söderut ligger Master's Glaive, en dyster utgrävningsplats kring en kolossal varelse som spetsats av ett enormt stenvapen. Onu ger dig en Phial of Scrying och skickar spejare ner i hålan för att bekräfta om kultisterna har samlats där. Som Onu varnar dig har den spetsade bjässen visserligen varit död i evigheter, men spår av dess uråldriga, fördärvande kraft dröjer sig ännu kvar i benen – ett byte som Twilight's Hammer inte kan motstå."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Uppdraget ges av Onu, en vördnadsvärd uråldrig visdomsväktare som håller till längs vägen i södra Darkshore, nära Grove of the Ancients.",al={"uppdragsgivare","vem ger uppdraget master's glaive","startfigur"}},{q="Vad är Master's Glaive?",a="Master's Glaive är en forntida plats i södra Darkshore där en monstruös uråldrig herre föll för evigheter sedan, genomborrad genom skallen av en väldig stenglaiv. Det enorma förstenade skelettet ligger fortfarande inbäddat i jorden.",al={"vad är master's glaive","master's glaives bakgrund","jätteskalle i darkshore"}},{q="Varför är Twilight's Hammer-sekten intresserad av platsen?",a="Twilight's Hammer dyrkar Azeroths gamla, mörka krafter. Den väldiga varelsen som spetsades vid glaiven har varit död länge, men vilande spår av dess urkraft finns kvar i kvarlevorna. Kultisterna är desperata att lägga beslag på den.",al={"twilight-sekten i darkshore","varför är twilight-kultister här","twilight's hammer master's glaive"}},{q="Hur rapporterar jag tillbaka till Onu?",a="Du behöver inte gå hela vägen tillbaka till Onus fysiska plats. När du har utforskat utgrävningshålan vid Master's Glaive använder du Phial of Scrying i väskorna för att frammana en spåskål på marken. Då kan du tala direkt med Onu genom magi.",al={"var lämnar man in uppdraget","hur använder man spåflaskan","spåskål"}},{q="Vad händer efter spejaruppdraget?",a="När du har använt spåskålen för att bekräfta att kultisterna är där skickar Onu dig genast till deras läger i uppdraget 'The Twilight Camp' för att ta reda på mer om deras verksamhet.",al={"nästa uppdrag","fortsättning på master's glaive"}}},fx={fcbe4ca5={q="Varför skickar Onu dig för att undersöka The Master's Glaive?",a="Onu är djupt oroad över att Twilight's Hammer finns i Darkshore. Som en uråldrig vishetsväktare som vakar över skogarna vet han att den nihilistiska sekten vördar jordens besegrade Old Gods. The Master's Glaive markerar den forntida viloplatsen för ett sådant fallen vidunder, och Onu fruktar att rester av dess kvardröjande mörka kraft kan grävas fram och användas av sektmedlemmarna, trots att varelsen är död.",al={"varför vill onu detta","onus motiv vid the master's glaive","varför spana vid the master's glaive"}},["821e537b"]={q="Vilka skickas du att undersöka vid The Master's Glaive?",a="Du skickas för att rekognoscera Twilight's Hammer-sektmedlemmarna som smyger runt det väldiga monumentet. Dessa fanatiker vördar uråldriga krafter som en gång härskade över Azeroth. De har samlats i den väldiga gropen vid The Master's Glaive för att komma åt den ockulta essens eller kraftrest som fortfarande strålar från den förstenade skallen efter varelsen som dödades där.",al={"målet vid the master's glaive","vem ska jag leta efter vid the master's glaive","vem är vid the master's glaive"}},dfa4afd6={q="Varför behöver Onu att du spanar vid The Master's Glaive i stället för att gå dit själv?",a="Onu är en enorm, rotad vishetsväktare som inte obemärkt kan smyga sig ner i den djupa ravinen vid The Master's Glaive. Dessutom är Darkshores nattalvstrupper hårt ansatta av nagor längs kusten och förruttnelse i vildmarken. En smidig och duglig resenär med en Phial of Scrying kan i tysthet spana på sektens läger och rapportera tillbaka med magi utan att väcka oönskad uppmärksamhet.",al={"varför jag för onu","varför skicka mig till the master's glaive","varför spanar inte onu vid the master's glaive"}}},fp="19,162,21.256.0,15.334.0,29.119.0,28.172.0,57.180.0,28.187.0,32.147.0"}
P.entries["quest:94411"] = {n="Meddlesome Mages",s="Meddlesome Mages handlar om växande motsättningar i Shen'dar Highlands, där lärlingar från High Order tränger sig in nära heliga stående stenar. Lokala väktare måste driva bort dem för att skydda de sköra mystiska krafter som håller ön samman från vårdslös magisk påverkan.",h="Meddlesome Mages handlar om växande motsättningar i Shen'dar Highlands, där lärlingar från High Order tränger...",kw={"magiskt inblandande","high order","high order apprentices","meddlesome mages","shen'dar highlands","shen'dorei","stående stenar"},ang={["class:Mage"]="Magiker kommer att lägga märke till den skarpa kritiken av vårdslös besvärjelsekonst. High Orders lärlingar struntar i den sköra balansen i naturen som håller ön samman och visar därmed farorna med okontrollerad magisk påverkan."},sec={{t="Intrång vid stenarna",b="Spänningarna har blossat upp norr om byn i Shen'dar Highlands, där lärlingar från High Order har samlats kring urgamla stående stenar. Trots upprepade varningar om att låta dessa heliga platser vara har magikerna fortsatt att utforska sina magiska intressen. De lokala ledarna tvekar inför att utgjuta blod från sina shen'dorei-fränder, men har kallat på hjälp utifrån för att skingra de inträngande lärlingarna innan deras inblandning orsakar bestående skada."},{t="Den sårbara ön",b="Brådskan att driva bort High Order bottnar i den sköra balans som håller ön vid liv. De mystiska krafter som håller landet samman är bräckliga och gör hemlandet sårbart för vårdslös trollkonst. För stående stenarnas försvarare visar High Order fullständig likgiltighet inför farorna med sitt inblandande. En enda oförsiktig besvärjelse kan därför slita sönder öns band och förgöra allt som lever där."}},faq={{q="Vad handlar uppdraget Meddlesome Mages om?",a="Meddlesome Mages är ett uppdrag där äventyrare ska konfrontera och skingra High Order Apprentices, som har trängt sig in vid heliga stående stenar norr om byn i Shen'dar Highlands.",al={"vad är meddlesome mages","uppdraget meddlesome mages","vad är det här för uppdrag"}},{q="Vilka är High Order Apprentices?",a="High Order är en magikerfraktion vars medlemmar beskrivs som shen'dorei-bröder och -systrar till lokalbefolkningen. Deras lärlingar tränger in på helig mark och utforskar magi trots varningar om att hålla sig borta.",al={"vilka är high order apprentices","vad är high order","high order-magiker"}},{q="Varför måste High Order Apprentices skingras?",a="High Order har gång på gång ignorerat varningarna om att hålla sig borta från de stående stenarna. Deras vårdslösa magiska inblandning hotar de sköra magiska krafter som håller ön samman och riskerar att förstöra hemlandet.",al={"varför skingra high order","varför bekämpa lärlingarna","problem med stående stenar"}},{q="Var samlas High Order Apprentices?",a="Konfrontationen äger rum vid de stående stenarna norr om den lokala byn i Shen'dar Highlands.",al={"var finns uppdraget","shen'dar highlands plats","stående stenar norr om byn"}},{q="Vilka är shen'dorei som nämns i uppdraget?",a="Shen'dorei är släkt med uppdragsgivarens folk. Även om en inre konflikt försvagar deras gemensamma samhälle känner de lokala ledarna sig tvingade att agera beslutsamt mot High Order för att avvärja en katastrof.",al={"vilka är shen'dorei","shen'dorei-bröder och -systrar","vad är shen'dorei"}},{q="Vilken fara utgör magikerna för ön?",a="Krafterna som håller ön samman är sköra och sårbara. Okontrollerat magiskt inblandande kan rubba dessa band och i värsta fall förstöra hela ön.",al={"vad är faran","öns sköra krafter","vad kan hända med ön"}}},fp="16,168,26.347.0,18.259.0,41.133.0,35.191.0,49.195.0,47.100.0,46.196.0,44.133.0"}
P.entries["quest:94413"] = {n="A Magical Affront",s="A Magical Affront är ett uppdrag på Zephras som kretsar kring en konflikt om nyligen uppenbarade ley lines.",h="A Magical Affront är ett uppdrag på Zephras som kretsar kring en konflikt om nyligen uppenbarade ley lines.",kw={"a magical affront","arkanisk","ley line","ley lines","ärr","windshapers","zephras"},ang={["class:Druid"]="Druider kan hamna i en filosofisk konflikt, eftersom Windshapers ser de blottade ley lines som sårande ärr i det naturliga landskapet som desperat behöver läkas.",["class:Mage"]="För arkaniska magiutövare ger ley lines som trätt fram på Zephras en sällsynt, direkt tillgång till rå mystisk energi. Därför är det av stort vetenskapligt och magiskt intresse att bevara dem.",["class:Shaman"]="Windshapers vill lugna och läka störningar över Zephras. Deras omsorg om elementen och naturen står därmed i direkt konflikt med ordnar som utnyttjar råa magiska flöden."},sec={{t="Avslöjade strömmar",b="På Zephras yta har uråldriga underjordiska kanaler med rå magi nyligen brutit igenom marken. För lärda och magiutövare i den lokala orden är detta en ovärderlig gåva. Direkt, påtaglig kontakt med ley lines ger dem en aldrig tidigare skådad insikt i de arkaniska strömmar som genomsyrar regionen och utökar deras magiska kunnande avsevärt."},{t="Ärr och strid",b="Alla ser inte de blottade energierna som ett mirakel. The Windshapers ser sprickorna som öppna sår och destruktiva ärr tvärs över Zephras. De är fast beslutna att läka den sårade jorden och samlas vid brottställena för att dämpa eller läka de blottade ley lines. För orden som förlitar sig på denna råa kraft är ingreppet ett outhärdligt hot. Därför skickar de äventyrare sydväst in i skogen för att driva bort Windshapers."}},faq={{q="Vilka är Windshapers?",a="Windshapers är en grupp verksam på Zephras. De ser inte de uppträdande ley lines som en gåva av rå energi, utan som onaturliga sår eller ärr i landet som måste läkas. Deras insatser ställer dem i direkt konflikt med ordnar som vill studera och kanalisera ley lines.",al={"vilka är windshapers","vad är windshapers","windshapers zephras"}},{q="Varför vill orden driva bort Windshapers?",a="En orden som studerar ley lines på Zephras behöver tillgång till deras ytliga kraft för att fördjupa sin mystiska förståelse. Eftersom Windshapers aktivt försöker ”läka” och stänga eller laga dessa ley lines, ser orden deras handlingar som en outhärdlig förolämpning och kräver att de drivs bort.",al={"varför döda windshapers","varför slåss mot windshapers","windshapers konflikt"}},{q="Vad är ley lines på Zephras?",a="Ley lines är kanaler av mystisk energi som löper genom världen. På Zephras har dessa kanaler nyligen brutit fram till ytan och blottat direkt magisk kraft som genomsyrar landet. Det ger arkaniska magiutövare en aldrig tidigare skådad möjlighet att studera den.",al={"vad är ley lines på zephras","zephras ley lines","ley lines vid ytan"}},{q="Var ligger den omstridda ley line?",a="Den omstridda ley line som nämns i uppdraget ligger i skogen sydväst på Zephras, där Windshapers har samlats för att börja stänga eller laga det blottade magiska flödet.",al={"var ligger skogens ley line","ley line plats","skogen i sydväst"}},{q="Varför ser Windshapers ley lines som ärr?",a="Windshapers uppfattar det plötsliga brottet och framträngandet av råa underjordiska energier genom jorden som våldsamma ärr tvärs över Zephras. Enligt deras syn kräver återställandet av den naturliga balansen att revorna lagas, vilket står i direkt motsättning till arkaniska besvärjare som vill hålla dem öppna.",al={"varför vill windshapers läka ley lines","är ley lines skadliga på zephras","att läka ärren"}},{q="Vad har Zephras för betydelse i konflikten?",a="Zephras är landet där dessa blottade ley lines har trätt fram. Den plötsliga uppkomsten av rå magisk kraft över dess yta har gjort platsen till en konfliktpunkt mellan dem som vill bemästra dess arkaniska energier och dem som ser dem som onaturliga sprickor som måste återställas.",al={"vad är zephras","var utspelar sig a magical affront","zephras berättelse"}}},fp="17,236,17.287.0,16.313.0,24.195.0,51.208.0,33.200.0,39.139.0,51.254.0,53.214.0"}
P.entries["quest:94414"] = {n="The Anchors of Zephras",s="The Anchors of Zephras är ett introduktionsuppdrag som Halaan Hawk-Eye erbjuder på Zephras Isle. Halaan låter resenärer låna hans skarpa syn på långt håll för att betrakta de uråldriga ankarpylonerna som håller den flytande ön på plats och bevarar den. De väldiga monoliterna tycks orörda på avstånd, men Halaan varnar för att vindandarnas stabiliserande magi har börjat vackla.",h="The Anchors of Zephras är ett introduktionsuppdrag som Halaan Hawk-Eye erbjuder på Zephras Isle.",kw={"ankarpylon","the anchors of zephras","halaan hawk-eye","ley-linjer","skynsyn","vindandar","zephras"},ang={["class:Mage"]="Halaan skiljer sin skarpa syn från magin hos dem som kan hämta kraft ur ley-linjerna under Zephras.",["class:Shaman"]="Ankarpylonerna är direkt beroende av vindandarnas välsignelse. Därför är all instabilitet i deras magi en akut elementär angelägenhet för schamaner som försöker bevara balansen."},sec={{t="Öns förankringar",b="Zephras ankarpyloner är uråldriga, väldiga monoliter som vindarnas andar skänkte ön. De är djupt invävda i öns mystiska grundvalar och binder, stabiliserar och bevarar landmassan bland de virvlande skyarna. Att se en av dem är att bevittna den sköra balans som håller Zephras svävande, helt beroende av vindandarnas välvilja."},{t="En oroande förändring",b="Ankarpylonerna står stolt och ser oskadda ut för blotta ögat, men de har börjat bete sig oberäkneligt. Halaan Hawk-Eye säger att den magiska harmoni som håller dem vid kraft har blivit instabil och ojämn på senare tid. Eftersom det saknas tydliga tecken på fysisk skada väcker detta subtila förfall stilla oro bland dem som vakar över lundarna, och antyder djupare obalanser som hotar ön."},{t="Halaans gåva",b="Halaan saknar både den medfödda skynsyn som låter vissa se mellan världar och den magiska förmågan att utnyttja Zephras djupa ley-linjer. I stället har han en enklare, skarpare naturlig gåva: synskärpa som når långt och klart. Genom att låna ut sitt perspektiv låter han andra se de avlägsna pylonerna i detalj och uppmuntrar nykomlingar att uppskatta det de har, samtidigt som de håller sig vaksamma på hemlandets föränderliga öde."}},faq={{q="Vad är ankarpylonerna på Zephras?",a="Ankarpylonerna är uråldriga, mystiska konstruktioner som vindarnas andar skänkte ön. De binder och förankrar Zephras och håller ön magiskt svävande och stabil ovanför världen omkring den.",al={"vad är förankringarna","zephras ankarpylon","vad är en ankarpylon"}},{q="Vad är det för fel på ankarpylonerna?",a="Pylonerna visar inga tydliga tecken på fysisk skada eller yttre förfall, men deras stabiliserande magi har på senare tid blivit instabil och ojämn. Det väcker oro för vad som i det tysta stör deras förbindelse.",al={"varför sviktar förankringarna","problem med ankarpylon","vad hände med förankringarna"}},{q="Vem är Halaan Hawk-Eye?",a="Halaan Hawk-Eye är en väktare som bor i Zephras Isles lundar. Han har välsignats med skarp syn som når långt och vakar över landets välmående, samtidigt som han begrundar öns mystiska hälsa.",al={"halaans bakgrund","vem är halaan"}},{q="Vad är Halaans gåva?",a="Halaans gåva är en utomordentligt skarp syn på långt håll. Till skillnad från mystiker som använder skynsyn för att se mellan världar eller kanalisera ley-linjernas krafter är Halaans förmåga naturlig och vardaglig. Den låter honom urskilja avlägsna landmärken med kristallklar skärpa.",al={"halaans gåva","hur ser halaan så långt"}},{q="Vad är skynsyn?",a="Skynsyn är en mystisk varseblivning som vissa utövare på Zephras besitter. Den låter dem tränga igenom slöjan och se direkt mellan världar, långt bortom vad vanlig fysisk syn förmår.",al={"vad är skynsyn","skynsyn betydelse"}},{q="Varifrån kommer magin som driver pylonerna?",a="Vindarnas andar skänkte Zephras ankarpylonerna. Halaan säger att pylonerna binder och bevarar ön, men förklarar inte varifrån deras fortsatta kraft kommer.",al={"vem skapade pylonerna","ankarpylonernas ursprung"}}},fx={["61bc2f74"]={q="Varför vill Halaan Hawk-Eye att du ska titta på ankarpylonen?",a="Halaan Hawk-Eye vakar över lunden och bryr sig djupt om Zephras välmående. De uråldriga ankarpylonerna, gåvor från vindarnas andar, binder samman och håller ön vid liv, men deras magi har på sistone blivit instabil och ojämn. Även om de ser oskadade ut erbjuder Halaan dig att dela sin skarpa syn, så att du kan se pylonerna på nära håll och förstå hur skört ditt hemland är.",al={"halaans motiv","varför titta på ankarpylonen","varför vill halaan detta"}}},fp="22,192,19.274.0,18.282.0,13.287.0,38.155.0,37.135.0,23.142.0,22.148.0,17.114.0,51.159.0"}
P.entries["quest:94427"] = {n="A Lesson in Divinity",s="Din orden skickar dig till Tanis Alderwood i Trade Quarter i Undercity. Där får du en chans att visa barmhärtighet genom goda gärningar.",h="Din orden skickar dig till Tanis Alderwood i Trade Quarter i Undercity.",kw={"a lesson in divinity","gudomlighet","barmhärtighet","tiggeri","tanis alderwood","trade quarter","undercity"},ang={["class:Priest"]="För dig som präst definierar din orden gudomlighet som att göra gott för dess egen skull. Den säger att tragedier kan hota den barmhärtighet som präglade dig i livet."},sec={{t="En kallelse till barmhärtighet",b="Din orden lär att gudomlighet innebär att göra gott för dess egen skull, inte att sträva efter att bli en gud. Enligt orden förde en tragedi dig hit. Nu ber den dig att hitta Tanis Alderwood i Trade Quarter i Undercity. Tanis behöver hjälp och kan ha nytta av din barmhärtighet."},{t="Tanis vädjan",b="När du närmar dig Tanis Alderwood är hen rädd att du ska skada hen. Hen försäkrar att hen inte har något otalt med dig eller din orden. Sedan vädjar hen till dig att lämna hen i fred."}},faq={{q="Vem är Tanis Alderwood?",a="Tanis Alderwood är en person som behöver hjälp i Trade Quarter i Undercity.",al={"tanis","vem är tanis","person i trade quarter"}},{q="Varför skickas jag till Tanis?",a="Din orden säger att Tanis Alderwood kan ha nytta av din barmhärtighet.",al={"varför tanis","hjälpa tanis","vad är meningen"}},{q="Vad betyder gudomlighet för min orden?",a="Din orden definierar gudomlighet som att göra gott för dess egen skull, snarare än att sträva efter att bli en gud.",al={"gudomlighetens betydelse","gott för dess egen skull","vad är gudomlighet"}},{q="Var kan jag hitta Tanis Alderwood?",a="Du hittar Tanis Alderwood i Trade Quarter i Undercity.",al={"tanis plats","var är tanis","trade quarter"}}},fp="20,127,16.244.0,14.156.1,23.66.0,23.60.0,36.88.0,33.60.0"}
P.entries["quest:94434"] = {n="A Lesson in Divinity",s="I Undercity ber Tanis Alderwood dig om rent tyg. Hans fru faller sönder, och han hoppas kunna linda in henne tills en apotekare blir ledig.",h="I Undercity ber Tanis Alderwood dig om rent tyg.",kw={"a lesson in divinity","apotekare","tiggare","dark lady","linnetyg","tanis alderwood","undercity","fru"},sec={{t="En tiggares vädjan",b="Apotekarna är upptagna med Dark Ladys ärenden. Därför ber Tanis dig att hämta linnetyg till hans fru. Han hoppas att tyget ska hålla ihop henne medan de väntar på hjälp."}},faq={{q="Vem ber om hjälp?",a="Tanis Alderwood, en tiggare i Undercity, ber dig att hjälpa hans fru.",al={"vem är tanis","tanis alderwood","tiggaren"}},{q="Vad är det för fel på Tanis fru?",a="Tanis säger att hon bokstavligen faller sönder och behöver lindas in för att hålla ihop.",al={"frun faller sönder","vad har hänt med hans fru","tanis fru"}},{q="Varför kan inte apotekarna hjälpa till?",a="Tanis säger att apotekarna är upptagna med Dark Ladys ärenden.",al={"apotekarna upptagna","varför ingen apotekare","dark ladys ärenden"}},{q="Vad behöver Tanis?",a="Tanis ber dig att hämta rent tyg så att han kan linda in sin fru medan de väntar på apotekarna.",al={"vilket tyg behöver han","linnetyg till tanis","hjälpa tiggaren"}}},fp="20,140,15.175.0,23.70.0,31.84.0,32.71.0,21.97.0"}
P.entries["quest:94435"] = {n="A Lesson in Divinity",s="Tanis Alderwood tackar dig för hjälpen och kallar dig en vän. Danitha Morr ser denna lilla tjänst som ett sätt att stärka Forsakens band till Light.",h="Tanis Alderwood tackar dig för hjälpen och kallar dig en vän.",kw={"a lesson in divinity","danitha morr","dark lady","forsaken","light","misstro","symbol","tanis alderwood"},ang={["faction:Alliance"]="Som resenär från Alliance hör du Danitha beskriva hur Forsaken arbetar för att hjälpa sitt folk att blomstra igen.",["race:Undead"]="Som Forsaken hör du Danitha mana till mod och rättfärdighet för att hjälpa ditt folk att blomstra igen."},sec={{t="En liten tjänst",b="Danitha Morr säger att din hjälp kan stärka Forsakens band till Light. Misstro och sammansvärjningar dröjer sig kvar bland Dark Ladys anhängare. Forsaken måste möta den rädslan med mod och rättfärdighet. Danitha ger dig en symbol för det som väntar."}},faq={{q="Vem tackar mig?",a="Tanis Alderwood tackar dig för att du hjälper honom och säger att du alltid kommer att ha en vän i honom.",al={"tanis alderwood","vem är tanis","tanis tackar"}},{q="Vad säger Danitha att min hjälp betyder?",a="Danitha säger att även en liten tjänst kan stärka Forsakens band till Light.",al={"varför hjälpa danitha","liten tjänsts betydelse","band till light"}},{q="Varför nämner Danitha misstro?",a="Danitha säger att Dark Lady och några i hennes tjänst misstror dem, och att vissa till och med smider ränker mot dem.",al={"misstro mot forsaken","dark lady rädsla","varför misstror man dem"}},{q="Vad ger Danitha mig?",a="En symbol från Danitha, för det som väntar.",al={"vilken symbol","danithas föremål","symbol för det som väntar"}}},fp="20,173,15.265.0,19.89.0,36.97.0,34.107.0,26.43.0"}
P.entries["quest:94436"] = {n="A Lesson in Divinity",s="I A Lesson in Divinity ber Danitha Morr dig visa vad en präst kan göra med Symbol of Life. Deathguard Billmuth vid Bandarion Keep har kommit för att söka hjälp åt en vän.",h="I A Lesson in Divinity ber Danitha Morr dig visa vad en präst kan göra med Symbol of Life.",kw={"a lesson in divinity","bandarion keep","danitha morr","deathguard billmuth","forsaken","light","präst","symbol of life"},ang={["class:Priest"]="Danitha ber dig att som präst visa din förmåga att kanalisera Light med Symbol of Life."},sec={{t="En vädjan om hjälp",b="Billmuth säger att prästerna avvisade honom, och hans vän kanske inte har någon annan att vända sig till. Han är inte stolt över att be dig, men han behöver hjälp åt Forsaken. Symbol of Life ska visa din förmåga att kanalisera Light. Att hantera den kan orsaka obehag. Dess kraft kan ändå vara din bundsförvant och vägledare, även för Forsaken, vars skapelse är knuten till en kraft som står i motsats till Light."}},faq={{q="Vem ber om hjälp?",a="Deathguard Billmuth vid Bandarion Keep har kommit för att söka hjälp åt en vän.",al={"billmuth hjälp","vem behöver hjälp"}},{q="Varför ber Billmuth en präst om hjälp?",a="Billmuth säger att prästerna avvisade honom, och du kan vara hans väns enda chans.",al={"varför präst","prästerna avvisade honom"}},{q="Vad är Symbol of Life?",a="Symbol of Life är en talisman med kraft från Light som Danitha Morr ger dig för att visa din förmåga att kanalisera Light.",al={"symbol of life","light talisman"}},{q="Varför kan det göra ont att hantera Symbol of Life?",a="Danitha varnar för att talismanen kan orsaka obehag eftersom Light står i motsats till kraften som skapade Forsaken.",al={"symbol smärta","light gör ont"}},{q="Var hittar jag Deathguard Billmuth?",a="Deathguard Billmuth finns på nedervåningen i Bandarion Keep.",al={"billmuth plats","bandarion keep"}}},fp="20,173,14.380.0,23.73.0,31.83.0,27.116.0,44.121.0,37.52.0"}
P.entries["quest:94438"] = {n="A Lesson in Divinity",s="Danitha Morr skickar dig till Venomweb Vale för att hitta Deathguard Falgan. Han och hans följeslagare kom ifrån varandra efter att ha fått veta att Scarlet Crusade planerar en attack mot Brill.",h="Danitha Morr skickar dig till Venomweb Vale för att hitta Deathguard Falgan.",kw={"a lesson in divinity","billmuth","brill","danitha morr","deathguard falgan","scarlet crusade","symbol of life","venomweb vale"},sec={{t="Falgans återkomst",b="Deathguard Falgan följde med Billmuth för att undersöka Scarlets verksamhet i Venomweb Vale. De fick veta att Scarlet Crusade planerar någon form av attack. Nu frågar Falgan om du vill hjälpa Forsaken ytterligare."}},faq={{q="Vem ber mig att hitta Falgan?",a="Danitha Morr ber dig att hitta Deathguard Falgan och hjälpa honom om du kan.",al={"vem skickade mig","danitha morr","uppdragsgivare"}},{q="Var finns Falgan?",a="Falgan finns i Venomweb Vale.",al={"falgans plats","var finns falgan","hitta deathguard"}},{q="Vad hände med Falgan?",a="Falgan stannade kvar efter att ett ljud gjort Scarlets styrkor uppmärksamma på honom och hans följeslagare. Hans följeslagare nådde Brill utan honom.",al={"falgan saknas","vad hände","rädda falgan"}},{q="Vad upptäckte Falgan och Billmuth?",a="Falgan och Billmuth fick veta att Scarlet Crusade planerar någon form av attack.",al={"scarlets order","vad upptäckte de","anfallsplaner"}},{q="Vad används Symbol of Life till?",a="Symbol of Life används för att återuppliva Deathguard Falgan.",al={"återuppliva falgan","symbol life","hur rädda falgan"}},{q="Vad ber Falgan om efter att ha återvänt?",a="Efter att ha återvänt frågar Falgan om du är villig att hjälpa Forsaken ytterligare.",al={"hjälpa forsaken","vad händer sedan","falgan frågar"}}},fp="20,163,15.200.0,32.72.0,16.27.0,24.124.0,38.79.0,31.67.0,37.82.0"}
P.entries["quest:94440"] = {n="A Lesson in Divinity",s="Deathguard Billmuth behöver din hjälp att hämta Scarlet Crusades anfallsplaner från Venomweb Vale. Deathguard väntar sig ett anfall och hoppas att planerna ska hjälpa dem att förbereda ett bakhåll.",h="Deathguard Billmuth behöver din hjälp att hämta Scarlet Crusades anfallsplaner från Venomweb Vale.",kw={"a lesson in divinity","anfallsplaner","bandarion keep","deathguard billmuth","forsaken","scarlet crusade","venomweb vale"},sec={{t="Order till fästet",b="Scarlet Crusaders bär förflyttningsorder i sina väskor, och Deathguard väntar sig ett anfall. Ta med en kopia av planerna till Deathguard Billmuth i Bandarion Keep. Då kan Deathguard förbereda ett bakhåll."},{t="En vän räddad",b="Billmuth tackar dig för att du räddade hans vän och säger att han ska ta planerna till sin befälhavare. Dina handlingar har visat honom att du är Forsaken rakt igenom, trots den misstro som vissa av hans folk hyser mot din klass."}},faq={{q="Vad behöver Billmuth?",a="Deathguard Billmuth ber dig att hämta Scarlet Crusades anfallsplaner från Venomweb Vale.",al={"vad vill billmuth","billmuth planer","planer till billmuth"}},{q="Var finns anfallsplanerna?",a="Scarlet Crusaders i Venomweb Vale bär på anfallsplanerna.",al={"var finns planerna","scarlet planer plats","hitta anfallsplaner"}},{q="Varför vill Deathguard ha planerna?",a="Deathguard väntar sig ett anfall och vill ha planerna för att kunna förbereda ett bakhåll.",al={"varför hämta planerna","vad ska planerna användas till","deathguard bakhåll"}},{q="Vem ska få planerna?",a="Ta med planerna till Deathguard Billmuth i Bandarion Keep.",al={"vem får planerna","lämna planerna till","var finns billmuth"}}},fp="20,172,19.209.0,14.221.1,24.94.0,27.62.0,39.81.0,29.57.0"}
P.entries["quest:94441"] = {n="A Lesson in Divinity",s="En annan Forsaken ber dig tacka Danitha Morr för paladinernas insats vid Bandarion Keep. Ditt arbete har vunnit Deathguards tacksamhet och ger dig återlösningens gåva.",h="En annan Forsaken ber dig tacka Danitha Morr för paladinernas insats vid Bandarion Keep.",kw={"a lesson in divinity","bandarion keep","danitha morr","deathguard","forsaken","light","återlösning","symbol of life"},sec={{t="Tack vid fästet",b="En annan Forsaken ber dig framföra ett tack till Danitha Morr vid Bandarion Keep. Resten av Deathguard kommer att få höra om din och de andra paladinernas insats. De är stolta över att räkna dig till Forsaken och litar på att Dark Lady vakar över dig."},{t="En gåva från Light",b="Danitha säger att en paladin som är redo att ta emot en av Lights största välsignelser kan använda Symbol of Life. Hon skänker dig återlösning och låter dig återuppväcka fallna följeslagare. Din insats betyder mycket för Forsaken och paladinerna vid Bandarion Keep. Deathguard hoppas att sådana handlingar ska vinna andra Forsakens hjärtan och sinnen."}},faq={{q="Vem ska jag tacka?",a="Du ombeds tacka Danitha Morr för paladinernas insats vid Bandarion Keep.",al={"vem är danitha","tacka danitha","danitha morr"}},{q="Vem får höra om insatsen?",a="Resten av Deathguard kommer att få höra om paladinernas insats vid Bandarion Keep.",al={"deathguards tack","vem får höra","insats vid fästet"}},{q="Vad gör Symbol of Life?",a="Symbol of Life kan användas av en paladin som är redo att ta emot en av Lights största välsignelser.",al={"symbol of life","livets symbol","vad gör den"}},{q="Varför är Deathguard stolta över mig?",a="Deathguard är stolta över att räkna dig till Forsaken och värdesätter din insats tillsammans med paladinerna vid Bandarion Keep.",al={"forsaken stolta","varför stolta","deathguard stolta"}}},fp="20,178,18.262.0,15.335.1,15.82.0,32.82.0,32.101.0,34.129.0"}
P.entries["quest:94449"] = {n="Call of Fire",s="Call of Fire är ett shamanistiskt uppdrag som leder noviser in i lågornas farliga och kaotiska rike högt uppe i Dun Morogh. Efter att ha bemästrat jordens tålmodiga lärdomar skickas utövaren till Bruegs Kindleborn för att pröva om hen är redo för Fire Sapta.",h="Call of Fire är ett shamanistiskt uppdrag som leder noviser in i lågornas farliga och kaotiska rike högt uppe...",kw={"bruegs kindleborn","call of fire","dun morogh","jordens sapta","fire totem","eldens sapta","schaman","south gate outpost"},ang={["class:Shaman"]="Det här uppdraget är en avgörande andlig prövning för schamanen, en övergång från stenens uthållighet till eldens våldsamma, destruktiva kraft.",["faction:Alliance"]="I Dun Moroghs berg följer alliansschamaner sina äldstes vägledning för att väcka kontakt med eldelementen.",["race:Dwarf"]="Denna rit äger rum högt ovanför South Gate Outpost i Dun Morogh och prövar om en dvärg har disciplin nog att tygla lågans brinnande hunger."},sec={{t="Det brinnande provet",b="Efter att ha visat tålamod och stadga genom jordens element får schamaner möta en betydligt mer oberäknelig kraft: eldens elementande. Till skillnad från den stadiga, obevekliga stenen lockar elden med löften om kaos, förstörelse och våldsam energi. En äldste skickar novisen över Dun Moroghs snötäckta toppar för att söka vägledning innan hen försöker tygla denna vilda hetta."},{t="Bergens eremit",b="Högt uppe i bergen ovanför South Gate Outpost håller mentorn Bruegs Kindleborn uppsikt från en avskild grotta. När en novis anländer med en äldstes rekommendation förbereder Bruegs hen för eldens sapta. Men han utfärdar en sträng varning: lusten att bränna och förtära väcks lätt, men att bemästra lågan kräver att man vet precis när man ska hålla igen."}},faq={{q="Vem är Bruegs Kindleborn?",a="Bruegs Kindleborn är en mentor som bor i en bergsgrotta högt ovanför South Gate Outpost i Dun Morogh. Han bedömer schamaner som äldste skickat dit för att avgöra om de har den mognad och disciplin som krävs för att få eldens sapta.",al={"vem är bruegs kindleborn","bruegs kindleborns historia","var finns bruegs"}},{q="Vad är eldens sapta?",a="En sapta är en elementär brygd eller beredning som låter en schaman kommunicera med elementandar. Eldens sapta ger kontakt med lågan och dess råa kraft, men kräver mental koncentration och en grund av sten.",al={"vad är eldens sapta","fire sapta","sapta betydelse"}},{q="Var finns Bruegs Kindleborn?",a="Bruegs Kindleborn finns långt österut i Dun Moroghs snöiga berg, i skydd i en grotta med utsikt över South Gate Outpost.",al={"var hittar man bruegs kindleborn","grottan vid south gate outpost","var lämnar man in call of fire"}},{q="Vad är syftet med Call of Fire?",a="Call of Fire är en övergångsrit för schamaner som har visat tålamod och bemästrat jorden. Den låter dem möta förstörelsens kaotiska kraft under Bruegs Kindleborns vakande öga.",al={"vad är call of fire","eldtotemets uppdrag i dun morogh"}},{q="Varför måste en schaman lära sig stenens lärdomar före elden?",a="Jorden står för orubbligt tålamod, stabilitet och kontroll. Utan den grund av stadga som stenen lär ut riskerar en schaman att överväldigas av eldens oberäkneliga hunger och destruktiva lidelser.",al={"varför stenen först","minns vad stenen lärde dig"}},{q="Vilka förkunskaper krävs innan man påbörjar Call of Fire?",a="Uppdraget bygger vidare på tidigare prövningar där novisen visat tålamod och funnit stadga i jorden. Den äldste skickar en elev till Bruegs Kindleborn först när elevens disciplin har visat sig vara stadig.",al={"förkunskaper för call of fire","koppling till tålamodsuppdraget"}}},fp="12,175,17.311.0,24.321.0,25.214.0,26.225.0,35.122.0,40.155.0,57.173.0,68.186.0"}
P.entries["quest:94465"] = {n="Call of Fire",s="Call of Fire är en helig prövning för noviser som vill visa att de är andligt redo att hantera elementär eld. De måste bära Torch of the Dormant Flame längs en avskild bergsstig i Loch Modan och söka upp Braldir Ashmantle vid Shrine of the Dormant Flame.",h="Call of Fire är en helig prövning för noviser som vill visa att de är andligt redo att hantera elementär eld.",kw={"braldir ashmantle","call of fire","fire totem","loch modan","shaman","shrine of the dormant flame","torch of the dormant flame","valley of kings"},ang={["class:Shaman"]="Prövningen sätter en blivande shaman på prov i sin hängivenhet att komma i kontakt med eldens elementandar. Hen måste bära en helig fackla till en avskild topp i Loch Modan.",["faction:Alliance"]="Medan vanliga resenärer i Alliansens områden bara ser karg bergssten, vaktar helgedomens väktare uråldriga elementhemligheter som är dolda för andras blickar.",["race:Dwarf"]="Uppdragets dialog speglar dvärgarnas sätt att tala och leder noviserna bortom Valley of Kings, upp bland de oländiga klipporna i Khaz Modan."},sec={{t="Stigen bortom Valley of Kings",b="Att förtjäna Fire Totem kräver mer än rå fysisk styrka. Noviserna får i uppgift att bära den släckta Torch of the Dormant Flame högt upp bland klipporna i Loch Modan. Bortom stenhällarna i Valley of Kings leder en mödosam stigning till en avskild bergstopp, där elementen råder långt ovanför de dödligas vägar."},{t="Shrine of the Dormant Flame",b="Högt uppe på den vindpinade toppen står Braldir Ashmantle, väktaren som har fått i uppdrag att vaka över Shrine of the Dormant Flame. Oförberedda vandrare och skattjägare som tar sig upp hit möts bara av tystnad och kal sten. För äkta noviser med den heliga facklan uppenbarar Braldir en djupare elementär kraft som slumrar i helgedomens eldfat och väntar på att åter tändas."}},faq={{q="Vad är uppdraget Call of Fire?",a="Call of Fire är en övergångsrit för en novis som vill förtjäna sitt eldtem. Uppdraget leder novisen upp bland klipporna i Loch Modan för att överlämna Torch of the Dormant Flame till Braldir Ashmantle på en helig bergstopp.",al={"vad är call of fire","shamanens eldprov i loch modan","uppdraget för fire totem"}},{q="Vem är Braldir Ashmantle?",a="Braldir Ashmantle är väktaren som vakar över Shrine of the Dormant Flame högt uppe bland klipporna i Loch Modan. Han avvisar vanliga resenärer och skattletare och välkomnar endast dem som bär Torch of the Dormant Flame.",al={"vem är braldir ashmantle","helgedomens väktare i loch modan"}},{q="Var ligger Shrine of the Dormant Flame?",a="Shrine of the Dormant Flame ligger högt uppe bland klipporna i Loch Modan. Dit kommer du genom att följa en dold stig som slingrar sig bortom Valley of Kings.",al={"var ligger shrine of the dormant flame","platsen för dormant flame"}},{q="Vad är syftet med Torch of the Dormant Flame?",a="Torch of the Dormant Flame är en rituell symbol som noviser bär för att visa sin uppriktiga avsikt och beredskap att komma i kontakt med elementär eld. Braldir Ashmantle måste få se facklan innan han tar emot dem.",al={"vad är torch of the dormant flame","syftet med torch of the dormant flame"}},{q="Varför måste novisen resa till Loch Modan?",a="Den heliga elementtoppen med Shrine of the Dormant Flame blickar ut över Loch Modan, bortom Valley of Kings. Platsen valdes för att ligga avskilt från vanliga resenärer.",al={"varför resa till loch modan","varför ligger eldhelgedomen i loch modan"}},{q="Hur förtjänar man eldtemet genom prövningen?",a="När novisen har nått Braldir Ashmantle och visat sin avsikt med facklan, måste hen tända lågan i helgedomens eldfat och återvända med den brinnande för att förtjäna eldtemet.",al={"vad händer när man hittar braldir","hur får man fire totem"}}},fp="12,157,35.270.0,31.328.0,31.202.0,25.204.0,49.124.0,54.195.0,45.165.0,48.166.0"}
P.entries["quest:94466"] = {n="Call of Fire",s="Call of Fire är en elementär prövning i Loch Modan där noviser förbereder sig för att tala med Eternal Flame och vinna sin egen Fire Totem. Under Braldir Ashmantles ledning samlar kandidater elementära ingredienser från lokala kobolder och troggs för att brygga en bindande Fire Sapta. Resan lär dem att eld inte bara är ett redskap för förödelse, utan själva livets smedja och andetag.",h="Call of Fire är en elementär prövning i Loch Modan där noviser förbereder sig för att tala med Eternal Flame...",kw={"braldir ashmantle","call of fire","eternal flame","fire sapta","fire tar","fire totem","loch modan","stonesplinter seer","tunnel rat geomancer"},ang={["class:Shaman"]="För att tala med elden måste man skapa ett elementärt band med hjälp av en särskilt tillredd sapta. Det leder mot gemenskap med Eternal Flame och möjligheten att få en Fire Totem.",["faction:Alliance"]="Denna prövning utspelar sig i dvärgarnas område Loch Modan och förankrar shamanernas riter stadigt i Alliansens marker, där lokala troggs och kobolder utgör hotet.",["race:Dwarf"]="Braldir Ashmantle vägleder noviser i Loch Modan och ger ett jordnära, dvärgiskt perspektiv på elementäreld. Han ser den som smedjans och skapelsens andetag, inte bara som förstörelse."},sec={{t="Vägen till lågan",b="Bland Loch Modans karga klippor vakar en elementär mentor vid namn Braldir Ashmantle över vägen för noviser som söker lågans kraft. Att tala med eldandarna är ingen enkel besvärjelse; först måste en dödlig själ stämmas till det brinnande elementet genom en helig brygd som kallas Fire Sapta. Utan denna förberedelse skulle Eternal Flames hetta förtära i stället för att upplysa. Braldir kräver att de sökande visar sin beslutsamhet genom att samla två avgörande eldbundna ingredienser från dalens fientliga invånare."},{t="Ingredienser från jord och gnista",b="För att tillreda Fire Sapta krävs ämnen med stark elementär resonans. I norr utvinner Tunnel Rat Geomancers klibbig Fire Tar i sina labyrintiska hålor och använder den som bränsle för sin underjordiska magi. I söder bär Stonesplinter Seers, troggmystiker, Reagent Pouches fyllda med primitiva elementära amuletter genom de karga kullarna. Att ta föremålen kräver kamp mot två av Loch Modans mest svårutrotade plågor, och materialen behövs för att binda en novis själ till elden."},{t="Visdomens härdning",b="När ingredienserna har lämnats över delar Braldir Ashmantle med sig av visdom som tyglar rå förstörelse med tålamod. För den erfarna mentorn är eld mycket mer än vrede och aska – den står för liv, smedjans hantverk och själva skapelsens andetag. Sann behärskning av elementen ligger i balans: liksom skuggan ger ljuset mening hindrar lågan stenen från att förbli ett blott kallt minne. Att bemästra lågan kräver att man vet när man ska förena i stället för att bara bränna."}},faq={{q="Vad är syftet med Call of Fire?",a="Call of Fire är en övergångsrit för blivande shamaner som söker gemenskap med Eternal Flame. För att tala med eldandarna och göra anspråk på en Fire Totem måste man först tillreda Fire Sapta, som binder ens dödliga själ till elementet.",al={"vad är call of fire","vad är det här för uppdrag","syftet med call of fire"}},{q="Vem är Braldir Ashmantle?",a="Braldir Ashmantle är en elementär vägvisare som bor i Loch Modan. Han lär noviser om eldens balans och tillreder den nödvändiga Fire Sapta när de rätta elementära ingredienserna har samlats in.",al={"vem ger call of fire","vem är braldir ashmantle","braldir ashmantles plats"}},{q="Vad är Fire Sapta?",a="Fire Sapta är en elementär dryck eller beredning som tillverkas av eldbundna ingredienser. Genom att dricka eller använda den stäms shamanens själ till och binds vid eldens elementplan, vilket möjliggör syner och gemenskap med Eternal Flame.",al={"vad är fire sapta","vad gör en sapta","varför behövs sapta"}},{q="Var hittar man Fire Tar?",a="Tunnel Rat Geomancers som håller till i koboldgrottorna i norra Loch Modan bär på Fire Tar. Geomanterna använder tjäran i sina primitiva eldkonster.",al={"var får jag fire tar","fire tars plats","fire tar i koboldgrottor"}},{q="Var hittar man Stonesplinter Reagent Pouch?",a="Reagent Pouch måste tas från Stonesplinter Seers som håller till i Loch Modans södra kullar. Dessa troggmystiker använder påsarna för att förvara ingredienser knutna till elementär magi.",al={"var får jag reagent pouch","stonesplinter seers påse","stonesplinter pouchs plats"}},{q="Hur ser Braldir Ashmantle på eldens element?",a="I stället för att behandla eld som meningslös förstörelse lär Braldir att eld är smedja, liv och skapelsens andetag. Den står i balans med andra krafter, härdar kall sten och ger tillvaron värme och mening.",al={"braldirs syn på eld","eldens betydelse i loch modan","dvärgarnas eldfilosofi"}}},fp="12,263,21.387.0,31.422.0,23.387.0,36.157.0,25.144.0,21.164.0,28.119.0,47.147.0,52.193.0"}
P.entries["quest:94467"] = {n="Call of Fire",s="Call of Fire är ett elementärt prov där en novis dricker en tillredd sapta för att uppfatta och möta en mindre manifestation av eld. Genom att kuva anden och lägga dess glöd i den heliga eldfatet vinner den sökande lågans gunst.",h="Call of Fire är ett elementärt prov där en novis dricker en tillredd sapta för att uppfatta och möta en...",kw={"eldfat","call of fire","fire sapta","glowing ember","mindre manifestation av eld","schamanprov","shrine of eternal flame"},ang={["class:Shaman"]="Ett grundläggande prov för schamaner som söker gemenskap med elden. Det kräver en helig sapta för att uppfatta och möta lågornas andar."},sec={{t="Eldens rit",b="Call of Fire är ett traditionellt prov på ande och mod. Vägledd av elementär kunskap får en novis en tillredd Fire Sapta som väcker sinnena för den osynliga världen. När novisen dricker brygden vid helgedomen och går upp mot toppen blir gränsen mellan dödliga ögon och urkrafter allt tunnare, och en slumrande eldmanifestation visar sig, redo att utmanas."},{t="Möte med manifestationen",b="Mötet med den mindre manifestationen av eld prövar både beslutsamhet och uthållighet. Elementarande angriper inte utan anledning, men när den utmanas växer dess styrka för varje ögonblick. När den besegras lämnar den efter sig glödande kol, som måste föras till eldfatet högst upp vid Shrine of Eternal Flame för att tända facklan och vinna andens varaktiga gunst."}},faq={{q="Vad är Call of Fire?",a="Call of Fire är en helig övergångsrit där en novis dricker en särskilt tillredd Fire Sapta för att uppfatta en eldande, möter den i strid och offrar dess glödande kol i ett eldfat för att vinna eldens gunst.",al={"vad är call of fire","call of fire-uppdraget","eldtotemets prov"}},{q="Vad är syftet med Fire Sapta?",a="Fire Sapta är en tillredd brygd som öppnar novisens andliga syn och låter hen se elementaranden som väntar på bergstoppen.",al={"fire sapta syfte","varför dricka sapta","vad gör sapta"}},{q="Vilken ande visar sig under provet?",a="Provet kräver att novisen möter en mindre manifestation av eld på toppen, som väntar med att strida tills den blir träffad.",al={"vilken ande ska jag strida mot","call of fire-varelse","eldmanifestation"}},{q="Varför måste eldanden besegras snabbt?",a="Elementaranden blir allt vildare och hetare ju längre striden pågår. Därför är ett snabbt och avgörande slag avgörande för att kuva den innan lågorna blir övermäktiga.",al={"varför ska man slå snabbt","call of fire-striden","eldandens tidsgräns"}},{q="Vad gör man med de glödande kolen?",a="När den mindre manifestationen av eld har besegrats bärs dess glödande kol till eldfatet högst upp vid Shrine of Eternal Flame för att tända ritualfacklan.",al={"vart förs kolen","call of fire-eldfat","eldfatet vid shrine of eternal flame"}},{q="Vad innebär det att vinna eldens gunst?",a="När ritualen fullbordas och facklan tänds vinner man eldelementarernas direkta gunst och gemenskap och knyter ett viktigt band till lågorna.",al={"vad är belöningen","vad ger ritualen","eldens gunst"}}},fp="12,165,17.289.0,24.311.0,25.159.0,38.135.0,37.96.0,45.150.0,37.157.0,40.124.0"}
P.entries["quest:94468"] = {n="Call of Fire",s="Call of Fire är en helig övergångsrit där en novis hämtar Torch of Eternal Flame från en utsiktsplats ovanför Loch Modan och bär den till Dun Morogh. När resenären återlämnar lågan till mentorn Bruegs Kindleborn visar det att hen behärskar elementen och förtjänar sin Fire Totem.",h="Call of Fire är en helig övergångsrit där en novis hämtar Torch of Eternal Flame från en utsiktsplats ovanför...",kw={"bruegs kindleborn","call of fire","dun morogh","fire totem","lågfödd","loch modan","schaman","torch of eternal flame"},ang={["class:Shaman"]="Den här riten fullbordar eldens prov för blivande schamaner i Khaz Modan och ger dem den Fire Totem som krävs för att kanalisera lågor och stå i förbindelse med eldandarna.",["faction:Alliance"]="När andliga kallelser slår rot i Alliansens områden i Khaz Modan vägleder mästare som Bruegs Kindleborn nya noviser i elementens konster.",["race:Dwarf"]="Att bära lågan från höjderna ovanför Loch Modan ned till Dun Morogh speglar de starka banden mellan dvärgarnas andliga sökare och krafterna i deras bergshem."},sec={{t="Lågan över sjön",b="Call of Fire markerar ett avgörande ögonblick i novisens förbindelse med elementen. Högt uppe på en bergsrygg, där vinden viner över höjderna, tänder novisen Torch of Eternal Flame med utsikt över Loch Modan. Den dansande lågan speglar en ande som vaknar och väcker en elementär iver som måste vårdas och bäras tryggt nedför stigarna till Dun Moroghs snöiga dalar."},{t="Lågföddas belöning",b="I Dun Morogh väntar Bruegs Kindleborn, en elementmentor som avgör om resenärens inre eld verkligen har fått fäste. När novisen visar upp den brinnande facklan bevisar hen sin vilja och vördnad inför elden. Kindleborn hyllar novisen som lågfödd och skänker hen en Fire Totem, vilket upptar hen i en släktlinje av elementär vägledning för de sina."}},faq={{q="Vad är Call of Fire?",a="Call of Fire är ett andligt prov för schamaner i Khaz Modan. Efter att ha tänt Torch of Eternal Flame vid en fyrfat med utsikt över Loch Modan måste novisen bära den brinnande lågan genom bergen tillbaka till Bruegs Kindleborn i Dun Morogh.",al={"vad är call of fire","uppdraget call of fire","vad gör man i call of fire"}},{q="Vem är Bruegs Kindleborn?",a="Bruegs Kindleborn är en mentor och elementär vägvisare som bor i Dun Morogh. Han vakar över eldens elementriter och ger noviser som klarar färden sin Fire Totem.",al={"vem är bruegs kindleborn","var finns bruegs kindleborn","bruegs kindleborns plats"}},{q="Vad är Torch of Eternal Flame?",a="Torch of Eternal Flame är en helig ceremoniell fackla som tänds vid ett fyrfat med utsikt över Loch Modan. Den står för novisens inre förbindelse med elementär eld och måste bäras tryggt tillbaka till Bruegs Kindleborn i Dun Morogh.",al={"vad är torch of eternal flame","torch of eternal flame","var får man facklan"}},{q="Vad får du när du klarar provet?",a="När du tryggt har lämnat Torch of Eternal Flame till Bruegs Kindleborn erkänner mentorn din brinnande ande och ger dig din Fire Totem, som tecken på att du är lågfödd.",al={"vilken belöning ger call of fire","får man fire totem","call of fire totem"}},{q="Var äger resan rum?",a="Resan börjar vid en utsiktsplats med utsikt över Loch Modan, där facklan tänds, och följer bergsstigen tillbaka till Dun Moroghs snöiga trakter för att möta Bruegs Kindleborn.",al={"var utspelar sig call of fire","call of fire färdväg","vart ska facklan bäras"}},{q="Varför nämner Bruegs Madoran?",a="Bruegs svär ”Vid Madorans skägg” och syftar på Madoran Bronzebeard, den vördade dvärgaledare som ledde Bronzebeard-klanen under De tre hammarnas krig.",al={"varför säger han vid madorans skägg","madorans betydelse","vem är madoran som bruegs nämner"}}},fp="12,162,23.241.0,22.320.0,25.218.0,25.156.0,35.200.0,47.173.0,35.148.0,32.169.0"}
P.entries["quest:94480"] = {n="A Gift From Our Enemies",s="Gorg ber dig ta med stulet foder till Rog'mar så att dess allierade får mat. Närliggande gnoller och den framryckande Twilight hotar bosättningen.",h="Gorg ber dig ta med stulet foder till Rog'mar så att dess allierade får mat.",kw={"allierade","gård","gnoller","gorg","mustig gryta","rog'mar","stulet foder","twilight"},sec={{t="Mat till Rog'mar",b="Gorg väntar i Rog'mar på det stulna foder du samlat ihop. Människorna är inte det enda hotet i närheten: gnoller morrar från kullarna och Twilight tränger sig närmare. Att hålla Rog'mars allierade mätta kan hjälpa dem att bevara sin styrka."},{t="En mustig gryta",b="Fodret luktar starkt och jordigt, med något obehagligt under doften. Gorg känner igen att du tog det från gården och säger att det blir en mustig gryta åt de allierade."}},faq={{q="Varför vill Gorg ha det stulna fodret?",a="Gorg ska använda det stulna fodret till att laga en mustig gryta åt Rog'mars allierade.",al={"varför foder","gorg foder","vad ska det stulna fodret användas till"}},{q="Vilka hot finns nära Rog'mar?",a="Människorna är ett hot, medan gnoller morrar från närliggande kullar och Twilight tränger sig närmare.",al={"gnoller i närheten","hot från twilight","vad finns nära rog'mar"}},{q="Vem är Gorg?",a="Gorg tar emot det stulna fodret i Rog'mar och säger att det kan bli en mustig gryta.",al={"vem är gorg"}},{q="Var ska jag lämna det stulna fodret?",a="Lämna det stulna fodret till Gorg i Rog'mar.",al={"foder plats","var lämna fodret","gorg plats"}}},fp="23,139,16.224.0,13.177.1,35.73.0,30.92.0,12.91.0,32.40.0"}
P.entries["quest:94484"] = {n="Unnerving Silence",s="Unnerving Silence handlar om att en druideenklav i en grotta i nordöstra Shadowgale Forest plötsligt har slutat höra av sig. Efter Ban'aethalls förstörelse och den ökande oron i området skickas en utredare för att hitta Elegael Thornpaw och ta reda på vad som hänt enklaven.",h="Unnerving Silence handlar om att en druideenklav i en grotta i nordöstra Shadowgale Forest plötsligt har...",kw={"ban'aethall","druid","druideenklav","elegael thornpaw","shadowgale forest","unnerving silence"},ang={["class:Druid"]="Den förlorade kontakten med en avskild enklav i Shadowgale Forest väcker omedelbar oro hos druider som är lyhörda för vildmarkens balans. Att undersöka varför Elegael Thornpaw tystnat handlar om att skydda sina fränder och ta reda på vad som har stört deras gemenskap."},sec={{t="Tystnad i trädkronorna",b="En stilla oro vilar över vildmarken efter Ban'aethalls fall. Byn ligger i ruiner och en mystisk oro sprider sig genom området, samtidigt som de etablerade kontaktvägarna börjar brytas. Särskilt har de regelbundna rapporterna från en avskild druideenklav, djupt inne i en grotta i nordöstra Shadowgale Forest, plötsligt upphört. Det gör deras allierade oroliga."},{t="På jakt efter enklaven",b="Resenärer på väg mot Shadowgale Forest får i uppdrag att leta reda på Elegael Thornpaw, en framstående person bland druiderna som bor i grottan. En utredare måste ta sig in i det skuggiga nordöstra området och ta reda på om enklaven bara har dragit sig undan för att fördjupa sin gemenskap med naturen eller fallit offer för samma faror som härjade i Ban'aethall."}},faq={{q="Vad handlar uppdraget Unnerving Silence om?",a="Unnerving Silence är ett uppdrag att undersöka varför en druideenklav i Shadowgale Forest plötsligt har slutat höra av sig. En orolig person ber resenärer som ska åt det hållet att leta i en grotta i nordost och ta reda på vad som hänt den avskilda gruppen.",al={"uppdraget unnerving silence","vad är unnerving silence"}},{q="Var finns Elegael Thornpaw?",a="Elegael Thornpaw finns i en grotta i den nordöstra delen av Shadowgale Forest. Hon är kontaktpersonen för den avskilda druideenklav som håller till där.",al={"var finns elegael thornpaw","elegael thornpaws plats","hitta thornpaw"}},{q="Vem är Elegael Thornpaw?",a="Elegael Thornpaw tillhör druideenklaven som bor i en grotta i nordöstra Shadowgale Forest. Hennes långvariga tystnad och uteblivna rapporter har väckt allvarlig oro för enklavens säkerhet.",al={"vem är elegael thornpaw","thornpaws bakgrund"}},{q="Vad är Shadowgale Forest?",a="Shadowgale Forest är ett skogsområde med en dold druideenklav i en grotta i nordost. Efter den omfattande oron i området och Ban'aethalls fall har kontakten med skogens invånare blivit oroväckande osäker.",al={"vad är shadowgale forest","shadowgale forests druideenklav"}},{q="Vad är Ban'aethall?",a="Ban'aethall var en by djupt inne i Shadowgale Forest som nyligen ödelagts. Förstörelsen och den större oron i området har ökat rädslan för att närliggande läger, som Shadowgale-enklaven, också kan vara i fara.",al={"vad hände med banaethall","banaethalls ruiner","ban'aethalls fall"}},{q="Varför har druideenklaven tystnat?",a="Druidernas schemalagda meddelanden och rapporter från Shadowgale Forest har upphört utan förklaring. Med tanke på Ban'aethalls förstörelse och de ökande spänningarna i området finns det allvarlig oro för att en katastrof eller fientliga styrkor har drabbat dem.",al={"varför slutade druiderna skicka meddelanden","varför är druiderna tysta"}}},fp="17,142,21.259.0,19.271.0,42.188.0,36.131.0,24.183.0,26.223.0,20.193.0,39.222.0"}
P.entries["quest:94485"] = {n="Tears of the Lady",s="Tears of the Lady är ett akut hjälp­uppdrag åt Elegael i Shadowgale Forest. För att behandla sårade kamrater som blivit kvar i Nightclaw Den måste resenärer söka igenom trädstammar i närheten efter Lady's Tear, en antiseptisk mossa som är livsviktig för att förbinda svåra sår.",h="Tears of the Lady är ett akut hjälp­uppdrag åt Elegael i Shadowgale Forest.",kw={"elegael","lady's tear","mossa","nightclaw den","grötomslag","shadowgale forest","tears of the lady"},ang={["class:Priest"]="Präster kanaliserar Ljuset för att läka livshotande skador, men naturliga grötomslag som Lady's Tear är viktiga fysiska förband för sårade överlevande när den magiska hjälpen inte räcker till.",["profession:Herbalism"]="Örtkunniga och fältläkare värdesätter Lady's Tear för dess klibbiga, antiseptiska sekret, som snabbt kan förbinda öppna sår och förebygga infektion i nödsituationer ute i vildmarken."},sec={{t="Desperata botemedel i Shadowgale",b="I Shadowgales skuggiga djup söker Elegael akut hjälp med att behandla följeslagare som är instängda i Nightclaw Den. Svårt skadade allierade väntar på räddning, men vanliga förnödenheter saknas. Därför måste läkemedel samlas direkt från den omgivande vildmarken. Allt hänger på att hitta naturliga botemedel innan tiden rinner ut för dem som lämnats kvar."},{t="Den läkande mossan",b="Den viktigaste ingrediensen i Elegaels planerade grötomslag är Lady's Tear, en spinkig mossa som klamrar sig fast vid trädens baser runtom i Shadowgale Forest. Växten utsöndrar ett trögflytande, klibbigt sekret med naturligt antiseptiska egenskaper. Det kan försegla öppna sår och skydda svåra skador från att förvärras i den fuktiga vildmarken. Om Elegael får tillräckligt med mossa kan hen förbereda förbanden som behövs för att stabilisera de fallna."}},faq={{q="Vad handlar uppdraget Tears of the Lady om?",a="Tears of the Lady är en räddningsinsats som leds av Elegael i Shadowgale Forest. Sårade kamrater är fortfarande instängda i Nightclaw Den, och Elegael behöver växter från trakten för att göra ett akut grötomslag och hålla dem vid liv.",al={"vad är tears of the lady","information om uppdraget tears of the lady"}},{q="Vad är Lady's Tear?",a="Lady's Tear är en spinkig mossa som växer nära trädens baser i skogarna kring Shadowgale Forest. Den utsöndrar en naturligt klibbig sav som fungerar som ett kraftfullt antiseptiskt medel och därför passar utmärkt för att lägga om och förbinda öppna sår.",al={"vad är ladys tear","ladys tear-mossa","vad är lady's tear-mossa"}},{q="Vem är Elegael?",a="Elegael är den överlevande som organiserar sjukvårdsinsatsen i Shadowgale Forest. Elegael lämnade sårade följeslagare i Nightclaw Den och samlar nu in medicinalväxter för att förbereda behandlingar innan hen återvänder för att hjälpa dem.",al={"vem är elegael","uppdragsgivare för tears of the lady"}},{q="Vad är Nightclaw Den?",a="Nightclaw Den är en plats nära Shadowgale Forest där flera av Elegaels skadade allierade har blivit kvar. Deras tillstånd är kritiskt, vilket gör det brådskande att samla in läkande ingredienser.",al={"vad är nightclaw den","var ligger nightclaw den"}},{q="Varför behöver Elegael Lady's Tear-mossa?",a="Mossan ger ett viktigt antiseptiskt sekret som behövs för att blanda till ett medicinskt grötomslag. Det klibbiga ämnet förseglar öppna sår och motverkar infektion hos de överlevande som lämnats kvar i hålan.",al={"varför behövs ladys tear","vad gör mossan"}},{q="Var hittar man Lady's Tear-mossa?",a="Lady's Tear-mossa klamrar sig vanligtvis fast vid trädens baser runtom i Shadowgale Forest. Elegael samlade in det som fanns inom räckhåll, men mer måste hämtas i skogarna runt omkring.",al={"var växer ladys tear","hitta ladys tear"}}},fp="17,157,32.238.0,16.312.0,42.164.0,20.178.0,15.135.0,26.156.0,39.165.0,32.153.0"}
P.entries["quest:94486"] = {n="Feathers for Binding",s="Feathers for Binding är ett uppdrag i Shadowgale Forest där du samlar isolerande fjädrar från unga skriklingar för att göra ett skyddande läkande omslag. Dessa vanligtvis fogliga varelser har blivit farligt aggressiva, men deras fjädrar behövs fortfarande för att skydda antiseptiska salvor mot väder och vind. Äventyrare måste trotsa de fientliga ungarna för att säkra material till traktens vård.",h="Feathers for Binding är ett uppdrag i Shadowgale Forest där du samlar isolerande fjädrar från unga...",kw={"antiseptisk saft","feathers for binding","läkande omslag","shadowgale forest","shadowgale-skrikling","skrikling","skriklingar"},ang={["class:Druid"]="Druider kan känna sorg tillsammans med uppdragsgivaren över att unga skogsdjur måste dödas, även när den ökande aggressiviteten och det akuta medicinska behovet lämnar få andra alternativ.",["profession:Herbalism"]="Örtkunniga och naturhelare kan uppskatta den noggranna avvägningen mellan mossa, antiseptisk trädsaft och isolerande fjädrar när man skapar ett effektivt fältförband eller läkande omslag."},sec={{t="Skogens läkande medel",b="I Shadowgale Forests djup kräver förberedelser av fältmedicin ofta uppfinningsrikedom och kunskap om naturens resurser. Vid behandling av svåra skador använder örtkunniga och läkare ett särskilt omslag av mossa och antiseptisk trädsaft. För att hindra saften från att torka snabbt eller förlora sin verkan i hårt väder behövs slitstarka, isolerande bindor. De unga Shadowgale-skriklingarnas fjädrar utgör ett utmärkt naturligt skydd. De täcker såret och håller läkemedlet på plats."},{t="Oväntad fientlighet",b="Det har oväntat blivit farligt att skaffa de duniga fjädrarna. Vanligtvis är unga Shadowgale-skriklingar fogliga skogsvarelser. På sistone har de dock blivit oförklarligt mycket mer aggressiva. De här unga rovdjuren anfaller nu förbipasserande med kraftiga klor som kan orsaka dödliga skador. För att samla fjädrarna måste äventyrare möta varelser som förvandlats från harmlösa ungar till verkliga faror."},{t="En beklaglig nödvändighet",b="De lokala vårdarna känner stor tyngd när de ber resenärer att jaga unga varelser, och sörjer öppet att det blivit nödvändigt att gallra bland dem. Men eftersom flera nödlägen hotar trakten och bestarna blir allt farligare, fyller jakten ett dubbelt syfte: att samla viktiga läkemedelsmaterial och hejda ett växande hot mot skogsstigarna. Varje insamlad fjäder behandlas med respekt, så att deras offer inte blir förgäves."}},faq={{q="Varför behövs Shadowgale-skriklingarnas fjädrar till omslaget?",a="Fjädrarna från unga Shadowgale-skriklingar har naturligt isolerande egenskaper. När de läggs ovanpå ett lager mossa fungerar de som ett skyddande bandage. Det hindrar antiseptisk saft från att torka och skyddar såret mot hårt väder.",al={"fjädrarnas syfte","varför skriklingsfjädrar","fjädrar till omslag"}},{q="Hur farliga är de unga skriklingarna?",a="Shadowgale-skriklingar är vanligtvis fogliga, men på sistone har de blivit ovanligt fientliga. Trots sin unga ålder har de stora, vassa klor som kan slita upp magen på en oförsiktig resenär.",al={"skriklingars farlighet","är skriklingar farliga","skriklingars aggressivitet"}},{q="Varför måste unga skriklingar jagas i stället för vuxna?",a="Uppdragsgivaren uttrycker uppriktig sorg över att unga bestar måste gallras ut. Men eftersom de plötsligt blivit mycket mer fientliga och flera akuta problem i vildmarken måste hanteras, anses det vara en smärtsam nödvändighet att minska deras antal och samla in behövda läkemedel.",al={"varför döda unga skriklingar","döda unga skriklingar"}},{q="Var hittar man Shadowgale-skriklingarna?",a="Shadowgale-skriklingarna rör sig bland trädkronorna och i snåren i Shadowgale Forest. Resenärer måste vara försiktiga när de tar sig genom skogen för att spåra upp dem.",al={"var ligger shadowgale forest","skriklingars plats","var finns skriklingar"}},{q="Vilka andra ingredienser används tillsammans med fjädrarna?",a="Omslaget består av lokal mossa och antiseptisk saft. Sedan binds och isoleras det med duniga fjädrar från unga skriklingar.",al={"ingredienser i omslaget","vad innehåller omslaget"}},{q="Varför har skriklingarna blivit så fientliga på sistone?",a="Det är oklart exakt vad som orsakat deras plötsliga fientlighet, men de unga varelserna, som vanligtvis är fridsamma, har blivit ovanligt aggressiva. Det lägger ännu en kris till dem som de lokala vårdarna måste hantera.",al={"varför är skriklingar arga","orsaken till skriklingars aggressivitet"}}},fp="20,179,22.275.0,26.255.0,23.313.0,63.166.0,43.170.0,58.225.0,43.142.0,63.106.0,50.175.0"}
P.entries["quest:94487"] = {n="Unwanted and Unworthy",s="Unwanted and Unworthy är ett uppdrag på Zephras där äventyrare hjälper Elegael att hämnas på Al'Aketh Cultists efter ett blodigt bakhåll i Shadowgale Forest. Genom att dräpa kultisterna och återta stulna arvegods hämnas spelarna fallna druider och återtar heliga släktreliker åt High Elder.",h="Unwanted and Unworthy är ett uppdrag på Zephras där äventyrare hjälper Elegael att hämnas på Al'Aketh...",kw={"al'aketh","blodbestänkta arvegods","elegael","footsoldiers","arvegods","shadowgale forest","shen'dorei","stormchasers","zephras"},ang={["class:Druid"]="Al'Aketh Cultists spillde lokala druider blod under sitt oprovocerade angrepp på Zephras, vilket gör denna attack till en direkt hämndaktion och ett försvar av naturens balans."},sec={{t="Bakhåll i Shadowgale Forest",b="Zephras fredliga balans rubbades plötsligt när Al'Aketh Cultists överraskade de lokala druiderna med ett bakhåll i Shadowgale Forest. Elegael hade tidigare avfärdat dessa fanatiker som ofarliga drömmare med ”moln mellan öronen”, men överrumplades av attackens rena brutalitet. Druidernas blod rann över skogsmarken, och kravet på snabb vedergällning riktades mot Footsoldiers och Stormchasers som låg bakom."},{t="Besudlade arvegods och förlorad ungdom",b="För Elegael fråntog kultisternas förräderi dem deras arv: de förtjänar inte längre att kallas shen'dorei, och deras kvarlevor förtjänar inte heller hemlandets vindar. Många av kultisterna var unga och hade lovande framtider, men fanatismen satte stopp för dem. Genom att återta deras blodbestänkta arvegods hjälper äventyrarna till att se till att dessa heliga föremål återlämnas till High Elder, där de väntar på en visare och mer värdig generation."}},faq={{q="Vilka är Al'Aketh Cultists?",a="Al'Aketh Cultists är stormbesatta kultister som verkar på ön Zephras. Enligt Elegael betraktades de en gång som bara dåraktiga, eller som personer med ”moln mellan öronen”, men de tog plötsligt till brutalt våld mot de lokala druiderna.",al={"vilka är alaketh","alaketh-kulten","vilka är kultisterna"}},{q="Vem är Elegael?",a="Elegael är en beskyddare eller druid av shen'dorei-folket med anknytning till Zephras, som överfölls av Al'Aketh Cultists. Upprörd över förräderiet och blodspillan bland unga söker Elegael vedergällning och vill återta de stulna släktklenoderna.",al={"vem är elegael","uppdragsgivaren elegael"}},{q="Vad är de blodbestänkta arvegodsen?",a="De blodbestänkta arvegodsen tillhörde unga shen'dorei som drogs in i Al'Aketh Cult. Elegael samlar in dem så att de en dag kan återlämnas till High Elders samling och gå vidare till en mer värdig framtida generation.",al={"blodbestänkta arvegods","varför samla arvegods","vad är arvegodsen"}},{q="Vilka är shen'dorei?",a="Shen'dorei är folket som bor på Zephras. Elegael anser att de förrädiska Al'Aketh Cultists har förverkat sin rätt att kallas shen'dorei genom sitt våldsamma förräderi och sin kränkning av öns harmoni.",al={"shen'dorei betydelse","vilka är shen'dorei"}},{q="Var ligger Shadowgale Forest?",a="Shadowgale Forest är ett skogsområde på Zephras där Al'Aketh Footsoldiers och Stormchasers håller till och där det oprovocerade bakhållet mot druiderna ägde rum.",al={"shadowgale forest läge","var ligger shadowgale"}},{q="Varför överföll Al'Aketh Cultists druiderna?",a="Kultisternas exakta motiv är ett oroande mysterium för Elegael. De hade länge avfärdats som ofarliga fanatiker, men deras plötsliga och våldsamma uppror krossade den sköra balansen på ön.",al={"varför anföll kultisterna","kultisternas motiv","varför överföll de druiderna"}}},fp="21,124,27.286.0,32.360.0,30.198.0,15.244.0,32.200.0,24.189.0,27.146.0,48.174.0"}
P.entries["quest:94488"] = {n="The Ties That Bind",s="The Ties That Bind är ett uppdrag i Shadowgale Forest som kretsar kring ett bittert svek inom druidkretsen. Elegael Thornpaw upptäcker att Haalien, en druid från kretsen som varit försvunnen, har anslutit sig till de anfallande kultisterna som befälhavare och beordrar hans avrättning. Uppdraget visar pliktens smärtsamma personliga pris när familjen vänder sig mot sina egna.",h="The Ties That Bind är ett uppdrag i Shadowgale Forest som kretsar kring ett bittert svek inom druidkretsen.",kw={"cenarion circle","befälhavaren haalien","kultister","druid","elegael thornpaw","haalien","shadowgale forest","the ties that bind"},ang={["class:Druid"]="Cenarion Circle håller bevarandet av balans och släktskap heligt. Därför är Haaliens svek och blodspillan bland andra druider i kretsen ett särskilt allvarligt brott mot ordningen."},sec={{t="Svek i skogen",b="I djupet av Shadowgale Forest möter druider en hänsynslös kultistnärvaro som sprider skräck och blodspillan. För Elegael Thornpaw förvärras angreppet av en bitter upptäckt: doften av en tidigare druid från kretsen, Haalien, hänger över slakten. Haalien försvann flera månader tidigare, men dog inte i vildmarken. I stället slöt han upp med de invaderande kultisterna och tog befälet över deras våldsamma fälttåg mot sina tidigare fränder."},{t="Blod och släktskap",b="Haalien svek mer än sina löften till Cenarion Circle. När den fallne befälhavarens avhuggna huvud visas upp avslöjar Elegael att Haalien var hennes egen kusin. Hon rasar över hans grymheter, men att själv döda en släkting blev en alltför tung börda att bära ensam. Hans död sätter ett blodigt slut på en avfälling vars ondska kostade många oskyldiga livet."}},faq={{q="Vem erbjuder uppdraget The Ties That Bind?",a="Elegael Thornpaw är en druid stationerad i Shadowgale Forest. Med kultisternas intrång att hantera skickar hon äventyrare för att jaga befälhavaren Haalien, efter att ha upptäckt hans del i blodbadet.",al={"vem ger the ties that bind","uppdragsgivare i shadowgale","vem är elegael thornpaw"}},{q="Vem är befälhavaren Haalien?",a="Befälhavaren Haalien var tidigare en druid i Cenarion Circle som försvann flera månader innan kultistangreppen. Han föll inte offer för det annalkande mörkret, utan anslöt sig frivilligt till de fientliga kultisterna och steg i graderna tills han ledde deras styrkor mot sina fränder.",al={"vem är haalien","befälhavaren haalien bakgrund","haalien bakgrund"}},{q="Varför vill Elegael att befälhavaren Haalien ska dö?",a="Haalien övergav sin druidkrets och tog befälet över kultister som slaktade oskyldiga och spillde sina bröders blod. På grund av hans handlingar och hotet han utgör mot skogen beordrar Elegael hans avrättning.",al={"varför döda haalien","haaliens brott","vad gjorde haalien"}},{q="Vilken koppling finns mellan Elegael Thornpaw och Haalien?",a="Befälhavaren Haalien är Elegael Thornpaws kusin. Hon är djupt rasande över hans brott, men medger att det skulle ha varit en bitter börda att själv avrätta sin egen släkting. Därför ber hon en äventyrare om hjälp.",al={"är elegael och haalien släkt","hur känner elegael och haalien varandra"}},{q="Varför finns det kultister i Shadowgale Forest?",a="De lokala druiderna kan inte heller förstå kultisternas exakta motiv för att vara i Shadowgale Forest. Men deras styrkor leds av före detta medlemmar av kretsen, som Haalien, som riktade våld och blodspillan mot skogens försvarare.",al={"kultister i shadowgale forest","varför finns kultister i shadowgale"}},{q="Var utspelar sig uppdraget?",a="Uppdraget utspelar sig i Shadowgale Forest, där Elegael Thornpaw undersöker kultisternas invasion och konfronteras med den dystra verkligheten i sin kusins svek.",al={"var utspelar sig the ties that bind","shadowgale forest plats"}}},fp="18,192,22.310.0,17.349.1,40.171.0,25.191.0,45.206.0,60.166.0,50.198.0,33.133.0"}
P.entries["quest:94489"] = {n="The Wounds of Betrayal",s="The Wounds of Betrayal är ett uppdrag i Shadowgale Forest som skildrar följderna av ett tragiskt överfall mot de sällsynta shen'dorei-druiderna. Elegael skickar dig med brådskande omslag till sina sårade fränder i Nightfang Den och för att leta efter hennes försvunna partner, Jorel Windsinger. Uppdraget blottlägger snart svekets bittra pris och driver på en hämndlysten konflikt mot Al'Aketh.",h="The Wounds of Betrayal är ett uppdrag i Shadowgale Forest som skildrar följderna av ett tragiskt överfall mot...",kw={"al'aketh","druid","elegael","jorel windsinger","nightfang den","shadowgale forest","shen'dorei","the wounds of betrayal"},ang={["class:Druid"]="Som druider som vårdar vildmarken känns det tungt och personligt när andra druider, särskilt de fåtaliga shen'dorei-druiderna, faller offer för svek och svåra skador.",["race:NightElf"]="Nattalver vördar druiderna traditioner. Därför berör lidandet bland besläktade druider i Shadowgale Forest och kampen mot förräderi dem djupt."},sec={{t="Hjälp åt shen'dorei",b="The Wounds of Betrayal börjar med Elegael, en shen'dorei-druid som tar hand om följderna av ett katastrofalt överfall i Shadowgale Forest. Hon har hastigt förberett medicinska omslag och söker desperat en äventyrare som kan föra hjälp till hennes fränder, som tagit skydd i närbelägna Nightfang Den, strax norrut på andra sidan gläntan. Shen'dorei-druiderna är ytterst få, så varje enskild medlems överlevnad är avgörande för deras utsatta gemenskap."},{t="Sökandet efter Jorel Windsinger",b="Utöver att ge de sju illa tilltygade druiderna i grottan akut vård bär Elegael på en personlig vädjan: att hitta sin partner, Jorel Windsinger. När hon flydde striderna för att förbereda mediciner kämpade Jorel redan för sitt liv. En färd in i Nightfang Dens mörka skrymslen avslöjar den verkliga förödelse som drabbat tillflyktsorten och Jorels dystra öde."},{t="Ett löfte om vedergällning",b="När Elegael får höra om Jorels tragiska slut och det fruktansvärda priset hennes fränder fått betala brister hennes behärskning i sorg och vrede. Med sammanbitna tänder och ett smärtfyllt morrande förkastar hon förtvivlan till förmån för ren vedergällning. Hon svär att alla som är allierade med de skuggfyllda Al'Aketh ska få känna hennes obevekliga vrede för slakten på hennes folk."}},faq={{q="Vem ger uppdraget The Wounds of Betrayal?",a="Uppdraget ges av Elegael, en shen'dorei-druid som desperat försöker ta hand om sina sårade fränder efter ett våldsamt angrepp i Shadowgale Forest.",al={"vem ger the wounds of betrayal","uppdragsgivare the wounds of betrayal","vem är elegael"}},{q="Var ligger Nightfang Den?",a="Nightfang Den är en grotta strax norrut på andra sidan gläntan i Shadowgale Forest. Där har skadade shen'dorei-druider dragit sig tillbaka för att söka skydd.",al={"var ligger nightfang den","nightfang den plats","var finns de sårade druiderna"}},{q="Vem är Jorel Windsinger?",a="Jorel Windsinger är Elegaels partner. Han skadades svårt i angreppet och stannade i Nightfang Den, där spelaren upptäcker hans tragiska öde.",al={"vem är jorel windsinger","jorel windsingers öde","var är jorel"}},{q="Vad är shen'dorei-druiderna?",a="Shen'dorei är en sällsynt grupp med mycket få druider. Eftersom de är så få betonar Elegael att varje överlevande liv bland dem är dyrbart.",al={"vad är shendorei","vilka är shendorei-druiderna","shen'dorei-druidernas historia"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är fiender som ligger bakom, eller är allierade med dem som angrep druiderna. När Elegael får veta Jorels öde och hur hennes orden ödelagts svär hon att hämnas på Al'Aketh och alla deras allierade.",al={"vilka är al'aketh","al'aketh","varför hatar elegael al'aketh"}},{q="Vad händer Jorel Windsinger under uppdraget?",a="När du hittar Jorel Windsinger i hålan upptäcker du att hans tillstånd har tagit en tragisk vändning. När du återvänder till Elegael med besked om hans öde och de överlevande druidernas svåra belägenhet drabbas hon av sorg och svär ursinnigt att hämnas.",al={"vad händer jorel windsinger","överlever jorel","jorels öde"}}},fp="22,202,22.265.0,31.307.1,20.247.2,43.111.0,31.123.0,24.120.0,31.101.0,21.214.0,46.206.0"}
P.entries["quest:94490"] = {n="Ripped Missive",s="Ripped Missive är ett blodbestänkt brev som hittades på Haalien och avslöjar en brutal kultistattack mot en druidehåla i Shadowgale Forest. Innehållet blottlägger de hänsynslösa motiven bakom massakern och antyder farlig omstörtning inifrån Valanaar.",h="Ripped Missive är ett blodbestänkt brev som hittades på Haalien och avslöjar en brutal kultistattack mot en...",kw={"kultist","druidehåla","elegael thornpaw","haalien","lotheluum","pylon","ripped missive","shadowgale forest","valanaar"},ang={["class:Druid"]="Druider kommer att finna en bitter tragedi i brevet: druiderna i hålan slaktades bara för att de stod i vägen för kultister som sökte efter en forntida pylon."},sec={{t="Blodbestänkta order",b="Det här sönderrivna och blodbestänkta dokumentet låg gömt bakom Haaliens armskena och innehåller mörka upplysningar om det senaste våldet i Shadowgale Forest. Det hittades efter en våldsam strid och kastar ljus över kultisternas mörka avsikter när de anföll den lokala druidehålan. Brevet ger viktiga ledtrådar åt den som söker rättvisa för de fallna."},{t="Meningslös massaker",b="När du visar pergamentet för Elegael Thornpaw i Shadowgale Forest kommer den fruktansvärda sanningen om räden fram. Kultisterna angrep inte druiderna på grund av någon särskild fejd. De sökte efter en mystisk pylon och mördade hålans invånare enbart för att de stod i vägen. Elegael rasar över den meningslösa massakern och svär att hämnas på alla kultister som finns kvar i skogen."},{t="Förräderi i Valanaar",b="Brevet avslöjar inte bara att kultisterna sökte efter pylonen, utan också något långt mer oroande: ordern verkar ha kommit från själva Valanaar. Denna dystra insikt pekar på en förrädare i bosättningen. För att avslöja konspirationen innan fler liv går förlorade måste brevet genast föras till Lotheluum i Valanaar."}},faq={{q="Vad är Ripped Missive?",a="Ripped Missive är ett sönderrivet, blodbestänkt brev som hittades instucket bakom Haaliens armskena efter en strid. Det innehåller viktiga upplysningar som avslöjar motiven bakom kultisternas attack mot en druidehåla i Shadowgale Forest.",al={"vad är ripped missive","uppdraget ripped missive","blodbestänkt brev haalien"}},{q="Var hittades brevet?",a="Brevet hittas direkt på Haalien, instucket bakom en av deras armskenor efter en våldsam konfrontation. Det skadades och fläckades av blod under striden.",al={"vem släppte ripped missive","var kom ripped missive ifrån","vem är haal ien"}},{q="Vem ska få Ripped Missive?",a="Brevet lämnas först till Elegael Thornpaw i Shadowgale Forest. När Elegael har läst det ger hen dig i uppdrag att snabbt lämna det till Lotheluum i Valanaar för att varna för ett möjligt förräderi.",al={"vem vill ha ripped missive","vem ska jag ge ripped missive till","elegael thornpaw brev"}},{q="Varför angrep kultisterna druidehålan?",a="Brevet avslöjar att kultisterna inte angrep druidehålan av hat mot druiderna, utan för att lägga beslag på en pylon där. Druiderna som bodde där slaktades skoningslöst enbart för att de stod i kultisternas väg.",al={"varför angrep kultisterna druidehålan","kultisternas motiv druidehålan","varför angrep haal ien"}},{q="Varifrån kom attackordern?",a="Brevet visar att kultisternas order kom från Valanaar. Det tyder på att en förrädare döljer sig i bosättningen och styr verksamheten därifrån.",al={"varifrån kom ordern","vem skickade haal ien","förrädare i valanaar"}},{q="Vem är Lotheluum och varför måste hen underrättas?",a="Lotheluum är en kontakt i Valanaar. Elegael Thornpaw beordrar dig att ta brevet till Lotheluum och varna om att kultisternas dödliga order kan spåras till någon som gömmer sig i Valanaar.",al={"vem är lotheluum","varför ta brevet till lotheluum","lotheluum valanaar"}}},fp="14,167,19.240.0,19.260.1,21.250.2,27.155.0,36.126.0,38.158.0,42.114.0,38.96.0,47.166.0"}
P.entries["quest:94491"] = {n="The Fate of the Den",s="The Fate of the Den skildrar de dystra följderna av en kultistattack mot en avskild druidskans. En äventyrare skickas med ett återfunnet meddelande till Lotheluum i Valanaar, med nyheter om svåra förluster. Meddelandet avslöjar en djupt oroande verklighet: någon i Valanaar har försett fienden med viktig information.",h="The Fate of the Den skildrar de dystra följderna av en kultistattack mot en avskild druidskans.",kw={"kultister","druidskans","high elder","lotheluum","meddelande","the fate of the den","förrädare","valanaar"},ang={["class:Druid"]="Druider känner tyngden av den här tragedin starkt, eftersom de stupade i skansen var deras fränder och deras avskilda tillflykt förråddes till fientliga kultister."},sec={{t="Tragedin i The Den",b="Efter kultisternas våldsamma angrepp på druidskansen finner sig de överlevande försvararna tilltufsade och sörjer sina stupade kamrater. Den omedelbara krisen kunde hejdas med hjälp utifrån, men de fysiska och känslomässiga skadorna är enorma. De stupade kan inte återupplivas, och de sårade överlevande är inte i skick att ge sig ut på en lång vandring medan kultister fortfarande stryker omkring i närheten."},{t="Förräderi i Valanaar",b="Ett återfunnet meddelande bekräftar att kulten inte agerade på måfå; någon som håller sig dold i Valanaar har aktivt läckt underrättelser till dem. När Lotheluum får meddelandet uttrycker han fullständig bestörtning över slakten på sina fränder och den skrämmande insikten att en medbrottsling eller förrädare går fri i deras bosättning. Fast besluten att deras offer inte ska glömmas för han bevismaterialet direkt till High Elder."}},faq={{q="Vem är Lotheluum?",a="Lotheluum bor i Valanaar och tar emot rapporter om druidskansen. När han får veta om angreppet och granskar det återfunna meddelandet uttrycker han djup sorg över sina stupade fränder och lovar att föra bevisen på förräderiet direkt till High Elder.",al={"lotheluum","vem är lotheluum","lotheluum npc"}},{q="Vad hände i druidskansen?",a="Druidskansen utsattes för ett förödande angrepp av fientliga kultister, och många försvarare dödades. Även om hotet hejdas med hjälp av en äventyrare är de överlevande försvararna svårt tilltygade och hittar bevis för att en insider låg bakom angreppet.",al={"vad hände i skansen","angrepp på druidskansen","bakgrund till the fate of the den"}},{q="Vad avslöjar det återfunna meddelandet?",a="Meddelandet avslöjar att en kontaktperson som håller sig dold i bosättningen Valanaar i hemlighet har försett kulten med underrättelser. Informationen tyder på att den dödliga räden mot skansen möjliggjordes genom sabotage och spionage på orten.",al={"vad står det i meddelandet","meddelande från skansen","förrädarens meddelande"}},{q="Vem är High Elder som Lotheluum nämner?",a="High Elder är en framstående auktoritet i Valanaar som Lotheluum lyder under. På grund av de svåra förlusterna och hotet från en aktiv förrädare för Lotheluum genast meddelandet och nyheten om tragedin vidare till High Elder.",al={"vem är high elder","valanaars high elder","high elder"}},{q="Vem låg bakom angreppet på druidskansen?",a="Angreppet utfördes av medlemmar i en kult som verkar i området. Kultisterna lyckades tillfoga invånarna i skansen katastrofala förluster tack vare vägledning från en informatör som fått skydd i Valanaar.",al={"vem angrep skansen","vem angrep druidskansen","kultister i skansen"}},{q="Varför kunde inte den överlevande i skansen själv leverera meddelandet?",a="Den överlevande i skansen var för svårt sårad för att klara vandringen till Valanaar efter angreppet. Förutom att kroppen inte klarade resan stannade den överlevande kvar för att göra sig av med de återstående kultisterna och skickade en äventyrare för att slå larm.",al={"varför levererar vi meddelandet","uppdragsgivaren är skadad","varför kan den överlevande inte ta sig till valanaar"}}},fp="19,269,18.340.0,21.379.1,17.202.0,31.204.0,39.171.0,45.194.0,48.164.0,69.180.0"}
P.entries["quest:94493"] = {n="A Sacrifice in Vain",s="Elegael Thornpaw fruktar att Al'Aketh Cultists ska övermanna de sårade i hennes lya. Ett meddelande till Valanaar har inte nått fram, så hon måste be om hjälp.",h="Elegael Thornpaw fruktar att Al'Aketh Cultists ska övermanna de sårade i hennes lya.",kw={"a sacrifice in vain","al'aketh cultists","lya","elegael thornpaw","förstärkningar","valanaar","sårade"},sec={{t="En vädjan om hjälp",b="Al'Aketh Cultists överföll Elegael Thornpaws kamrater nästan helt utan förvarning. Många i hennes lya är sårade eller döende, och hon vet inte hur länge de kan överleva anfallet. Hon hade försökt skicka bud till Valanaar, men meddelandet nådde inte fram. Utan förstärkningar i sikte ber Elegael dig om hjälp."}},faq={{q="Vem ber om hjälp?",a="Elegael Thornpaw ber om hjälp medan Al'Aketh Cultists anfaller hennes kamrater.",al={"vem behöver hjälp","elegael thornpaw","elegael"}},{q="Vad hände med dem i lyan?",a="Al'Aketh Cultists låg i bakhåll och anföll dem nästan utan förvarning. Många är sårade eller döende.",al={"sårade i lyan","vad hände här","kultisternas anfall"}},{q="Varför skickade Valanaar inga förstärkningar?",a="Elegaels meddelande nådde inte Valanaar, så förstärkningarna har inte anlänt.",al={"var är förstärkningarna","valanaar meddelande","meddelande till valanaar"}},{q="Vad behöver Elegael?",a="Elegael ber dig hjälpa hennes sårade kamrater att överleva anfallet från Al'Aketh Cultists.",al={"hur går det att hjälpa","hjälpa elegael","vad ber hon om"}}},fp="19,163,14.316.0,23.75.0,39.83.0,41.77.0,23.83.0"}
P.entries["quest:94494"] = {n="Call of Water",s="Call of Water är ett andligt uppdrag för shamaner som är redo att förena sig med vattenelementets renande natur. Efter att ha skapat harmoni med vind, jord och eld når den invigde Norric Lochthane i Loch Modan, som uppmanar dem att ta det första steget mot att lära sig vattnets renhet.",h="Call of Water är ett andligt uppdrag för shamaner som är redo att förena sig med vattenelementets renande...",kw={"call of water","element","berg","renhet","shaman","totemprövning","water totem"},ang={["class:Shaman"]="Denna prövning är ett grundläggande steg i att stämma sig till elementandarna och gå från jord och eld mot förståelsen av vattnets flöde och renhet.",["race:Dwarf"]="Mentorns kärva dvärgstämma speglar hur dvärgshamaner i Forever närmar sig föreningen med naturen längs karga bergsstigar."},sec={{t="Renhetens väg",b="Call of Water är ett viktigt steg på shamanens väg mot elementär balans. Med jorden som grund för varje steg, vinden i ryggen och den inre elden brinnande stark kallas vandraren att förstå vattnets djupare natur. Det är inte bara en yttre kraft, utan också en andlig spegling av renhet och uthållighet."},{t="Uppstigning bland elementen",b="En erfaren mentor talar med bergens stadiga stämma och manar den invigde framåt utan tvekan. En shaman får aldrig en förbindelse med andarna till skänks. Den kräver fysisk ansträngning, uthållig själ och en färd upp genom karg terräng. Som mentorn varnar väntar berget inte på någon, och resan mot verklig förståelse måste börja med det avgörande första steget."}},faq={{q="Vad är Call of Water?",a="Call of Water är en andlig övergångsrit för shamaner som söker förening med vattenelementet. Efter att redan ha lärt sig jordens stadga, vindens fart och eldens gnista kallas den som söker att lära sig vattnets djupare sanning.",al={"vad är call of water","call of water-uppdraget","vad är det här för uppdrag"}},{q="Vem vägleder detta steg på resan?",a="Eldrun Stormbreaker, shamantränaren i Ironforge, skickar den invigde till Norric Lochthane i Loch Modan. Norric säger dessa ord för att mana till beslutsam handling och påminna vandraren om att varken elementen eller höjderna väntar på den tveksamma.",al={"vem ger call of water","vem säger att berget inte väntar på någon","mentor i call of water"}},{q="Vad betyder det att berget inte väntar på någon?",a="Det är en uppmaning att ta det första steget på en krävande uppstigning. Shamaners resor leder ofta högt upp bland toppar och in i avlägsen vildmark där andarna bor. Där krävs beslutsamhet, inte dröjande tvivel.",al={"vad betyder berget väntar inte på någon","berget väntar inte på någon","bergets betydelse"}},{q="Vad är sanningen om vattnets renhet?",a="I shamanens utövande ger varje element sina egna lärdomar. Sten ger stadga och eld stärker beslutsamheten, medan vatten står för rening, flöde och renhet – viktiga insikter för att balansera andarna inom sig.",al={"varför vattnets renhet","vattnets renhets sanning","vattenelementets betydelse"}},{q="Hur förhåller sig vatten till de andra elementen här?",a="Innan vandraren närmar sig vattnet erkänner resan jorden, vinden och elden som grundvalar, redan förnimmade i stövel, andetag och mage. Harmoni med elementen kräver att man bemästrar balans, inte att man söker en enda kraft för sig.",al={"vilka element kommer först","förkunskaper för vatten","elementen i call of water"}},{q="Vart går den invigde efter att ha hört dessa ord?",a="Den invigde måste ta det första steget. Norric Lochthane skickar dem vidare till Wetlands för att söka Water Sapta hos Hervdana Saegrund, som bor i en grotta under de södra vattenfallen.",al={"vad händer sedan i call of water","vart går jag nu","nästa steg i call of water"}}},fp="13,164,18.179.0,24.227.0,26.141.0,36.205.0,53.171.0,36.156.0,49.173.0,53.148.0"}
P.entries["quest:94495"] = {n="Call of Water",s="Call of Water skickar andliga sökare till Wetlands för att lära sig vattnets renande kraft och söka efter Water Sapta. I en avskild grotta under de södra vattenfallen välkomnar dvärgen Hervdana Saegrund resenärer som vågar sig ut i vildmarken.",h="Call of Water skickar andliga sökare till Wetlands för att lära sig vattnets renande kraft och söka efter...",kw={"call of water","dvärg","hervdana saegrund","schaman","södra vattenfallen","water sapta","wetlands"},ang={["class:Shaman"]="Uppdraget är ett viktigt steg i att lära sig vattnets natur och få tag på en Water Sapta för att få kontakt med andarna.",["faction:Alliance"]="Resan tar resenärer djupt in i det förrädiska Wetlands, långt från alla dvärgiska eller alliansens vaktpatruller.",["race:Dwarf"]="Hervdana känner igen sökaren som en frände som vågar sig ut i de farliga träskmarkerna, där Dark Iron-dvärgar lurar i närheten."},sec={{t="Vattnets natur",b="Resan mot förståelse av vatten börjar med en enkel lektion om dess dubbla natur: vatten står för återfödelse, formar sten och renar orenheter när det är rent, men hotar med förödelse när det är förorenat. De som söker gemenskap med elementet skickas ut i vildmarken för att hämta en Water Sapta från dem som lever nära det."},{t="Skydd under vattenfallen",b="Djupt inne i Wetlands fuktiga träskmarker har Hervdana Saegrund och hennes familj sitt hem i en grotta, gömd direkt under de södra vattenfallen. Långt från Ironforge-vakternas beskydd uthärdar de hotet från Dark Iron-dvärgar som lurar i de omgivande träskmarkerna för att kunna leva avskilt vid de forsande vattenfallen."}},faq={{q="Vem är Hervdana Saegrund?",a="Hervdana Saegrund är en dvärg som bor med sin familj i en grotta under Wetlands södra vattenfall. Hon hjälper schamaner som söker gemenskap med vatten och kunskap om Water Sapta.",al={"vem är hervdana","hervdana saegrund","var finns hervdana"}},{q="Vad är Water Sapta?",a="En Water Sapta är ett ceremoniellt elixir som schamaner använder för att få kontakt med vattnets andar. För att få tag på en i de östra rikena hänvisas sökare till Hervdana Saegrund nära de södra vattenfallen.",al={"vad är water sapta","sapta betydelse","varför skaffa water sapta"}},{q="Var finns Hervdana Saegrund?",a="Hervdana och hennes familj bor avskilt i en grotta direkt under de södra vattenfallen i Wetlands.",al={"var bor hervdana","var ligger grottan","de södra vattenfallens läge"}},{q="Varför bor Hervdana i det farliga Wetlands?",a="Trots den ständiga faran från Dark Iron-dvärgar som lurar i träskmarkerna och den totala avsaknaden av stadsvakter har Hervdana och hennes släkt av egna skäl valt att leva avskilt i vattenfallsgrottan.",al={"varför bo i wetlands","faror i wetlands","dark iron i wetlands"}},{q="Vad är lärdomen om vatten här?",a="Vatten står för återfödelse, formar sten, sköljer bort smuts och lindrar trötta när det är rent. Men om det fördärvas eller förorenas förstör det allt det rör vid.",al={"vad betyder vatten","vattnets filosofi","lärdom om vatten"}},{q="Vad är syftet med uppdraget Call of Water?",a="Call of Water är en schamansk övergångsrit som vägleder de invigda till att förstå elementets natur och söka upp Water Sapta hos avskilda vägvisare.",al={"vad är det här för uppdrag","vem är uppdraget till för","dvärgschamanens uppdrag"}}},fp="13,172,19.234.0,25.277.0,25.191.0,24.183.0,37.114.0,49.167.0,40.130.0,47.114.0"}
P.entries["quest:94497"] = {n="Call of Water",s="Call of Water är ett andligt uppdrag i Wetlands som vägleder en novis på vägen mot att förtjäna sapta. Genom att samla bräckt flodmynningsvatten där bergens vattenfall möter havets tidvatten lär sig sökaren vattnets livgivande krafter samtidigt som hen tar sig fram bland träskets faror.",h="Call of Water är ett andligt uppdrag i Wetlands som vägleder en novis på vägen mot att förtjäna sapta.",kw={"call of water","dark iron","flodmynning","hervdana","sapta","skinnflaska","wetlands"},ang={["class:Shaman"]="Att söka sapta kräver att man förstår vattnets natur i olika länder och stämmer sin ande till dess många former.",["race:Dwarf"]="Hervdana sörjer den fortsatta splittringen mellan dvärgklanerna, särskilt när Dark Iron-dvärgar tränger så långt norrut som till Wetlands."},sec={{t="Sapta-vägen",b="För att förtjäna sapta och möta andarna måste en novis söka vatten i dess olika former. Hervdana vägleder sökare att se hur vatten rör sig, förändrar liv och ger näring åt landet. Resan börjar med att förstå flodmynningsvatten där havets tidvatten möter färskt vatten från höglandet."},{t="Där sötvatten möter bräckt vatten",b="Vid foten av vattenfallen nedanför Hervdanas grotta rinner källvatten från höglandet ner i träsket och möter saltvatten som tidvattnet fört in från kusten. Havets tidvatten för med sig sediment, mineraler och krafter som skiljer sig mycket från klart smältvatten från bergen, vilket gör flodmynningen till en källa till naturlig visdom."},{t="Skuggor i träsket",b="Att samla vatten i Wetlands är inte riskfritt. Förutom den farliga träskfaunan har Dark Iron-dvärgar trängt obehagligt långt norrut. Hervdana betraktar med sorg den pågående fientligheten mellan dvärgklanerna och ser hur mycket dvärgfolket skulle kunna åstadkomma om de bara lade sina fejder åt sidan."}},faq={{q="Vad är sapta?",a="Sapta är en helig dryck som används för att möta elementandarna. För att förtjäna den måste en novis söka vatten i dess olika tillstånd och förstå hur det formar landet och ger näring åt levande varelser.",al={"vad är sapta","sapta betydelse","varför söka sapta"}},{q="Vem är Hervdana?",a="Hervdana ger uppgiften från sin grotta ovanför vattenfallen i Wetlands. Hon vägleder noviser när de samlar vattenprover för att stämma dem till elementet.",al={"vem ger call of water","var finns hervdana","hervdanas grotta"}},{q="Varför samla vatten där sötvatten möter bräckt vatten?",a="Flodmynningsvatten är en särskild samlingspunkt där snösmältning och färska källor från höglandet blandas med havets tidvatten. Mötet mellan sötvatten och mineralrikt saltvatten för med sig unika sediment och andlig visdom.",al={"varför flodmynningsvatten","bräckt vatten wetlands","där sötvatten möter saltvatten"}},{q="Vilka faror lurar nära vattenfallen?",a="Dark Iron-dvärgar har smugit sig norrut in i Wetlands och utgör ett direkt hot mot resenärer och elementssökare som försöker nå träskmarkerna och vattenfallen.",al={"dark iron i wetlands","varför är dark iron-dvärgar här","hotet från dark iron"}},{q="Vad innebär det att bli ett kärl?",a="Ett kärl är en novis som har börjat söka vattnets visdom aktivt och bär med sig gåvor av naturens vatten för att utveckla en djupare samklang med elementen.",al={"vad är ett kärl","vattenkärl"}},{q="Vad används Empty Brown Waterskin till?",a="Empty Brown Waterskin är kärlet Hervdana tillhandahåller för att samla in det bräckta provet vid foten av träskets vattenfall.",al={"vad används empty brown waterskin till","vilken skinnflaska används"}}},fp="13,176,20.273.0,26.308.0,20.248.0,18.191.0,16.149.0,52.128.0,38.136.0,37.126.0,43.116.0"}
P.entries["quest:94499"] = {n="Call of Water",s="Call of Water är ett uppdrag där resande skickas till Stonewatch Falls i Redridge för att undersöka misstänkt förorening i vattnet från Lake Everstill. Genom att fylla en Empty Red Waterskin och återvända med den till Hervdana Saegrund i Wetlands avslöjar schamaner den verkliga orsaken till de muterade murlocerna i trakten och får samtidigt ett viktigt reagens till sina andliga prövningar.",h="Call of Water är ett uppdrag där resande skickas till Stonewatch Falls i Redridge för att undersöka misstänkt...",kw={"call of water","hervdana saegrund","lake everstill","nightcrawler-murlocer","redridge","sapta","skuggseare","stonewatch falls","wetlands"},ang={["class:Shaman"]="Uppdraget är ett viktigt steg i bryggandet av en Water Sapta och prövar schamanens hängivenhet och förmåga att uppfatta vatten långt hemifrån, innan mötet med vattnets andar."},sec={{t="Ett misstänkt vattenfall",b="Hervdana Saegrund i Wetlands skickar blivande schamaner söderut till Redridge för att undersöka vattendragen som störtar nerför Stonewatch Falls. Lake Everstill förser Lakeshire med rent vatten, men murlocerna som håller till vid vattenfallets fot har blivit ovanligt stora och förvridna bestar. Hervdana misstänker gift, mörk trolldom eller läckage från den gamla fästningen ovanför och ber resande samla ett prov i en Empty Red Waterskin."},{t="Föroreningens verkliga källa",b="När Hervdana undersöker den fyllda vattenskinnen upptäcker hon att vattnet som forsar från Everstill är helt rent och opåverkat av föroreningar. De lokala Nightcrawler-murlocernas fysiska förvridning beror inte på förorenat dricksvatten, utan på den mörka magi som skuggseare runt Stonewatch använder. Provet visar både att vattenfallet är rent och att schamanen är hängiven, och fungerar som ett viktigt reagens när en andlig sapta ska bryggas."}},faq={{q="Vem ger uppdraget och var finns personen?",a="Hervdana Saegrund, som finns i Wetlands, ger uppdraget. Hon studerar vattenkällor och de reagens som krävs för att skapa en sapta åt en blivande schaman inför de andliga prövningarna.",al={"vem ger call of water","uppdragsgivaren hervdana"}},{q="Varför skickas du för att hämta vatten från Stonewatch Falls?",a="Hervdana misstänker att märkligt gift, mörk magi eller förorening kan rinna nerför Stonewatch Falls från det gamla fortet ovanför och orsaka missbildningar hos murlocerna vid foten. Hon behöver ett färskt prov att undersöka.",al={"varför fylla vattenskinn i redridge","syftet med stonewatch falls"}},{q="Är vattnet vid Stonewatch Falls faktiskt förorenat?",a="Nej, själva vattnet visar sig vara helt rent och oförorenat. Hervdana kommer fram till att de lokala murlocernas förvridna tillstånd i stället beror på mörk magi från traktens skuggseare, inte på förorenat vatten.",al={"är vattnet vid stonewatch förorenat","är lake everstill förorenad"}},{q="Varför är murlocerna vid Stonewatch Falls så stora och förvridna?",a="Nightcrawler-murlocerna nära vattenfallets fot är stora och förvridna jämfört med dem som finns i The Loch eller Wetlands. Hervdana drar slutsatsen att förändringen orsakas av de lokala skuggsearnas onda magi.",al={"varför är murlocer i redridge muterade","skillnad på murlocer vid stonewatch"}},{q="Vad används vattenprovet till?",a="En sapta är en ceremoniell blandning som låter en schaman genomtränga slöjan och uppfatta elementandar. Hervdana samlar rena prover från olika vatten för att brygga det reagens du behöver.",al={"vad är en sapta","syftet med belöningen i call of water"}},{q="Vem är Norric?",a="Norric är en bundsförvant eller mentor som är inblandad i schamanernas prövningar. Hervdana säger att han kommer att glädjas åt att du lyckats hämta det rena vattenprovet.",al={"vem är norric","norric i call of water"}}},fp="13,154,17.377.0,29.321.1,48.155.0,56.206.0,50.111.0,65.166.0,34.165.0,14.135.0"}
P.entries["quest:945"] = {n="Therylune's Escape",s="I södra Darkshore har en ung nattalv vid namn Therylune irrat in på de hotfulla utgrävningsplatserna vid The Master's Glaive och hamnat omringad av fientliga kultister. En eskort från Alliansen behövs för att föra henne i säkerhet och meddela hennes oroliga syster Therysil, som vilar vid The Shrine of Aessina, att hon överlevt.",h="I södra Darkshore har en ung nattalv vid namn Therylune irrat in på de hotfulla utgrävningsplatserna vid The...",kw={"ashenvale","kultister","eskort","the master's glaive","the shrine of aessina","therylune","therysil","twilight's hammer"},ang={["faction:Alliance"]="Att hjälpa strandade vandrare som Therylune stärker Alliansens närvaro och välvilja bland de infödda nattalver som försvarar Ashenvale.",["race:NightElf"]="The Master's Glaive är ett uråldrigt ärr i Kalimdors historia. Att se dina kaldorei-fränder irra obekymrat in bland kultisternas utgrävningar är en tankeväckande påminnelse om hoten som växer inne i Ashenvale."},sec={{t="En farlig promenad",b="The Master's Glaive är ett av Darkshores mest kusliga landmärken, dominerat av en uråldrig monstruös varelses väldiga kranium, genomborrat av ett enormt stensvärd. Trots den fasa som vilar över dalen irrade Therylune rakt in i ravinens hjärta. Snart blev hon fast under Twilight's Hammer-kultisternas bevakning och överlevde bara tack vare snabba reflexer och sin förmåga att gömma sig i den oländiga terrängen."},{t="Besked till helgedomen",b="Therylunes syster Therysil bor långt i söder vid den fridfulla The Shrine of Aessina. Therylune är känd för att vara äventyrslysten och inte bry sig om att smutsa ner kläderna, men även hennes närmaste blev chockade när hon gav sig in bland de osunda utgrävningarna vid The Master's Glaive. Beskedet att Therylune är i säkerhet lättar oron hos en djupt bekymrad syster, som vet alltför väl vilka mörka krafter som just nu gräver genom Darkshores uråldriga jord."}},faq={{q="Vem är Therylune?",a="Therylune är en äventyrslysten ung nattalv som irrade in bland de farliga utgrävningarna vid The Master's Glaive i södra Darkshore. Hon är Therysils syster.",al={"therylune","vem är flickan","alv i fällan"}},{q="Vem är Therysil?",a="Therysil är Therylunes syster och håller till vid den fridfulla The Shrine of Aessina i Ashenvale. Hon blir bestört när hon får veta att hennes syster irrat så nära en så mörk och besudlad plats.",al={"therysil","therylunes syster"}},{q="Varför är The Master's Glaive så farligt?",a="The Master's Glaive är en uråldrig, hotfull ravin där en uråldrig ”old lord” föll för länge sedan. Twilight's Hammer-kultister svärmar över området, gräver aggressivt på platsen och anfaller alla som tränger sig in.",al={"faran vid the master's glaive","kultister vid the master's glaive"}},{q="Vart ska Therylune eskorteras?",a="Therylune behöver eskorteras bort från det omedelbara området kring The Master's Glaive till säkerhet. Därefter måste räddaren resa till The Shrine of Aessina för att underrätta hennes syster.",al={"eskortens mål","vart ska therylune"}},{q="Var ligger The Shrine of Aessina?",a="The Shrine of Aessina ligger i sydvästra Ashenvale, väster om Astranaar, och är en fristad tillägnad skogsanden Aessina.",al={"var ligger the shrine of aessina","var är therysil"}},{q="Hur överlevde Therylune omringad av kultister?",a="Therylune lyckades undvika att bli tillfångatagen enbart genom att hitta ett trångt gömställe bland klipporna och terrängen innan Twilight's Hammer-kultisterna hann upptäcka henne.",al={"hur gömde sig therylune"}}},fx={["8c0c4bd7"]={q="Varför behöver Therylune din hjälp för att fly?",a="Therylune irrade in i den olycksbådande utgrävningen vid The Master's Glaive och fann sig snart fångad och omringad av Twilight's Hammer-sektmedlemmar. Hennes förmåga att gömma sig har hållit henne vid liv, men hon kan inte på egen hand smita förbi fanatikerna som omringar henne för att nå säkerhet och lugna sin syster, Therysil.",al={"varför vill therylune ha hjälp","therylunes motiv","varför hjälpa therylune"}},cc515991={q="Varför kan Therylune inte fly på egen hand?",a="Therylune är skicklig nog på att gömma sig för att undvika att bli tillfångatagen direkt, men hon är helt obeväpnad och försvarslös, djupt inne på fientligt område. Eftersom inga vakter eller allierade finns i närheten är hon helt beroende av en förbipasserande äventyrare som kan bana en flyktväg genom sektmedlemmarna.",al={"varför behöver therylune mig","varför kan therylune inte fly","varför jag för therylune"}}},fp="18,189,17.304.0,18.371.0,17.159.0,16.156.0,40.167.0,41.143.0,39.130.0,49.129.0"}
P.entries["quest:94500"] = {n="Call of Water",s="Call of Water skickar en äventyrare genom Ashenvales smaragdgröna trädkronor för att samla rent, uråldrigt vatten från sjön vid Astranaar. Det är det sista insamlingssteget innan resenären skickas tillbaka till Norric.",h="Call of Water skickar en äventyrare genom Ashenvales smaragdgröna trädkronor för att samla rent, uråldrigt...",kw={"ashenvale","astranaar","auberdine","call of water","menethil","norric","southshore","vattensäck"},ang={["faction:Alliance"]="Uppdraget leder resenärer längs Alliansens sjöväg från Eastern Kingdoms till Kalimdor och förbinder Menethil Harbor med Auberdine och Night Elf-bosättningen Astranaar.",["race:NightElf"]="Uppdraget leder resenärer till det rena vattnet kring Astranaar, ett av Kaldoreis kärnområden i Ashenvale, där uråldriga ruiner fortfarande ligger orörda."},sec={{t="Jakten på rent vatten",b="Call of Water kräver att en äventyrare fyller en vattensäck med Ashenvales orörda vatten. Sökaren måste ta sig till Astranaar, en fristad omgiven av rent, uråldrigt vatten som skvalpar mot sjunkna ruiner från en svunnen tid. Detta rena prov är den sista vätskan uppdragsgivaren behöver innan resenären skickas vidare till Norric."},{t="Vägen till Astranaar",b="För att nå Ashenvales djup måste man korsa havet från Eastern Kingdoms. Den rekommenderade vägen går med fartyget från Menethil Harbor mot Auberdine, med ett hamnstopp i Southshore på vägen. Från Auberdines kajer leder vägen inåt land, in bland Ashenvales smaragdgröna trädkronor, där resenärer varnas för att hålla sig på sin vakt bland trädens vaksamma skuggor."}},faq={{q="Vad är uppdraget Call of Water?",a="Call of Water är ett uppdrag där resenären ska ta med en tom vattensäck djupt in i Ashenvales uråldriga skog. Målet är att samla ett prov av rent, uråldrigt och möjligen förtrollat vatten från sjön vid bosättningen Astranaar innan det återlämnas till uppdragsgivaren.",al={"vad är call of water","uppdraget call of water","målet med call of water"}},{q="Var samlar jag vatten till uppdraget?",a="Vattnet måste samlas från sjön som omger Astranaar, djupt inne i Ashenvale. Vattnet där är fortfarande orört och strömmar bland uråldriga, sjunkna ruiner från en svunnen tid.",al={"var hittar man rent vatten","var fyller man vattensäcken","call of water plats"}},{q="Hur tar jag mig till Ashenvale för uppdraget?",a="Resenärer rekommenderas att ta båten från Menethil Harbor till Auberdine, som stannar i Southshore på vägen. Från Auberdine vid Darkshores kust reser man söderut in i Ashenvales djupa, smaragdgröna skogar för att nå Astranaar.",al={"hur tar man sig till astranaar","resa till ashenvale","båt till astranaar"}},{q="Vad gör vattnet vid Astranaar speciellt?",a="Sjön vid Astranaar är känd för att innehålla vatten som inte har berörts av fördärv. Under ytan ligger nedsänkta stenruiner som vittnar om en uråldrig, svunnen tid av alvisk civilisation och ger vattnet dess rena och möjligen förtrollade egenskaper.",al={"vilken sjö finns i astranaar","astranaars vattenruiner","ruiner i astranaars sjö"}},{q="Vem är Norric?",a="Norric är personen som väntar på resenären efter att detta sista vätskeprov har samlats in. Uppdragsgivaren samlar in detta rena vatten från Ashenvale som den sista ingrediensen innan äventyraren skickas tillbaka till Norric.",al={"vem är norric","återvänd till norric"}},{q="Vilka faror kan jag vänta mig i Ashenvale?",a="Ashenvale är en uråldrig, tät skog full av faror. Uppdragsgivaren varnar resenärer att ständigt vara på sin vakt och påminner om att skogen har vakande ögon som aldrig blinkar när man färdas under dess smaragdgröna trädkronor.",al={"faror i ashenvale","hot i ashenvale"}}},fp="13,126,25.233.0,21.285.0,32.174.0,44.137.0,44.197.0,42.188.0,14.146.0,42.147.0"}
P.entries["quest:94501"] = {n="Call of Water",s="Call of Water är ett andligt prov för shamaner som söker de heliga vatten totem-riterna. Genom att överlämna rent vatten välsignat av Hervdana till Norric Lochthane i Loch Modan förbereder sig sökarna på att skapa den elementära sapta som behövs för att tala med andarna vid Stendel's Pond.",h="Call of Water är ett andligt prov för shamaner som söker de heliga vatten totem-riterna.",kw={"call of water","hervdana","loch modan","moonbrook","norric lochthane","shaman","stendel's pond","vial of purest water","water sapta","water totem"},ang={["class:Shaman"]="Detta prov är ett avgörande steg för att tala med elementen, utföra vatten totem-riterna och skapa den sapta som behövs för att se elementandar.",["faction:Alliance"]="Alliansens shamaner söker kontakt med vattenandar i de östra länderna och knyter samman Loch Modan med Westfall.",["race:Dwarf"]="Resan för samman dvärgiska shamanaspiranter med elementära mentorer som Norric Lochthane i Khaz Modan."},sec={{t="Vägen till Water Totem",b="Call of Water är ett viktigt prov i andlig samklang för blivande shamaner som söker harmoni med vattenelementet. För att gå denna väg måste man samla vatten som välsignats av Hervdana själv och visa både tålamod och vördnad för andarna innan kärlet förs till Norric Lochthane i Loch Modan."},{t="Sapta blir till",b="När Norric får det välsignade kärlet berättar han att den heliga vätskan ska användas till att brygga en vattensapta. Drycken låter sökaren skåda bortom det synliga och se vattenandarna som bor vid Stendel's Pond nära Moonbrook. Varenda droppe är dyrbar, för även en fuktad propp fyller sin funktion i de heliga riterna."}},faq={{q="Vem är Norric Lochthane?",a="Norric Lochthane är en mentor som bor i Loch Modan och vägleder kandidater genom deras samvaro med elementen. Han leder förberedelserna och riterna som krävs för att få en Water Totem.",al={"vem är norric","norric i loch modan","vem är norric lochthane"}},{q="Vem är Hervdana?",a="Hervdana Saegrund är vägvisaren i Wetlands. Hon bor med sin familj i en grotta vid de södra vattenfallen och välsignar det heliga vatten som blivande shamaner samlar in. Därmed ger hon det den andliga renhet som krävs för att skapa en vattensapta.",al={"vem är hervdana","välsignad av hervdana","hervdana vatten"}},{q="Vad används en sapta till?",a="En sapta är en elementär dryck som tillreds med heligt vatten. När en shaman dricker den kan hen skåda bortom slöjan och uppfatta de svårfångade vattenandar som bor i naturliga vattenpölar.",al={"vad är water sapta","saptans syfte","vad gör sapta"}},{q="Var ligger Stendel's Pond?",a="Stendel's Pond ligger i Westfall nära Moonbrook. I dess vatten finns elementära vattenandar som en shaman måste söka upp efter att ha druckit sin tillredda sapta.",al={"var ligger stendel's pond","stendel pond plats","vattenandar vid stendel"}},{q="Varför är Vial of Purest Water viktig?",a="Vial of Purest Water innehåller välsignat vatten som behövs för att brygga vattensaptan och utföra de heliga riterna som krävs för att få en Water Totem. Norric varnar för att inte ens en enda droppe får gå till spillo.",al={"varför behövs rent vatten","vial of purest water syfte"}},{q="Vad är vatten totem-riterna?",a="Vatten totem-riterna är andliga prov som shamaner genomgår för att stämma sig till vattenelementet och visa respekt och balans innan de får en Water Totem.",al={"vad är vatten totem-riterna","hur får man en water totem"}}},fp="13,168,27.150.0,18.228.1,24.159.0,16.165.0,25.123.0,32.133.0,42.162.0,31.137.0"}
P.entries["quest:94502"] = {n="Call of Water",s="Call of Water är ett elementuppdrag där du färdas från Loch Modan till Westfall för att återställa balansen i en fördärvad källa. Genom att rena den besmittade varelsen vid Stendel's Pond och utföra en uråldrig ritual vid den bortglömda helgedomen vinner du vattenandarnas gunst och får deras Water Totem.",h="Call of Water är ett elementuppdrag där du färdas från Loch Modan till Westfall för att återställa balansen i...",kw={"call of water","loch modan","moonbrook","norric","schaman","stendel's pond","water totem","westfall"},ang={["class:Shaman"]="Den här prövningen är en viktig övergångsrit där du stämmer dig till vattenandarna och vinner Water Totem, som visar din harmoni med och behärskning av elementkrafterna.",["faction:Alliance"]="Alliansens schamaner måste färdas genom sina områden, från Loch Modan till de oroliga trakterna i Westfall, för att rena det fördärvade vattnet."},sec={{t="En källa besmittad av skuggor",b="I Moonbrooks skugga ligger Stendel's Pond, som en gång var en hyllad, klar och ren källa. Mörka krafter som sveper över Westfall har förorenat dess fridfulla vatten och tystat de lokala vattenandarna. En gammal helgedom står vid stranden, försummad och täckt av damm och spindelväv, och väntar på att någon ska väcka de slumrande krafterna inom den."},{t="Reningsriten",b="Norric i Loch Modan vägleder dig genom ritualen som krävs för att återställa balansen. Riten kräver att du möter den vidriga varelsen som förorenar Stendel's Pond, tar dess armskenor och lägger dem på stenhelgedomen tillsammans med några droppar av ett alkemiskt brygd. När du uttalar besvärjelsen framkallar ångorna en renad ande, som delar med sig av sin visdom och visar att du är värdig Water Totem."}},faq={{q="Vad är uppdraget Call of Water?",a="Call of Water är en andlig prövning för schamaner som söker kontakt med vattnets element. Uppdraget går ut på att rena fördärvet vid Stendel's Pond i Westfall, använda en gammal helgedom där för att frammana en renad vattenande och vinna sin Water Totem.",al={"vad är call of water","water totem-uppdrag","vattenuppdrag i westfall"}},{q="Vem ger det här uppdraget?",a="Uppdraget ges av Norric, en mentor i Loch Modan. Han lär dig elementritualer, ger dig särskilda brygder och vägleder dig i att rena fördärvade elementvatten.",al={"vem ger call of water","norric i loch modan","uppdragsgivare"}},{q="Var ligger Stendel's Pond?",a="Stendel's Pond ligger strax utanför Moonbrook i sydvästra Westfall. Den var en gång en ren källa, men har blivit stillastående och grumlig under inflytande av mörka, fördärvande krafter.",al={"var ligger stendel's pond","stendel's ponds plats","damm nära moonbrook"}},{q="Hur renar du fördärvet vid Stendel's Pond?",a="För att rena vattnet måste du besegra den fördärvande närvaron vid Stendel's Pond, ta dess armskenor och lägga dem på den uråldriga helgedomen tillsammans med de återstående dropparna av brygden medan du uttalar orden Norric har lärt dig.",al={"hur renar man dammen","rena stendel's pond","ritual vid helgedomen"}},{q="Vad får du när du slutför uppdraget?",a="När du har klarat prövningen och återvänt till Norric i Loch Modan med bevis på reningen får du din Water Totem, som ger dig makt över vattnets elementkrafter.",al={"vilken belöning ger call of water","water totem-belöning"}},{q="Varför är Stendel's Pond fördärvad?",a="Det är oklart var mörkret kommer ifrån. Källan ligger onaturligt stilla och omges av djurben, vilket väcker frågan om den har förgiftats av Westfalls spridande misär eller själv är en källa till fördärvet.",al={"varför är stendel's pond fördärvad","vad fördärvade dammen"}}},fp="13,212,26.284.0,21.359.1,32.235.0,21.168.0,24.152.0,52.195.0,43.169.0,32.211.0"}
P.entries["quest:94503"] = {n="Call of Water",s="Call of Water är ett uppdrag i Westfall där äventyrare ska rena korrumperade elementarkrafter.",h="Call of Water är ett uppdrag i Westfall där äventyrare ska rena korrumperade elementarkrafter.",kw={"call of water","rening","korrumpering","elementar","minor manifestation of water","vattenande","westfall"},ang={["class:Shaman"]="Att tala med uråldriga element och rena besmittade vattenandar är en grundläggande elementrit. Den påminner shamaner om deras eviga plikt att bevara naturens balans.",["faction:Alliance"]="Manifestationen finns i Westfall, ett territorium tillhörande Alliansen där de lokala andarna uthärdar den krypande farsot som drabbar landet."},sec={{t="Reningen av de besmittade vattnen",b="I Westfalls vindpinade landskap hotas vattnens naturliga balans av korrumperade andar. Riten Call of Water kräver att du möter denna ondska och uttalar heliga ord som frammanar ett strålande ljus. Ljuset skingrar de rastlösa, besmittade essenserna till ofarlig aska och stilla dimma."},{t="Andens varning",b="När de korrumperade väsendena drivits tillbaka kan en Minor Manifestation of Water tryggt visa sig och tala med dig. Den omedelbara korrumperingen avtar, men anden varnar för att landets livskraft fortsätter att minska. Den påminner mästarna om att skydda livet är en ständig uppgift."}},faq={{q="Vad är Call of Water?",a="Call of Water är en andlig prövning i Westfall där korrumperade andar fördrivs med en ritual som framkallar ett ljussken. Det befriar de plågade vattnen och gör det möjligt att tala med en Minor Manifestation of Water.",al={"vad är call of water","call of water westfall","vattenuppdrag i westfall"}},{q="Var finns Minor Manifestation of Water?",a="Minor Manifestation of Water finns i Westfall. Den visar sig när de korrumperade andarna i närheten har kuvats och skingrats, redo att tala med dem som hjälpte vattnen.",al={"var finns minor manifestation of water","manifestationens plats","vattenande westfall"}},{q="Vad händer när de korrumperade andarna renas?",a="När besvärjelsen fullbordas bryter ett strålande ljus fram och skingrar de korrumperade andarna. Deras besmittade essens löses upp och sprids som aska, medan vattnet fräser till och blir mild dimma.",al={"vad händer under ritualen","korrumperade andar call of water"}},{q="Har landet återställts helt när uppdraget är klart?",a="Den omedelbara korrumperingen har drivits tillbaka och avtar, men elementaren varnar för att livskraften fortsätter att minska. Det långvariga skyddet av livet ligger i dödligas händer.",al={"är korrumperingen borta","räddade vi vattnet"}},{q="Vem kallas in för att hjälpa manifestationen?",a="Uppdraget erkänner spelarens kall och tackar deras klass för att de träder fram, renar andarna och tar på sig ansvaret att skydda det liv som håller på att sina.",al={"vem kan göra call of water","klasskrav för vattenuppdrag"}},{q="Varför korrumperades vattenandarna i Westfall?",a="Korrumperade andar har stört de naturliga vattnen i Westfall. Även om besmittelsens exakta ursprung är oklart, suger andarnas onda närvaro direkt livskraften ur området.",al={"varför är vattnet korrumperat i westfall","vattenproblem i westfall"}}},fp="13,113,28.166.0,20.184.0,22.203.0,52.163.0,53.149.0,53.155.0,47.147.0,49.153.0"}
P.entries["quest:94505"] = {n="Call of Water",s="Call of Water är en elementär övergångsrit där shamaner lär sig att kommunicera med vattenandar och använda deras läkande krafter. Genom att hämta en Shard of Water från Westfall åt Norric Lochthane i Loch Modan visar de sin hängivenhet och får sin Water Totem.",h="Call of Water är en elementär övergångsrit där shamaner lär sig att kommunicera med vattenandar och använda...",kw={"call of water","loch modan","norric lochthane","shaman","shard of water","water totem","westfall"},ang={["class:Shaman"]="Den här prövningen är en grundläggande övergångsrit som ger en shaman gemenskap med vattenandarna och deras Water Totem för att läka och upprätthålla liv.",["faction:Alliance"]="Till skillnad från Hordens shamaner i Kalimdor vänder sig alliansanslutna invigda till mentorer som Norric Lochthane i Loch Modan och genomgår prövningar på platser som Westfall."},sec={{t="Vattnets väg",b="Call of Water är en viktig andlig prövning där shamaner knyter band till vattenelementet. De invigda får i uppdrag att resa till Westfall och återvända till Norric Lochthane i Loch Modan med Shard of Water. Genom att visa sin förståelse för vattnets livgivande väsen och dess roll i att rena korruption förtjänar shamanerna sin Water Totem och tar ett viktigt steg på sin elementära resa."},{t="Livets givare",b="Prövningen förmedlar en grundläggande elementär sanning: vatten är liv, och korruption gör slut på livet. Shamaner har fått i uppgift att använda vattnets läkande styrka för att skydda de utsatta och bevara levande varelser. Som mentor Norric Lochthane konstaterar när han tar emot Shard of Water sträcker sig vattnets rena gåvor långt bortom enkel fysisk läkning och omfattar uthållighet, förnyelse och andlig balans."}},faq={{q="Vem är Norric Lochthane?",a="Norric Lochthane är en shamansk mentor i Loch Modan. Han vägleder de invigda genom deras prövningar så att de förstår vattenandarna, prövar deras beslutsamhet med en resa till Westfall och ger dem deras Water Totem när de överlämnar bevis på sin gemenskap med vattnet.",al={"vem är norric lochthane","vem ger water totem","norric i loch modan"}},{q="Vad är Shard of Water?",a="Shard of Water är det fysiska bevis som förs tillbaka från Westfall till Norric Lochthane i Loch Modan. Den visar att den invigde har kommunicerat med vattnet, förstått dess livgivande natur och lärt sig bekämpa korruption.",al={"vad är shard of water","användning av shard of water","shard of water uppdragsföremål"}},{q="Varför går prövningen till Westfall?",a="De invigda skickas till Westfall för att förstå vattnets livgivande kraft och hur korruption hotar den. Även små segrar i det oroliga landet väger tungt när den invigdes förmåga att skydda liv ska visas.",al={"varför åka till westfall","vattenuppdrag i westfall","resan till westfall i call of water"}},{q="Vad betyder vattentotemen?",a="Water Totem förkroppsligar en shamans band till vattenelementet. Den är främst känd för att lindra och läka sår med rent vatten, men dess andliga gåvor sträcker sig långt bortom grundläggande läkning och omfattar bevarande och livskraft.",al={"vad gör water totem","varför behöver shamaner water totem","water totems berättelse"}},{q="Vilken lärdom ger prövningen om vatten?",a="Den elementära filosofi som lärs ut under prövningen betonar att vatten ger liv, medan korruption hejdar det. En shaman har fått i uppgift att använda vattnets elementära kraft för att vårda, skydda och återställa balansen där korruption hotar levande varelser.",al={"vad betyder vatten är liv","call of water filosofi","shamanernas vattenlära"}},{q="Vad händer när Call of Water är avklarad?",a="Norric Lochthane påpekar att en invigdes nästa elementära prövning inte kommer med detsamma. Han uppmuntrar shamaner att ta sig tid att öva och utforska vattnets djupare mysterier innan de antar fler prövningar.",al={"vilken prövning kommer härnäst","nästa shamanprövning","vad händer efter call of water"}}},fp="13,163,17.305.0,13.267.0,24.236.0,27.193.0,36.173.0,44.145.0,45.201.0,46.170.0"}
P.entries["quest:94535"] = {n="Bristle Hills Bandits",s="Kreza Darkthorn skickar dig till Bristle Hills efter att gnoller attackerat allierade gruvarbetare. Du ska återta den stulna malmen från deras läger.",h="Kreza Darkthorn skickar dig till Bristle Hills efter att gnoller attackerat allierade gruvarbetare.",kw={"allierade gruvarbetare","banditer","bristle hills","gnoller","kreza darkthorn","stulen malm"},sec={{t="Malm från Bristle Hills",b="Allierade gruvarbetare rapporterar gnollattacker i kullarna söder om Kreza Darkthorn. Du ska hitta lägren i Bristle Hills och återta den stulna malmen. Gruvarbetarnas förluster står på spel."},{t="Efter återtagandet",b="Kreza Darkthorn säger att malmen har återtagits och att eld utplånar alla spår och lukter som lämnats kvar."}},faq={{q="Vem skickar mig efter den stulna malmen?",a="Kreza Darkthorn ber dig återta malmen som stulits från allierade gruvarbetare.",al={"vem är kreza","vem ger malmuppdrag"}},{q="Var finns banditerna?",a="Gnollerna finns i läger i Bristle Hills, söder om Kreza Darkthorn.",al={"gnolläger","var finns banditer"}},{q="Vem stal malmen?",a="Gnoller i Bristle Hills attackerade allierade gruvarbetare och tog deras malm.",al={"malmtjuvar","vem tog malmen"}},{q="Vad hände med gruvarbetarna?",a="Allierade gruvarbetare som arbetar i kullarna söderut rapporterade flera attacker från gnoller.",al={"gruvarbetare attackerade","varför stals malmen"}}},fp="21,139,18.187.0,18.98.1,34.70.0,22.71.0,18.70.0,28.83.0"}
P.entries["quest:94556"] = {n="Jom-jom's Escape",s="Jom-jom vill återvända hem och ber dig följa honom till Clugfist vid Bolder'ok.",h="Jom-jom vill återvända hem och ber dig följa honom till Clugfist vid Bolder'ok.",kw={"bolder'ok","clugfist","eskortera","vän","hem","jom-jom"},sec={{t="Vägen hem",b="Vid Bolder'ok behöver Jom-jom din hjälp att hitta till Clugfist. Han kom hit för att leta efter en vän, och nu vill han åka hem."}},faq={{q="Vem är Jom-jom?",a="Jom-jom kom hit för att leta efter en vän och vill nu åka hem.",al={"vem är jom-jom","jom-jom"}},{q="Vart vill Jom-jom ta sig?",a="Jom-jom vill återvända hem, och du ombeds följa honom till Clugfist vid Bolder'ok.",al={"vart ska jom-jom","jom-jom hem"}},{q="Vem är Clugfist?",a="Clugfist är den som Jom-jom ska eskorteras till vid Bolder'ok.",al={"clugfist","vem är clugfist"}},{q="Varför kom Jom-jom hit?",a="Jom-jom kom hit för att leta efter en vän.",al={"varför är jom-jom här","jom-jom kom"}},{q="Ser Jom-jom dig som en vän?",a="När du räddar honom kallar Jom-jom dig för en vän.",al={"jom-jom vän","liten en"}}},fp="16,81,12.116.0,15.59.0,30.87.0,16.62.0,26.34.0,35.47.0"}
P.entries["quest:94568"] = {n="The Cult's True Plans",s="The Cult's True Plans handlar om följderna av en kultavhoppares för tidiga död. När informatören är död och hans hemligheter gått förlorade måste utredarna rådfråga Talaanis Shadowsong för att utarbeta en ny strategi mot kulten.",h="The Cult's True Plans handlar om följderna av en kultavhoppares för tidiga död.",kw={"kult","avhoppare","fredsbevarare","talaanis shadowsong","the cult's true plans","förrädare"},sec={{t="En tystad avhoppare",b="En insider lämnade kulten när han blev skräckslagen av dess förestående planer och hoppades få hjälp utifrån. Tragiskt nog dödades avhopparen innan han hann berätta vad han visste, och lämnade bara illavarslande varningar efter sig utan några konkreta uppgifter om vad kulten tänker släppa lös."},{t="En ny strategi",b="När deras främsta informatör är död måste ledningen rådfråga Talaanis Shadowsong för att ompröva sin strategi. Att möta kulten i en öppen konfrontation med fredsbevarare bedöms vara en förlorad strid, så de som utreder hotet måste hitta en annan väg framåt."}},faq={{q="Vem var avhopparen som nämns i det här uppdraget?",a="En avhoppare från kulten sökte hjälp när han blev skräckslagen av vad kulten än planerade. Tyvärr dödades han innan han kunde avslöja detaljerna om deras planer, och tog med sig sin värdefulla information i graven.",al={"vem dog i the cult's true plans","vem är den döde avhopparen","kultavhopparens hemligheter"}},{q="Vem är Talaanis Shadowsong?",a="Talaanis Shadowsong är den viktiga kontakt som rådfrågas om hur man ska gå vidare mot kulten efter informatörens plötsliga död. Du bevittnar ett strategiskt samtal med Talaanis för att komma fram till nästa handlingsplan.",al={"talaanis shadowsongs roll","vem är talaanis shadowsong","tala med talaanis"}},{q="Varför kan fredsbevararna inte bara anfalla kulten direkt?",a="Att skicka in fredsbevarare i en öppen strid mot kultens styrkor anses vara alldeles för riskabelt, eftersom fredsbevararna inte väntas klara sig väl i en frontalkrock. En mer subtil eller alternativ strategi krävs i stället.",al={"varför inte strida mot kulten","fredsbevarare mot kult","direkt anfall mot kulten"}},{q="Vad är kultens verkliga planer?",a="Kultens exakta planer är höljda i dunkel eftersom informatören dog innan han hann berätta vad han visste. Vad deras mål än är var det skrämmande nog för att få en medlem att desperat lämna kulten.",al={"vad planerar kulten","kultens planer","vad betyder the cult's true plans"}},{q="Vad är nästa steg efter samtalet med Talaanis?",a="När ledningen har insett att en öppen strid inte är aktuell och att deras främsta underrättelsekälla är död måste den utarbeta en alternativ metod för att avslöja och motverka kultens planer.",al={"vad händer efter the cult's true plans","nästa steg i kultuppdraget"}},{q="Vad händer under The Cult's True Plans?",a="Du talar med Talaanis Shadowsong och bevittnar ett rådslag om situationen. Samtalet kretsar kring följderna av informatörens död och varför vanliga militära styrkor inte kan förväntas stoppa kulten.",al={"sammanfattning av uppdraget the cult's true plans","vad gör man i the cult's true plans"}}},fp="21,139,19.170.0,23.268.1,45.146.0,27.161.0,55.145.0,33.163.0,51.142.0,42.178.0"}
P.entries["quest:94613"] = {n="My Kingdom for a Horse",s="En närliggande gård har förlorat sina hästar, så Stormwind står utan kavalleri i fälttåget mot Horde. Du skickas till Wheeler’s Grange för att tala med Benjy.",h="En närliggande gård har förlorat sina hästar, så Stormwind står utan kavalleri i fälttåget mot Horde.",kw={"benjy","horde","försvunna hästar","my kingdom for a horse","stormwinds kavalleri","stridshästar","wheeler’s grange"},sec={{t="De saknade hästarna",b="Stormwinds stridshästar kommer från två närliggande gårdar, men Wheeler’s Grange har förlorat alla sina hästar. Orsaken är okänd, och utan hästar har staden inget kavalleri till fälttåget mot Horde. Du skickas till gården för att tala med Benjy och höra vad han har att säga."}},faq={{q="Varför behöver Stormwind hästarna?",a="Stormwind förlitar sig på stridshästar till sitt kavalleri, som staden anser nödvändigt för fälttåget mot Horde.",al={"varför hästar","behöva stridshästar","stormwinds kavalleri"}},{q="Vad hände med hästarna på Wheeler’s Grange?",a="Hela familjen Wheelers hästbestånd är försvunnet, och orsaken är okänd.",al={"försvunna hästar","vart hästarna tar vägen","wheelers hästar"}},{q="Vem är Benjy?",a="Benjy finns på Wheeler’s Grange, dit du skickas för att fråga om de försvunna hästarna.",al={"benjy","personen på wheelers grange","vem ska jag prata med"}},{q="Var hålls Stormwinds stridshästar?",a="Stormwinds stridshästar kommer från två närliggande gårdar. Familjen Wheeler äger den ena, Wheeler’s Grange.",al={"hästgårdar","var hästarna kommer ifrån","stridshästgårdar"}}},fp="22,160,17.279.0,35.111.0,50.73.0,13.83.0,39.108.0"}
P.entries["quest:94616"] = {n="Water Sapta",s="Water Sapta är en ceremoniell dryck som stämmer ens andliga syn med vattnets dolda andar och fördärv. Bäraren får i uppdrag att hitta förorenat dammvatten på Westfalls fält och undersöka en elementär obalans.",h="Water Sapta är en ceremoniell dryck som stämmer ens andliga syn med vattnets dolda andar och fördärv.",kw={"elementär stämning","sapta","schamanprövning","förorenat damm","water sapta","vattenandar","westfall"},ang={["class:Shaman"]="En sapta är en alkemisk eller rituell dryck som schamaner använder för att stämma sina andliga sinnen med elementandar som inte syns för vanliga ögon.",["faction:Alliance"]="När fördärvat vatten i Westfall undersöks förs elementära reningsriter till hjärtat av ett alliansrike."},sec={{t="Vattnets syn",b="I shamankonstens elementtraditioner är en sapta en ceremoniell brygd som bereder vägen genom slöjan mellan den fysiska världen och andarna. Water Sapta stämmer sinnena specifikt med vattenelementet och ger den andliga syn som krävs för att uppfatta elementära störningar och dolda andar. Utan en sådan stämning kan vanliga resenärer se rakt på en elementaruppenbarelse utan att urskilja mer än vanliga krusningar."},{t="Störningar i Westfall",b="Uppdraget med Water Sapta skickar bäraren till Westfall, ett torrt alliansrike präglat av oro och försummelse. I detta vindpinade land finns ett förorenat damm vars vatten lider av andlig förorening. Med hjälp av saptans förmåga att skärpa sinnena måste bäraren söka upp det fördärvade vattnet för att upptäcka störningen och återställa harmonin bland de lokala vattenandarna."}},faq={{q="Vad är Water Sapta?",a="En vattensapta är en särskild andlig brygd som skapats för att schamaner ska kunna samverka med elementen. När man dricker eller använder en sapta öppnas sinnena tillfälligt för elementarväsen och andliga obalanser som annars är dolda för dödliga.",al={"vad är water sapta","water saptas syfte","vad gör water sapta"}},{q="Var finns det förorenade dammet i Westfall?",a="Det förorenade dammvattnet finns i Westfall. Schamaner skickas dit med vattensaptan för att hitta fördärvade vattenkällor och ta itu med den andliga störning som frodas i området.",al={"var finns det förorenade dammet","förorenat damm i westfall","förorenat damms läge"}},{q="Varför leder vattensaptan till Westfall?",a="Även i jordbruksbygder och torkdrabbade människoländer som Westfall kan elementärt vatten drabbas av förorening eller mörkt fördärv. Uppdraget går ut på att söka efter förorenat dammvatten och återställa balansen bland de oroliga andar som bor där.",al={"varför åka till westfall","vattenfördärv i westfall","varför är vattnet i westfall förorenat"}},{q="Vem använder vattensaptan?",a="Vattensaptor anförtros åt schamaner som genomgår prövningar i samverkan med elementen. Genom att ta del av saptan stämmer utövaren sina sinnen med vattenandar och kan uppfatta dolda elementarväsen eller undersöka förorenade dammar.",al={"vem dricker water sapta","vem använder water sapta","schaman dricker sapta"}},{q="Vad händer när du tar saptan till det förorenade dammet?",a="När du använder vattensaptan nära det förorenade dammet i Westfall får du elementär syn, som avslöjar vattnets andliga tillstånd eller kallar fram dolda andar knutna till den lokala vattenprövningen.",al={"vad händer efter att sapta används","sapta och elementär syn"}},{q="Hur fungerar elementära saptor i schamantraditionen?",a="Saptor förenar jordnära ingredienser med elementära välsignelser i en ceremoniell dryck. Schamaner förlitar sig på dem under sina prövningar för att stämma sig med specifika element — jord, eld, vatten eller luft — och överbrygga klyftan mellan den fysiska världen och andevärlden.",al={"hur fungerar saptor","sapta-lore"}}},fp="11,183,23.267.0,23.267.0,22.127.0,38.138.0,42.163.0,25.180.0,58.170.0,51.171.0"}
P.entries["quest:94638"] = {n="Strength and Mercy",s="Ur'endras livskamrat ber dig att göra slut på hennes lidande sedan hon förlorat sig i vansinne. Din beslutsamhet ger dig en välsignelse som låter dig anta hans fränders skepnad.",h="Ur'endras livskamrat ber dig att göra slut på hennes lidande sedan hon förlorat sig i vansinne.",kw={"druidens välsignelse","gustberry lowlands","klons skepnad","shen'dar highlands","strength and mercy","ur'endra","vindarnas magi"},ang={["class:Druid"]="Som druid ombeds du att visa din beslutsamhet innan du får en välsignelse som låter dig anta druidens fränders skepnad."},sec={{t="En tung vädjan",b="En druid ber dig att göra slut på Ur'endras lidande i Shen'dar Highlands. Hon är hans livskamrat, men vansinnet har vänt henne mot hennes egna fränder. Förlusten av vindarnas magi har fått många varelser att förlora sig själva, och Ur'endra är en av dem. Hennes lya ligger i en grotta väster härom, bland branterna mellan Shen'dar Highlands och Gustberry Lowlands."},{t="Välsignelsen",b="I Shen'dar Highlands sörjer Ur'endras livskamrat förlusten av henne och kallar den nödvändig för balansen. Han ser din beslutsamhet när du accepterar ett så fruktansvärt pris. Han skänker dig en välsignelse som låter dig anta hans fränders skepnad, och ger dig i uppdrag att hjälpa dem som saknar styrka och försvara dem som är i nöd."}},faq={{q="Vem är Ur'endra?",a="Ur'endra är livskamrat till druiden som ber dig att göra slut på hennes lidande.",al={"ur'endra","vem är urendra","druidens livskamrat"}},{q="Varför angriper Ur'endra sina fränder?",a="Ur'endra har förlorat sig i vansinne. Förlusten av vindarnas magi har fått många varelser att förlora sig själva.",al={"varför är urendra vansinnig","urendra angriper","vad hände med urendra"}},{q="Var ligger Ur'endras lya?",a="Ur'endra har sin lya i en grotta väster om druiden, bland branterna mellan Shen'dar Highlands och Gustberry Lowlands.",al={"urendras grotta","var är urendra","grotta i shen'dar"}},{q="Vad ber druiden mig att göra?",a="Druiden ber dig att göra slut på Ur'endras lidande.",al={"urendra uppdrag","vad ska göras","döda urendra"}},{q="Vilken välsignelse skänker druiden?",a="Druiden skänker dig en välsignelse som låter dig anta hans fränders skepnad.",al={"skepnadens välsignelse","klons väg","druidens välsignelse"}},{q="Varför ber druiden om detta?",a="Druiden anser att det är nödvändigt för balansen att göra slut på Ur'endras lidande.",al={"varför döda urendra","varför är detta nödvändigt","balans"}}},fp="18,141,12.353.0,12.293.1,16.68.0,34.112.0,25.125.0,33.47.0,35.72.0,32.74.0"}
P.entries["quest:94668"] = {n="Bloodmaster's Ring",s="Vid Bloodmaster's Ring rapporterar du till Jezap efter att ha bevisat dig mot Twilight ogres. Bloodmaster är redo att avgöra om du hör hemma där.",h="Vid Bloodmaster's Ring rapporterar du till Jezap efter att ha bevisat dig mot Twilight ogres.",kw={"bloodmaster","bloodmaster's ring","goblin","jezap","maktens brant","twilight ogres"},sec={{t="Vid ringen",b="Utmaningen vid Bloodmaster's Ring har fört dig till Jezap. När du besegrat Twilight ogres rapporterar du till honom, medan Bloodmaster och en goblinföljeslagare ser på. De avgör om du hör hemma bland dem som närmar sig maktens brant."}},faq={{q="Vem rapporterar jag till vid Bloodmaster's Ring?",a="Du rapporterar till Jezap vid Bloodmaster's Ring.",al={"vem är jezap","rapportera till jezap","bloodmaster ring goblin"}},{q="Vad gjorde jag innan jag kom hit?",a="Du krossade Twilight ogres som bedömdes vara svaga.",al={"vad hände tidigare","twilight ogres","föregående steg vid ringen"}},{q="Vad letar Bloodmaster efter?",a="Bloodmaster avgör om du hör hemma vid maktens brant.",al={"bevisa mig","vad vill bloodmaster","hör jag hemma"}}},fp="18,147,11.262.0,45.46.0,33.49.0,36.72.0"}
P.entries["quest:94669"] = {n="Pay to Play",s="En samlare kräver en säkerhetsdeposition innan du får gå in i Bloodmaster's Ring. Betala, så får du kvalificera dig för att bevisa din styrka där.",h="En samlare kräver en säkerhetsdeposition innan du får gå in i Bloodmaster's Ring.",kw={"bloodmaster's ring","clugfist","betala för att spela","bevisa din styrka","ring","säkerhetsdeposition"},sec={{t="Priset för inträdet",b="Du måste betala en säkerhetsdeposition för att gå in i Bloodmaster's Ring. Samlaren säger att betalningen krävs för din säkerhet. Om du inte betalar hotar samlaren med att berätta för Clugfist att du vägrade bevisa din styrka för det välkomnande sällskapet. Ditt val avgör om du kvalificerar dig för ringen."}},faq={{q="Varför måste jag betala?",a="Samlaren säger att en säkerhetsdeposition krävs för din säkerhet och för att du ska kvalificera dig för Bloodmaster's Ring.",al={"varför betala","säkerhetsdeposition","uppdraget pay to play"}},{q="Vem är Clugfist?",a="Clugfist är den person som samlaren hotar med att berätta för om du vägrar betala.",al={"vem är clugfist","clugfist","gamle clugfist"}},{q="Vad händer om jag vägrar?",a="Samlaren säger att hen kommer att berätta för Clugfist att du inte ville bevisa din styrka.",al={"betala inte","vägra depositionen","ingen deposition"}},{q="Vad kvalificerar betalningen mig för?",a="När du betalar säkerhetsdepositionen kvalificerar du dig för Bloodmaster's Ring.",al={"kvalificera sig för vad","inträde till ringen","bloodmaster ring"}}},fp="11,132,18.294.0,21.106.0,16.76.0,25.90.0,32.67.0"}
P.entries["quest:94670"] = {n="Bloodmaster's Ring",s="Utmaningen i Bloodmaster's Ring ställer dig mot Buzzbeak, med berömmelse i potten. Ringens mästare väntar sig en enkel kamp.",h="Utmaningen i Bloodmaster's Ring ställer dig mot Buzzbeak, med berömmelse i potten.",kw={"bloodmaster","bloodmaster's ring","buzzbeak","berömmelse","odjur","kamp","ring"},sec={{t="In i ringen",b="Bloodmaster ställer Buzzbeak framför dig i ringen. Du får veta att den första kampen ska vara enkel, men odjuret sägs fälla sin motståndare och ta dennes tillhörigheter. De som går in i ringen utlovas berömmelse."}},faq={{q="Vem möter jag i Bloodmaster's Ring?",a="Du möter Buzzbeak i Bloodmaster's Ring.",al={"kamp med bloodmaster","vem är buzzbeak","motståndare i ringen"}},{q="Vad sägs Buzzbeak göra?",a="Buzzbeak beskrivs som ett flyktigt odjur som kan fälla dig och ta dina tillhörigheter.",al={"buzzbeaks attack","vad gör buzzbeak","odjur i ringen"}},{q="Varför gå in i ringen?",a="Bloodmaster utlovar berömmelse till den som går in i ringen.",al={"berömmelse i ringen","bloodmasters berömmelse","varför slåss mot buzzbeak"}},{q="Ska den här kampen vara enkel?",a="Bloodmaster framställer detta som en enkel första kamp.",al={"enkel kamp i ringen","bloodmaster enkel","buzzbeak svår"}}},fp="18,129,13.210.0,41.44.0,32.90.0,19.52.0,31.53.0"}
P.entries["quest:94672"] = {n="Encroaching Twilight",s="Tran'gul varnar för att Twilight's Hammer har slagit till mot en mänsklig bosättning väster om Rog'mar. Du skickas till Sunnyglade för att minska kultens antal innan den får fäste i närheten.",h="Tran'gul varnar för att Twilight's Hammer har slagit till mot en mänsklig bosättning väster om Rog'mar.",kw={"annalkande skymning","mänsklig bosättning","rog'mar","sunnyglade","tran'gul","twilight-noviser","twilight-plundrare","twilight's hammer"},sec={{t="Ett hot i närheten",b="Den mänskliga bosättningen i väster har redan härjats, och Rog'mar kan stå näst på tur. Tran'gul skickar dig till Sunnyglade, där Twilight's Hammer har inlett sin kampanj mot dem som kulten kallar kättare. Dess plundrare och noviser hotar att få fäste nära Rog'mar."},{t="Efter striden",b="När kultens antal har minskat kan Tran'gul söka efter orsaken till dess aldrig tidigare skådade expansion."}},faq={{q="Vem oroar sig Tran'gul för?",a="Tran'gul fruktar Twilight's Hammer, en kult som angriper dem den anser vara kättare.",al={"vem är hotet","hotet från twilight's hammer"}},{q="Vad hände med den mänskliga bosättningen?",a="Twilight's Hammer har härjat en mänsklig bosättning väster om Rog'mar.",al={"bosättning i väster","vad hände i väster"}},{q="Varför ska jag till Sunnyglade?",a="Tran'gul skickar dig till Sunnyglade för att minska Twilight's Hammers antal.",al={"varför sunnyglade","vad finns i sunnyglade"}},{q="Vem kan kulten rikta in sig på härnäst?",a="Tran'gul fruktar att Rog'mar kan stå näst på tur efter den mänskliga bosättningen i väster.",al={"vem står näst på tur","rog'mar härnäst"}}},fp="20,173,15.274.0,15.96.1,30.75.0,38.65.0,29.74.0,31.74.0"}
P.entries["quest:94680"] = {n="Twilight Missives",s="Tran'gul vill ta reda på varför Twilight's Hammer-kultisterna har blivit fler kring Sunnyglade. Han ber dig hämta deras meddelanden så att han kan ta reda på vad de är ute efter.",h="Tran'gul vill ta reda på varför Twilight's Hammer-kultisterna har blivit fler kring Sunnyglade.",kw={"kultister","meddelanden","rog'mar","sunnyglade","tran'gul","twilight missives","twilight shadowmancers","twilight's hammer"},sec={{t="En växande närvaro",b="Tran'gul har sett fler Twilight's Hammer-kultister i området än tidigare. Deras Twilight Shadowmancers är betrodda medlemmar av orden och kan känna till dess kampanj. Du ombeds hämta meddelanden från dem så att Tran'gul kan ta reda på vad kulten är ute efter."}},faq={{q="Vem ber om Twilight Missives?",a="Tran'gul i Rog'mar ber dig hämta meddelanden från Twilight Shadowmancers i Sunnyglade.",al={"vem vill ha meddelandena","tran'gul ber om","vem är tran'gul"}},{q="Var hittar jag Twilight Shadowmancers?",a="Twilight Shadowmancers finns i Sunnyglade.",al={"shadowmancer-plats","var finns twilight-kultister","sunnyglade-meddelanden"}},{q="Varför vill Tran'gul ha meddelandena?",a="Tran'gul vill veta mer om kultisterna och vad de är ute efter.",al={"varför hämta meddelanden","vad vill tran'gul veta","kultistpapper"}},{q="Varför oroar sig Tran'gul för kultisterna?",a="Tran'gul har sett fler Twilight's Hammer-kultister än tidigare, och de verkar ha blivit djärvare och vill utöka sitt inflytande.",al={"varför är twilight här","kultister blir fler","twilight-antal"}}},fp="17,171,18.258.0,35.91.0,44.45.0,36.67.0,45.128.0"}
P.entries["quest:947"] = {n="Cave Mushrooms",s="Cave Mushrooms är ett uppdrag från Alliansen som ges av nattalven Barithras Moonshade i Auberdine. När han tar fram en specialblandning skickar Barithras en äventyrare till en dold grotta bakom Cliffspring Falls för att samla sällsynta svampar och undersöka oroande föraningar från Grove of the Ancients.",h="Cave Mushrooms är ett uppdrag från Alliansen som ges av nattalven Barithras Moonshade i Auberdine.",kw={"auberdine","barithras moonshade","cave mushrooms","cliffspring falls","darkshore","death cap","grove of the ancients","onu","scaber stalks"},ang={["faction:Alliance"]="Auberdine är Alliansens främsta fäste längs Kalimdors kust, och växande ondska i de östra bergen hotar hela kustens trygghet direkt.",["profession:Herbalism"]="Samlare och örtkunniga uppskattar jakten på death cap och scaber stalks, även om de här exemplaren växer i mörka grottor i stället för i frodig skogsmark.",["race:NightElf"]="Grove of the Ancients är fortfarande djupt förbundet med Darkshores naturliga balans, så varje störning de känner av under fallen är mycket oroande."},sec={{t="Ett recept bakom fallen",b="Barithras Moonshade behöver särskilda ingredienser till en kraftfull blandning: scaber stalks och en svårfunnen death cap. De här svamparna trivs i den fuktiga, skuggiga grottan som ligger dold precis bakom Cliffspring Falls i nordöstra Darkshore. Själva alkemin är krävande, men det är betydligt farligare att samla exemplaren än att plocka vanliga skogsörter."},{t="De äldstes varning",b="Barithras undvek inte grottan av ren lättja. De vördnadsvärda trädväktarna i Grove of the Ancients utfärdade stränga varningar, eftersom de kände att en otäck närvaro hade börjat slå sig ner i bergsgrottorna. Genom att skicka en tålig utforskare i stället för att undersöka saken själv vill Moonshade ta reda på om de äldstes dystra föraningar om en krypande ondska i norra Darkshore verkligen stämmer."}},faq={{q="Var börjar uppdraget?",a="Du får uppdraget av Barithras Moonshade, som bor i nattalvernas kustbosättning Auberdine i centrala Darkshore.",al={"var hämtar man cave mushrooms","var finns barithras moonshade","var börjar uppdraget cave mushrooms"}},{q="Var finns svamparna?",a="De växer i en grotta dold bakom Cliffspring Falls, längs bergssidan nordost om Auberdine.",al={"var finns scaber stalks","var finns death cap","grottan bakom vattenfallet i darkshore"}},{q="Varför hämtar inte Barithras Moonshade svamparna själv?",a="Grove of the Ancients rådde uttryckligen Barithras att hålla sig borta från fallen. De stora trädväktarna kände att en onaturlig, växande ondska hade tagit sin tillflykt i grottan.",al={"varför går barithras inte dit","varför stannar barithras i auberdine"}},{q="Vilka svampar behövs?",a="Moonshade behöver fem scaber stalks och en enda mycket farlig death cap-svamp för att färdigställa sin brygd.",al={"svampar som behövs","vilka svampar behöver moonshade"}},{q="Vart leder ärendet sedan?",a="När närvaron i grottan har bekräftats och svamparna levererats går färden söderut till den uråldriga beskyddaren Onu i Grove of the Ancients.",al={"nästa uppdrag efter cave mushrooms","fortsättningsuppdrag från onu"}},{q="Varför oroar sig de äldste för Cliffspring Falls?",a="Grove of the Ancients varnade Barithras för att en växande ondska kan lura i grottan bakom fallen. Han ber en resenär att samla svampar och undersöka varningen.",al={"de äldstes varning om cliffspring falls","varför utforska grottan"}}},fx={a048db56={q="Varför vill Barithras Moonshade att detta ska göras?",a="Barithras Moonshade är örtalchemist och brygger en kraftfull ny brygd som kräver sällsynta svampar från grottan bakom Cliffspring Falls. Men han har också en djupare oro utöver sitt alkemiska arbete: Grove of the Ancients varnade honom för att ett växande ont lurar i just den grottan. Genom att skicka dig för att samla ingredienser hoppas han också få veta om de uråldriga väktarnas mörka förebud stämmer.",al={"varför vill barithras ha grottsvampar","barithras moonshades motiv","varför samla svamp åt barithras"}},["991c4c10"]={q="Vad ska Death Cap användas till?",a="Death Cap är en ytterst sällsynt och kraftfull giftig svamp som växer i grottan bakom Cliffspring Falls. Barithras Moonshade behöver ett oskadat exemplar som en viktig ingrediens i en specialbrygd han tillverkar i Auberdine.",al={"vad används death cap till","vad death cap-svampen är till för","varför behöver barithras death cap"}},be6516db={q="Vad ska Scaber Stalk användas till?",a="Scaber Stalk är sällsynta svampar som frodas i den fuktiga, skuggiga grottan bakom Cliffspring Falls. Barithras Moonshade behöver fem stycken till sina pågående alkemiska brygder, tillsammans med den kraftfulla Death Cap.",al={"vad scaber stalk används till","vad scaber stalk-svampen är till för","varför behöver barithras scaber stalk"}}},fp="14,210,25.227.0,21.252.1,27.115.0,32.104.0,61.156.0,35.87.0,35.141.0,55.161.1"}
P.entries["quest:94727"] = {n="Digging for Answers",s="Twilight's Hammer gräver genom Riverglades efter en okänd kraftkälla. Du skickas till Sunnyglade för att förhöra en av deras gruvarbetare.",h="Twilight's Hammer gräver genom Riverglades efter en okänd kraftkälla.",kw={"gräva efter svar","gruvarbetare","riverglades","source of power","sunnyglade","twilight's hammer"},sec={{t="Gruvarbetare i Sunnyglade",b="Twilight's Hammer har arbetare som gräver i Sunnyglade, och du skickas för att förhöra en av gruvarbetarna. Deras sökande pekar mot en kraftkälla, men dess natur är fortfarande okänd. Fanatikerna håller sina hemligheter väl, så gruvarbetarna kanske vet vad de söker."}},faq={{q="Vad gräver Twilight's Hammer efter?",a="Twilight's Hammer verkar söka efter en kraftkälla i Riverglades, men det är fortfarande okänt vad det är.",al={"vad gräver de efter","twilight's hammer gräver","source of power"}},{q="Varför ska jag förhöra en gruvarbetare?",a="Twilight's Hammers fanatiker håller sina hemligheter väl, så du skickas till Sunnyglade för att förhöra en av deras gruvarbetare.",al={"varför gruvarbetare","prata med gruvarbetaren","uppdraget gräva efter svar"}},{q="Var finns gruvarbetarna?",a="Gruvarbetarna gräver i Sunnyglade, i Riverglades.",al={"var ligger sunnyglade","gruvarbetarnas plats","grävning i riverglades"}}},fp="19,148,20.255.0,42.119.0,29.112.0,21.61.0"}
P.entries["quest:94733"] = {n="Our Ogre Friend",s="En goblin ber dig hitta Gobam i Bolder'ok och ta med mat till Snufflesnout, Chub'chobs husdjursgalt. Gobam hjälper gärna till eftersom Chub'chob är hans vän.",h="En goblin ber dig hitta Gobam i Bolder'ok och ta med mat till Snufflesnout, Chub'chobs husdjursgalt.",kw={"bolder'ok","chub'chob","klubbhus","gobam","goblin","vår ogrevän","husdjursgalt","snufflesnout"},sec={{t="En väns begäran",b="Efter att du vunnit några strider ber goblinen dig hitta Gobam i Bolder'ok. Han behöver mat till Snufflesnout, Chub'chobs husdjursgalt, men säger att arbetet håller honom upptagen. Gobam finns öster om Clugfist's clubhouse, och goblinen hoppas att du kan hitta honom."}},faq={{q="Vem är Gobam?",a="Gobam är den blyga typen som goblinen skickar dig att leta efter i Bolder'ok.",al={"vem är gobam","vem gobam"}},{q="Var hittar jag Gobam?",a="Gobam finns öster om Clugfist's clubhouse i Bolder'ok.",al={"gobams plats","var gobam"}},{q="Vem är Snufflesnout?",a="Snufflesnout är Chub'chobs husdjursgalt, och goblinen ber dig ta med mat till den.",al={"snufflesnout","mat till galten"}},{q="Varför behöver goblinen hjälp?",a="Goblinen säger att arbetet håller honom upptagen, så han ber dig hitta mat till Snufflesnout.",al={"varför hjälpa goblinen","goblinen upptagen"}},{q="Varför hjälper Gobam till?",a="Gobam säger att han ogillar goblinen, men hjälper Chub'chob eftersom de är goda vänner.",al={"gobam hjälper","varför gobam hjälper"}}},fp="15,157,20.242.0,13.66.0,23.51.0,20.83.0,30.86.0,20.92.0"}
P.entries["quest:94739"] = {n="Bloodmaster's Ring",s="Bloodmaster skickar ner dig i gropen för att möta Kronk. Publiken väntar redan ivrigt på nästa rond.",h="Bloodmaster skickar ner dig i gropen för att möta Kronk.",kw={"utroparen","bloodmaster","bloodmaster's ring","kamp","deltagare","kronk","grop"},sec={{t="Nästa rond",b="Utroparen gör publiken redo medan Kronk väntar som nästa deltagare. Du skickas ner i gropen för att möta honom, och sorlet stiger inför den kommande kampen."}},faq={{q="Vem är Kronk?",a="Kronk är nästa deltagare i Bloodmaster's Ring. Utroparen säger att de känner varandra sedan länge och beskriver honom som en stark slagskämpe.",al={"kronk","vem är kronk","kronk bloodmaster"}},{q="Vad vill Bloodmaster att jag ska göra?",a="Bloodmaster skickar ner dig i gropen för att möta Kronk.",al={"vad ska jag göra","uppgift i ringen","bloodmaster ring"}},{q="Varför slåss jag mot Kronk?",a="Utroparen presenterar Kronk som nästa deltagare, och kampen ska utkämpas i Bloodmaster's Ring.",al={"varför kronk","slåss mot kronk","kronk kamp"}},{q="Var utkämpas kampen?",a="Kampen utkämpas i gropen i Bloodmaster's Ring.",al={"var är kampen","gropen","ringens plats"}},{q="Vad händer när jag går ner i gropen?",a="Utroparen förbereder sig på att presentera Kronk medan du gör dig redo i gropen.",al={"efter att ha gått in","nästa i ringen","vad händer härnäst"}},{q="Vad säger utroparen om Kronk?",a="Utroparen säger att Kronk inte är särskilt klipsk, men är bra på att puckla på allt som kommer i hans väg.",al={"kronks bakgrund","hurdan är kronk","utroparen kronk"}}},fp="18,108,13.160.0,13.130.0,40.53.0,24.101.0,31.58.0,35.78.0,40.91.0"}
P.entries["quest:94773"] = {n="Divine Grace",s="En lektion som kallas Divine Grace tackar dig för att du tjänat the Light. Ditt föredöme betyder något för resenärer i farliga trakter.",h="En lektion som kallas Divine Grace tackar dig för att du tjänat the Light.",kw={"farliga trakter","divine grace","lektion","light","resenärer"},sec={{t="En lektion som tack",b="Efter din tjänstgöring prisas the Light för det föredöme du är för resenärer i farliga trakter. Du erbjuds en lektion som tack för det du har gjort."}},faq={{q="Vad handlar Divine Grace om?",a="Divine Grace tackar dig för att du tjänat the Light och varit ett föredöme för resenärer i farliga trakter.",al={"divine grace","vad är divine grace","uppdraget divine grace"}},{q="Vem är den här lektionen till för?",a="Du erbjuds lektionen som tack för din tjänst hos the Light.",al={"vem får lektionen","lektion för mig","belöning för divine grace"}},{q="På vilket sätt var jag ett föredöme?",a="Du blev ett föredöme för resenärer i farliga trakter och bortom dem.",al={"mitt föredöme","lysande föredöme","vad gjorde jag"}}},fp="12,116,18.159.0,27.102.0,23.69.0,23.65.0"}
P.entries["quest:94774"] = {n="Divine Grace",s="High Priestess Laurena kallar dig till Cathedral of Light i Stormwind eftersom dina överordnade har godkänt fortsatt utbildning. Dina lektioner i Ljusets vägar kan nu börja.",h="High Priestess Laurena kallar dig till Cathedral of Light i Stormwind eftersom dina överordnade har godkänt...",kw={"cathedral of light","gudomlig nåd","high priestess laurena","ljuset","ljusets tjänare","stormwind","utbildning"},ang={["class:Priest"]="Dina överordnade har godkänt att du som präst får fortsatt utbildning i Ljusets vägar."},sec={{t="En kallelse till Stormwind",b="Dina överordnade skickar dig till Cathedral of Light i Stormwind efter att ha bedömt att du har visat vad du går för. Där är High Priestess Laurena redo att vägleda dig i din fortsatta utbildning. Hon säger att det finns lärdomar som varje Ljusets tjänare måste ta till sig, och hon är beredd att diskutera dem med dig."}},faq={{q="Varför skickas jag till Stormwind?",a="Dina överordnade anser att du har visat vad du går för och har godkänt fortsatt utbildning i Ljusets vägar.",al={"varför stormwind","skickad till katedralen","varför gå dit"}},{q="Vem är High Priestess Laurena?",a="High Priestess Laurena finns i Cathedral of Light i Stormwind och är redo att vägleda dig i din utbildning.",al={"laurena vem","vem är laurena","översteprästinna"}},{q="Var hittar jag High Priestess Laurena?",a="High Priestess Laurena finns i Cathedral of Light i Stormwind.",al={"laurenas plats","var är laurena","katedralens plats"}},{q="Vilken utbildning erbjuder Laurena?",a="Laurena är beredd att diskutera lärdomar som alla Ljusets tjänare måste ta till sig.",al={"utbildning i ljuset","vilka lärdomar","lära sig ljusets vägar"}}},fp="12,181,19.290.0,33.108.0,30.101.0,39.65.0,34.81.0"}
P.entries["quest:94789"] = {n="Call of Air",s="En schaman skickas till Veyric Thundervein bland de norra kullarna i Arathi Highlands. Han ska lära dig mer om att bemästra luften.",h="En schaman skickas till Veyric Thundervein bland de norra kullarna i Arathi Highlands.",kw={"luft","arathi highlands","call of air","schaman","luftens andar","veyric thundervein","vindbesvärjelser"},sec={{t="De norra kullarna",b="En schaman skickar dig norrut till Arathi Highlands för att hitta Veyric Thundervein. Luftens element är svårt att bemästra, och han kan lära dig mer. Din växande skicklighet har fört dig så här långt; nu inriktas din träning på vinden och luftens andar."}},faq={{q="Vem är Veyric Thundervein?",a="Veyric Thundervein finns bland de norra kullarna i Arathi Highlands, där han kan lära dig mer om luften.",al={"veyric","vem är veyric","lufttränare"}},{q="Var hittar jag Veyric?",a="Hitta Veyric Thundervein bland de norra kullarna i Arathi Highlands.",al={"veyrics plats","var finns veyric","lufttränare i arathi"}},{q="Vad handlar Call of Air om?",a="En schaman skickar dig till Veyric Thundervein så att han kan lära dig mer om luftens element.",al={"uppdraget call of air","luftträning","vindbesvärjelser"}},{q="Varför ska jag till Arathi Highlands?",a="Veyric Thundervein finns bland de norra kullarna i Arathi Highlands, och han ska lära dig mer om luften.",al={"varför arathi","uppdrag att gå norrut","hitta veyric"}},{q="Vad lär Veyric ut?",a="Veyric lär dig att fokusera vindbesvärjelser och åkalla luftens andar.",al={"träning hos veyric","luftens andar","fokusera vindbesvärjelser"}}},fp="11,125,18.245.0,26.103.0,23.66.0,26.91.0,35.102.0,23.73.0"}
P.entries["quest:94792"] = {n="Taming the Beast",s="Taming the Beast är ett första prov där blivande äventyrare lär sig konsten att lugna och knyta band till vilda djur. Under Josephine Carsons ledning tar noviser med sig en Taming Rod in i skogen för att tämja en Rockhide Boar och öva på viktiga överlevnadsfärdigheter. Uppgiften visar att det är mycket lättare att överleva i karga trakter med ett lojalt djur vid sin sida, så länge man värnar om naturens känsliga balans.",h="Taming the Beast är ett första prov där blivande äventyrare lär sig konsten att lugna och knyta band till...",kw={"djurföljeslagare","naturens balans","djurträning","jägarens husdjur","josephine carson","rockhide boar","taming rod","taming the beast"},ang={["class:Druid"]="Druider håller inte djur på samma sätt som jägare, men uppdragets betoning på att värna naturens känsliga balans speglar grundläggande druidlära. Att bemöta skogens djurliv varsamt och återhållsamt värnar den naturliga jämvikt som druiderna svurit att skydda.",["class:Hunter"]="För jägare är konsten att tämja vilda djur en avgörande övergångsrit som i grunden förändrar hur de överlever i vildmarken. En lojal följeslagare ger viktigt skydd och vaksamhet i strid och skapar ett varaktigt partnerskap mellan spårare och djur."},sec={{t="Att knyta band till djur",b="För många som strövar genom vildmarken innebär en ensam färd genom otämjda områden en inbjudan till fara. Ett djur ger inte bara kraftfullt skydd i strid, utan också troget sällskap under långa och krävande resor. Att lära sig knyta ett sådant band är en viktig milstolpe för varje blivande jägare eller spårare. Under Josephine Carsons ledning får nybörjare en särskild Taming Rod och uppmanas att söka upp en Rockhide Boar i skogen. Att lugna och styra en sådan varelse är ett grundläggande prov som visar om en resenär har det fokus och lugn som krävs för att leda ett djur utan att ge vika för rädsla eller framkalla onödig blodsutgjutelse."},{t="Naturens balans",b="Att bemästra vilda djur medför ett stort etiskt och ekologiskt ansvar. Som Josephine Carson påminner sina elever får det aldrig slå över i hänsynslös exploatering att ta djur i sin tjänst, eftersom naturens balans är skör och alltid måste värnas. Tämjandet handlar inte om grymhet eller dominans, utan om att skapa harmoni och disciplin mellan djur och herre. Med den förtrollade staven kan en nybörjare tryggt öva på att hantera en mäktig varelse som en Rockhide Boar utan att för gott utarma det lokala djurlivet. När grunderna i att styra och lugna djuret väl sitter lämnas staven tillbaka, vilket visar att respekten för naturens ordning går före stoltheten."}},faq={{q="Vad är syftet med uppdraget Taming the Beast?",a="Uppdraget är en viktig övning för äventyrare som vill knyta band till vilda varelser. Under Josephine Carsons ledning lär sig nybörjare att närma sig och lugna en vild Rockhide Boar med hjälp av en särskild Taming Rod. Övningen visar blivande jägare hur ett djur kan hjälpa dem att överleva i vildmarken och betonar samtidigt vikten av att respektera naturens balans.",al={"uppdraget taming the beast","vad är taming the beast","jägarens husdjursuppdrag"}},{q="Vem är Josephine Carson?",a="Josephine Carson är en mentor som lär äventyrare den känsliga konsten att ta hand om djur. Hon ger dem en Taming Rod och låter eleverna öva sina färdigheter på en Rockhide Boar i den närliggande skogen. Josephine betonar att det krävs tålamod, övning och medvetenhet om naturens känsliga balans för att lära sig arbeta tillsammans med djur.",al={"josephine carson","vem ger taming the beast","uppdragsgivare för taming rod"}},{q="Vad används Taming Rod till?",a="Taming Rod är ett särskilt redskap som Josephine Carson tillhandahåller för djurträning. Äventyrare tar staven med sig in i skogen för att lugna och tämja en vild Rockhide Boar. Den låter nybörjare tryggt öva på att styra ett djur utan att orsaka bestående skada på det lokala djurlivet, och måste lämnas tillbaka till Josephine när provet är avklarat.",al={"taming rod","vad gör taming rod","hur använder man taming rod"}},{q="Varför behöver jägare djur?",a="Att färdas ensam genom vildmarkens faror utsätter resenärer för stora risker och bakhåll. Ett djur erbjuder pålitligt skydd, vaksamhet och kraftfull hjälp i strid, vilket gör farliga situationer mycket lättare att uthärda. Ett lojalt djur är både en kraftfull försvarare i främsta ledet och en pålitlig följeslagare under långa och farofyllda expeditioner genom otämjda trakter.",al={"varför skaffa ett husdjur","fördelar med djurföljeslagare","varför tämja djur"}},{q="Vilken varelse måste tämjas under det här provet?",a="Provet kräver att äventyrare ger sig in i skogen och tämjer en Rockhide Boar med den Taming Rod de fått. Dessa kraftiga djur är ett utmärkt test av grundläggande färdigheter i djurhantering och lär resenärer att behålla lugn och disciplin när de möter aggressiva vilda djur. Därefter ska de återvända och rapportera sina framsteg till Josephine Carson.",al={"vilken galt ska jag tämja","mål för rockhide boar","varelse i taming the beast"}},{q="Varför betonar Josephine Carson naturens balans?",a="Josephine Carson varnar för att vilda djur alltid måste betvingas med försiktighet och respekt, aldrig av girighet eller med våld. Naturens ordning är skör, och hänsynslös störning av det lokala djurlivet eller misshandel av varelser rubbar den ekologiska balansen. Att verkligen bemästra djur kräver förståelse för och respekt för deras plats i ekosystemet, inte att behandla dem som förbrukningsbara verktyg.",al={"naturens balans betydelse","naturens balans vid tämjande","varför respektera naturen"}}},fp="16,181,19.403.0,21.405.0,50.234.0,24.231.0,32.240.0,38.186.0,46.237.0,58.205.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="Training the Beast är ett grundläggande uppdrag för unga jägare som skickar dem till den erfarne skogsmannen Isaac Chan i Goldshire. Genom att slutföra uppdraget lär sig jägarna att träna, utfodra och återuppliva sina djurkamrater på rätt sätt, så att ett nyss tämjt vilddjur blir en trogen stridspartner.",h="Training the Beast är ett grundläggande uppdrag för unga jägare som skickar dem till den erfarne skogsmannen...",kw={"elwynn forest","utfodra husdjur","goldshire","jägarens husdjur","isaac chan","träning av husdjur","återuppliva husdjur","training the beast","skogsman"},ang={["class:Hunter"]="Uppdraget är en viktig övergångsrit för jägare under utveckling. De går från att bara fånga vilddjur till att skapa ett varaktigt, disciplinerat band genom att utfodra, återuppliva och träna dem.",["faction:Alliance"]="Alliansens jägare i Elwynn Forest förlitar sig på erfarna skogsmän som Isaac Chan i Goldshire för att bemästra grunderna i att hantera vilddjur."},sec={{t="Jaktens ansvar",b="Att lära sig tämja ett vilt djur är bara det första steget för en blivande jägare. En varaktig samhörighet kräver disciplin och kunskap. Uppdraget skickar nybörjarjägare till den erfarne skogsmannen Isaac Chan i Goldshire för att lära sig grunderna i att träna djur. Utan rätt vägledning förblir ett tämjt djur ett bångstyrigt vilddjur i stället för en pålitlig bundsförvant i vildmarken."},{t="En skogsmans vägledning",b="När jägarna anländer till Goldshire lär Isaac Chan dem färdigheterna som behövs för att ta hand om en djurkamrat. Undervisningen omfattar mer än enkla stridskommandon. Den tar också upp det viktiga ansvaret att utfodra kamraten så att den mår bra och att lära sig hur man återupplivar den om den stupar i strid. Chan påminner sina elever om att makt över vilda djur också innebär ett ansvar att respektera naturens balans och leva med vördnad inför världen omkring oss."}},faq={{q="Vem är Isaac Chan?",a="Isaac Chan är en erfaren skogsman som har bott i Goldshire i Elwynn Forest hela sitt liv. Han är respekterad för sin djupa kunskap om vilda djur och överlevnad i vildmarken, och lär nybörjarjägare hur de tar hand om, leder, utfodrar och återupplivar sina djurkamrater samt lär dem nya förmågor.",al={"vem är isaac chan","djurtränare i goldshire","isaac chans bakgrund"}},{q="Vad är syftet med Training the Beast?",a="En jägare kanske redan vet hur man tämjer ett vilddjur, men det här uppdraget ger kunskapen som behövs för att bevara bandet. Det lär jägaren att utfodra sin kamrat, återuppliva den om den stupar i strid och lära den nya stridsförmågor.",al={"vad gör uppdraget","varför träna vilddjur","syftet med training the beast"}},{q="Var hittar man Isaac Chan?",a="Isaac Chan finns i Goldshire, den centrala orten i Elwynn Forest, strax söder om Northshire Valley och sydväst om Stormwind City.",al={"var finns isaac chan","var lämnar jag in uppdraget","isaac chans plats"}},{q="Vilka färdigheter lär Isaac Chan ut?",a="Isaac Chan lär ut grunderna i skötsel och träning av husdjur. Det innebär att utfodra ditt vilddjur så att det mår bra, återuppliva det om det stupar i strid och lära det nya förmågor medan det växer tillsammans med dig.",al={"vilka färdigheter får man","inlärda husdjursförmågor","vad lär isaac chan ut"}},{q="Varför påminner Isaac Chan jägarna om att respektera naturen?",a="Isaac Chan betonar att det krävs ödmjukhet, inte dominans, för att bemästra vilda djur. Han uppmanar jägarna att värna naturens balans och leva med vördnad inför naturen omkring dem, så att bandet mellan jägare och vilddjur bygger på omsorg snarare än utnyttjande.",al={"varför respektera naturen","jägare respektera naturens balans"}},{q="Vem kan utföra uppdraget?",a="Training the Beast är särskilt utformat för jägare som har lärt sig att tämja vilddjur och behöver disciplinen från skogarna för att ta hand om och träna en djurkamrat.",al={"vem kan göra uppdraget","är training the beast bara för jägare"}}},fp="18,184,32.248.0,21.284.0,18.217.0,42.181.0,30.129.0,34.194.0,53.207.0,26.115.0"}
P.entries["quest:948"] = {n="Onu",s="Det här ärendet leder resenärer söderut från Auberdine mot Grove of the Ancients för att rådgöra med Onu. Dina fynd i grottan bakom Cliffspring Falls har väckt en av Darkshores äldsta väktares brådskande intresse.",h="Det här ärendet leder resenärer söderut från Auberdine mot Grove of the Ancients för att rådgöra med Onu.",kw={"ancient of lore","auberdine","barithras moonshade","cliffwater falls","darkshore","grove of the ancients","onu"},ang={["class:Druid"]="Druider vördar Ancients som naturens visdom förkroppsligad. Att på Onus uppdrag undersöka märklig växtlighet i grottorna stämmer väl överens med Cenarion Circles uppgifter.",["faction:Alliance"]="För Alliansens resenärer som hjälper till att trygga Darkshore är det avgörande att vinna de lokala uråldrigas förtroende och ta del av deras insikter för att kunna ta sig fram i Kalimdors gåtfulla norra vildmark.",["race:NightElf"]="Ancients of Lore är heliga bundsförvanter till Kaldorei och har väglett ditt folk sedan före Sunderingen. Att besvara Onus kallelse är en högtidlig plikt för att bevara Darkshores helgd."},sec={{t="En kallelse från de uråldriga",b="När Barithras Moonshade återvänder till Auberdine med svampprover från Cliffspring Falls djup inser han att saken handlar om långt mer än botanisk nyfikenhet. Ryktet om de fördärvade grottorna når snabbt Onu, en Ancient of Lore med rötter i den fridfulla tillflyktsorten Grove of the Ancients söder om staden. De uråldriga trädväktarna är tålmodiga och eftertänksamma av naturen, men Onus omedelbara önskan att rådgöra visar att fördärvet i Darkshores vattendrag kan ha samband med urgamla, oroande krafter."},{t="Färden till lunden",b="När du följer vägen söderut från Auberdine lämnar du kustens ruiner bakom dig och färdas inåt landet mot bergssluttningarna. Grove of the Ancients är en uråldrig tillflyktsort för naturen, till stor del skyddad från det krypande förfall som plågar kusten. Här väntar Onu bland höga stengravar och besläktade andar, redo att leda sina bundsförvanter mot djupare och mer skrämmande farsoter som vaknar vid vildmarkens gräns."}},faq={{q="Vem är Onu?",a="Onu är en Ancient of Lore, en väldig, tänkande trädväktare som samlar in och bevarar kunskap. Han vakar över Grove of the Ancients i södra Darkshore och erbjuder landets försvarare visdom och vägledning.",al={"vem är onu","onus identitet","vad är onu"}},{q="Varför vill Onu tala med mig?",a="Du begav dig nyligen in i grottorna under Cliffspring Falls för att samla svampprover åt Barithras Moonshade. Det märkliga som upptäcktes där oroade naturforskarna, så Onu bad att få träffa dig för att tala om det växande fördärvet.",al={"varför kallar onu","anledning till samtalet","varför gå till onu"}},{q="Var ligger Grove of the Ancients?",a="Grove of the Ancients ligger söder om Auberdine, vid foten av den östra bergskedjan. Följ huvudvägen söderut genom Darkshore och ta dig österut mot bergssluttningarna för att hitta Onu.",al={"onus plats","var ligger grove of the ancients","hur hittar man onu"}},{q="Vad är en Ancient of Lore för slags varelse?",a="Ancients of Lore är urgamla treanter som står på nattalvernas och Cenarion Circles sida. De vördas för sin djupa visdom och sitt minne och tjänar som levande förvarare av naturmagi och historiska hemligheter.",al={"ancient of lore","vad är onu för varelse","treant eller ancient"}},{q="Varför är Onus kallelse så brådskande?",a="Ancients är kända för sitt långsamma och eftertänksamma sätt och handlar sällan i hast. Som Barithras Moonshade påpekar måste hotet mot Darkshore vara allvarligt om en så tålmodig och metodisk varelse som Onu aktivt kallar dig till ett rådslag.",al={"varför så brådskande","är onu orolig","barithras varning"}},{q="Vad händer efter mötet med Onu?",a="När Onu hälsar dig välkommen till Grove of the Ancients ber han dig hjälpa till att undersöka ett långt mörkare hot längre söderut längs kusten: den illavarslande utgrävningen kring The Master's Glaive.",al={"nästa uppdrag efter onu","vad händer sedan","vart skickar onu dig"}}},fx={be40e913={q="Varför skickar Barithras Moonshade mig till Onu?",a="Barithras vet att de uråldriga vishetsväktarna besitter djup kunskap om landets förruttnelse, och Onu har själv uppmärksammat det du hittade i grottan vid Cliffspring Falls. Eftersom en uråldrig väktare sällan hör av sig om inte Darkshore hotas av en allvarlig och omedelbar fara, uppmanar Barithras dig att genast hörsamma kallelsen.",al={"barithras motiv","varför skicka mig till onu","varför vill barithras att detta ska göras"}}},fp="3,166,27.409.0,20.339.0,11.167.0,35.197.0,35.190.0,44.180.0,39.132.0,34.167.1"}
P.entries["quest:94819"] = {n="Contingency Plan",s="Någon skickar dig till Ironforge för att träffa High Priestess Mims. Ditt nästa prov närmar sig, och hon väntar i Mystic Ward.",h="Någon skickar dig till Ironforge för att träffa High Priestess Mims.",kw={"reservplan","high priestess mims","ironforge","ljuset","mystic ward","nästa prov","riter"},sec={{t="En väntande audiens",b="I Ironforge väntar High Priestess Mims på att få tala med dig i Mystic Ward. Ditt nästa prov närmar sig, och den som skickade dig kan inte lämna sin plats för att bevittna ditt folks riter. Må Ljusets välsignelse följa dig på resan när du går för att träffa Mims."}},faq={{q="Vem ska jag träffa?",a="High Priestess Mims väntar på att få tala med dig i Mystic Ward i Ironforge.",al={"vem väntar","träffa mims","mims"}},{q="Var hittar jag Mims?",a="Mims bör vara i Mystic Ward i Ironforge.",al={"var är mims","mims plats","mystic ward"}},{q="Varför ska jag till Ironforge?",a="High Priestess Mims vill tala med dig där, och ditt nästa prov närmar sig.",al={"varför ironforge","vad finns i ironforge","audiens"}},{q="Vad säger avsändaren om mitt folks riter?",a="Avsändaren önskar att hen kunde bevittna ditt folks riter, men säger att hen måste stanna där hen är.",al={"mitt folks riter","särskilda riter","varför kan hen inte komma"}},{q="Vad önskas för min resa?",a="Avsändaren önskar att Ljuset följer dig på din resa.",al={"ljusets välsignelse","ljuset följa mig","välsignelse för resan"}}},fp="16,129,18.253.0,23.76.0,22.47.0,28.82.0,49.97.0,30.61.0"}
P.entries["quest:94822"] = {n="Confounding Flash",s="Dina överordnade skickar dig till Ironforge för att fortsätta din träning hos High Priestess Mims. Din tjänst åt Light har väckt deras uppmärksamhet.",h="Dina överordnade skickar dig till Ironforge för att fortsätta din träning hos High Priestess Mims.",kw={"confounding flash","hall of mysteries","high priestess mims","ironforge","light","överordnade","träning"},sec={{t="Ytterligare en lektion",b="Dina överordnade skickar dig till High Priestess Mims i Hall of Mysteries i Ironforge. De anser att din tjänst har förberett dig för fortsatt träning. Mims ska vägleda dig, och lektionen väntar på din ankomst."},{t="Inför Mims",b="High Priestess Mims tar emot dig i Ironforge och påpekar att du är sen. Hon ursäktar förseningen med hänsyn till din tjänst åt Light och ber dig sedan att lyssna noga på hennes lektion."}},faq={{q="Vem skickade mig till Ironforge?",a="Dina överordnade bad dig att resa till Hall of Mysteries i Ironforge för fortsatt träning.",al={"vem skickade mig","vilka är mina överordnade"}},{q="Vem är High Priestess Mims?",a="High Priestess Mims är den som dina överordnade säger åt dig att söka upp i Ironforge. Hon kan vägleda dig i din fortsatta träning.",al={"vem är mims","mims"}},{q="Varför skickas jag på träning?",a="Dina överordnade anser att du har visat vad du går för genom din tjänst åt Light.",al={"varför träning","varför jag"}},{q="Var hittar jag High Priestess Mims?",a="Du hittar High Priestess Mims i Hall of Mysteries i Ironforge.",al={"var är mims","hall of mysteries"}}},fp="17,139,16.203.0,11.169.0,25.94.0,27.115.0,33.82.0,36.63.0"}
P.entries["quest:94824"] = {n="Confounding Flash",s="Ett meddelande skickar dig till Ironforge för att tala med High Priestess Mims. Hon har bett dig komma till Hall of Mysteries, men det är ännu oklart varför.",h="Ett meddelande skickar dig till Ironforge för att tala med High Priestess Mims.",kw={"förvirrande blixt","hall of mysteries","high priestess mims","ironforge","tala med mims","kallelse"},sec={{t="En kallelse till Ironforge",b="Vägen framåt leder till Ironforge, där High Priestess Mims väntar i Hall of Mysteries. Du skickas dit för att tala med henne personligen, men meddelandet säger inte varför hon kallat dig. Det gissar att dina bedrifter har gått väl, men låter Mims förklara saken."}},faq={{q="Vem vill tala med mig?",a="High Priestess Mims vill att du kommer och talar med henne i Ironforge.",al={"vem har kallat på mig","mims kallelse","high priestess mims"}},{q="Vart ska jag gå?",a="Du ombeds tala med High Priestess Mims i Hall of Mysteries i Ironforge.",al={"var är mims","var ligger hall of mysteries","åka till ironforge"}},{q="Varför vill Mims träffa mig?",a="Meddelandet förklarar inte varför High Priestess Mims vill tala med dig.",al={"varför kallade mims på mig","vad vill hon","orsak till kallelsen"}},{q="Vad ombeds jag göra?",a="Du ombeds tala med High Priestess Mims i Ironforge.",al={"vad är uppgiften","tala med mims","mims begäran"}}},fp="17,148,19.277.0,27.66.0,14.86.0,29.77.0,28.67.0"}
P.entries["quest:94841"] = {n="Lost Shipping Crate",s="En fraktlåda märkt för Friz Frazzlespark har försvunnit i Riverglades. Etiketten ber att den lämnas tillbaka till Powderfuse Port.",h="En fraktlåda märkt för Friz Frazzlespark har försvunnit i Riverglades.",kw={"låda","friz frazzlespark","etikett","försvunnen fraktlåda","karta","powderfuse port","riverglades"},sec={{t="En märkt låda",b="Friz Frazzlesparks låda har en handskriven etikett med Powderfuse Port i Riverglades som destination. En karta markerar en sydöstra strand norr om ett tempel omgivet av vatten, med bevingade varelser i närheten. Etiketten varnar för att öppna lådan utan uppsikt och anger att Friz ska ta emot den."}},faq={{q="Vem äger fraktlådan?",a="Etiketten anger Friz Frazzlespark som lådans ägare.",al={"lådans ägare","vem äger den"}},{q="Vart ska jag ta lådan?",a="Etiketten säger att lådan ska lämnas tillbaka till Friz Frazzlespark vid Powderfuse Port i Riverglades.",al={"var lådan ska lämnas","lådans leverans"}},{q="Vad står det på lådans etikett?",a="Den anger Friz Frazzlespark och Powderfuse Port, varnar för att öppna lådan utan uppsikt och anger en returplats i Riverglades.",al={"lådans etikett","vad som står på den"}},{q="Är lådan säker att öppna?",a="Etiketten säger att den inte ska öppnas utan uppsikt.",al={"öppna lådan","varning på lådan"}}},fp="19,137,14.300.0,28.55.0,30.94.0,32.153.0,26.50.0"}
P.entries["quest:94863"] = {n="Taming the Beast",s="Taming the Beast är en jägarlektion under Josephine Carsons ledning. Efter att ha lärt sig grunderna i att hantera djur med ett vildsvin måste den blivande jägaren vinna en vildare Gray Forest Wolfs förtroende med en Taming Rod.",h="Taming the Beast är en jägarlektion under Josephine Carsons ledning.",kw={"tämja bestar","gray forest wolf","jägare","jägarträning","josephine carson","taming rod","taming the beast"},ang={["class:Hunter"]="Den här träningen är en viktig övergångsrit för jägare och lär ut det tålamod och den respekt som krävs för att komma i samklang med vilda rovdjur."},sec={{t="Jägarens väg",b="En jägares band till det vilda kräver mer än att bara spåra och skjuta; det fordrar respekt och tålamod för att vinna ett vilt djurs förtroende. Efter att ha visat sina grundläggande färdigheter med vanliga vildsvin ställs blivande jägare inför en betydligt vildare utmaning: att ge sig in i skogen och tämja en Gray Forest Wolf. Under tränaren Josephine Carsons vakande öga får jägaren en förtrollad stav som ska lugna rovdjuret och lära jägaren den känsliga balansen mellan jägare och best."},{t="Ett prov på instinkt och tillit",b="Josephine Carson ger jägaren en särskild Taming Rod, utformad för att kanalisera ett lugnande inflytande så att jägaren kan närma sig farliga vilda djur. Uppgiften kräver tålamod och precision, eftersom vargen måste närmas utan dödligt våld samtidigt som dess naturliga aggressivitet stillas varsamt. När bandet har övats in och jägaren visat sig kunna samspela med bestens själ, lämnas staven tillbaka till Josephine som bevis på växande färdighet i att bemästra det vilda."}},faq={{q="Vad är uppdraget Taming the Beast?",a="Taming the Beast är ett träningsprov för jägare där en tränare ger en blivande jägare i uppgift att spåra upp och tämja en Gray Forest Wolf med hjälp av en förtrollad Taming Rod.",al={"uppdraget taming the beast","uppdrag med gray forest wolf","lektion i att tämja varg"}},{q="Vem ger uppdraget och vem slutför det?",a="Josephine Carson är instruktör för provet. Hon ger dig Taming Rod och bedömer ditt band till skogens djur innan hon tar tillbaka staven när du är klar.",al={"vem ger taming the beast","vem är josephine carson","var lämnar man in taming the beast"}},{q="Vilket djur måste du tämja?",a="Du får i uppgift att tämja en Gray Forest Wolf, en vildare skogspredator än de vildsvin du tränade med tidigare.",al={"vad ska jag tämja","vilken best","målet med taming the beast"}},{q="Vad används Taming Rod till?",a="Taming Rod är ett träningsredskap som Josephine Carson ger dig för att hjälpa en jägarlärling att lugna och knyta ett tillfälligt band till en vild Gray Forest Wolf utan att skada den permanent.",al={"vad gör taming rod","varför använda taming rod","taming rods bakgrund"}},{q="Vilket djur tämjde jägaren före provet?",a="Innan du mötte Gray Forest Wolf visade du dina grundläggande färdigheter i att hantera djur genom att lära dig tämja ett skogsvildsvin.",al={"tidigare lektion i tämjning","vad tämjdes före vargen"}},{q="Behåller du Gray Forest Wolf som en permanent följeslagare?",a="Nej, provet är en avgränsad lektion i att bemästra konsten att knyta band till djur. När du har övat dina färdigheter lämnar du tillbaka Taming Rod till Josephine Carson.",al={"behåller man vargen","är vargen ett permanent husdjur"}}},fp="16,174,22.331.0,28.279.0,35.112.0,35.99.0,34.107.0,32.133.0,43.73.0,58.94.0"}
P.entries["quest:94864"] = {n="Taming the Beast",s="Taming the Beast är höjdpunkten i jägares tidiga träning i Elwynn Forest, under ledning av Josephine Carson. Efter att ha visat att de behärskar vildsvin och vargar får jägarna i uppgift att använda en Taming Rod för att lugna en Young Forest Bear och vinna dess förtroende. Det här sista provet fördjupar jägarens samhörighet med vilddjuren och bevarar skogens naturliga balans genom respekt och skicklighet.",h="Taming the Beast är höjdpunkten i jägares tidiga träning i Elwynn Forest, under ledning av Josephine Carson.",kw={"samhörighet med vilddjur","träning i att tämja vilddjur","elwynn forest","jägaruppdrag","josephine carson","taming rod","taming the beast","young forest bear"},ang={["class:Hunter"]="Det här provet är en avgörande övergångsrit för jägaraspiranter. Det förvandlar enkla spårningsfärdigheter till en djup, empatisk samhörighet med vilddjuren.",["faction:Alliance"]="Skickliga djurmästare stärker Alliansens spejare i vildmarken med disciplinerade följeslagare som kan försvara gårdar och patrullera handelsvägar i Stormwinds områden.",["race:Human"]="För mänskliga jägare som tränar i Elwynn Forest lär tämjandet av traktens vilda djur dem att det är viktigt att samexistera med kungarikets naturliga rovdjur i stället för att bara utrota dem."},sec={{t="Jaktens sista prov",b="Blivande jägare i Elwynn Forest genomgår en krävande träning för att förstå de vilda djur som delar deras marker. Efter att redan ha visat att de kan hantera den listiga vargen och det tåliga vildsvinet ställs jägarna inför ett sista prov på mod och tålamod. Josephine Carson skickar dem för att möta Young Forest Bear, den kraftigaste och mäktigaste av skogens vanliga rovdjur. Den här riten prövar om en jägare kan stå emot björnens råa styrka och vinna dess förtroende i stället för att bara kuva den."},{t="Respekt och balans i Elwynn",b="Lärdomen bakom att tämja djurlivet i Elwynn bygger på respekt, inte herravälde. Skogsbjörnar står för skogens styrka och livskraft och spelar en viktig roll för att upprätthålla den naturliga ordningen. Med en särskilt förberedd Taming Rod lär sig jägarna att stilla vilddjurets aggressivitet och skapa ett äkta band av ömsesidig förståelse. Att lugna ett så mäktigt djur fördjupar jägarens andliga samhörighet med vildmarken och fullbordar grundutbildningen under Carsons ledning."}},faq={{q="Vem ger jägarna det här provet?",a="Josephine Carson ansvarar för det här provet för jägare som tränar i Elwynn Forest. Hon bedömer jägarens framsteg när de har tämjt mindre vilddjur och ger dem vägledning och den Taming Rod som behövs för att tämja skogsbjörnen. När provet är avklarat återlämnar jägarna staven direkt till henne som bekräftelse på att träningen är slutförd.",al={"vem ger taming the beast","uppdragsgivare för taming the beast","josephine carson uppdrag"}},{q="Vilka vilddjur måste tämjas före det här provet?",a="Innan jägarna tar sig an utmaningen att tämja en Young Forest Bear måste de först visa sin skicklighet och sitt tålamod genom att tämja ett vildsvin och en varg. De inledande proven visar att jägaren kan hantera både aggressiva och flocklevande vilddjur innan de möter Elwynns björnars råa styrka.",al={"vilddjur som krävs för att tämja","vad tämjde jag före björnen","vilddjur tämjda före detta"}},{q="Varför skickas jägarna efter en Young Forest Bear?",a="Young Forest Bear står för Elwynn Forests djurlivs styrka och mäktighet. Medan vildsvin och vargar prövar jägarens förmåga att hantera snabba eller uthålliga vilddjur, blir björnen det yttersta provet på uthållighet, respekt och fysiskt mod. Att vinna förtroendet hos ett så mäktigt rovdjur visar att jägaren helt behärskar grunderna i att hantera vilddjur.",al={"varför tämja young forest bear","syftet med young forest bear","varför björnar i elwynn"}},{q="Vad är Taming Rod till för?",a="Taming Rod är ett särskilt träningsredskap som Josephine Carson tillhandahåller för att hjälpa jägare att lugna vilda djur. Den samlar det fokus som krävs för att stilla en aggressiv Young Forest Bear utan att döda den, så att jägaren kan knyta ett fredligt band till den. När provet är över återlämnas staven till Carson, och träningen avslutas.",al={"syftet med taming rod","vad gör taming rod","varför använda taming rod"}},{q="Hur hjälper tämjandet Elwynn Forest?",a="Att tämja vilda djur ses som en viktig del av att bevara den naturliga balansen i Elwynn Forest. Genom att närma sig rovdjur med respekt och återhållsamhet i stället för att jaga ner dem hjälper jägarna till att bevara harmonin mellan det lokala ekosystemet och områdets bosättningar, så att farliga vilddjur leds bort på fredlig väg i stället för att dödas.",al={"varför är balansen i elwynn viktig","balansen i elwynn forest","tämjande och skogens balans"}},{q="Vad innebär det för en jägare att klara den här lektionen?",a="Att klara den här sista uppgiften fördjupar jägarens inneboende samhörighet med vilddjuren. Genom att vinna Elwynns mäktigaste varelses förtroende går jägaren bortom enkla jakttekniker och bemästrar den andliga kontakt som krävs för att skapa livslånga band med djurföljeslagare i hela Azeroth.",al={"vad händer efter att björnen tämjts","slutföra jägarträningen","vad innebär samhörighet med vilddjur"}},{q="Var finns Young Forest Bears?",a="Young Forest Bears strövar omkring i de skogsklädda delarna av Elwynn Forest, där de lever bland de täta träden tillsammans med vargar och spindlar. Jägare som ger sig av från närliggande bosättningar måste spåra dessa kraftiga varelser genom skogens snår för att använda tämjningsstaven och fullgöra Carsons sista order.",al={"var finns young forest bear","var hittar man björnar i elwynn","skogsbjörn i elwynn"}}},fp="16,291,27.363.0,29.396.0,34.219.0,49.184.0,47.224.0,38.240.0,42.245.0,54.219.0,35.246.0"}
P.entries["quest:94873"] = {n="Buying Friendship: Gelkis",s="En främling erbjuder Gelkis Clan en kasse med totemer i Gelkis Village. Deras kvartermästare ser gåvan som hjälp mot Magram Clan.",h="En främling erbjuder Gelkis Clan en kasse med totemer i Gelkis Village.",kw={"köpa vänskap","centaur","gelkis","gelkis clan","gelkis village","magram","molkar","kasse med totemer"},sec={{t="En gåva till Gelkis",b="Någon har gjort i ordning en kasse med totemer som du ska ta till kvartermästaren i Gelkis Village. Gelkis förlorar mark mot Magram, och deras isolering kan göra dem öppna för hjälp utifrån. Gåvan är tänkt att förbättra din ställning hos klanen."}},faq={{q="Varför ta med en kasse med totemer till Gelkis?",a="Gåvan är tänkt att förbättra din ställning hos Gelkis Clan, som förlorar mark mot Magram.",al={"kasse med totemer","varför totemer","gåva till gelkis"}},{q="Vem tar emot kassen?",a="Kvartermästaren i Gelkis Village tar emot kassen.",al={"gelkis kvartermästare","vem får kassen","mottagare av totemer"}},{q="Vilka problem står Gelkis inför?",a="Gelkis ligger illa till mot Magram, vars klan har varit ovanligt grym.",al={"gelkis problem","magram gelkis","varför förlorar de"}},{q="Vem är Molkar?",a="Molkar är kvartermästaren hos Gelkis som tar emot kassen.",al={"molkar gelkis","kvartermästare molkar","vem är molkar"}}},fp="25,137,21.259.0,38.102.0,22.61.0,32.92.0,14.57.0"}
P.entries["quest:94895"] = {n="Lost Shipping Crate",s="Friz Frazzlesparks fraktlåda har försvunnit från Powderfuse Port i Riverglades. Etiketten varnar för att öppna den utan uppsikt, och du ombeds lämna tillbaka den till Friz.",h="Friz Frazzlesparks fraktlåda har försvunnit från Powderfuse Port i Riverglades.",kw={"lådans etikett","lådans karta","friz frazzlespark","försvunnen fraktlåda","powderfuse port","riverglades","varning"},sec={{t="En märkt låda",b="En karta och en varning märker ut lådan du bär genom Riverglades. På etiketten står Friz Frazzlespark och Powderfuse Port, och det står att lådan ska lämnas tillbaka dit om den kommer bort. Du tar tillbaka den till sin ägare."}},faq={{q="Vem äger fraktlådan?",a="På etiketten står det att Friz Frazzlespark äger fraktlådan.",al={"lådans ägare","vem äger den","friz låda"}},{q="Vart ska jag ta lådan?",a="Lådan ska lämnas tillbaka till Friz Frazzlespark vid Powderfuse Port i Riverglades.",al={"vart lämna tillbaka lådan","lådans destination","powderfuse port"}},{q="Vad varnar etiketten för?",a="Etiketten varnar för att manipulera lådan och säger att den inte får öppnas utan uppsikt.",al={"varning på lådan","kan jag öppna den","öppna lådan"}},{q="Vad är utmärkt på lådans karta?",a="Kartan visar en röd cirkel längs en sydöstlig kust, norr om ett illa ritat tempel omgivet av vatten och bevingade varelser.",al={"lådans karta","vad finns på kartan","röd cirkel på kartan"}}},fp="19,188,14.214.0,28.69.0,30.87.0,31.85.0,34.131.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="Aid For The Refugees handlar om de fördrivna överlevande från Ban'aethal, en bosättning djupt inne i Shadowgale Forest som plötsligt evakuerades mitt i natten. När deras hem började falla upp mot himlen och den omgivande vildmarken blev alltför farlig att beträda, förlitar sig flyktingarna på modiga resenärer som kan hämta tillhörigheterna de tvingades lämna kvar.",h="Aid For The Refugees handlar om de fördrivna överlevande från Ban'aethal, en bosättning djupt inne i...",kw={"aid for the refugees","ban'aethal","tillhörigheter","ealaane","flyktingar","shadowgale forest"},sec={{t="En desperat vädjan",b="Aid For The Refugees är en vädjan om hjälp från Ealaane och hennes medfördrivna bybor. De överlevande flydde med knapp nöd från sina hem djupt inne i Shadowgale Forest och har samlats med nästan ingenting kvar, i hopp om att en resenär på genomfart ska våga möta farorna de lämnade bakom sig."},{t="Ban'aethals katastrof",b="Bosättningen Ban'aethal mötte ett ofattbart öde mitt i natten, när byn plötsligt började falla upp mot himlen. Den bisarra och skrämmande katastrofen gav invånarna bara några ögonblick att fly, så de tvingades överge sina personliga ägodelar medan skogen omkring dem blev fientlig och farlig."}},faq={{q="Vem är Ealaane?",a="Ealaane är en flykting från Ban'aethal som flydde tillsammans med andra när bosättningen började rasa samman. Hon ber äventyrare på väg mot Shadowgale Forest att hämta personliga tillhörigheter som lämnats kvar i ruinerna.",al={"vem gav hjälp till flyktingarna","uppdragsgivare för aid for the refugees","ealaane"}},{q="Vad hände med Ban'aethal?",a="Ban'aethal var en bosättning djupt inne i Shadowgale Forest. Invånarna tvingades nyligen evakuera mitt i natten på grund av en plötslig och bisarr katastrof.",al={"vad är ban'aethal","var ligger ban'aethal","byn ban'aethal"}},{q="Varför var byborna tvungna att evakuera Ban'aethal?",a="Evakueringen utlöstes plötsligt mitt i natten, när Ban'aethal började falla upp mot himlen. Byn och den omgivande skogen blev alltför farliga för invånarna att stanna i eller återvända till.",al={"varför evakuera ban'aethal","faller upp mot himlen","katastrofen i ban'aethal"}},{q="Varför ber byborna att någon hämtar deras tillhörigheter?",a="Katastrofen slog till plötsligt mitt i natten och tvingade byborna att fly för sina liv med nästan ingenting. Nu när skogen och ruinerna är fulla av faror förlitar de sig på dugliga äventyrare för att hämta det som lämnades kvar.",al={"varför behövs tillhörigheterna","övergivna tillhörigheter","varför hämta tillhörigheter"}},{q="Vad är Shadowgale Forest?",a="Shadowgale Forest är det skogsområde där bosättningen Ban'aethal ligger. Efter den bisarra katastrofen som slet sönder byn har skogen blivit extremt farlig för vanligt folk.",al={"var ligger shadowgale forest","shadowgale forests historia"}},{q="Kan flyktingarna återvända hem?",a="Nej. Enligt Ealaane är både Shadowgale Forest och ruinerna av Ban'aethal alltför farliga för att de fördrivna invånarna någonsin ska kunna återvända på egen hand.",al={"kan flyktingarna återvända","är ban'aethal säkert"}}},fp="20,237,16.174.0,26.196.0,15.173.0,28.138.0,50.180.0,66.227.0,26.166.0,39.121.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="The Fate of a Loved One är ett uppdrag om Resaan, som gav sig in i de farliga Ruins of Ban'aethal för att leta efter förnödenheter och aldrig återvände. Över en vecka senare ber hans sörjande partner resenärer på väg mot ruinerna att ta reda på vad som hänt honom och föra hem honom eller återfinna hans kära arvegods.",h="The Fate of a Loved One är ett uppdrag om Resaan, som gav sig in i de farliga Ruins of Ban'aethal för att...",kw={"ban'aethal","arvegods","resaan","ruins of ban'aethal","förnödenheter","the fate of a loved one"},sec={{t="En desperat vädjan",b="The Fate of a Loved One kretsar kring en desperat vädjan från någon vars partner, Resaan, gav sig tillbaka in i Ruins of Ban'aethal. Trots innerliga böner om att han skulle stanna kände Resaan sig tvungen att trotsa farorna i ruinerna för att söka efter förnödenheter. Han lämnade någon bakom sig som nu väntar i plågsam ovisshet."},{t="Försvunnen i ruinerna",b="Mer än en vecka har gått sedan Resaan gav sig av, långt längre än man rimligen kunde vänta sig att han skulle vara borta. Resenärer på väg mot Ban'aethal ombeds att leta efter honom bland ruinerna – att leda honom hem om han fortfarande lever, eller att återfinna hans familjearvegods om bara tragedi väntar där."}},faq={{q="Vem är Resaan?",a="Resaan är en person som gav sig tillbaka in i Ruins of Ban'aethal för att samla förnödenheter, trots böner om att han skulle stanna. Efter mer än en vecka utan livstecken fruktar hans älskade att han har mött en tragisk död bland ruinerna.",al={"vem är resaan","var är resaan","hitta resaan"}},{q="Vad är Ruins of Ban'aethal?",a="Ruins of Ban'aethal är en farlig plats dit Resaan gav sig för att söka efter nödvändiga förnödenheter. Hans älskade anser att färden är så farlig att det är osannolikt att någon överlever där ensam i en vecka.",al={"vad är banaethal","ruins of banaethal historia","var ligger banaethal"}},{q="Varför återvände Resaan till Ban'aethal?",a="Resaan återvände till Ban'aethal för att hämta förnödenheter. Han valde att göra den farliga resan trots att hans älskade bad honom att inte ge sig av.",al={"varför återvände resaan","varför är resaan i banaethal"}},{q="Vad ber uppdragsgivaren dig att ta med tillbaka?",a="Om Resaan fortfarande lever ber uppdragsgivaren dig att föra honom hem i säkerhet. Om han har omkommit i ruinerna vädjar uppdragsgivaren om att du återfinner hans personliga arvegods som ett sista minne.",al={"vad vill uppdragsgivaren","vad händer om resaan är död"}},{q="Hur länge har Resaan varit försvunnen?",a="Resaan har varit försvunnen i över en vecka sedan han gav sig in i Ruins of Ban'aethal. Med tanke på områdets faror får den långa tystnaden hans älskade att frukta det värsta.",al={"hur länge har resaan varit försvunnen","hur länge har resaan varit borta"}},{q="Vem erbjuder uppdraget?",a="Uppdraget erbjuds av Resaans sörjande partner eller älskade, som desperat söker visshet och är beredd att be förbipasserande resenärer på väg mot Ban'aethal om hjälp.",al={"vem ger uppdraget the fate of a loved one","uppdragsgivaren i the fate of a loved one"}}},fp="23,187,16.187.0,21.250.0,14.178.0,33.131.0,36.92.0,47.155.0,33.146.0,22.123.0"}
P.entries["quest:949"] = {n="The Twilight Camp",s="The Twilight Camp är ett alliansuppdrag för spaning, riktat mot de hemlighetsfulla kultisterna i lägret kring The Master's Glaive i södra Darkshore. Efter att ha fått en glimt av deras ritualplats i en spåskål måste spanare infiltrera utgrävningen för att ta reda på vad Twilight's Hammer försöker gräva fram.",h="The Twilight Camp är ett alliansuppdrag för spaning, riktat mot de hemlighetsfulla kultisterna i lägret kring...",kw={"darkshore","the master's glaive","onu","spåskål","twilight camp","twilight tome","twilight's hammer"},ang={["class:Druid"]="Att avslöja kultens forskning är avgörande för cenarieväktarna, som försöker hålla korrumperande uråldriga väsen säkert begravda.",["faction:Alliance"]="När kultens märkliga utgrävningar stoppas hindras ett växande hot från att destabilisera norra Kalimdor.",["race:NightElf"]="Twilight's Hammer vanhelgar Kalimdors heliga marker med mörk trolldom, alldeles under grenarna i Darkshores uråldriga lundar."},sec={{t="Undersök utgrävningen",b="The Master's Glaive har länge varit ett olycksbådande, förstenat mysterium bland de klippiga kullarna i södra Darkshore, men Twilight's Hammers plötsliga ankomst gjorde en gammal kuriositet till ett omedelbart hot. Efter att ha spanat in deras befästningar med en spåskål skickas spejare rakt in i lägret för att ta reda på deras verkliga avsikter innan försvarsåtgärder kan sättas in."},{t="Den illustrerade boken",b="En genomsökning av lägret visar att kultisterna inte är några vanliga skattsökare eller banditer. Deras verksamhet styrs av djupa ockulta studier. Långt inne i deras norra läger finns en uråldrig, noggrant handtryckt bok med mästerliga men oroande illustrationer. Texten bevisar att Twilight's Hammer medvetet undersöker den väldiga varelse som ligger begravd under jorden."}},faq={{q="Vad är målet med uppdraget The Twilight Camp?",a="Du måste infiltrera Twilight's Hammers läger nära The Master's Glaive i södra Darkshore och hitta en ledtråd om deras motiv, närmare bestämt en handtryckt ritualbok som finns i lägret.",al={"målet med uppdraget twilight camp","vad gör jag i twilight camp"}},{q="Vem skickar dig för att undersöka lägret?",a="Uppdraget tas emot direkt från spåskålen vid utsiktsplatsen ovanför The Master's Glaive. Det fortsätter undersökningen som inleddes för den uråldrige väktaren Onu.",al={"vem ger twilight camp","uppdragsgivare twilight camp"}},{q="Var i lägret finns ledtråden?",a="Den rätta ledtråden är Twilight Tome, som finns i den norra delen av lägret. Andra böcker i lägret kan vara farliga lockbeten som släpper lös skyddsmagi mot inkräktare.",al={"var finns boken","twilight tome plats","hitta ledtråd twilight camp"}},{q="Varför befinner sig Twilight's Hammer vid The Master's Glaive?",a="Kultisterna är besatta av de Gamla gudarnas uråldriga, mörka krafter och deras tjänare. De gräver ut det väldiga förstenade kadaver som den enorma stenbladet genomborrar, för att studera eller väcka den uråldriga ondska som finns kvar där.",al={"varför är kultister vid masters glaive","twilights hammer syfte darkshore"}},{q="Vad händer när du har hittat boken?",a="När du har hämtat boken får du uppdraget Return to Onu, som ber dig ta med de upptäckta skrifterna norrut till den uråldriga träanten i Grove of the Ancients.",al={"nästa uppdrag efter twilight camp","vart går jag efter twilight tome"}}},fx={["8554815a"]={q="Varför leder skålen för skådning dig till att undersöka lägret?",a="Onus skådarskål visar att Twilight's Hammer-sektmedlemmar har samlats runt The Master's Glaive, där en uråldrig ”gammal herre” föll för länge sedan. Deras syfte är okänt, men Onu är säker på att det är mörkt. Innan han och lundens försvarare kan lägga upp en plan behöver de något från lägret som avslöjar vad sekten tänker göra.",al={"varför undersöka twilight-lägret","skålen för skådningens syfte","varför söka igenom twilight-lägret"}}},fp="17,240,15.204.0,20.195.1,44.149.0,38.146.0,36.119.0,52.204.0,36.121.0"}
P.entries["quest:94911"] = {n="Child of Nature",s="I Thunder Bluff ser en annan Skyborne lovande tecken i dina druidiska konster och hänvisar dig till Turak Runetotem. Han kan lära dig hur du tar dig till Cenarion Circles fäste i Moonglade.",h="I Thunder Bluff ser en annan Skyborne lovande tecken i dina druidiska konster och hänvisar dig till Turak...",kw={"cenarion circle","child of nature","druid","moonglade","skyborne","thunder bluff","turak runetotem"},ang={["class:Druid"]="Som druid hänvisas du till Turak Runetotem i Thunder Bluff, som kan lära dig hur du tar dig till Cenarion Circle i Moonglade.",["race:Skyborne"]="Som Skyborne får du veta att druiderna i Cenarion Circle kommer att välkomna dig och dela med sig av sin kunskap."},sec={{t="En druids välkomnande",b="Din lärare tror att druiderna i Cenarion Circle kommer att välkomna dig och dela med sig av sin kunskap. Turak Runetotem i Thunder Bluff kan visa dig hur du tar dig till deras fäste i Moonglade."}},faq={{q="Vem ska jag tala med?",a="Tala med Turak Runetotem i Thunder Bluff. Han kan lära dig hur du tar dig till Moonglade.",al={"vem ska jag tala med","turak runetotem","vem är turak"}},{q="Var finns Cenarion Circles fäste?",a="Cenarion Circles fäste ligger i Moonglade på Kalimdor.",al={"var finns cirkeln","cenarion circle plats","moonglade"}},{q="Varför skickas jag till Moonglade?",a="Druiderna i Cenarion Circle kan dela med sig av sin kunskap till dig.",al={"varför moonglade","lära sig bli druid","druidträning"}}},fp="15,186,19.189.0,24.85.0,44.63.0,33.69.0"}
P.entries["quest:94912"] = {n="Child of Nature",s="I Stormwind kan Sheldras Moontree visa dig vägen till Moonglade. Där har druiderna i Cenarion Circle visdom att dela med sig av till ett naturens barn.",h="I Stormwind kan Sheldras Moontree visa dig vägen till Moonglade.",kw={"cenarion circle","naturens barn","druid","kalimdor","moonglade","sheldras moontree","skyborne","stormwind"},ang={["class:Druid"]="Som druid hänvisas du till Cenarion Circle, en uråldrig orden vars medlemmar utövar druidernas konster.",["race:Skyborne"]="Som Skyborne är du bland de första av ditt folk som anländer till Azeroth, och du välkomnas."},sec={{t="Ett avlägset fäste",b="Sheldras Moontree, en Night Elf i Stormwind, kan visa dig hur du når Moonglade på Kalimdor. Cenarion Circle har sitt fäste där. Det är en uråldrig orden av naturkännare och druider som har mycket att lära dig."}},faq={{q="Vem är Sheldras Moontree?",a="Sheldras Moontree är en Night Elf i Stormwind som kan visa dig hur du når Moonglade.",al={"sheldras","night elf i stormwind","vem lär mig vägen till moonglade"}},{q="Vad är Cenarion Circle?",a="Cenarion Circle är en uråldrig orden av naturkunniga och utövare av druidernas konster.",al={"cenarion circle","druidorden","naturens cirkel"}},{q="Var ligger Cenarion Circles fäste?",a="Cenarion Circle har sitt fäste i Moonglade på Kalimdor.",al={"cenarions fäste","var ligger moonglade","moonglade"}},{q="Vad kan jag lära mig av Cenarion Circle?",a="Druiderna i Cenarion Circle har mycket visdom att dela med sig av till dig.",al={"cenarions läror","vad kan de lära ut","druidernas visdom"}}},fp="15,149,16.215.0,25.86.0,28.93.0,42.66.0,42.66.0"}
P.entries["quest:94914"] = {n="Moonglade",s="Din lärare öppnar en väg till Moonglade, där Dendrite Starblaze väntar. Där kan du tala med honom om den väg du har slagit in på.",h="Din lärare öppnar en väg till Moonglade, där Dendrite Starblaze väntar.",kw={"björnskepnad","dendrite starblaze","druid","keeper remulos","moonglade","nighthaven","teleportering"},ang={["class:Druid"]="Som druid välkomnas du av din lärare till Moonglade och får lära dig en besvärjelse för att resa dit."},sec={{t="En första lektion",b="Din lärare välkomnar druider till Moonglade. Keeper Remulos vakar över dem som vilar där. Du får Teleport: Moonglade, en besvärjelse som för dig dit när du söker kunskap eller tröst. Din första lektion är att tala med Dendrite Starblaze i Nighthaven om den väg du nu följer."},{t="Björnskepnaden",b="Dendrite Starblaze ser att du redan har bemästrat björnskepnaden. Han ser att du har kommit en bra bit på väg."}},faq={{q="Vem ska jag tala med i Moonglade?",a="Tala med Dendrite Starblaze i Nighthaven om den väg du följer.",al={"vem ska jag tala med","dendrite starblaze","nighthaven druid"}},{q="Hur tar jag mig till Moonglade?",a="Din lärare ger dig Teleport: Moonglade, en besvärjelse som för dig dit.",al={"moonglade teleportering","hur nå moonglade","teleporteringsbesvärjelse"}},{q="Vem vakar över druider i Moonglade?",a="Keeper Remulos vakar över druider som vilar i Moonglade.",al={"keeper remulos","moonglades väktare","vem vaktar moonglade"}},{q="Vad säger Dendrite om mina framsteg?",a="Dendrite ser att du redan har bemästrat björnskepnaden.",al={"björnskepnad","har jag bemästrat björnskepnaden","dendrites svar"}}},fp="9,132,14.290.0,13.112.1,35.70.0,26.75.0,37.57.0,41.72.0"}
P.entries["quest:94946"] = {n="The Magical City of Dalaran",s="En magiker i Valanaar skickar dig från Zephras Isle till Dalaran City, där flera magiker väntar på ditt folk. Staden är en utgångspunkt för att utforska Azeroth, men länderna bortom den kan vara farliga utan förberedelser och erfarenhet.",h="En magiker i Valanaar skickar dig från Zephras Isle till Dalaran City, där flera magiker väntar på ditt folk.",kw={"kult","dalaran","dalaran city","danaaris stargale","magiker","skycutter","valanaar","zephras isle"},ang={["race:Skyborne"]="Som Skyborne reser du från Zephras Isle för att ansluta dig till magikerna som väntar på ditt folks ankomst till Dalaran."},sec={{t="Ankomst till Dalaran",b="Den senaste tidens händelser med kulten håller talaren kvar i Valanaar tills vidare. Flera magiker väntar på ditt folk i Dalaran, så du skickas till bryggan utanför stugan. Där går du ombord på en skycutter med destination Dalaran City.\n\nTala med Danaaris Stargale när du kommer fram. Ditt folk håller fortfarande på att finna sig till rätta i staden, och landet bortom dess trygghet kan visa sig vara farligt."}},faq={{q="Vem väntar i Dalaran?",a="Flera magiker väntar på ditt folks ankomst till Dalaran. När du når staden blir du ombedd att tala med Danaaris Stargale.",al={"magiker i dalaran","vem finns i dalaran","dalarans magiker"}},{q="Var reser jag ifrån?",a="Du reser från Zephras Isle till Dalaran City ombord på en skycutter vid bryggan utanför stugan.",al={"hur kommer man till dalaran","från zephras","skycutter"}},{q="Varför stannar talaren i Valanaar?",a="Den senaste tidens händelser med kulten ändrade talarens planer, så talaren tänker stanna i Valanaar en tid.",al={"varför stanna i valanaar","kulten ändrade planerna","magiker i valanaar"}},{q="Är det säkert utanför Dalaran?",a="Landet bortom Dalaran kan vara farligt utan ordentliga förberedelser och erfarenhet.",al={"säkert utanför dalaran","fara nära dalaran","dalarans utkanter"}}},fp="27,238,18.368.0,26.125.0,23.96.0,39.105.0,27.83.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="'Welcome to Azeroth' markerar Skyborne-resenärernas ankomst till Stormwind, människornas huvudstad, via Skyborne Portal. När de anmäler sig i Stormwind Keep får nykomlingarna ett formellt erkännande och tillstånd av Highlord Bolvar Fordragon att resa fritt i hela Alliansens områden.",h="'Welcome to Azeroth' markerar Skyborne-resenärernas ankomst till Stormwind, människornas huvudstad, via...",kw={"bolvar fordragon","högalv","high order","kirin tor","portal","skyborne","stormwind keep","welcome to azeroth"},ang={["faction:Alliance"]="Highlord Bolvar Fordragon välkomnar formellt High Order på kung Anduin Wrynns vägnar och ger dem tillstånd att fritt färdas genom Alliansens områden.",["race:Skyborne"]="För Skyborne öppnar denna audiens formellt Stormwinds portar och Alliansens områden för högalver som anländer genom portalen."},sec={{t="Ankomst till huvudstaden",b="Resenärerna kliver rakt in i Stormwinds livliga stadskärna genom den mystiska Skyborne Portal. De ska anmäla sig hos människornas ledning och tar sig genom stadens storslagna huvudgator till Stormwind Keep för att presentera sig inför regentskapet."},{t="Audiens hos regenten",b="I den storslagna tronsalen hälsar Highlord Bolvar Fordragon medlemmar av High Order välkomna efter att en budbärare från Kirin Tor har förvarnat honom. Han konstaterar att det var länge sedan högalver vandrade genom Stormwind Keeps salar. Regenten välkomnar dem nådigt som gäster och ger dem fri lejd genom alla Alliansens områden på kungens vägnar."}},faq={{q="Vad handlar det här uppdraget om?",a="'Welcome to Azeroth' är ett introduktionsuppdrag där en resenär går genom Skyborne Portal till Stormwind och presenterar sig för Highlord Bolvar Fordragon i Stormwind Keep.",al={"vad är welcome to azeroth","uppdraget welcome to azeroth"}},{q="Vem är Bolvar Fordragon?",a="Highlord Bolvar Fordragon är regent över Stormwinds tron och styr riket från Stormwind Keep på den unge kungen Anduin Wrynn vägnar, medan kung Varian fortfarande är försvunnen.",al={"vem är bolvar fordragon","stormwinds regent"}},{q="Varför tar Bolvar emot Skyborne?",a="En budbärare från Kirin Tor underrättade Bolvar Fordragon om att medlemmar av High Order skulle anlända. Bolvar välkomnar dem som kronans gäster och ger dem tillstånd att utforska och resa fritt genom Alliansens områden.",al={"varför är skyborne i stormwind","högalver i stormwind"}},{q="Vad är High Order?",a="High Order är den fraktion eller grupp som de Skyborne-högalverna tillhör. Kirin Tor meddelade Stormwinds ledning om deras ankomst.",al={"vem är high order","high orders historia"}},{q="Vart leder Skyborne Portal?",a="Skyborne Portal för resenärer direkt till Stormwind, människornas huvudstad, så att nyanlända kan fortsätta raka vägen till Stormwind Keep och söka audiens hos kronan.",al={"skyborne portals destination","vart leder portalen"}},{q="Får Skyborne vistas i hela Alliansens område?",a="Bolvar Fordragon välkomnar formellt Skyborne som gäster på kungens vägnar och ger dem uttryckligen tillstånd att resa obehindrat genom Alliansens länder.",al={"tillhör skyborne alliansen","skyborne välkomnas av alliansen"}}},fp="18,159,22.196.0,27.336.0,25.120.0,24.159.0,37.190.0,23.130.0,36.163.0,55.129.0"}
P.entries["quest:94962"] = {n="Bloodmaster's Ring",s="En kamp mot Bonegnaw är nästa match på vägen mot att bli mästare i Bloodmaster's Ring. Ogrerna väntar på att se om du kan bjuda dem på en strid värd att se.",h="En kamp mot Bonegnaw är nästa match på vägen mot att bli mästare i Bloodmaster's Ring.",kw={"bloodmaster","bloodmaster's ring","bonegnaw","match","mästare","kamp","ogrer"},sec={{t="Nästa match",b="Dina segrar har ännu inte gjort dig till mästare, och Bloodmaster har en ny strid i åtanke. Han utser Bonegnaw till din motståndare och lovar en överraskning. Ogrerna tittar på, och nästa match ska underhålla dem."},{t="Efter kampen",b="Bloodmaster är missnöjd med hur matchen får honom att framstå. Ogrerna verkar däremot roade, och han varnar dig för att vara stolt över utgången."}},faq={{q="Vem är min motståndare?",a="Bonegnaw är din motståndare i Bloodmaster's Ring.",al={"kamp mot bonegnaw","vem slåss jag mot"}},{q="Är jag mästare än?",a="Bloodmaster säger att dina segrar ännu inte har gjort dig till mästare.",al={"bloodmaster mästare","bli mästare"}},{q="Vem tittar på kampen?",a="Ogrer tittar på matchen i Bloodmaster's Ring.",al={"ogrer tittar på","vem är road"}}},fp="18,170,13.221.0,15.156.1,19.52.0,20.64.0,26.54.0"}
P.entries["quest:94964"] = {n="Bloodmaster's Ring",s="En utropare kallar in dig för att möta Mog’thar i Bloodmaster’s Ring. Publiken väntar på nästa utmanare.",h="En utropare kallar in dig för att möta Mog’thar i Bloodmaster’s Ring.",kw={"utropare","bloodmaster’s ring","utmanare","publik","mog’thar","ring"},sec={{t="Nästa utmanare",b="Utroparen har hållit publiken på helspänn och presenterar nu Mog’thar som nästa utmanare. Du kallas in i Bloodmaster’s Ring, där publiken väntar på att se vad som händer."}},faq={{q="Vem möter jag i Bloodmaster’s Ring?",a="Du kallas in för att möta Mog’thar i Bloodmaster’s Ring.",al={"möta mog’thar","vem är nästa utmanare","motståndare i bloodmaster’s ring"}},{q="Vad säger utroparen om Mog’thar?",a="Utroparen säger att Mog’thar är inget att ta lätt på.",al={"vem är mog’thar","nästa utmanare","är mog’thar ett skämt"}},{q="Varför skickas jag in i ringen?",a="Utroparen vill hålla publikens entusiasm uppe genom att presentera ännu en utmanare.",al={"varför möta mog’thar","orsak till ringkampen","vad vill utroparen"}}},fp="18,123,18.181.0,42.62.0,45.41.0,34.91.0"}
P.entries["quest:94978"] = {n="Taming the Beast",s="Quel'ana Quickgale lär dig om bandet mellan djur och mästare. Du börjar med att tämja en Windsong Crawler nära vattnet på Zephras.",h="Quel'ana Quickgale lär dig om bandet mellan djur och mästare.",kw={"djurtämjning","quel'ana quickgale","taming rod","taming the beast","valanaar","windsong crawler","zephras"},sec={{t="Det första bandet",b="Du har Taming Rod och en Windsong Crawler att tämja. Hitta en nära en vattensamling och öva på dina färdigheter. Lämna sedan tillbaka staven till Quel'ana Quickgale i Valanaar. Den här varelsen är ditt första steg mot mästerskap."}},faq={{q="Vad ber Quel'ana mig att tämja?",a="Quel'ana ber dig att tämja en Windsong Crawler nära en vattensamling på Zephras.",al={"vilket djur","mål för tämjning","crawler uppdrag"}},{q="Vad används Taming Rod till?",a="Du använder Taming Rod för att tämja en Windsong Crawler.",al={"hur staven fungerar","tämjningsverktyg","stavuppdrag"}},{q="Var hittar jag en Windsong Crawler?",a="Windsong Crawlers lever nära vattensamlingar på Zephras.",al={"crawler plats","var finns crawler","zephras djur"}},{q="Vem gav mig Taming Rod?",a="Quel'ana Quickgale ger dig Taming Rod i Valanaar.",al={"uppdragsgivare","vem är quelana","quelana quickgale"}},{q="Varför lär jag mig att tämja ett djur?",a="Att lära sig om bandet mellan djur och mästare är det första steget mot att bemästra din klass.",al={"varför tämja crawler","bemästra djur","första tämjningen"}}},fp="16,132,10.215.0,34.77.0,27.50.0,35.55.0,27.56.0,34.90.0"}
P.entries["quest:94979"] = {n="Taming the Beast",s="I Gustberry Lowlands ber Quel'ana Quickgale dig att tämja en galestrider. Din skicklighet i öppen terräng förbereder dig för kommande prövningar.",h="I Gustberry Lowlands ber Quel'ana Quickgale dig att tämja en galestrider.",kw={"galestrider","gustberry lowlands","ornery galestrider","quel'ana quickgale","taming rod","taming the beast","valanaar","zephras"},sec={{t="Över slätterna",b="Du har redan visat att du kan tämja flodens krypare. Nu ger Quel'ana Quickgale dig en Taming Rod och skickar dig till låglandet i Zephras. Där springer en stolt, bevingad galestrider snabbt över slätterna. Vinn dess förtroende och öva på din färdighet. Ta sedan med staven tillbaka till Quel'ana i Valanaar."}},faq={{q="Vad vill Quel'ana att jag ska tämja?",a="Quel'ana ber dig att tämja en Ornery Galestrider i Gustberry Lowlands.",al={"tämja vad","tämja galestrider","vilket djur"}},{q="Var hittar jag en galestrider?",a="Du hittar Ornery Galestrider i Gustberry Lowlands, på slätterna i Zephras.",al={"var finns galestrider","galestrider plats","var finns låglandet"}},{q="Vad används Taming Rod till?",a="Quel'ana ger dig Taming Rod så att du kan tämja en Ornery Galestrider.",al={"taming rod användning","vad används staven till","hur tämja djur"}},{q="Vem gav mig det här uppdraget?",a="Quel'ana Quickgale i Valanaar ber dig att tämja en Ornery Galestrider och ta med Taming Rod tillbaka.",al={"vem skickade mig","vem är quelana","quickgale"}}},fp="16,138,17.298.0,35.74.0,32.88.0,27.72.0,28.100.0"}
P.entries["quest:95"] = {n="Sven's Revenge",s="Drivna av sorg och hämnd ber eremiten Sven Yorgen resenärer att återvända till hans förstörda gård i södra Duskwood. Medan han i åratal förföljde de skuggiga ryttarna som slaktade hans familj, begravde en misstänkt gestalt något nära hans lada som kan ge svar.",h="Drivna av sorg och hämnd ber eremiten Sven Yorgen resenärer att återvända till hans förstörda gård i södra...",kw={"dark riders","deadwind pass","duskwood","hög med lös jord","stubbe","sven yorgen","svens hämnd","the yorgen farmstead"},ang={["class:Paladin"]="Den våldsamma slakten på oskyldiga utförd av ondskefulla krafter från Deadwind Pass kräver rättmätig vedergällning och rättvisa för de döda.",["faction:Alliance"]="Slakten på familjen Yorgen är ännu ett tecken på Duskwoods isolering och visar hur långt mörka krafters räckvidd sträcker sig utan regelbundna patruller från Stormwinds armé."},sec={{t="Tragedin på gården",b="Sven Yorgen var en gång en enkel bonde som brukade jorden i sydöstra Duskwood. Hans liv slogs i spillror när huvtäckta Dark Riders red ner från Deadwind Pass och angrep hans hem, där de massakrerade hans familj medan han var borta. När Sven återvände till massakern fick han syn på en okänd gestalt som smög omkring nära ladan och frenetiskt begravde något i marken. Sven valde hämnden och gav sig genast av för att jaga mördarna, medan det som hade gömts blev kvar."},{t="Hemligheter grävs fram",b="Nu har Sven slagit läger i de västra kullarna och är uppslukad av vrede. Han behöver någon som återvänder till Yorgen Farmstead. Bakom en gammal trädstubbe mellan bondgården och den förstörda ladan ligger en hög löst hopskottad jord. Att hitta det som begravts där är första steget mot att förstå varför de skuggiga ryttarna över huvud taget gav sig på en stillsam bonde i Duskwood."}},faq={{q="Vem är Sven Yorgen?",a="Sven Yorgen var en vanlig bonde som bodde i sydöstra Duskwood, nära gränsen till Deadwind Pass. Efter att ha kommit hem och funnit sin familj mördad av illavarslande ryttare övergav han sin gård och blev en enstöring, besatt av att hämnas på de skyldiga.",al={"vem är sven","sven bakgrund","svens historia"}},{q="Vad hände med Svens gård?",a="Svens gård överfölls av de mystiska Dark Riders som kom från Deadwind Pass. De slaktade hela hans familj och lämnade gården i ruiner innan Sven hann återvända och försvara dem.",al={"tragedin på yorgen farmstead","vad hände med svens gård","varför är svens gård förstörd"}},{q="Vem begravde något bakom ladan?",a="Strax efter massakern såg Sven en skuggig gestalt som lurade nära hans lada och begravde ett föremål. Sven flydde ut i vildmarken för att jaga Dark Riders innan han hann fånga främlingen eller gräva upp det som gömts.",al={"vem begravde föremålet","skuggig gestalt vid svens gård","vem grävde jordhögen"}},{q="Var ligger jordhögen?",a="Jordhögen finns vid Yorgen Farmstead i sydöstra Duskwood, begravd precis bakom en gammal trädstubbe mellan ladan och den förstörda bondgården.",al={"var ligger jordhögen","jordhögens plats","var finns stubben"}},{q="Vilka är Dark Riders?",a="Dark Riders är hotfulla, huvtäckta ryttare som rider ut från Deadwind Pass. Lite är känt om deras ursprung, men deras våldsamma räder i Duskwood lämnar bara död och förödelse efter sig.",al={"vad är dark riders","dark riders bakgrund","ryttarna från deadwind pass"}},{q="Varför grävde inte Sven upp det begravda föremålet själv?",a="När Sven återvände hem och såg gestalten begrava föremålet var han uppslukad av sorg och förföljde genast de flyende Dark Riders. När han väl hade upprättat sitt gömda läger var gården övertagen och alltför smärtsam för honom att återvända till.",al={"varför undersökte inte sven jorden","varför gav sven sig av"}}},fx={e064b97c={q="Varför vill Sven Yorgen att det begravda föremålet hämtas?",a="Sven söker hämnd för sin familjs brutala slakt, utförd av de mystiska Dark Riders of Deadwind Pass. När han upptäckte massakern såg han en skuggfigur skyndsamt begrava något nära sin lada innan den flydde. Driven av vrede och behovet av svar tror Sven att det som ligger under jorden kan avslöja varför hans gård blev måltavla och vem som hjälpte till att förgöra hans familj.",al={"varför vill sven ha det här","sven yorgens motiv","varför hämnduppdraget åt sven"}}},fp="14,234,24.320.0,18.307.0,19.181.0,29.133.0,37.168.0,41.140.0,24.145.0,47.164.0"}
P.entries["quest:950"] = {n="Return to Onu",s="Return to Onu är ett alliansuppdrag som avslutar en inledande undersökning av kultisterna som slagit läger längs Darkshores kust. Efter att ha plundrat kultisternas läger och försökt läsa Twilight Tome återfår en äventyrare en enda sida med vansinniga krumelurer, som ska lämnas till kunskapens forntida Onu i Grove of the Ancients.",h="Return to Onu är ett alliansuppdrag som avslutar en inledande undersökning av kultisterna som slagit läger...",kw={"darkshore","grove of the ancients","insane scribbles","gamla gudar","onu","twilight tome","twilight's hammer"},ang={["class:Druid"]="Krumelurernas kaotiska, onaturliga resonans är en kränkning av den naturliga ordning som druiderna, tillsammans med treanter som Onu, tjänar för att bevara.",["faction:Alliance"]="Genom att undersöka kultens verksamhet längs Darkshores kust ser man till att nattalvboplatser som Auberdine förblir skyddade mot dolda hot.",["race:NightElf"]="Mörka kultisters vanhelgande av Darkshores stränder hotar balansen som kunskapens Ancients vakar över. Därför är Onus varningar djupt personliga för kaldorei."},sec={{t="En glimt av vansinne",b="När någon upptäcker Twilight Tome i Twilight's Hammer-lägret och blickar in bland dess blad, utsätts sinnena genast för ett angrepp. Den skrivna texten böljar och dansar över pergamentet, och utsirade ornament förvandlas till groteska gestalter. Den mentala påfrestningen är så överväldigande att en dödlig hjärna bara klarar av att slita loss en enda sida med nedklottrade anteckningar innan den dukar under för yrsel."},{t="Forntida misstankar",b="När Onu får sidan känner den väldige Ancient av den onaturliga aura som genomsyrar pappersbiten. Pergamentet utstrålar kaotisk, uråldrig magi, som Onu direkt kopplar till de forntida, skuggfyllda krafter som ligger begravda under jorden. Krumelurerna är svåra att tyda, men de bekräftar att Twilight's Hammer i Darkshore inte bara ägnar sig åt röveri, utan ingår i en djupare, hädisk plan."}},faq={{q="Vad är sidan som tagits ur Twilight Tome?",a="Sidan, som helt enkelt kallas Insane Scribbles, är ett avrivet blad ur kultens heliga bok. Den orsakar svår psykisk plåga för den som betraktar den, eftersom skriften vrider sig till groteska, skiftande mönster knutna till uråldrig tomrumsmagi.",al={"insane scribbles","vad är krumelurerna","sida ur twilight tome"}},{q="Vem är Onu?",a="Onu är en kunskapens Ancient, rotad i Grove of the Ancients i södra Darkshore. Han är en äldre väktare och lärd som vägleder nattalver och allierade i Alliansen mot nya förruttnelser i skogen.",al={"vem är onu","onu darkshore","treant onu"}},{q="Vad får Onu veta av krumelurerna?",a="Onu känner kaotiska, uråldriga energier strömma från sidan och identifierar inflytandet från forntida, illvilliga väsen. Skrifterna antyder att kultisterna i Twilight's Hammer aktivt söker efter relikplatser och begravda krafter i hela Darkshore.",al={"vad upptäckte onu","krumelurernas betydelse"}},{q="Varför är Twilight's Hammer i Darkshore?",a="Kulten har dragits till Darkshore för att gräva ut ruinerade alvplatser och hitta spår av forntida krafter knutna till uråldrigt mörker och de gamla gudarna. De använder landets kaos för att dölja sina ritualer.",al={"kultister i darkshore","varför är twilight hammer här"}},{q="Vart leder undersökningen härnäst?",a="Efter upptäckten av kultens närvaro riktar Onu uppmärksamheten mot de forntida alvruinerna i Mathystra i norr och uppmanar äventyrare att säkra forntida reliker innan kultisterna kan lägga beslag på dem.",al={"vilket uppdrag kommer härnäst","nästa efter return to onu"}},{q="Varför orsakar det yrsel att läsa boken?",a="Twilight Tome är inskriven med mörk, vansinnesframkallande magi av tomrum och kaos. Glyferna förvirrar aktivt dödliga sinnen och orsakar hallucinationer och svimningsanfall för att hindra utomstående från att avslöja deras hemligheter.",al={"varför ger boken yrsel","twilight tomes effekter"}}},fp="13,134,22.216.0,18.276.1,46.130.0,11.190.0,39.209.0,42.194.0,40.157.1,42.166.0"}
P.entries["quest:95033"] = {n="On the Other Side",s="Tan'jani skickar dig till Camp Mojache i Feralas för att söka hjälp hos Witch Doctor Uzer'i. Uzer'i är känd för sin magi, men är också jägare.",h="Tan'jani skickar dig till Camp Mojache i Feralas för att söka hjälp hos Witch Doctor Uzer'i.",kw={"camp mojache","feralas","jägare","magi","på andra sidan","tan'jani","witch doctor uzer'i"},sec={{t="Tan'janis vän",b="I Feralas ligger Camp Mojache, där du hittar Witch Doctor Uzer'i, en gammal vän till Tan'jani. Tan'jani säger att Uzer'i arbetar med magi, men också är jägare. Du skickas för att tala med honom och lämnar de vidsträckta, öppna slätterna bakom dig."}},faq={{q="Vem skickade mig till Uzer'i?",a="Tan'jani skickar dig till Witch Doctor Uzer'i, en gammal vän.",al={"tan'jani skickade mig","vem är gamle tanjani"}},{q="Var hittar jag Uzer'i?",a="Witch Doctor Uzer'i finns i Camp Mojache i Feralas.",al={"uzer'is plats","var finns häxdoktorn"}},{q="Varför skickas jag till Uzer'i?",a="Tan'jani säger att Uzer'i söker hjälp och ber dig tala med honom.",al={"varför tala med uzeri","vad vill tanjani"}},{q="Vad gör Uzer'i?",a="Witch Doctor Uzer'i arbetar med magi och är också jägare.",al={"uzeris yrke","häxdoktor jägare"}}},fp="17,137,17.228.0,22.57.0,24.50.0,30.72.0,20.58.0"}
P.entries["quest:95034"] = {n="The Debt",s="Lumina Windsinger i The Sepulcher berättar om attacken som lämnade Banon svårt sårad. Enligt henne var det en worgen som överföll dem på vägen.",h="Lumina Windsinger i The Sepulcher berättar om attacken som lämnade Banon svårt sårad.",kw={"banon","gnoller","lumina windsinger","attack på vägen","the sepulcher","the debt","worgen"},sec={{t="Ett sår på vägen",b="Lumina Windsinger i The Sepulcher berättar för dig vad som hände på vägen. En jättelik, varglik worgen anföll hennes sällskap och dödade dess vakter. Banon ställde sig mellan varelsen och Lumina, som drev bort den med en besvärjelse. Då hade Banon redan blivit svårt biten. Han uppmanade henne att lämna honom, men hon stannade, och de två haltade vidare innan gnoller hittade dem."},{t="Banons sista ögonblick",b="Banon i The Sepulcher genomborrades av många gnollklingor innan han vände sig mot Lumina. Hon såg att han fortfarande kände igen henne, trots att han inte kunde behärska sig. Lumina tror att worgenen beseglade hans öde och svär att döda den så att den inte kan utsätta någon annan levande varelse för samma fasa."}},faq={{q="Vem anföll Lumina och Banon på vägen?",a="En jättelik, varglik worgen anföll Lumina och Banon på vägen.",al={"vad anföll dem","worgenattack","angripare på vägen"}},{q="Vad hände med vakterna?",a="Worgenen dödade vakterna som följde med Lumina och Banon.",al={"vakternas öde","vad hände med vakterna","vakter på vägen"}},{q="Hur drev Lumina bort worgenen?",a="Lumina lyckades kasta en besvärjelse som skrämde worgenen och fick den att fly.",al={"hur fick worgenen att fly","luminas besvärjelse","vad skrämde den"}},{q="Varför blev Banon biten?",a="Banon kastade sig i vägen för worgenen för att skydda Lumina, och varelsen bet honom svårt.",al={"banons bett","hur skadades banon","vad hände med banon"}},{q="Var berättar Lumina för dig vad som hände?",a="Lumina Windsinger ger dig sin berättelse i The Sepulcher.",al={"var finns lumina","luminas plats","the sepulcher"}}},fp="8,160,19.344.0,20.277.1,42.64.0,28.66.0,36.78.0,21.91.0,41.57.0"}
P.entries["quest:95036"] = {n="A Moon-Kissed Blade",s="Trevan varnar dig för att worgen hotar Silverpine Forest. Old Fire-Eye trotsar döden genom okänd magi, och Trevan ber dig ta reda på vad som krävs för en särskild klinga.",h="Trevan varnar dig för att worgen hotar Silverpine Forest.",kw={"a moon-kissed blade","material till klingan","old fire-eye","silverpine forest","särskilt vapen","trevan","worgen"},sec={{t="En smeds lista",b="Old Fire-Eye är den worgen som anföll Trevan och hans följeslagare. Trevan ska ge dig en lista över material till ett vapen mot honom. Materialen är insamlade, och Trevan tror att han känner en smed som kan smida klingan."}},faq={{q="Vem är Old Fire-Eye?",a="Old Fire-Eye är den största och elakaste av alla worgen. Han anföll Trevan och hans följeslagare.",al={"old fire-eye","fire eye worgen","stor worgen"}},{q="Varför kommer Old Fire-Eye tillbaka gång på gång?",a="Okänd magi hindrar Old Fire-Eye från att förbli död.",al={"varför dör inte fire-eye","old fire eye magi","worgen som inte förblir död"}},{q="Vad behöver Trevan från mig?",a="Trevan ska ge dig en lista över material som behövs för att smida ett särskilt vapen.",al={"vad vill trevan","trevans lista","material till klingan"}},{q="Varför behövs en särskild klinga?",a="Old Fire-Eye trotsar döden genom okänd magi. Trevan säger att ett särskilt vapen behövs för att döda honom.",al={"moon kissed blade varför","vapen mot old fire-eye","döda fire eye"}},{q="Vem kan smida klingan?",a="Trevan tror att han känner en smed som kan smida klingan.",al={"smed till klingan","vem tillverkar moon blade","klingans smed"}}},fp="19,170,14.223.0,20.93.0,39.51.0,30.74.0,30.105.0,24.55.0"}
P.entries["quest:95041"] = {n="Data Hoarders",s="Data Hoarders är ett uppdrag från Jemma Quikswitch, en förvisad gnom som bor i Ironforge. Under den desperata evakueringen av Gnomeregan kopierade hon familjens mest värdefulla arkiv till hålkort, men tappade flera i de iskalla drivorna utanför stadsportarna. Att återfinna de förlorade datakorten innebär att rädda allt från avancerade ritningar till örlogsfartyg till oersättliga familjerecept.",h="Data Hoarders är ett uppdrag från Jemma Quikswitch, en förvisad gnom som bor i Ironforge.",kw={"data hoarders","dun morogh","gnomeregan","ironforge","jemma quikswitch","hålkort","andra kriget","ubåtsskrov"},ang={["faction:Alliance"]="Alliansen förlitar sig i hög grad på gnomisk uppfinningsrikedom. Genom att hjälpa fördrivna flyktingar att bevara krigstidens ingenjörsritningar ser du till att värdefull teknisk kunskap inom Alliansen inte går förlorad för alltid.",["profession:Cooking"]="Bland ritningar i världsklass finns också Grandma Quikswitchs personliga chilirecept, ett bevis på att god mat har lika stort känslovärde som militär vetenskap.",["profession:Engineering"]="Ingenjörer kan uppskatta det stora värdet som göms på dessa kort, med autentiska ritningar till ubåtsskrov från Andra kriget och komplexa arkanotekniska ekvationer.",["race:Gnome"]="För gnomiska äventyrare handlar återhämtningen av hålkorten om att bevara kulturen och se till att viktiga uppfinningar och familjeminnen inte går förlorade i hemlandets radioaktiva ruiner."},sec={{t="En jakt i snön",b="När trogginvasionen och den efterföljande strålningskatastrofen tvingade gnomerna att lämna Gnomeregan flydde tusentals med de ägodelar de kunde få med sig i kaoset. Jemma Quikswitch tog det förnuftiga steget att skriva ner generationer av familjekunskap på fysiska hålkort. Tragiskt nog läckte flera viktiga kort ut ur en skadad väska och ner i snöfälten kring den fallna staden. Utan de saknade hålkorten blir de återstående uppgifterna obegripligt nonsens, och familjens intellektuella arv riskerar att gå förlorat."},{t="Ekvationer och chili",b="Gnomernas dataarkiv speglar den märkliga bredden i deras civilisations prioriteringar. Familjen Quikswitchs handlingar innehåller avancerade arkanotekniska fältekvationer, viktiga ritningar till ubåtsskrov från Andra kriget och Grandma Quikswitchs hemliga chilirecept. För en utomstående kan det verka märkligt att blanda militär ingenjörskonst med matlagning, men för flyktingarna i Ironforge är det lika viktigt att bevara hemtrevnaden som att bevara tekniska underverk."}},faq={{q="Vem är Jemma Quikswitch?",a="Jemma Quikswitch är en gnomisk flykting som lyckades undkomma Gnomeregans fall och nu bor tryggt bland dvärgarnas salar i Ironforge.",al={"jemma quikswitch","vem ger data hoarders","uppdragsgivare data hoarders"}},{q="Vilka uppgifter finns på de förlorade korten?",a="Hålkorten innehåller familjen Quikswitchs arkiv, däribland arkanotekniska ekvationer, ritningar till ubåtsskrov från Andra kriget och Grandma Quikswitchs chilirecept.",al={"vad är hålkorten","vad fanns på korten","quikswitchs arkiv"}},{q="Var tappades datakorten?",a="De gled ut genom ett hål i Jemmas packning när hon flydde från Gnomeregan och ligger begravda i den snötäckta terrängen utanför portarna till den underjordiska staden i Dun Morogh.",al={"var finns korten","datakortens plats","var tappade hon dem"}},{q="Varför kan Jemma inte läsa de kort som finns kvar utan de saknade?",a="Jemma säger att uppgifterna är för oordnade för att kunna återställas utan de saknade hålkorten. Uppdraget förklarar inte hur korten kodar eller organiserar informationen.",al={"varför behövs alla kort","oordnade uppgifter","hålkortens data"}},{q="Vilken roll hade gnomerna med ubåtar under Andra kriget?",a="Under Andra kriget bidrog gnomerna stort till Alliansens krigsinsats med avancerad ingenjörskonst. De konstruerade och styrde särskilt undervattensfarkoster för att bekämpa Hordens sjöstridskrafter.",al={"gnomiska ubåtar andra kriget","ubåtsskrovets ritningar"}},{q="Varför bor gnomiska flyktingar i Ironforge?",a="Efter att Gnomeregan plötsligt föll för trogginvasionen och den katastrofala strålningen flydde de överlevande gnomerna sitt underjordiska hem. King Magni Bronzebeard erbjöd dem en fristad i den närliggande dvärgstaden Ironforge.",al={"varför är gnomer i ironforge","gnomer som bor med dvärgar"}}},fp="13,256,22.294.0,19.259.0,24.95.0,38.177.0,34.125.0,66.158.0,65.158.0,45.172.0"}
P.entries["quest:95042"] = {n="Seeking the Kor Gem",s="I Ashenvale ser Ulric Frostveil ditt sökande efter en Kor Gem som en välbekant uppgift för besvärjare i Alliance. Han visar dig norrut till Blackfathom Deeps, där naga fortfarande använder ädelstenarna.",h="I Ashenvale ser Ulric Frostveil ditt sökande efter en Kor Gem som en välbekant uppgift för besvärjare i...",kw={"ashenvale","blackfathom deeps","forsaken","kor gem","naga","ulric frostveil"},sec={{t="En ädelsten i Ashenvale",b="Ulric ber dig att hämta en Kor Gem åt honom från ruinerna i Blackfathom Deeps, norr om Ashenvale. Nagorna där nere använder fortfarande ädelstenarna. De kan förstärka magiska vapen och redskap, men Ulric varnar dig för att gå ensam."},{t="Ulrics intresse",b="Ulric Frostveil känner igen fördärvet i ädelstenen. Han säger att han kan skingra ondskan som nagahäxorna har ingjutit i den. Sedan frågar han om du skulle sälja den till honom för hans akademiska studier."}},faq={{q="Vem är Ulric Frostveil?",a="Ulric Frostveil är en Forsaken i Ashenvale som ber dig att hämta en Kor Gem åt honom.",al={"ulric frostveil","vem är ulric","forsaken i ashenvale"}},{q="Var kan jag hitta en Kor Gem?",a="Ulric hänvisar dig norrut till Blackfathom Deeps, där nagorna fortfarande använder Kor Gems.",al={"kor gem plats","var finns ädelstenen","blackfathom ädelsten"}},{q="Vad används Kor Gems till?",a="Kor Gems kan förstärka magiska vapen och redskap.",al={"kor gem användning","ädelsten magi","vad gör kor gem"}},{q="Varför vill Ulric ha en Kor Gem?",a="Ulric ber dig att hämta en Kor Gem åt honom. Han säger att den kan vara av värde för hans akademiska studier.",al={"ulric vill ha ädelsten","varför ädelsten","frostveil ädelsten"}},{q="Vilka använder fortfarande Kor Gems?",a="Nagorna i Blackfathom Deeps använder fortfarande Kor Gems.",al={"naga ädelstenar","vilka använder kor gems","blackfathom naga"}}},fp="19,177,18.215.0,16.190.1,23.79.0,27.76.0,27.52.0,30.89.0,24.49.0"}
P.entries["quest:95059"] = {n="Frazzlespark's Crate",s="En goblin har en leverans till Knight Commander Demar Brant vid Farholde Keep. Du ombeds bära Frazzlespark's Crate till honom, men goblinens syfte hänger samman med folkets trygghet och framgång.",h="En goblin har en leverans till Knight Commander Demar Brant vid Farholde Keep.",kw={"låda","demar brant","farholde keep","frazzlespark","frazzlesparks låda","goblinleverans","riddarkommendör"},sec={{t="En leverans till borgen",b="Frazzlespark skickar dig sydväst till Farholde Keep, där Knight Commander Demar Brant väntar. Lådan är avsedd för honom, och goblinen insisterar på att använda hans fullständiga namn. Du bär leveransen till borgen av skäl som rör goblinernas folks trygghet och framgång."}},faq={{q="Vem väntar på lådan?",a="Knight Commander Demar Brant väntar på Frazzlespark's Crate vid Farholde Keep.",al={"vem vill ha lådan","demar brant leverans"}},{q="Vart ska jag ta Frazzlespark's Crate?",a="Ta Frazzlespark's Crate till Knight Commander Demar Brant vid Farholde Keep, sydväst om Frazzlespark.",al={"lådans plats","var ligger farholde keep"}},{q="Varför vill Demar att hans fullständiga namn används?",a="Frazzlespark påpekar att Demar alltid får goblinen att använda hans fullständiga namn, men anger ingen anledning.",al={"demars fullständiga namn","varför riddarkommendör"}},{q="Varför kallar Frazzlespark det en specialleverans?",a="Frazzlespark kallar det en specialleverans och säger att Demar Brant väntar på den vid Farholde Keep.",al={"låda leverans","vad är speciellt med lådan"}},{q="Varför är den här leveransen viktig?",a="Frazzlespark säger att vissa affärer måste skötas för att trygga goblinernas folks säkerhet och framgång.",al={"varför leverera lådan","goblinernas trygghet"}}},fp="20,205,19.286.0,29.82.0,37.102.0,39.95.0,49.98.0,30.104.0"}
P.entries["quest:95065"] = {n="Fishin' Time",s="Vid Stormwind Harbor börjar Gilbert Gray få slut på bete, just när fisken nappar. Han ber förbipasserande hämta mer från en butik längs stadens kanaler.",h="Vid Stormwind Harbor börjar Gilbert Gray få slut på bete, just när fisken nappar.",kw={"kanaler","catherine leland","fishin time","gilbert gray","nattkrypare","glänsande prydnad","stormwind harbor","trade district"},ang={["faction:Alliance"]="Som medborgare i alliansen bidrar du till livet och moralen i Stormwind genom att hjälpa Gilbert Gray med ett vardagligt behov.",["race:Human"]="Som människa med Stormwind som hem ger du en äldre person en paus från rikets politik genom att hjälpa honom njuta av en stillsam fiskestund."},sec={{t="En dag vid vattnet",b="Gilbert Gray tillbringar lugna dagar med att fiska vid Stormwind Harbors kant. Han håller ögonen på flötet, men när fisken nappar kan betesburken snabbt bli tom. När förrådet är slut och fisken fortfarande nappar ber den äldre fiskaren förbipasserande att hämta mer."},{t="Fiskegrejer vid kanalerna",b="Catherine Leland driver en fiskebutik längs stenkantade kanaler, strax väster om Trade District. Hon förser fiskare i hela Stormwind med drag och bete, däribland stamkunder som Gilbert Gray."}},faq={{q="Vem är Gilbert Gray?",a="Gilbert Gray är en äldre fiskare vid Stormwind Harbor. Han tillbringar dagarna med att kasta ut linan i havet och ber förbipasserande hämta bete och drag när förrådet börjar sina.",al={"gilbert gray","gamle gray","vem ger uppdraget"}},{q="Vem är Catherine Leland?",a="Catherine Leland driver en fiskebutik längs stadens kanaler, strax väster om Trade District. Hon säljer fiskeutrustning och bete till Stormwinds fiskare.",al={"catherine leland","fiskeförsäljare stormwind","leland stormwind"}},{q="Var fiskar Gilbert Gray?",a="Gilbert Gray fiskar vid Stormwind Harbor, där han njuter av den öppna utsikten över havet.",al={"gilbert gray plats","var är gilbert gray","fiskare vid hamnen"}},{q="Vilka förnödenheter behöver Gilbert Gray?",a="Gilbert Gray behöver nattkrypare som bete och en glänsande prydnad som drag. Catherine Leland säljer båda längs kanalerna.",al={"uppdragsföremål fishin time","vilket bete vill gray ha"}},{q="Varför hämtar inte Gilbert Gray förnödenheterna själv?",a="Fisken nappar, och Gilbert Gray vill inte lämna sin plats eller gå miste om en fin fångst genom att gå tillbaka in i staden efter förnödenheter.",al={"varför kan gray inte köpa bete","varför behöver gray hjälp"}},{q="Var längs kanalerna ligger Catherine Lelands butik?",a="Catherine Lelands butik ligger längs kanalerna, strax väster om Trade District, intill stengångarna över stadens vattenleder.",al={"catherine leland plats","var ligger lelands butik","kanalerna vid trade district"}}},fp="12,206,18.235.0,25.223.0,20.167.0,24.160.0,29.82.0,37.118.0,52.132.0,58.129.0"}
P.entries["quest:951"] = {n="Mathystra Relics",s="Det här uppdraget sänder Alliansens äventyrare norrut längs Darkshores kust för att söka igenom de igenvuxna Ruins of Mathystra. Onu, en forntida kunskapsväktare med rötter i Grove of the Ancients, söker dessa urgamla kaldorei-föremål för att förstå hur Twilight's Hammer-sekten använder nattälvornas trolldom i sina onda riter.",h="Det här uppdraget sänder Alliansens äventyrare norrut längs Darkshores kust för att söka igenom de igenvuxna...",kw={"darkshore","grove of the ancients","the master's glaive","mathystra","onu","reliker","ruins of mathystra","twilight's hammer"},ang={["class:Druid"]="Genom att hjälpa Onu kan druider tjäna en av naturens främsta forntida väktare och skydda Darkshores urgamla historia från att förvridas av mörka sekterister.",["faction:Alliance"]="Att hindra Twilight's Hammer från att göra urgammal magi till ett vapen är avgörande för att säkra norra Kalimdor mot mörka, underjordiska krafter.",["race:NightElf"]="För nattalverna är det en sorgsen påminnelse om civilisationens fall att se reliker från tiden före Sunderingen grävas upp ur jorden. Det är också en oroväckande varning om att apokalyptiska galningar utnyttjar deras förfäders mäktiga konster."},sec={{t="En oroande upptäckt",b="När äventyrarna återfann ett besudlat pergament från sekteristerna kring det kolossala monumentet The Master's Glaive, dechiffrerade Onu en oroande uppenbarelse. Texten var inte någon inhemsk sekttext, utan ett förbannat fragment av urgammal nattalvisk skrift. Besudlat av Twilight's Hammer avslöjade pergamentet att dessa apokalyptiska fanatiker använder bortglömd alvisk magi för att väcka eller kalla tillbaka sina forntida herrar till de dödligas värld."},{t="Den fallna borgen",b="För att motverka detta mörka verk ger Onu hjältarna i uppdrag att bege sig till Ruins of Mathystra, längs Darkshores nordöstra kust. För länge sedan var Mathystra en strålande högborneborg innan den krossades under Sunderingen. Staden har rasat samman till ruiner, ogräs och naga, men kraftfulla rester av dess ursprungliga mystiska och andliga besvärjelser dröjer kvar i krossade urnor och forntida reliker utspridda bland stenfundamenten."},{t="Att avslöja mörka planer",b="Genom att samla in överlevande artefakter från ruinernas gräsbevuxna bråte hoppas Darkshores försvarare kunna avslöja vilka metoder sekteristerna tänker utnyttja. Onu studerar den kvarvarande magin i relikerna och skyndar sig att tyda sektens planer innan Twilight's Hammer helt kan förvrida den urgamla kaldorei-trolldomen och befria sina underjordiska herrar."}},faq={{q="Vad är Mathystra-relikerna?",a="De är skärvor av förtrollat lergods, urnor och artefakter som lämnats kvar i Ruins of Mathystra. De skapades under höjdpunkten av den urgamla nattalviska civilisationen före den stora Sunderingen och sjuder fortfarande av kvarvarande magisk energi.",al={"vad är relikerna","mathystra-relikernas historia","alviska reliker i mathystra"}},{q="Varför vill Onu ha relikerna?",a="Onu upptäckte att Twilight's Hammer-sekten använder urgammal alvisk magi i ett försök att återföra sina mörka herrar till världen. Genom att studera hela reliker från Mathystra hoppas Onu förstå hur sekten tänker manipulera den uråldriga kraften.",al={"varför vill onu ha reliker","mathystra-relikernas syfte"}},{q="Var låg Ruins of Mathystra?",a="Ruinerna ligger längs Darkshores nordöstra kust, norr om ruinerna Ameth'Aran och Bashal'Aran, strax bortom Tower of Althalaxx.",al={"var ligger mathystra","mathystra plats"}},{q="Vilka försöker Twilight's Hammer återföra?",a="Sekten hängiver sig åt forntida, ondskefulla herrar. Onu varnar för att de använder urgammal alvisk magi för att återföra dessa gamla herrar till Azeroth.",al={"vilka är twilight hammers herrar","sektens herrar i darkshore"}},{q="Vad var Mathystra innan det blev en ruin?",a="Mathystra var en gång en stor borg och stad för nattalverna, för tusentals år sedan. Staden föll i ruiner under den stora Sunderingen och har sedan dess tagits över av vildmark, spöken och vidriga strandvarelser som naga.",al={"mathystras historia","vad var mathystra"}},{q="Vem ger uppdraget ”Mathystra Relics”?",a="Uppdraget ges av Onu, en uråldrig treant med rötter i Grove of the Ancients i södra centrala Darkshore, efter undersökningen av The Master's Glaive.",al={"vem startar mathystra relics","uppdragsgivare för mathystra relics"}}},fp="16,215,22.360.1,18.296.0,21.293.1,30.220.0,31.222.0,42.138.0,50.154.0,43.204.0,39.177.0"}
P.entries["quest:95111"] = {n="An Underrated Talent",s="I Silverpine Forest ger Trevan Rol Ott en chans att smida en klinga efter dina önskemål. Otts enkla vapen har fått beröm av smeder i Undercity.",h="I Silverpine Forest ger Trevan Rol Ott en chans att smida en klinga efter dina önskemål.",kw={"beställning","specialbeställd klinga","ott","smed","tarren mill","undercity","vapensmed"},sec={{t="En smeds chans",b="Trevan Rol ber dig att ta material till Ott i Tarren Mill och erbjuda honom ett uppdrag. Ott säljer enkla klingor till resenärer. Trevan köpte en och tog den senare till Undercity för underhåll. Där berömde de lokala smederna dess kvalitet och trodde att den var ett verk av en berömd mästare. Nu får Ott chansen att smida en klinga efter dina specifikationer."},{t="Otts svar",b="Ott säger att ingen har bett honom att göra ett specialbeställt vapen förut. Han brukar tillverka enkla, funktionella vapen i sin egen stil och söker ingen berömmelse. Ändå är han villig att försöka. Han undrar varför du valde honom när smeder i Undercity också tar emot specialbeställningar."}},faq={{q="Vem är Ott?",a="Ott är en vapensmed i Tarren Mill som säljer enkla klingor till resenärer.",al={"ott smed","vem är ott","tarren mill smed"}},{q="Varför vill smeden i Undercity att jag ska hitta Ott?",a="Smeden köpte en av Otts klingor och blev förvånad när smeder i Undercity berömde dess kvalitet. Smeden vill att Ott ska få en chans att skapa något speciellt.",al={"varför ott","undercity smed beställning","ott beställning"}},{q="Vad ska jag ta med till Ott?",a="Du tar med material till Ott i Tarren Mill och ger honom en beställning på att smida din klinga.",al={"material till ott","vad ska jag ta med","ott material"}},{q="Tillverkar Ott vapen på beställning?",a="Ott säger att ingen har bett honom att tillverka ett vapen på beställning förut, men han är villig att försöka.",al={"ott specialbeställd klinga","kan ott smida åt mig","ott beställningar"}},{q="Varför frågar Ott varför jag valde honom?",a="Ott säger att smeder i Undercity tar emot specialbeställningar och undrar varför du sökte upp honom i stället.",al={"varför välja ott","ott undrar varför","varför inte smed i undercity"}}},fp="20,155,16.348.0,12.255.1,11.73.0,49.163.0,26.97.0,29.87.0,33.90.0"}
P.entries["quest:95118"] = {n="Saltwater Savages",s="En hamnföreståndare ber dig minska antalet Murlocs längs Eastwind Shore. Sjömän, fiskare och hans barn klagar ständigt på dem.",h="En hamnföreståndare ber dig minska antalet Murlocs längs Eastwind Shore.",kw={"eastwind shore","fiskare","murloc","murloc oracle","murloc warrior","hamnföreståndare","sjömän","saltwater savages"},sec={{t="Klagomål i hamnen",b="Hamnföreståndaren har hört nog med klagomål från sjömän, fiskare och till och med sina barn. Murlocs besvärar honom, men han måste fortfarande sköta hamnen. Han ber dig döda några längs Eastwind Shore och hoppas få lite lugn från allt oväsen omkring sig."}},faq={{q="Varför vill hamnföreståndaren att Murlocs ska dödas?",a="Sjömän, fiskare och hamnföreståndarens barn fortsätter att klaga på dem. Han kallar dem en plåga och vill få lite lugn medan han sköter hamnen.",al={"varför döda murlocs","murlocs stör hamnen"}},{q="Vilka Murlocs menar han?",a="Han ber dig döda Murloc Oracles och Murloc Warriors längs Eastwind Shore.",al={"murloc-typer","orakel och krigare"}},{q="Var finns Murlocs?",a="Hamnföreståndaren visar dig till Eastwind Shore.",al={"murlocs vid eastwind shore","var finns murlocs"}},{q="Löser det problemet att döda de här Murlocs?",a="Hamnföreståndaren räknar med att fler Murlocs snart kommer tillbaka, men hoppas att deras död ska ge honom lite lugn fram till dess.",al={"murlocs kommer tillbaka","är det över"}}},fp="17,152,22.244.0,49.149.0,33.76.0,22.45.0,45.118.0"}
P.entries["quest:95120"] = {n="WANTED: Old Rot-Chum",s="Wharfmaster Whizzbuzz utlovar en belöning för bevis på Old Rot-Chums död. Den aggressiva murlocen har attackerat små farkoster i de södra vattnen.",h="Wharfmaster Whizzbuzz utlovar en belöning för bevis på Old Rot-Chums död.",kw={"murloc","murlocöar","old rot-chum","roddbåtar","små farkoster","södra vatten","wharfmaster whizzbuzz"},sec={{t="Ett hot till havs",b="Sjömän och simmare i vattnen i söder utsätts för attacker mot roddbåtar och andra små farkoster. Lokala fiskare kallar den aggressiva murlocen bakom attackerna för Old Rot-Chum. Wharfmaster Whizzbuzz utlovar en belöning för bevis på att varelsen är död och ber dig ta med beviset till honom."}},faq={{q="Vem är Old Rot-Chum?",a="Old Rot-Chum är smeknamnet som lokala fiskare gett en ovanligt aggressiv murloc.",al={"old rot-chum","rot-chum","vem är rot-chum"}},{q="Var har Old Rot-Chum synts till?",a="Old Rot-Chum har synts till i vattnen i söder, nära öar fulla av murlocs.",al={"var finns old rot-chum","rot-chums plats","var finns murlocen"}},{q="Vad har Old Rot-Chum attackerat?",a="Old Rot-Chum har attackerat roddbåtar och andra små farkoster.",al={"vad attackerar rot-chum","båtattacker","murloc och roddbåtar"}},{q="Vem utlovar belöningen?",a="Wharfmaster Whizzbuzz utlovar en belöning i utbyte mot bevis på Old Rot-Chums död.",al={"vem vill ha bevis på rot-chum","wharfmasters belöning","vem betalar för old rot-chum"}},{q="Vilka bevis ber Whizzbuzz om?",a="Wharfmaster Whizzbuzz ber dig ta med bevis på Old Rot-Chums död.",al={"vilka bevis för rot-chum","ta med bevis","bevis på död"}}},fp="20,154,15.274.0,20.82.0,33.90.0,37.65.0,22.87.0,34.73.0"}
P.entries["quest:95121"] = {n="A Taste of the Sea",s="Fimbo Greasemitz vill ha färska skaldjur till en ny gryta på sitt kafé vid vattnet. Du samlar lokala ingredienser för att förnya menyn.",h="Fimbo Greasemitz vill ha färska skaldjur till en ny gryta på sitt kafé vid vattnet.",kw={"strand","kafé","fimbo greasemitz","fisk","murlocögon","rostad vildsvinsstek","sand crawler-kött","skaldjursgryta"},ang={["profession:Cooking"]="Som kock ser du att Fimbo letar efter färska lokala ingredienser till en skaldjursgryta."},sec={{t="En ny rätt",b="Fimbo Greasemitz driver ett kafé vid vattnet, där menyn varje dag består av rostad vildsvinsstek och fisk. Han vill prova en skaldjursgryta och ber dig hämta murlocögon och Sand Crawler-kött från stränderna i närheten."}},faq={{q="Vem är Fimbo Greasemitz?",a="Fimbo Greasemitz driver ett kafé vid vattnet och vill lägga till skaldjursgryta på menyn.",al={"vem är fimbo","fimbos kafé","fimbo greasemitz"}},{q="Vilka ingredienser behöver Fimbo?",a="Fimbo ber om murlocögon och Sand Crawler-kött till sin skaldjursgryta.",al={"ingredienser till gryta","vilket kött","murlocögon"}},{q="Varför vill Fimbo ha skaldjur?",a="Han vill ha ett nytt recept på skaldjursgryta som kan förnya kaféets dagliga meny med rostad vildsvinsstek och fisk.",al={"varför gryta","ny meny","kafémat"}},{q="Var hittar du ingredienserna?",a="Fimbo säger att murlocögon och Sand Crawler-kött finns längs stränderna i närheten.",al={"var finns köttet","var finns ingredienserna","saker från stranden"}}},fp="18,129,10.206.0,24.84.0,33.70.0,28.94.0,35.87.0"}
P.entries["quest:95125"] = {n="Ott's Masterwork",s="Ott är redo att smida en klinga åt dig av fina material. Du får se på när han arbetar.",h="Ott är redo att smida en klinga åt dig av fina material.",kw={"smed","klinga","smide","mästerverk","material","ott"},sec={{t="Vid ässjan",b="Ott uppskattar de fina materialen och hoppas att hans arbete ska motsvara dina förväntningar. Han smider en klinga åt dig och erbjuder dig den sedan för dina resor."}},faq={{q="Vem tillverkar min klinga?",a="Ott smider din klinga av de fina material du har lämnat till honom.",al={"vem smider den","otts klinga","ott smed"}},{q="Kan jag se på när Ott smider den?",a="Ott ber dig att hålla avstånd när han börjar smida. Du blir ombedd att se på när han arbetar.",al={"se ott smida","se klingan tillverkas","smidesprocess"}},{q="Vad säger Ott när klingan är färdig?",a="Ott kallar klingan sitt finaste verk och hoppas att den tjänar dig väl på dina resor.",al={"ott färdig","vad säger ott","klingan färdig"}}},fp="16,85,12.137.0,23.63.0,25.81.0,45.81.0"}
P.entries["quest:95126"] = {n="The Moonsilver Blade",s="I Silverpine Forest väntar Trevan Rol på klingan som ska fullborda hans arbete innan han möter ett odjur.",h="I Silverpine Forest väntar Trevan Rol på klingan som ska fullborda hans arbete innan han möter ett odjur.",kw={"odjur","lumina","moonsilver blade","ott","ott's masterwork","silverpine forest","trevan rol"},sec={{t="Klingan",b="Ott tackar dig för chansen att hjälpa till och ber dig framföra hans tacksamhet till Trevan. Du tar med dig Ott's Masterwork tillbaka till Trevan Rol i Silverpine Forest."},{t="Trevans godkännande",b="Trevan Rol granskar klingan och godkänner Otts arbete. Bara odjuret återstår. När du är redo ber han dig att tala med Lumina."}},faq={{q="Vem tillverkade Ott's Masterwork?",a="Ott tillverkade Ott's Masterwork och skickade det med dig till Trevan Rol.",al={"vem tillverkade klingan","otts klinga","mästerverkets skapare"}},{q="Vem är Trevan Rol?",a="Trevan Rol tar emot och granskar Ott's Masterwork i Silverpine Forest.",al={"vem är trevan","trevans klinga","trevan rol"}},{q="Vart ska jag ta klingan?",a="Ta Ott's Masterwork till Trevan Rol i Silverpine Forest.",al={"vart ska klingan","vart ska ott's masterwork","klingans destination"}},{q="Vad tycker Trevan om klingan?",a="Trevan Rol granskar klingan och säger att den duger gott.",al={"gillar trevan klingan","är otts klinga bra","trevans godkännande"}},{q="Vem ska jag tala med efter Trevan?",a="När du är redo ber Trevan Rol dig att tala med Lumina.",al={"vad händer sedan","vem är lumina","tala med lumina"}}},fp="20,102,9.152.0,17.138.1,26.61.0,18.71.0,27.58.0,36.57.0,37.64.0"}
P.entries["quest:95140"] = {n="Old Fire-Eye",s="Lumina Windsinger skickar dig efter Old Fire-Eye i Silverpine Forest med Moonsilver Blade. Windshapers väntar på hans död, och Lumina hoppas att klingan ska vägleda dig väl.",h="Lumina Windsinger skickar dig efter Old Fire-Eye i Silverpine Forest med Moonsilver Blade.",kw={"banon","gilneas","lumina windsinger","moonsilver blade","old fire-eye","silverpine forest","windshapers"},sec={{t="En klingas syfte",b="Windshapers har gett dig Moonsilver Blade. Lokalbefolkningen säger att Old Fire-Eye jagar över ett stort område söder härom, oftast nära portarna till Gilneas. Lumina ber dig att hitta honom och använda klingan för att döda honom. Windshapers tacksamhet hänger på hans död."},{t="Efter jakten",b="När du återvänder tackar Lumina dig och säger att Banon nu kan vila i frid. Sedan lägger hon en liten del av sitt folks magi på den blodfläckade klingan och hoppas att vindarna ska vägleda den väl."}},faq={{q="Vem ber mig att jaga Old Fire-Eye?",a="Lumina Windsinger ber dig att jaga Old Fire-Eye med Moonsilver Blade.",al={"vem skickade mig","luminas uppdrag","windsinger"}},{q="Var kan jag hitta Old Fire-Eye?",a="Lokalbefolkningen säger att Old Fire-Eye jagar över ett stort område söder om Lumina, oftast nära portarna till Gilneas.",al={"fire eye plats","var är old fire-eye","gilneas portar"}},{q="Vad ska jag använda mot Old Fire-Eye?",a="Lumina ber dig att använda Moonsilver Blade för att döda Old Fire-Eye.",al={"klinga mot fire-eye","moonsilver vapen","vilket vapen"}},{q="Varför vill Lumina att Old Fire-Eye ska dödas?",a="Lumina säger att Windshapers kommer att vara tacksamma när Old Fire-Eye är död.",al={"varför döda fire-eye","varför jaga honom","fire-eye anledning"}},{q="Vem är Banon?",a="Lumina säger att Banon kan vila i frid när Old Fire-Eye har dödats.",al={"banon vem","banon frid","vem är banon"}},{q="Vad gör Lumina med klingan?",a="Lumina lägger en liten del av sitt folks magi på den blodfläckade Moonsilver Blade.",al={"klingans magi","lumina förtrollar klingan","vindmagi"}}},fp="12,175,17.261.0,14.186.1,38.74.0,30.100.0,39.64.0,40.71.0,13.64.0,35.89.0"}
P.entries["quest:95141"] = {n="Report to Rog'mar",s="En orch hänvisar dig till Rog'mar, en utpost i det omstridda Riverglades. Anmäl dig hos Krom'rosh, vars erfarenhet har hjälpt utposten att stå emot upprepade anfall.",h="En orch hänvisar dig till Rog'mar, en utpost i det omstridda Riverglades.",kw={"anfall","östkusten","krom'rosh","utpost","riverglades","rog'mar","stonard"},sec={{t="En utpost håller stånd",b="Riverglades ligger nordost om Stonard längs östkusten. Många har försökt lägga beslag på området, men få har lyckats. Rog'mar är en liten utpost som har överlevt otaliga anfall. Du skickas dit för att anmäla dig hos Krom'rosh, en gammal bundsförvant vars stridserfarenhet har hjälpt utposten att hålla stånd."}},faq={{q="Var ligger Rog'mar?",a="Rog'mar ligger i Riverglades, nordost om Stonard längs östkusten.",al={"rog'mar läge","var ligger rogmar","rog'mar utpost"}},{q="Vem ska jag anmäla mig hos?",a="Du ska anmäla dig hos Krom'rosh vid utposten Rog'mar.",al={"anmäla sig hos vem","vem är krom'rosh","kromrosh"}},{q="Vad är Rog'mar?",a="Rog'mar är en liten utpost i Riverglades som har stått emot otaliga anfall.",al={"rogmar vad","riverglades utpost","liten utpost"}},{q="Varför är Krom'rosh i Rog'mar?",a="Krom'roshs erfarenhet av att bekämpa fiender har hjälpt utposten att hålla stånd.",al={"varför är kromrosh där","krom'rosh roll","vem leder rogmar"}},{q="Vad är Riverglades för slags område?",a="Riverglades är ett omstritt område längs östkusten, nordost om Stonard.",al={"riverglades","hur är riverglades","omstritt område"}}},fp="17,157,18.302.0,17.78.0,22.54.0,16.81.0,28.70.0,38.84.0"}
P.entries["quest:95143"] = {n="Finding Tan'jani",s="En resenär ber dig hitta sitt syskon Tan'jani. Meddelanden placerar honom söder om Loch Modan, och det senaste pekar mot Rog'mar i Riverglades.",h="En resenär ber dig hitta sitt syskon Tan'jani.",kw={"blodfläckat brev","loch modan","försvunnen bror","riverglades","rog'mar","tan jani","tan'jani"},sec={{t="En försvunnen bror",b="En resenärs bror, Tan'jani, har gett sig av för att leta efter något okänt. Ett meddelande placerar honom någonstans söder om Loch Modan. Ett blodfläckat brev nämner Riverglades och Rog'mar längre söderut, och resenären ber dig hitta honom där."}},faq={{q="Vem är Tan'jani?",a="Tan'jani är bror till resenären som ber dig hitta honom.",al={"tan'jani","tan jani","försvunnen bror"}},{q="Var nämndes Tan'jani senast?",a="Ett blodfläckat brev nämner Riverglades och Rog'mar, längre söderut än Loch Modan.",al={"var är tan'jani","tan'janis plats","rog'mar"}},{q="Vad letade Tan'jani efter?",a="Tan'jani letade alltid efter något, men hans bror vet inte vad.",al={"vad letade han efter","tan'jani letade","varför gav han sig av"}},{q="Vad står det i meddelandena?",a="En resenär berättade att hen hade mött Tan'jani någonstans söder om Loch Modan. Ett blodfläckat brev nämner Riverglades och Rog'mar, men det mesta går inte att läsa.",al={"tan'janis meddelanden","blodfläckat brev","vad hände med brevet"}}},fp="16,147,17.242.0,16.63.0,34.86.0,32.80.0,25.156.0"}
P.entries["quest:95144"] = {n="Overseas Delivery",s="Fizzgrimble ber dig föra en förseglad låda över havet till Friz Frazzlespark i Riverglades. Innehållet ska förbli en överraskning tills lådan når Powderfuse Port.",h="Fizzgrimble ber dig föra en förseglad låda över havet till Friz Frazzlespark i Riverglades.",kw={"fizzgrimble","friz frazzlespark","mystisk låda","leverans över havet","powderfuse port","riverglades","steamwheedle port"},sec={{t="En varsam överfart",b="Fizzgrimble skickar dig österut mot Steamwheedle Port, där ett skepp vanligtvis erbjuder passage över havet. Lådan ska till Friz Frazzlespark vid Powderfuse Port i Riverglades. Hantera den varsamt på vägen; Fizzgrimble varnar dig för att öppna eller skaka den."}},faq={{q="Vem är paketet till?",a="Friz Frazzlespark väntar på lådan vid Powderfuse Port i Riverglades.",al={"vem får lådan","friz frazzlesparks paket"}},{q="Vart ska jag ta lådan?",a="Ta den till Friz Frazzlespark vid Powderfuse Port i Riverglades.",al={"lådans destination","var ligger powderfuse port"}},{q="Var kan jag få passage över havet?",a="Fizzgrimble rekommenderar att du beger dig österut till Steamwheedle Port, där ett skepp vanligtvis erbjuder en säker överfart.",al={"hur tar jag mig över","steamwheedle skepp"}},{q="Vad ska jag göra med lådan på vägen?",a="Håll lådan stängd och undvik att luta eller skaka den, eller att göra plötsliga rörelser med den.",al={"hur bär jag lådan","kan jag öppna paketet"}},{q="Vad finns i lådan?",a="Friz Frazzlespark ber dig vända dig om medan hen tittar inuti, så att innehållet förblir en överraskning.",al={"lådans innehåll","vad är överraskningen"}}},fp="17,178,18.262.0,23.81.0,30.67.0,40.101.0,43.85.0,25.98.0"}
P.entries["quest:95161"] = {n="Remember That I Love You",s="I Stormwind är ett blodfläckat brev på väg till Jeremy Heartweaver. Han har lämnat barnhemmet för ett nytt hem hos Avette Fellwood i Duskwood.",h="I Stormwind är ett blodfläckat brev på väg till Jeremy Heartweaver.",kw={"avette fellwood","blood-stained letter","duskwood","jeremy heartweaver","remember that i love you","stormwind","barnhemmet i stormwind"},ang={["faction:Alliance"]="För Alliansen säger minnessaker från stupade eller försvunna anhöriga, som bärs till adopterade föräldralösa barn, något om de personliga kostnaderna för kungarikets oroliga tillstånd.",["race:Human"]="Som människa från Stormwind färdas du från rikets relativt trygga hjärta till Duskwoods hemsökta, bortglömda bosättningar."},sec={{t="Ett meddelande till ett föräldralöst barn",b="Barnen på barnhemmet i Stormwind har förlorat sina familjer i krig, umbäranden och kaoset som sliter sönder kungariket. Jeremy Heartweaver var ett av dem, tills Avette Fellwood adopterade honom. Hon tog honom med sig till Duskwood, där skogarna är dystra och livet innebär faror och hårt arbete. Barnhemmets föreståndare trodde att ett hem hos en familj skulle ge honom mer än ett liv kvar i staden."},{t="Ett dystert tecken",b="Ett Blood-Stained Letter är adresserat till Jeremy, som är i Avette Fellwoods vård. Spåren leder söderut, förbi tryggheten i Elwynn Forest och in i Duskwoods skuggor. Vilken tragedi drabbade Jeremy efter att han lämnat Stormwind, och varför bär brevet ett så dystert tecken?"}},faq={{q="Vem är Jeremy Heartweaver?",a="Jeremy Heartweaver är en ung pojke som växte upp på barnhemmet i Stormwind. Avette Fellwood adopterade honom nyligen, och nu bor och arbetar han i Duskwood.",al={"jeremy","vem är jeremy","den föräldralöse jeremy"}},{q="Vem är Avette Fellwood?",a="Avette Fellwood är Jeremys adoptivmor och bor i Duskwood. Föreståndarna på barnhemmet i Stormwind anser att hon är en vänlig kvinna som troligen tog emot Jeremy för att få ytterligare ett par händer till sitt dagliga arbete.",al={"avette","vem är avette","adoptivmor"}},{q="Vad är Blood-Stained Letter?",a="Blood-Stained Letter är adresserat till Jeremy Heartweaver och hamnar hos hans adoptivvårdnadshavare, Avette Fellwood. Det bär på ekon av våld eller tragedi.",al={"blood-stained letter","brevet","vad är brevet"}},{q="Var hittar jag Avette Fellwood?",a="Avette Fellwood bor i Duskwood, den mörka skogen strax söder om Elwynn Forest, på andra sidan floden.",al={"avette fellwoods plats","var är avette","hitta avette"}},{q="Varför skickades Jeremy till Duskwood?",a="Jeremy adopterades från barnhemmet i Stormwind. Föreståndarna trodde att en familj och hederligt arbete i det farliga Duskwood var bättre än ett liv som föräldralös på barnhemmet.",al={"varför duskwood","varför lämnade jeremy stormwind","barnhemmet i duskwood"}},{q="Vilken fraktion kan ta det här uppdraget?",a="Endast Alliansen kan ta sig an det här uppdraget. Det börjar i Stormwind, människornas huvudstad, och leder in i det allianskontrollerade Duskwood.",al={"är det här alliansen","endast alliansen","horduppdrag"}}},fp="24,136,23.349.0,12.253.1,26.146.0,23.196.0,33.150.0,32.101.0,32.173.0,34.125.0"}
P.entries["quest:95162"] = {n="Paletusk Harvesting",s="Na'zok ber dig samla paletusk-kött nära Bolder'ok. Ranchen försörjer närliggande ogres och levererar till Rog'mar medan kriget går framåt.",h="Na'zok ber dig samla paletusk-kött nära Bolder'ok.",kw={"vildsvinskött","bolder'ok","na'zok","ogres","paletusk","paletusk-skörd","ranch","rog'mar"},sec={{t="Kött till ranchen",b="Na'zok behöver mer kött på ranchen nära Bolder'ok, där ogres låter Na'zok stanna så länge köttet fortsätter komma. När kriget går framåt ökar behovet av mat, och ogres börjar se Na'zok som sin nästa måltid. Du ombeds samla bitar av vildsvinskött åt de hungriga ogres och Rog'mar."}},faq={{q="Vem ber om kött?",a="Na'zok ber dig samla vildsvinskött nära Bolder'ok åt ogres och Rog'mar.",al={"vem behöver kött","na'zoks begäran","vem är na'zok"}},{q="Varför behöver Na'zok köttet?",a="Ranchen är en av Na'zoks få matkällor, och ogres låter Na'zok stanna så länge köttet fortsätter komma.",al={"varför kött","varför samla vildsvin","hungriga ogres"}},{q="Vem är Rog'mar?",a="Rog'mar nämns som någon som behöver få en del av köttet.",al={"kött till rog'mar","kött åt rog'mar"}},{q="Var är Na'zok?",a="Na'zok är nära Bolder'ok.",al={"na'zoks plats","var ligger ranchen"}},{q="Vilket kött behövs?",a="Na'zok ber om bitar av vildsvinskött från paletusk.",al={"vildsvinskött","paletusk-kött","köttbitar"}}},fp="19,126,18.294.0,23.77.0,30.106.0,15.58.0,16.25.0,20.50.0"}
P.entries["quest:95163"] = {n="Drive Them Back",s="Na'zok ber dig föra tillbaka förrymda Young Paletusks till hans gård nära Bolder'ok. Kultingarna har korsat floden, och de behövs i sina fållor.",h="Na'zok ber dig föra tillbaka förrymda Young Paletusks till hans gård nära Bolder'ok.",kw={"bolder'ok","förrymda kultingar","gård","gorgegut","na'zok","paletusk","grisar","unga paletusks"},sec={{t="De förrymda kultingarna",b="På Na'zoks gård nära Bolder'ok strövar fler grisar omkring i dalen än det finns i fållorna. Gorgegut har inte varit någon idealisk gårdsdräng, men han håller människorna borta. Några av Young Paletusks har korsat floden, och de är för små för att slaktas ute på fältet. Na'zok ger dig en käpp så att du kan fösa tillbaka dem till fållorna."}},faq={{q="Varför är kultingarna utanför fållorna?",a="Några Young Paletusks har rymt över floden från Na'zoks gård.",al={"förrymda kultingar","grisar på rymmen","varför grisar utanför"}},{q="Vem är Gorgegut?",a="Gorgegut är Na'zoks gårdsdräng, men Na'zok säger att han inte har varit särskilt bra på jobbet.",al={"gorgegut gårdsdräng","vem är gorgegut","gårdens grisskötare"}},{q="Varför ska Young Paletusks föras tillbaka?",a="Young Paletusks är för små för att slaktas ute på fältet, så Na'zok vill att de förs tillbaka till gården.",al={"föra tillbaka kultingar","varför föra tillbaka grisar","ung paletusk"}},{q="Var ligger Na'zoks gård?",a="Na'zoks gård ligger nära Bolder'ok.",al={"na'zoks gård plats","gård nära bolder'ok","var ligger grisgården"}}},fp="15,148,19.313.0,38.70.0,16.78.0,35.106.0,23.32.0"}
P.entries["quest:95183"] = {n="Step One: Rock",s="Hamur i Bolder'ok vill ha fina stenar från floden i närheten. Ta med dem så att han kan göra ett litet vapen åt en liten varelse.",h="Hamur i Bolder'ok vill ha fina stenar från floden i närheten.",kw={"bolder'ok","fina stenar","hamur","ogrevapen","flod","litet vapen"},sec={{t="Hamurs begäran",b="Hamur i Bolder'ok säger att du är för liten för att svinga ett ordentligt ogrevapen. Han erbjuder sig att göra ett litet åt dig om du tar med fina stenar. Han vill ha stenar från floden utanför Bolder'ok, där bara de bästa stenarna duger."}},faq={{q="Vem är Hamur?",a="Hamur finns i Bolder'ok och erbjuder sig att göra ett litet vapen åt dig om du tar med fina stenar.",al={"hamur vem","vem vill ha stenar"}},{q="Var hittar jag stenarna?",a="Hamur ber om fina stenar från floden utanför Bolder'ok.",al={"stenarnas plats","var finns stenarna"}},{q="Varför vill Hamur ha stenar?",a="Hamur säger att han ska använda de fina stenarna till att göra ett litet vapen åt en liten varelse.",al={"varför stenar","vad ska stenarna användas till"}},{q="Vilken sorts stenar vill Hamur ha?",a="Hamur vill ha fina stenar från floden utanför Bolder'ok. Han säger att inte alla stenar duger.",al={"fina stenar","vilka stenar"}}},fp="14,119,15.217.0,13.87.0,26.59.0,26.80.0,35.92.0"}
P.entries["quest:95189"] = {n="Crest of Lordaeron",s="Crest of Lordaeron är en väderbiten relik med den fallna nordliga kungadömets kungliga emblem. Sådana reliker är sällsynta sedan rikets fall och hittades bland de öde ruinerna av Capital City. Någon i Stormwind skulle gärna lägga vantarna på just den här.",h="Crest of Lordaeron är en väderbiten relik med den fallna nordliga kungadömets kungliga emblem.",kw={"crest of lordaeron","heraldik","lady dena kennedy","lordaeron","relik","ruins of lordaeron","stormwind","tirisfal glades"},ang={["faction:Alliance"]="Lordaerons emblem symboliserar grundpelaren i den ursprungliga Alliance, så att återfinna det är en symbolisk seger över Scourge och Forsakens försök att utplåna allt.",["race:Human"]="För människor, särskilt dem vars familjer en gång kallade norr sitt hem, är emblemet en gripande påminnelse om det storslagna kungarike som en gång ledde Alliance."},sec={{t="Ett splittrat arv",b="När Scourge drog fram genom kungariket Lordaeron förstördes dess palats, arkiv och stolta insignier till stor del, eller lämnades att förfalla i Undercitys skugga. Fysiska föremål med det kungliga emblemet som överlevt är ytterst sällsynta. Att återfinna ett helt eller väderbitet emblem bland de nordliga ruinerna innebär att en påtaglig del av människornas historia räddas från glömskan."},{t="En fristad i söder",b="Efter det tredje kriget flydde tusentals nordliga flyktingar söderut mot kungariket Stormwind och bar bara med sig minnen av sitt hemland. I Stormwind City är Lady Dena Kennedy angelägen om att förvärva sådana lämningar från Lordaeron, vilket gör reliker som det här emblemet mycket värdefulla i den sydliga huvudstaden."}},faq={{q="Vad är Crest of Lordaeron?",a="Det är ett väderbitet heraldiskt emblem som visar Lordaerons officiella märke. Det lämnades kvar när kungariket föll för Scourge och är en högt värderad historisk relik för människornas överlevande.",al={"crest of lordaeron","vad är crest of lordaeron","föremålet crest of lordaeron"}},{q="Vem vill ha Crest of Lordaeron?",a="Emblemet lämnas till Lady Dena Kennedy, en aristokratisk beskyddare i Stormwind City som vill samla in och bevara sällsynta föremål från det fallna nordliga riket.",al={"vem tar emot emblemet","var lämnar jag crest of lordaeron","lämna in emblemet"}},{q="Var hittades emblemet?",a="Det återfanns i Ruins of Lordaeron i Tirisfal Glades, den förstörda huvudstaden som nu ligger rakt ovanför Forsakens fäste Undercity.",al={"emblemets plats","emblem från ruinerna","var hittar jag emblemet"}},{q="Varför är föremål från Lordaeron så sällsynta?",a="Kungarikets snabba och katastrofala fall under det tredje kriget ledde till en systematisk slakt av dess folk och förödelse av dess gods. Mycket få personliga arvegods överlevde Scourge och Forsakens efterföljande framväxt.",al={"varför är lordaerons reliker sällsynta","sällsynta föremål från lordaeron"}},{q="Varför bryr sig Stormwind om reliker från Lordaeron?",a="Stormwind tog emot vågor av flyktingar, riddare och adelsfolk som flydde förödelsen i norr. Att bevara reliker hedrar Alliances fallna systerrike och håller de nordliga människornas arv vid liv.",al={"varför bryr sig stormwind","stormwind och lordaerons reliker"}},{q="Vem är Lady Dena Kennedy?",a="Lady Dena Kennedy är en adelskvinna som bor i Stormwind City och aktivt intresserar sig för att rädda historiska lämningar och arvegods med ursprung i Lordaeron.",al={"lady dena kennedy","vem är dena kennedy"}}},fp="18,193,20.268.0,19.292.0,31.177.0,33.110.0,26.141.0,41.176.0,50.174.0,25.126.0"}
P.entries["quest:95195"] = {n="Bloodied Insignia",s="Bloodied Insignias är tragiska kvarlevor efter Lordaerons fallna försvarare, utspridda bland rikets härjade ruiner. De bär Alliansens gamla emblem och tillhörde soldater vars familjer flydde söderut till Stormwind under det tredje kriget.",h="Bloodied Insignias är tragiska kvarlevor efter Lordaerons fallna försvarare, utspridda bland rikets härjade...",kw={"allians","bloodied insignia","lordaeron","marcus jonathan","flyktingar","ruins of lordaeron","stormwind","tredje kriget"},ang={["class:Paladin"]="Många av de fallna i huvudstaden stred sida vid sida med Silverhandens riddare. Att återbörda deras medaljer hedrar den heliga ordens förlorade bröder och systrar.",["faction:Alliance"]="Att återlämna dessa emblem till General Marcus Jonathan är en plikthandling och ett sätt att minnas soldaterna som gav sina liv för att försvara den ursprungliga Alliansen.",["race:Human"]="För Alliansens människor är dessa märken allvarliga påminnelser om det största människorikets fall. De knyter samman flyktingarna i Stormwind med deras fallna släktingar i norr."},sec={{t="De fallnas minnesmärken",b="När prins Arthas återvände för att härja Lordaeron med Scourge blev dess mäktiga armé övermannad och massakrerad. Otaliga soldater dog när de försvarade huvudstaden och de omgivande områdena. Efter sig lämnade de få fysiska spår utöver rostiga rustningar och blodfläckad mässing. Dessa gamla emblem från Alliansen tillhörde männen och kvinnorna som stod emot de odödas anstormning. Varje medalj, nedtrampad i ruinstadens jord och grus, är ett minne av rikets sista, desperata försvar."},{t="Budbärare åt de landsflyktiga",b="Många överlevande från Lordaeron flydde söderut över havet och slog sig ner som flyktingar i Stormwind City. Årtionden av allians och släktskap förenar de två människorikena, och många i södern längtar efter besked om sina försvunna närstående. General Marcus Jonathan, befälhavare för stadsvakten i Stormwind, tar hand om dessa blodiga emblem så att minnet av de nordliga försvararna bevaras och deras överlevande familjer äntligen får veta vad som hänt dem."}},faq={{q="Vad är Bloodied Insignias?",a="De är militära medaljer som bars av soldater från kungariket Lordaeron, vilka stred och dog under Alliansens fana i det tredje kriget.",al={"föremålet bloodied insignia","vad är det här emblemet","emblemens bakgrund"}},{q="Var hittar man dessa emblem?",a="De återfinns över hela Ruins of Lordaeron i Tirisfal Glades, där rikets försvarare gjorde sitt sista motstånd mot Scourge.",al={"var faller emblem","emblemens plats","märken i ruins of lordaeron"}},{q="Varför vill General Marcus Jonathan ha dem?",a="General Marcus Jonathan ansvarar för försvaret av Stormwind City, där otaliga nordliga flyktingar nu bor. Han samlar in dessa kvarlevor så att Lordaerons krigares offer kan hedras och deras levande släktingar i södern kan få besked.",al={"vem är marcus jonathan","varför ge dem till stormwind","marcus jonathan och emblem"}},{q="Varför bar Lordaerons soldater emblem från Alliansen?",a="Den ursprungliga Alliansen bildades i Lordaeron under kung Terenas Menethil II för att besegra den gamla Horden. Lordaeron var Alliansen av Lordaerons hjärta och ledare under det andra och tredje kriget.",al={"lordaerons alliansvapen","märke från alliansen av lordaeron"}},{q="Vad hände med soldaterna som bar dessa medaljer?",a="De dödades under det tredje kriget, när prins Arthas Menethil förrådde riket, mördade sin far och släppte lös de odöda i Scourge över huvudstaden.",al={"vad dödade soldaterna","lordaerons soldaters öde"}},{q="Finns det fortfarande levande släktingar till dessa soldater?",a="Ja. Tusentals invånare och soldater evakuerades från Lordaeron under pesten och Scourges invasioner och fann till sist en fristad i kungariket Stormwind.",al={"lordaerons flyktingar i stormwind","vem saknar soldaterna"}}},fp="17,169,20.402.0,26.384.0,32.119.0,32.141.0,43.191.0,55.176.0,52.147.0,51.144.0"}
P.entries["quest:952"] = {n="Grove of the Ancients",s="Grove of the Ancients är ett leveransuppdrag för Alliansen som för äventyrare från Darnassus över havet till Darkshore. På uppdrag av Arch Druid Fandral Staghelm tar kuriren ett brev till Onu, en vördnadsvärd Ancient of Lore som bor söder om Auberdine.",h="Grove of the Ancients är ett leveransuppdrag för Alliansen som för äventyrare från Darnassus över havet till...",kw={"ancient of lore","auberdine","cenarion circle","darkshore","darnassus","fandral staghelm","grove of the ancients","onu","the oracle glade"},ang={["class:Druid"]="När unga druider levererar brev mellan Arch Druid i Darnassus och Onu får de möta de olika temperamenten hos sina äldre inom Cenarion Circle. Staghelms driv ställs mot en Ancient of Lores stilla tålamod.",["faction:Alliance"]="För Alliansens kämpar som har uträttat sina ärenden i Darnassus ger den här leveransen ett tidigt skäl att ordna flygrutter med hippogryfer och utforska Darkshores kustland.",["race:NightElf"]="Uppdraget markerar den naturliga övergången från Teldrassils skyddade vagga till Kalimdors större vildmarker på fastlandet. Det lyfter fram den filosofiska skillnaden mellan Fandral Staghelm och Malfurion Stormrages läror."},sec={{t="Från grenverket",b="Efter att ha hjälpt till med ärenden kring The Oracle Glade på Teldrassils höjder blir äventyrarna kort och gott inkallade till ännu en tjänst av Arch Druid Fandral Staghelm. Staghelm låter inga händer gå sysslolösa och ger budbäraren i uppgift att föra ett brådskande meddelande över havet till Darkshores uråldriga skogar. Han säger åt dem att boka en flygtur med en hippogryf från staden."},{t="En skillnad i tålamod",b="När budbäraren når Darkshore och reser söder om Auberdine till Grove of the Ancients överlämnar hen brevet till Onu. Den väldige Ancient of Lore tar emot det under tyst eftertanke och antyder stillsamt att Staghelm är obevekligt otålig. För Onu och skogens uråldriga väktare sker allt i sin rätta tid – en lugn och bestående visdom som Shan'do Malfurion Stormrage förkroppsligade, men som Staghelm tydligt saknar."}},faq={{q="Vem ger uppdraget Grove of the Ancients?",a="Arch Druid Fandral Staghelm ger dig uppdraget från Cenarion Enclave i Darnassus när du har slutfört hans tidigare ärende kring The Oracle Glade.",al={"uppdragsgivare grove of the ancients","vem ger grove of the ancients","fandral staghelm uppdrag"}},{q="Var ligger Grove of the Ancients?",a="Grove of the Ancients ligger på fastlandet i Darkshore, strax söder om kusthamnen Auberdine.",al={"grove of the ancients plats","var ligger grove of the ancients","onu plats"}},{q="Vem är Onu?",a="Onu är en vis och vördnadsvärd Ancient of Lore som vilar i Darkshore. Som väktare och förvaltare av naturens visdom tar han emot brev från druidernas ledarskap i Darnassus.",al={"vem är onu","onu darkshore","onu ancient of lore"}},{q="Hur tar man sig från Teldrassil till Darkshore?",a="Resenärer tar sig vanligtvis från Darnassus ner till Rut'theran Village och flyger sedan över vattnet med en hippogryf till hamnbyn Auberdine i Darkshore.",al={"hur tar man sig till darkshore","resa till auberdine","hippogryf till darkshore"}},{q="Varför nämner Onu Shan'do Stormrage?",a="När Onu tar emot brevet kommenterar han Arch Druid Staghelms rastlösa brådska. Han tänker på att skogen följer sin egen takt, ett tidlöst tålamod som Shan'do Malfurion Stormrage förstod och respekterade.",al={"onu kommentar om malfurion","shan'do stormrage hänvisning","varför nämns shan'do"}},{q="Vilka uppdrag kommer före det här?",a="Det här uppdraget är det sista steget i en kort kedja med tre delar. Den börjar med The Enchanted Glade, följs av Teldrassil och skickar dig sedan vidare till Darkshore.",al={"förkunskapskrav grove of the ancients","grove of the ancients uppdragskedja","uppdrag före onu"}}},fx={["00893f03"]={q="Varför vill Arch Druid Fandral Staghelm att det här meddelandet överlämnas till Onu?",a="Fandral Staghelm vill upprätthålla nära kontakt med de uråldriga beskyddarna på andra sidan havet i Kalimdor. Onu, en Ancient of Lore som har sina rötter i Darkshore, har väntat på besked från Arch Druid om angelägenheter på Teldrassil. Nu när Fandral har fått de senaste rapporterna från The Oracle Glade är han otålig att genast skicka vidare sina rön och instruktioner och driva på sina planer för nattalverna.",al={"varför skicka meddelande till onu","fandrals motiv i grove of the ancients","varför vill fandral att det överlämnas"}},["658e120a"]={q="Varför väljer Fandral Staghelm dig att överlämna sitt meddelande?",a="Efter att ha sett dig föra bud från The Oracle Glade till Darnassus antar Fandral att du redan kan utföra känsliga ärenden över långa avstånd. I stället för att dra erfarna Cenarion-sändebud eller Sentinels från deras uppgifter sätter han helt enkelt en beprövad budbärare i tjänst för att föra hans skrivelse till Darkshore.",al={"varför just jag med fandrals meddelande","varför skicka spelaren till onu","varför inte skicka en sentinel"}}},fp="21,226,18.230.0,22.341.0,43.135.0,43.109.0,11.160.0,43.126.0,39.192.0,33.143.0"}
P.entries["quest:95204"] = {n="Crest of Lordaeron",s="Crest of Lordaeron är en väderbiten historisk artefakt med det fallna kungarikets emblem. Få sådana skatter överlevde Scourges förstörelse, och därför överlämnas den till Oran Snakewrithe i Undercity för att hjälpa till att bevara Forsakens historia.",h="Crest of Lordaeron är en väderbiten historisk artefakt med det fallna kungarikets emblem.",kw={"crest of lordaeron","forsaken","lordaeron","oran snakewrithe","relik","undercity"},ang={["faction:Horde"]="Genom att hjälpa Forsakens arkivarier i Undercity bidrar du till att bevara Lordaerons materiella arv bland ruinerna som Scourge lämnade efter sig.",["race:Undead"]="Som tidigare medborgare i Lordaeron värdesätter Forsaken bevarade reliker från sitt fallna kungarike som sällsynta kvarlevor från sina forna liv och sitt arv."},sec={{t="En kvarleva från det fallna kungariket",b="Lordaerons kungarike krossades under tredje kriget, och efter det återstod knappt något utom aska, ruiner och Scourges förödelse. Eftersom så mycket av rikets materiella kultur utplånades är bevarade insignier och emblem som Crest of Lordaeron ytterst sällsynta. För Forsaken som bor under ruinerna av Capital City är dessa föremål värdefulla, konkreta band till den civilisation de en gång tillhörde."},{t="Att bevara Forsakens arv",b="När den väderbitna vapenskölden återfinns ute i världen överlämnas den till Oran Snakewrithe i Undercity. Oran verifierar dess äkthet, och testar till och med metallen genom att bita i den, innan han bekräftar att det är ett äkta, till största delen intakt arvegods från deras hem. För Oran och Forsakens arkivarier hjälper varje räddad del till att återskapa en historia som Scourge försökte utplåna helt."}},faq={{q="Vad är Crest of Lordaeron?",a="Crest of Lordaeron är ett väderbitet emblem med det fallna människorikets symbol. Eftersom mycket få fysiska reliker överlevde Scourges förstörelse är den en ovärderlig historisk kvarleva för dem som försöker bevara Lordaerons arv.",al={"vad är crest of lordaeron","uppdraget med lordaerons vapensköld","föremålet vapensköld"}},{q="Vem vill ha vapenskölden i Undercity?",a="Vapenskölden förs till Oran Snakewrithe, som bor i Undercity. Oran granskar noga och bevarar återfunna artefakter med anknytning till det gamla kungariket.",al={"vem får vapenskölden","var lämnar man in vapenskölden","lämna in vapenskölden i undercity"}},{q="Varför biter Oran Snakewrithe i vapenskölden?",a="När Oran Snakewrithe tar emot vapenskölden biter han i den för att verifiera dess äkthet och materialsammansättning innan han förklarar den vara en äkta, till största delen intakt relik från Lordaeron.",al={"varför bita i vapenskölden","oran biter i vapenskölden"}},{q="Varför värdesätter Forsaken reliker från Lordaeron?",a="Forsaken är de odöda resterna av Lordaerons tidigare befolkning. Trots sin odödlighet och nya trohet är reliker från deras förstörda hemland påtagliga band till deras historia och identitet.",al={"varför bryr sig forsaken om lordaeron","forsakenreliker"}},{q="Vad händer med vapenskölden när den lämnas in?",a="Oran Snakewrithe tar hand om vapenskölden för att se till att den förvaras säkert. Han behandlar den som en dyrbar historisk skatt som hjälper till att återupprätta och minnas deras kungarikes arv.",al={"vad händer med vapenskölden","bevara vapenskölden"}},{q="Hur sällsynta är bevarade reliker från Lordaeron?",a="Fysiska emblem och reliker från tiden före tredje kriget är ytterst sällsynta. De flesta av Lordaerons symboler krossades, plundrades eller korrumperades när Arthas och Scourge tog över riket.",al={"är vapenskölden sällsynt","hur många vapensköldar finns kvar"}}},fp="18,148,40.264.0,28.278.0,31.183.0,33.113.0,41.137.0,46.153.0,52.134.0,45.150.0"}
P.entries["quest:95212"] = {n="Never Saddle on Quality",s="Never Saddle on Quality är ett uppdrag för Alliansen vid Amberstill Ranch i Dun Morogh. Djurvårdarna behöver felfria skinn från bergsleoparder för att tillverka varma sadlar åt riddjur som ska förstärka expeditionen till Alterac. På så vis kan både riddjur och ryttare stå emot den bitande kylan i de norra bergen.",h="Never Saddle on Quality är ett uppdrag för Alliansen vid Amberstill Ranch i Dun Morogh.",kw={"alterac","expeditionen till alterac","amberstill ranch","dun morogh","leopardpälsar","never saddle on quality","felfria leopardpälsar","baggar","sadlar"},ang={["class:Hunter"]="Uppdraget kräver skickliga spårare och jägare som kan hitta de vildaste bergsleoparderna i Dun Morogh och säkra felfria skinn.",["faction:Alliance"]="Amberstill Ranchs uppfödning av baggar förser direkt Alliansens styrkor med förstärkningar av riddjur i Alteracs iskalla höjder.",["race:Dwarf"]="Dun Moroghs tåliga bergsbaggar är typiska dvärgriddjur, och uppfödarna vid Amberstill Ranch vägrar utrusta dem med undermålig utrustning."},sec={{t="Expeditionens riddjur",b="Vid Amberstill Ranch i Dun Morogh förbereder djurvårdarna ett nytt lag robusta bergsbaggar som ska förstärka Alliansens expedition i Alterac. Förberedelserna har dock stannat av eftersom det saknas lämpligt material för att tillverka slitstarka sadlar som skyddar djuren mot kylan."},{t="Värme i de höga passen",b="För att stå emot den stränga kylan i Alteracbergen behöver expeditionens riddjur tjock isolering av hög kvalitet. Jägare skickas till de östra klipporna för att spåra upp de största och vildaste bergsleoparderna i Dun Morogh och ta tillvara deras felfria skinn. Då får Alliansens styrkor utrustning som klarar de höga passen."}},faq={{q="Vad är Never Saddle on Quality?",a="Never Saddle on Quality är ett uppdrag som utgår från Amberstill Ranch i Dun Morogh. En uppfödare behöver leopardpälsar av hög kvalitet för att tillverka robusta, varma sadlar åt ett lag baggar som förbereds som förstärkning till expeditionen till Alterac.",al={"vad är det här för uppdrag","uppdraget never saddle on quality","vad är never saddle on quality"}},{q="Varför behövs leopardpälsar?",a="Pälsarna behövs för att tillverka slitstarka, varma sadlar åt expeditionens riddjur. Bergsleoparderna i Dun Morogh har tjock, isolerande päls som skyddar ryttare och djur mot den bitande bergskylan i Alterac.",al={"varför leopardpälsar","vad används pälsarna till","varför felfria skinn"}},{q="Vart ska baggarna skickas?",a="Riddjuren ska till Alliansens styrkor som deltar i expeditionen till Alterac. Med hårt väder och pågående insatser i de höga passen är välutrustade ridbaggar ett viktigt stöd.",al={"vart ska baggarna","vem får baggarna","förstärkning till alterac"}},{q="Vilken roll har Amberstill Ranch här?",a="Amberstill Ranch ligger i de snöiga kullarna i Dun Morogh, öster om Kharanos. Gården är den främsta platsen för uppfödning och träning av dvärgarnas bergsbaggar.",al={"var ligger amberstill ranch","amberstill ranchs plats"}},{q="Var strövar leoparderna?",a="De vilda snöleoparderna strövar omkring på de snöiga höjderna och klipporna öster om Amberstill Ranch i Dun Morogh. Där måste jägare spåra upp de största djuren för att få tag på felfria skinn.",al={"var hittar man leoparder","var finns leoparder i dun morogh"}},{q="Varför är skydd mot kyla så viktigt för expeditionen?",a="Kungariket och bergen i Alterac är kända för sin stränga kyla och hårda vindar. Utan tjockt sadelmaterial av hög kvalitet riskerar både riddjur och ryttare förfrysning och utmattning i bergsterrängen.",al={"är det kallt i alterac","varför varma sadlar"}}},fp="23,229,23.201.0,26.290.0,32.198.0,29.181.0,30.175.0,37.125.0,27.157.0,63.166.0"}
P.entries["quest:95213"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder handlar om en tom, farlig kruttunna som hittas bland troggs nära Gol'Bolar Quarry. När du återlämnar den saknade tunnan till Quarrymaster Thesten avslöjas ett allvarligt säkerhetsbrott och en riskfylld brist i stenbrottets sprängmedelsförråd.",h="Stolen Blasting Powder handlar om en tom, farlig kruttunna som hittas bland troggs nära Gol'Bolar Quarry.",kw={"sprängkrut","dun morogh","tom kruttunna","gol'bolar quarry","kruttunna","quarrymaster thesten","stolen blasting powder","thesten","troggs"},ang={["faction:Alliance"]="Det är viktigt för alliansens verksamhet i Khaz Modan att skydda Dun Moroghs försörjningsleder och gruvutposter mot troggangrepp.",["profession:Engineering"]="Sprängkrut är ett farligt och instabilt ämne. Ingenjörerna förstår bättre än någon annan vilken förödelse troggs kan orsaka med obehöriga sprängämnen.",["profession:Mining"]="Stenbrottets arbete bygger på kontrollerade sprängningar för att utvinna sten, men saknade kruttunnor signalerar allvarlig fara inne i gruvgångarna.",["race:Dwarf"]="Gol'Bolar Quarry förser Ironforge med sten och resurser, så säkerheten kring stenbrottets sprängämnen är en akut angelägenhet för alla dvärgar."},sec={{t="En farlig upptäckt",b="En tom tunna märkt med allvarliga varningar visar att farligt sprängkrut har hamnat i obehörigas händer vid Gol'Bolar Quarry. Sådana sprängmedel får bara användas vid kontrollerad brytning med stenbrottsmästarens uttryckliga tillstånd. Att tunnan hittas bland fientliga troggs tyder på ett betydligt mer explosivt hot mot gruvan än vanliga störningar i arbetet."},{t="Stenbrottsmästarens oro",b="När den tomma behållaren återlämnas till Quarrymaster Thesten besannas de värsta farhågorna hos dvärgarnas arbetsledare. Thesten blir blek när han ser tunnan och inser att det saknade sprängkrutet redan har tömts och hanterats av troggsen som svärmar i området under jord. Upptäckten får stenbrottets ledning att febrilt försöka ta reda på vad varelserna tänker spränga härnäst."}},faq={{q="Vad är Stolen Blasting Powder?",a="Stolen Blasting Powder är ett uppdrag som inleds när du hittar en tom tunna med sprängkrut och farlighetsvarningar i händerna på troggs nära Gol'Bolar Quarry. Det gör Quarrymaster Thesten uppmärksam på stölden av explosiva gruvförnödenheter.",al={"vad är stolen blasting powder","uppdrag med kruttunna","lore om tom kruttunna"}},{q="Vem ska få den tomma kruttunnan?",a="Den tomma kruttunnan ska lämnas direkt till Quarrymaster Thesten, som leder arbetet vid Gol'Bolar Quarry i Dun Morogh.",al={"vart ska tunnan lämnas","vem är thesten","stenbrottsmästarens plats"}},{q="Varför är det stulna sprängkrutet farligt?",a="Tunnan har tydliga varningar om att stenbrottsmästaren måste godkänna användningen och innehöll farligt sprängkrut. Om troggs får tag på tunga sprängämnen eller detonerar dem hotas hela stenbrottet och närliggande bosättningar.",al={"varför är sprängkrut farligt","troggs med sprängämnen","varför har troggs sprängkrut"}},{q="Vad är Gol'Bolar Quarry?",a="Gol'Bolar Quarry är en dvärgisk gruva i Dun Morogh där sten och mineraler bryts åt Ironforge.",al={"var ligger gol'bolar","stenbrottets plats","gol'bolar dun morogh"}},{q="Varför blir Quarrymaster Thesten blek?",a="När Quarrymaster Thesten får syn på den tomma tunnan blir han märkbart blek och frågar var den hittades. Han inser genast att det farliga innehållet redan har hamnat i händerna på fientliga troggs.",al={"varför blir thesten blek","thestens reaktion","vad säger thesten"}},{q="Vad gör troggs nära Gol'Bolar Quarry?",a="Troggs har tagit över de lägre delarna och utkanterna av Gol'Bolar Quarry. De stör dvärgarnas gruvarbetare och letar igenom utrustning och sprängkrut från gruvan.",al={"finns det troggs i stenbrottet","trogginvasion i dun morogh","varför tar troggs sprängkrut"}}},fp="22,191,21.331.0,24.279.1,31.192.0,40.119.0,44.169.0,25.107.0,40.168.0,44.164.0"}
P.entries["quest:95214"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder är ett uppdrag vid Gol'Bolar Quarry i Dun Morogh där äventyrare måste återta försvunnen ammunition. Primitiva troggs har kommit över tillräckligt med sprängpulver för att jämna en fästningsflygel med marken, så Quarrymaster Thesten måste rekrytera diskret hjälp innan en katastrof inträffar.",h="Stolen Blasting Powder är ett uppdrag vid Gol'Bolar Quarry i Dun Morogh där äventyrare måste återta...",kw={"sprängpulver","dun morogh","sprängämnen","gol'bolar quarry","ironforge","king magni","quarrymaster thesten","thesten","troggs"},ang={["faction:Alliance"]="Försörjningslederna och stenbrotten i Dun Morogh är avgörande för Alliansens fäste i bergen. Att bevara freden och vakta farlig ammunition skyddar High Seat i närbelägna Ironforge.",["profession:Mining"]="Sprängpulver är ett oumbärligt redskap för att röja sten och öppna malmådror i djupa schakt, men det kräver disciplin att hantera. Att förlora stora tunnor till vilda grottvarelser är varje quarrymasters mardröm.",["race:Dwarf"]="Gol'Bolar Quarry bidrar till Ironforges stenhantverk och utgrävningar. Att låta underjordiska troggs göra gruvsprängämnen till vapen alldeles utanför King Magnis dörr är ett förödmjukande säkerhetsmisslyckande för varje dvärgförman."},sec={{t="Ett saknat förråd",b="Vid Gol'Bolar Quarry i Dun Morogh är dvärgarnas arbete starkt beroende av kraftiga sprängladdningar för att bryta sten och öppna djupa malmådror. Säkerheten brast dock när primitiva troggs som lurade bland klipporna i närheten lyckades komma över en hel stor leverans högklassigt sprängpulver. Quarrymaster Thesten fick skynda sig att hitta dugligt folk innan tjuvflocken råkade utlösa en explosion."},{t="En krutdurk bland klipporna",b="Mängden material som saknas är häpnadsväckande: Thesten säger att tunnan innehöll tillräckligt med sprängkraft för att förvandla King Magni Bronzebeards storslagna tronsal till en sal under bar himmel. Troggarna bar det farliga bytet österut till sina primitiva läger vid foten av bergen. Om de lämnades åt sig själva skulle det bara vara en tidsfråga innan de upptäckte eld eller slog sten mot gnista."},{t="En tyst lösning",b="När de stulna laddningarna har slitits ur troggarnas händer och tryggt återförts till stenbrottets förråd drar Thesten en tung suck av lättnad. Quarrymastern belönar äventyraren med en diskret vädjan om att inte nämna den lilla händelsen för någon."}},faq={{q="Vem är Quarrymaster Thesten?",a="Quarrymaster Thesten övervakar arbetet vid Gol'Bolar Quarry i Dun Morogh. Han ansvarar för utgrävningsplatsens säkerhet och produktivitet, och hamnar i en pinsam knipa när ett stort förråd industrisprängpulver försvinner under hans uppsikt.",al={"vem är thesten","quarrymaster thesten","vem ger uppdraget"}},{q="Var finns det stulna sprängpulvret?",a="Troggarna som håller till bland klipporna och i hålorna strax öster om Gol'Bolar Quarry bar bort pulvret. Äventyrare skickas till de klippiga utlöparna för att ta tillbaka de farliga tunnorna och säckarna från varelserna innan katastrofen slår till.",al={"var finns stulit sprängpulver","troggarnas plats","pulvrets plats"}},{q="Varför stal troggarna sprängpulvret?",a="Troggs är primitiva underjordiska varelser som drivs av enkel list och revirtänkande. De stal pulvret från stenbrottets arbetare, och Quarrymaster Thesten befarar att även klumpiga experiment kan leda till att de råkar antända sprängämnena.",al={"varför stjäl troggs pulver","vad vill troggs med pulver"}},{q="Hur farligt är det stulna sprängpulvret?",a="Enligt Quarrymaster Thesten innehöll den saknade tunnan tillräckligt med explosivt pulver för att spränga King Magnis tronsal till spillror och lämna den öppen mot himlen. Om allt detonerade på en gång i stenbrottet eller grottorna skulle kraften vara förödande.",al={"hur kraftigt är pulvret","pulver i magnils tronsal","är pulvret farligt"}},{q="Varför vill Quarrymaster Thesten hålla händelsen hemlig?",a="När du återlämnar pulvret betalar Thesten dig och ber dig att inte nämna den lilla händelsen för någon. Han säger inte varför, men att förlora så mycket sprängämne till troggs är uppenbarligen något han helst vill hålla tyst om.",al={"varför hålla det hemligt","thestens hemlighet","nämn inte händelsen"}},{q="Vad är Gol'Bolar Quarry?",a="Gol'Bolar Quarry är en framstående utgrävningsplats för dvärgar i östra Dun Morogh, där man bryter sten till byggnads- och ingenjörsprojekt i hela riket. I de djupa schakten får arbetarna regelbundet hantera underjordiska skadedjur som troggs som tränger fram ur berget.",al={"vad är gol'bolar","gol'bolar quarry","var ligger gol'bolar"}}},fp="22,183,19.282.0,25.250.0,16.202.1,28.188.0,46.166.0,45.194.0,44.189.0,59.199.0,25.191.0"}
P.entries["quest:95216"] = {n="The New Plague",s="The New Plague är ett forskningsprojekt som Theodore Griffs bedriver i Apothecarium i Undercity. Efter rapporter om en dödlig leddjursart i ruinerna ovanför, vars gift fräter även på odött kött, vill Griffs analysera och bakåtkonstruera dess dödliga toxiner.",h="The New Plague är ett forskningsprojekt som Theodore Griffs bedriver i Apothecarium i Undercity.",kw={"apothecarium","sekret","ruins of lordaeron","the new plague","theodore griffs","giftig variant","undercity","witherfang"},ang={["faction:Horde"]="Horden tolererar de övergivna som taktiska allierade i Eastern Kingdoms, men de illavarslande biologiska experimenten som pågår i Apothecarium väcker ofta oro hos mer hedervärda medlemmar.",["race:Undead"]="Royal Apothecary Society jagar obevekligt toxiner som kan skada både levande och döda för att säkra de övergivnas överhöghet och skydda deras unga nation."},sec={{t="Apotekarens ambition",b="I Apothecariums fuktiga skrymslen samlar Royal Apothecary Society ständigt in virulenta ämnen från hela Azeroth. Theodore Griffs, en av dess hängivna forskare, spårar exotiska bestar och dödliga föroreningar för att främja de övergivnas alkemiska innovationer. Efter att ha hört rykten om en giftig varelse som strövar bland de krossade stenarna ovanför skickar Griffs ut äventyrare för att hämta ett användbart prov innan tillfället går förlorat."},{t="Ett köttfrätande toxin",b="Målet för forskningen är Witherfang, ett giftigt leddjur som jagar i Lordaerons yttra ruiner. Dess gift har den sällsynta och skrämmande egenskapen att bryta ned inte bara levande vävnad, utan även dött och bevarat kött. För en apotekare som arbetar med att förfina biologisk krigföring och skydda de övergivnas rike ger kunskapen om hur ett sådant toxin kringgår nekrotiskt motstånd ovärderliga kemiska insikter."},{t="Bakåtkonstruktion av sekretet",b="Även om Griffs uttrycker sin frustration när äventyrare dödar Witherfang i stället för att fånga den levande, räcker det insamlade sekretet som analysmaterial. Genom att bryta ned varelsens kroppsvätskor tänker apotekaren bakåtkonstruera giftets virulenta verkningssätt, så att även ett krossat leddjur bidrar till Undercitys växande kemiska styrka."}},faq={{q="Vem är Theodore Griffs?",a="Theodore Griffs är en apotekarforskare verksam i Apothecarium i Undercity. Han undersöker kraftfulla toxiner och exotiska exemplar för att framställa föreningar åt de övergivna och visar föga hänsyn till den som inte uppskattar det känsliga alkemiska hantverket.",al={"vem ger uppdraget the new plague","theodore griffs","vem är theodore griffs"}},{q="Vad är Witherfang?",a="Witherfang är ett dödligt, giftigt leddjur som lurar i Ruins of Lordaeron ovanför Undercity. Det producerar ett anmärkningsvärt frätande toxin som kan lösa upp även motståndskraftigt odött kött.",al={"vad är witherfang","var finns witherfang","leddjur i ruins of lordaeron"}},{q="Varför vill Theodore Griffs ha Witherfangs gift?",a="Theodore Griffs vill studera Witherfangs gift för att ta reda på hur dess toxiner fräter igenom odött kött. Han hoppas kunna bakåtkonstruera ämnet till kraftfulla varianter för de övergivnas alkemiska arsenal.",al={"vad vill theodore med witherfang","varför samla in den mycket giftiga varianten"}},{q="Varför är Theodore Griffs upprörd när du återvänder?",a="Theodore Griffs hoppades att exemplaret skulle hållas intakt eller skördas varsamt i stället för att dödas direkt. Han är irriterad över att Witherfang dödades, men lyckades ändå utvinna tillräckligt med kvarvarande sekret ur lämningarna för att studera dess egenskaper.",al={"varför blev theodore arg","förstörde jag provet"}},{q="Vad är Apothecariums syfte?",a="Apothecarium är Royal Apothecary Societys forskningscentrum under Lordaeron. Det beskrivs som Undercitys viktigaste kvarter och ägnas åt att testa virulenta varianter, framställa alkemiska vapen och experimentera på exotiska varelser.",al={"apothecariums syfte","varför är apothecarium viktigt"}},{q="Hur anser Theodore att virulenta varianter bäst överförs?",a="Enligt Theodore Griffs är det mest potenta och tillförlitliga sättet att överföra smitta alltid att föra in den direkt i blodomloppet.",al={"hur överförs giftet","överföringssätt"}}},fp="14,171,25.338.0,24.301.0,29.280.1,23.260.0,19.139.0,49.156.0,45.172.0,40.236.0,64.109.0"}
P.entries["quest:95217"] = {n="The Quarry's Smith",s="The Quarry's Smith är ett uppdrag från Frast Dokner, en yrkesverksam smed stationerad vid ett läger i ett stenbrott. När en väntad leverans uteblir och han blir strandsatt vänder sig smeden till villiga resenärer för att samla råmetall och tåligt läder till viktiga reparationer av lägret. I utbyte mot materialen delar Dokner med sig av praktiska smidestekniker till blivande metallarbetare.",h="The Quarry's Smith är ett uppdrag från Frast Dokner, en yrkesverksam smed stationerad vid ett läger i ett...",kw={"smide","kopparbarrar","dun morogh","dvärg","frast dokner","gol'bolar quarry","ironforge","the quarry's smith","hårda vildsvinshudar"},ang={["faction:Alliance"]="Genom att hjälpa Dokner håller du det avlägsna dvärgiska stenbrottet i drift och stärker den lokala infrastrukturen och utrustningens beredskap i det snöiga höglandet.",["profession:Blacksmithing"]="Frast Dokner fungerar som fältmentor för lärlingar inom smide och byter sina hårt vunna smidestekniker mot råmetall och läder som håller hans städ varmt.",["profession:Mining"]="Gruvarbetare som arbetar i fyndigheterna i närheten får en omedelbar lokal köpare för sina smälta kopparbarrar och kan förvandla råmalm till praktisk utbildning och reparationer av lägret.",["race:Dwarf"]="Gol'Bolar Quarry visar Bronzebeard-klanens företagsamhet och industri i Dun Morogh, där dvärgarnas beslutsamhet håller smedjorna brinnande även när försörjningskaravanerna blir försenade."},sec={{t="Brist i stenbrottet",b="Livet vid en aktiv utgrävning kräver ständigt underhåll, från att vässa hackor och byta ut slitna fästen till att förstärka lägerutrustning. När en viktig leverans inte kommer i tid börjar det dagliga arbetet stanna av. Utan färska varor från de stora handelsvägarna tvingas hantverkarna på plats improvisera och vända sig till förbipasserande äventyrare för att hålla lägret fungerande. Frast Dokner, som arbetar vid smedjan medan förseningarna fortsätter, förlitar sig på alla som är villiga att leta fram enkla metaller och hudar i stället för att vänta sysslolös på transportvagnar som kanske blir hopplöst försenade."},{t="En lärlings uppgörelse",b="Traditionella dvärggillen för smeder värdesätter disciplin och välbevarade metoder, och delar sällan med sig av yrkeshemligheter till tillfälliga vandrare. Dokner väger dock lokala behov mot gillets formaliteter. Eftersom det råder omedelbar brist på bearbetbar koppar och slitstarkt läder för att laga verktyg och lägerutrustning erbjuder han ett praktiskt byte: kom med råmaterialen direkt till hans städ, så lär han dig sina personliga smidestekniker. Det är en ömsesidigt fördelaktig uppgörelse som vuxit fram ur gränslandets behov, där värdefull yrkeskunskap byts mot omedelbar överlevnad och underhåll."}},faq={{q="Vem är Frast Dokner?",a="Frast Dokner är en erfaren smed stationerad vid ett läger i ett stenbrott. Han ansvarar för att underhålla verktyg, byggnadsbeslag och utrustning åt arbetarna på plats. När logistiska förseningar skär av hans vanliga försörjningslinje tar han saken i egna händer och rekryterar förbipasserande äventyrare för att skaffa råmaterialen han så desperat behöver.",al={"frast dokners bakgrund","vem är smeden i stenbrottet","smed i stenbrott"}},{q="Varför behöver stenbrottet kopparbarrar och vildsvinshudar?",a="Utgrävningen och underhållet av lägret förbrukar stora mängder tåliga material. Koppar är en lättillgänglig, formbar metall som passar till ersättningsbeslag, spikar, fästen och förstärkningsband för trasiga verktyg. Hårda vildsvinshudar ger slitstarkt läder till bälgar, verktygslindor, remmar och skyddsförkläden som står emot de hårda gnistorna och det tunga sliparbetet i stenbrottet.",al={"varför kopparbarrar och vildsvinshudar","material som smeden i stenbrottet behöver","reparationsmaterial till stenbrottet"}},{q="Varför är leveransen försenad?",a="Frast Dokner berättar inte vad förseningen beror på, men landvägarna genom snöiga klippor och bergspass plågas ofta av hårda snöstormar, kringströvande vilda djur och fientliga bakhåll från troggar eller banditer. Avlägsna gruvläger och stenbrott är ofta de första bosättningarna som drabbas när transportvagnar blir försenade.",al={"försenad leverans","vad hände med förnödenheterna","varför är förnödenheterna försenade"}},{q="Vad erbjuder Frast Dokner i utbyte mot materialen?",a="I stället för att bara erbjuda mynt lovar Frast Dokner att dela med sig av sina personliga smidestekniker till den som skaffar förnödenheterna han behöver. För en blivande hantverkare ger undervisning direkt från en erfaren yrkesman ute i fält praktiska insikter i metallarbete och utrustningsunderhåll som stadens formella smedgillen sällan lär ut till nybörjare.",al={"belöning från smeden i stenbrottet","vad lär frast ut","frasts smidestekniker"}},{q="Var ligger stenbrottet?",a="Frast Dokner arbetar i Dun Morogh vid Gol'Bolar Quarry, en dvärgisk utgrävningsplats inbäddad i de snöiga förbergen söder om Kharanos. Stenbrottet utsätts ständigt för hårt vinterväder och aggressiva underjordiska troggar, som regelbundet trakasserar gruvarbetarna och stör handelskaravaner från Ironforge.",al={"vilket stenbrott är det här","var finns frast dokner","smedens plats i stenbrottet"}},{q="Tillhör Frast Dokner Ironforge?",a="Ja, Frast Dokner och lägret vid stenbrottet verkar inom Bronzebeard-klanens och kungariket Ironforges domäner. Stenbrytning och malmutvinning i bergen i Dun Morogh är viktiga för dvärgakungarikets byggprojekt och försvarsverk, vilket gör lokala smeder som Dokner oumbärliga för Ironforges industriella styrka.",al={"frast dokner ironforge","tillhör stenbrottet ironforge","dvärgarnas lojalitet i stenbrottet"}}},fp="18,217,23.504.0,23.468.0,20.252.0,52.315.0,32.278.0,59.287.0,29.246.0,42.258.0"}
P.entries["quest:95250"] = {n="Abominable Creatures",s="Abominable Creatures är ett uppdrag från Captain Truman, en mänsklig lojalist som desperat väntar på förstärkningar i utkanten av Lordaerons fallna huvudstad. Han tror att hans befälhavare, en vördad Grand Marshal, fortfarande kämpar tappert i närliggande Ruins of Lordaeron och ber därför en duglig äventyrare att leta upp honom. Uppdraget avslöjar det dystra ödet för rikets förlorade försvarare och den bittra fientlighet som pyr bland de överlevande lojalistiska styrkorna.",h="Abominable Creatures är ett uppdrag från Captain Truman, en mänsklig lojalist som desperat väntar på...",kw={"abominable creatures","captain truman","grand marshal","head of the baron","lordaeron","ruins of lordaeron","baronen","lordaerons sanna söner"},ang={["faction:Alliance"]="Uppdraget visar den farliga och isolerade situationen för resterna av Alliance som försöker verka bland ruinerna i norra Lordaeron. Det belyser hur de kvarvarande lojalistiska trupperna kämpar med sviktande hopp och den psykiska påfrestningen av att möta övermäktiga monster.",["race:Human"]="Mänskliga äventyrare får bevittna det hjärtskärande ödet för Lordaerons fallna ledarskap, då till och med en aktad Grand Marshal förvandlades till en grotesk odöd fasa. Captain Trumans bittra sorg och nationalistiska nit speglar det råa trauma som bärs av mänskliga överlevare som desperat vill återta sitt förfädershem.",["race:Undead"]="För Forsaken är baronens groteska förvandling en dyster påminnelse om hur Scourge stympade Lordaerons främsta försvarare och förvandlade dem till monstruösa styggelser. Captain Trumans löfte att rensa ruinerna från alla bestar och odöda speglar den obevekliga fientlighet som de levande lojalistiska styrkorna hyser mot folket i Undercity."},sec={{t="En desperat vakt",b="Captain Truman står vaksam vid sin post och väntar oroligt på de sedan länge försenade förstärkningarna som ska hjälpa till att försvara Lordaeron. Han litar på sin överordnades stridsförmåga, en berömd Grand Marshal som han beskriver som en lång, ståtlig hjälte. Truman är fortfarande bunden av sin plikt efter att ha fått order om att hålla linjen medan befälhavaren gav sig in i den pågående striden. Kaptenen misstror utomstående djupt och föraktar öppet dem han anser vara av en lägre ras. Han vägrar att lita på lokala irreguljära styrkor. När en duglig resenär närmar sig tar Truman tillfället i akt att be om hjälp. Han vädjar till någon att bege sig in i det ödelagda området, se efter sin herre och bedöma striden."},{t="Ruins of Lordaeron",b="Sökandet leder äventyrarna rakt in i de farliga Ruins of Lordaeron, den krossade huvudstaden som föll för Scourge under det tredje kriget. Captain Truman väntar sig att hans ärorika ledare ska stå triumferande över de fallna, men verkligheten i den pesthärjade staden är långt dystrare. Ruinerna vimlar av fasor, odöda rester och styggelser som strövar omkring på de sönderslagna stenlagda torgen. För att ta sig fram genom de ödelagda gatorna måste man konfrontera den brutala sanningen om vad som hände försvararna som gav sig in i staden. I stället för att hitta en oklanderlig riddare som håller linjen upptäcker resenärerna att befälhavaren mött ett tragiskt och förvridet slut bland monstren på gårdarna."},{t="En fasansfull upptäckt",b="När äventyrarna hittar den försvunne befälhavaren, som kallas baronen, gör de en fasansfull upptäckt: den en gång så ståtliga hjälten har förvandlats till ett groteskt odött monster. För att slutföra det dystra uppdraget måste de döda varelsen och ta med sig Head of the Baron tillbaka till Captain Truman. När Truman får se huvudet från sin tidigare herre reagerar han med chock, fasa och djup avsky. Kaptenen kan inte acceptera befälhavarens fruktansvärda öde och brister ut i bitter vrede. Han anklagar äventyraren för att stå på monstrens sida och svär att Lordaerons sanna söner en dag ska återta sitt land och rensa det från alla bestar."}},faq={{q="Vem ger uppdraget Abominable Creatures?",a="Uppdraget erbjuds av Captain Truman, en mänsklig lojalist som är stationerad i området kring det fallna riket. Han håller oroligt sin post medan han väntar på förstärkningar och söker desperat nyheter om sin befälhavare, en vördad Grand Marshal som gav sig in i närliggande Ruins of Lordaeron.",al={"vem ger abominable creatures","uppdragsgivare för abominable creatures","var startar abominable creatures"}},{q="Var utspelar sig uppdraget Abominable Creatures?",a="Uppdraget leder äventyrarna till Ruins of Lordaeron, den krossade huvudstaden som översvämmas av Scourges fasor och odöda rester. Captain Truman har en post utanför den pesthärjade huvudstaden och ber modiga resenärer att bege sig rakt in i de farliga ruinerna för att hitta hans försvunne överordnade.",al={"abominable creatures plats","var slutförs abominable creatures","abominable creatures zon"}},{q="Vem är Captain Trumans herre?",a="Captain Truman kallar sin herre för Grand Marshal och prisar honom som en lång, ståtlig militärhjälte. Uppdragsmålen kallar dock den försvunne adelsmannen för baronen, vilket visar att han var en högt uppsatt aristokrat och militär befälhavare som ledde rikets försvar.",al={"vem är trumans befälhavare","grand marshals identitet enligt truman","vem är baronen"}},{q="Vad hände med Grand Marshal i Ruins of Lordaeron?",a="Grand Marshal lyckades inte hålla stånd med segern i sikte. Han dödades och förvandlades till en monstruös odöd varelse i Ruins of Lordaeron. När äventyrarna hittar honom ser de en styggelse som kallas baronen. De tvingas förgöra honom och ta hans avhuggna huvud.",al={"vad hände med baronen","grand marshals öde","är grand marshal död"}},{q="Varför blir Captain Truman arg när du lämnar in uppdraget?",a="Captain Truman väntade sig att hans ståtlige befälhavare skulle vara vid liv och segerrik. När han får se baronens groteska, muterade huvud fylls han av fasa och avsky. Rasande anklagar han äventyraren för att dra ett sjukt skämt och umgås med vidriga bestar.",al={"varför är truman arg","trumans reaktion på abominable creatures","varför skriker truman åt dig"}},{q="Vad menar Captain Truman med ”Lordaerons sanna söner”?",a="Captain Truman använder uttrycket om nitiska mänskliga patrioter som är fast beslutna att återta sitt krossade hemland. Hans ord uttrycker en våldsam och intolerant vision där de rättmätiga mänskliga överlevarna ska rensa riket från alla odöda, bestar och personer som anses stå i förbund med dem.",al={"vad betyder lordaerons sanna söner","vilka är lordaerons sanna söner","truman och de sanna sönerna"}},{q="Varför vägrar Captain Truman att lita på ”halvblod”?",a="Captain Truman visar djupt förakt för icke-mänskliga raser och irreguljära allierade, som han avfärdar som opålitliga halvblod och avskum. Hans intensiva främlingsfientlighet hindrar honom från att anförtro sig åt någon annan än dem han anser vara rikets värdiga representanter.",al={"truman och halvblod","varför är captain truman rasistisk","trumans främlingsfientlighet"}}},fp="20,312,17.524.0,22.516.0,23.483.1,41.230.0,53.227.0,31.222.0,61.182.0,61.234.0,62.233.0,54.218.0"}
P.entries["quest:95254"] = {n="WANTED: Trapclaw",s="Fimbo Greasemitz vill ha Trapclaws klo efter att den enorma krabban stjäl bete och skär av fiskelinor under bryggorna. Ta den till honom, så lovar han en måltid tillagad med sin hemliga kryddblandning.",h="Fimbo Greasemitz vill ha Trapclaws klo efter att den enorma krabban stjäl bete och skär av fiskelinor under...",kw={"bete","krabba","krabbkött","bryggor","fimbo greasemitz","fiskelinor","klo","trapclaw"},sec={{t="Under bryggorna",b="Fimbo Greasemitz är ute efter krabbkött, och Trapclaw har krupit omkring under bryggorna. Den stora krabban stjäl bete och skär av fiskelinor. Fimbo ber dig att ta med Trapclaws klo till honom, för han planerar att använda den till en måltid."}},faq={{q="Vem vill ha Trapclaws klo?",a="Fimbo Greasemitz vill ha Trapclaws klo för krabbköttets skull.",al={"vem vill ha klon","fimbo greasemitz begäran"}},{q="Vad gör Trapclaw?",a="Trapclaw kryper omkring under bryggorna, stjäl bete och skär av fiskelinor.",al={"varför trapclaw","krabba under bryggor"}},{q="Varför vill Fimbo ha klon?",a="Fimbo vill ha krabbkött och ber om Trapclaws klo.",al={"vad ska klon användas till","begäran om krabbkött"}},{q="Vad lovar Fimbo att laga?",a="Fimbo säger att han ska laga en rätt med smör och sin hemliga kryddblandning.",al={"vilken måltid","fimbos rätt"}}},fp="16,188,15.218.0,36.59.0,23.75.0,31.54.0,32.68.0"}
P.entries["quest:953"] = {n="The Fall of Ameth'Aran",s="Sentinel Tysha Moonblade skickar äventyrare till Ameth'Arans hemsökta ruiner i Darkshore för att tyda forntida stentavlor. Inskrifterna berättar om tragedin och förödelsen som drabbade Highborne-staden under Sundering. Kunskapen ska föras till Circle of Ancients i Auberdine, där man återupptäcker historia som till stor del gick förlorad under War of the Ancients.",h="Sentinel Tysha Moonblade skickar äventyrare till Ameth'Arans hemsökta ruiner i Darkshore för att tyda...",kw={"ameth'aran","auberdine","azshara","circle of ancients","darkshore","highborne","sundering","tavlor","tysha moonblade"},ang={["class:Mage"]="Tavlorna ger en skakande inblick i den elviska magins höjder före Sundering och den fruktansvärda förödelse som följde när kraften spårade ur.",["faction:Alliance"]="När du hjälper Sentinels att säkra Darkshores historia bevarar du viktig kunskap åt nattalvsledarna som vägleder Alliance på Kalimdor.",["race:NightElf"]="Ameth'Arans ruiner är en dyster påminnelse om dina förfäders övermod under drottning Azshara och de katastrofala följderna av otyglad arkanisk trolldom."},sec={{t="Highbornes ekon",b="Långt innan kusten sprack upp och blev Darkshores dimmiga vidder var Ameth'Aran en blomstrande bosättning, där drottning Azsharas främsta trollkarlar utövade mäktig arkansk magi. Efter Well of Eternitys katastrofala förstörelse för tiotusen år sedan återstod bara krossad marmor och spruckna pelare av staden. Än i dag hemsöks den av de rastlösa, plågade andarna från Highborne, som dog när deras guldålder slets sönder."},{t="Förlorade krönikor återfinns",b="War of the Ancients kastade nattalvernas civilisation in i en kaotisk kamp för överlevnad, och förvånansvärt få skriftliga berättelser överlevde Great Sundering oskadda. Sentinel Tysha Moonblade försökte själv undersöka ruinerna och fann två stora ingraverade tavlor, Lay of Ameth'Aran och Fall of Ameth'Aran, innan spöklika Highborne-vålnader tvingade henne att dra sig tillbaka. Genom att hämta avskrifterna kan sanningen om den forntida katastrofen nå de lärda i Circle of Ancients i Auberdine."}},faq={{q="Vad är Ameth'Aran?",a="Ameth'Aran är en forntida nattalvsruin i centrala Darkshore. För tiotusen år sedan var det en stad där drottning Azsharas Highborne-adelsmän öppet utövade och studerade storslagen arkansk magi, innan den föll under Great Sundering.",al={"ameth'aran historia","vad var ameth'aran","vem bodde i ameth'aran"}},{q="Varför finns det spöken i Ameth'Aran?",a="De rastlösa spöken som hemsöker ruinerna är andar från Highborne som levde och dog där. De fångades i den plötsliga, våldsamma katastrof som krossade Well of Eternity och splittrade Kalimdor, och deras andar förblir bundna till ruinerna i evig plåga.",al={"varför finns andar i ameth'aran","ameth'arans spöken","rastlösa highborne"}},{q="Vem är Sentinel Tysha Moonblade?",a="Sentinel Tysha Moonblade är en nattalvssentinel som är stationerad längs vägen i Darkshore. Hon fick i uppdrag att spana efter forntida platser och återfinna förlorade historiska dokument åt Circle of Ancients i Auberdine.",al={"tysha moonblade","vem ger fall of ameth'aran"}},{q="Varför vill Circle of Ancients att tavlorna ska läsas?",a="Förstörelsen av Well of Eternity kastade Kalimdor in i en enorm omvälvning och utplånade otaliga bibliotek och monument. Eftersom så få skriftliga dokument överlevde War of the Ancients ger tavlorna sällsynta ögonvittnesskildringar av Sundering ur Highbornes perspektiv.",al={"varför läsa tavlorna","circle of ancients tavlor","betydelsen av lay of ameth'aran"}},{q="Var finns tavlorna?",a="De två stora tavlorna, Lay of Ameth'Aran och Fall of Ameth'Aran, är inristade i stående stenmonument bland Ameth'Arans förstörda gårdar, omgivna av stadens tidigare invånares vandrande spöken.",al={"var finns ameth'arans tavlor","tavlornas platser","hur läser man ameth'aran"}},{q="Vad hände med Ameth'Arans Highborne under Sundering?",a="När Well of Eternity imploderade vid höjdpunkten av War of the Ancients slet enorma skakningar och arkaniska motreaktioner Kalimdor i stycken. Ameth'Aran rasade samman och begravde sina invånare, medan deras spöken blev kvar i rasmassorna.",al={"hur föll ameth'aran","ameth'arans förstörelse"}}},fx={["4f4506ec"]={q="Varför vill Sentinel Tysha Moonblade att det här blir gjort?",a="Sentinel Tysha Moonblade skickades på Circle of Ancients vägnar för att undersöka de uråldriga ruinerna. Uppteckningar från War of the Ancients och Sundering är ytterst sällsynta på grund av den tidens omvälvningar. Genom att samla in historien som ristats på tavlorna kan hon ge druiderna och de äldste i Auberdine en fullständig redogörelse.",al={"tysha moonblades motiv","varför behöver tysha detta","varför studera ameth'aran-tavlorna"}},["2329a43d"]={q="Varför behöver Sentinel Tysha Moonblade din hjälp?",a="Tysha gav sig tidigare in i Ameth'Aran för att själv undersöka tavlorna, men överfölls och drevs bort av de hämndlystna Highborne-andar som hemsöker ruinerna. Eftersom hon inte kan skriva av inskrifterna på ett säkert sätt under ständiga andeattacker behöver hon en skicklig äventyrare som kan ta sig in i ruinerna och tyda texten åt henne.",al={"varför kan inte tysha läsa tavlorna","varför behöver tysha mig","varför går inte tysha själv"}}},fp="22,278,23.289.0,26.458.0,19.221.0,35.199.0,32.190.0,56.311.0,30.204.0,66.216.0"}
P.entries["quest:95314"] = {n="That Shadowvale Green Elixir",s="Carolai Anise i Brill söker fynd från den övergivna bosättningen Shadowvale, djupt inne i den avskilda Whispering Forest. Innan riket föll var byn ökänd för att destillera Whispering Elixir från märkliga lokala örter, en kraftfull brygd som förblev eftertraktad på svarta marknaden även efter att den förbjudits i Lordaeron.",h="Carolai Anise i Brill söker fynd från den övergivna bosättningen Shadowvale, djupt inne i den avskilda...",kw={"apotekare","brill","carolai anise","gift","shadowvale","tirisfal","whispering elixir","whispering forest"},ang={["class:Rogue"]="Whispering Elixir var länge eftertraktat av olagliga giftblandare och skurkar som höll sig undan Lordaerons forna domares uppmärksamhet.",["profession:Herbalism"]="Elixiret får sin styrka från säregna örter som bara frodas under den avskilda Whispering Forests kusliga trädkrona.",["race:Undead"]="För Forsaken innebär återvinningen av Lordaerons bortglömda destillat både lönsam handel och experiment med apotekarkonst i det nya Undercity."},sec={{t="En förbjuden brygd",b="Långt före det tredje kriget och Scourges ankomst bryggde Shadowvales tillbakadragna invånare en särpräglad brygd som kallades Whispering Elixir. Den destillerades från sällsynta örter som bara fanns i Tirisfal Glades och blev ökänd i norra Lordaeron. Trots att den officiellt var förbjuden i Capital City gjorde dess ovanliga egenskaper den eftertraktad bland mystiker, giftblandare och apotekare som var beredda att trotsa kungliga dekret."},{t="Ruiner i Whispering Forest",b="Shadowvale ligger dolt djupt inne i Whispering Forest i västra Tirisfal. Byns invånare var historiskt sett slutna och misstrogna och välkomnade sällan främlingar. Efter Scourges invasion föll bosättningen i ruiner, men bortglömda förråd av den åldrade gröna elixiren finns kvar bland spillrorna. Carolai Anise håller till i Brill och drar nytta av den ihållande efterfrågan i undre världen genom att betala äventyrare som vågar sig in i skogens oroväckande tystnad."},{t="Den viskande förbannelsen",b="Carolai föredrar att avfärda rykten som ren vidskepelse, men Whispering Forest har ett mörkt rykte. Enligt lokal folktro är själva jorden och rötterna i skogen besmittade av en uråldrig förbannelse, som tränger direkt in i växterna som Shadowvales bryggare skördar. Vad det än är för kvardröjande ondska som hemsöker den övergivna byn har det knappast dämpat avlägsna köpares begär efter dess buteljerade rester."}},faq={{q="Vad är Shadowvale?",a="Shadowvale var en avskild by gömd i Whispering Forest i västra Tirisfal Glades. Invånarna var hemlighetsfulla enstöringar, främst kända för att destillera sällsynta brygder från den lokala vildmarken innan Scourge översvämmade området.",al={"var ligger shadowvale","vilka bodde i shadowvale","byn shadowvale"}},{q="Vad är Whispering Elixir?",a="Det är en kraftfull grön brygd gjord på unika örter från Tirisfal. Drycken var mycket eftertraktad av mystiker, giftblandare och apotekare och förbjöds i Capital City innan Lordaeron föll.",al={"vad gör elixiret","shadowvales gröna elixir i historien","whispering elixir"}},{q="Vem är Carolai Anise?",a="Carolai Anise är en företagsam Forsaken som bor i Brill. Hon förmedlar värdefulla och förbjudna kuriositeter och skaffar olagliga ingredienser som Shadowvales elixir för att sälja till intresserade köpare runtom i riket.",al={"carolai anise","vem ger uppdraget that shadowvale green elixir","uppdragsgivare i brill"}},{q="Varför förbjöds elixiret i Capital City?",a="Ingen anledning anges. Carolai säger bara att elixiret förbjöds i staden och att apotekare, mystiker och giftblandare ändå sökte efter det. En del tror att Whispering Forest är förbannad och att elixiret, destillerat från dess rötter, bär på samma förbannelse. Carolai avfärdar dock detta som vidskepelse och kopplar det aldrig till förbudet.",al={"varför var whispering elixir olagligt","är elixiret giftigt"}},{q="Varför anses Whispering Forest vara farlig?",a="Den avskilda skogen väster om Deathknell anses allmänt vara kuslig och förbannad. De som vågar sig dit berättar om en djup ondska och märkliga fenomen i skogen, som enligt rykten har besmittat örterna som växer ur dess jord.",al={"är whispering forest förbannad","whispering forests historia"}},{q="Vilka är köparna som vill ha elixiret?",a="Enligt Carolai Anise är flera köpare ivriga att få tag på överlevande flaskor från tiden före kriget, men hon säger inte vilka de är.",al={"vem köper elixiret","carolai anises köpare"}}},fx={["4d019fa8"]={q="Varför vill Carolai Anise att Whispering Elixir samlas in?",a="Carolai Anise skaffar sällsynta varor i Brill, och efterfrågan på den olagliga brygden har aldrig riktigt försvunnit. Många ivriga köpare ber henne om leveranser, så de flaskor som fortfarande är hela bland ruinerna kan ge en rejäl vinst.",al={"varför vill carolai ha elixiret","carolai anises motiv","varför samla whispering elixir"}}},fp="28,195,13.300.0,30.405.0,20.331.1,19.190.0,26.192.0,21.142.0,46.280.0,50.204.0,39.105.0"}
P.entries["quest:95315"] = {n="The Riverglades Report",s="Captain Nials skickar dig söderut med ett brev till Demar Brant vid Farholde Keep. En spejare rapporterar att en fiendestyrka samlas bortom Wetlands, nära en bosättning som kallas Farholde.",h="Captain Nials skickar dig söderut med ett brev till Demar Brant vid Farholde Keep.",kw={"captain nials","brev","demar brant","farholde","farholde keep","rivergladesrapport","spejare","wetlands"},sec={{t="En spejares ord",b="Captain Nials har hört att en stor fiendestyrka samlas långt söder om Wetlands. Där kan det finnas en bosättning som kallas Farholde, men namnet är bara bekant för honom. Han ger dig ett brev till Demar Brant, som leder förläggningen vid Farholde Keep på Riverglades sydöstra kust."}},faq={{q="Vad rapporterade spejaren?",a="Spejaren rapporterade att en stor fiendestyrka samlas långt söderut, bortom Wetlands.",al={"spejarrapport","vad händer i söder"}},{q="Vem skickar Captain Nials mig till?",a="Du ska överlämna Captain Nials brev till Demar Brant vid Farholde Keep.",al={"vem får brevet","demar brant"}},{q="Var ligger Farholde Keep?",a="Farholde Keep ligger längs Riverglades sydöstra kust.",al={"var ligger farholde","förläggningens plats"}},{q="Vad är Farholde?",a="Captain Nials har hört talas om en bosättning som kallas Farholde nära styrkan som samlas.",al={"bosättningen farholde","vad är farholde"}}},fp="22,180,16.302.0,26.80.0,35.83.0,23.67.0,17.81.0"}
P.entries["quest:95328"] = {n="Whispering Horror Residue",s="Whispering Horror Residue är resterna av ett märkligt odjur som slingrar sig och hämtats från under Whispering Forest. Oförvägna äventyrare samlar in de av tomrummet berörda kvarlevorna och för dem till Father Lankester i Undercitys War Quarter för skuggforskning.",h="Whispering Horror Residue är resterna av ett märkligt odjur som slingrar sig och hämtats från under...",kw={"father lankester","skugga","tirisfal","undercity","tomrum","war quarter","whispering forest","whispering horror residue"},ang={["class:Priest"]="Förfallna skuggpräster som Father Lankester har ett starkt vetenskapligt och teologiskt intresse för exemplar från tomrummet. De ser märkliga kvarlevor från andra plan som studieobjekt snarare än rena avskyvärdheter.",["faction:Horde"]="Äventyrare i Hordens tjänst hämtar oroväckande exemplar från Tirisfal Glades dolda vildmarker för att understödja forskningen under huvudstadens ruiner.",["race:Undead"]="De Förfallna i Undercity studerar aktivt förbjuden magi och onaturlig fördärvning i hela Lordaeron. De söker utnyttja mörka fenomen för att stärka sitt osäkra grepp om kungariket."},sec={{t="En olustig skörd",b="Whispering Horror Residue består av bisarra, slingrande kvarlevor som skrapats upp från ett besegrat odjur under Whispering Forest. I stället för att överge denna onaturliga märklighet samlar driftiga äventyrare in det ryckande materialet i hopp om att forskare i Undercity ska kunna använda det till något gott."},{t="Studier i skuggan",b="Odjurets kvarlevor får en ivrig mottagare i Father Lankester, som finns i Undercitys War Quarter. Lankester påpekar att Whispering Forest länge har berörts av tomrummet och välkomnar chansen att undersöka fysiska rester av denna mörka fördärvning medan han utforskar skuggans mysterier."}},faq={{q="Vad är Whispering Horror Residue?",a="Whispering Horror Residue består av slingrande kroppsliga kvarlevor från ett märkligt odjur som besegrades under Whispering Forest. Trots sin olustiga natur är det värdefullt för forskare inom skuggmagi och deras arkana och ockulta studier.",al={"vad är resterna","vad är whispering horror residue","föremål med rester"}},{q="Vem vill ha Whispering Horror Residue?",a="Resterna lämnas till Father Lankester, en Förfallen som finns i Undercitys War Quarter. Han välkomnar möjligheten att utforska skuggans mysterier och fenomen berörda av tomrummet.",al={"vem tar emot resterna","vem är father lankester","var lämnar man in resterna"}},{q="Varifrån kommer detta exemplar?",a="Exemplaret kommer från under Whispering Forest, en olycksbådande skog väster om Deathknell i Tirisfal Glades. Som Father Lankester påpekar är det känt att det motbjudande området har berörts av tomrummet.",al={"var kommer odjuret ifrån","whispering forests historia","under whispering forest"}},{q="Varför vill Father Lankester ha resterna?",a="Father Lankester vill studera skuggans och tomrummets mysterier. För Förfallna som utforskar förbjudna konster erbjuder fysiska rester från tomrumsbesmittade varelser sällsynta insikter och forskningsmaterial.",al={"varför vill lankester ha detta","skuggforskning i undercity","varför studera resterna"}},{q="Var hittar man Father Lankester?",a="Father Lankester håller till i Undercitys War Quarter. War Quarter är ett livligt centrum för Förfallna krigare, lärda och militära strateger under ruinerna av Lordaerons huvudstad.",al={"var ligger war quarter","var finns lankester","lankesters plats i undercity"}},{q="Har Whispering Forest berörts av tomrummet?",a="Whispering Forest har länge haft ett ondskefullt rykte bland invånarna i Tirisfal. Father Lankester påpekar att det inte är någon hemlighet att den motbjudande skogen och utrymmena under den har berörts av tomrummet.",al={"är whispering forest fördömd","tomrumsfördärv i whispering forest","vad berör whispering forest"}}},fp="25,138,21.162.0,17.197.0,38.149.0,40.151.0,34.147.0,43.154.0,36.168.0,45.147.0"}
P.entries["quest:95349"] = {n="The Earthen Ring",s="Den här färden markerar Windshapers ankomst från Zephras till Azeroth som en förtrupp, efter förseningar orsakade av kultister i Valanaar. Resenärerna går ombord på ett skycutter-skepp utanför lodgen och går i land i Mulgore för att möta Alaana Stormwalker och börja vänja sig vid en vidsträckt och farlig ny värld.",h="Den här färden markerar Windshapers ankomst från Zephras till Azeroth som en förtrupp, efter förseningar...",kw={"alaana stormwalker","banu-alah","kult","mulgore","skycutter","the earthen ring","valanaar","windshapers","zephras"},ang={["class:Shaman"]="Windshapers och shamaner hyser en djup vördnad för elementen och förlitar sig på vindarnas välvilja för att vägleda dem under färden genom luften. Deras ankomst under The Earthen Rings fana knyter dem direkt till de elementära traditioner som slår rot i Mulgore.",["race:Skyborne"]="För Skyborne-äventyrare som lämnar Valanaar markerar färden deras historiska ankomst till Azeroth som en förtrupp. De lämnar kultproblemen i hemlandet bakom sig och tar sina första steg på Mulgore slätter.",["race:Tauren"]="Som Mulgore ursprungliga vårdare bevittnar Tauren ankomsten av nya resenärer från Zephras till sina förfäders slätter. Genom att välkomna dessa himmelsfarare knyter de tidigt band till allierade som etablerar ett fäste i deras länder."},sec={{t="Avfärd från Valanaar",b="Resenärer på väg till Azeroth måste ändra sina planer på grund av de senaste störningarna som kultens verksamhet orsakat i Valanaar. Medan de högsta ledarna stannar kvar vid lodgen för att slutföra brådskande ärenden och hejda kultisthotet skickas en liten förtrupp av Windshapers i förväg. Pionjärerna beger sig till hamnen strax utanför lodgen och går ombord på ett skycutter-fartyg som ska färdas över himlen. Befälhavarna lovar att snart ansluta, men den första expeditionen vilar helt på förtruppens axlar. Den skickas i förväg för att etablera en närvaro innan resten kan följa efter."},{t="Ankomst till Mulgore",b="När äventyrarna från Zephras landar på Mulgore slätter välkomnas de av Alaana Stormwalker. Det tar tid och kräver omsorgsfullt arbete att etablera ett fäste i Azeroth, så nykomlingarna uppmuntras att utforska trakten och vänja sig vid sin nya omgivning. Vindarna är gynnsamma för expeditionen, men Azeroth är fortfarande ett främmande och farligt rike. Att lära känna den lokala terrängen, djurlivet och grannfolken är ett viktigt första steg innan de återstående resenärerna från Valanaar anländer för att hjälpa till."}},faq={{q="Varför reser Windshapers till Azeroth?",a="En förtrupp av Windshapers skickas i förväg för att etablera en närvaro i Azeroth medan deras ledare stannar kvar i Valanaar. Nyliga problem med en lokal kult störde de ursprungliga resplanerna och försenade resten av gruppen. Därför färdas förtruppen ensam i förväg för att gå i land och säkra ett fäste tills förstärkningarna kan följa efter.",al={"varför resa till azeroth","windshapers uppdrag","varför är windshapers i mulgore"}},{q="Vem är Alaana Stormwalker?",a="Alaana Stormwalker är kontaktpersonen som väntar på att ta emot Windshapers när de landar i Mulgore. Hon välkomnar resenärer från Zephras och konstaterar att det kommer att ta tid att etablera en trygg närvaro i de nya länderna. Medan förberedelserna inleds råder hon de nyanlända äventyrarna att utforska trakten och förbereda sig på farorna i Azeroth.",al={"vem är alaana","alaana stormwalkers roll","var finns alaana stormwalker"}},{q="Varför försenades huvudavfärden?",a="Huvudresan från Valanaar sköts upp på grund av oroande händelser med en lokal kult. Problemen med kultisterna tvingade expeditionens ledare att stanna kvar vid lodgen för att slutföra sina ärenden. I stället för att avbryta uppdraget helt skickade de en liten förtrupp av Windshapers med ett skycutter-fartyg för att bana väg till Azeroth.",al={"varför blev det försenat","vilken kult försenade resan","varför stanna i valanaar"}},{q="Hur reser man från Valanaar till Mulgore?",a="Resenärerna gör resan genom att gå ombord på ett skycutter-skepp som ligger förtöjt strax utanför lodgen i Valanaar. Fartyget för förtruppen genom luften till Mulgore slätter och är den främsta transportförbindelsen mellan Zephras och Azeroths länder under den första expeditionen.",al={"hur tar man sig till mulgore","var finns skeppet","hur reser man till azeroth"}},{q="Vad är Zephras?",a="Zephras är hemtrakten eller ursprunget för äventyrarna som anländer med skycutter-fartyget. När resenärerna når Mulgore beskriver Alaana Stormwalker dem som nykomlingar från Zephras och säger att gynnsamma vindar har lett dem genom luften till Azeroths främmande och farliga områden.",al={"var ligger zephras","vad är zephras","zephras historia"}},{q="Vad bör äventyrare göra när de anländer till Mulgore?",a="Nyanlända äventyrare uppmuntras att rekognosera och utforska Mulgore med omnejd. Eftersom det tar tid att etablera ett fast fäste är det viktigt att lära känna den närliggande terrängen, varelserna och de lokala hoten inför färder genom denna spännande men farliga nya värld.",al={"vad ska man göra i mulgore","nästa steg efter ankomsten","vad ska man göra härnäst"}}},fp="16,272,23.440.0,18.424.0,45.264.0,26.240.0,35.192.0,50.190.0,16.215.0,52.209.0"}
P.entries["quest:95350"] = {n="Welcome to Azeroth",s="'Welcome to Azeroth' är ett introduktionsuppdrag som skickar en resenär från Thunder Bluff till Orgrimmar på Windshapers vägnar. Med Earthen Rings andliga band som vägledning möter sändebudet krigshövding Thrall för att knyta överlevnadsband och skapa en allians med Horden.",h="'Welcome to Azeroth' är ett introduktionsuppdrag som skickar en resenär från Thunder Bluff till Orgrimmar på...",kw={"earthen ring","horden","orgrimmar","thrall","thunder bluff","visdomens dal","welcome to azeroth","windshapers"},ang={["class:Shaman"]="Med vägledning från Earthen Ring och vindarnas välsignelse knyter resan samman andliga fränder med schamanledarskapets hjärta i Visdomens dal.",["faction:Horde"]="Det diplomatiska uppdraget formaliserar banden med Horden och presenterar nykomlingarna direkt för krigshövding Thrall som viktiga allierade för överlevnad i Kalimdor.",["race:Skyborne"]="Från de höga höjderna ner till ytvärlden söker Skyborne Windshapers kontakt med Thunder Bluff och Orgrimmar för att säkra sin plats bland nya allierade."},sec={{t="Allierade i en större värld",b="När nykomlingar ger sig ut i Kalimdors vidsträckta vildmarker upptäcker de snabbt att överlevnad bygger på gemenskap. Windshapers blickar bortom sitt isolerade ursprung mot folken där nere och inser att isolering inte skyddar mot Azeroths hot. Genom att sträcka ut en hand till taurenstaden Thunder Bluff och blicka mot orkernas fästen i öster söker de pålitliga följeslagare att möta vildmarken tillsammans med."},{t="Ett möte med krigshövdingen",b="Resan för sändebuden till Thunder Bluffs höga torn innan de leds över The Barrens till Orgrimmar, Hordens mäktiga huvudstad. I den stillsamma Visdomens dal väntar krigshövding Thrall, koalitionens vägledande kraft. Mötet med Thrall markerar Windshapers officiella inträde i Kalimdors politiska och andliga gemenskap, förenade av ett gemensamt mål och respekt för elementen."}},faq={{q="Vad är syftet med uppdraget Welcome to Azeroth?",a="'Welcome to Azeroth' är ett diplomatiskt introduktionsuppdrag där ett sändebud på Windshapers vägnar skickas för att möta krigshövding Thrall i Orgrimmar. Det är en officiell presentation för den större Horden och Kalimdors ytvärld.",al={"vad är det här för uppdrag","uppdraget welcome to azeroth","syftet med welcome to azeroth"}},{q="Vilka är Windshapers?",a="Windshapers är en grupp som sträcker sig från höjderna mot allierade på marken och söker överlevnad genom gemenskap med Earthen Ring och Horden. De skickar resenärer för att tala direkt med Hordens ledare i Durotar.",al={"vilka är windshapers","vad är windshapers"}},{q="Varför skickas du för att tala med Thrall?",a="Som Hordens krigshövding och en vördad schamanledare övervakar Thrall koalitionens viktigaste allianser från Visdomens dal. Kontakten med honom formaliserar relationerna mellan Windshapers och Horden.",al={"varför besöka thrall","tala med thrall i orgrimmar","varför åka till orgrimmar"}},{q="Hur reser du från Thunder Bluff till Orgrimmar?",a="Resenärer flyger från flygmästaren vid Thunder Bluffs centrala rastplats och svävar österut över Kalimdors slätter till Orgrimmars kanjonfäste.",al={"hur tar man sig till orgrimmar","flygmästaren i thunder bluff","från thunder bluff till orgrimmar"}},{q="Vilken roll spelar Earthen Ring i det här uppdraget?",a="I det här mötet beskrivs Earthen Ring som en del av Hordens koalition av likasinnade folk. De hjälper till att knyta band mellan schamanfraktioner och Kalimdors nationer.",al={"earthen rings roll i horden","är earthen ring med i horden"}},{q="Var finns Thrall i Orgrimmar?",a="Krigshövding Thrall bor i Visdomens dal, en stillsam andlig fristad i Orgrimmars västra delar där schamaner och stammarnas rådgivare samlas.",al={"var finns thrall","thralls plats i visdomens dal"}}},fp="18,196,25.303.0,29.350.0,52.156.0,24.200.0,38.208.0,50.154.0,48.142.0,37.139.0"}
P.entries["quest:954"] = {n="Bashal'Aran",s="De demoniska satyrerna och de våldsamma grellerna som hemsöker den uråldriga Night Elf-staden Bashal'Aran närmar sig inte en helgedom, badande i ett övernaturligt blått sken. Thundris Windweaver, Auberdines äldste, skickar äventyrare för att undersöka källan till denna orörda fristad.",h="De demoniska satyrerna och de våldsamma grellerna som hemsöker den uråldriga Night Elf-staden Bashal'Aran...",kw={"asterion","bashal'aran","blått sken","darkshore","grell","kaldorei-ruiner","satyr","thundris windweaver"},ang={["faction:Alliance"]="Auberdines spejare förlitar sig på Alliance-vandrare som tränger in i Darkshores omstridda ruiner och undanröjer demoniska hot innan de når kusten.",["race:NightElf"]="Bashal'Aran är en dyster påminnelse om det som gick förlorat under Sundering, där dina uråldriga fränders kvardröjande andar fortfarande håller ensamma vakor mot den annalkande demoniska korruptionen."},sec={{t="En fyr bland ruinerna",b="Bashal'Aran var en gång en storslagen bosättning i det uråldriga Kaldorei-imperiet, men dess krossade marmor och igenvuxna valv vimlar nu av demonisk smitta. Förvridna satyrer och korrumperade greller livnär sig girigt på ruinernas kvarvarande magiska energier, och deras ondska växer för varje dag som går. Trots deras rovgiriga herravälde upptäckte Thundris Windweaver i Auberdine något märkligt: på en västlig klippa i ruinerna brinner ett eteriskt blått sken över en helgedom som ingen demon närmar sig."},{t="Den sårade anden",b="Om du trotsar demonernas patruller och når den upphöjda helgedomen upptäcker du att det blå ljuset inte är något naturligt fenomen. Det kommer från Asterion, en uråldrig ande vars vaka har fortsatt genom århundraden av ensamhet. Omgiven av ylande bestar och vidriga vidunder ser den utmattade anden till och med en resande främling som en välkommen paus efter årtionden av isolering."}},faq={{q="Var finns det blå skenet?",a="Det blå skenet lyser på toppen av en liten upphöjd klippa vid ruinernas västra kant i Bashal'Aran, strax öster om Auberdine i Darkshore. Platsen ligger något högre än de omkringliggande, sönderfallande murarna.",al={"hitta blått sken","var finns asterion","bashal'aran helgedomens plats"}},{q="Varför undviker satyrerna helgedomen?",a="Ingen vet ännu. Ett märkligt blått sken genomsyrar helgedomen, och de demoniska satyrerna och grellerna som annars hemsöker ruinerna närmar sig den inte. Thundris Windweaver skickar dig för att hitta skenets källa.",al={"varför fruktar demoner","varför håller sig satyrerna borta"}},{q="Vem skickar dig på det här uppdraget?",a="Thundris Windweaver, en Night Elf-druid och Auberdines äldste, ger dig uppdraget efter att ha lagt märke till de onaturliga demonrörelserna i de östra ruinerna.",al={"vem ger uppdraget","uppdragsgivare","thundris windweavers plats"}},{q="Vad är Bashal'Aran?",a="Bashal'Aran är en uråldrig kaldorei-ruin inbäddad i Darkshores skogar. Den plundrades under det uråldriga Sundering och har sedan dess hemsökts av magiska parasiter, greller och satyrer som söker sig till dess slumrande ley-krafter.",al={"vad hände med bashal'aran","bashal'arans historia"}}},fx={["2cba9e48"]={q="Varför vill Thundris Windweaver att jag undersöker Bashal'Aran?",a="Thundris Windweaver betraktar Bashal'Arans uråldriga ruiner med växande oro. Fördärvade sprites och satyrs svärmar över området och utnyttjar kvarvarande arkana energier för att förstärka sin demoniska kraft. Men mitt i denna invasion står en enda helgedom, omgiven av en märklig blå aura, helt orörd av demonerna. Thundris måste förstå vilken kraft som håller dem borta och om den kan vara nyckeln till att hejda fördärvet som tränger in i Darkshore.",al={"varför undersöka bashal'aran","thundris motiv","varför skicka mig till bashal'aran"}}},fp="11,161,21.382.0,17.245.1,31.192.0,35.147.0,28.136.0,20.171.0"}
P.entries["quest:95417"] = {n="The Purple Ones",s="Clubtoe ber dig leta efter oger som saknas i grottorna under Sunnyglade. Några som återvänder har förändrats, och han vill förstå varför.",h="Clubtoe ber dig leta efter oger som saknas i grottorna under Sunnyglade.",kw={"grottor","clubtoe","mörka runor","försvunna oger","oger","lila","sunnyglade","de lila","twilight hammer"},sec={{t="Clubtoes oro",b="Clubtoe har sett vänner gå in i grottorna under Sunnyglade utan att komma tillbaka. Några återvänder lila och beter sig inte längre som hans vänner. Han ber dig söka igenom grottorna efter de försvunna ogerna, men fruktar att även du kan återvända förändrad."},{t="I grottorna",b="Under Sunnyglade hittar du en död ogre bland mörka runor. Krafterna i Twilight Hammers ritual har överväldigat honom."}},faq={{q="Vem är Clubtoe?",a="Clubtoe är en ogre vars vänner har försvunnit i grottorna under Sunnyglade.",al={"clubtoe","vem är clubtoe"}},{q="Varför ber Clubtoe mig söka igenom grottorna?",a="Några av Clubtoes vänner kommer inte tillbaka från grottorna, och några som återvänder är lila och beter sig annorlunda.",al={"försvunna oger","hitta clubtoes vänner","grottoger"}},{q="Var finns de försvunna ogerna?",a="Clubtoe ber dig leta efter de försvunna ogerna i grottorna under Sunnyglade.",al={"vart ogerna tar vägen","grottan vid sunnyglade","oger som saknas"}},{q="Vad är märkligt med ogerna som återvänder?",a="Några återvänder lila och beter sig inte längre som Clubtoes vänner.",al={"lila oger","varför lila","oger som beter sig märkligt"}}},fp="15,138,17.245.0,12.124.1,15.83.0,44.110.0,28.79.0,43.60.0"}
P.entries["quest:95418"] = {n="Spread the Word",s="Tran'gul ber dig ta Chogg'Zacs huvud till Rog'mar efter att en ogre lämnat Twilight's Hammer. Nyheten om avhoppet kan få fler av kultens ogres att bryta sig loss.",h="Tran'gul ber dig ta Chogg'Zacs huvud till Rog'mar efter att en ogre lämnat Twilight's Hammer.",kw={"chogg'zac","clubtoe","clugfist","ogreavhopp","rog'mar","sprid nyheten","tran'gul","twilight's hammer"},sec={{t="Ett meddelande till Tran'gul",b="Tran'gul i Rog'mar behöver få Chogg'Zacs huvud tillbaka till sina vänner. Clubtoe säger att han är färdig med Twilight's Hammer och tänker ansluta sig till Clugfist, den största ogre han känner, tillsammans med många andra. Clubtoe tänker stanna där han är tills faran är över. Nu måste Tran'gul få veta vad Clubtoe har valt."},{t="Nyheter från grottan",b="Tran'gul får höra att grottan bjöd på ännu en överraskning. Du har övertalat en av Twilight's Hammers ogres att hoppa av, och han berättade om andra av sitt slag. Tran'gul säger att de måste agera genast på den här nyheten."}},faq={{q="Vem är Clubtoe?",a="Clubtoe är en ogre som säger att han är färdig med Twilight's Hammer och tänker ansluta sig till de fria ogres.",al={"clubtoe","ogren clubtoe","vem är clubtoe"}},{q="Vem är Clugfist?",a="Clugfist är den största ogre Clubtoe känner, och Clubtoe säger att han lämnade Twilight's Hammer tillsammans med många vänner.",al={"clugfist","ogren clugfist","största ogren"}},{q="Vad ber Clubtoe mig att ta med?",a="Clubtoe ber dig ta Chogg'Zacs huvud tillbaka till sina vänner.",al={"choggs huvud","chogg'zacs huvud","vad ska tas med"}},{q="Vart ska jag ta Chogg'Zacs huvud?",a="Du ska lämna Chogg'Zacs huvud till Tran'gul i Rog'mar.",al={"vart ta huvudet","tran'gul","rog'mar"}},{q="Varför är Tran'gul orolig?",a="Tran'gul får veta att en ogre från Twilight's Hammer har hoppat av och nämnt andra av sitt slag.",al={"tran'guls reaktion","skymningsgrottan","varför agera nu"}}},fp="15,172,22.303.0,18.202.1,15.99.0,16.109.0,34.62.0,33.59.0,26.94.0"}
P.entries["quest:95427"] = {n="Twilight No More!",s="Clubtoe ber dig konfrontera Chogg'Zac i grottan i Sunnyglade. Han skyller på dem för sina vänners död och deras löfte att göra ogres starka.",h="Clubtoe ber dig konfrontera Chogg'Zac i grottan i Sunnyglade.",kw={"grotta","chogg'zac","clubtoe","vänner","ogres","sunnyglade","skymning"},sec={{t="Clubtoes vädjan",b="Clubtoe säger att hans vänner är döda och skyller på Chogg'Zac. De lovade att göra ogres starka, men han säger att de ljög. Därför ber han dig hjälpa honom att vända sig mot dem i grottan i Sunnyglade. Han vill ha deras huvuden och tänker inte krossa fler stenar åt dem."},{t="Ett nytt namn",b="När Chogg'Zac är döda ropar Clubtoe triumferande. Han säger att han har slutat krossa stenar åt tinies och slutat förlora vänner. Han kallar sig inte längre Twilight."}},faq={{q="Vem är Clubtoe?",a="Clubtoe är en ogre som säger att Chogg'Zac lovade att göra ogres starka. Han skyller på dem för sina vänners död.",al={"clubtoe","vem är clubtoe","clubtoes bakgrund"}},{q="Varför vill Clubtoe att Chogg'Zac ska dö?",a="Clubtoe säger att Chogg'Zac ljög om att göra ogres starka och skyller på dem för sina vänners död.",al={"varför döda chogg'zac","skäl till chogg zac","chogg'zac uppdrag"}},{q="Var finns Chogg'Zac?",a="Chogg'Zac finns i grottan i Sunnyglade.",al={"chogg'zac plats","var finns chogg zac","grottan i sunnyglade"}},{q="Vad vill Clubtoe att du ska göra?",a="Clubtoe ber dig döda Chogg'Zac och samla in deras huvuden.",al={"vad vill clubtoe ha","vad ska man hämta åt clubtoe","clubtoes huvuden"}}},fp="17,141,14.247.0,10.155.1,15.108.0,37.94.0,20.37.0,32.59.0"}
P.entries["quest:95428"] = {n="Clugfist's Decree",s="Clugfist låter dig stanna i Bolder'ok tills vidare, efter att Skyborne besegrat Twilight's Hammer. Han ber dig meddela de andra att klanen snart ska strida igen.",h="Clugfist låter dig stanna i Bolder'ok tills vidare, efter att Skyborne besegrat Twilight's Hammer.",kw={"bolder'ok","clugfist","dekret","horde","krom'rosh","rog'mar","skyborne","twilight's hammer"},ang={["faction:Horde"]="Som medlem av Horde kan Bolder'ok bli mäktiga allierade om ditt folk fortsätter att vinna deras förtroende."},sec={{t="Besked till Rog'mar",b="Krom'rosh i Rog'mar väntar på att höra från dig. Clugfist låter dig stanna i Bolder'ok tills vidare och ber dig föra beskedet vidare till de andra Skyborne. Klanen väntar sig snart mer blodsutgjutelse."},{t="Förtroende och allianser",b="Krom'rosh ser Bolder'ok-klanen som en möjlig allierad till Horde. Deras senaste kamp för frihet från Twilight's Hammer påminner om Hordes egen blodiga historia. Din rapport kan hjälpa Horde att fortsätta vinna deras förtroende."}},faq={{q="Vad vill Clugfist att jag ska göra?",a="Clugfist ber dig meddela de andra Skyborne att Bolder'ok-klanen väntar sig att strida igen snart.",al={"clugfists dekret","vad ska jag rapportera","clugfists order"}},{q="Var ska jag rapportera?",a="Clugfist hänvisar dig till Krom'rosh i Rog'mar för att rapportera.",al={"rapportera till krom'rosh","var finns krom'rosh","rapport till rog'mar"}},{q="Kan jag stanna i Bolder'ok?",a="Clugfist låter dig stanna i Bolder'ok tills vidare.",al={"stanna i bolder'ok","clugfist låter mig stanna","tillstånd från bolder'ok"}},{q="Vilka är Bolder'ok?",a="Bolder'ok är en klan som nyligen kämpade för frihet från Twilight's Hammer.",al={"bolder'ok-klanen","vem är clugfist","clugfists folk"}},{q="Varför bryr sig Horde om Bolder'ok?",a="Krom'rosh tror att Bolder'ok kan bli mäktiga allierade om Horde fortsätter att vinna deras förtroende.",al={"horde och bolder'ok","bolder'oks allierade","varför bryr sig krom'rosh"}}},fp="17,168,16.182.0,19.225.1,33.97.0,18.55.0,24.52.0,22.85.0,44.105.0"}
P.entries["quest:95494"] = {n="Bruised Pride and Lion Hides",s="Bruised Pride and Lion Hides är ett uppdrag där du hjälper en skadad jägare eller hantverkare som behöver råa lejonhudar för att uppfylla ett handelsavtal med en lokal garvare. På grund av sina skador kan personen inte jaga säkert och förlitar sig på resande äventyrare som kan leverera materialet och värna om personens oklanderliga yrkesrykte.",h="Bruised Pride and Lion Hides är ett uppdrag där du hjälper en skadad jägare eller hantverkare som behöver råa...",kw={"bruised pride and lion hides","jakt","lädervaror","lejonhudar","garvare","handel"},sec={{t="En jägares dilemma",b="I Bruised Pride and Lion Hides hjälper du en skadad jägare som inte kan spåra vilda djur efter en nylig skada. För att inte svika ett pågående handelsavtal med en lokal hantverkare anlitar jägaren en äventyrare som kan spåra upp vilda lejon och samla in deras hudar."},{t="Hålla överenskommelsen",b="De insamlade råhudarna byts mot färdig läderutrustning hos en lokal garvare, något uppdragsgivaren behöver för sin försörjning. Trots sina skador och den sårade stoltheten över att behöva hjälp utifrån ser uppdragsgivaren till att hålla avtalet och bevara sitt yrkesrykte."}},faq={{q="Vad handlar det här uppdraget om?",a="Lejonhudarna samlas in åt en skadad jägare eller handelsman som levererar råmaterial till en lokal garvare. I utbyte mot hudarna får uppdragsgivaren färdiga lädervaror som är nödvändiga för försörjningen.",al={"vad är bruised pride and lion hides","uppdragets mål","vad ska lejonhudarna användas till"}},{q="Varför behöver uppdragsgivaren hjälp med att samla in hudar?",a="Uppdragsgivaren har skadat sig och kan inte jaga lejonen själv. I stället för att bryta ett långvarigt affärsavtal med en lokal garvare förlitar sig uppdragsgivaren på äventyrare som kan sköta leveransen.",al={"varför behövs hjälp","varför kan de inte jaga"}},{q="Vem får lejonhudarna?",a="Råhudarna byts med en lokal garvare. Garvaren bereder dem till färdiga lädervaror som uppdragsgivaren behöver för sitt vanliga arbete och sina affärer.",al={"vem får lejonhudarna","vart tar hudarna vägen"}},{q="Vad betyder namnet ”Bruised Pride and Lion Hides”?",a="Titeln anspelar på två saker: en bokstavlig flock lejon som måste jagas och jägarens stolthet, som fått sig en törn eftersom jägaren aldrig tidigare har misslyckats med att leverera enligt ett avtal, trots sina nuvarande fysiska begränsningar.",al={"betydelsen av bruised pride","varför heter det bruised pride"}},{q="Var överenskommelsen med garvaren i fara?",a="Ja. Skadan hindrar uppdragsgivaren från att jaga, vilket riskerar nästa leverans. Genom att samla in lejonhudarna kan uppdragsgivaren hålla sin del av avtalet och undvika att leverera för lite.",al={"håller överenskommelsen med garvaren","bröts handelsavtalet"}},{q="Hur skadades uppdragsgivaren?",a="Uppdragsgivaren skadade sig så att hen inte kan jaga lejon i vildmarken, men den exakta orsaken till skadan nämns inte. Genom att leverera hudarna kan uppdragsgivaren bevara sitt rykte.",al={"uppdragsgivarens skada","vad hände med jägaren"}}},fp="28,174,18.195.0,24.236.0,25.157.0,51.130.0,28.128.0,55.170.0,44.136.0,32.171.0"}
P.entries["quest:95495"] = {n="The Hermit Tanner",s="The Hermit Tanner är ett lokalt leveransuppdrag i The Barrens där äventyrare bär ett knippe råhudar till en tillbakadragen hantverkare som bor på en ås med utsikt över The Dry Hills. Uppdraget visar hur avlägsna samarbeten håller savannens handel igång och introducerar en isolerad, slående eremit som upprätthåller regelbunden handel trots sin avskildhet.",h="The Hermit Tanner är ett lokalt leveransuppdrag i The Barrens där äventyrare bär ett knippe råhudar till en...",kw={"the barrens","bundle of hides","the dry hills","the hermit tanner","ås","garvare","vrang"},ang={["faction:Horde"]="Resenärer genom den centrala savannen hjälper ofta lokala handlare som Vrang att transportera viktiga handelsvaror genom The Barrens oländiga terräng."},sec={{t="En ås i The Barrens",b="The Barrens karga savann främjar handel mellan tåligt folk, även om inte alla hantverkare föredrar det livliga tempot vid vägskäl och boplatser. I skuggan av The Dry Hills byter en handlare vid namn Vrang regelbundet varor med en tillbakadragen garvare som har byggt ett stillsamt hem på åsen med utsikt över landskapet. Eftersom den branta vandringen uppför den klippiga sluttningen är för ansträngande för Vrang, förlitar han sig på förbipasserande äventyrare som kan bära knippen med råhudar upp till hans avskilda samarbetspartner."},{t="En ovanlig hantverkare",b="Innan Vrang skickar iväg resenärer ser han till att ge en tydlig varning om den ensamme hantverkaren. Eremiten har ett oroande och ovanligt utseende som kan skrämma ovetande besökare, men Vrang försäkrar att den tillbakadragne garvaren inte utgör någon fara för gäster. När eremiten tar emot råhudarna vid sitt hem på åsen välkomnar han budbäraren varmt, men beklagar att Vrang inte kunde ta sig upp, eftersom det finns något han hoppades få tala med handlaren om personligen."}},faq={{q="Vem skickar dig med leveransen?",a="En handlare vid namn Vrang ordnar uppdraget och ber en förbipasserande resenär leverera ett knippe råhudar till en affärspartner som bor på åsen ovanför.",al={"vem ger uppdraget the hermit tanner","var börjar uppdraget","vrang leverans"}},{q="Var bor eremitgarvaren?",a="Eremitgarvaren bor ensam i ett avskilt hem på den höga åsen med utsikt över The Dry Hills i The Barrens.",al={"eremitgarvarens plats","var finns eremitgarvaren","eremit på åsen"}},{q="Varför varnar Vrang dig för garvarens utseende?",a="Vrang varnar resenärer i förväg för att inte låta sig skrämmas av garvarens ovanliga eller obehagliga utseende. Han bedyrar att eremiten inte utgör något hot mot besökare, trots sitt utseende.",al={"eremitens utseende","varför ser eremiten skrämmande ut"}},{q="Varför kunde inte Vrang själv ta sig upp?",a="Vrang förklarar att han just nu inte lätt kan klara den branta klättringen uppför den oländiga sluttningen på egen hand, så han anlitar i stället ett bud.",al={"varför behövs leveransen","varför kan vrang inte ta sig upp"}},{q="Vilka varor levereras upp till åsen?",a="Leveransen består av ett knippe hudar avsedda för eremitens garveriverksamhet, ett hantverk som de båda regelbundet samarbetar kring.",al={"vad är ett knippe hudar","varor som levereras i uppdraget"}},{q="Vad vill eremitgarvaren tala med Vrang om?",a="När garvaren tar emot leveransen beklagar han att Vrang inte kunde komma upp personligen och nämner att han har något han behöver tala direkt med Vrang om.",al={"vad vill garvaren med vrang","garvarens affärer med vrang"}}},fp="17,169,22.210.0,27.293.0,31.100.0,34.108.0,54.122.0,42.107.0,44.89.0,55.101.0"}
P.entries["quest:955"] = {n="Bashal'Aran",s="Asterion, en sorgsen highborne-ande som hemsöker de gamla ruinerna i Bashal'Aran, söker ett sätt att häva bindningsmagin som håller hans vålnadsgestalt fången. Han tror att de busiga lokala grellarna har rört vid sigillet som håller honom kvar och ber därför resenärer samla in deras örhängen för att spåra dess kvarvarande magiska resonans.",h="Asterion, en sorgsen highborne-ande som hemsöker de gamla ruinerna i Bashal'Aran, söker ett sätt att häva...",kw={"asterion","bashal'aran","bindning","darkshore","spöke","grell","grell earring","sigill"},ang={["class:Mage"]="Asterions metod att använda förtrollade prydnader för att spåra kvarvarande magiska utstrålningar speglar uråldriga Highborne-metoder för magisk spådom.",["faction:Alliance"]="När de kaotiska grellarna kring Bashal'Aran drivs bort blir de förrädiska norra delarna av Darkshore tryggare för Alliansen.",["race:NightElf"]="För Kaldorei är mötet med Asterion en bister påminnelse om den uråldriga civilisation som föll under Sunderingen och lämnade plågade själar bundna i ruinerna i årtusenden."},sec={{t="En plåga genom århundraden",b="Bland Bashal'Arans krossade marmor dröjer Asterion, en uråldrig Night Elf-ande som uthärdat århundraden i fångenskap. Fångad mellan liv och verklig död har hans existens förfallit till en plågsam väntan under Darkshores trädkronor. Han är bunden direkt till den förstörda bosättningen genom magisk konst och saknar medel att själv bryta sina bojor; hans sinne har nötts ned av oräkneliga år av ensamhet och förtvivlan."},{t="Spår i vildmarken",b="Asterion misstänker att nyckeln till hans befrielse är ett uråldrigt sigill som gömts någonstans i ruinerna. Han kan inte själv söka igenom snåren och de rasade stenarna, men de vilda grellarna som härjar i Bashal'Aran letar ständigt efter föda och stjäl små prydnader. Asterion ber resenärer samla in örhängena som dessa varelser bär, så att han kan läsa av de magiska avtryck som finns kvar på smyckena och hitta sigillet som plågar hans själ."}},faq={{q="Vem är Asterion?",a="Asterion är ett uråldrigt Night Elf-spöke som är bundet till ruinerna i Bashal'Aran i Darkshore. Ett mystiskt sigill har hållit honom fången i århundraden, och han har sett tidsåldrar passera i plåga medan han längtat efter att befrias från sitt vålnadstillstånd.",al={"asterions historia","vem är spöket i bashal'aran","asterion uppdragsgivare"}},{q="Varför vill Asterion ha grellörhängen?",a="Grellar är ökända asätare som samlar på glänsande prydnader och smycken. Asterion tror att varelserna har rört vid det magiska sigill som håller honom fången, så deras örhängen kan ha tillräckligt med magiska rester för att hjälpa honom hitta det.",al={"varför grellörhängen","grellörhängenas syfte","örhängeuppdrag i darkshore"}},{q="Vad är Bashal'Aran?",a="Bashal'Aran är en uråldrig Night Elf-ruin vid Darkshores skogsklädda kust, från tiden före den stora Sunderingen. Den är översvämmad av vilda grellar, satyrer och vålnadsrester från dess sedan länge fallna invånare.",al={"vad är bashal'aran","bashal'arans historia","ruinerna i bashal'aran"}},{q="Vad händer när örhängena har samlats in?",a="Asterion undersöker örhängena och känner att grellarna inte bär på själva sigillet, men att de har snuddat vid det i vad han anser vara relativt nyligen. Spåret hjälper honom att ringa in dess plats i ruinerna.",al={"vad visar örhängena","hade grellarna sigillet","resultat av grellörhänget"}},{q="Varför är Asterion fången här?",a="Asterion bands till Bashal'Aran av ett uråldrigt magiskt sigill som skapades för århundraden sedan. Bindningen förankrar hans ande vid ruinernas fysiska plats och hindrar honom från att gå vidare till en fridfull vila.",al={"vem band asterion","hur är asterion bunden","asterions sigill"}},{q="Vad är grellar?",a="Grellar är små, illvilliga skogsvarelser som hör hemma i Kalimdors skogar. De är kända för sitt busiga lynne, sina vassa klor och sin kärlek till prydnadssaker. De härjar ofta i gamla ruiner och angriper resenärer på väg förbi.",al={"vad är en grell","grellarnas historia","grellar i darkshore"}}},fx={["99bf1a9e"]={q="Varför vill Asterion att det här blir gjort?",a="Asterion är fångad i en plågsam andeskepnad, bunden till Bashal'Arans ruiner av en uråldrig magisk sigill. Århundraden av fångenskap har långsamt brutit ner hans förstånd, och han längtar efter att befrias från plågan. Genom att undersöka örhängena som de lokala varelserna bär hoppas han magiskt kunna skåda sigillformens exakta plats, så att den till sist kan förstöras.",al={"asterions motiv","varför hjälpa asterion","varför vill asterion ha örhängen"}},a8a71265={q="Varför behöver Asterion din hjälp i stället för att agera själv?",a="Asterion är ett formlöst spöke som bundits direkt till ruinerna av mäktig trolldom. Han kan varken färdas långt från sin viloplats eller själv strida fysiskt mot grells och sprites. Därför är han helt beroende av förbipasserande dödliga som jagar varelserna och samlar in deras prydnader åt hans spådomar.",al={"varför behöver asterion mig","varför kan inte asterion hämta örhängena","varför kan inte asterion lämna platsen"}}},fp="11,257,23.299.0,18.346.0,16.183.0,38.133.0,20.187.0,43.223.1,29.145.0,16.164.0"}
P.entries["quest:95507"] = {n="Vrang's Game",s="Vrang skickar dig genom en dal i The Barrens för att kontrollera sina fällor. Småviltet de fångar kan hjälpa honom, men andra vilda djur gör området farligt.",h="Vrang skickar dig genom en dal i The Barrens för att kontrollera sina fällor.",kw={"barrens","småvilt","fångat vilt","fällor","dal","vrang","vilda djur"},sec={{t="Vrangs fällor",b="Vrang har fällor utspridda över dalen, och han vill att du tar med dig allt småvilt de har fångat tillbaka. Håll också uppsikt över de vilda djuren, för de kan göra området farligt."}},faq={{q="Vad vill Vrang ha?",a="Vrang vill att du kontrollerar hans fällor och tar med dig allt småvilt de har fångat tillbaka.",al={"vrang fällor","vrang vilt","vad behöver vrang"}},{q="Var finns Vrangs fällor?",a="Vrangs fällor är utspridda över en dal i The Barrens.",al={"var finns fällorna","fällornas plats","barrens fällor"}},{q="Vad är farligt runt fällorna?",a="Andra vilda djur runt fällorna kan vara farliga om du inte är uppmärksam.",al={"fara i närheten","andra djur","fara från vilda djur"}}},fp="12,154,13.185.0,21.82.0,24.59.0,35.81.0"}
P.entries["quest:95508"] = {n="Unwelcome Guests",s="Du hjälpte någon att överleva ett möte med ovälkomna gäster, och personen är tacksam. Vad som förde er samman är fortfarande oklart.",h="Du hjälpte någon att överleva ett möte med ovälkomna gäster, och personen är tacksam.",kw={"skuld","hjälp","överleva","tack","ovälkomna gäster"},faq={{q="Vad hände här?",a="Du hjälpte personen som talar att överleva ett möte, men personen ger inga detaljer om det.",al={"vad hände","ovälkomna gäster","problem med gäster"}},{q="Vem tackar mig?",a="Personen som tackar dig namnges inte.",al={"vem är detta","vem tackade mig","uppdragsgivare"}},{q="Varför står personen i skuld till mig?",a="Personen som talar säger att du hjälpte till att rädda personens liv, men förklarar inte vad som hände.",al={"varför tacka mig","varför står personen i skuld till mig","hjälpte personen"}}},fp="16,128,19.82.0,19.40.0,24.77.0"}
P.entries["quest:95534"] = {n="Strahnbrad Mystery",s="En svedd lapp ber dig undersöka märkliga händelser kring de gamla blåsbälgarna i Strahnbrad. Rapportera vad du får veta i Hillsbrad.",h="En svedd lapp ber dig undersöka märkliga händelser kring de gamla blåsbälgarna i Strahnbrad.",kw={"eldelementar","eldmagi","hillsbrad","gamla blåsbälgar","svedd lapp","strahnbrad","mysteriet i strahnbrad"},sec={{t="Den svedda lappen",b="En lapp som hittats i Strahnbrad varnar för att de gamla blåsbälgarna verkar röra sig när ingen ser på. Skribenten avfärdar berättelsen som en spökhistoria, men insisterar ändå på att du tar reda på sanningen innan hen återvänder. Skribenten tror att stor makt finns i Strahnbrad, och eldmagi har bränt bort resten av meddelandet."},{t="Dina upptäckter",b="I Hillsbrad får stadsborna höra din rapport om de gamla blåsbälgarna i Strahnbrad. En eldelementar bodde inuti dem, men hur den hamnade där är fortfarande ett mysterium."}},faq={{q="Vad är märkligt med de gamla blåsbälgarna?",a="En svedd lapp hävdar att de gamla blåsbälgarna i Strahnbrad vaknar till liv när ingen ser på.",al={"de gamla blåsbälgarnas mysterium","blåsbälgar som rör sig","strahnbrads blåsbälgar"}},{q="Vem lämnade lappen?",a="Lappen nämner inte skribentens namn; det står att hen kommer tillbaka.",al={"vem skrev lappen","den svedda lappens skribent","mystisk lapp"}},{q="Vad säger lappen om Strahnbrad?",a="Skribenten tror att stor makt finns i Strahnbrad.",al={"makt i strahnbrad","stor makt där","vad finns i strahnbrad"}},{q="Var rapporterar jag vad jag hittar?",a="Du ombeds rapportera dina upptäckter inne i staden i Hillsbrad.",al={"var rapportera upptäckter","rapport i hillsbrad","rapportera i staden"}}},fp="18,128,15.291.0,13.167.1,38.90.0,18.60.0,40.51.0,30.59.0"}
P.entries["quest:956"] = {n="Bashal'Aran",s="Asterion, en Night Elf-ande fångad bland Bashal'Arans ruinerade pelare, söker reliken som håller honom bunden till denna värld. Han har känt av fångenskapens fördärv bland traktens grells och skickar resande på jakt efter satyrerna som styr dem och efter Ancient Moonstone Seal.",h="Asterion, en Night Elf-ande fångad bland Bashal'Arans ruinerade pelare, söker reliken som håller honom bunden...",kw={"ancient moonstone seal","asterion","bashal'aran","darkshore","grell","kaldorei","night elf-spöke","satyr"},ang={["class:Druid"]="Satyrernas förvridna inflytande fortsätter att fördärva Darkshores vilda djur och störa uråldriga andar som borde vila fridfullt i naturens kretslopp.",["faction:Alliance"]="När ruinerna i Darkshore renas från satyrernas fördärv säkras Kalimdors nordkust och Kaldorei får hjälp att låta sitt tragiska förflutna vila.",["race:NightElf"]="Bashal'Aran är en dyster påminnelse om ditt folks uråldriga förflutna, där kvarlevande förfäder hålls fastkedjade vid jorden av satyrer som förkroppsligar den demoniska förrädelsen under Sundering."},sec={{t="Ett fängelse av uråldrig sten",b="I långt över tusen år har anden Asterion varit bunden till Bashal'Arans fallna ruiner. Marmorpelarna runt omkring utgör en obeveklig bur som varken hans avtagande andliga krafter eller hans uråldriga magi kan krossa. Bunden av en förbannad relik har han tillbringat århundraden med att blicka ut över Darkshores dimhöljda trädkronor och undra om ens stenens nötning skulle kunna befria honom."},{t="Satyrerna och Moonstone Seal",b="När Asterion upptäckte att närliggande grells bar spår av magin som höll honom fången, drog han slutsatsen att satyrerna som styr de kaotiska varelserna hade lagt beslag på förtrollningens källa. Dessa demoniska Night Elves strövar genom de uråldriga dungarna och håller Ancient Moonstone Seal under uppsikt. Att återta denna talisman är det avgörande steget mot att krossa de osynliga galler som håller Asterion bunden till hans helgedom."}},faq={{q="Vem är Asterion?",a="Asterion är ett uråldrigt Night Elf-spöke fångat i Bashal'Arans ruiner. Bunden av uråldrig magi har han tillbringat mer än tusen år inspärrad bland helgedomens stående pelare, oförmögen att gå vidare eller lämna sitt stenfängelse.",al={"vem är asterion","asterions historia","spöke i bashal aran"}},{q="Varför har satyrerna Ancient Moonstone Seal?",a="Satyrerna leder och påverkar de vilda grells som angriper norra Darkshore. Eftersom grells bar spår av den bindande magin förstod Asterion att deras onda satyrmästare hade beslagtagit Ancient Moonstone Seal för att hålla traktens andar plågade och bundna.",al={"varför har satyrerna sigillet","satyrernas moonstone seal","ancient moonstone seal"}},{q="Vad händer när sigillet återtas?",a="Asterion får tag i själva reliken som har bundit honom i århundraden. Att återta Ancient Moonstone Seal är det näst sista steget mot hans befrielse. Då kan sigillet krossas, så att han äntligen får vandra fritt i skogarna igen.",al={"vad gör sigillet","återta sigillet"}},{q="Vad är Bashal'Aran?",a="Bashal'Aran är en uråldrig Night Elf-ruin längs norra Darkshores dimhöljda stränder. Den var en gång en storslagen bosättning eller helig enklav, men ligger nu i ruiner och hemsöks av grells, satyrer och fångade andar från en svunnen tid.",al={"bashal arans historia","vad är bashal aran"}},{q="Hur länge har Asterion varit fången här?",a="Asterion har varit fängslad i mer än tusen år. Utan fysiska medel eller magi för att bryta gränsen tvingades han vänta genom århundradena och undra om han någonsin skulle bli fri.",al={"hur gammal är asterion","hur länge fången"}},{q="Kan Asterion bara gå sin väg från helgedomen?",a="Nej. Ancient Moonstone Seal upprätthåller en metafysisk barriär runt helgedomen. Stenpelarna fungerar som en ogenomtränglig bur som hindrar hans spöklika gestalt från att ta sig utanför dem.",al={"kan asterion lämna platsen","varför är spöket fångat"}}},fx={["31aed888"]={q="Varför vill Asterion att sigillet hämtas?",a="Asterion är desperat efter frihet. Den uråldriga reliken är ankaret som håller honom fången för evigt och hans ande instängd i den förfallna helgedomen. I över tusen år har han blickat bortom stenpelarna utan att kunna bryta deras grepp med vare sig styrka eller trolldom. Att hämta artefakten är det enda sättet att förstöra den och äntligen låta honom vandra fritt i skogarna igen.",al={"varför vill asterion att det här blir gjort","asterions motiv","varför hjälpa asterion"}},["5f1ff286"]={q="Vad är Ancient Moonstone Seal?",a="Ancient Moonstone Seal är en magisk relik som fungerar som nyckeln till Asterions fångenskap. Den skapar en ogripbar barriär mellan Bashal'Arans pelare, som en evig cell som ingen besvärjelse eller fysisk styrka kan krossa. Så länge sigillet finns i de närliggande fördärvade krafternas händer förblir Asterion bunden till helgedomen.",al={"vad är ancient moonstone seal","vad gör moonstone seal","ancient moonstone seals syfte"}},c7650517={q="Varför skickas du mot de lokala satyrs?",a="Satyrs styr de vidriga grells som svärmar över Bashal'Arans ruiner. Eftersom de mindre grells bar spår av sigillets förtrollning drog Asterion slutsatsen att deras herrar måste ha tagit själva artefakten. Satyrs är fördärvade och dras till uråldriga magiska reliker. De håller sigillet i sitt läger och är därför ditt mål.",al={"vilka är satyrs i bashal'aran","varför strida mot satyrs","vem har sigillet"}},["341831b6"]={q="Varför kan Asterion inte hämta sigillet själv?",a="Asterion kan inte lämna helgedomens gränser. Sigillets magi håller honom helt bunden inom området och gör stenpelarna till ogenomträngliga galler. Han har varken styrkan eller trolldomen som krävs för att bryta sig fri, så han är helt beroende av en utomstående som kan ta sig in i satyr-lägren åt honom.",al={"varför behöver asterion mig","varför kan inte asterion hämta sigillet","varför just jag åt asterion"}}},fp="11,211,25.361.0,29.356.0,16.200.0,50.207.0,40.163.1,20.218.0,40.178.0,46.141.0"}
P.entries["quest:95601"] = {n="The Purple Ones",s="Clubtoe ber dig stoppa Twilight's Hammer-riterna i Sunnyglade. Riterna stärker vissa ogres och dödar andra.",h="Clubtoe ber dig stoppa Twilight's Hammer-riterna i Sunnyglade.",kw={"clubtoe","empowered brutes","ogre","sunnyglade","the purple ones","twilight ritualists","twilight's hammer"},sec={{t="Riter i Sunnyglade",b="I Sunnyglade skickar Clubtoe dig mot Twilight Ritualists och Empowered Brutes. En död ogre verkar vara en av vännerna Clubtoe letade efter. Riterna stärker vissa medlemmar och dödar fler, så Clubtoe vill att ritualisterna och deras skapelser stoppas innan de sprider sig."}},faq={{q="Vem är Clubtoe?",a="Clubtoe är den som ber dig stoppa Twilight Ritualists i Sunnyglade.",al={"clubtoe","vem är clubtoe"}},{q="Vad gör The Purple Ones?",a="Twilight Ritualists utför riter på sina medlemmar. Vissa blir stärkta, medan fler dödas.",al={"the purple ones","vad gör the purple ones"}},{q="Varför vill Clubtoe stoppa riterna?",a="Clubtoe befarar att ritualisterna och deras monstrositeter kommer att sprida sig.",al={"varför stoppa riter","varför döda ritualister"}},{q="Vad hände med Clubtoes vänner?",a="En död ogre verkar vara en av vännerna Clubtoe letade efter.",al={"clubtoes vänner","var är vännerna"}},{q="Var är Clubtoe?",a="Clubtoe är i Sunnyglade.",al={"clubtoes plats","sunnyglade clubtoe"}}},fp="15,111,19.274.0,15.76.0,31.98.0,42.65.0,35.71.0,17.25.0"}
P.entries["quest:95602"] = {n="Sickening Lights",s="Clubtoe ber dig slå sönder de lysande ritualcirklarna under Sunnyglade. Ljuset gör honom sjuk, och han fruktar Chogg'Zacs vrede om han agerar ensam.",h="Clubtoe ber dig slå sönder de lysande ritualcirklarna under Sunnyglade.",kw={"grottor","chogg'zac","clubtoe","ljus","glänsande bilder","illamåendeframkallande ljus","sunnyglade","twilight ritual circles"},sec={{t="Ett illamåendeframkallande sken",b="Clubtoe arbetar i grottorna under Sunnyglade och krossar sten åt Chogg'Zac. Han hittar lysande ljus i stenen, och de andra ritar bilder med dem. Skenet får Clubtoe att må illa, men han fruktar att Chogg'Zac ska straffa honom för att ha förstört bilderna. Du ombeds förstöra Twilight Ritual Circles, och Clubtoe hoppas att ljuset inte längre ska besvära honom."}},faq={{q="Vem ber mig förstöra cirklarna?",a="Clubtoe ber dig förstöra Twilight Ritual Circles under Sunnyglade.",al={"vem är clubtoe","clubtoe-uppdrag","vem vill få ljusen krossade"}},{q="Varför vill Clubtoe att ljusen ska krossas?",a="Ljuset får Clubtoe att må illa, och han vill krossa de lysande bilderna.",al={"varför krossa ljusen","ljusen gör clubtoe sjuk","clubtoe avskyr ljus"}},{q="Vem är Chogg'Zac?",a="Chogg'Zac är Clubtoes chef, och Clubtoe är rädd att han blir arg om cirklarna förstörs.",al={"chogg'zac","clubtoes chef","storchef"}},{q="Vad är de glänsande bilderna?",a="De är Twilight Ritual Circles, som finns i grottorna under Sunnyglade. Clubtoe kallar dem lysande bilder.",al={"glänsande bilder","skymningscirklar","vad är ljusen"}},{q="Vad gör Clubtoe i grottorna?",a="Clubtoe krossar sten åt Chogg'Zac och har hittat lysande ljus i stenen.",al={"clubtoes arbete","krossa sten","vad gör clubtoe"}},{q="Mår Clubtoe bättre när cirklarna har krossats?",a="När du har krossat cirklarna säger Clubtoe att han redan mår bättre.",al={"clubtoe slutfört","hjälpte det att krossa dem","ljusen får honom att må bättre"}}},fp="16,147,16.364.0,38.75.0,41.78.0,17.90.0,28.116.0,34.76.0,55.66.0"}
P.entries["quest:95621"] = {n="Trouble in the Valley",s="Trouble in the Valley handlar om en mystisk grupp Kul Tiran-soldater som upptäckts genomsöka dalbottnen. Beväpnade trupper har slagit läger nära en förstörd karavan i söder, vilket får lokala spejare att vilja oskadliggöra dem och ta reda på varför de oväntat söker igenom området.",h="Trouble in the Valley handlar om en mystisk grupp Kul Tiran-soldater som upptäckts genomsöka dalbottnen.",kw={"karavan","kul tiras","soldater","trouble in the valley","dal","förstörd karavan"},ang={["race:Human"]="Att se soldater med havsgröna färger och ankarsymboler från öriket Kul Tiras i dalen är ett sällsynt och oväntat möte med denna tillbakadragna, sjöfarande människonation."},sec={{t="Misstänkt aktivitet i dalen",b="En vaksam gevärsskytt som spanade över låglandet fick syn på en grupp människosoldater som genomsökte dalbottnen. Genom att titta noga med ett kikarsikte kunde spejaren tydligt urskilja heraldiken och uniformerna från sjönationen Kul Tiras. Deras oväntade närvaro i dalen väckte genast oro, eftersom beväpnade främlingar sällan rör sig så öppet utan att dra till sig uppmärksamhet."},{t="Den förstörda karavanen",b="Soldaterna intog en position nära en förstörd karavan i söder. Vad som lockade dem till den havererade vagnen är fortfarande ett brådskande mysterium. Lokala observatörer har bedömt den påträngande beväpnade närvaron som ett omedelbart hot och skickat utredare för att oskadliggöra soldaterna och ta reda på expeditionens verkliga syfte."}},faq={{q="Vad gör Kul Tiran-soldater i dalen?",a="En prickskytt fick syn på en grupp Kul Tiran-soldater som letade efter något i dalen nedanför. De slog läger nära en förstörd karavan i söder, vilket fick lokala spejare att undersöka deras märkliga avsikter.",al={"varför är kul tiran här","kul tiras-soldater i dalen","vad gör kul tiran här"}},{q="Var ligger Kul Tiran-lägret?",a="Soldaterna har slagit läger nära en förstörd karavan söder om utsiktsplatsen där spejaren spanar över dalen.",al={"den förstörda karavanens plats","var ligger kul tiras-lägret","karavanens plats"}},{q="Hur upptäcktes Kul Tiran-närvaron?",a="En spejare som höll utkik över dalen använde ett kikarsikte för att undersöka den mystiska gruppen människor på avstånd och kände lätt igen Kul Tiras utmärkande uniformer och insignier.",al={"hur identifierades de","kul tiras uniformer"}},{q="Vad är målet med att undersöka lägret?",a="Uppgiften går ut på att resa söderut mot den förstörda karavanen, konfrontera Kul Tiran-soldaterna där och ta reda på vad som fick dem att söka igenom området.",al={"vad är målet","målen i trouble in the valley"}},{q="Varför betraktas Kul Tiran-soldaterna som fiender?",a="Eftersom en beväpnad grupp utländska soldater utan förklaring genomsöker området kring en förstörd karavan, anser spejarna att de utgör ett hot som måste oskadliggöras för att deras avsikter ska bli kända.",al={"varför slåss mot kul tiras","är kul tiran fientliga"}},{q="Vem upptäckte soldaterna i dalen?",a="Walton, eremitskräddaren som håller utkik över dalen, upptäckte först soldaterna genom sitt kikarsikte och anlitade en äventyrare för att oskadliggöra dem och ta reda på varför de var där.",al={"vem såg soldaterna","vem gav uppdraget"}}},fp="21,177,33.236.0,19.264.0,48.174.0,36.100.0,42.130.0,48.127.0,50.180.0,40.164.0"}
P.entries["quest:95646"] = {n="Horrors in the Highland",s="Rethiel the Greenwarden känner en oren fördärvelse sippra genom en bergsklyfta in i det osaltade vattnet ovanför Wetlands. Äventyrare måste ta sig upp till utgrävningsplatserna för att döda en Highland Horror och hämta dess rotkärna. Rethiel upptäcker att en uråldrig energi håller på att vakna och varnar för att det fortsatta grävandet hotar säkerheten för alla i regionen.",h="Rethiel the Greenwarden känner en oren fördärvelse sippra genom en bergsklyfta in i det osaltade vattnet...",kw={"födärvelse","utgrävningsplatser","highland horror","horrors in the highland","rethiel","rethiel the greenwarden","rotkärna","wetlands"},ang={["class:Druid"]="Rethiel känner hur den naturliga balansen förändras genom hans rötter och vattendragen. Druider som är lyhörda för landet kommer att känna igen hur sötvattenlivet plötsligt blivit sårbart för uråldrig fördärvelse.",["faction:Alliance"]="Alliansens utforskare och Prospektörer som arbetar på utgrävningsplatser i bergen riskerar att störa uråldriga krafter begravda under jorden.",["race:Dwarf"]="Dvärgarnas utgrävningsplatser i höglandet har grävt fram mer än uråldriga reliker, vilket får Rethiel att uppmana utgrävarna att avbryta arbetet innan värre ondska vaknar."},sec={{t="Smitta i klyftan",b="Djupt inne i Wetlands känner Rethiel the Greenwarden en oroande förändring i landet. En oren smitta sipprar genom en bergsklyfta och infekterar sötvattensvarelserna som lever i höglandet ovanför. Till skillnad från det härdiga liv som formats av det bräckta låglandsvattnet har dessa sötvattensvarelser aldrig känt havets skyddande salt och är därför helt försvarslösa mot det onda som sprider sig. Rethiel ber äventyrare ta sig upp till utgrävningsplatserna, döda en Highland Horror och hämta dess rotkärna."},{t="Ett uråldrigt uppvaknande",b="När Highland Horrors rotkärna förs fram till Rethiel bekräftas väktarens farhågor: en uråldrig energi har börjat vakna. Åkomman som plågar höglandets varelser är ingen vanlig sjukdom, utan en följd av den senaste tidens grävande. Rethiel varnar enträget för att de ivriga utgrävarna vid bergsplatserna genast måste sluta gräva, innan deras tanklösa nyfikenhet släpper lös något långt värre över Wetlands."}},faq={{q="Vem ger uppdraget Horrors in the Highland?",a="Rethiel the Greenwarden, en uråldrig beskyddare som vakar över Wetlands, ger uppdraget efter att ha känt en oren fördärvelse sippra genom en närliggande bergsklyfta.",al={"vem ger horrors in the highland","uppdragsgivare för horrors in the highland","rethiel uppdrag"}},{q="Var finns Highland Horrors?",a="Highland Horrors håller till på utgrävningsplatserna på högre mark ovanför låglandet, nära bergsklyftan där fördärvelsen sipprar fram.",al={"var finns highland horrors","highland horror plats","var hittar man highland horror"}},{q="Varför är höglandets varelser så mottagliga för fördärvelse?",a="Höglandets sötvattensvarelser saknar den härdande saltlaken och havssaltet som finns i de lägre våtmarkerna, vilket gör dem sköra och särskilt bittra i sin reaktion på den fördärvande smittan.",al={"varför är varelserna smittade","varför är höglandets varelser fördärvade","fördärvelse i osaltat vatten"}},{q="Vad är en Highland Horrors rotkärna?",a="Rotkärnan är hjärtat i den fördärvade Highland Horror. Rethiel behöver den för att undersöka den onaturliga kraft som sprider sig genom vattendragen och bekräfta fördärvelsens natur.",al={"vad är rotkärnan","highland horrors kärna","varför hämta rotkärnan"}},{q="Vad upptäcker Rethiel när du återlämnar rotkärnan?",a="När Rethiel undersöker kärnan inser han att en uråldrig energi har börjat vakna djupt nere i jorden, troligen störd av vårdslöst grävande på utgrävningsplatserna.",al={"vad upptäcker rethiel","uråldrig energi i wetlands","fara vid utgrävning"}},{q="Varför vill Rethiel att utgrävarna slutar gräva?",a="Rethiel varnar för att de ivriga utgrävarna i höglandet genast bör sluta gräva för sin egen säkerhets skull, eftersom deras arbete riskerar att släppa lös farliga uråldriga krafter.",al={"rethiel stoppa grävandet","vad bör utgrävarna göra","varning vid dvärgarnas utgrävningsplats"}}},fp="23,266,18.437.0,19.372.1,45.144.0,36.131.0,60.132.0,43.189.0,57.170.0,53.127.0"}
P.entries["quest:95647"] = {n="Lost in the Thicket Things",s="En orolig alkemist ber resenärer leta reda på hennes försvunne make, Ardin Grassman, som försvann efter att ha följt rykten om skyhöga, okända grässorter. Ardins botaniska nyfikenhet ledde honom rakt mot en närliggande utgrävningsplats, där farliga vilda djur och spindelangrepp har belägrat arbetslaget.",h="En orolig alkemist ber resenärer leta reda på hennes försvunne make, Ardin Grassman, som försvann efter att...",kw={"alkemi","ardin","ardin grassman","utgrävningsplatser","örtinsamling","lost in the thicket things","spindlar","skyhöga grässorter"},ang={["class:Druid"]="Druider som är i samklang med vildmarkens balans kan intressera sig för Ardins naturliga förmåga att känna av växtlighet, liksom den onaturliga upprördhet som stör djurlivet nära utgrävningsplatserna.",["profession:Herbalism"]="Ardin Grassman har en medfödd förmåga att känna av växter och örter och klättrar ofta i förrädisk terräng för att samla sällsynta växter till alkemin."},sec={{t="En samlares kall",b="I ”Lost in the Thicket Things” söker en alkemist hjälp med att hitta sin försvunne make, Ardin Grassman. Ardin har en ovanlig, instinktiv fallenhet för naturen och trotsar regelbundet branta klippor och avlägsen vildmark för att samla sällsynta örter och botaniska exemplar till sina alkemiförråd. När ett förbipasserande utgrävningslag berättade om bisarra, skyhöga grässorter som ingen sett förut, tog nyfikenheten överhanden och Ardin gav sig av för att själv undersöka växtligheten."},{t="Bakhåll vid utgrävningen",b="Ardin följde expeditionen till deras utgrävningsplats, men hamnade rakt i fara. Något i det omgivande landet hade gjort den lokala faunan upprörd, så att aggressiva vilda djur – framför allt svärmar av fientliga spindlar – gick till angrepp och övermannade utgrävningslaget. Ardin och arbetslaget blev instängda av de anstormande bestarna och belägrade tills resenärer ingrep och räddade den strandsatte botanisten."}},faq={{q="Vem är Ardin Grassman?",a="Ardin Grassman är en samlare med en ovanlig naturlig förmåga att känna av växter och örter. Han söker regelbundet av klippor och bergstoppar för att förse sin fru med vilda växter till hennes alkemiverksamhet, men nyfikenheten på märkliga, skyhöga grässorter drog honom mot en utgrävningsplats.",al={"vem är ardin","ardin grassmans bakgrund","vem är ardin grassman"}},{q="Varför gav sig Ardin ut i vildmarken?",a="Ardin hörde ett utgrävningslag beskriva enorma, skyhöga grässorter som de aldrig hade stött på förut. Hans fallenhet för ovanliga växter lockade honom att ge sig ut och se den märkliga växtligheten med egna ögon, men han kom aldrig hem igen.",al={"varför gav sig ardin av","varför är ardin försvunnen","vad letade ardin efter"}},{q="Vart tog Ardin vägen?",a="Ardin begav sig mot de närliggande utgrävningsplatserna efter att ha hört rapporter från en expedition som passerade. Resenärer som letar efter honom måste söka igenom utgrävningsplatserna där arbetslaget slog läger.",al={"var är ardin","ardins plats","var hittar man ardin grassman"}},{q="Vad hände med Ardin vid utgrävningsplatsen?",a="Ardin fann att utgrävningslägret hade övermannats när den lokala faunan blev upprörd och aggressiv. Jättespindlar och andra uppretade bestar överföll expeditionen och höll Ardin och arbetslaget instängda tills hjälp utifrån kom.",al={"vad hände med ardin","är ardin död","vad attackerade ardin"}},{q="Vem letar efter Ardin?",a="Sökandet börjar hos Ardins fru, en alkemist som förlitar sig på hans örtexpeditioner för att fylla sina hyllor. När han inte kom tillbaka efter att ha undersökt rykten om märkligt gräs sökte hon upp dugliga resenärer som kunde hämta hem honom.",al={"vem ger uppdraget lost in the thicket things","vem startade det här uppdraget","ardins fru"}},{q="Varför attackerade de vilda djuren utgrävningslaget?",a="Djurlivet kring utgrävningsplatserna blev plötsligt och våldsamt upprört, men den exakta orsaken är fortfarande oklar. Störningen drev aggressiva varelser, särskilt spindlar, att svärma och övermanna utgrävningslaget.",al={"varför attackerar spindlarna","vad gjorde djuren upprörda","varför är bestarna arga"}}},fp="26,183,19.303.0,22.250.1,22.215.0,39.168.0,19.133.0,46.178.0,25.183.0,48.162.0"}
P.entries["quest:95663"] = {n="Dragonmaw Rumors",s="Deathstalkers söker säkrare uppgifter om den Dragonmaw-magi som det ryktas om i Wetlands. Du skickas för att möta deras agent i kullarna ovanför klanens läger.",h="Deathstalkers söker säkrare uppgifter om den Dragonmaw-magi som det ryktas om i Wetlands.",kw={"söndriga symboler","deathstalker agent","deathstalkers","drakbindning","dragonmaw","dragonmaws läger","rykten om dragonmaw","wetlands"},sec={{t="Viskningar i Wetlands",b="En Deathstalker i Wetlands behöver din hjälp medan rykten sprids om klanen Dragonmaw. De sägs behärska magi som binder drakar, och det viskas om att de förbereder en uppvisning av den kraften. Söndriga symboler gav inga säkra bevis, så du skickas för att möta en agent i kullarna ovanför deras läger."}},faq={{q="Vad ryktas Dragonmaw hålla på med?",a="Enligt ryktet förbereder Dragonmaw en uppvisning av magi som är stark nog att få drakar att tjäna dem.",al={"rykten om dragonmaw","vad planerar dragonmaw","dragonmaws magi"}},{q="Varför behöver Deathstalkers hjälp?",a="Deathstalkers har bara söndriga symboler och osäkra rykten om Dragonmaw, så en agent behöver hjälp i kullarna ovanför klanens läger.",al={"deathstalker behöver hjälp","varför hjälpa deathstalkers","vad behöver de"}},{q="Var finns agenten från Deathstalkers?",a="Agenten finns i kullarna ovanför Dragonmaw-lägret i Wetlands.",al={"agentens plats","var möta agenten","deathstalker agent kullarna"}},{q="Vad avslöjade de söndriga symbolerna?",a="De söndriga symbolerna förmedlade bara osäkra rykten om en påstådd magiuppvisning av Dragonmaw.",al={"söndriga symboler","vad symbolerna visade","symboler dragonmaw"}},{q="Vad händer när du möter agenten?",a="Agenten från Deathstalkers avslöjar nästa steg när du möter henne i kullarna ovanför Dragonmaw-lägret.",al={"möta agenten","nästa steg","vad säger agenten"}}},fp="16,151,24.300.0,43.98.0,35.151.0,32.67.0,35.94.0,37.106.0"}
P.entries["quest:95664"] = {n="Elder Knowledge",s="En märklig Titan Relic sprider ljus som ett levande prisma, men dess natur är ännu oklar. Du tar den till Elder Rise i Thunder Bluff för att söka någon som kan förklara dess uråldriga kraft.",h="En märklig Titan Relic sprider ljus som ett levande prisma, men dess natur är ännu oklar.",kw={"uråldrig kraft","sammansatt skärva","elder knowledge","elder rise","levande prisma","thunder bluff","titan relic"},sec={{t="En skärva av ljus",b="Den ovanliga sammansatta skärvan du bär på sprider ljus som ett levande prisma. Dess natur är oklar, men dess kraft känns uråldrig. Du tar Titan Relic till Elder Rise i Thunder Bluff och söker någon som kan berätta mer."}},faq={{q="Vad är Titan Relic?",a="Det är en ovanlig sammansatt skärva som sprider ljus som ett levande prisma. Dess natur är oklar, men dess kraft känns uråldrig.",al={"titan relic","vad är reliken","prismaskärva"}},{q="Vart ska jag ta Titan Relic?",a="Ta Titan Relic till Elder Rise i Thunder Bluff och leta efter någon som kan förklara vad den är.",al={"vart ska reliken","elder rise relik","thunder bluff skärva"}},{q="Varför bär jag på skärvan?",a="Du söker någon på Elder Rise som kan berätta mer om Titan Relic.",al={"varför denna relik","vad göra med skärvan","elder knowledge uppdrag"}}},fp="15,186,16.232.0,24.127.0,32.92.0,28.82.0"}
P.entries["quest:95682"] = {n="Open the Maw",s="En Deathstalker Agent ber dig driva bort Dragonmaw från Excavation Sites och ta med allt av intresse tillbaka. Klanen kanske söker en väg tillbaka till makten.",h="En Deathstalker Agent ber dig driva bort Dragonmaw från Excavation Sites och ta med allt av intresse tillbaka.",kw={"dark lady","deathstalker agent","dragonmaw","excavation site","forsaken","orchiskt klotter","rend"},sec={{t="Ett diskret tillvägagångssätt",b="En Deathstalker Agent utanför Excavation Site vill få bort Dragonmaws styrkor. Resterna av den draktämjande klanen tror sig ha hittat något som kan återge dem deras forna makt. Deras illa rustade styrkor måste drivas bort så att Deathstalkers kan ta sig in obemärkta. Ta med allt av intresse som du hittar tillbaka, och låt saken stanna mellan agenten och den kungliga ledningen."},{t="Det återfunna klottret",b="Deathstalker Agent känner igen den orchiska skriften bland de återfunna föremålen. Den visar att Dragonmaw hoppas kunna blidka Rend, deras falske krigshövding. Agenten kallar försöket utsiktslöst, men kunskapen är värdefull för Dark Lady. Agenten låter dig behålla de återfunna föremålen och varnar dig för att säga något om uppdraget."}},faq={{q="Vem skickade mig till Excavation Site?",a="En Deathstalker Agent utanför Excavation Site ber dig driva bort Dragonmaw och ta med allt av intresse tillbaka.",al={"vem vill driva bort dragonmaw","deathstalker agents uppdrag","vem skickade mig"}},{q="Vad hoppas Dragonmaw kunna göra?",a="Resterna av Dragonmaw tror sig ha hittat något som kan återge dem deras forna makt.",al={"dragonmaws plan","varför är dragonmaw här","dragonmaw tillbaka till makten"}},{q="Varför vill Deathstalkers få platsen röjd?",a="De vill ta sig in på Excavation Site utan att bli upptäckta.",al={"varför röja excavation site","deathstalkers tar sig in","vad behöver de"}},{q="Vad ska jag ta med tillbaka?",a="Ta med allt av intresse som du hittar hos Dragonmaw tillbaka till Deathstalker Agent.",al={"vad ska hämtas","dragonmaws föremål","vad vill agenten"}},{q="Vem är Dark Lady?",a="Agenten använder den titeln för Sylvanas, som leder Forsaken.",al={"vad betyder dark lady","vem är dark lady","sylvanas titel"}}},fp="12,153,16.379.0,20.323.1,35.117.0,36.95.0,47.50.0,25.77.0,21.63.0"}
P.entries["quest:95697"] = {n="Changing Tastes",s="Changing Tastes är ett uppdrag i Orgrimmar om kulinariska ambitioner på Borstan's Firepit. Efter råd från Zamja och berättelser om jättelika rovfågelklor låter Borstan äventyrare resa över havet till Wetlands för att hämta exotiskt kött från snårrovfåglar.",h="Changing Tastes är ett uppdrag i Orgrimmar om kulinariska ambitioner på Borstan's Firepit.",kw={"borstan","borstans eldstad","changing tastes","utgrävningsplatser","orgrimmar","snårrovfågel","kött från snårrovfågel","wetlands","zamja"},ang={["faction:Horde"]="Att förse Borstan's Firepit innebär att ge sig djupt in i omstridda områden på andra sidan havet och ta med exotiskt kött tillbaka till Orgrimmar.",["profession:Cooking"]="Borstan vill förädla traditionella rustika rätter till något som passar Horde-huvudstaden. Det visar hur kulinariska smaker och värdshusmenyer utvecklas bortom byarnas klassiker."},sec={{t="Att förädla huvudstadens mat",b="I hjärtat av Orgrimmar vill Borstan's Firepit utöka sitt kulinariska utbud. Zamja föreslog att de skulle börja servera hemlagad rovfågel för resenärer som saknar de tröstande, välbekanta rätterna från sina hembyar. Borstan gillade tanken på att servera rovfågel för att locka nya gäster, men tyckte att det inte passade Horde-huvudstaden att bara återskapa byarnas rustika rätter. I stället föreställde han sig en storslagenare och djärvare variant av den klassiska rätten."},{t="Jakten i Wetlands",b="Inspirationen kom när en jägare återvände till Orgrimmar med en enorm klo från snårrovfåglarna som stryker omkring vid utgrävningsplatserna i Wetlands. Fascinerad av dessa bestars kvalitet och storlek ordnar Borstan så att äventyrare korsar havet till Eastern Kingdoms, trotsar utgrävningsområdena och hämtar förstklassigt kött från snårrovfåglar till hans sprakande eldar."}},faq={{q="Vad är uppdraget Changing Tastes?",a="Changing Tastes är ett kulinariskt uppdrag i Orgrimmar. Borstan, som äger Borstan's Firepit, vill ha kött från snårrovfåglar i avlägsna Wetlands för att lyfta värdshusets meny över enkel bymat.",al={"vad är changing tastes","uppdraget changing tastes"}},{q="Vem är Zamja?",a="Zamja är en medarbetare eller kollega inom matlagning i Orgrimmar. Hon föreslog att Borstan's Firepit skulle lägga till hemlagade rovfågelrätter för att locka kunder som vanligtvis inte besöker stället.",al={"vem är zamja","zamja matlagning"}},{q="Vad är Borstan's Firepit?",a="Borstan's Firepit är ett matställe i Horde-huvudstaden Orgrimmar, känt för sina rejäla kötträtter som serveras till både resenärer och lokalbor.",al={"borstans eldstad","var finns borstan"}},{q="Varför vill Borstan ha kött från snårrovfåglar?",a="Zamja föreslog vanlig, hemlagad rovfågel för att locka gäster, men Borstan vill skapa en storslagnare variant av välbekanta smaker. Inspirerad av en jägares berättelse om jättelika klor valde han snårrovfåglarna i Wetlands.",al={"varför rovfågelkött","varför snårrovfågel"}},{q="Var finns snårrovfåglarna?",a="Snårrovfåglar lever vid utgrävningsplatserna i Wetlands, en alliansvänlig region på andra sidan Great Sea i Eastern Kingdoms.",al={"var hittar jag snårrovfåglar","rovfåglar vid utgrävningsplatserna i wetlands"}},{q="Vem ger uppdraget Changing Tastes?",a="Borstan, ägaren till Borstan's Firepit i Orgrimmar, erbjuder uppdraget efter att ha inspirerats av råd från Zamja och en trofé som en äventyrslysten jägare tagit med sig tillbaka.",al={"vem ger changing tastes","borstan uppdragsgivare"}}},fp="15,189,25.341.0,24.317.0,34.184.0,13.162.0,26.124.0,42.179.0,38.130.0,36.162.0"}
P.entries["quest:957"] = {n="Bashal'Aran",s="Det här uppdraget ber äventyrare hjälpa Asterions fångade ande i ruinerna av Bashal'Aran. Genom att föra hans bindande sigill söderut till systerruinerna i Ameth'Aran söker de ett sätt att bryta hans uråldriga bojor.",h="Det här uppdraget ber äventyrare hjälpa Asterions fångade ande i ruinerna av Bashal'Aran.",kw={"ameth'aran","asterion","athrikus","azshara","bashal'aran","darkshore","highborne","månstenssigill"},ang={["class:Mage"]="De kraftfulla förtrollningarna som håller Asterion bunden och de överlevande lågorna i Ameth'Aran ger en inblick i den råa arkana kraft som uråldriga Highborne-trollkarlar behärskade.",["faction:Alliance"]="När de uråldriga förbannelserna i Darkshore skingras säkras gränserna för de nya Night Elf-bosättningar som växer fram från Auberdine.",["race:NightElf"]="För nutidens Night Elves i Kalimdor innebär Asterions frigivning ett allvarligt möte med folkets förflutna före Sundringen och den kvardröjande korruptionen hos drottning Azsharas Highborne-adel."},sec={{t="Ett fängelse av uråldrig trolldom",b="Asterions ande har dröjt sig kvar i Bashal'Aran i årtusenden, fjättrad i döden av ett Ancient Moonstone Seal. Sigillet smiddes med Highborne-kastens mäktiga trolldom före den stora Sundringen och kan inte krossas med vanlig styrka. För att förstöra det krävs den särskilda magin från en uråldrig låga som fortfarande glöder bland de fallna stenarna i Ameth'Aran i söder."},{t="Darkshores tvillingruiner",b="Bashal'Aran och Ameth'Aran var en gång livliga systerboplatser i kaldoreis civilisation, när drottning Azshara härskade och Evighetens källa ännu höll deras imperium samman. I dag är båda platserna igenvuxna, hemsökta ruiner fyllda av kvarvarande andar och instabila arkana energier. I ett lusthus av sten i Ameth'Aran finns ett mystiskt fyrfat med cyanblå eld, den enda kraft som kan förtära Asterions bindande relik."},{t="Hämnden vaknar",b="När sigillet förstörts är Asterion äntligen fri från sin börda. Han blickar ut över ett krossat Kalimdor som förändrats fullständigt sedan den gyllene tidsålder han minns. Men friheten ger honom ingen frid. Han känner att hans tidigare mästare och fångvaktare, Highborne Athrikus, fortfarande lever, och Asterions uråldriga förtvivlan övergår snabbt i en kall, brännande hämndlystnad."}},faq={{q="Vem är Asterion?",a="Asterion är en Night Elf-ande som är fångad i ruinerna av Bashal'Aran. Han levde för tiotusen år sedan, under drottning Azsharas regeringstid, och hålls bunden till ruinerna av ett sigill som skapades av en av de mäktigaste bland Highborne.",al={"asterion","vem är spöket","npc asterion"}},{q="Var förstör jag Ancient Moonstone Seal?",a="Sigillet måste föras söderut till Ameth'Aran, Bashal'Arans tvillingruin. Leta efter ett lusthus av sten som skyddar ett stort, kubformat fyrfat med uråldrig grönblå magisk eld.",al={"var finns lågan","plats för uråldrig låga","förstör sigill"}},{q="Hur hänger Bashal'Aran och Ameth'Aran ihop?",a="De var systerstäder i det uråldriga Night Elf-imperiet före Sundringen. Båda ödelades för tiotusen år sedan och lämnade efter sig hemsökta stenpelare, kvarvarande arkana energier och oroliga andar.",al={"tvillingruiner","ametharan koppling","bashalaran ametharan"}},{q="Vem fängslade Asterion?",a="Asterion säger att en av de mäktigaste bland Highborne skapade sigillet som håller honom bunden. Mer om hans tidigare mästare avslöjas under uppdragskedjan.",al={"vem fängslade asterion","vem är athrikus","asterions mästare"}},{q="Vilken tid minns Asterion?",a="Asterion vandrade senast på jorden när den ursprungliga Evighetens källa ännu fanns, drottning Azshara styrde imperiet och Highbornes adel höll sina ståtliga hov före Sundringen.",al={"asterions förflutna","evighetens källas tidsålder","hur gammal är asterion"}},{q="Får Asterions ande ro när han blir fri?",a="Sigillet ska förstöras för att bryta Asterions fängelse. Hans reaktion på friheten får du veta när du återvänder till honom.",al={"går asterion vidare","vad händer med asterion","asterion efter frigivningen"}}},fx={["8275c861"]={q="Varför vill Asterion att Ancient Moonstone Seal förstörs?",a="Ancient Moonstone Seal är ankaret som håller Asterions ande fången i plåga bland Bashal'Arans ruiner. Det skapades för årtusenden sedan med mäktig Highborne-trolldom och håller honom fängslad, blind för världen bortom. Att förstöra det i den mystiska uråldriga lågan i Ameth'Aran är det enda sättet att krossa hans eteriska bojor och ge honom frihet och klarhet att se vad som blivit av Kalimdor.",al={"varför förstöra moonstone seal","asterions motiv","varför vill asterion bryta sigillet"}},["51df5ddd"]={q="Varför behöver Asterion att du tar sigillet till Ameth'Aran?",a="Asterion är bunden av den uråldriga Highborne-magin som håller honom fast vid Bashal'Aran. Han kan inte lämna de närmaste ruinerna, än mindre färdas söderut till Ameth'Aran. Han behöver en resenär som bär sigillet in i den uråldriga lågan.",al={"varför kan inte asterion förstöra sigillet","varför behöver asterion mig","varför skicka en äventyrare att förstöra sigillet"}}},fp="11,147,27.134.0,23.371.0,17.273.1,16.195.0,46.180.0,60.221.0,24.132.1,32.178.0,45.113.1"}
P.entries["quest:95737"] = {n="Seeking Caitlin",s="I Menethil Harbor väntar en alkemist på besked om ett sällsynt gräs. Hon ber dig hitta Caitlin Grassman, vars man inte har hört av sig från en utgrävning.",h="I Menethil Harbor väntar en alkemist på besked om ett sällsynt gräs.",kw={"alkemist","caitlin grassman","utgrävning","gräsfrön","menethil harbor","urtida gräs","seeking caitlin","wetlands"},ang={["profession:Herbalism"]="Som örtsamlare blir du ombedd att se till Caitlin efter att hennes mans grupp hittat spår av ett sällsynt urtida gräs."},sec={{t="En saknad rapport",b="Alkemisten fick höra av Caitlin att hennes mans utgrävningsgrupp hade hittat spår av ett urtida gräs. Caitlin vet inte hur mycket de hittade eller om det går att komma åt.\n\nNu ber alkemisten dig att tala med Caitlin i Menethil Harbor. Båda kvinnorna väntar på att få veta vad som hänt med de utlovade fröna."}},faq={{q="Vem är Caitlin Grassman?",a="Caitlin Grassman är alkemist i Menethil Harbor. Hennes man anslöt sig till en utgrävningsgrupp som hittade spår av ett urtida gräs.",al={"caitlin","vem är caitlin","caitlin grassman"}},{q="Vad vill alkemisten att jag ska göra?",a="Alkemisten ber dig att tala med Caitlin Grassman i Menethil Harbor.",al={"hitta caitlin","tala med caitlin","caitlins uppdrag"}},{q="Vad hittade utgrävningsgruppen?",a="Gruppen hittade spår av ett sedan länge försvunnet urtida gräs. Hur mycket det finns och om det går att komma åt är fortfarande okänt.",al={"urtida gräs","sällsynt gräs","utgrävningsfynd"}},{q="Varför är de oroliga?",a="Caitlin lovade alkemisten att hennes man skulle ta med sig gräsfrön tillbaka, men inga har kommit. Båda kvinnorna misstänker att något har gått på tok vid utgrävningen.",al={"var är fröna","saknade gräsfrön","varför oroliga"}}},fp="15,161,16.313.0,24.130.0,38.73.0,34.117.0,23.151.0"}
P.entries["quest:95748"] = {n="The Gurubashi Legends of Old",s="En trollärd söker en avgnidning av en uråldrig stentavla norr om Vile Reef. Dess legend kan klargöra hur stort det förlorade I'lalai var.",h="En trollärd söker en avgnidning av en uråldrig stentavla norr om Vile Reef.",kw={"uråldrig ruin","gurubashi","i'lalai","legend","avgnidning","stentavla","troll","the vile reef"},ang={["race:Troll"]="Som troll blir du ombedd att hjälpa en lärd att studera legender om en förlorad trollstad."},sec={{t="En stentavla vid kusten",b="Den lärde jämför en bit av en stentavla som du tog med dig med ruinerna utanför Vile Reef. Ruinerna verkar för små för att motsvara den vidsträckta civilisation som texten beskriver. Därför ber den lärde dig att göra en avgnidning av en stentavla i en uråldrig trollruin på kustkullarna i norr."},{t="Ett gammalt minne",b="Den lärde tar tacksamt emot avgnidningen och säger sig känna igen stentavlan från sin ungdom. Många månar har gått sedan den senast lästes, och den lärdes minne har bleknat."}},faq={{q="Vad vill den lärde ha?",a="Den lärde vill ha en avgnidning av en stentavla med legender om den förlorade trollstaden I'lalai.",al={"avgnidning av stentavla","vad behöver han","begäran om avgnidning"}},{q="Var finns stentavlan?",a="Den finns i en uråldrig trollruin på kustkullarna norr om Vile Reef.",al={"stentavlans plats","var finns stentavlan","norr om revet"}},{q="Varför vill den lärde ha en avgnidning?",a="En bit av en stentavla som du tog med dig beskriver I'lalai som en vidsträckt civilisation, medan ruinerna utanför Vile Reef verkar för små för att motsvara den.",al={"varför avgnidning","i'lalais stentavla","legend om förlorad stad"}},{q="Vad är I'lalai?",a="I texten på stentavlans fragment beskrivs I'lalai som en förlorad trollstad och en vidsträckt civilisation.",al={"staden i'lalai","förlorad trollstad","ilalai"}},{q="Vad säger den lärde om stentavlan?",a="Den lärde har läst stentavlan tidigare, i sin ungdom, men säger att många månar har gått och att minnet har bleknat.",al={"den lärdes minne","läst stentavlan tidigare","gammal trolllegend"}}},fp="28,122,21.278.0,13.159.0,27.93.0,20.71.0,36.128.0,16.91.0,43.105.0"}
P.entries["quest:95770"] = {n="Locating the Lost City",s="Kin'weelay ber dig söka igenom Vile Reef efter en grotta med koppling till den förlorade staden. Naga som samlas där kan ha hittat något värt att undersöka.",h="Kin'weelay ber dig söka igenom Vile Reef efter en grotta med koppling till den förlorade staden.",kw={"grotta","i'lalai","kin'weelay","locating the lost city","lost city","murlocs","naga","the vile reef"},sec={{t="En grotta i revet",b="Kin'weelay minns hur han dök bland ruinerna i Vile Reef innan murlocs bosatte sig där. Han minns en grotta och ber dig utforska revet för att hitta ingången. Naga samlas nu i området, och han vill veta vad som lockade dem dit."},{t="En möjlig upptäckt",b="När du återvänder lyssnar Kin'weelay på vad du såg. Naga kommer och går från ruinen i grottan, men deras syfte är fortfarande oklart. Han undrar om den har en koppling till I'lalai och Lost City, som troll länge har betraktat som en myt. Nu vill han undersöka saken."}},faq={{q="Vem ber mig söka igenom Vile Reef?",a="Kin'weelay ber dig utforska Vile Reef och leta efter en grottingång.",al={"vem skickade mig","kin weelays begäran","vem vill detta"}},{q="Varför letar jag efter en grotta?",a="Kin'weelay minns en grotta bland ruinerna i Vile Reef och misstänker att den kan hjälpa honom att hitta Lost City.",al={"varför grotta","ledtråd till lost city","vad letar jag efter"}},{q="Varför samlas naga där?",a="Kin'weelay har hört att naga samlas i området, men orsaken är okänd.",al={"naga vid revet","varför naga","nagas anledning"}},{q="Vad hände med ruinerna i Vile Reef?",a="Murlocs bosatte sig bland ruinerna i Vile Reef efter Kin'weelays ungdom, då han brukade dyka där.",al={"ruiner i vile reef","murlocs där","vem bosatte sig vid revet"}},{q="Var finns grottingången?",a="Grottingången finns i Vile Reef. Kin'weelay ber dig utforska revet för att hitta den.",al={"grottans plats","hitta ingången","var finns grottan"}}},fp="22,146,20.228.0,20.259.1,41.76.0,30.102.0,33.88.0,37.103.0,29.88.0"}
P.entries["quest:95772"] = {n="Songblade Search",s="Songblade Search är ett dvärgärende där Dorin Songblade ber resande att leta efter hans bror Daewyn i Wetlands. Daewyn gav sig av med en arkeologisk expedition från Loch Modan för att gräva i outforskade kullar, men hans ovanliga tystnad fick brodern att frukta det värsta.",h="Songblade Search är ett dvärgärende där Dorin Songblade ber resande att leta efter hans bror Daewyn i...",kw={"daewyn songblade","dls","dorin songblade","loch modan","songblade search","wetlands","whelgar's excavation site"},ang={["faction:Alliance"]="Alliansens resande mellan Loch Modan och Menethil Harbor passerar ofta utgrävningsplatserna och hjälper strandsatta dvärgprospektörer och hantverkare.",["race:Dwarf"]="Dvärgexpeditioner och arkeologiska utgrävningar är vanliga i Khaz Modan, men att färdas från Loch Modans säkerhet till farliga Wetlands innebär ofta stora risker för de anhöriga."},sec={{t="En brors oro",b="Dorin Songblade stannade kvar i sin verkstad, överhopad av beställningar på omgjorda gördlar, medan hans bror Daewyn anslöt sig till en dvärgexpedition som gav sig av från Loch Modan. Daewyn begav sig norrut till Wetlands karga kullar, ivrig att utforska orörd mark som aldrig rörts av dvärgarnas hackor. Daewyn brukar dock skicka brev så snart han kommit fram, och hans tystnad gjorde Dorin djupt orolig."},{t="Grävplatsen i Wetlands",b="Resande som beger sig till Wetlands kan hitta Daewyn Songblade bland grävarna vid Whelgar's Excavation Site. Daewyn liknar sin bror Dorin mycket och bär ett särskilt gevär med initialerna ”DLS” inristade i träkolven, vilket visar att han nådde den avlägsna utgrävningsplatsen i träskmarkerna."}},faq={{q="Vem ger uppdraget Songblade Search?",a="Dorin Songblade ger uppdraget. Han är en hantverkare som just nu är överhopad med arbete med att göra om en hög gördlar, vilket hindrade honom från att följa med sin bror på en arkeologisk utgrävning.",al={"vem ger songblade search","uppdragsgivare för songblade search","dorin songblade"}},{q="Vem är Daewyn Songblade?",a="Daewyn Songblade är Dorin Songblades bror. Han gav sig av med en expedition från Loch Modan mot Wetlands vilda kullar, men hörde inte av sig som han brukar.",al={"vem är dorins bror","försvunnen songblade-dvärg","daewyn songblade"}},{q="Var hittar man Daewyn?",a="Daewyn finns vid Whelgar's Excavation Site i Wetlands. Du känner igen honom på den starka likheten med Dorin och hans skjutvapen, vars träkolv har ”DLS” inristat.",al={"var finns daewyn","var hittar man daewyn songblade","songblade search plats"}},{q="Varför reste Daewyn till Wetlands?",a="Daewyn anslöt sig till en dvärgexpedition från Loch Modan som sökte oupptäckta kullar i Wetlands för en arkeologisk utgrävning.",al={"varför reste daewyn till wetlands","syftet med whelgar's excavation","varför reste dvärgarna till wetlands"}},{q="Vad står initialerna på geväret för?",a="Initialerna ”DLS” på skjutvapnets kolv tillhör Daewyn Songblade och bekräftar att dvärgen vid utgrävningsplatsen verkligen är Dorins försvunne bror.",al={"vad står dls för","dls inristat på gevär","initialerna dls"}},{q="Varför oroade sig Dorin för sin bror?",a="Dorin blev orolig eftersom Daewyn vanligtvis skriver tillbaka snabbt efter att ha gett sig av på en resa. När inga brev kom efter avfärden till Wetlands fick Dorin en obehaglig föraning om att något hade gått fel.",al={"varför är dorin orolig","varför leta efter daewyn","orsaken till songblade search"}}},fp="16,183,18.330.0,23.239.1,37.155.0,24.160.0,26.152.0,38.111.0,44.147.0,40.170.0"}
P.entries["quest:95773"] = {n="Enemies in the Water",s="Nagor samlas nära gamla trollruiner utanför kusten, medan Horde redan pressas av angrepp mot sina karavaner. Du ombeds att möta hotet och visa att du håller på att bevisa ditt värde.",h="Nagor samlas nära gamla trollruiner utanför kusten, medan Horde redan pressas av angrepp mot sina karavaner.",kw={"bloodscalp","brinescale","fiender i vattnet","grom'gol","horde","nagor","ogrer","treuddar","trollruiner"},ang={["faction:Horde"]="Horde försöker skydda sina karavaner och samtidigt hålla utkik efter ett möjligt angrepp från havet."},sec={{t="Rapporter från kusten",b="Horde har fått rapporter om nagor som samlas nära gamla trollruiner under havsytan. Angrepp från Bloodscalp och ogrer anstränger redan försvaret, så ett hot från vattnet lämnar föga tid att dröja. Du ombeds att konfrontera skärmytslare från Brinescale och ta med deras treuddar tillbaka som bevis."},{t="Ett budskap vid Grom’gol",b="Vid Grom’gol ska treuddarna du tar med tillbaka sättas upp utanför portarna. Där ska de varna för att Horde inte är att leka med, och ditt arbete får beröm av befälhavaren."}},faq={{q="Varför är nagorna nära kusten?",a="Enligt rapporterna samlas nagorna kring gamla trollruiner under havsytan.",al={"nagor kusten","nagor i vattnet","varför nagor här"}},{q="Vilka är fienderna här?",a="Hotet kommer från skärmytslare från Brinescale, en grupp nagor som rapporterats nära kusten.",al={"fiender i vattnet","vilka är nagorna","brinescale"}},{q="Varför vill Horde att nagorna ska bekämpas?",a="Horde är redan hårt pressat av att försvara sina karavaner mot angrepp från Bloodscalp och ogrer, och fruktar ett överraskningsanfall från havet.",al={"varför döda nagor","horde nagproblem","angrepp från havet"}},{q="Vilket bevis efterfrågas?",a="Du ombeds att ta med treuddar från Brinescale tillbaka som bevis på att du har lyckats.",al={"treuddar som bevis","vad ska tas med tillbaka","brinescale treuddar"}},{q="Vad ska hända med treuddarna?",a="De ska sättas upp utanför portarna till Grom’gol som en varning om att Horde inte är att leka med.",al={"treuddarnas budskap","sätta upp treuddar","gromgol treuddar"}},{q="Hur bevisar detta mitt värde?",a="Befälhavaren berömmer ditt arbete och säger att du snabbt håller på att bevisa ditt värde för Horde.",al={"bevisa sitt värde","hordes gillande","varför är jag här"}}},fp="20,188,22.299.0,23.197.1,32.74.0,25.86.0,44.135.0,24.73.0,33.104.0,29.89.0"}
P.entries["quest:95774"] = {n="Her Name Is Olgra",s="När Mankrik får veta att Olgra har dött i strid beslutar han sig för att hedra henne med ett bestående minnesmärke. Han ber dig hämta hennes försvunna bensmycken från de närbelägna Razormane-rövarna, så att de kan vila intill hennes monument.",h="När Mankrik får veta att Olgra har dött i strid beslutar han sig för att hedra henne med ett bestående...",kw={"smycken","mankrik","minnesmärke","olgra","polerat ben","quilboar","razormane-rövare"},sec={{t="Att hedra de fallna",b="En läkare lyckades rädda Mankrik, men Olgra dog av sina skador på slagfältet. Den sörjande krigaren vill att hennes namn och offer aldrig ska glömmas och förbereder ett bestående minnesmärke till hennes ära."},{t="Förlorade minnessaker",b="Olgra bar älskade smycken av polerat ben, men de saknades på hennes viloplats. Mankrik vill återta dessa personliga skatter från de närbelägna Razormane-rövarna, så att de kan vila intill monumentet han reser åt henne."}},faq={{q="Vem är Olgra?",a="Olgra föll i strid mot quilboar. Läkaren som hjälpte Mankrik lyckades rädda honom, men Olgra gick inte att rädda, och Mankrik tänker hedra hennes minne för alltid.",al={"vem är olgra","mankriks fru","vem dog"}},{q="Vad är Olgras smycken?",a="Hennes smycken är älskade hantverkade prydnader av polerat ben som hon bar innan hon dödades.",al={"vad är olgras smycken","olgras juveler","vad är smyckena gjorda av"}},{q="Varför jagas Razormane-rövarna?",a="Smyckena togs från Olgras fallna kropp, så Mankrik skickar dig mot Razormane-rövarna nära platsen där hon dog för att återta dem.",al={"varför döda razormane-rövare","vem stal olgras smycken","var finns smyckena"}},{q="Vad ska Mankrik göra med de återfunna smyckena?",a="Mankrik tänker placera de återfunna bensmyckena intill monumentet han bygger åt Olgra, så att hennes minne aldrig bleknar.",al={"mankriks minnesmärke","vad ska mankrik göra med smyckena","varför vill mankrik ha smyckena"}}},fp="17,152,19.165.0,14.226.0,13.135.0,28.111.0,43.127.0,51.122.0"}
P.entries["quest:95775"] = {n="The Drowned City",s="En lärd ber dig undersöka ruiner som vaktas av naga och göra avtryck av deras stentavlor. Staden kan vara I’lalai, rik på förlorad historia.",h="En lärd ber dig undersöka ruiner som vaktas av naga och göra avtryck av deras stentavlor.",kw={"träkol","dränkta staden","skinn","i’lalai","förlorad historia","naga","avtryck","ruiner","stentavlor"},sec={{t="Genom grottan",b="Den lärde är för gammal för att gå in i ruinerna, så du ombeds gå i hens ställe. Bortom grottan som vaktas av naga misstänker den lärde att ruinerna kan vara I’lalai. Den förlorade staden kan rymma en mängd historisk kunskap. Du ska göra avtryck av alla stentavlor du hittar och ta med dem tillbaka."}},faq={{q="Vad är The Drowned City?",a="Ruinerna kan vara den förlorade staden I’lalai, enligt den lärde som skickade dig.",al={"dränkta staden","vilken stad är det här","i’lalais ruiner"}},{q="Vem vill att jag utforskar ruinerna?",a="En lärd ber dig utforska ruinerna eftersom hen är för gammal för att gå dit själv.",al={"vem skickade mig","vem vill ha avtryck","den lärdes uppdrag"}},{q="Varför skickas jag dit?",a="Den lärde hoppas att ruinerna rymmer en stor mängd förlorad historisk kunskap.",al={"varför utforska","varför stentavlor","förlorad historia"}},{q="Vad ska jag ta med tillbaka?",a="Gör avtryck av alla stentavlor du hittar med hjälp av skinn och träkol. Återvänd sedan till den lärde.",al={"vad ska tas med tillbaka","avtryck av stentavlor","uppdrag att göra avtryck"}},{q="Var ligger ruinerna?",a="Ruinerna ligger på andra sidan grottan som vaktas av naga.",al={"var ligger den dränkta staden","naga-grottan","ruinernas läge"}}},fp="16,132,17.294.0,25.83.0,34.82.0,26.77.0,33.95.0,20.62.0"}
P.entries["quest:95776"] = {n="The Only Good Brinescale...",s="Naga i vattnen nära kusten väcker oro för ett större hot. Du ombeds hitta deras ledare i Drowned City.",h="Naga i vattnen nära kusten väcker oro för ett större hot.",kw={"brinescale","kust","drowned city","infiltration","kin'weelay","naga","var'taka"},sec={{t="Ett hot till havs",b="Naga nära kusten har dödats, men deras antal tyder på en större fara. Kin'weelay tror att Brinescale naga tar sig in i ruinerna av Drowned City. Deras närvaro där tyder på att de söker efter något som kan utsätta kusten för fara. Du ombeds döda deras ledare, Var'Taka."},{t="Återkomsten",b="När du återvänder tolkar din uppdragsgivare din ankomst som ett tecken på att Var'Taka är död. När nagaledaren är borta finns det en oro mindre för kusten."}},faq={{q="Varför är Brinescale naga i Drowned City?",a="Kin'weelay tror att Brinescale naga letar efter något i Drowned City, men det är okänt vad de söker.",al={"varför naga där","brinescale naga syfte","vad letar naga efter"}},{q="Vem är Kin'weelay?",a="Kin'weelay tror att Brinescale naga infiltrerar Drowned City.",al={"kin weelay","vem är kin'weelay","kin"}},{q="Vem är Var'Taka?",a="Var'Taka är ledare för Brinescale naga i Drowned City.",al={"var taka","nagaledare","brinescale-ledare"}},{q="Vad ombeds jag göra?",a="Du ombeds döda Var'Taka i Drowned City.",al={"vad ska jag göra","vad är uppgiften","vem ska dödas"}}},fp="27,126,17.299.0,10.143.1,48.121.0,18.89.0,16.66.0,22.51.0"}
P.entries["quest:95789"] = {n="Shady Saltseers",s="En av Baron Revilgaz kontakter skickar dig till Drowned City efter Saltseers, pirater som samlar på magiska artefakter. Deras stöldgods har väckt uppmärksamhet nu när den sjunkna trollruinen har rest sig igen.",h="En av Baron Revilgaz kontakter skickar dig till Drowned City efter Saltseers, pirater som samlar på magiska...",kw={"baron revilgaz","drowned city","magiska artefakter","pirater","saltseers","shady saltseers","trollruin","voodoo infused artifacts"},sec={{t="En barons begäran",b="En av Baron Revilgaz kontakter ber dig att återta artefakter från Saltseers i Drowned City. Piraterna samlar på magiska föremål, och sedan ruinen återvänt finns där gods att lägga beslag på. Det är deras stulna artefakter som Revilgaz kontakt är ute efter."}},faq={{q="Vem vill ha Saltseers artefakter?",a="En av Baron Revilgaz kontakter ber dig att återta artefakterna.",al={"vem skickade mig","baron revilgaz kontakt","vem vill ha artefakter"}},{q="Vilka är Saltseers?",a="Saltseers är pirater som samlar på magiska artefakter.",al={"saltseer pirater","vilka är saltseers","saltseers"}},{q="Var finns Saltseers?",a="De finns i Drowned City, en sjunken trollruin som har rest sig igen.",al={"var ligger drowned city","var finns saltseers","drowned city"}},{q="Vilka artefakter letar jag efter?",a="Du ombeds att återta Voodoo Infused Artifacts som Saltseers har stulit.",al={"vad ska samlas in","voodooartefakter","stöldgods"}}},fp="15,205,19.255.0,37.62.0,22.56.0,24.71.0,32.74.0"}
P.entries["quest:95791"] = {n="The Saltseer Captain",s="En rivaliserande jägare vill få bort Captain Dreadrise och hans Saltseer Coroners från Drowned City. Deras besättning fortsätter att samla in de magiska artefakter han söker.",h="En rivaliserande jägare vill få bort Captain Dreadrise och hans Saltseer Coroners från Drowned City.",kw={"captain dreadrise","drowned city","magiska artefakter","pirater","saltseer","saltseer coroners"},sec={{t="En rival i staden",b="En rivaliserande jägare söker din hjälp i Drowned City, där Saltseer-piraterna har blivit en nagel i ögat på honom. Captain Dreadrise och hans Saltseer Coroners samlar in de magiska artefakter han vill ha. Han ber dig att röja kaptenen och tre ur hans besättning ur vägen."}},faq={{q="Vem är Captain Dreadrise?",a="Captain Dreadrise leder Saltseer-piraterna i Drowned City.",al={"dreadrise","saltseer-kapten","kaptenen"}},{q="Vilka är Saltseer Coroners?",a="Saltseer Coroners är besättningsmedlemmar som Captain Dreadrise samarbetar med för att samla in magiska artefakter.",al={"saltseer-besättning","coroners","dreadrises besättning"}},{q="Varför vill uppdragsgivaren få bort Dreadrise?",a="Captain Dreadrise och hans besättning fortsätter att samla in magiska artefakter som uppdragsgivaren har sökt efter, och han är trött på konkurrensen.",al={"varför döda dreadrise","varför röja kaptenen ur vägen","dreadrises rival"}},{q="Var finns Captain Dreadrise och Saltseer-piraterna?",a="Captain Dreadrise och Saltseer-piraterna finns i Drowned City.",al={"var finns dreadrise","var finns saltseer","pirater i drowned city"}},{q="Vad ber uppdragsgivaren mig att göra?",a="Uppdragsgivaren ber dig att dräpa Captain Dreadrise och tre Saltseer Coroners i Drowned City.",al={"vad ska jag göra","dreadrise-uppdrag","saltseer-uppgift"}}},fp="20,154,19.268.0,25.65.0,30.99.0,39.127.0,46.67.0,33.93.0"}
P.entries["quest:95795"] = {n="Fallen in the Fen",s="Fallen in the Fen är en sorgsen färd som börjar när en död dvärg hittas vid en utgrävning. Beskedet till hans bror Dorin Songblade i Lakeshire ger en förkrossad hantverkare ro, efter att han smitt gåvor åt sin bortgångne bror.",h="Fallen in the Fen är en sorgsen färd som börjar när en död dvärg hittas vid en utgrävning.",kw={"smed","dorin","dorin songblade","dvärg","utgrävning","utgrävningsplatser","fallen in the fen","lakeshire","songblade"},ang={["faction:Alliance"]="Att ge en hantverkare i Redridge ro ger tröst åt en sörjande invånare under en orolig tid för kungariket.",["profession:Blacksmithing"]="Dorin lade all sin skicklighet i vapnen han tänkt ge sin bror som överraskning. Nu påminner utrustningen honom bara om broderns för tidiga död.",["race:Dwarf"]="Dvärgar vet hur bitter sorgen är när en bror går förlorad i gamla utgrävningar och otämjd vildmark, särskilt när det smidda stålet överlever handen som skulle hålla det."},sec={{t="Tragedi vid utgrävningen",b="En stilla tragedi utspelar sig vid utgrävningsplatserna, där en äventyrslysten dvärgs livlösa kropp hittas. En äventyrare täcker kvarlevorna med dvärgens egen mantel och tar sedan det dystra beskedet tillbaka till Lakeshire för att hitta hans anhöriga."},{t="En brors sorg",b="I Lakeshire bryter dvärgsmeden Dorin Songblade ihop när han får veta vad som hänt hans bror. I flera veckor hade Dorin arbetat vid sin ässja och smitt en överraskningsgåva åt sin bror, men utrustningen blev inte klar i tid för expeditionen. Fylld av ånger över att inte ha följt med klarar Dorin varken av att smida om eller sälja det han tillverkat med egna händer. I stället ger han de färdiga föremålen till den som gav honom visshet."}},faq={{q="Vad är Fallen in the Fen?",a="Fallen in the Fen är ett sorgset uppdrag som börjar när kvarlevorna efter en fallen dvärg upptäcks vid en utgrävning. Du täcker kroppen med hans mantel och beger dig till Lakeshire för att personligen berätta för dvärgens sörjande bror, Dorin Songblade, vad som hänt.",al={"vad är fallen in the fen","uppdraget fallen in the fen"}},{q="Vem är Dorin Songblade?",a="Dorin Songblade är en dvärgisk smed som bor i Lakeshire. Han hade smitt utrustning som en överraskningsgåva åt sin bror innan han fick veta om den tragiska döden vid utgrävningsplatserna.",al={"vem är dorin songblade","dorin i lakeshire","dorin songblades roll"}},{q="Vem är den fallne dvärg som hittades vid utgrävningen?",a="Den fallne dvärg som hittades vid utgrävningsplatserna var Dorin Songblades bror. Han hade nyligen passerat genom Lakeshire för att samla förnödenheter inför sin expedition, innan han dog ute i vildmarken.",al={"vem dog i kärret","död dvärg vid utgrävning","vems kropp finns vid utgrävningen"}},{q="Var hittar man Dorin Songblade?",a="Dorin Songblade finns i Lakeshire, den främsta bosättningen i Redridge Mountains, där han arbetar vid smedjan.",al={"var finns dorin songblade","dorin songblades plats"}},{q="Vad smidde Dorin åt sin bror?",a="Dorin arbetade med att smida utrustning som en överraskningsgåva åt sin bror. Tyvärr blev arbetet inte klart innan brodern gav sig av på sin expedition, och Dorin är förkrossad över utrustningen som han varken kan behålla eller sälja.",al={"vad smidde dorin","dorins överraskningsgåva"}},{q="Varför ger Dorin bort föremålen han tillverkat?",a="Överväldigad av sorg och ånger över att inte ha följt med sin bror vill Dorin varken smida om eller sälja vapnen han arbetat så hårt med. Han skänker bort de färdiga föremålen som tack till resenären som kom med beskedet om hans bror.",al={"varför gav dorin bort utrustningen","varför ger dorin dig utrustning"}}},fp="17,175,18.158.0,17.401.1,26.175.0,23.161.0,48.153.0,35.114.0,39.182.0,46.176.0"}
P.entries["quest:95803"] = {n="A Token of Good Faith",s="Danitha skickar dig för att föra Rudolph Gelhardts huvud till Sylvanas Windrunner i Undercity. Överlämnandet ska visa Forsaken att ditt folk hängivet verkar för deras välgång.",h="Danitha skickar dig för att föra Rudolph Gelhardts huvud till Sylvanas Windrunner i Undercity.",kw={"a token of good faith","danitha","dark lady","forsaken","light","rudolph gelhardt","sylvanas windrunner","undercity"},sec={{t="Ett bevis på lojalitet",b="Danitha säger att Sylvanas misstror ditt folk och öppet talar nedsättande om dem. Hon ber dig överlämna Rudolph Gelhardts huvud som bevis på att ni håller ordning i era egna led och står vid Forsakens sida."},{t="Dark Ladys svar",b="Sylvanas tvivlar på att Danithas orden kan hindra fler av sina medlemmar från att vända Light mot sitt eget folk. Hon varnar för att hon kanske inte längre kommer att tolerera orden om den slutar tjäna Forsakens intressen. Orden kommer att bevakas."}},faq={{q="Vem ber mig att överlämna Rudolph Gelhardts huvud till Sylvanas?",a="Danitha ber dig att föra Rudolph Gelhardts huvud till Sylvanas Windrunner i Undercity.",al={"vem skickade mig till sylvanas","danitha överlämna huvud","huvud till dark lady"}},{q="Varför vill Danitha att jag överlämnar huvudet till Sylvanas?",a="Danitha vill att överlämnandet ska visa Sylvanas att ditt folk håller ordning i sina egna led och värnar om Forsakens välstånd.",al={"varför överlämna rudolphs huvud","vad är överlämnandet till för","bevisa lojalitet"}},{q="Varför misstror Sylvanas Danithas folk?",a="Danitha säger att Sylvanas hyser stor misstro mot ditt folk och nästan öppet talar nedsättande om dem.",al={"varför sylvanas misstror oss","dark ladys misstro","varför talar hon nedsättande om oss"}},{q="Vart ska jag föra Rudolph Gelhardts huvud?",a="Du blir ombedd att föra Rudolph Gelhardts huvud till Sylvanas Windrunner i Undercity.",al={"var är sylvanas","plats för överlämnande av huvudet","ta det till undercity"}}},fp="21,186,17.189.0,24.238.1,59.92.0,55.135.0,46.86.0,42.89.0"}
P.entries["quest:95805"] = {n="Grace of An'she and Mu'sha",s="Grace of An'she and Mu'sha är en helig taurenpilgrimsfärd på Red Cloud Mesa, där solen och månen hedras som Jordmoderns himmelska ögon. Genom att bära skör, glödande rökelse till en högt belägen helgedom i de sydöstra kullarna visar resenärerna vördnad för himlaljusen som skänker värme, liv och vägledning åt slätterna.",h="Grace of An'she and Mu'sha är en helig taurenpilgrimsfärd på Red Cloud Mesa, där solen och månen hedras som...",kw={"an'she","jordmodern","måne","mu'sha","mulgore","red cloud mesa","helgedom","glödande rökelse","sol","tauren"},ang={["class:Druid"]="Taurendruider ser solens och månens eviga dans som balansens ursprungliga gestalt, som vägleder deras förståelse av naturens kosmiska rytmer.",["class:Shaman"]="Schamaner talar direkt med världens andar av jord, eld, vatten och luft, men visar lika stor vördnad för de himmelska tvillingarna vars ljus upprätthåller allt levande.",["faction:Horde"]="De heliga riterna på mesan visar den djupa naturvördnad som nomadiska tauren för med sig till sina allierade i Horde.",["race:Tauren"]="Vördnaden för An'she och Mu'sha är central för taurenfolkets andliga identitet och påminner unga krigare om att livet kräver att de hedrar de himmelska tvillingljusen lika troget som Jordmodern själv."},sec={{t="Jordmoderns ögon",b="I taurenmyten kallas solen och månen An'she och Mu'sha, och vördas som Jordmoderns tvillingögon. Medan elementandar bor direkt i Azeroths stenar, vindar och vatten vakar dessa himmelska tvillingar över världen från himlens höjder. Deras ständiga färd över skyn markerar dygnets eviga rytm och skänker värme, vägledning och hopp till alla levande varelser. Att hedra tvillingarna är en viktig andlig plikt och lär att balans kräver vördnad inte bara för marken under ens fötter, utan också för ljuset som strålar ner från himlen."},{t="Ett offer på höjderna",b="För att hedra de himmelska tvillingarna måste en pilgrim bära glödande rökelse till kullarna sydost om mesan, med utsikt över den och strax söder om de taggiga quilboar-markerna. Färden kräver uppmärksamhet och snabbhet: de väldoftande glöden måste överlämnas innan de brunnit ut till kall aska, och resenärerna måste se till att hålla dem borta från vatten längs leden. När pilgrimen når den högt belägna helgedomen kastar hen glöden i den heliga elden och låter den aromatiska röken bära vördnaden upp mot solen och månen."}},faq={{q="Vilka är An'she och Mu'sha?",a="I taurenmytologin är An'she och Mu'sha solen och månen, och de vördas som Jordmoderns tvillingögon. Till skillnad från jordens, luftens, eldens och vattnets andar bor de inte direkt i Azeroths jord. I stället lyser de upp världen från himlavalvet, där An'she skänker värme och liv medan Mu'sha ger vägledning och tröst om natten.",al={"vilka är an'she och mu'sha","an'she och mu'sha i mytologin","taurens sol- och mångudar"}},{q="Varför offrar tauren till solen och månen?",a="Taurenfilosofin lär att balans är nödvändig för all existens. Jordandar råder över det närmaste landskapet, medan An'shes och Mu'shas ljus ger livsviktig energi, syn och hopp åt alla levande varelser. Att offra glödande rökelse på höga platser är en handling av ömsesidig vördnad och ett erkännande av att dödligt liv inte kan frodas utan de båda himlakropparnas ständiga välvilja.",al={"varför vörda solen och månen","tauren och himmelsk dyrkan","varför hedra an'she och mu'sha"}},{q="Var ligger An'shes och Mu'shas helgedom?",a="An'shes och Mu'shas helgedom ligger i de höga kullarna sydost om mesan. Den blickar ut över de vidsträckta slätterna nedanför och ligger strax söder om de taggiga quilboarområdena. Det höga läget ger fri sikt över den öppna himlen och gör platsen idealisk för att sända rök upp mot himlarna.",al={"var ligger an'shes helgedom","helgedomens plats i mulgore","hur hittar man rökelsehelgedomen"}},{q="Vad betyder den glödande rökelsen?",a="Den glödande rökelsen fungerar som en fysisk kanal för bön och vördnad. När dess väldoftande glöd brinner för röken resenärens hängivenhet direkt upp mot solen och månen. När glöden kastas i helgedomens eld fullbordas ritualen, och pilgrimen får en fridfull känsla av andlig tillfredsställelse.",al={"vad gör rökelsen","innebörden av rökelseoffret","varför bränna glödande rökelse"}},{q="Varför måste rökelsen levereras snabbt och hållas torr?",a="Ritualen kräver vaksamhet, snabbhet och omsorg av pilgrimen. Rökelsen måste fortfarande glöda när den kastas i den heliga elden vid helgedomen, så färden måste vara avklarad innan glöden slocknar och blir kall aska. Dessutom släcks glöden omedelbart i vatten, vilket förstör offret innan det når höjderna.",al={"varför har rökelsen en tidsgräns","håll den torr","rökelsen brinner upp"}},{q="Hotar quilboar pilgrimsfärden till helgedomen?",a="Quilboar-stammar håller till i välförsvarade törnlyor i kullarna strax norr om helgedomen. Själva helgedomen ligger på en stillsam utsiktsplats söder om deras marker, men resenärer måste se upp så att de inte råkar hamna i quilboarens snår. Fientliga angrepp kan lätt försena eller störa den ömtåliga färden.",al={"quilboar nära helgedomen","är quilboar ett hot mot pilgrimer","quilboar söder om mesan"}},{q="Hur skiljer sig Mu'sha från andra kulturers syn på månen?",a="I taurenmyten är månen Mu'sha, Jordmoderns kärleksfulla vänstra öga som blickar ner på de dödligas liv. Andra raser på Azeroth, framför allt nattalverna, vördar samma lysande vita måne som gudinnan Elune, men i tauren-traditionen är hon oupplösligt förenad med sin soltvilling, An'she.",al={"är mu'sha elune","taurenmånens skillnad från elune","mu'sha och nattalverna"}}},fp="26,245,27.439.0,26.365.0,26.278.0,53.262.0,49.238.0,51.250.0,55.237.0,54.242.0,61.217.0"}
P.entries["quest:95809"] = {n="Heartwoven",s="Heartwoven är ett Alliance-uppdrag i Wetlands med ett enkelt budskap om överlevnad och tillgivenhet. Efter att ha röjt en flyktväg åt en strandsatt samlare i träskmarkerna bär äventyrare ett handflätat hjärta av vass till Caitlin Grassman i Menethil Harbor.",h="Heartwoven är ett Alliance-uppdrag i Wetlands med ett enkelt budskap om överlevnad och tillgivenhet.",kw={"caitlin grassman","grassman","heartwoven","menethil harbor","vasstråhjärta","vass","wetlands"},ang={["faction:Alliance"]="Menethil Harbor är en viktig Alliance-hamn i Wetlands, där vanliga invånare förlitar sig på resenärer för att hålla de farliga lederna genom träskmarkerna säkra.",["profession:Cooking"]="När Caitlin får vasstråhjärtat och hör att hennes partner överlevt börjar hon genast laga en varm och mättande måltid för att välkomna honom hem."},sec={{t="En signal från träskmarkerna",b="Ute i Wetlands förrädiska träskmarker innebär både liv och arbete ständig fara. Ardin Grassman gav sig av för att se de märkliga gräsen vid utgrävningsplatserna, men blev strandsatt bland träskets faror tills en förbipasserande resenär röjde en väg genom vildmarken. Utmattad men beslutsam stannar han för att hämta andan och säkra sin skörd innan han beger sig tillbaka mot hamnens trygghet."},{t="Minnen från Menethil",b="Innan samlaren beger sig hem tar han kärrvass ur packningen och flätar den till ett hjärta. Han anförtror äventyraren detta tecken, som ska bäras till Caitlin Grassman i Menethil Harbor. I den livliga kustbosättningen väntar Caitlin djupt orolig. När hon får höra att han överlevt och snart kommer tillbaka för en varm måltid håller hon det flätade vasstråhjärtat mot bröstet i lättnad."}},faq={{q="Vad är uppdraget Heartwoven?",a="Heartwoven är ett Alliance-uppdrag i Wetlands. En äventyrare hjälper Ardin Grassman, som blivit strandsatt vid utgrävningsplatserna ute i träskmarkerna. Han tillverkar ett flätat tecken av vass, ett budskap om överlevnad och kärlek som ska lämnas till Caitlin Grassman i Menethil Harbor.",al={"uppdraget heartwoven","vad är heartwoven","heartwoven i wetlands"}},{q="Vem är Caitlin Grassman?",a="Caitlin Grassman är en Alliance-invånare som väntar oroligt i Menethil Harbor. Hon fruktar för sin make Ardins liv. Han gav sig av till utgrävningsplatserna bland Wetlands faror, och hon känner en djup lättnad när du berättar att han överlevt.",al={"vem är caitlin grassman","caitlin menethil harbor","caitlin grassman"}},{q="Vad är det flätade vasstråhjärtat?",a="Det flätade vasstråhjärtat är ett handgjort tecken som den strandsatte samlaren tillverkar av kärrvassen i sin packning. Han flätar det snabbt för att visa att han lever och snart är på väg hem.",al={"vad är vasstråhjärtat","hjärta flätat av vass","flätat vasstråhjärta"}},{q="Var lämnar du in Heartwoven?",a="Uppdraget avslutas hos Caitlin Grassman, som väntar i Alliance-hamnstaden Menethil Harbor på Wetlands västkust.",al={"var lämnar man in heartwoven","plats för inlämning av heartwoven","var finns caitlin grassman"}},{q="Vem ger dig uppdraget Heartwoven?",a="Uppdraget ges av Ardin Grassman, Caitlins make, som överlevde farorna vid utgrävningsplatserna ute i Wetlands. När en äventyrare har röjt en säker väg åt honom vilar han, samlar ihop sina säckar och skickar äventyraren i förväg med ett handgjort tecken till Caitlin.",al={"vem ger heartwoven","vem flätar hjärtat","den överlevande i heartwoven"}},{q="Vad hände med den strandsatta samlaren?",a="Ardin gav sig till utgrävningsplatserna för att se märkliga, höga gräs och blev instängd när uppretade vilda djur, framför allt spindlar, övermannade utgrävningsteamet. Tack vare att en äventyrare röjde en väg genom hoten i omgivningen överlevde han, kunde samla ihop sina säckar och bege sig tryggt tillbaka till Menethil Harbor.",al={"vad hände med samlaren","lever han","överlevande i heartwoven"}}},fp="10,154,25.296.0,18.318.0,29.211.0,24.201.0,29.156.0,32.125.0,35.182.0,39.273.0"}
P.entries["quest:95810"] = {n="Lost Relic Carry",s="Lost Relic Carry handlar om att återfinna en trasig del av en uråldrig stenmekanisk automat och lämna den till Prospector Whelgar i Wetlands. Relikens okända kompositmaterial vittnar om Titanernas sofistikerade ingenjörskonst och väcker stor vördnad hos dvärgiska forskare.",h="Lost Relic Carry handlar om att återfinna en trasig del av en uråldrig stenmekanisk automat och lämna den...",kw={"automat","utgrävningsplats","explorers league","lost relic carry","prospector whelgar","stenmekanisk","titan relic","wetlands"},ang={["profession:Engineering"]="Kompositmaterialet och den intrikata utformningen hos den stenmekaniska automaten vittnar om avancerade mekaniska principer långt bortom vanlig dödlig ingenjörskonst.",["race:Dwarf"]="Dvärgäventyrarna i Explorers' League är besatta av att gräva fram forntida reliker från sina skapare, vilket gör detta automatfragment till ett eftertraktat fynd för dvärgarnas kulturarv."},sec={{t="Ett fragment av uråldrigt hantverk",b="Djupt inne på forntida marker kan äventyrare hitta en trasig komponent från en stenmekanisk automat. Den är långt ifrån vanligt ras, och dess ovanliga kompositmaterial avslöjar hantverket bakom en avancerad, uråldrig mekanism med koppling till Titanerna."},{t="Till utgrävningsplatsen",b="Prospector Whelgar, som håller till vid utgrävningsplatsen i Wetlands, studerar lämningar från forntiden. Genom att föra reliken i säkerhet och lämna den till honom får dvärgiska lärda värdefulla fysiska bevis medan de undersöker sitt forntida arv."}},faq={{q="Vad är Titan Relic?",a="Reliken är en trasig del av en uråldrig stenmekanisk automat. Den består inte av vanligt stenras, utan av ett okänt kompositmaterial som tydligt ingick i en komplicerad mekanisk anordning.",al={"vad är reliken","vad är föremålet","del av stenmekanism"}},{q="Vem är Prospector Whelgar?",a="Prospector Whelgar är en dvärgisk forskare som ansvarar för utgrävningsplatsen i Wetlands. Han studerar forntida jordiska lämningar och reliker som grävs fram på utgrävningsplatser runt om i regionen.",al={"vem är whelgar","whelgars bakgrund","ansvarig för utgrävningen"}},{q="Var ska reliken lämnas?",a="Reliken ska lämnas till Prospector Whelgar vid hans utgrävningsplats i Wetlands, där dvärgiska utgrävare undersöker forntida ruiner.",al={"var ska jag lämna den","var lämnar jag in den","whelgars plats"}},{q="Vad skapade den stenmekaniska automaten?",a="Automatfragmentet identifieras som en Titan-relik. I dvärgisk folktro har forntida mekaniska konstruktioner och stenautomater koppling till de gåtfulla Titanerna, som formade världen.",al={"vem skapade stenautomaten","automatens ursprung","kopplingen till titanerna"}},{q="Varför behandlar Prospector Whelgar reliken med vördnad?",a="Det är ytterst farligt att ge sig ner i djupen där dessa automater finns. Whelgar påpekar att den som överlever färden ner och återvänder med en sådan del i behåll förtjänar genuin respekt.",al={"varför är whelgar imponerad","farlig färd ner i djupen"}},{q="Vad är ovanligt med automatens material?",a="Materialet är en unik komposit med en främmande struktur, olik vanlig sten eller smitt metall. Det visar hur sofistikerat och gåtfullt hantverket bakom Titanernas forntida konstruktioner var.",al={"vad är materialet","främmande komposit"}}},fp="16,141,27.158.0,26.198.0,24.140.0,26.167.0,42.130.0,37.159.0,59.164.0,47.153.0"}
P.entries["quest:95883"] = {n="The Tortured Soul",s="The Tortured Soul är ett uppdrag kring ett hastigt hopsatt ritualaltare vid Beren's Peril i Silverpine Forest. För att fullfölja de mörka riterna som beskrivs i en övergiven anteckning måste äventyrare hämta en själ präglad av lidande från de farliga klipporna i närheten.",h="The Tortured Soul är ett uppdrag kring ett hastigt hopsatt ritualaltare vid Beren's Peril i Silverpine Forest.",kw={"beren's peril","ohelig energi","blodoﬀer","offersten","ritual","silverpine forest","the tortured soul"},ang={["class:Priest"]="Ritualen använder ohelig energi som slitits ur lidande andar och står i skarp kontrast till den Heliga Ljusets helande principer.",["class:Warlock"]="Att kanalisera plågade själar och utföra mörka riter vid uråldriga offerstenar speglar den dystra, manipulativa naturen hos demonisk magi och skuggmagi.",["race:Undead"]="Silverpine Forest tillhör de Förfallna, där rester av mörk magi och kvardröjande lidande ständigt hotar Lordaerons gränser."},sec={{t="En hastig rit",b="Vid Beren's Peril i Silverpine Forest står ett altare med resterna av en hastigt hopsatt mörk ritual. En klottrad anteckning bland den vårdslöst utspridda röran visar att de flesta ingredienser redan har samlats in. Bara ett blodoﬀer och en Tortured Soul återstår för att slutföra ritualen."},{t="Oheliga energier frigörs",b="Invånarna i klipporna vid Beren's Peril uthärdar svår smärta och är därför lämpliga mål för att utvinna den plågade essens som ritualen kräver. När den utvunna själen läggs fram vid den olycksbådande offerstenen frigörs en våg av ohelig magisk energi, och ritualen förs närmare sin fullbordan."}},faq={{q="Vad är The Tortured Soul?",a="The Tortured Soul är ett uppdrag vid Beren's Peril i Silverpine Forest. Det går ut på att undersöka en ofullbordad mörk ritual vid en offersten och leta upp en plågad varelses själ i närheten för att komplettera ritualens ingredienser.",al={"vad är uppdraget the tortured soul","tortured soul silverpine","uppdraget beren's peril"}},{q="Var äger ritualen rum?",a="Ritualaltaret och dess olycksbådande offersten ligger vid Beren's Peril, en bergig och farlig enklav i Silverpine Forest.",al={"var är ritualen","var ligger beren's peril","offerstenens plats"}},{q="Vilka beståndsdelar krävs för ritualen?",a="Enligt en papperslapp som lämnats vid altaret har nästan allt material hastigt samlats in. Två viktiga beståndsdelar saknas: ett blodoﬀer och en Tortured Soul.",al={"vad behövs för ritualen","ritualens beståndsdelar vid beren's peril"}},{q="Var hittar du Tortured Soul?",a="Uppdragstexten säger att varelserna i närheten av Beren's Peril verkar tillräckligt plågade för att lämna ifrån sig den essens som behövs för att ge offerstenen kraft.",al={"var hittar man tortured soul","vem har själen"}},{q="Vad händer när Tortured Soul förs till altaret?",a="När den plågade själen förs till offerstenen avger den ohelig energi, vilket för den mörka ceremonin ett steg närmare fullbordan.",al={"vad händer när man för fram själen","lämna in tortured soul"}},{q="Vem skapade ritualen vid Beren's Peril?",a="Det framgår inte vem som skapade ritualen, men anteckningarna och det hastigt insamlade materialet tyder på att någon flydde eller satte ihop altaret i stor hast bland Beren's Perils fientliga invånare.",al={"vem skapade ritualen","vem skrev anteckningen"}}},fp="17,163,12.253.0,23.250.1,26.158.0,34.114.0,44.129.0,36.120.0,60.116.0,40.147.0"}
